P.entries["item:99-year-old-port"] = {n="99年波尔多陈酿",s="99年波尔多陈酿是一瓶极为罕见的陈年佳酿，从藏宝海湾运来，作为送给加兹鲁维的私人礼物。棘齿城码头发生货运事故后，一个名叫疯狂的马格利什的疯子趁机抢走了它，逃进了哀嚎洞穴外蜿蜒曲折的隧道。",h="99年波尔多陈酿是一瓶极为罕见的陈年佳酿，从藏宝海湾运来，作为送给加兹鲁维的私人礼物。棘齿城码头发生货运事故后，一个名叫疯狂的马格利什的疯子趁机抢走了它，逃进了哀嚎洞穴外蜿蜒曲折的隧道。",kw={"99年波尔多陈酿","比戈弗兹","加兹鲁维","疯狂的马格利什","陈酿","棘齿城","里维加兹","哀嚎洞穴"},ang={["class:Rogue"]="疯狂的马格利什靠着蹩脚的潜行本领，在哀嚎洞穴外的黑暗中藏身，但技艺娴熟的潜行者很容易就能把他从阴影里逼出来。"},sec={{t="贵重货物倾覆",b="横渡无尽之海运送贵重货物总有风险，但在棘齿城一个寻常早晨的卸货作业中，起重机操作员比戈弗兹却让事情变得糟糕得多。为了卸完从藏宝海湾运来的大批货物，这个地精让起重机超载，结果堆积如山的货箱轰然坠落，砸在码头上。混乱中，镇上那个名叫疯狂的马格利什、惯爱惹事的怪人抢走了一瓶年份非同寻常的99年波尔多陈酿，朝着哀嚎洞穴的方向逃进了山丘。"},{t="外交佳酿",b="被盗的陈酿并非寻常酒水；这是Blackwater Raiders的大财主里维加兹送给棘齿城首席工程师兼统治者加兹鲁维的一份贵重外交礼物。丢失如此珍贵的货物，不仅危及比戈弗兹的生计，也让他与码头主管的关系更加紧张。追踪的线索通向洞穴外围昏暗的岩洞，那个行踪不定的窃贼带着尚未开封的珍品潜藏在阴影中，迫使码头工人招募外来的佣兵，赶在加兹鲁维发现这场纰漏之前将酒找回。"}},faq={{q="99年波尔多陈酿原本是送给谁的？",a="这瓶酒是藏宝海湾的主人、大财主里维加兹送给棘齿城老板加兹鲁维的一份贵重私人礼物。",al={"陈酿是送给谁的","谁会收到陈酿","加兹鲁维的礼物"}},{q="疯狂的马格利什是怎么拿到这瓶陈酿的？",a="起重机操作员比戈弗兹试图卸下超出起重机承载能力的货物，结果货箱散落在棘齿城码头上。疯狂的马格利什趁乱抢走了那瓶陈年佳酿，逃之夭夭。",al={"陈酿如何被盗","谁偷了陈酿","码头事故"}},{q="疯狂的马格利什把酒带到了哪里？",a="马格利什穿过贫瘠之地逃向内陆，藏进了通往哀嚎洞穴的岩石前厅和外围隧道。",al={"疯狂的马格利什在哪里","陈酿藏在哪里","陈酿位置"}},{q="比戈弗兹为什么不亲自取回陈酿？",a="比戈弗兹一路追赶小偷，来到了哀嚎洞穴入口，但他惧怕盘踞在洞中的野兽和堕落的德鲁伊，拒绝进去。",al={"比戈弗兹为何不追","胆小的起重机操作员"}}},fx={["5b0242c9"]={q="99年波尔多陈酿是什么？",a="这瓶波尔多陈酿非常罕见，且年份久远，它是从藏宝海湾千里迢迢运来的。这是大财主里维加兹作为一份尊贵的个人礼物送给棘齿城的总工程师兼领袖加兹鲁维的，这瓶陈年佳酿代表了地精贸易大亨之间无价的敬意。",al={"99年波尔多陈酿是什么","99年波尔多陈酿","波尔多陈酿"}}},fp="16,141,24.258.0,18.378.1,50.101.0,42.157.0,39.125.0,48.140.0"}
P.entries["item:a-bloodstained-journal-page"] = {n="一张染血的日记书页",s="在调查斯塔文·密斯特曼托期间，指挥官阿尔泰娅·埃伯洛克安排人查验了一张撕破的染血日记书页。上面还有几个字依稀可辨，她请书记员达尔塔将字迹与城镇文档中的笔迹进行比对。",h="在调查斯塔文·密斯特曼托期间，指挥官阿尔泰娅·埃伯洛克安排人查验了一张撕破的染血日记书页。上面还有几个字依稀可辨，她请书记员达尔塔将字迹与城镇文档中的笔迹进行比对。",kw={"染血","达尔特雷","夜色镇","暮色森林","埃伯洛克","笔迹","日记","斯塔文"},ang={["faction:Alliance"]="为了王国的守护者，夜色镇的守夜人查验这份骇人的文书，将其作为调查的证据。"},sec={{t="骇人的证物",b="指挥官阿尔泰娅·埃伯洛克守护着夜色镇，她要求查验一张撕破的染血书页上的笔迹。虽然书页上血迹厚重，但仍有几个字依稀可辨，可供书记员达尔塔与城镇文档中的笔迹进行比对。"},{t="笔迹与罪证",b="书记员达尔塔在夜色镇的大厅保管登记册，多年来归档签名的工作让他熟悉了当地人的笔迹。他将书页与镇上的档案进行比对，确认书页出自斯塔文之手，这位家庭教师的罪行已无可置疑。"}},faq={{q="这张染血的日记书页是什么？",a="这是一张撕破的染血书页，在调查斯塔文·密斯特曼托期间被送去查验。指挥官阿尔泰娅·埃伯洛克请书记员达尔塔核对上面的笔迹。",al={"染血的日记书页","斯塔文日记书页","染血书页"}},{q="谁能确认这张书页是谁写的？",a="夜色镇大厅的书记员达尔塔能确认这张书页的作者。他保管着镇上的登记册，会将书页上的字迹与旧签名进行比对，以核实斯塔文的笔迹。",al={"谁阅读书页","书记员达尔塔日记","谁辨认笔迹"}},{q="阿尔泰娅·埃伯洛克为什么需要查验这张书页？",a="指挥官阿尔泰娅·埃伯洛克已经留意斯塔文一段时间了，她想请书记员达尔塔将书页与城镇文档进行比对。她需要知道两者的字迹是否出自同一人之手。",al={"阿尔泰娅为何需要书页","为何核对笔迹"}},{q="这张书页会将调查引向何处？",a="书页被送到夜色镇的书记员达尔塔手中，由他将上面的笔迹与登记册进行比对。他查验完毕后，调查将由指挥官阿尔泰娅·埃伯洛克继续推进。",al={"书页之后的进展","斯塔文任务链下一步"}}},fx={e0fa872a={q="染血的日记书页来自哪里，是谁制作的？",a="这张书页是斯塔文·密斯特曼托个人日记的残页。上面残留的文字描述了他的绝望以及他想要血债血偿的意图。",al={"谁写了染血的日记书页","斯塔文日记书页来源","染血的书页来自哪里"}}},fp="27,228,24.240.0,21.232.1,39.170.0,36.167.0,50.181.0,47.165.1"}
P.entries["item:a-clue-to-sanders-treasure"] = {n="A Clue to Sanders' Treasure",s="在西部荒野，A Clue to 杉德尔' Treasure引领寻宝者继续追寻杉德尔船长的踪迹。这是在峭壁与海岸间寻宝的第二步。",h="在西部荒野，A Clue to 杉德尔' Treasure引领寻宝者继续追寻杉德尔船长的踪迹。这是在峭壁与海岸间寻宝的第二步。",kw={"木桶","烟囱","线索","海盗","杉德尔","宝藏","西部荒野"},sec={{t="海盗的谜题",b="循着杉德尔船长的第一张藏宝图，你找到了一张羊皮纸，指向西部荒野更深的内陆。纸上潦草的字迹指引你从海岸向东，登上峭壁，朝大路前进。\n\n在残破的石砌废墟和废弃的烟囱附近，一只旧木桶标出了杉德尔藏匿下一条线索的地方。这条寻宝之路通向动荡不安的农田深处。"}},faq={{q="这是什么线索？",a="杉德尔船长留下了一张手写的纸条，指引足够聪明、能循着他的踪迹前行的人，找到藏在西部荒野的另一个容器。",al={"杉德尔的线索","杉德尔宝藏的线索","杉德尔宝藏的线索是什么"}},{q="这条线索指向哪里？",a="线索指引你从海岸向东，登上峭壁，朝西部荒野的大路前进。一只旧木桶就在残破的烟囱附近。",al={"该去哪里","线索指向何处","烟囱位置"}},{q="杉德尔船长是谁？",a="杉德尔船长曾是一名海盗。他藏在西部荒野沿岸和乡间各处的宝藏与谜题，至今仍留存着他的往事。",al={"杉德尔船长是谁","杉德尔的故事","杉德尔船长"}}},fx={e66b6229={q="这条线索来自哪里，是谁制作的？",a="这份书面笔记是由杉德尔船长留下的，他是一位臭名昭著的剑客，在西部荒野各处埋藏了他的非法战利品。这位狡猾的船长并没有留下一张直接指向他财宝的地图，而是写下了一连串谜题和指示，将每条信息隐藏在海岸各处的地标中，以考验任何胆大心细、足以追踪他遗产的人。",al={"谁制作了桑德斯的线索","线索来自哪里","线索的起源"}},["4dc920ed"]={q="为什么这条线索对寻宝者很有价值？",a="单看这张羊皮纸，它只是一首晦涩难懂的打油诗，但对于一位立志发财的人来说，它是揭开杉德尔船长传说中的隐藏宝藏的关键一步。按照上面的指示是找到他精心设计的寻宝游戏中下一个线索的唯一途径，并最终获得这位海盗船长私藏的所有财宝。",al={"为什么要桑德斯的线索","为什么线索很重要","桑德斯的线索有什么用"}}},fp="27,161,17.359.0,18.130.0,26.124.0,24.133.0"}
P.entries["item:a-dusty-unsent-letter"] = {n="一封覆满灰尘的信",s="在西部荒野，一封蒙尘的信揭示了斯塔文·密斯特曼托在月溪镇的过往。这封未寄出的信在一只旧手提箱中被发现，证实了他失踪前曾住在那里。",h="在西部荒野，一封蒙尘的信揭示了斯塔文·密斯特曼托在月溪镇的过往。这封未寄出的信在一只旧手提箱中被发现，证实了他失踪前曾住在那里。",kw={"书记员达尔塔","夜色镇","布满灰尘的未寄出的信","弃灵","月溪镇","斯塔文·密斯特曼托","斯塔文的传说"},ang={["faction:Alliance"]="身为一名联盟旅人，了解斯塔文的行踪，有助于夜色镇准确记录那些往来于西部荒野和暮色森林的人类聚居地之间的旅人与流亡者。"},sec={{t="尘封的线索",b="追查斯塔文·密斯特曼托过往的调查者在月溪镇的一只旧手提箱中找到了一封未寄出的信。夜色镇的居民名册仍将他的最后住址记为Moonbrook Schoolhouse，书记员达尔塔想知道他是否确实在那里住过。这封信证实，斯塔文曾在西部荒野的这座小镇住过一段时间。找到信件时，一个心怀怨恨的弃灵受到惊扰，它满怀恶意，守护着斯塔文往昔留下的遗物。"},{t="更新名册",b="书记员达尔塔在夜色镇的市政厅收下了这封信，将其作为镇上档案的佐证。他觉得这封信始终未被寄出一事十分蹊跷，并暗示了斯塔文在联盟南部诸王国留下的踪迹。"}},faq={{q="这封信在哪里找到？",a="这封信在西部荒野月溪镇的一只废弃手提箱中，周围的破败房屋已被迪菲亚潜行者占据。",al={"信件位置","哪里获取尘封的未寄出的信","月溪镇信件"}},{q="这封信为何没有寄出？",a="这封信从未寄出的原因尚不明确。书记员达尔塔觉得此事可疑，认为斯塔文可能仓促逃离了月溪镇，或是在前往别处之前遗落了信件。",al={"为何未寄出","斯塔文的信未寄出","信是写给谁的"}},{q="谁需要看这封信？",a="书记员达尔塔需要看这封信。他在夜色镇的市政厅内管理居民名册。",al={"信交给谁","书记员达尔塔信件","交付信件"}},{q="为什么找到信时会有幽灵袭击？",a="惊扰手提箱会召来一个弃灵，它与斯塔文阴魂不散的往事相连。它会攻击任何探查他那段被遗忘人生的人，并对闯入者施加令人衰弱的斯塔文诅咒。",al={"弃灵","幽灵为何出现","斯塔文的诅咒"}}},fx={f7d2f799={q="“一封覆满灰尘的信”是什么？",a="这块破旧的羊皮纸是月溪镇一个旧脚箱里未寄出的信件。它是斯塔文·密斯特曼托曾居住在西部荒野，随后从当地历史中销声匿迹的有力证据。",al={"一封覆满灰尘的信","什么是覆满灰尘的信","月溪镇的覆满灰尘的信"}},["9d1bfc16"]={q="“一封覆满灰尘的信”来自哪里，是谁制作的？",a="这封信被留在了月溪镇，存放在这座荒废城镇的一个脚箱里。它是在斯塔文·密斯特曼托在西部荒野逗留期间写的，是他写给村外联系人的，但出于某种未知的原因，它在发出之前就被遗弃了。",al={"谁写了覆满灰尘的信","这封信来自哪里","覆满灰尘的信的起源"}},ab0e7a8a={q="为什么有人想要“一封覆满灰尘的信”？",a="夜色镇的书记员达尔塔需要官方证据来更新关于斯塔文·密斯特曼托的城镇登记记录。由于城镇记录存在缺失，这封信提供了斯塔文曾居住在月溪镇的必要核实信息，使达尔塔能够妥善记录他过去的行踪。",al={"谁想要覆满灰尘的信","为什么要留着覆满灰尘的信","为什么要带信给达尔塔"}}},fp="21,154,18.440.0,21.237.1,27.132.0,30.184.0,29.98.0,41.199.0"}
P.entries["item:a-faded-journal-page"] = {n="一张褪色的日记书页",s="在艾尔文东部，一张旧书页指向了斯塔文·密斯特曼托的阴暗往事。",h="在艾尔文东部，一张旧书页指向了斯塔文·密斯特曼托的阴暗往事。",kw={"夜色镇","艾尔文森林","褪色的日记书页","治安官哈迦德","斯密茨","斯塔文"},ang={["faction:Alliance"]="身为联盟旅人，你可以借助这份被遗忘的记录，解开一个困扰着艾尔文与暮色森林之间河流两岸镇民的谜团。"},sec={{t="箱中的羊皮纸",b="褪色的日记书页在治安官哈迦德家中的一个旧箱子里放了多年，他的家就在艾尔文森林东部边界附近。哈迦德在那里退休隐居，但日渐衰退的视力让他无法读清这张饱经风霜的羊皮纸。书页一直无人理会，直到追查斯塔文·密斯特曼托真相的调查者将它取走。"},{t="通往夜色镇的线索",b="治安官哈迦德读不清脆弱纸页上的字迹，便让调查者渡过河流，前往暮色森林的血鸦旅店。酒保旅店老板斯密茨一查看书页，就认出了上面的笔迹，将它与笼罩这片地区的阴暗往事联系起来。"}},faq={{q="在哪里能找到褪色的日记书页？",a="这张书页位于艾尔文森林东部、与暮色森林隔河相望的边界附近，在治安官哈迦德附近一所房屋楼上的箱子里。",al={"书页位置","褪色的日记书页在哪里","箱子位置"}},{q="治安官哈迦德为什么无法亲自阅读书页？",a="治安官哈迦德年事已高，视力衰退得十分严重，已经无法辨认褪色的字迹。",al={"哈迦德为什么没读","治安官哈迦德失明"}},{q="谁认得日记书页上的笔迹？",a="夜色镇血鸦旅店的酒保旅店老板斯密茨看到书页时，认出了上面的笔迹。",al={"谁认得笔迹","谁阅读书页"}},{q="什么在守护装着书页的箱子？",a="一个敌对的弃灵会攻击任何打开楼上箱子的人，让人无法安然查看书页。",al={"箱子幽灵","箱子旁什么会攻击"}}},fx={["6378278c"]={q="“褪色的日记书页”是什么？",a="这是一张陈旧、风化的羊皮纸，是从治安官哈迦德家中的一个箱子里找到的。上面的文字随着时间的推移已经变得模糊不清，但它保留了一段真实的条目，详细记录了斯塔文·密斯特曼托的个人想法和行踪，是揭开他黑暗历史的一条重要线索。",al={"什么是褪色的日记书页","褪色的日记书页","褪色的日记书页信息"}},["0f9a7ce9"]={q="“褪色的日记书页”来自哪里？",a="这张书页是斯塔文·密斯特曼托本人作为其个人日记的一部分书写的。它最终出现在治安官哈迦德后来居住在艾尔文森林和暮色森林交界处附近的住宅楼上，被放在一个装有废弃羊皮纸的箱子里。",al={"褪色的日记书页起源","谁写了褪色的日记书页","褪色的日记书页来自哪里"}},["200aee1d"]={q="为什么要寻找“褪色的日记书页”？",a="寻找被称为斯塔文·密斯特曼托这一神秘人物背后真相的调查员需要这张书页来拼凑他的过去。因为上面的笔迹非常独特，将其展示给夜色镇的旅店老板斯密茨等见多识广的当地人，可以获得关于斯塔文历史和行踪的重要线索。",al={"为什么要寻找褪色的日记书页","为什么要用到褪色的日记书页","褪色的日记书页目的"}}},fp="20,112,22.316.0,22.254.1,38.133.0,51.96.0,51.126.0,44.109.0"}
P.entries["item:a-letter-to-grelin-whitebeard"] = {n="给格瑞林·白须的信",s="一封来自铁炉堡的信送到了格瑞林·白须在寒脊山谷的营地。信中的消息和指示，拉近了山中都城与冰雪边地的距离。",h="一封来自铁炉堡的信送到了格瑞林·白须在寒脊山谷的营地。信中的消息和指示，拉近了山中都城与冰雪边地的距离。",kw={"寒脊山谷","丹莫罗","格瑞林·白须","铁炉堡","信件","邮件投递"},ang={["race:Dwarf"]="身为矮人，你可能会带着公函穿越丹莫罗冰冷的山口。年轻的巡山人和新兵将此视为一项基本职责，希望借此为自己赢得名声。"},sec={{t="山中来函",b="格瑞林·白须在寒脊山谷的营地收到了一封来自铁炉堡的公函。安威玛尔能提供庇护，但山谷远离那片安全之地。书信将野外的斥候和学者与山中都城的厅堂联系起来。这封信沿着山路向南，送到了他的手中。"}},faq={{q="格瑞林·白须是谁？",a="格瑞林·白须是一名矮人斥候兼探险者，在寒脊山谷东南部扎营。安威玛尔的信使为他送来铁炉堡的消息和指示。",al={"格瑞林·白须","格瑞林是谁","收信人"}},{q="这封信来自哪里？",a="这封信来自矮人的都城铁炉堡。一名当地邮差带着它穿过寒脊山谷，送往野外。",al={"信件来源","谁寄的信","来自哪里"}},{q="信里写了什么？",a="国王麦格尼·铜须给格瑞林寄来了一封短信。时间紧迫，他授权格瑞林自行决定如何对付巨魔，尤其是如果格瑞林能找到速战速决的办法。格瑞林很高兴收到消息；他已经有一阵子没听到铁炉堡的音讯了。",al={"信件内容","信里说了什么","信件正文"}}},fx={["163f292d"]={q="“给格瑞林·白须的信”是什么？",a="这是一封从铁炉堡发出的密封信函，经过寒脊山谷，准备送达在路边营地的格瑞林·白须手中。",al={"什么是给格瑞林·白须的信","给格瑞林·白须的信","这封信是什么"}},b0fcb20c={q="为什么格瑞林·白须想要这封信？",a="格瑞林在他的寒脊山谷营地驻扎已久，一直没有收到来自主城的消息。他渴望收到铁炉堡的消息。",al={"为什么要送给格瑞林的信","为什么格瑞林想要这封信","谁想要格瑞林的信"}}},fp="29,164,28.300.0,25.163.0,32.134.0,26.268.0"}
P.entries["item:a-mysterious-message"] = {n="神秘的信件",s="在西部荒野，一封从信使手中截获的信件，让人民军掌握了谁在指挥迪菲亚潜行者的证据。",h="在西部荒野，一封从信使手中截获的信件，让人民军掌握了谁在指挥迪菲亚潜行者的证据。",kw={"黑爪","迪菲亚信使","艾德温·范克里夫","格里安·斯托曼","月溪镇","神秘的信息","西部荒野"},ang={["class:Rogue"]="这封截获的公文，让潜行者得以窥见迪菲亚地下势力所采用的行动保密措施、信使路线和加密通信方式。",["faction:Alliance"]="对在西部荒野提供援助的联盟勇士而言，这份截获的文件证明，王国农田地区的动乱是由艾德温·范克里夫领导的一场蓄谋已久的叛乱，而非零星的匪患。"},sec={{t="黑爪的传闻",b="这封公文指出，范克里夫是兄弟会的首领，还提到了一位名叫黑爪的同伙。兄弟会更广泛的关系网仍隐藏在暗处。破译这份文件后，人民军便有了迫使被俘窃贼合作的筹码，也有了找到兄弟会真正据点的途径。"},{t="截获的命令",b="一名迪菲亚信使携带这封信，在月溪镇、金海岸矿洞和詹戈洛德矿洞的迪菲亚据点之间传递消息。截获这封信，让格里安·斯托曼的调查有了突破。几个星期以来，人民军一直怀疑有人在指挥这场匪徒叛乱，却始终没有确凿的证据。\n\n这封信证实，艾德温·范克里夫指挥着兄弟会在西部荒野各地的行动。他通过使用代号的各级成员和中间人发号施令。"}},faq={{q="这封信向人民军揭示了什么？",a="这封信让格里安·斯托曼掌握了证据，证实艾德温·范克里夫指挥着迪菲亚潜行者在西部荒野各地的行动。民兵一直怀疑他就是这些亡命之徒的首领，如今终于得到了证实。",al={"字条上写了什么","神秘的信件背景故事","信里有什么"}},{q="黑爪是谁？",a="截获的信件提到，黑爪是一名同伙或代理人。除此之外，其身份和行踪几乎无人知晓，仍是迪菲亚关系网深处那些隐秘人物中的一员。",al={"黑爪是谁","黑爪背景故事","迪菲亚的黑爪"}},{q="谁携带着这封信？",a="一名迪菲亚信使携带这封信，沿着西部荒野的道路往返于月溪镇、金海岸矿洞和詹戈洛德矿洞之间，协调匪徒的行动。",al={"谁拿着信","谁掉落神秘的信件","迪菲亚信使"}},{q="格里安·斯托曼读完信后发生了什么？",a="范克里夫的身份得到确认后，民兵开始寻找迪菲亚的总部。一名被俘的盗贼答应带领斥候前往秘密藏身处，以换取自己的性命。",al={"接下来是什么","斯托曼的反应","神秘的信件后续"}}},fx={["9bec86bb"]={q="“神秘的信件”是什么？",a="这是一封由迪菲亚信使携带穿过西部荒野的密封信件。信是寄给一个名叫黑爪的操作员的，包含着在该地区活动的阴谋分子之间的关键通信。",al={"神秘的信件","这封信是什么","迪菲亚便条"}},ea5b5889={q="“神秘的信件”来自哪里，是谁制作的？",a="这封信件出自迪菲亚潜行者的高层，写给他们的操作员黑爪的指示，并通过连接月溪镇、金海岸矿洞和詹戈洛德矿洞的信使路线进行传送。",al={"谁写了神秘的信件","谁发了神秘的信件","神秘的信件起源"}},f3ab4b79={q="为什么格里安·斯托曼想要“神秘的信件”？",a="格里安·斯托曼和人民民兵团急于找到迪菲亚潜行者的秘密藏身处，并了解他们的指挥结构。截获这封信件为他们提供了确凿的书面证据，证明艾德温·范克里夫直接策划了迪菲亚潜行者的叛乱。",al={"为什么要神秘的信件","斯托曼为什么要信件","为什么获取神秘的信件"}}},fp="20,116,22.276.1,18.437.1,54.191.1,18.205.0,25.159.0,46.172.1"}
P.entries["item:a-simple-compass"] = {n="简易罗盘",s="在西部荒野被焚毁的阿历克斯顿农场，一只小箱子里放着一个简易罗盘。在巴隆斯·阿历克斯顿成为暴风城的城市建筑师之前，它就属于他。",h="在西部荒野被焚毁的阿历克斯顿农场，一只小箱子里放着一个简易罗盘。在巴隆斯·阿历克斯顿成为暴风城的城市建筑师之前，它就属于他。",kw={"阿历克斯顿","巴隆斯","出身","箱子","罗盘","农场","暴风城","西部荒野"},ang={["faction:Alliance"]="帮助巴隆斯·阿历克斯顿找回纪念物，让人看到了迪菲亚起义给人们带来的伤痛。即使是暴风城中地位显赫的领袖，也在西部荒野的动乱中失去了家园。",["race:Human"]="身为王国的人类一员，你能从这个罗盘中看到两种生活的对照：一边是暴风城安全而富丽堂皇的庭院，另一边是西部荒野荒废而无法无天的边地。"},sec={{t="童年的纪念物",b="巴隆斯·阿历克斯顿从小在西部荒野的自家农场干活。他用来辨认方向的第一件工具，就是一只简易罗盘。它或许激发了他对几何、制图和探索的兴趣。后来，迪菲亚潜行者袭击并烧毁了农场，匪徒占据了农田，而罗盘留在废墟中一只坚固的箱子里。"},{t="寄托的情感",b="巴隆斯的父亲逃过了那场劫难，却没能把家中的财物带到安全的地方。在暴风城的石墙之内，这个罗盘对一位建筑大师已没什么用处。然而，它对巴隆斯意义重大。找回罗盘，就能让他重新拥有一份难得且完好的牵系，连着他清贫的出身和童年时宁静的乡野。"}},faq={{q="简易罗盘是什么？",a="巴隆斯·阿历克斯顿年幼时住在西部荒野的自家农场，拥有一只简易罗盘，那是一只普通、不带魔法的袖珍罗盘。",al={"简易罗盘","阿历克斯顿的罗盘","巴隆斯的罗盘"}},{q="罗盘在哪里？",a="罗盘就在西部荒野哨兵岭西边不远处，阿历克斯顿农场被焚毁的废墟中的阿历克斯顿的箱子里。",al={"哪里能找到罗盘","罗盘位置","亚历克斯顿的箱子位置"}},{q="谁想找回这只罗盘？",a="暴风城的城市建筑师巴隆斯·阿历克斯顿希望找回这个罗盘。在教堂广场的市政厅附近可以找到他。",al={"谁需要罗盘","罗盘交还","罗盘属于谁"}},{q="为什么罗盘被留在了农场？",a="迪菲亚匪徒袭击并烧毁了阿历克斯顿农场。巴隆斯的父亲仓皇逃命，无法带走家中较重的财物，因此箱子留在了废墟里。",al={"为什么留下罗盘","农场发生了什么"}}},fp="16,160,18.345.0,17.325.0,25.116.0,29.131.0,32.127.0,44.181.0"}
P.entries["item:a-stack-of-letters"] = {n="一摞信件",s="在寒脊山谷，一摞信件穿过山口送来，要交给冰雪荒野中的斥候。",h="在寒脊山谷，一摞信件穿过山口送来，要交给冰雪荒野中的斥候。",kw={"安威玛尔","寒脊山谷","寒脊山谷邮件递送","格瑞林·白须","一摞信件","塔林·锐眼"},ang={["race:Dwarf"]="作为一名初到寒脊山谷的年轻巡山人，你在白雪覆盖的营地之间递送邮件。这段旅程让你见识到丹莫罗崎岖的道路，以及散布各处的守望者。"},sec={{t="穿越山口",b="寄往寒脊山谷的信件由穿越山口的旅人从安威玛尔带来。通往丹莫罗群山中偏远营地的道路崎岖难行，因此邮差要靠旅人将每捆信件继续送往前方。这一捆要送给寒脊山谷深处的斥候。\n\n在信件分拣之前，人们以为湖畔营地里的塔林·锐眼是唯一的收信人。其中有一封信是寄给巡山人格瑞林·白须的。"}},faq={{q="这摞信件里有什么？",a="这捆信件里有寄给寒脊山谷矮人的私人信件和公文。起初，人们以为冰湖附近营地里的塔林·锐眼是唯一的收信人，直到发现其中有一封写着格瑞林·白须的名字。",al={"信件里有什么","一摞信件的内容","信件寄给谁"}},{q="是谁将这些信件寄往寒脊山谷？",a="这些信件穿过山口进入寒脊山谷，抵达安威玛尔。从那里，一位愿意沿路捎信的旅人将它们继续送往前方。",al={"信件来自哪里","谁寄的信"}},{q="谁会收到这些信件？",a="矮人斥候塔林·锐眼在冰湖边的营地收到这包信件。他翻看这摞信件时，发现了一封寄给格瑞林·白须的信。",al={"谁收到信件","信件递送对象"}}},fx={["6f17116a"]={q="“一摞信件”是什么？",a="这是一捆通过山道抵达寒脊山谷的邮件。在安威玛尔交给你时，这叠信件包含了寄给驻扎在冰雪荒野当地登山者的通信。",al={"什么是一摞信件","一摞信件物品","信件是什么"}},["9fce371d"]={q="为什么有人想要“一摞信件”？",a="生活和巡逻在寒冷地带的登山者依赖常规邮寄来保持信息畅通。塔林·锐眼在冰冻的湖边等待这些公文已经有一段时间了，尽管检查后发现，这捆信件中并非每一封都是他的。",al={"为什么要递送信件","为什么塔林想要这些信件","一摞信件的用途"}}},fp="18,110,16.437.0,36.225.0,44.154.0,25.149.0"}
P.entries["item:a-torn-journal-page"] = {n="一张被撕破的日记书页",s="在暴风城，一张被撕破的日记书页将一个旧箱子与斯塔文·密斯特曼托的往事联系起来。书页上模糊的字迹指向了保存在艾尔文森林的档案。",h="在暴风城，一张被撕破的日记书页将一个旧箱子与斯塔文·密斯特曼托的往事联系起来。书页上模糊的字迹指向了保存在艾尔文森林的档案。",kw={"运河","暮色森林","斯塔文的传说","治安官哈迦德","密封的箱子","斯塔文·密斯特曼托","暴风城","被撕破的日记书页"},ang={["faction:Alliance"]="身为联盟的一员，你能看到暴风城与艾尔文的悬案和被遗忘的档案如何将阴影延伸至暮色森林，纠缠着那片苦苦挣扎的边疆。"},sec={{t="运河边的线索",b="一张被撕破的日记书页藏在暴风城运河旁一个密封的储物箱中。在那些被遗忘的私人物品里，旧书、传家宝和一只陶瓷花瓶围着这张破旧的残页。尽管书页残破，难以辨认，上面独特的笔迹仍指向了斯塔文·密斯特曼托的往事。王国中有谁能认出写下这些文字的人呢？"},{t="追寻密斯特曼托的踪迹",b="治安官哈迦德住在远离暴风城的艾尔文森林。这位年迈的军官视力日渐衰退，却仍记得那独特的笔迹，它曾出现在密斯特曼托悲剧往事的早期篇章中。这张饱经风霜的书页必须交给熟悉王国旧档案的人。"}},faq={{q="在哪里能找到被撕破的日记书页？",a="一张被撕破的日记书页藏在暴风城运河旁一个密封的储物箱中，压在被遗忘的家用物品、狩猎战利品和一只旧陶瓷花瓶下面。",al={"被撕破的日记书页位置","哪里能找到被撕破的日记书页","密封的箱子 暴风城"}},{q="这张书页出自谁的日记？",a="这张书页出自斯塔文·密斯特曼托的私人手稿。他曾是一名家庭教师，其黑暗的过去和突然失踪引发了遍及暮色森林与艾尔文森林的调查。",al={"日记书页是谁写的","残页作者","斯塔文 是谁"}},{q="谁能辨认残页上的笔迹？",a="治安官哈迦德能认出这种笔迹。这位年迈、近乎失明的退役军官住在艾尔文森林东部的东谷伐木场附近，记得自己在视力衰退前见过这种笔迹。",al={"残页交给谁","谁能读懂被撕破的日记书页","治安官哈迦德 日记"}},{q="找到这张书页为何对暮色森林如此重要？",a="找到这张书页很重要，因为夜色镇的 镇议会 正在拼凑斯塔文·密斯特曼托的过往，以查明与他有关的诡异事件和尘封罪行背后的真相。",al={"暮色森林为何关心日记","斯塔文 与暮色森林的联系"}}},fx={["8b619691"]={q="“撕裂的日记书页”是什么？",a="撕裂的日记书页是一张在暴风城的一个密封储物箱里，被旧家传宝、书籍和狩猎战利品掩盖住的破烂书页。它是关于斯塔文·密斯特曼托的一份重要书面证据，提供了独特的笔迹样本，将他安静的过去生活与困扰暮色森林的黑暗谜团联系在了一起。",al={"撕裂的日记书页背景","什么是撕裂的日记书页","这本日记书页是什么"}}},fp="19,138,20.317.0,28.281.1,37.167.0,38.182.0,46.202.0,45.190.0"}
P.entries["item:abercrombie-s-crate"] = {n="亚伯克隆比的箱子",s="亚伯克隆比的箱子被遗弃在沃古尔食人魔山附近，箱子的主人被食人魔赶跑了。箱子里装着这位古怪隐士的精密工具和采集的草药。",h="亚伯克隆比的箱子被遗弃在沃古尔食人魔山附近，箱子的主人被食人魔赶跑了。箱子里装着这位古怪隐士的精密工具和采集的草药。",kw={"亚伯克隆比","亚伯克隆比的箱子","暮色森林","食人魔山","食人魔窃贼","沃古尔"},ang={["faction:Alliance"]="你深入沃古尔食人魔山，找回遗失的物资，那里的食人魔威胁着暮色森林南部。",["profession:Herbalism"]="亚伯克隆比为寻找稀有植物而深入森林，因此，对当地的草药师来说，找回他的植物采集工具是一项熟悉的差事。"},sec={{t="落入食人魔之手",b="亚伯克隆比离开暮色森林西部的小屋，外出采集植物。在远离家园的地方，他遇到了一群充满敌意的食人魔，为了活命仓皇逃走，丢下了装有器具和采集植物的箱子。食人魔把箱子搬到了沃古尔食人魔山，如今这只沉重的箱子就放在洞口附近。"},{t="古怪的物品",b="亚伯克隆比声称，箱子里的工具和植物都无害。然而，箱子归还时，他的兴奋却露出了破绽。他差点说出感谢“亡”的话，随即改口，让人不禁怀疑这些被抢走的工具究竟有何用途。"}},faq={{q="箱子在哪里？",a="箱子在暮色森林南部群山中的沃古尔食人魔山，放在洞口旁的露天处。",al={"箱子位置","亚伯克隆比的箱子在哪里","沃古尔箱子"}},{q="亚伯克隆比为什么会丢失箱子？",a="亚伯克隆比在远离家园的地方采集草药时，遭到了食人魔的袭击。他徒步逃走，丢下了物资，食人魔则把这些东西搬回了巢穴。",al={"食人魔如何得到箱子","箱子为何在食人魔那里"}},{q="箱子里有什么？",a="亚伯克隆比说，箱子里装着稀有草药和专用的采集工具。箱子归还时，他的兴奋和失言暗示，这些工具或许有着更阴暗的用途。",al={"箱内物品","亚伯克隆比丢了什么"}},{q="亚伯克隆比为什么差点感谢“亡”？",a="亚伯克隆比拿回箱子时，脱口而出：“感谢亡……”随后又改口感谢冒险者。他始终没有说出，自己差点感谢的究竟是谁，或是什么。",al={"亚伯克隆比亡失言","感谢亡的含义"}}},fx={["7a42047e"]={q="“亚伯克隆比的箱子”是什么？",a="这是一个属于亚伯克隆比的木制补给箱，他是一位住在暮色森林北路边破败棚屋里的隐士。亚伯克隆比声称箱子里装着他那孤独手艺所必需的稀有草药和精巧工具，尽管他古怪的行为和无意中泄露的只言片语暗示他看重箱子里的东西是出于更黑暗的目的。",al={"亚伯克隆比的箱子","箱子是什么","亚伯克隆比的箱子物品"}},c6e454ed={q="为什么亚伯克隆比想要找回他的箱子？",a="亚伯克隆比在觅食时被来自南部山丘的食人魔伏击，为了逃命被迫丢弃了他的补给品。他非常想念他的设备，声称没有它就无法继续他的草药研究，并承诺找回箱子能确保未来有快乐、高效的工作之夜。",al={"为什么要取回亚伯克隆比的箱子","为什么亚伯克隆比想要箱子","为什么要箱子"}}},fp="19,149,17.291.0,17.231.1,27.107.0,28.158.0,25.181.1,45.170.1"}
P.entries["item:admiral-proudmoore-s-orders"] = {n="普罗德摩尔将军的命令",s="库尔提拉斯部队仍然坚守着杜隆塔尔的沿海阵地，而《普罗德摩尔将军的命令》则列明了他们的计划。这些文件写于戴林·普罗德摩尔在塞拉摩战死之前，描述了一场针对部落的战役。",h="库尔提拉斯部队仍然坚守着杜隆塔尔的沿海阵地，而《普罗德摩尔将军的命令》则列明了他们的计划。这些文件写于戴林·普罗德摩尔在塞拉摩战死之前，描述了一场针对部落的战役。",kw={"本尼迪克","杜隆塔尔","库尔提拉斯","纳兹格雷尔","命令","奥格瑞玛","普罗德摩尔","提拉加德"},ang={["faction:Horde"]="对部落而言，这些文件支持了那些认为与人类的停战无法长久维持的人。文件表明，库尔提拉斯部队从登陆的那一刻起，就打算发动一场灭绝之战。",["race:Troll"]="身为黑暗之矛巨魔，这些命令向你表明，盘踞在你族人家园沿海地区的人类，仍是迫在眉睫的威胁。"},sec={{t="仇恨的遗产",b="《普罗德摩尔将军的命令》表明，提拉加德城堡的库尔提拉斯部队仍有意继续作战。本尼迪克上尉的驻军保管着这些文件，其中详述了针对部落的长期军事行动和防御工事。这些计划表明，戴林·普罗德摩尔在杜隆塔尔的攻势是一场有组织的战役，意在他死后仍能继续进行。对部落而言，这些文件揭示了库尔提拉斯的军事行动，以及可能威胁边境的增援部队。"},{t="送往索尔的堡垒",b="部落斥候将找回的命令送往奥格瑞玛的索尔的堡垒。他们在萨尔的房间里将命令交给纳兹格雷尔，这些计划印证了纳兹格雷尔的警告：人类不可信，而且仍是现实的威胁。部落领袖如今有理由为沿海地区遭受更多袭击做好准备。"}},faq={{q="普罗德摩尔将军的命令是什么？",a="《普罗德摩尔将军的命令》是戴林·普罗德摩尔在塞拉摩战死前拟定的军事指令。这些命令要求留在杜隆塔尔的库尔提拉斯士兵加固沿海阵地，并对部落发动战争。",al={"普罗德摩尔将军的命令","命令是什么","将军的命令物品"}},{q="这些命令是在哪里缴获的？",a="这些命令是在杜隆塔尔的提拉加德城堡缴获的，当时那里正发生着对抗东南海岸附近库尔提拉斯部队的战斗。",al={"哪里能找到命令","命令位置","谁掉落命令"}},{q="谁需要查看这些命令？",a="纳兹格雷尔需要看到这些命令。他在奥格瑞玛的智慧谷内的索尔的堡垒中，为大酋长萨尔出谋划策。",al={"交给谁","谁需要命令","命令交付"}},{q="库尔提拉斯士兵为何仍在杜隆塔尔作战？",a="库尔提拉斯士兵仍留在杜隆塔尔，是因为本尼迪克中尉等人始终忠于普罗德摩尔将军灭绝兽人的使命。他的命令为驻军提供了计划，使他们无需他亲自督战，也能继续袭扰杜隆塔尔。",al={"人类为何在杜隆塔尔","提拉加德城堡为何敌对","戴林死后为何还在战斗"}}},fp="27,190,18.376.0,25.288.1,37.223.0,34.129.0,30.114.0,53.238.0"}
P.entries["item:ados-fragment"] = {n="阿度斯碎片",s="在湿地的维尔加挖掘场，阿度斯碎片与戈阿兹之石另外三块遗失的碎片散落于此。四块碎片合在一起，便是一件刻有泰坦铭文的古老圣物。",h="在湿地的维尔加挖掘场，阿度斯碎片与戈阿兹之石另外三块遗失的碎片散落于此。四块碎片合在一起，便是一件刻有泰坦铭文的古老圣物。",kw={"阿度斯碎片","挖掘","戈阿兹之石","上古之神","遗物","泰坦","湿地","维尔加"},ang={["race:Dwarf"]="身为矮人，你知道探险者协会正在寻找阿度斯碎片这样的Titans遗物，以揭开你们一族及其远古创造者的起源。"},sec={{t="戈阿兹之石的碎片",b="勘察员维尔加需要四块碎片，才能在维尔加挖掘场复原戈阿兹之石，阿度斯碎片便是其中之一。在迅猛龙占据挖掘场之前，维尔加就已开始翻译主石板，并发现铭文总在关键之处中断。这四块碎片分别名为阿度斯、莫德、高尔姆和奈尔鲁，遗失在废墟各处的古老容器与土堆中，周围有野兽游荡。"},{t="泰坦的文字",b="勘察员维尔加将阿度斯碎片与另外三块碎片拼合后，就能读出戈阿兹之石上刻着的完整泰坦文字。完整的文字提到一项宏大的神圣计划和一则预示毁灭的预言，随后宣告：“上古之神……被锁在大地之下。”它揭示了泰坦在远古时代将原初存在囚禁于艾泽拉斯地下的往事。"}},faq={{q="阿度斯碎片是什么？",a="阿度斯碎片是古老的戈阿兹之石的一块残片，发现于湿地的维尔加挖掘场。上面雕刻的文字源自塑造世界的泰坦。",al={"阿度斯碎片","阿度斯是什么","戈阿兹之石碎片 阿度斯"}},{q="在哪里能找到这块碎片？",a="这块碎片散落在湿地的维尔加挖掘场，位于米奈希尔港以东。它通常藏在古代圣物或松软的土堆中，附近有领地意识很强的迅猛龙出没。",al={"阿度斯碎片在哪里","阿度斯位置","如何找到阿度斯"}},{q="碎片上写着什么？",a="阿度斯碎片上的铭文本身并不完整。勘察员维尔加需要莫德、高尔姆和奈尔鲁碎片，才能继续翻译石板。",al={"阿度斯碎片文字","阿度斯上写着什么","戈阿兹之石翻译"}},{q="谁需要这块碎片？",a="勘察员维尔加正在寻找阿度斯碎片，以完成戈阿兹之石的翻译。他是探险者协会的一名矮人，负责管理这片已成废墟的挖掘场。",al={"谁需要阿度斯碎片","阿度斯碎片交付","维尔加 阿度斯"}}},fx={f3ac27ac={q="阿度斯碎片来自何处，又是谁制作了它？",a="阿度斯碎片是戈阿兹之石的碎片，这是一件在湿地挖掘场发现的远古圣物。在它于废墟中碎裂成四块之前，泰坦曾在这块石头上刻下了神秘的铭文。",al={"阿度斯碎片来源","谁制作了阿度斯碎片","阿度斯碎片来自哪里"}}},fp="13,165,25.386.0,16.361.1,26.162.0,28.180.0,27.149.1,24.148.0"}
P.entries["item:agamand-family-axe"] = {n="阿加曼德家传战斧",s="在提瑞斯法北部，阿加曼德家传战斧仍存放在这个家族的祖传兵器之中。它曾是富有磨坊主的象征，如今库勒曼·法席恩正寻求夺走它，剥夺已成为亡灵的阿加曼德族人仅存的尊严。",h="在提瑞斯法北部，阿加曼德家传战斧仍存放在这个家族的祖传兵器之中。它曾是富有磨坊主的象征，如今库勒曼·法席恩正寻求夺走它，剥夺已成为亡灵的阿加曼德族人仅存的尊严。",kw={"阿加曼德","阿加曼德墓穴","阿加曼德家传战斧","阿加曼德磨坊","库勒曼·法席恩","传家宝","提瑞斯法林地"},ang={["class:Warrior"]="墓穴中保存的武器表明，阿加曼德家族除了财富和粮食储备，也有尚武的传统。",["race:Undead"]="对被遗忘者而言，夺走阿加曼德家族的传家宝，是在向同样死于瘟疫的洛丹伦旧贵族清算旧怨。"},sec={{t="阿加曼德家族的兵器",b="第三次大战之前，阿加曼德家族在提瑞斯法林地北部丘陵各处拥有土地，还拥有规模庞大的磨坊和一座家族墓穴。阿加曼德家传战斧与其他祖传兵器一同存放在长眠于此的历代族长和战士身旁。天灾军团攻陷了庄园，屠杀了其中的居民，但那些武器依然留在地下的武器架上。"},{t="怨恨中的讨偿",b="天灾军团 将死去的阿加曼德家族复活，变成了巫妖王麾下毫无心智的奴仆。他们昔日的仆人库勒曼·法席恩以亡灵之躯存活下来，对旧主人满怀怨恨。法席恩将自己的死归咎于这个家族，派被遗忘者游荡者进入墓穴，从武器架上取走斧、剑、锤和匕首。他要抹去阿加曼德家族传承的最后痕迹。"}},faq={{q="阿加曼德家传战斧在哪里？",a="这把战斧存放在阿加曼德家族墓穴内的武器架上，墓穴位于提瑞斯法林地北部、阿加曼德磨坊的北端。",al={"战斧位置","战斧在哪里","阿加曼德战斧地点"}},{q="谁想要阿加曼德家传战斧？",a="布瑞尔的被遗忘者库勒曼·法席恩正在寻求这把战斧，以及这个家族的匕首、钉锤和长剑。他要剥夺旧主人的荣誉。",al={"谁需要战斧","库勒曼·法席恩任务","谁想要阿加曼德传家宝"}},{q="库勒曼·法席恩为什么憎恨阿加曼德家族？",a="法席恩生前受雇于阿加曼德家族，他将自己的死归咎于他们。如今他们化为亡灵爪牙，在庄园中游荡，而他则通过劫掠他们的墓穴来复仇。",al={"法席恩为什么想要传家宝","库勒曼·法席恩的过往","法席恩的怨恨"}},{q="阿加曼德家传战斧是可以使用的武器吗？",a="不是。这把战斧是一件祖传遗物，取回它是为了证明这个家族的墓室已遭亵渎。",al={"战斧能否装备","战斧属性"}}},fx={e4f67fe3={q="什么是阿加曼德家传战斧？",a="阿加曼德家传战斧是提瑞斯法林地显赫的阿加曼德家族的传家武器。它与家族其他的珍贵武器一同保存在祖传的墓穴中，代表了该家族在天灾军团席卷洛丹伦、将活着的家族成员变成毫无意识的亡灵奴仆之前的尚武传承与遗产。",al={"阿加曼德战斧","什么是阿加曼德家传战斧","阿加曼德传家战斧"}}},fp="18,202,24.350.0,20.373.0,40.130.0,33.154.0,50.162.0,42.92.0"}
P.entries["item:agamand-family-dagger"] = {n="阿加曼德家传匕首",s="在提瑞斯法北部，阿加曼德家传匕首与家族的其他武器一同存放在家族墓穴中。库勒曼·法席恩想要这把匕首和家族的其他兵器，以剥夺昔日主人留下的传承与荣耀。",h="在提瑞斯法北部，阿加曼德家传匕首与家族的其他武器一同存放在家族墓穴中。库勒曼·法席恩想要这把匕首和家族的其他兵器，以剥夺昔日主人留下的传承与荣耀。",kw={"阿加曼德","阿加曼德磨坊","库勒曼·法席恩","墓穴","匕首","传家宝","天灾军团","提瑞斯法林地"},ang={["class:Rogue"]="身为Rogue，你知道，潜过死而复生的亡灵，从墓穴的武器架上取走利刃，能让盗窃化作冰冷的复仇。",["race:Undead"]="身为Undead，你深知在洛丹伦幸存的被遗忘者与昔日主人之间那道充满苦涩的鸿沟，如今那些主人已被束缚，只能在Scourge中无意识地效力。"},sec={{t="墓穴中的传承",b="第三次大战之前，阿加曼德家族在提瑞斯法林地北部起伏的草甸间拥有大片庄园和谷物磨坊。天灾军团摧毁了他们的权势，但他们的武器仍留存在阿加曼德磨坊北面的家族墓穴中。家中不得安息的亡灵成员与巫妖王麾下无意识的仆从守卫着这把匕首。它令人想起这个家族的尚武传统，以及他们曾经凌驾于仆人和佃户之上的地位。"},{t="怨恨驱使的索取",b="库勒曼·法席恩住在布瑞尔，但他曾在为阿加曼德家族效力时丧命。他将自己的死归咎于这个家族，对他而言，这把匕首意味着怨恨，而非高贵的血统。法席恩派冒险者进入阿加曼德家族墓穴，取回匕首、长剑、战斧和钉锤。他想通过夺走墓中的这些兵器，剥夺那些已归入天灾军团的家族长辈最后的尊严，让阿加曼德之名彻底消失。"}},faq={{q="阿加曼德家传匕首是什么？",a="这件祖传武器曾属于提瑞斯法林地富有的阿加曼德家族。它与家族的其他兵器一同安放在他们的墓穴中，如今那里已被天灾军团控制。",al={"阿加曼德匕首","阿加曼德匕首是什么","家传匕首提瑞斯法"}},{q="在哪里能找到阿加曼德家传匕首？",a="这把匕首放在阿加曼德家族墓穴内的阿加曼德武器架上，墓穴位于提瑞斯法林地阿加曼德磨坊的最北端。",al={"哪里能找到阿加曼德匕首","阿加曼德匕首位置","匕首武器架位置"}},{q="库勒曼·法席恩为什么想要这把匕首？",a="库勒曼·法席恩生前曾为阿加曼德家族效力，并将自己的死归咎于他们。他想要这把匕首和其他传家宝，以剥夺昔日主人的荣耀，让他们彻底败亡。",al={"法席恩为什么想要匕首","法席恩 阿加曼德任务","为什么盗取阿加曼德墓穴"}},{q="这套传家武器还有哪些？",a="这套武器还包括阿加曼德家传长剑、阿加曼德家传战斧和阿加曼德家传钉锤。它们都存放在家族墓穴的武器架间。",al={"阿加曼德其他传家宝","阿加曼德武器列表","墓穴里还有什么"}}},fp="21,168,21.394.0,22.355.0,34.156.0,41.132.0,43.185.0,47.148.0"}
P.entries["item:agamand-family-mace"] = {n="阿加曼德家传钉锤",s="在阿加曼德磨坊，阿加曼德家传钉锤仍锁在家族墓穴中。它曾是洛丹伦北部一件引以为傲的传家宝，如今，他们昔日的仆人库勒曼·法席恩正在寻找它。",h="在阿加曼德磨坊，阿加曼德家传钉锤仍锁在家族墓穴中。它曾是洛丹伦北部一件引以为傲的传家宝，如今，他们昔日的仆人库勒曼·法席恩正在寻找它。",kw={"阿加曼德家族墓穴","阿加曼德家传钉锤","阿加曼德传家宝","阿加曼德磨坊","库勒曼·法席恩","提瑞斯法林地"},ang={["race:Undead"]="阿加曼德家族墓穴遭到亵渎，表明生前的旧怨会如何驱使被遗忘者清算往日的恩仇。"},sec={{t="破败的家族遗产",b="在第三次大战之前，阿加曼德家族在提瑞斯法林地北部拥有大片农田和风车磨坊。和当地其他贵族一样，他们也未能逃过亡灵瘟疫。天灾军团将他们复生为效命于巫妖王的无心智奴仆，如今他们仍在破败的庄园里游荡。家族的古老宝物依然锁在家族墓穴中。其中就有阿加曼德家传钉锤，见证着一个沦为蹒跚亡灵的家族昔日的传承。"},{t="仆人的复仇",b="库勒曼·法席恩正在寻找这柄钉锤，以及另外三件祖传兵器。这位曾受雇于阿加曼德家族的仆人将自己的死归咎于这个家族。法席恩复活后成为了被遗忘者的一员，他想剥夺那些无意识的阿加曼德家族仅存的每一丝尊严与荣誉。除了钉锤，他还想得到祖传的剑、斧和匕首，希望从昔日主人统治过的土地上抹去他们的记忆与骄傲。"}},faq={{q="阿加曼德家传钉锤在哪里？",a="这柄钉锤放在阿加曼德家族墓穴内的武器架上，墓穴位于提瑞斯法林地阿加曼德磨坊的最北端。",al={"钉锤在哪里","阿加曼德钉锤位置","寻找阿加曼德钉锤"}},{q="谁想要阿加曼德家传钉锤？",a="库勒曼·法席恩是一名住在布瑞尔的被遗忘者，他索要这柄钉锤和其他传家宝，要与昔日的主人清算旧账。",al={"谁需要钉锤","谁收取阿加曼德钉锤","库勒曼·法席恩传家宝"}},{q="库勒曼·法席恩为什么想让人偷走这些传家宝？",a="法席恩生前侍奉阿加曼德家族，并将自己的死归咎于他们。从墓穴中取走他们珍爱的武器，是他抹去这个家族最后一丝荣誉的方式。",al={"为什么偷传家宝","库勒曼·法席恩的动机","为什么憎恨阿加曼德家族"}},{q="阿加曼德家族遭遇了什么？",a="阿加曼德家族曾统治着洛丹伦北部繁荣的阿加曼德磨坊，直到瘟疫来袭。他们复生的尸体如今成了天灾军团麾下毫无心智的奴仆，在庄园和墓穴中游荡。",al={"阿加曼德家族是谁","阿加曼德家族遭遇了什么","阿加曼德背景故事"}}},fx={["0ef93592"]={q="什么是阿加曼德家传钉锤？",a="阿加曼德家传钉锤是提瑞斯法林地曾经繁荣一时的阿加曼德家族的祖传遗物。这件武器与家族的其他武装宝藏一同存放在家族墓穴中，代表了该家族在被天灾军团毁灭之前，其曾经的地位与荣耀所留下的最后痕迹。",al={"阿加曼德钉锤","什么是阿加曼德家传钉锤","阿加曼德传家钉锤"}}},fp="19,196,16.422.0,21.393.1,41.125.0,34.141.0,52.171.0,36.194.0"}
P.entries["item:agamand-family-sword"] = {n="阿加曼德家传长剑",s="在提瑞斯法北部，阿加曼德家传长剑仍存放于家族墓穴中。这柄失去光泽的长剑曾象征着这个磨坊世家的财富与地位，如今库勒曼·法席恩正寻求得到它，以抹去这个家族留下的印记。",h="在提瑞斯法北部，阿加曼德家传长剑仍存放于家族墓穴中。这柄失去光泽的长剑曾象征着这个磨坊世家的财富与地位，如今库勒曼·法席恩正寻求得到它，以抹去这个家族留下的印记。",kw={"阿加曼德","墓穴","法席恩","传家宝","磨坊","天灾军团","长剑","提瑞斯法"},ang={["class:Warrior"]="身为战士，你眼前的这柄长剑曾被擦拭得锃亮，象征着洛丹伦的贵族身份，如今却被遗弃在亵渎的墓穴中，留下了尚武荣光破灭的痕迹。",["race:Undead"]="对被遗忘者而言，从提瑞斯法昔日的贵族手中夺回这些遗物，意味着向那段未能庇护他们、至今仍未消逝的过去清算旧账。"},sec={{t="墓中的传承",b="阿加曼德家族家族曾凭借提瑞斯法林地北部的磨坊，拥有巨大的财富和影响力。当天灾军团席卷洛丹伦时，这个家族惨遭灭门，族人的尸体又被复活，成了巫妖王麾下毫无心智的奴仆。他们的祖传武器，包括那柄仪式用剑，都被封存在磨坊北缘的阿加曼德家族墓穴中。从墓中的武器架上取走这些刀剑，意在抹去人们对这个覆灭家族的记忆，摧毁其贵族地位。"},{t="来自坟墓的复仇",b="库勒曼·法席恩是一名居住在布瑞尔的被遗忘者，他正在寻找这柄长剑。他生前曾为阿加曼德家族效力，并将自己的死归咎于昔日的主人。法席恩派冒险者取回这柄长剑，以及这个家族祖传的斧、匕首和锤。他要剥夺那些步履蹒跚的阿加曼德家族仅存的荣誉，彻底摧毁他们血脉的尊严。"}},faq={{q="阿加曼德家传长剑是什么？",a="阿加曼德家传长剑是阿加曼德家族的祖传武器，这个显赫的贵族家族在洛丹伦陷落之前，经营着提瑞斯法林地北部的谷物磨坊。",al={"阿加曼德长剑背景故事","阿加曼德家传长剑是什么"}},{q="长剑存放在哪里？",a="这柄剑存放在阿加曼德家族墓穴内的武器架上，墓穴位于提瑞斯法林地阿加曼德磨坊的北缘。天灾军团的奴仆和复活的阿加曼德家族成员守卫着墓穴。",al={"阿加曼德长剑在哪里","阿加曼德长剑位置"}},{q="库勒曼·法席恩为什么想要这柄长剑？",a="库勒曼·法席恩生前曾为阿加曼德家族效力，并将自己的死归咎于他们。他寻找他们的传家武器，是为了剥夺他们仅存的荣誉，抹去人们对这个世家的记忆。",al={"谁想要长剑","法席恩为什么想要传家宝"}},{q="阿加曼德家族遭遇了什么？",a="阿加曼德家族在天灾军团入侵洛丹伦时惨遭屠戮。死去的族人至今仍被困在毫无心智的奴役之中，为巫妖王效命，徘徊于祖传的庄园和墓穴。",al={"阿加曼德家族是谁","阿加曼德磨坊的故事"}}},fp="20,212,20.473.0,31.337.1,33.165.0,27.200.0,42.188.0,36.178.0"}
P.entries["item:ahanu-s-leather-goods"] = {n="安哈努的皮货",s="安哈努的皮货将雷霆崖的皮革制品运往十字路口。安哈努把制好的皮甲和补给送到贫瘠之地，供那里的旅人使用。",h="安哈努的皮货将雷霆崖的皮革制品运往十字路口。安哈努把制好的皮甲和补给送到贫瘠之地，供那里的旅人使用。",kw={"安哈努","十字路口","迪弗拉克","加翰·鹰翼","皮货","塔尔","雷霆崖","双足飞龙"},ang={["race:Tauren"]="身为牛头人，你可以看到这次送货如何将你的祖先故土莫高雷与贫瘠之地各处的部落领地联系起来。"},sec={{t="台地之间的贸易",b="安哈努制作皮货，准备运往莫高雷以外的地方交易。在雷霆崖，这位制皮匠将生皮制成衣物和装备，供给贫瘠之地十字路口的商人加翰·鹰翼。穿越平原的陆路行程十分缓慢，因此牛头人选择从空中运送包裹。塔尔和迪弗拉克训练的双足飞龙能迅速将货物运往远方。"}},faq={{q="安哈努的皮货里装着什么？",a="安哈努的包裹里装着在雷霆崖用生皮制成的皮货。这些实用的护甲和装备已备妥，可以卖给旅人了。",al={"皮货是什么","安哈努包裹内容","包裹里有什么"}},{q="谁来接收这个包裹？",a="加翰·鹰翼在十字路口接收包裹。他将制成的货物卖给途经贫瘠之地中部的猎人、战士和冒险者。",al={"谁接收皮货","送往哪里","加翰皮货运送"}},{q="为什么用双足飞龙运送这个包裹？",a="安哈努用双足飞龙寄送包裹，因为把沉重的货物运下升降梯，再穿过贫瘠之地，需要不少时间。他指引信使去找雷霆崖的双足飞龙管理员塔尔，好让这些长着翅膀的信使将货物迅速送到十字路口等遥远的哨站。",al={"为什么空运包裹","雷霆崖双足飞龙运送","飞行管理员包裹"}}},fx={["32785653"]={q="什么是安哈努的皮货？",a="这是一捆在雷霆崖制作的成品皮货。这批货物将被运往贫瘠之地的十字路口定居点，旨在供应那里日益增多的聚集的旅行者。",al={"什么是安哈努的皮货","安哈努的皮货物品"}},["962e36b1"]={q="安哈努的皮货来自何处，又是谁制作的？",a="这些货物由安哈努准备，他是一位在雷霆崖高耸的平顶山上从事皮匠工艺的制皮师。他利用从贫瘠之地送来的生皮制作了这些成品。",al={"谁制作了安哈努的皮货","安哈努的皮货来源"}},["6d92aaf6"]={q="为什么会有人需要安哈努的皮货？",a="加翰·鹰翼订购了这批货物，以便卖给途经贫瘠之地的顾客。十字路口已经变成了一个充斥着漫游猎人和冒险者的繁忙枢纽，对优质、新鲜制作的皮革装备产生了热烈的需求。",al={"为什么运送安哈努的皮货","谁需要安哈努的皮货"}}},fp="21,147,22.360.0,37.138.0,25.152.0,41.276.0"}
P.entries["item:alaric-s-remains"] = {n="奥拉瑞克的遗骸",s="奥拉瑞克的骸骨躺在银松森林的一座浅坟里，远离芬里斯岛。他的灵魂请求旅人带着骸骨穿过腐皮豺狼人的地盘，直接进入芬里斯城堡。",h="奥拉瑞克的骸骨躺在银松森林的一座浅坟里，远离芬里斯岛。他的灵魂请求旅人带着骸骨穿过腐皮豺狼人的地盘，直接进入芬里斯城堡。",kw={"奥拉瑞克","奥拉瑞克的遗骸","芬里斯城堡","腐皮","浅坟","银松森林","隐蔽的壁龛","图勒·鸦爪"},ang={["class:Mage"]="身为法师，你或许能认出奥拉瑞克揭示的这批藏品与图勒·鸦爪有关，也与那些曾在芬里斯城堡中钻研和密谋、受训于达拉然的奥术师有关。",["race:Undead"]="身为被遗忘者旅人，你或许能理解一个死后安宁遭到打扰的灵魂。奥拉瑞克寻求的是安静独处，而非为黑暗女王效力。"},sec={{t="最后的请求",b="奥拉瑞克的骸骨从银松森林的一座浅坟中被挖了出来。他曾是芬里斯岛的居民，他的灵魂渴望回到生前珍爱的地方。他请求找到骸骨的人留下那双不合脚的靴子，将他的遗骸直接送进芬里斯城堡，远离在大陆上游荡的食腐者。"},{t="城堡中的壁龛",b="奥拉瑞克指引携带骸骨的人前往芬里斯城堡的西南塔楼，穿过遭到侵占的下层区域，进入一间安静的房间。一个落满灰尘的架子后面藏着一处暗龛，里面有一件图勒·鸦爪和他的法师同伴曾经珍视的宝物。为了答谢那些将他的骸骨送回家，让他得以远离腐皮豺狼人、安静长眠的人，奥拉瑞克将藏在那里的小饰物赠予他们。"}},faq={{q="奥拉瑞克生前是谁？",a="奥拉瑞克曾住在芬里斯城堡，他认为自己一生中最美好的时光就是在那里度过的。他死后被埋在银松森林的一座浅坟里，如今他的灵魂请求过路人将他的骸骨送回家。",al={"奥拉瑞克是谁","奥拉瑞克的故事","这人以前是谁"}},{q="奥拉瑞克的遗骸应该送到哪里？",a="奥拉瑞克的遗骸应安置在芬里斯岛上芬里斯城堡西南塔楼内，一处藏在积灰架子后面的壁龛中。",al={"奥拉瑞克送到哪里","积灰架子的位置","壁龛在哪里"}},{q="为什么奥拉瑞克想让自己的遗骸被封在架子后面？",a="芬里斯城堡曾让生前的奥拉瑞克感到安心，他希望在城堡的石墙内安息，而不是躺在土沟里。他还希望将壁龛封住，以免骸骨遭到在城堡中游荡的腐皮豺狼人的侵扰。",al={"为什么是芬里斯城堡","为什么是壁龛","为什么藏起尸体"}},{q="他为什么说要留下靴子？",a="奥拉瑞克说那双靴子在他生前就一直不合脚，所以他请求搬走浅坟中的骸骨时，将靴子留下。",al={"留下靴子","奥拉瑞克的靴子","靴子一直不合脚"}},{q="隐蔽的壁龛里除了安息之地，还有什么？",a="暗龛里存放着一件图勒·鸦爪及其昔日同伴曾经珍爱的物品，还有一些魔法物品，奥拉瑞克会将它们赠予任何将他的遗骸送去安葬的人。",al={"暗龛中的宝藏","架子后面有什么","图勒的物品"}}},fx={["7c652925"]={q="什么是奥拉瑞克的遗骸？",a="这是奥拉瑞克的骨骸和身体残余，他曾是芬里斯城堡的居民，死后被匆忙掩埋在银松森林。他徘徊的灵魂依然附着在骨头上保持着意识，敦促旅行者将他从泥土中挖掘出来，以便他能获得最终平静的安息之所。",al={"什么是奥拉瑞克的遗骸","奥拉瑞克的尸体","奥拉瑞克的遗骸物品"}},["6447c1c8"]={q="奥拉瑞克的遗骸来自哪里？",a="你从银松森林荒野中一个粗陋、浅显的坟墓里将它们挖掘出来，没包括他下葬时穿着的那双不合脚的靴子。奥拉瑞克死在远离他故居的荒野中，他那不得安息的遗骸被困在泥土中，直到被人挖掘出来。",al={"奥拉瑞克死在哪里","奥拉瑞克的浅坟","谁制造了奥拉瑞克的遗骸"}},["5f3dd52d"]={q="为什么奥拉瑞克希望找回他的遗骸？",a="奥拉瑞克在芬里斯城堡度过了他一生中最快乐的时光，在荒野中长眠让他无法安宁。他希望自己的遗骸能被带回城堡，安放在书架后面一个积满灰尘的隐蔽壁龛里，这样就可以避开在城堡领地上肆虐的烂皮豺狼人的搜刮。",al={"为什么要拿走奥拉瑞克的遗骸","为什么奥拉瑞克想移动他的遗体","为什么移动奥拉瑞克"}}},fp="16,168,15.298.0,22.360.1,15.210.0,42.123.0,55.211.0,41.133.0,57.177.0"}
P.entries["item:alien-egg"] = {n="异型卵",s="异型卵是一种奇特而神秘的卵，出现在千针石林各处的峡谷中，由当地的风蛇守护着。尽管它的外观陌生，当地的风蛇仍像守护自己的卵一样，拼死保护着它。它的出现引起了驻守乱风岗的牛头人斥候的好奇与担忧。",h="异型卵是一种奇特而神秘的卵，出现在千针石林各处的峡谷中，由当地的风蛇守护着。尽管它的外观陌生，当地的风蛇仍像守护自己的卵一样，拼死保护着它。它的出现引起了驻守乱风岗的牛头人斥候的好奇与担忧。",kw={"异型卵","乱风岗","哈加尔·雷蹄","千针石林","风蛇"},ang={["class:Hunter"]="风蛇是卡利姆多荒原上最受崇敬的野兽之一，要找到它们最稀有、守护最严密的卵之一，需要猎手施展全部的狩猎本能。",["race:Tauren"]="乱风岗的牛头人时刻警戒着下方的峡谷，将未知生物的出现视作一种征兆，或是对他们险踞崖边的聚落的直接威胁。"},sec={{t="风蛇的子嗣",b="异型卵出现在乱风岗以南和东北方的高耸石柱底部，与峡谷底部常见的野生生物截然不同。石林中的本地风蛇没有遗弃或毁掉这奇怪的卵，而是将它与自己的巢穴一同严密守护。哈加尔·雷蹄是一名从乱风岗高处守望四周的牛头人勇士，他希望取回这枚卵，查明它究竟会威胁台地上的聚落，还是仅仅为当地爬行动物的一种罕见变种。"},{t="阿利卡拉的子嗣",b="这枚神秘的卵被带到乱风岗接受进一步检查时，卵壳立刻破裂了。里面并非来自天外的入侵者：破壳而出的是阿利卡拉，牛头人传说中的红色风蛇，被认为是复仇之灵。幼蛇迅速腾空飞去，惊魂未定的哈加尔·雷蹄宣称，复仇本身已降临千针石林，由此引发了一连串事件，最终让当地的守卫与她正面交锋。"}},faq={{q="为什么这枚卵被称为“异型卵”？",a="这里的“异型”取的是完全外来、陌生的传统含义，表示当地牛头人斥候对它一无所知，并非暗示它来自外太空。它的颜色和斑纹与千针石林常见的风蛇卵全然不同。",al={"异型卵名称","为何称为异型","是否来自太空"}},{q="在哪里可以找到异型卵？",a="这枚卵位于千针石林的乱风岗以南和东北方，在峡谷底部靠近台地崖壁根部的地方。它周围总有怀有敌意的风蛇环绕守护。",al={"卵的位置","异型卵在哪里","寻找异型卵"}},{q="当地的风蛇为什么守护这枚卵？",a="没有人确切知道原因。风蛇像守护自己的卵一样守护着它，而那些声称见过它的人，甚至都没能靠近到足以检查它的距离。",al={"风蛇为何保护它","守护卵的风蛇"}},{q="把卵带给哈加尔·雷蹄后会发生什么？",a="这枚卵被送到乱风岗的哈加尔·雷蹄手中后，就在他眼前孵化了。从里面飞出的生物令哈加尔·雷蹄大为震惊，他立即派人向莫特加·火鬃寻求指点。",al={"向哈加尔·雷蹄交卵","孵出什么"}}},fx={["9259de71"]={q="什么是异型卵？",a="异型卵是人们在千针石林的野生风蛇群中发现的一窝不同寻常、神秘的卵。与该地区典型的蛇卵不同，它奇怪的外观引起了乱风岗的斥候和萨满的注意。尽管它来历不明，当地的风蛇却像保护自己的后代一样激烈地守护着它。",al={"什么是异型卵","异型卵信息","关于异型卵"}},e10e9f00={q="为什么哈加尔·雷蹄想要这枚异型卵？",a="乱风岗的哈加尔·雷蹄听说了关于一枚被当地风蛇守护的怪卵的传闻，他的斥候无法靠近进行研究。出于好奇和警惕，他请求勇敢的冒险者找回这枚蛋，以便他能亲自检查并弄清楚从中孵化出来的会是什么生物。",al={"为什么要找异型卵","为什么哈加尔想要那枚蛋","异型卵的用途"}}},fp="9,114,17.382.0,20.329.1,30.183.0,33.153.0,40.162.1,59.184.1"}
P.entries["item:alterac-granite"] = {n="奥特兰克花岗岩",s="在希尔斯布莱德丘陵北部的达隆山附近，奥特兰克花岗岩以其坚韧的质地和纹理吸引着石匠大师。国王麦格尼·铜须的御用石匠坚持用这种石料，向阵亡的士兵致敬。",h="在希尔斯布莱德丘陵北部的达隆山附近，奥特兰克花岗岩以其坚韧的质地和纹理吸引着石匠大师。国王麦格尼·铜须的御用石匠坚持用这种石料，向阵亡的士兵致敬。",kw={"奥特兰克花岗岩","达隆山","希尔斯布莱德","铁炉堡","马布里斯","苏利·巴鲁","萨多尔大桥"},ang={["profession:Mining"]="身为矿工或勘探者，你能看出奥特兰克花岗岩的断口齐整，密度非凡。这些特质使它有别于普通的山岩。",["race:Dwarf"]="身为矮人，你明白矮人石匠为何如此看重石料的品质。这种坚固的山石，是献给另一位铁炉堡之子的敬意。"},sec={{t="纪念碑之石",b="国王麦格尼·铜须下令为苏利·巴鲁建造一座纪念碑，这位英勇的矮人守卫在萨多尔大桥的惨剧中牺牲。大石匠玛布勒斯坦受命在铁炉堡雕刻这座纪念碑。他坚持使用奥特兰克花岗岩，而非普通的采石场石料。东部王国很少有石料能与之媲美，它坚固耐久，能让阵亡英雄的容貌与记忆历经数代而不朽。"},{t="险地采石",b="奥特兰克花岗岩分布在希尔斯布莱德丘陵北部的达隆山周围，靠近奥特兰克已成废墟的领地。凶猛的野兽、辛迪加匪徒和持续不断的纷争让这段旅途危机四伏。要将完好无瑕的石板带给铁炉堡的工匠，你必须深入各方争夺的土地。"}},faq={{q="奥特兰克花岗岩有什么用途？",a="铁炉堡的大石匠玛布勒斯坦请求提供奥特兰克花岗岩，用于王室为苏利·巴鲁建造的纪念碑，这位矮人士兵在保卫萨多尔大桥时牺牲。",al={"奥特兰克花岗岩用途","为何选用奥特兰克花岗岩","玛布勒斯坦石料"}},{q="在哪里能找到奥特兰克花岗岩？",a="你可以在希尔斯布莱德丘陵北部的达隆山采集奥特兰克花岗岩，那里的矿藏靠近奥特兰克边境。",al={"奥特兰克花岗岩位置","哪里获取奥特兰克花岗岩","达隆山花岗岩"}},{q="大石匠玛布勒斯坦为什么指定要这种石料？",a="大石匠玛布勒斯坦认为，奥特兰克花岗岩是能找到的最优质、最坚韧的雕刻石料之一。他认为，唯有这样的石料才配得上麦格尼国王委托建造、供后世瞻仰的王室纪念碑。",al={"玛布勒斯坦为何需要花岗岩","为何选用奥特兰克石料"}},{q="苏利·巴鲁是谁？",a="苏利·巴鲁是一名矮人士兵，在萨多尔大桥的战斗中阵亡。国王麦格尼·铜须下令建造一座纪念碑，以纪念他为联盟作出的牺牲。",al={"苏利·巴鲁","谁在萨多尔大桥牺牲"}}},fx={["9814170d"]={q="什么是奥特兰克花岗岩？",a="奥特兰克花岗岩是一种在北方丘陵发现的珍贵优质采石。它在石匠大师中享有盛誉，被认为是现存最好的雕刻石料之一，拥有打造值得皇家委托的史诗般、永恒纪念碑所需的耐久性和完美的纹理。",al={"什么是奥特兰克花岗岩","奥特兰克花岗岩物品","奥特兰克花岗岩信息"}},["842d3593"]={q="奥特兰克花岗岩来自何处，又是谁制作的？",a="奥特兰克花岗岩是从邻近奥特兰克崎岖山脉的希尔斯布莱德丘陵地区的达隆山开采出来的天然石料。它并非由工匠制造，而是直接从丘陵的古老岩石中开凿出来的，等待着熟练的石匠将其塑造成不朽的作品。",al={"奥特兰克花岗岩来源","奥特兰克花岗岩在哪里开采","谁制造了奥特兰克花岗岩"}}},fp="15,220,18.398.0,17.299.0,33.156.0,35.124.0,60.185.0,21.172.0"}
P.entries["item:altered-snapjaw-shell"] = {n="变异的钳嘴龟壳",s="甜水绿洲和死水绿洲的钳嘴龟长出了变异的龟壳，引起了一位德鲁伊的注意。它们的甲壳或许能揭示贫瘠之地下方的裂隙正如何影响当地的野生动物。",h="甜水绿洲和死水绿洲的钳嘴龟长出了变异的龟壳，引起了一位德鲁伊的注意。它们的甲壳或许能揭示贫瘠之地下方的裂隙正如何影响当地的野生动物。",kw={"变异的生物","变异的钳嘴龟壳","贫瘠之地","甜水绿洲","绿洲钳嘴龟","死水绿洲","图加·符文图腾"},ang={["class:Druid"]="身为德鲁伊，你可以研究绿洲野兽扭曲的甲壳，帮助查明扰乱贫瘠之地水域的隐秘失衡。"},sec={{t="腐化的迹象",b="绿洲鳄龟发生了一些变化，令研究这片土地的人感到不安。人们认为，甜水绿洲和死水绿洲的淡水龟饮用的泉水，来自神秘的地下裂隙。它们变异的甲壳引起了十字路口研究者的注意。牛头人德鲁伊图加·符文图腾正在收集这些龟壳，试图了解这片土地的健康状况。他想弄清楚，从地下深处涌出的能量究竟是一种非自然的枯萎之力，还是某种更为奇异的东西。"}},faq={{q="这些龟壳为什么会发生变异？",a="钳嘴龟生活在甜水绿洲和死水绿洲的泉水中，泉水来自地下深处的裂隙。涌入水中的奇异能量改变了在那里饮水的生物，使它们的甲壳明显扭曲变形。",al={"龟壳为什么变异","什么是变异的钳嘴龟壳","钳嘴龟壳变异"}},{q="谁需要这些龟壳，为什么？",a="十字路口的德鲁伊图加·符文图腾请猎手们收集这些龟壳。他相信，当地野兽的变化能够帮助查明，究竟是什么力量或腐化影响着贫瘠之地的水源。",al={"谁需要变异的钳嘴龟壳","图加·符文图腾龟壳","变异生物任务交付"}},{q="在哪里能找到这些钳嘴龟？",a="绿洲鳄龟栖息在甜水绿洲和死水绿洲的水中及泥泞的岸边，这两处绿洲分别位于十字路口的南方和东南方。",al={"绿洲钳嘴龟位置","哪里获得变异龟壳","钳嘴龟壳位置"}}},fx={["1549c45f"]={q="变异的钳嘴龟壳来自哪里？",a="这些龟壳属于栖息在贫瘠之地淡水泉周围的绿洲钳嘴龟，特别是滋水绿洲和死水绿洲。与普通的龟壳不同，它们之所以呈现出奇异的状态，是因为饮用了被绿洲下方神秘裂隙污染或赋予力量的水，从而导致生活在那里的生物发生了物理变异。",al={"变异的钳嘴龟壳来自哪里","变异的钳嘴龟壳来源","谁制造了变异的钳嘴龟壳"}}},fp="21,168,19.484.0,39.199.0,31.193.0,31.128.0"}
P.entries["item:ambercorn"] = {n="琥珀颗粒",s="在莫高雷各处，琥珀颗粒从古树上落下。牛头人收集它来酿制先知之水，这种饮剂用于幻象仪祭。",h="在莫高雷各处，琥珀颗粒从古树上落下。牛头人收集它来酿制先知之水，这种饮剂用于幻象仪祭。",kw={"安伯考恩","血蹄村","莫高雷","幻象仪祭","牛头人试炼","先知之水","扎尔曼·双月"},ang={["class:Shaman"]="身为萨满祭司，你敬重ambercorn这样的天然触媒。牛头人的传统认为，Earth Mother将灵性魔力赋予了她的树木与土壤孕育的收获。",["race:Tauren"]="身为年轻的牛头人，你学着辨认ambercorn，知道它是Rite of the Earth Mother所用的一种材料。这种饮剂有助于揭示你的灵魂之路。"},sec={{t="树冠的馈赠",b="琥珀颗粒落在莫高雷的大树下，牛头人从草丛中收集它。在牛头人看来，这些坚果蕴含着大地的灵性活力与潜藏的魔力。世世代代以来，牛头人的秘法师都深谙并运用着这股力量。年轻的猎人与旅者学着留意树冠下的地面，敬重大地母亲的馈赠。"},{t="先知的饮剂",b="在血蹄村，先知扎尔曼·双月用琥珀颗粒帮助年轻的牛头人为幻象仪祭做准备。他将它与从平原水井中收集的石头混合，制成先知之水。受试者在先祖的火焰前饮下这种仪式饮剂。他们的感知随之改变，一只指引他们的动物之灵显现出来，将带领他们前往下一个目的地。"}},faq={{q="什么是琥珀颗粒？",a="琥珀颗粒是一种坚果，从莫高雷高大的古树上落下。它蕴含着与大地之灵相连的自然魔力。",al={"琥珀颗粒","琥珀颗粒是什么"}},{q="哪里能找到琥珀颗粒？",a="琥珀颗粒散落在莫高雷巨树的树冠下，血蹄村周围尤其常见。",al={"琥珀颗粒位置","哪里能找到琥珀颗粒","如何获得琥珀颗粒"}},{q="琥珀颗粒有什么用途？",a="牛头人先知将琥珀颗粒与井石混合，酿制先知之水。受试者在幻象仪祭中饮下它，让灵魂向导显现。",al={"琥珀颗粒用途","琥珀颗粒有什么用"}},{q="血蹄村里谁需要琥珀颗粒？",a="在血蹄村，先知扎尔曼·双月让受试者收集琥珀颗粒，这是试炼的一部分，旨在证明他们与大地母亲的联系。",al={"谁需要琥珀颗粒","琥珀颗粒任务给予者"}}},fx={af22a474={q="琥珀颗粒来自何处，又是谁制作的？",a="琥珀颗粒并非凡人所造；它是生长在莫高雷平原上的巨树所结出的天然坚果或松果。牛头人将这些种子视为神圣大地的恩赐，其中蕴含着直接交织在这片土地上的魔法元素。",al={"琥珀颗粒来自哪里","琥珀颗粒来源","谁制造了琥珀颗粒","在哪里可以找到关于琥珀颗粒的传说"}},c9693aa2={q="为什么有人需要琥珀颗粒？",a="像扎尔曼·双月这样的牛头人萨满寻找琥珀颗粒是因为它所蕴含的潜在魔法属性。当它与神圣的井石结合并酿制成强大的先知之水时，它能在部落篝火前诱发精神恍惚，从而使年轻的牛头人获得完成神圣幻象仪式所需的幻象。",al={"为什么要用到琥珀颗粒","为什么要收集琥珀颗粒","谁需要琥珀颗粒","琥珀颗粒的用途"}}},fp="9,124,19.349.0,15.369.0,21.126.0,29.101.0,27.157.0,44.150.0"}
P.entries["item:amethyst-phial"] = {n="紫水晶瓶",s="科瑞萨斯·月怒在多兰纳尔将紫水晶瓶托付给旅人。他们带着瓶子前往神谕林地，采集神谕之树下方月亮井中的井水。",h="科瑞萨斯·月怒在多兰纳尔将紫水晶瓶托付给旅人。他们带着瓶子前往神谕林地，采集神谕之树下方月亮井中的井水。",kw={"紫水晶瓶","科瑞萨斯·月怒","大地之冠","多兰纳尔","月亮井","神谕林地","神谕之树","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你用瓶子监测世界之树的生命能量与逐渐蔓延的腐化。",["race:NightElf"]="身为 kaldorei，装满瓶子意味着承担一项庄严的职责，直面泰达希尔在未获祝福的情况下诞生所留下的缺陷。"},sec={{t="盛放圣水的容器",b="科瑞萨斯·月怒在泰达希尔将紫水晶瓶托付给旅人。这是大地之冠朝圣之旅中使用的最后一个容器。他们带着瓶子前往枝干的西北尽头，抵达神谕林地。神谕之树古老的树冠下，坐落着岛上第一座、也是力量最强的月亮井。将瓶子浸入泛着光辉的井水，便可汲取 艾露恩 恩典的精华。德鲁伊和女祭司用这些井水研究并照料生长状况难以预测的世界之树。"},{t="未获祝福的生长之重",b="泰达希尔在大德鲁伊范达尔·鹿盔的引领下长成，却未得到守护巨龙的祝福。他们认为此举出于傲慢，拒绝认可。因此，枝干遭受着令人不安的腐化，卡多雷 也依然是凡人。装满紫水晶瓶既是一项精神仪式，也是持续调查的一环。多兰纳尔的研究者仔细检验泰达希尔圣水的纯净程度。"}},faq={{q="紫水晶瓶有什么用途？",a="科瑞萨斯·月怒将瓶子交给旅人，让他们前往神谕林地，采集神谕之树下方泰达希尔第一座、也是力量最强的月亮井中的井水。",al={"紫水晶瓶用途","紫水晶瓶用来做什么","紫水晶瓶使用方法"}},{q="在哪里装满紫水晶瓶？",a="在多兰纳尔西北远处、达纳苏斯入口以北的神谕林地月亮井中装满瓶子。",al={"哪里装满紫水晶瓶","紫水晶瓶位置","神谕林地月亮井"}},{q="神谕林地的井水为何如此重要？",a="神谕之树下方的月亮井被认为是世界之树上第一座、也是力量最强的月亮井。井水蕴含着 艾露恩 的精华，能帮助研究者监测泰达希尔的精神与躯体状况。",al={"神谕林地井水为何重要","神谕之树 月亮井力量","神谕之井的意义"}},{q="是谁派你使用这个瓶子？",a="多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒将瓶子交给你，用于一项旨在了解泰达希尔生长异常的仪式。",al={"谁给予紫水晶瓶","科瑞萨斯·月怒的瓶子","谁需要紫水晶瓶"}}},fx={f821d918={q="什么是紫水晶瓶？",a="紫水晶瓶是泰达希尔给予旅行者的一种空仪式容器。它专为盛装纯净的附魔液体而打造，其用途是从古老的神谕之树下的月亮井中汲取并保存井水。",al={"紫水晶瓶","这个瓶子是什么"}},af37ef60={q="为什么科瑞萨斯·月怒想要装满紫水晶瓶？",a="科瑞萨斯·月怒寻求神谕林地中优质月亮井的水，以研究泰达希尔的奇怪状态。由于这棵伟大的世界之树缺乏巨龙军团的祝福，其生长过程依然存在缺陷且不可预测，这促使德鲁伊们对其最神圣的水域进行审视。",al={"为什么要装满紫水晶瓶","为什么科瑞萨斯想要这个瓶子","紫水晶瓶的用途"}}},fp="14,168,23.480.0,28.375.1,36.151.0,35.114.0,52.213.0,32.135.0"}
P.entries["item:an-undelivered-letter"] = {n="一封未寄出的信",s="闪金镇的狮王之傲旅店里，一封遗忘已久的信件藏着有关斯塔文·密斯特曼托过往的关键线索。",h="闪金镇的狮王之傲旅店里，一封遗忘已久的信件藏着有关斯塔文·密斯特曼托过往的关键线索。",kw={"运河区","信使","管理员弗索姆","闪金镇","狮王之傲旅店","密斯特曼托","斯塔文"},ang={["faction:Alliance"]="追寻信使那条被遗忘的路线，调查者会从田园风光中的闪金镇来到暴风城的富人区。"},sec={{t="午夜出逃",b="多年前，一场暴风雨让一名途经此地的信使来到狮王之傲旅店避雨。临近午夜，惊恐的信使穿着睡衣逃下楼，消失在倾盆大雨中，再也没有回来。他在二楼留下了一箱行李，其中有一封斯塔文·密斯特曼托写给暴风城运河区一处宅邸的信。"},{t="追寻学者的足迹",b="那封尚未拆封的信一直搁在旅店楼上的房间里，无人问津，直到如今有调查者开始沿着斯塔文在艾尔文森林留下的足迹追查。将这封遗失的信带给都城的管理员弗索姆，便会把这桩谜案从旅店寂静的厅堂引向暴风城的中心。"}},faq={{q="在哪里能找到这封未送达的信？",a="这封信放在闪金镇狮王之傲旅店二楼的一个储物箱里，箱子位于一间客房的床脚处。",al={"信在哪里","储物箱位置","狮王之傲箱子"}},{q="这封信为什么未能送达？",a="携带这封信的信使在一场暴风雨中来到狮王之傲旅店避雨。午夜前后，他惊慌失措，穿着睡衣跑下楼，消失在暴风雨中，留下了箱子和里面的物品。",al={"为何未送达","信使遭遇了什么","信使逃走"}},{q="这封信是谁写的？",a="这封信是斯塔文·密斯特曼托写的。他曾在旅店住过几个晚上，时间与那名受惊信使入住的时候相近。",al={"谁寄的信","斯塔文写信人","寄信人"}},{q="这封信原本要送到哪里？",a="这封信寄往暴风城的运河区。可以将它交给花园区附近的管理员弗索姆。",al={"谁收信","暴风城目的地","运河区信件"}}},fx={["72dbe9c7"]={q="什么是“一封未寄出的信”？",a="这是一封多年前由斯塔文·密斯曼德亲笔写下的被遗忘的信件。一名携带此信的信使在一个暴风雨之夜在闪金镇的狮王之傲旅店避雨，却在午夜时分因极度恐惧而逃入黑暗之中。这封信被遗留在信使的储物箱里，至今仍处于密封未读状态，其中隐藏着斯塔文过去的线索。",al={"什么是“一封未寄出的信”","“一封未寄出的信”物品","斯塔文的信"}},e9e7c880={q="为什么需要“一封未寄出的信”？",a="你需要它来揭开斯塔文·密斯曼德那段黑暗的历史。随着他在暮色森林和艾尔文森林的踪迹变得模糊，这封被遗忘的信件——收件人是暴风城运河区的一位居民——成为了拼凑他究竟是谁以及他结局如何的关键线索。",al={"为什么我需要这封未寄出的信","谁想要这封未寄出的信","“一封未寄出的信”的用途"}}},fp="21,104,17.359.0,19.256.1,38.126.0,35.227.0,22.123.0,35.117.0"}
P.entries["item:anaya-s-pendant"] = {n="安娜雅的坠饰",s="在亚米萨兰，安娜雅的坠饰仍由安娜雅·晨路不得安息的幽魂携带。塞瑞利恩·白爪始终为失去挚爱而悲伤，那场大灾变曾将他们的世界撕裂。",h="在亚米萨兰，安娜雅的坠饰仍由安娜雅·晨路不得安息的幽魂携带。塞瑞利恩·白爪始终为失去挚爱而悲伤，那场大灾变曾将他们的世界撕裂。",kw={"亚米萨兰","安娜雅·晨路","奥伯丁","塞瑞利恩·白爪","黑海岸","永志不渝","坠饰","永恒之井"},ang={["class:Druid"]="身为德鲁伊，你知道塞瑞利恩曾在尊师怒风身旁沉睡数千年，希望借此逃避悲伤，醒来后却发现幽魂仍在清醒的世界中徘徊。",["race:NightElf"]="身为暗夜精灵，你能从这枚坠饰中想起War of the Ancients，以及在大灾变中被拆散的无数生命与爱情。"},sec={{t="跨越万年的信物",b="一万年前，永恒之井被摧毁，古老的卡多雷城市亚米萨兰沦为废墟。塞瑞利恩·白爪以为挚爱的安娜雅已经死去，便带着悲伤，在尊师玛法里奥·怒风身旁陷入了漫长的沉睡。醒来后，他漫游黑海岸，发现安娜雅饱受折磨的幽魂仍带着坠饰，在亚米萨兰徘徊。塞瑞利恩无法亲手对她下手，于是请求旅人解放她的灵魂，并取回这件传家之物。"},{t="诀别与安息",b="在奥伯丁，塞瑞利恩接过坠饰，安娜雅·晨路的灵魂最后一次短暂地出现在他面前。痛苦曾将她束缚在亚米萨兰闹鬼的废墟中，如今摆脱了这份痛苦，她的幽魂安详地消逝在夜色里。只剩塞瑞利恩独自守着坠饰，以及那段古老爱情的回忆。"}},faq={{q="安娜雅的坠饰来自哪里？",a="安娜雅的坠饰来自安娜雅·晨路的幽魂，她在黑海岸南部的古老卡多雷遗迹亚米萨兰徘徊。",al={"安娜雅的坠饰获取地点","安娜雅的坠饰获取方法","安娜雅的坠饰掉落者"}},{q="谁想要安娜雅的坠饰？",a="塞瑞利恩·白爪想要安娜雅的坠饰。他是一位沉浸在悲伤中的暗夜精灵，住在黑海岸的海滨小镇奥伯丁。",al={"安娜雅的坠饰交给谁","塞瑞利恩·白爪任务","交还安娜雅的坠饰"}},{q="塞瑞利恩为什么无法亲自取回坠饰？",a="塞瑞利恩发现失去的爱人的灵魂在亚米萨兰徘徊，但即使经历了一万年的悲伤，他仍不忍亲手对她下手。",al={"塞瑞利恩为何没有杀死安娜雅","塞瑞利恩为何需要帮助"}},{q="将坠饰交还给塞瑞利恩后会发生什么？",a="当你在奥伯丁将坠饰交还给塞瑞利恩时，安娜雅的灵魂会短暂现身道别，随后消逝，归于安宁。塞瑞利恩则独自留下，在回忆中哀悼她。",al={"安娜雅的结局","塞瑞利恩的反应"}}},fx={["2379a09f"]={q="安娜雅的坠饰是什么？",a="安娜雅的坠饰是一件古老的纪念品，属于一位名叫安娜雅·黎行者的卡多雷。她在数千年前亚米萨兰毁灭时丧生。她的灵魂在废墟中徘徊，坠饰是她与塞瑞利恩·白爪在天崩地裂撕裂他们的世界之前那段美好往昔与永恒之爱的真切见证。",al={"安娜雅的坠饰是什么","安娜雅的坠饰背景故事","坠饰属于谁"}}},fp="15,186,27.493.0,17.305.1,37.133.0,26.116.0,52.153.0,54.165.1"}
P.entries["item:ancient-moonstone-seal"] = {n="远古月亮石封印",s="远古月亮石封印将阿斯特利安囚禁在巴莎兰的废墟中。它由上层精灵在大灾变发生很久以前铸造，以奥术魔法束缚着他的灵魂。",h="远古月亮石封印将阿斯特利安囚禁在巴莎兰的废墟中。它由上层精灵在大灾变发生很久以前铸造，以奥术魔法束缚着他的灵魂。",kw={"亚米萨兰","远古月亮石封印","阿斯特利安","埃瑟里克斯","巴莎兰","黑海岸","德斯利尔","上层精灵","月亮石"},ang={["class:Mage"]="对法师而言，这块月亮石展示了古代精灵的防护系魔法如何将束缚力场维持了一万多年。",["race:NightElf"]="对暗夜精灵而言，封印让人想起上层精灵的奥术力量，以及他们在大灾变之前残酷奴役他人的行径。"},sec={{t="上层精灵法术铸就的牢笼",b="远古月亮石封印将阿斯特利安的灵魂束缚在巴莎兰的石柱上。他昔日的主人、上层精灵巫师埃瑟里克斯·纳拉辛将它铸成了无法挣脱的锚，当时永恒之井尚存，艾萨拉女王仍在统治。一万多年过去了，阿斯特利安依然是一个受其魔法束缚的幽魂。他所掌握的力量和法术都无法破除这道结界。"},{t="在亚米萨兰摧毁封印",b="大灾变之后，封印落入了黑海岸周边荒野中的恶灵萨特手中。寻常力量无法损伤上层精灵施过魔法的石头。要摧毁这件遗物，就必须让它接触南方亚米萨兰双生废墟中依然燃烧的远古蓝色火焰。火焰会击碎埃瑟里克斯的束缚结界，让阿斯特利安的灵魂重获自由，进入凡人的世界。"}},faq={{q="远古月亮石封印是什么？",a="上层精灵巫师埃瑟里克斯·纳拉辛制造了远古月亮石封印，将阿斯特利安的幽魂束缚在他位于巴莎兰的神殿中。",al={"月亮石封印是什么","阿斯特利安的封印","巴莎兰封印"}},{q="封印被取回之前由谁持有？",a="在有人取回封印之前，它由巴莎兰周围废墟中的戴瑟雷萨特持有。封印的存在使这个萨特得以号令低等的劣魔仆从。",al={"谁持有封印","月亮石封印在哪里","谁掉落月亮石封印"}},{q="如何摧毁封印？",a="普通武器和当今的魔法都无法损伤封印。必须将它投入南方亚米萨兰双生废墟中依然燃烧的远古火焰。",al={"如何破除封印","摧毁月亮石封印","在哪里摧毁封印"}},{q="封印被摧毁后会发生什么？",a="亚米萨兰的火焰会摧毁封印，破除束缚阿斯特利安的魔法。被囚禁了数千年后，他的灵魂终于可以自由游荡于世间。",al={"破除封印有什么作用","阿斯特利安获释"}}},fx={bc236585={q="远古月亮石封印来自哪里，是谁制作的？",a="远古月亮石封印是在数千年前卡多雷帝国鼎盛时期，大分裂发生前制作的。它是由当时最强大的上层精灵领主之一——埃瑟里克斯·纳拉辛通过巫术锻造而成，用作一种神秘的束缚装置。",al={"谁制作了远古月亮石封印","远古月亮石封印起源","远古月亮石封印的创造者"}},a13d6402={q="为什么阿斯特利安想要远古月亮石封印？",a="阿斯特利安寻找这个封印，是因为它正是将他的灵魂禁锢在巴莎兰废墟神殿中的枷锁。只要封印保持完整，他就会被困在无形的牢笼之后，无法离开这座古老的监狱，也无法安息。通过取回封印，他希望能在亚米萨兰的远古烈焰中将其摧毁，从而最终获得自由。",al={"为什么阿斯特利安想要封印","为什么要寻找远古月亮石封印","谁想要远古月亮石封印"}}},fp="22,171,29.370.0,25.368.1,35.130.0,46.150.0,30.154.0,40.164.1"}
P.entries["item:ancient-statuette"] = {n="古代雕像",s="在灰谷西北部的海岸，塔尔伦正在寻找他从佐拉姆沉没的废墟中打捞出的古代雕像。这尊暗夜精灵雕像来自一座沉入海底的城市。",h="在灰谷西北部的海岸，塔尔伦正在寻找他从佐拉姆沉没的废墟中打捞出的古代雕像。这尊暗夜精灵雕像来自一座沉入海底的城市。",kw={"古代雕像","灰谷","娜迦","佐拉姆 废墟","雕像","塔尔伦","佐拉姆","佐拉姆海岸"},ang={["faction:Alliance"]="身为联盟的一员，你可以帮助塔尔伦记录并夺回暗夜精灵的文化遗产，抵御沿灰谷海岸步步侵入的娜迦。",["race:NightElf"]="身为暗夜精灵，你可以将这尊雕像视为大灾变之前 Kaldorei 文明的一块残片，它已在海底保存了数千年。"},sec={{t="浅滩中的遗物",b="佐拉姆沉没的废墟位于灰谷西北部近海。这座建于 大灾变 之前的暗夜精灵城市，在一万年前沉入了海底。最近，探险家塔尔伦乘着一艘小船勘察废墟，寻找历史遗物。娜迦袭击了他，将他逼上岸。逃跑时，他丢下了大部分随身物品，包括他打捞出的古代雕像。雕像就躺在他那艘凿沉的小船附近，位于潮水涨落处的沙地上。"},{t="佐拉姆的秘密",b="塔尔伦说，这尊雕像是他最珍视的物品，也是他冒险来到这片怪物横行的海岸的原因。他相信，这尊雕像能帮助解读佐拉姆的建筑、历史和奥术秘密，这一切都隐藏在佐拉姆海岸的波涛之下。"}},faq={{q="古代雕像是什么？",a="古代雕像来自佐拉姆沉没的废墟，那是一座位于灰谷西北部近海的古老暗夜精灵城市。",al={"雕像是什么","古代雕像背景故事","这件物品是什么"}},{q="谁在寻找这尊雕像？",a="暗夜精灵探险家塔尔伦正在寻找这尊雕像。他乘船勘察水下废墟时遭到娜迦袭击，逃跑时将这件遗物遗落在了海滩上。",al={"谁想要雕像","塔尔伦的雕像","谁丢失了雕像"}},{q="这尊雕像为何重要？",a="塔尔伦相信，这尊雕像能帮助揭开佐拉姆的历史，以及隐藏在海底废墟中的秘密。",al={"塔尔伦为什么想要它","雕像的用途"}},{q="为什么有娜迦在雕像的发现地附近游荡？",a="娜迦盘踞在佐拉姆海岸的近海水域和废墟中。任何地表居民胆敢靠近他们水下领地中沉没的遗迹，都会遭到攻击。",al={"海滩上为什么有娜迦","佐拉姆海岸的娜迦"}}},fp="17,177,23.445.0,16.254.0,30.100.0,33.154.0,31.116.0,48.154.0"}
P.entries["item:andron-s-ledger"] = {n="安德隆的账本",s="在幽暗城，安德隆·甘特的账本引起了亡灵哨兵的注意。他们正在寻找这本账本，而一名特工正为被遗忘者搜集情报。",h="在幽暗城，安德隆·甘特的账本引起了亡灵哨兵的注意。他们正在寻找这本账本，而一名特工正为被遗忘者搜集情报。",kw={"奥特兰克","安德隆·甘特","安德隆的账本","亡灵哨兵","米奈特·卡加德","潜行者区","辛迪加","瓦里玛萨斯"},ang={["class:Rogue"]="身为潜行者，取回并破译安德隆的账本证明了你的价值。米奈特·卡加德正式接纳你加入亡灵哨兵，瓦里玛萨斯也认可了你的工作。",["race:Undead"]="身为亡灵，你见识了被遗忘者如何搜集新领地周围威胁的情报。"},sec={{t="揭露辛迪加",b="安德隆·甘特在幽暗城的书架上放着一本账本，亡灵哨兵没料到会发现它。账本记载，辛迪加正在这一带暗中活动，这个组织由奥特兰克覆亡后的人类贵族残余组成。亡灵哨兵米奈特·卡加德立刻看出了它的价值：奥特兰克那些没落的领主又在策划阴谋。账本为被遗忘者的领袖提供了辛迪加开展行动的证据，超出了亡灵哨兵原先的预期。"},{t="交予恐惧魔王",b="米奈特·卡加德让持有账本的人直接前往皇家区，将账本交给瓦里玛萨斯，因为它涉及威胁被遗忘者领地的事。瓦里玛萨斯是希尔瓦娜斯·风行者麾下的恐惧魔王总管，通过亡灵哨兵掌管内部安全与谍报事务。他对这本账本给予嘉许，认可了亡灵哨兵情报网的能力，以及发现这份情报的特工的可靠。"}},faq={{q="安德隆的账本是什么？",a="安德隆的账本是一本来自安德隆·甘特在幽暗城的书架的记录簿，其中记载着亡灵哨兵寻求的情报。",al={"安德隆的账本","这是什么书","安德隆账本"}},{q="安德隆·甘特是谁？",a="安德隆·甘特是被遗忘者的一员，在幽暗城的炼金房附近经营一家商店。瓦里玛萨斯大人怀疑他在暗中协助一个外部组织，于是亡灵哨兵派出一名特工，冒充安德隆正在等候的信使去取得账本。",al={"安德隆是谁","安德隆·甘特"}},{q="亡灵哨兵为什么想要这本账本？",a="米奈特·卡加德想查看安德隆的资料，从中寻找对被遗忘者有用的情报。",al={"账本为何重要","亡灵哨兵为何想要账本"}},{q="谁会收到这本账本？",a="账本首先交给潜行者区的米奈特·卡加德。评估内容后，他指示持有账本的人将它直接送到黑暗女王大厅，交给瓦里玛萨斯大人。",al={"安德隆的账本交给谁","账本送给谁"}},{q="交付账本能为潜行者带来什么？",a="交付账本后，这名特工便能正式加入亡灵哨兵，这是被遗忘者的秘密刺客公会。",al={"亡灵哨兵入会","加入亡灵哨兵"}}},fx={["83ea0415"]={q="安德隆的账本来自哪里？",a="账本属于幽暗城的线人安德隆·甘特，他详细记录了自己的秘密交易。在被死亡猎手派出的特工取回之前，它一直放在他住处的书架上。",al={"谁制作了安德隆的账本","安德隆的账本起源","账本来自哪里"}},["45ae6031"]={q="为什么死亡猎手要安德隆的账本？",a="梅内特·卡卡德和死亡猎手寻找这本账本，是为了获取有关威胁被遗忘者的情报。梅内特在将账本送给瓦里玛萨斯领主之前，会先查阅其中的内容。",al={"为什么安德隆的账本遭到搜寻","谁想要安德隆的账本","为什么梅内特·卡卡德想要账本"}}},fp="15,146,24.415.1,26.382.1,24.125.0,19.246.0,41.92.0,24.188.0,52.123.0"}
P.entries["item:another-clue-to-sanders-treasure"] = {n="Another Clue to Sanders' Treasure",s="在西部荒野，杉德尔船长的一片羊皮纸指向了他藏匿的下一个标记。",h="在西部荒野，杉德尔船长的一片羊皮纸指向了他藏匿的下一个标记。",kw={"高崖","杉德尔船长","线索","羊皮纸","杉德尔的宝藏","西部荒野","风车"},ang={["class:Rogue"]="身为潜行者，你懂得如何解读隐晦的指引，在被遗忘的海边藏匿处搜寻暗藏的赃物。"},sec={{t="海边高崖上的踪迹",b="杉德尔船长把劫来的财宝分散藏在西部荒野各处，留下谜语和埋藏的标记，而非一张可能被夺走的完整地图。这片羊皮纸让寻宝线索从上一处藏匿地点继续延伸。上面写着，要转向北方，寻找海崖上方一座孤零零的风车旁被丢弃的水罐。"}},faq={{q="这条线索上写了什么？",a="羊皮纸上写着，要从藏起来的木桶处面向北方，径直走向海边高崖上一座孤零零的风车旁的空水罐。",al={"线索写了什么","杉德尔线索内容","线索上的指引"}},{q="杉德尔船长是谁？",a="杉德尔船长是一名海盗，曾在西部荒野的海岸和高崖沿途藏下多处赃物。他把标记藏在这片地区的各处，没有留下一张完整的地图。",al={"杉德尔是谁","杉德尔船长的背景","杉德尔西部荒野海盗"}},{q="这条线索接下来指向哪里？",a="线索沿着西部荒野的海崖向北，指向高崖上一座孤零零的风车，那里的空水罐标出了杉德尔寻宝路线的下一步。",al={"接下来去哪里","杉德尔风车线索","水罐在哪里"}}},fx={b0e51eff={q="\"杉德尔宝藏的另一个线索\"是什么？",a="这是一张手写的羊皮纸残片，是在西部荒野海岸的一个旧木桶里被发现的。纸上写着桑德斯船长留下的另一组航海方向，指引那些有胆量追寻他踪迹的人前往他留下的下一个隐藏宝藏。",al={"\"杉德尔宝藏的另一条线索\"是什么","桑德斯的线索羊皮纸","这张线索羊皮纸是什么"}},["37a7a825"]={q="这个线索来自哪里，是谁制作的？",a="该线索是由桑德斯船长书写并隐藏的，他是一位老水手，在西部荒野的海岸和乡村各地留下了一连串的线索。你从一个他很久以前藏匿它的废弃木桶中找回了这张羊皮纸残片。",al={"谁写了\"杉德尔宝藏的另一条线索\"","谁制作了桑德斯的线索","这条线索来自哪里"}},["632540c2"]={q="为什么有人会想要\"杉德尔宝藏的另一个线索\"？",a="沿着桑德斯的足迹是找到他埋藏的宝箱的唯一途径。每一条线索都以前一条为基础，提供了追踪这位船长在西部荒野各处行踪所需的准确地标，直至最终找到他藏匿的财宝。",al={"为什么要寻找桑德斯的线索","我为什么要桑德斯的宝藏线索","桑德斯的线索有什么用"}}},fp="33,88,29.292.0,29.131.0,24.163.0,31.145.0"}
P.entries["item:arikara-serpent-skin"] = {n="阿利卡拉蛇皮",s="阿利卡拉在黑云峰被召唤出来，随后遭到击杀，留下了一张覆满鳞片的皮。蛇皮被带到白沙岗哨，证明这条风蛇已被击败。",h="阿利卡拉在黑云峰被召唤出来，随后遭到击杀，留下了一张覆满鳞片的皮。蛇皮被带到白沙岗哨，证明这条风蛇已被击败。",kw={"阿利卡拉","凯恩·血蹄","黑云峰","火岩粉","莫特加·火鬃","蛇皮","白沙岗哨"},ang={["class:Shaman"]="身为萨满祭司，你知道将附魔的粉末撒入圣火，就能迫使先祖灵兽进入物质世界。",["race:Tauren"]="身为牛头人，你看出这张蛇皮象征着古老传说与现任领袖之间的冲突。玛加萨·野性图腾关于凯恩·血蹄的说法，让各个部族感到不安。"},sec={{t="召来怒灵的战利品",b="阿利卡拉是一条强大的风蛇，与牛头人的古老传说有关。传言说，随着牛头人的习俗发生变化，她开始寻求向凯恩·血蹄复仇。在长者玛加萨·野性图腾的指示下，勇士们备好了附魔的火岩粉。他们在黑云峰的墓葬崖顶点燃圣火，将这头灵兽引入物质世界。剥下阿利卡拉的皮，便得到了阿利卡拉蛇皮，作为她已死的证明。"},{t="令人不安的发现",b="在白沙岗哨，莫特加·火鬃收下了蛇皮，作为阿利卡拉已死的证明。玛加萨·野性图腾坚称，这条风蛇因先祖的愤怒而追杀凯恩·血蹄。然而，这头生物的死却让莫特加困惑不已：这样的灵兽为何会威胁他们的大酋长？蛇皮证明眼前的危险已经解除，但莫特加仍对玛加萨的解释心存疑虑。"}},faq={{q="阿利卡拉蛇皮是什么？",a="阿利卡拉蛇皮是从阿利卡拉身上剥下的鳞皮。这条传说中的风蛇在千针石林的黑云峰顶被召唤出来，随后遭到击败。",al={"蛇皮","阿利卡拉的皮","这张皮是什么"}},{q="谁想要阿利卡拉蛇皮？",a="白沙岗哨的莫特加·火鬃想要这张蛇皮和剩余的火岩粉，以此证明阿利卡拉已不再威胁任何人。",al={"谁收蛇皮","交给谁","谁要阿利卡拉的皮"}},{q="当初为什么要召唤阿利卡拉？",a="玛加萨·野性图腾声称，牛头人传统的变化激怒了先祖风蛇阿利卡拉，使她开始追踪大酋长凯恩·血蹄。她下令将这头野兽引出来，在凯恩受到伤害之前将其杀死。",al={"为何召唤阿利卡拉","为何杀死阿利卡拉"}},{q="从哪里能获得蛇皮？",a="在黑云峰内一座安葬死者的石峰上，将附魔的火岩粉撒入生命圣火，就能召唤阿利卡拉，随后便可从她身上取得蛇皮。",al={"哪里获得阿利卡拉蛇皮","阿利卡拉的位置"}}},fx={d099bc06={q="阿利卡拉蛇皮来自哪里？",a="这张皮是直接从阿利卡拉的尸体上剥下来的，这是一种在千针石林的黑云峰被召唤出来的邪恶风蛇之灵。玛加萨·野性图腾对火岩粉进行了附魔，当这种粉末撒在埋葬死者的生命圣火上时，就能召唤出阿利卡拉，以便将其击杀并剥下她的皮。",al={"阿利卡拉皮起源","阿利卡拉蛇皮来自哪里","阿利卡拉蛇皮的来源"}}},fp="20,140,26.387.0,22.344.1,33.152.0,35.128.0,44.209.0,31.148.0"}
P.entries["item:arnak-s-hoof"] = {n="阿纳克的蹄子",s="阿纳克的蹄子取自罪犯阿纳克·恐怖图腾，是他已死的骇人凭证。阿纳克杀害了一名牛头人同胞，又绑架了死者的妹妹，因此乱风岗的守卫下令将他处死，并在黑云峰的峭壁上追捕他。",h="阿纳克的蹄子取自罪犯阿纳克·恐怖图腾，是他已死的骇人凭证。阿纳克杀害了一名牛头人同胞，又绑架了死者的妹妹，因此乱风岗的守卫下令将他处死，并在黑云峰的峭壁上追捕他。",kw={"阿纳克","阿纳克·恐怖图腾","阿纳克的蹄子","峭壁卫兵图林·长角","黑云峰","乱风岗","拉克塔·风歌","千针石林"},ang={["faction:Horde"]="除掉阿纳克巩固了乱风岗在千针石林的权威，也削弱了背信弃义的恐怖图腾势力，后者正威胁着部落的补给路线。",["race:Tauren"]="对平原上的牛头人而言，取走阿纳克的蹄子，是以部族的正义惩处一名叛徒，他的杀戮行径给千针石林带来了耻辱与流血。"},sec={{t="放逐者的悬赏",b="阿纳克·恐怖图腾是个亡命之徒，在千针石林臭名昭著，其残暴行径甚至越过了牛头人氏族间纷争的底线。他杀害了另一名牛头人，并绑架了死者的妹妹拉克塔·风歌，随后便遭到正式悬赏，要求取其性命。阿纳克藏身于黑云峰的高处，周围有恐怖图腾守卫保护。将他杀死并带走砍下的蹄子，就能向乱风岗的峭壁卫兵图林·长角提供确凿的证明，表明这个凶手终于为自己的罪行付出了代价。"}},faq={{q="阿纳克的蹄子有什么用？",a="阿纳克的蹄子是亡命之徒阿纳克·恐怖图腾已死的实物凭证。将它交给乱风岗的峭壁卫兵图林·长角，即可完成悬赏通缉，领取承诺的奖赏。",al={"阿纳克的蹄子交付","阿纳克的蹄子用途","谁收阿纳克的蹄子"}},{q="阿纳克·恐怖图腾是谁？",a="阿纳克是恐怖图腾的一名叛徒，因谋杀和绑架而遭到通缉。他杀害了一名牛头人族人，并将死者的妹妹拉克塔·风歌囚禁在黑云峰的峭壁上。",al={"阿纳克是谁","阿纳克·恐怖图腾背景故事","阿纳克为何被通缉"}},{q="在哪里能找到阿纳克·恐怖图腾？",a="阿纳克位于千针石林北部黑云峰的悬崖上，沿着通往剃刀高地方向的嶙峋山岩附近的绳桥即可抵达。他将俘虏拉克塔·风歌关押在同一处峭壁上。",al={"阿纳克·恐怖图腾位置","阿纳克在哪里","如何找到阿纳克"}}},fx={["8804d903"]={q="阿纳克的蹄子是什么？",a="这只断蹄是亡命之徒牛头人阿纳克·野性图腾已被击杀的铁证。它直接取自千针石林风蚀台地上的尸体，被带回乱风岗以证明正义终究追上了这个被放逐的恶棍。",al={"阿纳克的蹄子","这是什么蹄子"}},a4f2e55c={q="阿纳克的蹄子来自哪里？",a="它取自阿纳克·野性图腾，一个潜伏在黑云峰附近悬崖上的叛徒牛头人。它不是锻造或制造出来的，而是在他俯瞰峡谷的藏身处与其对峙并将其击杀后获得的一件战利品。",al={"在哪能得到阿纳克的蹄子","阿纳克的蹄子来源","阿纳克的蹄子起源"}},ffececdb={q="为什么有人想要阿纳克的蹄子？",a="乱风岗的峭壁卫兵图林·长角发布了悬赏，要求提供阿纳克死亡的证明。阿纳克犯下了令人发指的罪行——杀害了一名无辜的牛头人并绑架了他的妹妹拉克塔·风歌。上交他的蹄子即完成了悬赏，并赢得了乱风岗守护者的感激与赏金。",al={"谁想要阿纳克的蹄子","为什么要上交阿纳克的蹄子","为什么要阿纳克的蹄子"}}},fp="12,191,20.484.0,30.175.0,24.192.0,31.198.0"}
P.entries["item:astor-s-letter-of-introduction"] = {n="阿斯托的介绍信",s="阿斯托·哈德恩携带着一封信，往返于银松森林与幽暗城之间。亡灵哨兵利用这封信冒充信使，调查涉嫌泄露被遗忘者情报的店主安德隆·甘特。",h="阿斯托·哈德恩携带着一封信，往返于银松森林与幽暗城之间。亡灵哨兵利用这封信冒充信使，调查涉嫌泄露被遗忘者情报的店主安德隆·甘特。",kw={"安德隆·甘特","炼金房","阿斯托·哈德恩","亡灵哨兵","米奈特·卡加德","银松森林","幽暗城","瓦里玛萨斯"},ang={["class:Rogue"]="作为被遗忘者盗贼，你可以在加入亡灵哨兵的实地考核中使用阿斯托的信。这项考核检验暗杀、偷窃和冒用身份的能力。",["race:Undead"]="作为亡灵，你可以从这场计谋中看出幽暗城内部的猜忌。瓦里玛萨斯大人利用亡灵哨兵，铲除被遗忘者内部的颠覆势力。"},sec={{t="信使的凭证",b="阿斯托·哈德恩在银松森林与幽暗城之间传递消息。他的介绍信能让持信人取得城中秘密联络人的信任。亡灵哨兵的负责人米奈特·卡加德需要调查幽暗城内可疑的泄密事件，而阿斯托的往来行踪使他成了目标。特工可以除掉阿斯托，夺取他的文书，再冒用他的身份，截取原本要交给他的秘密消息。"},{t="炼金房的诱捕行动",b="米奈特·卡加德用夺来的信欺骗安德隆·甘特，一位在炼金房附近经营店铺的店主。瓦里玛萨斯大人怀疑甘特向身份不明的第三方泄露被遗忘者的情报。一名卧底特工冒充约定的联络人，出示了这封信。甘特信任持信人，让特工有机会查明他的同谋是谁，并找到他叛变的证据。"}},faq={{q="阿斯托的介绍信有什么用途？",a="米奈特·卡加德用阿斯托的信欺骗店主安德隆·甘特。持信人冒充信使阿斯托·哈德恩，揭露甘特的秘密交易。",al={"信的用途","信有什么用","阿斯托的信的用途"}},{q="阿斯托·哈德恩是谁？",a="阿斯托·哈德恩是一名使者兼信使，沿着银松森林与幽暗城之间的道路传递私人信件。亡灵哨兵的特工截住了他。",al={"阿斯托是谁","阿斯托·哈德恩的故事","谁持有这封信"}},{q="米奈特·卡加德为什么想要这封信？",a="米奈特·卡加德需要这封信来考验想要加入亡灵哨兵的新兵，并对安德隆·甘特展开诱捕行动，瓦里玛萨斯大人怀疑此人有叛变之嫌。",al={"米奈特为什么需要这封信","卡加德的计划"}},{q="安德隆·甘特会怀疑这封信是偷来的吗？",a="不会。米奈特说甘特没有聪明到会怀疑其中有诈，而甘特也将持信人当成了同谋派来的惯常信使。",al={"甘特会察觉吗","安德隆会上当吗"}}},fx={da9b0b54={q="阿斯托的介绍信是什么？",a="这是阿斯托·哈德伦携带的证明文件，他是一位往返于银松森林和幽暗城之间的旅行信使。该文件表明持有人是安德隆·甘特的预期联络人，安德隆是一位涉嫌与不知名的外部势力勾结的幽暗城商人。",al={"阿斯托的信是什么","阿斯托的介绍信","这封信是什么"}}},fp="30,196,23.389.0,29.379.1,48.144.0,21.175.0,40.161.0,46.131.1"}
P.entries["item:ataeric-s-staff"] = {n="阿塔瑞克之杖",s="在瑟伯切尔，阿塔瑞克之杖标志着这位大法师的败亡。大法师阿塔瑞克是银松森林的一位达拉然资深法师，曾用这根法杖掌控当地的魔网。",h="在瑟伯切尔，阿塔瑞克之杖标志着这位大法师的败亡。大法师阿塔瑞克是银松森林的一位达拉然资深法师，曾用这根法杖掌控当地的魔网。",kw={"大法师阿塔瑞克","阿塔瑞克之杖","达拉然","魔网节点","瑟伯切尔","暗影牧师奥利斯特","银松森林","法师的头领"},ang={["class:Mage"]="身为法师，你能看出达拉然的大法师如何使用聚焦法器触及魔网节点，将其从沉寂中唤醒。",["race:Undead"]="对被遗忘者而言，夺回法杖可以遏制达拉然对银松森林魔法储备日益加深的控制，并巩固他们的西部边界。"},sec={{t="瑟伯切尔的战利品",b="暗影牧师奥利斯特忌惮达拉然日益扩张的魔法势力，下令杀死阿塔瑞克。他还要求夺取那根法杖。阿塔瑞克被杀、法杖被夺走后，汇聚的魔网能量再次陷入沉寂。将法杖带回瑟伯切尔，标志着对达拉然野心的一次明确胜利。然而，力量仍潜藏于大地之中，被遗忘者依然保持着警惕。"},{t="魔网之力的导体",b="大法师阿塔瑞克携带这根法杖，引导银松森林南部的魔网能量。达拉然派他前去唤醒其领地边界附近的一处古老魔网节点。这根法杖帮助他编织周围浩瀚的能量流，使这位大法师成为附近被遗忘者聚居地的重大威胁。"}},faq={{q="阿塔瑞克之杖属于谁？",a="这根法杖属于大法师阿塔瑞克，他是驻扎在银松森林的一位达拉然资深法师。他在那里负责监督唤醒一处强大的魔网节点。",al={"阿塔瑞克之杖属于谁","阿塔瑞克的法杖主人","谁掉落这根法杖"}},{q="暗影牧师奥利斯特为什么想要阿塔瑞克之杖？",a="瑟伯切尔的暗影牧师奥利斯特想用这根法杖证明大法师阿塔瑞克已死。他也想挫败达拉然掌控这一地区魔网的企图。",al={"奥利斯特为什么想要法杖","法杖在瑟伯切尔的用途","谁拿走法杖"}},{q="从大法师阿塔瑞克手中夺走法杖后，会发生什么？",a="阿塔瑞克被杀、法杖被夺走后，达拉然编织的魔网能量随之消散，陷入沉寂。被遗忘者眼前的魔法威胁就此解除。",al={"魔网会发生什么","击败阿塔瑞克之后"}},{q="在哪里能找到阿塔瑞克之杖？",a="大法师阿塔瑞克的尸体位于银松森林南部，达拉然势力所在之处附近，周围还有其他达拉然法师和守卫。法杖可以从他的尸体上取得。",al={"哪里获取阿塔瑞克之杖","阿塔瑞克的位置"}}},fp="15,152,23.378.0,22.298.1,35.152.1,53.171.0,59.162.1,31.160.0"}
P.entries["item:athrikus-narassin-s-head"] = {n="埃瑟里克斯·纳拉辛的头颅",s="在奥萨拉克斯之塔，埃瑟里克斯·纳拉辛的头颅证明了这名古老术士的死亡。这个邪教团体在黑海岸北部的恶魔活动已遭到破坏。",h="在奥萨拉克斯之塔，埃瑟里克斯·纳拉辛的头颅证明了这名古老术士的死亡。这个邪教团体在黑海岸北部的恶魔活动已遭到破坏。",kw={"奥萨拉克斯","埃瑟里克斯·纳拉辛","邪教徒","黑海岸","邪能","斩下的头颅","术士"},ang={["class:Warlock"]="身为术士，你知道埃瑟里克斯对邪能力量的掌控令他实力强大。他在奥萨拉克斯肆无忌惮地暴露行踪，最终招致了自己的覆灭。",["race:NightElf"]="身为暗夜精灵，你看到埃瑟里克斯·纳拉辛的死清除了卡利姆多北部海岸古老Kaldorei遗迹中的一股恶魔祸患。"},sec={{t="奥萨拉克斯的祸患",b="埃瑟里克斯·纳拉辛在奥萨拉克斯之塔指挥着一群黑暗巫师。这名古老的术士领导着一个邪教团体，在黑海岸沿岸施展邪能魔法，召唤恶魔，威胁着这片荒野。取下他的头颅，便能瓦解这个邪教团体的领导层，削弱其眼下在这一地区的势力，但腐化仍未消散，今后仍需保持警惕。"}},faq={{q="埃瑟里克斯·纳拉辛是谁？",a="埃瑟里克斯·纳拉辛是一名古老而强大的术士，领导着黑海岸北部奥萨拉克斯之塔内的邪教徒。他在塔顶指挥着这个邪教团体的恶魔仪式。",al={"埃瑟里克斯是谁","埃瑟里克斯的故事","术士是谁"}},{q="为什么需要他的头颅？",a="监视奥萨拉克斯之塔的联盟斥候需要证据，证明这名术士首领已经死亡。他被斩下的头颅证实了他的死讯，也证明了对恶魔势力的打击。",al={"为何取下头颅","埃瑟里克斯头颅的用途","头颅有何用途"}},{q="埃瑟里克斯·纳拉辛在哪里？",a="埃瑟里克斯·纳拉辛位于黑海岸北部的奥萨拉克斯之塔顶端，由忠于他的邪教徒和召唤出的恶魔守卫。",al={"哪里能找到埃瑟里克斯","埃瑟里克斯的位置","奥萨拉克斯之塔顶端"}},{q="杀死他能彻底消除恶魔的威胁吗？",a="埃瑟里克斯·纳拉辛的死重创了那些主持黑暗仪式的邪教徒，打乱了他们当前的行动，但恶魔势力可能重新集结。黑海岸仍需有人守卫。",al={"恶魔都消失了吗","高塔净化了吗","我们击败邪教了吗"}}},fx={["5ecacf9e"]={q="埃瑟里克斯·纳拉辛的头颅是什么？",a="这是埃瑟里克斯·纳拉辛被砍下的头颅，他是一位古老的暗夜精灵术士，指挥着奥萨拉克斯之塔内的黑暗势力。你以此作为当地邪教领袖已被击杀的不可辩驳的证据。",al={"埃瑟里克斯的头颅是什么","埃瑟里克斯·纳拉辛的头颅"}},["639f8902"]={q="埃瑟里克斯·纳拉辛的头颅来自哪里？",a="它直接取自黑海岸北部的奥萨拉克斯之塔顶端。埃瑟里克斯·纳拉辛盘踞在废墟结构的巅峰，周围环绕着他最危险的术士和邪能召唤爪牙，直到被击倒。",al={"埃瑟里克斯的头颅来自哪里","在哪能得到埃瑟里克斯的头颅","埃瑟里克斯的头颅来源"}}},fp="24,154,21.323.1,26.189.1,23.170.0,35.135.1,57.180.0"}
P.entries["item:bag-of-empty-ooze-containers"] = {n="一包空的软泥怪采样瓶",s="在铁炉堡，拉里斯·空轮提供空瓶，用于研究艾泽拉斯的软泥怪。他打算用这些瓶子盛装从野外采集的纯净软泥。",h="在铁炉堡，拉里斯·空轮提供空瓶，用于研究艾泽拉斯的软泥怪。他打算用这些瓶子盛装从野外采集的纯净软泥。",kw={"一包空的软泥怪采样瓶","空的纯净样本瓶","铁炉堡","拉里斯·空轮","软泥怪容器","纯净样本瓶","软泥"},ang={["faction:Alliance"]="身为联盟冒险者，你可以在铁炉堡协助拉里斯·空轮开展生态研究。从Un’Goro Crater这样的荒野之地带些实地采集的样本给他。",["race:Gnome"]="身为侏儒，你能看出这些耐用、耐化学腐蚀的瓶子所蕴含的巧思。它们让研究人员能够安全携带危险且具有腐蚀性的野生生物样本。"},sec={{t="野外研究设备",b="拉里斯·空轮研究艾泽拉斯软泥怪奇特的生理特征。他发现，它们很快就会受到周围腐化物质的影响，包括费伍德森林中受污染的残留物。因此，他委托制作了一批结实的瓶子，能够容纳酸性样本而不损伤样本。包里的瓶子足够用来在荒野地区采集纯净软泥，尤其是安戈洛环形山，那里古老黏稠的软泥怪未受恶魔污染。"}},faq={{q="一包空的软泥怪采样瓶里装着什么？",a="包里装着十个空的纯净样本瓶。这些玻璃瓶能够容纳具有腐蚀性的软泥，而不会损坏或污染样本。",al={"包里有什么","包内物品","软泥怪容器内的物品"}},{q="这些容器是谁提供的？",a="这些容器由拉里斯·空轮提供，他是铁炉堡探险者大厅的一名侏儒研究员。他研究软泥怪如何适应周围环境。",al={"谁提供软泥怪采样包","拉里斯·空轮的包","谁提供一包空的软泥怪采样瓶"}},{q="这些瓶子是用来采集哪种软泥怪的？",a="这些瓶子用来采集纯净、未受腐化的软泥。安戈洛环形山的黏稠软泥怪能提供纯净的软泥，与费伍德森林那些受污染的样本不同。",al={"瓶里装哪种软泥","纯净样本瓶采集目标","在哪里装满瓶子"}},{q="拉里斯为什么需要纯净的软泥样本？",a="拉里斯需要纯净的软泥，来研究软泥怪如何吸收周围环境中的特性。他可以将未受腐化的样本与来自受污染地区的软泥进行比较。",al={"为什么采集纯净软泥","空轮的研究目的","为什么需要纯净软泥怪"}}},fx={["9a2213f5"]={q="一包空的软泥怪采样瓶是什么？",a="这个袋子是一套专门的野外装备，由铁炉堡的拉里斯·空轮提供给你。里面有十个空的样品瓶，旨在安全地盛放和运输不稳定的软泥怪标本回他的工作室，而不会泄漏或污染其中的内容物。",al={"一包空的软泥怪采样瓶","什么是软泥怪采样瓶","拉里斯的软泥怪袋子"}}},fp="28,142,24.407.0,48.119.0,30.148.0,51.161.0,38.165.0"}
P.entries["item:balnir-snapdragons"] = {n="巴尼尔金鱼草",s="在巴尼尔农场，鲜艳的金鱼草依然生长，而天灾军团的腐化正向提瑞斯法林地逼近。被遗忘者研究这些花对魔法的敏感反应，以监测腐化的蔓延。",h="在巴尼尔农场，鲜艳的金鱼草依然生长，而天灾军团的腐化正向提瑞斯法林地逼近。被遗忘者研究这些花对魔法的敏感反应，以监测腐化的蔓延。",kw={"安娜斯塔西娅·哈特威尔","巴尼尔农场","巴尼尔金鱼草","法师区","瘟疫之地","提瑞斯法林地"},ang={["class:Mage"]="身为被遗忘者法师，你可以将巴尼尔金鱼草作为魔法导体来研究。它们的敏感反应有助于测定魔法疫病如何扭曲周围的魔网能量线。",["race:Undead"]="身为被遗忘者，你可以利用这些花监测你们的东部边界。如果巫妖王的腐化正在侵吞提瑞斯法的土壤，花朵的读数就能向幽暗城的研究人员发出警报。"},sec={{t="废墟中的花朵",b="巴尼尔金鱼草依然盛开在提瑞斯法林地东部的巴尼尔农场花园中。洛丹伦陷落、天灾军团崛起后，这座农庄已沦为废墟。瘟疫之地与提瑞斯法东部接壤，而花园正处于巫妖王的疫病侵逼这片地区的地方。这里的花朵让被遗忘者得以监测腐化的蔓延。"},{t="魔法晴雨表",b="巴尼尔金鱼草对大气中的魔法异常敏感，因而成了监测魔法疫病的活体晴雨表。安娜斯塔西娅·哈特威尔和幽暗城的被遗忘者法师需要采自农庄窗台花箱的新鲜花朵。他们将这些植物送交皇家药剂师学会研究，希望测出巫妖王的瘟疫越过边界、渗入提瑞斯法土壤的范围。"}},faq={{q="在哪里可以找到巴尼尔金鱼草？",a="巴尼尔金鱼草生长在巴尼尔农场废墟周围的花箱和花坛中，那里位于提瑞斯法林地东部，靠近西瘟疫之地。",al={"巴尼尔金鱼草位置","花在哪里","巴尼尔花朵位置"}},{q="安娜斯塔西娅·哈特威尔为什么需要这些金鱼草？",a="安娜斯塔西娅·哈特威尔希望将新鲜的金鱼草送交幽暗城的药剂师。这些花对潜藏魔法能量的敏感反应，有助于测定瘟疫之地的污染是否正在向提瑞斯法林地蔓延。",al={"为何采集金鱼草","巴尼尔农场任务目标","安娜斯塔西娅·哈特威尔金鱼草"}},{q="最初是谁种下了这些花？",a="巴尼尔金鱼草生长在巴尼尔农场的花园中，并以这座家族农庄命名。天灾军团摧毁了这座农场，洛丹伦其余的乡间地区也未能幸免。",al={"谁种下了巴尼尔金鱼草","巴尼尔家族金鱼草"}},{q="天灾军团摧毁了巴尼尔的花朵吗？",a="没有。金鱼草依然生长在巴尼尔农场的花园中。它们生长的地方离瘟疫之地如此之近，让安娜斯塔西娅·哈特威尔的研究人员得以研究瘟疫是否已进入提瑞斯法林地。",al={"瘟疫是否杀死了金鱼草"}}},fx={ebe2752a={q="巴尼尔金鱼草是什么？",a="巴尼尔金鱼草是一种独特的花卉，种植在提瑞斯法林地东部的巴尼尔农场的花箱里。它们天生敏感且对魔法能量异常容易接受，能够吸收周围潜伏的魔法流，这使它们成为探测附近环境腐化程度的主要指示物。",al={"什么是巴尼尔金鱼草","巴尼尔金鱼草花","巴尼尔金鱼草背景故事"}}},fp="18,185,15.327.0,18.391.0,38.148.0,51.202.0,34.183.0,43.194.0"}
P.entries["item:baron-longshore-s-head"] = {n="巴隆·朗绍尔的头颅",s="在商旅海岸，巴隆·朗绍尔的头颅是这位海盗船长已死的证明。加兹鲁维发布了公开悬赏，索要能够确认长滩身份的遗骸，以保护棘齿城的商船运输。",h="在商旅海岸，巴隆·朗绍尔的头颅是这位海盗船长已死的证明。加兹鲁维发布了公开悬赏，索要能够确认长滩身份的遗骸，以保护棘齿城的商船运输。",kw={"巴隆·朗绍尔","悬赏","加兹鲁维","吉尔尼斯","鲁莽","商旅海岸","棘齿城","南海海盗"},ang={["race:Human"]="身为人类，你可以追溯到巴隆·朗绍尔出身于吉尔尼斯，他在加入南海海盗之前便离开了这个闭关锁国的国家。"},sec={{t="海盗的悬赏",b="巴隆·朗绍尔以棘齿城以南商旅海岸沿线的营地为据点，率领南海劫掠者发动劫掠。他的旗舰鲁莽号威胁着卡利姆多与东部王国之间的地精贸易航线。棘齿城的首席工程师加兹鲁维悬赏征集能够确认长滩已死的证据。将这名海盗的头颅交来后，港务当局便会支付赏金。"}},faq={{q="巴隆·朗绍尔是谁？",a="巴隆·朗绍尔是一名来自人类王国吉尔尼斯的海盗船长。他以棘齿城以南商旅海岸沿线的营地为据点，率领南海海盗，驾驶鲁莽号肆虐于航线之上。",al={"巴隆·朗绍尔","长滩是谁","长滩船长"}},{q="谁想要巴隆·朗绍尔的头颅？",a="棘齿城的地精领袖加兹鲁维发布了公开悬赏，索要能够确认巴隆·朗绍尔身份的遗骸。南海海盗劫掠棘齿城的商船，而加兹鲁维希望港口的贸易不受干扰。",al={"谁要头颅","交给谁","加兹鲁维悬赏"}},{q="在哪里能找到巴隆·朗绍尔？",a="巴隆·朗绍尔在棘齿城以南海岸线上的三处南海海盗营地之间巡逻，就在商旅海岸沿线、北方城堡以北不远处。",al={"长滩在哪","长滩位置","巴隆·朗绍尔刷新"}},{q="巴隆·朗绍尔指挥的是哪艘船？",a="巴隆·朗绍尔是鲁莽号的船长，这艘船在贫瘠之地沿岸外的无尽之海劫掠商船。",al={"长滩的船","鲁莽号","鲁莽号船"}}},fx={["0986c9c0"]={q="巴隆·朗绍尔的头颅是什么？",a="这是巴隆·朗绍尔那颗可怕的断头，他是一位来自吉尔尼斯的臭名昭著的海盗船长，指挥着南海海盗的船只。你将其作为他死亡的铁证，以完成在棘齿城发布的针对他的悬赏，确保热砂港知道这位臭名昭著的劫掠者将不再困扰他们的商运航线。",al={"巴隆·朗绍尔的头颅物品","这是什么头颅","朗绍尔的头颅背景故事"}}},fp="22,174,22.367.0,24.204.0,33.226.0,31.148.0,38.107.0"}
P.entries["item:barrel-of-barleybrew-scalder"] = {n="一大桶热麦酒",s="在卡拉诺斯，马莱斯·麦酒将一桶热酒送往雷酒酿制厂。他要证明，自己的酿酒技艺足以媲美头号对手雷酒家族。",h="在卡拉诺斯，马莱斯·麦酒将一桶热酒送往雷酒酿制厂。他要证明，自己的酿酒技艺足以媲美头号对手雷酒家族。",kw={"麦酒","酿酒厂","丹莫罗","卡拉诺斯","马莱斯","热麦酒","雷酒"},ang={["class:Rogue"]="身为潜行者，你可以引开酒窖守卫的注意，将沉重的违禁品偷偷塞进有人看守的储藏处。在这里，你能体验一回矮人的暗中较量，倒也没什么重大风险。",["race:Dwarf"]="身为矮人，你知道酿造麦酒既是一门艺术，也是一场血腥的竞技。丹莫罗围绕酿酒配方的争斗，一直延伸到了酒窖深处。"},sec={{t="丹莫罗的激烈宿怨",b="雷酒家族与麦酒在丹莫罗的酿酒业中争斗激烈。雷酒家族以他们在卡拉诺斯那座繁忙的酿酒厂闻名。马莱斯·麦酒不愿活在他们的阴影下。于是，他酿出了辛烈的热麦酒，要证明自己的配方足以与他们抗衡。他希望尝过这酒的人都能明白，酿造矮人佳酿的技艺并非雷酒家族独有。"},{t="酒窖里的暗招",b="这桶酒将被送往雷酒酿制厂地下的酒窖。在那里，它会替换掉一桶深受当地人喜爱的雷霆麦酒。受挫的自尊催生了一场恶作剧，并非下毒或破坏。楼上接下来端出的酒，将被悄悄换成麦酒的烈酒热麦酒。"}},faq={{q="一大桶热麦酒里装的是什么？",a="桶里装的是马莱斯·麦酒的招牌酒热麦酒，这种矮人烈酒是为挑战雷酒家族的著名配方而酿造的。",al={"热麦酒内容物","什么麦酒","热麦酒是什么"}},{q="马莱斯为什么要调换这桶酒？",a="马莱斯承认雷酒家族酿的酒不错，但他想让他们学会谦逊。他希望酒窖里的客人在不知情的情况下尝到他的酒，发现麦酒的手艺即便不更胜一筹，也毫不逊色。",al={"为何调换酒桶","激烈竞争的缘由","马莱斯为何偷换酒"}},{q="这桶酒要送到哪里？",a="这桶酒要送进卡拉诺斯的雷酒酿制厂地下的酒窖。它会替换酒架上一桶即将开桶的雷霆麦酒。",al={"酒桶放在哪里","热麦酒酒桶位置","酿酒厂酒窖"}},{q="这酒是用来害人的吗？",a="不是。这是一种烈性矮人麦酒，酿来是为了与雷酒家族的酒一较高下。两个家族的竞争虽然激烈，却源于对自身手艺的自豪，而非恶意。",al={"热麦酒是否有毒","是否是毒药","是否会伤人"}}},fx={["9f414f7e"]={q="一大桶热麦酒是什么？",a="这是一桶由马莱斯·麦酒酿造的烈性麦酒。这桶酒并非通过常规贸易出售，而是作为酿酒竞争中的一种手段，意在秘密替换竞争对手的库存，以赢得不知情的饮用者的青睐。",al={"什么是热麦酒","热麦酒木桶","一大桶热麦酒"}},["00d1bcdd"]={q="一大桶热麦酒来自哪里，是谁制作的？",a="这桶酒是由马莱斯·麦酒酿造并提供的。作为对家族技艺的自豪，马莱斯调制了这个配方，旨在证明麦酒家族能够匹敌甚至超越竞争对手雷酒家族的声望。",al={"谁制作了热麦酒","热麦酒来自哪里","热麦酒起源"}}},fp="28,171,27.356.0,24.282.1,48.132.0,42.212.0,26.154.0,33.153.0"}
P.entries["item:barrel-of-shimmer-stout"] = {n="一大桶微光酒",s="在丹莫罗，一桶微光酒即将送往山中的哨岗。雷杰德·麦酒把自己试酿的艾尔酒送往高山隘口，喝过的人说这酒能让视野更明亮。",h="在丹莫罗，一桶微光酒即将送往山中的哨岗。雷杰德·麦酒把自己试酿的艾尔酒送往高山隘口，喝过的人说这酒能让视野更明亮。",kw={"一大桶微光酒","丹莫罗","矮人艾尔酒","洛克莫丹","巡山人维拉特·麦酒","雷杰德·麦酒","微光酒"},ang={["profession:Cooking"]="身为厨师，你知道矮人酿酒师会尝试用耐寒的山地食材和强劲的发酵工艺酿酒。他们酿造的艾尔酒，是为了抵御刺骨的寒冷。",["race:Dwarf"]="身为矮人，你知道酿酒是铁炉堡社会的一大基石。把刚刚酿制完善的烈性黑啤酒送给站岗的亲族，是山中一项光荣的传统。"},sec={{t="酿酒师的骄傲",b="雷杰德·麦酒用从丹莫罗各地采集的原料酿出了微光酒。这份配方是麦酒家族的最新成果。家族中的矮人酿酒师竞相酿造醇厚的艾尔酒，以抵御山间的严寒。雷杰德酿造这种烈性黑啤酒，是为了给那些在寒风中站岗的人暖暖肚子，让他们的感官更敏锐。"},{t="哨岗的补给",b="这桶酒要送给巡山人维拉特麦酒，他驻守在通往洛克莫丹的隘口南侧哨塔。那里的巡山人要忍受严寒，长时间站岗，还要不时与穴居人和野兽交战。一桶家族酿制的艾尔酒，能带来家乡的滋味。它的酒劲能让疲惫的哨兵觉得自己在黑暗中也能看得清楚。"}},faq={{q="一大桶微光酒里装的是什么？",a="桶里装的是微光酒，一种由雷杰德·麦酒试酿的矮人艾尔酒。喝过的人说，强烈的酒劲能让视野更明亮。",al={"微光酒是什么","这是什么艾尔酒","微光酒"}},{q="这桶烈性黑啤酒是谁酿的？",a="这酒是雷杰德·麦酒酿的。他来自丹莫罗的麦酒家族，花了不少时间完善配方，希望让族人刮目相看。",al={"谁酿造了微光酒","微光酒酿酒师","雷杰德·麦酒"}},{q="这桶酒是送给谁的？",a="这桶酒是送给雷杰德的兄弟，巡山人维拉特麦酒的。维拉特守卫着通往洛克莫丹道路上的南侧哨塔。",al={"这桶酒送给谁","这酒送往哪里","维拉特·麦酒"}},{q="喝下微光酒会有什么效果？",a="微光酒会带来强烈的醉意，让喝下它的人觉得自己在漆黑中也能看清东西。这股酒劲让它颇受时刻保持警惕的巡山人欢迎。",al={"微光酒效果","能让人在黑暗中看清吗","微光酒有什么作用"}}},fp="23,184,16.304.0,22.318.0,39.141.0,30.142.0,29.136.0,61.155.0"}
P.entries["item:barrel-of-thunder-ale"] = {n="一大桶雷霆麦酒",s="卡拉诺斯的雷酒酿制厂丢失了一桶雷霆麦酒。马莱斯原本打算用自己的热麦酒将它替换，让酿酒世家的宿怨变成了一场暗中破坏。",h="卡拉诺斯的雷酒酿制厂丢失了一桶雷霆麦酒。马莱斯原本打算用自己的热麦酒将它替换，让酿酒世家的宿怨变成了一场暗中破坏。",kw={"一大桶雷霆麦酒","烈酒村","丹莫罗","卡拉诺斯","马莱斯·麦酒","雷霆麦酒","雷酒"},ang={["class:Rogue"]="身为潜行者，你看得出，要潜入有人看守的地窖，调换沉重的麦酒桶而不惊动守卫，需要怎样的身手。",["race:Dwarf"]="身为矮人，你知道酿酒在商业和政治中都举足轻重。在对手氏族自己的地窖里调换他们引以为傲的酒桶，是一种肆无忌惮的侮辱。"},sec={{t="苦涩的交易",b="卡拉诺斯的雷酒家族与烈酒村的麦酒家族是宿敌。马莱斯·麦酒试图将一桶自己的热麦酒偷偷放进雷酒家族的地窖。他希望他们的顾客会选择自己酿的酒。那桶雷霆麦酒在调包时被取走，证明即使有当地卫兵看守，调包仍然成功了。"}},faq={{q="这桶里装的是什么？",a="桶里装的是雷霆麦酒，是雷酒家族在卡拉诺斯酿造的著名烈性黑啤酒。在整个丹莫罗，这种矮人麦酒都以酒劲猛烈而闻名。",al={"雷霆麦酒桶内物品","雷霆麦酒是什么"}},{q="这桶酒从哪里来？",a="这桶酒原本存放在卡拉诺斯酿酒厂的地窖里。有人在秘密送入马莱斯用来与之竞争的酒时，将它取走了。",al={"哪里获取","雷霆麦酒位置"}},{q="谁想要这桶酒？",a="马莱斯·麦酒想要这桶酒。他在西边的烈酒村，等着用它证明自己的热麦酒已经混进雷酒家族的酒桶之中。",al={"雷霆麦酒交给谁","马莱斯·麦酒任务"}},{q="为什么要取走这桶酒？",a="马莱斯想要证据，证明有人潜入雷酒家族的地窖，避过酿酒厂的守卫，破坏了对手的存酒。",al={"为什么偷雷霆麦酒","宿敌的故事"}}},fp="21,170,14.341.0,27.148.0,32.132.0,22.160.0,25.134.0"}
P.entries["item:barrow-key"] = {n="古墓钥匙",s="石爪峰地下深处，古墓钥匙被锁在猛禽洞穴中。它是三把德鲁伊钥匙之一，守护着封存在洞穴宝库中的古老珍宝。",h="石爪峰地下深处，古墓钥匙被锁在猛禽洞穴中。它是三把德鲁伊钥匙之一，守护着封存在洞穴宝库中的古老珍宝。",kw={"古墓钥匙","利爪钥匙","守门人的钥匙","沉睡者的钥匙","石爪峰","猛禽洞穴","猛禽洞穴储藏室","大兽穴"},ang={["class:Druid"]="身为德鲁伊，你知道古墓钥匙是一项古老防护仪式的一部分。猛禽洞穴的德鲁伊设计了这项仪式，用来保护地下圣所中的神圣物品。",["faction:Horde"]="石爪山脉的部落密探从被俘的暗夜精灵口中逼问信息，试图找到古墓钥匙，洗劫德鲁伊的私人宝库。"},sec={{t="守护者的防护",b="暗夜精灵德鲁伊在猛禽洞穴的地下墓穴中布下重重结界，保护他们的圣物免遭入侵者侵扰。古墓钥匙藏在通道间的一处秘藏中，也是这层层防御的一部分。只有守门人的钥匙才能打开这处秘藏，因此，寻宝者必须了解德鲁伊的防御布置，才能取得古墓钥匙。"},{t="开启宝库",b="猛禽洞穴深处的一座石制祭坛上，刻有三个钥匙孔，分别对应古墓钥匙、利爪钥匙和沉睡者的钥匙。同时转动这三把钥匙，防护魔法便会消散。届时，隐藏宝库中的德鲁伊圣物便唾手可得。"}},faq={{q="古墓钥匙有什么用途？",a="古墓钥匙与利爪钥匙、沉睡者的钥匙配合使用，可以打开猛禽洞穴储藏室，那是石爪峰深处的一口石箱，里面存放着受到保护的德鲁伊圣物。",al={"古墓钥匙用途","古墓钥匙能打开什么","古墓钥匙的用处"}},{q="古墓钥匙藏在哪里？",a="古墓钥匙被锁在石爪峰猛禽洞穴蜿蜒隧道深处的一处墓穴秘藏中。这处秘藏外形像一支隐蔽的壁上火把。",al={"古墓钥匙位置","古墓钥匙在哪里","寻找古墓钥匙"}},{q="如何打开存放古墓钥匙的秘藏？",a="你需要守门人的钥匙才能打开这处秘藏。德鲁伊将它藏在猛禽洞穴主入口附近的一盏小提灯中。",al={"打开墓穴秘藏","解锁古墓钥匙","守门人的钥匙 墓穴"}},{q="是谁将古墓钥匙藏在猛禽洞穴中的？",a="居住在石爪峰的暗夜精灵德鲁伊为洞穴设计了严密的防御，以免他们强大的神器落入敌手。他们将钥匙分别藏在洞穴的不同地方。",al={"谁制作了古墓钥匙","谁把钥匙藏在猛禽洞穴"}}},fx={["6b9fc30c"]={q="古墓钥匙是什么？",a="古墓钥匙是石爪峰顶猛禽洞穴中的暗夜精灵德鲁伊所制作的三把附魔钥匙之一。它是复杂安保结界的一部分，旨在保护他们最珍贵和强大的遗物不落入敌手。",al={"古墓钥匙是什么","古墓钥匙信息","猛禽洞穴古墓钥匙"}},["17616df0"]={q="为什么有人想要古墓钥匙？",a="石爪山脉的部落势力正在寻找古墓钥匙，以及它的同系钥匙：利爪钥匙和沉睡者的钥匙。这三把钥匙合在一起可以破解封印猛禽洞穴宝库的德鲁伊结界，打开古墓深处封存的强大物品的宝库。",al={"为什么要找古墓钥匙","为什么想要古墓钥匙","谁想要古墓钥匙"}}},fp="10,128,22.337.0,19.242.1,32.165.0,31.150.0,52.121.0,43.183.0"}
P.entries["item:bartleby-s-mug"] = {n="巴特莱比的酒杯",s="在暴风城，伯加德要求一名年轻战士从顽固的主人手中赢得巴特莱比的酒杯。巴特莱比在酒馆的一场打斗中落败后，才肯交出酒杯。",h="在暴风城，伯加德要求一名年轻战士从顽固的主人手中赢得巴特莱比的酒杯。巴特莱比在酒馆的一场打斗中落败后，才肯交出酒杯。",kw={"巴特莱比","巴特莱比的酒杯","伯加德","暴风城","酒馆斗殴","战士训练"},ang={["class:Warrior"]="身为联盟战士，你要从巴特莱比手中强夺酒杯，才能获得巴特莱比的酒杯。当言语无效时，这场打斗就需要毅力与力量。"},sec={{t="斗殴者的战利品",b="巴特莱比紧握着心爱的酒杯不放，直到在一场打斗中落败。即便如此，他也要喝干最后一滴酒，才肯把酒杯交出来。这个酒杯证明，战士能够迫使不肯配合的对手屈服。"}},faq={{q="巴特莱比的酒杯有什么用？",a="战士在训练试炼中取得巴特莱比的酒杯，作为获胜的凭证。将它带给教官，就能证明战士有能力击败一个顽固的酒馆斗殴者，并迫使他交出酒杯。",al={"巴特莱比的酒杯用途","为什么需要巴特莱比的酒杯","酒杯有什么用"}},{q="酒杯原本属于谁？",a="酒杯属于巴特莱比。这个好斗的酒鬼整日喝酒打架，只有在一名立志成为战士的人徒手击败他后，才肯交出酒杯。他还要先把酒喝完。",al={"巴特莱比是谁","巴特莱比的主人","谁拿着酒杯"}},{q="谁要求取得巴特莱比的酒杯？",a="伯加德要求取得巴特莱比的酒杯。这位暴风城的战士训练师在一旁观看打斗，并要求战士拿酒杯作为凭证，才肯继续传授武艺。",al={"谁想要酒杯","巴特莱比的酒杯交给谁","巴特莱比的酒杯交付"}}},fx={["481c5411"]={q="巴特莱比的酒杯是什么？",a="巴特莱比的酒杯是暴风城酒馆中一位喜欢斗殴的常客巴特莱比的个人酒具。这只酒杯是年轻战士勇武的有力证明——只有在战斗中彻底击败巴特莱比，并且等他喝完杯中最后的一滴酒之后，他才会交出这只酒杯。",al={"巴特莱比的酒杯是什么","巴特莱比的酒杯"}},a3659338={q="伯尔加德为什么想要巴特莱比的酒杯？",a="伯尔加德要求你拿到这只酒杯，以此作为你在酒馆斗殴中站稳脚跟并击败巴特莱比的实物证明。拿走一个嗜酒者的心爱酒杯绝非易事；交出这只酒杯证明了你已经用拳头说服了巴特莱比，并已准备好继续你的战士训练。",al={"为什么要巴特莱比的酒杯","为什么伯尔加德要这只酒杯","伯尔加德要酒杯的用途"}}},fp="14,160,17.203.0,32.196.0,28.185.0,28.166.0"}
P.entries["item:bathran-s-hair"] = {n="巴斯兰的头发",s="在灰谷西北部的巴斯兰鬼屋废墟中，巴斯兰的头发依然是一种稀有草药。暗夜精灵医者看重它治疗肉体与灵魂疾患的功效。",h="在灰谷西北部的巴斯兰鬼屋废墟中，巴斯兰的头发依然是一种稀有草药。暗夜精灵医者看重它治疗肉体与灵魂疾患的功效。",kw={"灰谷","巴斯兰的头发","巴斯兰鬼屋","迈斯特拉岗哨","奥雷迪尔·阔叶","植物束"},ang={["profession:Herbalism"]="受过训练的草药师更容易找到巴斯兰的头发，他们凭借辨识野生植物的老练眼光，能发现杂物中隐藏的植物包裹。",["race:NightElf"]="对Kaldorei而言，被遗忘者出现在生长着巴斯兰的头发等疗伤植物的废墟中，令守护古老家园的事业受到威胁。"},sec={{t="灵魂的良药",b="巴斯兰的头发生长在迈斯特拉岗哨以北的古老废墟中，暗夜精灵医者长久以来都很珍视它。寻常草药能疗愈身体的创伤，据说巴斯兰的头发还能使灵魂复原。当阿斯特兰纳的一名年幼暗夜精灵身患重病时，草药师奥雷迪尔·阔叶便寻找这种稀有植物，用来配制良药。"},{t="废墟中的采集",b="巴斯兰的头发在废墟中更难寻觅。在靠近黑海岸边界的巴斯兰鬼屋，它藏在散落各处的废弃植物包裹和落叶堆下。废墟中还出现了被遗忘者的身影，这个消息令奥雷迪尔·阔叶感到不安。"}},faq={{q="巴斯兰的头发有什么用途？",a="暗夜精灵医者用巴斯兰的头发治疗超出寻常疾病范畴的严重疾患。奥雷迪尔·阔叶用它调配治疗药剂，救治一个灵魂正在衰弱的垂死孩童。",al={"巴斯兰的头发有什么作用","巴斯兰的头发用途","巴斯兰的头发用处"}},{q="巴斯兰的头发生长在哪里？",a="巴斯兰的头发生长在巴斯兰鬼屋内，那是灰谷北部一处古老聚落的废墟，位于向北通往黑海岸的大路以东。",al={"哪里能找到巴斯兰的头发","巴斯兰的头发位置","巴斯兰的头发在哪里"}},{q="被遗忘者为什么对巴斯兰鬼屋感兴趣？",a="奥雷迪尔·阔叶得知被遗忘者出现在巴斯兰鬼屋，对他们的到来感到不安，但他们在那里的目的并未得到说明。在灰谷的其他地方，暗夜精灵报告说，废墟和兽穴中也出现了被遗忘者，并担心他们意图将疾病散播到整片森林。",al={"亡灵为什么在巴斯兰鬼屋","巴斯兰鬼屋中的被遗忘者","亡灵 巴斯兰"}},{q="奥雷迪尔·阔叶是谁？",a="奥雷迪尔·阔叶是灰谷西部迈斯特拉岗哨的一名草药师。他研究当地植物，为旅人和受伤的森林守卫配制药物。",al={"奥雷迪尔·阔叶","谁需要巴斯兰的头发"}}},fx={b940f392={q="巴斯兰的头发是什么？",a="巴斯兰的头发是一种稀有而娇嫩的草药，生长在灰谷北部的巴斯兰鬼屋的古老废墟之中。这种植物在暗夜精灵草药师中非常有名，具有强大的恢复能力，既能治愈精神上的创伤，也能缓解身体上的病痛。",al={"巴斯兰的头发是什么","巴斯兰的头发草药"}}},fp="14,166,23.333.0,24.243.1,32.188.0,31.162.0,51.270.0,25.171.0"}
P.entries["item:battleboar-flank"] = {n="斗猪肋排",s="在莫高雷，年轻的猎人从威胁牛头人猎场的野兽身上收集斗猪肋排。这些肉用来喂养部族的幼辈。",h="在莫高雷，年轻的猎人从威胁牛头人猎场的野兽身上收集斗猪肋排。这些肉用来喂养部族的幼辈。",kw={"斗猪","斗猪肋排","刺刃峡谷","刺背","纳拉其营地","格鲁尔·鹰风","莫高雷","红云台地"},ang={["profession:Cooking"]="作为厨师，你可以用肋排慢炖出一锅营地共享的炖肉，让大家填饱肚子。",["race:Tauren"]="作为牛头人，猎杀威胁家园的斗猪能让你学会保卫家园，同时尊重并善用Earth Mother的馈赠。"},sec={{t="来自刺背威胁的食粮",b="刺背野猪人在刺刃峡谷训练斗猪，让它们闯入牛头人的猎场。它们的袭击威胁着纳拉其营地的年轻牛头人。格鲁尔·鹰风派新手猎人去猎杀这些野兽，取回肋排和鼻子。肋排被炖成肉汤，供部族的幼辈食用，野猪人驱来对付牛头人的野兽就这样成了他们的食粮。"}},faq={{q="斗猪肋排有什么用途？",a="纳拉其营地的年轻猎人按照格鲁尔·鹰风的指示收集斗猪肋排。这些肉被炖成肉汤，供村里的年轻牛头人食用。",al={"斗猪肋排用途","斗猪肋排是什么","为什么收集斗猪肉"}},{q="哪里能找到斗猪肋排？",a="猎人从斗猪和刺背斗猪身上割取斗猪肋排，这些野兽出没在红云台地的刺刃峡谷附近，位于纳拉其营地以东。",al={"斗猪肋排来源","哪里的斗猪掉落肋排","谁掉落斗猪肋排"}},{q="斗猪为什么侵入牛头人的土地？",a="刺背野猪人繁育斗猪，并将它们训练得充满敌意。随着刺背野猪人与牛头人之间的关系日益紧张，野猪人把这些野兽赶进牛头人的传统猎场，骚扰这些新来者。",al={"斗猪为什么袭击","野猪人 斗猪 莫高雷","刺刃 斗猪"}}},fx={c29b6530={q="什么是斗猪肋排？",a="这是一种从莫高雷的红色平原和峡谷中游荡的斗猪身上获取的鲜美肉块。虽然这些凶猛的猪是被为了战争而非食用而繁育和训练的，但在猎物匮乏时，它们的肉足够充实，足以养活部落。",al={"什么是斗猪肋排","斗猪肋排信息","斗猪肉"}},["4a352cac"]={q="斗猪肋排从哪儿来？",a="这些肋排是从在刺刃峡谷附近潜行的斗猪和刺背斗猪身上切割下来的。这些生物被敌对的刺背野猪人饲养和训练得充满攻击性，将原本的野生猎物变成了凶猛的领地野兽。",al={"斗猪肋排来源","斗猪肋排从哪儿来","谁有斗猪肉"}},f9e62759={q="格鲁尔·鹰风为什么想要斗猪肋排？",a="格鲁尔·鹰风收集这些肋排是为了喂养纳拉其营地的部落年轻后辈。将这些肉烹饪成营养丰富的炖肉，确保了狩猎所得没有任何浪费，同时也惩罚了将这些极具攻击性的野兽赶进牛头人祖传猎场的刺背野猪人。",al={"为什么要收集斗猪肋排","为什么格鲁尔要肋排","谁要斗猪肋排"}}},fp="16,129,38.345.0,36.147.0,34.142.0,51.216.0"}
P.entries["item:battleboar-snout"] = {n="斗猪头",s="年轻的牛头人猎人在红云台地附近收集斗猪头，此时刺背正侵入他们的猎场。这些斗猪头还会被炖成肉汤，供纳拉其营地的孩子们食用。",h="年轻的牛头人猎人在红云台地附近收集斗猪头，此时刺背正侵入他们的猎场。这些斗猪头还会被炖成肉汤，供纳拉其营地的孩子们食用。",kw={"斗猪","斗猪头","刺刃峡谷","刺背","纳拉其营地","格鲁尔·鹰风","红云台地"},ang={["profession:Cooking"]="身为厨师，你可以将斗猪头这类坚韧的食材放在火上慢煮，为部族炖制篝火肉汤。",["race:Tauren"]="身为牛头人，收集斗猪头和猪肉，是对Earthmother所维系的平衡的尊重。这既能遏制入侵的掠食者，也能为纳拉其营地的孩子们提供食物。"},sec={{t="战利品与食粮",b="刺背野猪人在红云台地下方的刺刃峡谷训练斗猪，试探牛头人的猎场。格鲁尔·鹰风派出年轻的勇士，抵御这场侵扰。一个斗猪头就能证明一头斗猪已被击杀。牛头人将斗猪头与腰肉一起炖成浓汤，供孩子们食用。"}},faq={{q="斗猪头有什么用途？",a="格鲁尔·鹰风让纳拉其营地的年轻猎人收集斗猪头和腰肉。斗猪头证明那些构成威胁的野猪已被击杀，牛头人也会将它们炖成肉汤，供部族的孩子们食用。",al={"斗猪头用途","为什么保留斗猪头","格鲁尔·鹰风用斗猪头做什么"}},{q="这些斗猪头来自哪里？",a="斗猪头来自红云台地边缘附近，以及东面刺刃峡谷各处的斗猪和刺背斗猪。",al={"哪里能找到斗猪","谁掉落斗猪头","斗猪位置"}},{q="斗猪为什么侵入牛头人的土地？",a="敌对的刺背野猪人将斗猪训练得异常凶猛。这些野猪从刺刃峡谷向外推进，侵入牛头人世代狩猎的地方。",al={"野猪为什么攻击","野猪人的野猪","刺刃峡谷斗猪"}}},fx={a852a9b9={q="什么是斗猪头？",a="这是刺背野猪人在刺刃峡谷附近饲养和训练的斗猪的被切下的头部。格鲁尔·鹰风和纳拉其营地的牛头人将这些肉块与猪的肋排一起，视为可以炖给部落年轻人吃的丰盛食材，同时也作为他们的猎人正在猎杀这些入侵野兽的实物证明。",al={"斗猪头","什么是斗猪头","这是什么物品"}}},fp="16,180,23.312.0,36.205.0,32.148.0,51.167.0"}
P.entries["item:battleworn-axe"] = {n="破斧",s="在赤脊山，破斧是入侵这片山地的黑石兽人的标志。治安官马瑞斯在湖畔镇收取缴获的武器，作为当地居民受到威胁的证据。",h="在赤脊山，破斧是入侵这片山地的黑石兽人的标志。治安官马瑞斯在湖畔镇收取缴获的武器，作为当地居民受到威胁的证据。",kw={"破斧","黑石","湖畔镇","玛瑞斯","兽人","赤脊山","石堡","武器"},ang={["faction:Alliance"]="对联盟而言，在暴风城主力部队驻扎他处之际，每一把送到湖畔镇的斧头，都意味着威胁赤脊山那些缺乏保护的居民的入侵者又少了一个。",["profession:Blacksmithing"]="身为铁匠，你能从这些粗陋的铁斧上看出黑石武器典型的坚韧、厚重的锻造工艺，尽管斧刃参差不齐，满是缺口。"},sec={{t="入侵者的战利品",b="黑石掠夺者从燃烧平原向南推进，进入赤脊山，手中拿着这些沉重且满是缺口的斧头。治安官马瑞斯和湖畔镇疲于应付的城镇卫兵收集这些斧头，以确认又一名四处劫掠的兽人已经倒下，同时了解步步进逼的战帮装备有多精良。"},{t="山中的威胁",b="黑石入侵者加固了石堡要塞，并在赤脊山东南部建立了据点，将镇民困在湖畔镇。夺取他们久经战斗的武器，既能削减战帮可用的兵器，也能扫清道路，让联盟通行。"}},faq={{q="什么是破斧？",a="赤脊山的黑石兽人携带着破斧，这些结实的武器因长期使用而磨损。缴获的斧头证明入侵者已被击杀。",al={"破斧资料","这些斧头是什么","黑石斧头"}},{q="湖畔镇有谁需要这些斧头？",a="治安官马瑞斯统领湖畔镇的城镇卫兵，他需要这些斧头，以证明黑石的威胁正被逐出城镇领地。",al={"谁收破斧","破斧任务给予者","治安官马瑞斯斧头"}},{q="这些斧头从何而来？",a="赤脊山各处的黑石兽人都携带着这些斧头，尤其是北面石堡要塞附近和东南部兽人营地中的兽人。",al={"哪里掉落破斧","刷破斧","哪些兽人携带这些斧头"}},{q="兽人最初为什么会来到赤脊山？",a="黑石氏族从燃烧平原穿过山口向南进军，攻占石堡要塞，并在赤脊山北部和东部四处劫掠，以牵制湖畔镇。",al={"黑石兽人为何在赤脊山","石堡入侵","黑石威胁的原因"}}},fp="14,182,20.267.0,23.249.0,25.150.0,34.138.0,30.138.0,48.198.0"}
P.entries["item:berard-s-journal"] = {n="伯纳德的日记",s="焚木村的伯纳德的日记中，记载着皇家药剂师学会所需的研究。博拉尔德研究过一种古老的瘟疫，它曾使洛丹米尔湖的水生生物灭绝。",h="焚木村的伯纳德的日记中，记载着皇家药剂师学会所需的研究。博拉尔德研究过一种古老的瘟疫，它曾使洛丹米尔湖的水生生物灭绝。",kw={"药剂师博拉尔德","药剂师伦弗利尔","伯纳德的日记","洛丹米尔湖","大药剂师法拉尼尔","焚木村","皇家药剂师学会","银松森林"},ang={["faction:Horde"]="作为部落的一员，你在焚木村找回遗失的研究，有助于被遗忘者在银松森林各处建立稳固的防御据点。",["race:Undead"]="作为Undead，任何一点有关毒物的知识，都能帮助皇家药剂师学会获得武器，保护被遗忘者抵御Scourge与活着的敌人。"},sec={{t="洛丹米尔湖遗失的研究",b="在阿鲁高的暗影魔法蔓延至银松森林之前，药剂师博拉尔德曾是皇家药剂师学会最有前途的研究者之一。他在焚木村研究一种古老的疫病，数百年前，它曾使洛丹米尔湖的所有水生生物灭绝。当阿鲁高的诅咒笼罩村庄时，博拉尔德失去了理智，沦为奴仆。他详尽的实地研究笔记，仍留在焚木村旅店住处的书架上。"},{t="新的瘟疫的助力",b="尽管皇家药剂师学会失去了博拉尔德，他的研究却保存了下来。在瑟伯切尔，药剂师伦弗利尔意识到了这些研究的价值，派遣被遗忘者特工深入危机四伏的村庄，取回日记。这些关于古老湖水毒素的笔记，为大药剂师法拉尼尔和炼金房中的皇家药剂师学会成员研制被遗忘者自己的新瘟疫奠定了基础。"}},faq={{q="药剂师博拉尔德是谁？",a="药剂师博拉尔德是皇家药剂师学会中一位才华出众的成员，住在焚木村。他研究古老毒素期间，大法师阿鲁高诅咒了这片地区，使博拉尔德精神崩溃，沦为奴仆。",al={"博拉尔德是谁","博拉尔德的故事","药剂师博拉尔德"}},{q="在哪里能找到伯纳德的日记？",a="伯纳德的日记放在他旧日书房的书架上，书房位于焚木村旅店的楼上，地处银松森林南部深处。",al={"寻找伯纳德的日记","日记位置","书在哪里"}},{q="日记中记载了什么研究？",a="日记记载了博拉尔德对一种古老疫病的研究发现，这种疫病曾使洛丹米尔湖的所有水生生物灭绝。皇家药剂师学会希望利用它的毒性，研制自己的化学武器。",al={"日记记载了什么","博拉尔德的研究","日记内容"}},{q="药剂师伦弗利尔为什么想要这本日记？",a="药剂师伦弗利尔想在这些有用的研究被毁或遗失之前将其找回。博拉尔德对洛丹米尔湖疫病的研究发现，提供了大药剂师法拉尼尔在幽暗城研制被遗忘者新瘟疫所需的成分。",al={"伦弗利尔为什么想要日记","伦弗利尔日记任务"}}},fx={b3a0b77c={q="伯纳德的日记是什么？",a="伯纳德的日记是由皇家药剂师学会的前成员药剂师伯纳德编写的一本科学研究笔记。其中包含了关于很久以前消灭了洛丹米尔湖中所有水生生物的某种古代传染病的详细发现，被遗忘者希望研究它以用于自己的炼金术。",al={"伯纳德的日记","伯纳德的日记是什么"}},["719e9fe0"]={q="伯纳德的日记从哪儿来，是谁做的？",a="这本日记是由药剂师伯纳德在被大法师阿鲁高的暗影魔法控制而发疯之前撰写的。他把研究资料保存在焚木村的旅店里，在他变成没有思想的仆从后，这本大部头被遗留在了书架上。",al={"伯纳德的日记从哪儿来","谁写了伯纳德的日记","伯纳德的日记来源"}}},fp="16,167,31.428.0,23.360.1,26.208.0,32.142.0,41.207.0,47.238.0"}
P.entries["item:bernice-s-necklace"] = {n="波尼斯的项链",s="在艾尔文森林的斯通菲尔德农场，波尼斯将亡夫的项链珍藏在身边。",h="在艾尔文森林的斯通菲尔德农场，波尼斯将亡夫的项链珍藏在身边。",kw={"波尼斯 大婶","波尼斯的项链","比利·马科伦","法戈第矿洞","金牙","幸运护身符","斯通菲尔德"},ang={["faction:Alliance"]="对艾尔文森林的联盟农户而言，这条项链让人想起暴风城旷日持久的军事远征给平民生活带来的伤痛。"},sec={{t="士兵遗失的护身符",b="波尼斯·斯通菲尔德大婶在斯通菲尔德农场保管着丈夫的项链。他曾参加过暴风城的多次军事远征，每次上阵都会带着这件护身符，祈求好运。波尼斯说，悲剧只发生在他最后一次出征时。唯独那次远征，他忘了带上项链。自他去世后，这件遗物一直是她最珍爱的物品之一。"},{t="拾荒者窃走的项链",b="年幼的比利·马科伦在法戈第矿洞附近探险时，那条闪亮的项链从他手中滑落。矿洞里一个颇有名气的狗头人金牙发现了项链，将它带走。和其他狗头人一样，他也喜欢闪亮而贵重的小饰物。他把项链和自己搜罗来的财宝放在了一起。"}},faq={{q="这条项链原本属于谁？",a="这条项链原本属于波尼斯·斯通菲尔德大婶的亡夫。他参加暴风城的军事远征时，一直将它作为幸运护身符佩戴。",al={"项链原本属于谁","波尼斯 项链主人","丈夫的项链"}},{q="项链是怎么落到狗头人手里的？",a="比利·马科伦看见一个长着金牙的大个子狗头人在法戈第矿洞附近捡起项链，随后将它带走。波尼斯大婶希望能找回项链。",al={"项链如何遗失","金牙 为什么有项链","谁拿走了项链"}},{q="这条项链为什么对波尼斯大婶如此重要？",a="这条项链寄托着波尼斯对亡夫的珍贵回忆。他相信它能在战斗中保护自己，而他唯一一次在战争中倒下，恰好就是他没带上项链的那天。",al={"波尼斯 为什么想找回项链","波尼斯 丈夫的故事","项链有魔法吗"}},{q="金牙是谁？",a="金牙是个颇有名气的狗头人拾荒者，巢穴位于艾尔文森林的法戈第矿洞内。他收集闪亮的小饰物，并拿走了掉落在附近的项链。",al={"金牙 是什么","金牙 的背景故事","项链在谁手里"}}},fp="18,85,22.368.0,20.306.1,35.131.0,45.154.0,51.165.0,17.174.0"}
P.entries["item:besseleth-s-fang"] = {n="贝瑟莱斯的牙齿",s="在希塞尔山谷，贝瑟莱斯的牙齿标志着一只致命蜘蛛的威胁已被终结。",h="在希塞尔山谷，贝瑟莱斯的牙齿标志着一只致命蜘蛛的威胁已被终结。",kw={"蜘蛛恐惧症","贝瑟莱斯","贝瑟莱斯的牙齿","马格兰","希塞尔山谷","石爪山脉","烈日石居","蛛网小径"},ang={["class:Hunter"]="身为猎人，你可以取下这只顶级掠食蜘蛛族母长近两英尺的毒牙，作为你追踪技巧与战斗实力的证明。",["faction:Horde"]="除掉山谷中的蜘蛛，有助于保护连接贫瘠之地边境与烈日石居的险峻山路。"},sec={{t="山谷潜猎者的战利品",b="贝瑟莱斯和她的子嗣让希塞尔山谷危机四伏，威胁着过往旅人。每到夜晚，这只巨型蜘蛛就会让蛛网小径成为穿越峡谷者的死亡陷阱。她的毒牙长近两英尺，滴淌着剧毒。当地守卫饱受她的毒牙之苦，交出这颗毒牙能让他们松一口气。"}},faq={{q="贝瑟莱斯的牙齿有什么用？",a="这颗毒牙证明蜘蛛族母贝瑟莱斯已被杀死。烈日石居的马格兰曾遭她的毒牙袭击，险些丧命，幸存后便悬赏除掉她，并奖赏将这件战利品带给他的人。",al={"贝瑟莱斯的牙齿用途","谁要贝瑟莱斯的牙齿","毒牙交付"}},{q="这颗毒牙来自哪里？",a="这颗毒牙来自贝瑟莱斯，一只栖息在希塞尔山谷中的巨型掠食蜘蛛。山谷位于石爪山脉境内，在狂风峭壁以南主路的西侧。",al={"如何获得贝瑟莱斯的牙齿","贝瑟莱斯在哪里","贝瑟莱斯位置"}},{q="马格兰为什么想要杀死贝瑟莱斯？",a="贝瑟莱斯和她的子嗣会捕食沿道路前往烈日石居的旅人，尤其是在夜间。马格兰遭到贝瑟莱斯伏击，被她的毒牙咬伤后，便发布悬赏，以确保道路安全。",al={"为什么杀死贝瑟莱斯","马格兰蜘蛛悬赏","为什么悬赏贝瑟莱斯"}},{q="是谁发布了收取毒牙的悬赏？",a="马格兰发布了这份悬赏。狂风峭壁岔路口以南的主路旁立着一块通缉告示牌，警告旅人当心希塞尔山谷的危险。",al={"石爪山脉蜘蛛通缉告示","蜘蛛恐惧症任务发布者"}}},fx={f0d9a9a7={q="贝瑟莱斯的牙齿是什么？",a="贝瑟莱斯的牙齿是从掠食性蜘蛛贝瑟莱斯身上取下的一颗两英尺长的巨大牙齿。它和它的巢穴潜伏在希塞尔山谷，在夜间捕食蛛网小径上的旅行者。这颗牙齿是那个在石爪山脉的小径上恐吓行人的可怕蛛形纲生物终于被击杀的无可辩驳的实物证明。",al={"贝瑟莱斯的牙齿是什么","贝瑟莱斯的牙齿"}}},fp="16,79,28.315.0,34.227.0,31.184.0,48.220.0,35.165.0"}
P.entries["item:bethor-s-scroll"] = {n="比索的卷轴",s="比索·埃斯沙德写下反制咒文，帮助药剂师伦弗利尔调制抵御图勒·鸦爪黑暗巫术的防护药剂。这份卷轴是对抗守护芬里斯岛的 Scourge 死灵法术的关键。",h="比索·埃斯沙德写下反制咒文，帮助药剂师伦弗利尔调制抵御图勒·鸦爪黑暗巫术的防护药剂。这份卷轴是对抗守护芬里斯岛的 Scourge 死灵法术的关键。",kw={"药剂师伦弗利尔","比索·埃斯沙德","比索的卷轴","芬里斯岛","腐皮","银松森林","瑟伯切尔","图勒·鸦爪"},ang={["class:Mage"]="身为法师，你能看出，熟悉另一位施法者独有的魔法，如何能成为有力的反制手段。这份卷轴映照出肯瑞托分崩离析的往事。",["race:Undead"]="身为亡灵，你能从这张羊皮纸中看到被遗忘者的施法者与药剂师如何通力合作。它将达拉然昔日的奥术学识与瑟伯切尔的炼金技艺结合在一起。"},sec={{t="反制死灵法师",b="比索·埃斯沙德写下奥术配方，指导皇家药剂师学会调制恢复药水。药剂师伦弗利尔在瑟伯切尔接收这份卷轴。卷轴上的咒文能反制图勒在堡垒周围布下的虚弱妖术。"},{t="同僚的背叛",b="比索·埃斯沙德从腐皮豺狼人身上取得的受污染脓液中，认出了图勒·鸦爪的手笔。图勒曾是肯瑞托一位前途无量的年轻法师。当 Scourge 崛起时，他背叛了同胞，转而效忠巫妖王。比索得知图勒仍然活着，并从芬里斯岛指挥腐皮在银松森林各地发动袭击。比索深知这位昔日同僚的施法技艺，于是写下了这份卷轴。"}},faq={{q="比索的卷轴上写了什么？",a="比索·埃斯沙德在卷轴上写下了专门的奥术咒文。他曾与图勒·鸦爪一同研习法术，熟悉这位死灵法师惯用的法术，因此他的配方指明了如何通过炼金术调制反制药水。",al={"卷轴写了什么","比索的卷轴内容","卷轴上有什么"}},{q="谁接收这份卷轴？",a="驻守在银松森林瑟伯切尔的药剂师伦弗利尔接收这份卷轴。他利用其中的魔法制作防护药剂。",al={"卷轴交给谁","比索的卷轴交付","谁接收卷轴"}},{q="药剂师伦弗利尔为什么需要用魔法咒文来调制药水？",a="药剂师伦弗利尔钻研的是炼金术，而非传统巫术，他也承认自己很少将如此直接的魔法力量融入药剂。普通的抗毒药剂无法穿透保护图勒的 天灾军团 诅咒，因此需要比索的奥术配方才能让药剂生效。",al={"药剂师为什么需要法术","伦弗利尔 魔法药水"}},{q="图勒·鸦爪在投靠 天灾军团 之前是什么人？",a="在第三次大战之前，图勒·鸦爪是一位前途无量的年轻人类法师，也是比索·埃斯沙德的同僚。当巫妖王集结亡灵大军时，图勒抛弃了其他施法者，向 天灾军团 宣誓效忠。",al={"图勒·鸦爪 是谁","图勒 的过往","图勒 与 比索"}}},fx={["31160c67"]={q="比索的卷轴从哪儿来，是谁做的？",a="这份卷轴是由幽暗城魔法区中为被遗忘者效力的亡灵法师比索·埃斯沙德撰写的。通过识别从烂皮豺狼人身上找到的邪恶脓液上的魔法印记，比索意识到他以前的同事图勒·鸦爪还活着，并且已经投靠了天灾军团。基于对比索·鸦爪奥术技巧的深刻了解，比索将反咒语抄写在这张羊皮纸上，以帮助击败他那堕落的前同事。",al={"谁写了比索的卷轴","谁制作了比索的卷轴","比索的卷轴从哪儿来"}},["64d2974c"]={q="为什么需要比索的卷轴？",a="药剂师伦弗利尔需要卷轴上铭刻的魔法咒语来酿制一种防御性的解毒剂。图勒·鸦爪在他位于芬里斯岛的要塞中施展强大且令人虚弱的诅咒。通过将比索的奥术配方注入炼金药剂，皇家药剂师学会可以制造出一种专门的药水，让你在对抗图勒时免受其邪恶巫术的侵害。",al={"为什么想要比索的卷轴","比索的卷轴为什么重要","比索的卷轴有什么用"}}},fp="15,192,26.240.1,22.428.1,35.183.0,25.127.0,69.250.0,54.231.0"}
P.entries["item:bingles-blastencapper"] = {n="宾格斯的气压炸弹",s="宾格斯的旋翼机坠入洛克湖后，宾格斯的气压炸弹落到了穴居人手中。没有它，宾格斯支援解放诺莫瑞根的计划就岌岌可危。",h="宾格斯的旋翼机坠入洛克湖后，宾格斯的气压炸弹落到了穴居人手中。没有它，宾格斯支援解放诺莫瑞根的计划就岌岌可危。",kw={"宾格斯","气压炸弹","雷管","爆炸物","诺莫瑞根","旋翼机","洛克莫丹","穴居人"},ang={["profession:Engineering"]="气压炸弹展现了侏儒的工程天赋：构造复杂，威力惊人，能从高空发动毁灭性的打击。",["race:Gnome"]="侏儒正奋力收复诺莫瑞根，每件工具、每份弹药都至关重要。找回宾格斯的炸弹，或许就能让侏儒凭借巧妙的航空发明，反击入侵的穴居人。"},sec={{t="不稳定的发明",b="宾格斯·雷管制造了气压炸弹，用来从空中打击占领诺莫瑞根的穴居人和麻风侏儒。机械故障让他的旋翼机坠入洛克湖，但宾格斯活了下来。北部岛屿上的穴居人洗劫了残骸，把这件不稳定的武器带回了营地。"},{t="诺莫瑞根的空中支援",b="宾格斯需要气压炸弹来协助夺回诺莫瑞根。流亡的侏儒正准备收复遭受辐射的家园，而他指望用自己的旋翼机和拿手弹药发动空袭。这枚炸弹落在穴居人手中，可能意外地给洛克莫丹带来一场灾难。找回它，就能为侏儒反抗军保住一件宝贵的武器。"}},faq={{q="宾格斯的气压炸弹是什么？",a="宾格斯·雷管制造了气压炸弹，用来从空中打击占据诺莫瑞根的穴居人和麻风侏儒。",al={"气压炸弹是什么","气压炸弹","宾格斯的炸弹"}},{q="气压炸弹怎么会落到洛克湖？",a="宾格斯驾驶的旋翼机坠入了洛克湖。附近岛屿上的穴居人洗劫了残骸，带走了他的工具，其中就包括这枚炸弹。",al={"为什么在洛克湖","宾格斯怎么弄丢的","坠机"}},{q="气压炸弹现在在谁手里？",a="洛克湖北部岛屿上的穴居人从残骸中拿走了气压炸弹，如今正把它看守在营地里。",al={"谁偷走了气压炸弹","在谁手里","穴居人"}},{q="宾格斯为什么需要找回气压炸弹？",a="宾格斯需要找回气压炸弹和工具，修好旋翼机，发动空袭，支援收复诺莫瑞根的行动。",al={"为什么要找回","气压炸弹为什么重要","为了诺莫瑞根"}}},fp="22,148,20.300.0,26.361.0,31.120.0,45.144.0,36.110.0,49.141.0"}
P.entries["item:bingles-hammer"] = {n="宾格斯的榔头",s="在洛克莫丹的坠机地点，宾格斯·雷管需要从穴居人手中找回宾格斯的榔头。拿回装备后，他就能修好飞行器，帮助解放诺莫瑞根。",h="在洛克莫丹的坠机地点，宾格斯·雷管需要从穴居人手中找回宾格斯的榔头。拿回装备后，他就能修好飞行器，帮助解放诺莫瑞根。",kw={"宾格斯","雷管","诺莫瑞根","榔头","洛克莫丹","工具桶","穴居人"},ang={["profession:Engineering"]="身为工程师，你知道一把侏儒精工打造的榔头很难找到替代品。宾格斯需要这样一把榔头，才能在荒野中重建他的试验型旋翼机。",["race:Gnome"]="身为侏儒，你每找回一件工具，就让解放祖辈家园的空中突袭更近一步。"},sec={{t="受困飞行员的工具箱",b="穴居人洗劫了宾格斯·雷管位于淡水湖岛屿上的坠机地点。他们抢走了他的榔头和高效炸药。修复凹陷的机身、调整旋翼机的机械部件，都需要用到这把榔头。没有装备，宾格斯就无法驾驶飞行器，为奋战着夺回诺莫瑞根的侏儒部队提供支援。"}},faq={{q="在哪里能找到宾格斯的榔头？",a="宾格斯的榔头就在一个 宾格斯的工具桶 里，这些工具桶散落在洛克北部穴居人盘踞的岛屿上。",al={"榔头位置","宾格斯的榔头在哪","如何找到榔头"}},{q="这把榔头属于谁？",a="这把榔头属于宾格斯·雷管，一位侏儒工程师兼飞行员。他的飞行器坠毁在洛克莫丹的湖岸边。",al={"榔头属于谁","宾格斯的榔头主人"}},{q="这件工具为什么对宾格斯如此重要？",a="宾格斯需要集齐整套工具，才能重建坠毁的旋翼机。他计划驾驶它，打击占据诺莫瑞根的穴居人和麻风侏儒。",al={"为什么需要榔头","宾格斯的榔头用途"}},{q="谁偷走了宾格斯的榔头？",a="住在湖中岛屿上的穴居人洗劫了坠机地点。他们抢走了宾格斯的工具桶和特制的 气压炸弹 炸药。",al={"谁拿走了榔头","穴居人窃贼"}}},fp="15,181,28.330.0,35.122.0,31.131.0,41.146.0,26.124.0"}
P.entries["item:bingles-screwdriver"] = {n="宾格斯的螺丝起子",s="在洛克莫丹北部的岛屿间，宾格斯的螺丝起子混在坠机时遗失的装备之中。穴居人把它和飞行员宾格斯·雷管的工具一起抢走了。",h="在洛克莫丹北部的岛屿间，宾格斯的螺丝起子混在坠机时遗失的装备之中。穴居人把它和飞行员宾格斯·雷管的工具一起抢走了。",kw={"宾格斯","布拉斯坦海默","旋翼机","洛克莫丹","螺丝起子","工具桶","穴居人"},ang={["profession:Engineering"]="作为工程师，你知道，要摆弄旋翼机复杂的旋翼和精密的扳机组件，一把制作精良的螺丝起子至关重要。",["race:Gnome"]="作为侏儒，你每找回一件工具，就能让宾格斯离重建飞行器的目标更近一步，去对抗那些将你的同胞赶出诺莫瑞根的穴居人和麻风侏儒。"},sec={{t="飞行员的重要工具",b="宾格斯·雷管坠落在洛克莫丹时，丢失了修理旋翼机所需的工具。附近岛屿上的穴居人抢走了他的工具桶，螺丝起子就装在其中一个桶里。宾格斯修理飞行器、摆弄机载武器时，需要用它进行精细调整。"},{t="为夺回家园做准备",b="宾格斯致力于从穴居人和麻风侏儒手中解放诺莫瑞根。他打算凭借自己的飞行本领，配合不稳定的气压炸弹弹药，发动空中突袭。螺丝起子、扳手和铁锤将帮助他重建旋翼机，让空中反攻得以继续。"}},faq={{q="在哪里能找到宾格斯的螺丝起子？",a="宾格斯坠机后，穴居人把他的工具桶散落在洛克莫丹北部的岛屿上。螺丝起子就在其中一个桶里。",al={"螺丝起子位置","寻找宾格斯的螺丝起子","螺丝起子在哪里"}},{q="螺丝起子为什么对宾格斯如此重要？",a="宾格斯需要螺丝起子和其他工具来重建旋翼机，并为夺回诺莫瑞根的战役准备炸药。",al={"宾格斯为什么需要它","它有什么用"}},{q="最初是谁偷走了螺丝起子？",a="宾格斯迫降后，住在洛克莫丹岛屿上的穴居人拿走了他的工具桶和气压炸弹炸药。",al={"谁拿走了工具","谁偷了宾格斯的工具"}},{q="宾格斯在坠机时还丢失了哪些工具？",a="除了螺丝起子，宾格斯还丢失了扳手、铁锤，以及储备的不稳定的气压炸弹炸药。",al={"宾格斯的其他工具","还丢了什么"}}},fx={f72526b7={q="宾格斯的螺丝起子是什么？",a="宾格斯的螺丝起子是属于宾格斯·雷管的工程工具，他是一位在洛克莫丹遇难的侏儒飞行员。这和他的扳手与锤子一样，是他随身携带在旋翼机上，用于维护他的飞行机器和为侏儒抵抗军制造军火的必要工具之一。",al={"宾格斯的螺丝起子是什么","宾格斯的螺丝起子信息","关于宾格斯的螺丝起子"}}},fp="20,164,19.293.0,29.275.0,36.137.0,47.137.0,45.122.0,47.123.0"}
P.entries["item:bingles-wrench"] = {n="宾格斯的扳手",s="在洛克湖，宾格斯的扳手和这位飞行员的其他工具一同失踪了。宾格斯·雷管的飞行器迫降后，穴居人拿走了它。",h="在洛克湖，宾格斯的扳手和这位飞行员的其他工具一同失踪了。宾格斯·雷管的飞行器迫降后，穴居人拿走了它。",kw={"宾格斯","布拉斯坦海默","旋翼机","洛克莫丹","工具桶","穴居人","扳手"},ang={["profession:Engineering"]="身为工程师，你知道工匠没了定制扳手就寸步难行，尤其是附近还有穴居人在搜刮。",["race:Gnome"]="身为侏儒，每找回一件工具，都能让抵抗军离反攻诺莫瑞根那些遭受辐射的大厅更近一步。"},sec={{t="岛上的失物",b="宾格斯·雷管的旋翼机坠入洛克湖时，他侥幸活了下来。随后，穴居人洗劫了北部小岛上的坠机地点。他们拿走了他的专用物资，把他的工具分散藏在营地里的桶中。\n\n宾格斯的扳手是三件关键手工工具之一，与他的大威力气压炸弹炸药同样重要。没有这把扳手，宾格斯就无法修复坠毁的旋翼机。他原本计划发动空袭，支援那些为夺回诺莫瑞根而战的流亡侏儒，如今只能暂缓行动。"}},faq={{q="这把扳手属于谁？",a="这把扳手属于宾格斯·雷管，他是个性情古怪的侏儒飞行员，驾驶的旋翼机坠入了洛克湖。",al={"宾格斯是谁","宾格斯物主","扳手的主人"}},{q="这把扳手为什么对宾格斯如此重要？",a="宾格斯需要用专用工具修复受损的飞行器，装配机载炸药，以便向占据诺莫瑞根的穴居人和麻风侏儒发动空袭。",al={"宾格斯为什么需要扳手","扳手用途","扳手有什么用"}},{q="坠机后，扳手落到了哪里？",a="当地穴居人捡走了扳手，把它藏在从宾格斯那里偷来的一个工具桶里，就在洛克湖北部岛屿上的营地中。",al={"宾格斯的扳手在哪里","扳手位置","寻找宾格斯的扳手"}},{q="和扳手一起被偷走的还有什么？",a="穴居人还拿走了宾格斯的螺丝起子、宾格斯的榔头，以及他的实验性气压炸弹炸药。",al={"其他物资","丢失的工具","穴居人还拿走了什么"}}},fp="15,145,22.497.0,31.109.0,42.182.0,44.141.0,43.120.0"}
P.entries["item:black-claw-stout"] = {n="黑爪烈酒",s="在暴风城地下，黑爪加尔德斯为维沙克公爵调制了一杯酒。这杯烈酒以普通酒馆饮品的名义送到他手中。",h="在暴风城地下，黑爪加尔德斯为维沙克公爵调制了一杯酒。这杯烈酒以普通酒馆饮品的名义送到他手中。",kw={"黑爪烈酒","祈愿厅","维沙克公爵","毒药","已宰的羔羊","暴风要塞","加尔德斯"},ang={["class:Warlock"]="对于暴风城隐秘的术士集会来说，送酒是一趟差事。一名多管闲事的贵族想要关闭他们位于已宰的羔羊下方的庇护所。",["faction:Alliance"]="将这杯酒送入暴风要塞，让已宰的羔羊下方的术士们得以接近首都的贵族。"},sec={{t="致命毒酒",b="在已宰的羔羊酒馆大厅的下方，黑爪加尔德斯避开城市卫兵的耳目行事。维沙克公爵一再威胁要取缔这里的活动，却始终拖欠着楼上的酒账。于是，加尔德斯利用了这名贵族贪杯的弱点。他在一杯寻常的酒馆饮品中掺入了足以致命的毒药。"},{t="无声的暗杀",b="在暴风要塞的祈愿厅，维沙克公爵收到了这杯烈酒。他傲慢自大，又渴望饮酒，便欣然接受了这份被他误认为是仆人殷勤奉上的饮品。他当场喝了下去。毒药几乎立刻发作，就在王廷眼皮底下，让这名在政界始终不懈地抨击教派的人永远闭上了嘴。"}},faq={{q="黑爪烈酒是什么？",a="黑爪加尔德斯在暴风城法师区的已宰的羔羊下方的地下墓穴中，为维沙克公爵调制黑爪烈酒。",al={"这是什么酒","黑爪烈酒的故事","毒酒"}},{q="这杯烈酒的目标是谁？",a="目标是维沙克公爵，他是祈愿厅里一名专横的贵族，一边力主关闭这处术士庇护所，一边又在那里赊账喝酒。",al={"谁喝了这杯酒","谁死于黑爪烈酒","维沙克目标"}},{q="这杯酒是谁调制的？",a="黑爪加尔德斯在已宰的羔羊下方的墓穴中调制这杯烈酒。",al={"黑爪烈酒的调制者","这是谁调制的","加尔德斯的酒"}},{q="为什么要给维沙克公爵送去这杯烈酒？",a="加尔德斯把这杯烈酒送给身在祈愿厅的维沙克公爵，并让送酒的人看看这名贵族是否喜欢他的特制佳酿。",al={"维沙克会死吗","黑爪烈酒的效果"}}},fx={a6b6f1b7={q="扎德斯为什么要你把黑爪烈酒送给威肖克勋爵？",a="威肖克勋爵是一位虚伪的贵族，他整天游说关闭“屠宰场”，却在晚上跑到楼上喝酒并拖欠酒馆账单。为了让他彻底闭嘴，扎德斯调制了这种致命的特制酒，利用威肖克对酒精的嗜好，假借提供清凉饮料的名义将其除掉。",al={"为什么要运送黑爪烈酒","为什么给威肖克黑爪烈酒","扎德斯为什么要给威肖克烈酒"}}},fp="16,133,15.332.1,19.338.1,25.143.0,31.151.0,21.85.0,38.128.1"}
P.entries["item:black-feather-quill"] = {n="黑色羽毛",s="黑色羽毛就在班奈希尔兽穴中，是唤醒猛禽德鲁伊所必需的物品。",h="黑色羽毛就在班奈希尔兽穴中，是唤醒猛禽德鲁伊所必需的物品。",kw={"阿斯瑞达斯·熊皮","班奈希尔兽穴","黑色羽毛","黑羽之箱","多兰纳尔","猛禽德鲁伊","唤醒圣物"},ang={["class:Druid"]="身为德鲁伊，你知道黑色羽毛是一件神圣的器具，当猛禽德鲁伊的灵魂与翡翠梦境交流时，它维系着他们与现实世界的联系。",["race:NightElf"]="身为暗夜精灵，你知道瘤背熊怪亵渎班奈希尔圣物箱的行径，又一次令人痛心地提醒着族人，腐化正侵蚀泰达希尔。"},sec={{t="唤醒的媒介",b="黑色羽毛是用于唤醒休眠中的猛禽德鲁伊的四件神圣法器之一。其余三件是鸦爪神符、天蓝宝石和筑巢符文。这一仪式将沉睡的德鲁伊从翡翠梦境中唤回。没有这些物品，德鲁伊就可能被困在梦境中，无法返回现实中的躯体。"},{t="班奈希尔的威胁",b="腐化的瘤背熊怪占据了班奈希尔兽穴，使存放圣物的箱子陷入危险。多兰纳尔的阿斯瑞达斯·熊皮下令迅速取回圣物，以免受困的德鲁伊迷失在梦境之中。"}},faq={{q="黑色羽毛有什么用途？",a="黑色羽毛是四件唤醒圣物之一，用于唤醒在翡翠梦境中进行仪式性休眠的猛禽德鲁伊。",al={"黑色羽毛用途","为什么需要黑色羽毛","羽毛有什么用"}},{q="黑色羽毛存放在哪里？",a="黑色羽毛存放在黑羽之箱中，位于泰达希尔中部的班奈希尔兽穴深处。",al={"黑色羽毛位置","黑色羽毛箱在哪里","羽毛位置"}},{q="为什么没有黑色羽毛和其他圣物，德鲁伊就无法醒来？",a="德鲁伊的休眠依靠精妙的魔法，使他们进入翡翠梦境。没有神圣法器，他们沉睡的灵魂就无法找到返回躯体的路。",al={"德鲁伊为什么需要圣物才能醒来","德鲁伊能自行醒来吗"}},{q="谁要求取回黑色羽毛？",a="多兰纳尔的阿斯瑞达斯·熊皮指引冒险者取回黑色羽毛和其他唤醒圣物，以解救身处险境的德鲁伊。",al={"谁需要羽毛","黑色羽毛任务发布者"}}},fx={["8b872c36"]={q="黑色羽毛是什么？",a="黑色羽毛是泰达希尔班奈希尔兽穴中的暗夜精灵猛禽德鲁伊所保存的四件神圣觉醒圣物之一。它被存放在一个专门的箱子里，是一种必要的仪式组件，用于平静地唤醒沉睡在翡翠梦境中的德鲁伊。",al={"黑色羽毛是什么","黑色羽毛物品","黑色羽毛背景"}}},fp="19,91,20.359.0,23.238.0,41.129.0,38.122.0,64.185.0,37.147.0"}
P.entries["item:blackened-skull"] = {n="焦黑的颅骨",s="在阿加曼德磨坊，焦黑的颅骨是对抗天灾军团的战利品。布瑞尔的亡灵卫兵迪林格尔需要这些颅骨，以证明暗眼骷髅法师正被消灭。",h="在阿加曼德磨坊，焦黑的颅骨是对抗天灾军团的战利品。布瑞尔的亡灵卫兵迪林格尔需要这些颅骨，以证明暗眼骷髅法师正被消灭。",kw={"阿加曼德磨坊","焦黑的颅骨","布瑞尔","暗眼唤骨者","亡灵卫兵迪林格尔","锯齿肋骨","天灾军团","磨坊告急"},ang={["class:Mage"]="身为Mage，你知道这些颅骨是阿加曼德磨坊那些被列为打击目标的骷髅施法者的遗骸。",["race:Undead"]="身为被遗忘者，你与暗眼骷髅法师作战，既是为了生存，也是为了阻止昔日的主人在你的家门口建立集结地。"},sec={{t="骷髅法师的战利品",b="暗眼骷髅法师在阿加曼德磨坊徘徊。这些骷髅施法者用充满恶意的通灵法术对付生者和被遗忘者，企图在提瑞斯法北部为巫妖王的大军建立前哨基地。布瑞尔的亡灵卫兵迪林格尔要求收集它们残破的颅骨，以证明天灾军团的法术先锋正被击退。"}},faq={{q="焦黑的颅骨从何而来？",a="焦黑的颅骨来自暗眼骷髅法师，这些骷髅施法者出没于提瑞斯法林地北部阿加曼德磨坊周围的田地和建筑中。",al={"焦黑的颅骨来源","谁掉落焦黑的颅骨","哪里获取焦黑的颅骨"}},{q="亡灵卫兵迪林格尔为什么需要焦黑的颅骨？",a="亡灵卫兵迪林格尔需要焦黑的颅骨和锯齿肋骨，以证明被遗忘者的守卫正在对抗天灾军团。被遗忘者必须阻止巫妖王那些没有心智的爪牙在如此靠近布瑞尔和幽暗城的地方站稳脚跟。",al={"迪林格尔的颅骨","为什么收集颅骨","磨坊告急颅骨"}},{q="这些颅骨为什么会焦黑？",a="布瑞尔没有人说起是什么烧黑了这些颅骨。亡灵卫兵迪林格尔需要这些颅骨，以证明阿加曼德磨坊的暗眼骷髅法师正被消灭。",al={"为什么会焦黑","焦黑的颅骨背景故事"}},{q="天灾军团在阿加曼德磨坊做什么？",a="天灾军团正试图加固废弃的阿加曼德磨坊，将其作为前沿集结地，向提瑞斯法林地各处发动更深入的进攻和突袭。",al={"阿加曼德磨坊的天灾军团","天灾军团为什么在磨坊"}}},fx={d39fbd85={q="什么是焦黑的颅骨？",a="焦黑的颅骨是从徘徊在阿加曼德磨坊的暗眼白骨法师身上收获的残酷战利品。这些黑暗的遗骸对于被遗忘者的死亡卫兵来说是实物证明，表明另一个天灾军团的施法者在还没来得及帮助建立敌方基地之前就已经被干掉了。",al={"什么是焦黑的颅骨","焦黑的颅骨物品","焦黑的颅骨背景"}}},fp="15,179,25.332.0,36.153.0,52.236.0,29.155.0,43.141.0"}
P.entries["item:bloodfeather-belt"] = {n="血羽腰带",s="在泰达希尔北部，血羽鹰身人聚集在神谕林地，身上系着粗制皮革腰带。哨兵阿瑞尼亚·碎云收集这些腰带，作为附近巢穴已被清剿的证明。",h="在泰达希尔北部，血羽鹰身人聚集在神谕林地，身上系着粗制皮革腰带。哨兵阿瑞尼亚·碎云收集这些腰带，作为附近巢穴已被清剿的证明。",kw={"阿瑞尼亚·碎云","血羽","血羽腰带","鹰身人","神谕林地","泰达希尔"},ang={["faction:Alliance"]="帮助哨兵阿瑞尼亚·碎云，就能让来自泰达希尔古树的重要报告顺利送达达纳苏斯的领袖手中。",["race:NightElf"]="血羽族群玷污了泰达希尔的天然树冠。清剿她们的巢穴，夺回神谕林地，是每一位Kaldorei家园守护者的职责。"},sec={{t="巢穴中的战利品",b="血羽鹰身人在神谕林地周围的枝杈间筑巢，四处滋事。她们的存在威胁着古老的神谕之树，也阻断了泰达希尔北部的通行。这群鹰身人伏击并杀死了一名向达纳苏斯递送报告的信使后，哨兵阿瑞尼亚·碎云号召旅人出击，清剿巢穴。从死去的鹰身人身上取下的腰带，证明她们的数量正在减少，道路也在逐渐恢复安全，让消息能够再次送达首都。"}},faq={{q="哨兵阿瑞尼亚·碎云为什么需要这些腰带？",a="阿瑞尼亚·碎云和她率领的一小队哨兵守护着神圣的神谕之树，抵御附近巢穴中的血羽鹰身人。鹰身人杀死了一名赶往达纳苏斯的信使后，阿瑞尼亚请旅人带回腰带，作为清剿巢穴、削减鹰身人数量的证明。",al={"阿瑞尼亚为何需要腰带","血羽腰带用途","为何收集腰带"}},{q="血羽腰带从哪里来？",a="泰达希尔北部，神谕林地周围树木与峭壁间的血羽鹰身人都带着这些腰带。群落中的每一类鹰身人都带着一条，包括风巫、女巫、潜行者和狂怒者。",al={"谁掉落血羽腰带","哪里获取腰带","血羽腰带位置"}},{q="鹰身人为什么会威胁神谕林地？",a="鹰身人在神谕之树附近筑起了巢穴，这棵古树守望着世界之树的健康。她们的侵袭使守卫林地的哨兵陷入孤立，并以暴力阻断送往达纳苏斯的消息。",al={"神谕林地鹰身人","泰达希尔为何有鹰身人","鹰身人威胁神谕之树"}}},fx={["40b720b3"]={q="什么是血羽腰带？",a="血羽腰带是栖息在泰达希尔北部的神谕林地的血羽鹰身人所佩戴的个人装饰品。对于驻扎在林地的暗夜精灵来说，这些粗糙的腰带是战利品，也是另一个邪恶的鹰身人从神圣枝头被剔除的有力证明。",al={"血羽腰带信息","血羽腰带是什么","血羽腰带背景"}}},fp="17,183,23.458.0,54.285.0,38.201.0,46.225.0"}
P.entries["item:bloodfury-ripper-s-remains"] = {n="血怒撕裂者的遗体",s="在烈日石居，马格兰寻求血怒撕裂者的遗体，以此证明血怒鹰身人的首领已死。她的死将打击威胁牛头人定居点的势力。",h="在烈日石居，马格兰寻求血怒撕裂者的遗体，以此证明血怒鹰身人的首领已死。她的死将打击威胁牛头人定居点的势力。",kw={"血怒撕裂者","焦炭谷","鹰身人","马格兰","遗体","石爪山","烈日石居"},ang={["faction:Horde"]="清除血怒族母这样的荒野威胁，有助于保障部落商队与斥候往返贫瘠之地和石爪山的道路安全。",["race:Tauren"]="血怒鹰身人直接威胁着烈日石居。收集她们首领的遗体，有助于保护石爪山那些和平的牛头人定居点。"},sec={{t="斩断血脉",b="血怒撕裂者率领焦炭谷的鹰身人，凶狠地攻击侵入领地的外来者。她们在焦黑的废墟间筑巢，威胁着石爪山脉各处的旅人与萨满祭司。削减鹰身人的数量能暂时缓解危险，但烈日石居的马格兰知道，只有除掉她们的首领，才能换来长久的安宁。血怒撕裂者几乎如同女王一般统治着鹰身人，指挥她们攻击领地上的入侵者。她的遗体证明她已死去，使鹰身人陷入混乱，也让那些致力于修复和守护崎岖家园的牛头人更加安心。"}},faq={{q="血怒撕裂者的遗体有什么用途？",a="血怒撕裂者的遗体证明这位鹰身人首领已死。烈日石居的马格兰寻求这具遗体，以确认这位如同女王般的族母已被除掉。",al={"遗体有什么用","遗体用途","谁想要遗体"}},{q="在哪里可以找到血怒撕裂者？",a="血怒撕裂者在石爪山脉南部焦炭谷的西部和西北部山脊一带徘徊。她的羽毛呈蓝色，与族群中其他鹰身人的红白羽毛截然不同。",al={"血怒撕裂者位置","撕裂者在哪里","寻找血怒撕裂者"}},{q="马格兰为什么想要除掉她？",a="马格兰认为，仅仅削减普通鹰身人的数量，无法阻止她们袭击周边地区。他希望杀死血怒撕裂者，瓦解她们的统治体系，削弱她们集结起来对抗烈日石居的能力。",al={"为什么杀死血怒撕裂者","马格兰的动机","为什么要撕裂者死"}}},fx={ba88af47={q="血怒撕裂者的遗体是从哪里获得的？",a="这些遗体是在焦炭谷的西山击杀血怒撕裂者本人后采集的。与她那红白色的同类不同，这只蓝羽的鸟身人女王统治着焦炭谷荒凉悬崖上的血怒鸟身人部落，这使她成为了任何试图瓦解该鸟身人群体指挥权的人眼中的珍贵目标。",al={"血怒撕裂者的遗体来源","掉落血怒撕裂者遗体的怪物","血怒撕裂者遗体的背景"}},["81140692"]={q="马格兰为什么要血怒撕裂者的遗体？",a="烈日石居的马格兰需要这些遗体作为证明，证明血怒鸟身人的女族长确实已经死了。仅仅消减它们的数量是不够的；马格兰相信，击杀她们的女王会让幸存的鸟身人无所适从，导致她们的数量逐渐减少，从而让他从困扰他的苦涩愤怒中解脱出来。",al={"马格兰索要血怒撕裂者遗体的原因","为什么需要血怒撕裂者遗体","谁想要血怒撕裂者的遗体"}},ff70f27b={q="血怒撕裂者的遗体是什么？",a="这些可怕的遗骸是从血怒撕裂者的尸体上取下的实物证明，它是盘踞在焦炭谷的血怒鹰身人的族长兼首领。她几乎就像是鸟群的女王，引导着它们在石爪山脉大肆扩张。她被杀后的遗体无可辩驳地证明了她对山谷鹰身人的统治已经以血腥的终局告终。",al={"血怒撕裂者的遗体是什么","血怒撕裂者的遗体这是什么","谁是血怒撕裂者"}}},fp="26,161,22.583.0,45.136.0,36.184.0,43.222.0"}
P.entries["item:bloodstone-choker"] = {n="血石颈环",s="在暴风城，黑暗缚灵者加科因的血石颈环将术士的仪式与虚空相连。他的学徒偷走了这件护符，投奔了迪菲亚潜行者。",h="在暴风城，黑暗缚灵者加科因的血石颈环将术士的仪式与虚空相连。他的学徒偷走了这件护符，投奔了迪菲亚潜行者。",kw={"血石颈环","迪菲亚潜行者","黑暗缚灵者加科因","苏伦娜·凯尔东","誓缚","已宰的羔羊","虚空行者","术士"},ang={["class:Warlock"]="作为联盟术士，夺回血石颈环标志着你从掌握基础法术迈向支配强大的恶魔仆从。",["faction:Alliance"]="苏伦娜·凯尔东投奔迪菲亚潜行者，表明艾尔文森林的亡命之徒正在搜寻危险的秘术遗物，以增强反抗暴风城的力量。"},sec={{t="被盗的媒介",b="黑暗缚灵者加科因是暴风城已宰的羔羊地下的一位术士导师，曾持有血石颈环。他的学徒苏伦娜·凯尔东背叛了他，偷走了颈环。她带着这件附魔护符逃入艾尔文森林，加入了迪菲亚潜行者。如今，她就在布莱克威尔南瓜田。必须在强盗利用颈环的力量之前将它夺回。"},{t="驯服虚空",b="这枚颈环由血石雕成，连接着凡人世界与扭曲虚空中扭曲的暗影。在酒馆地下的墓穴中，黑暗缚灵者加科因在召唤法阵处引导它的魔力。一个充满敌意的虚空行者响应召唤，从虚空中现身。术士必须持有护符，与这个狂怒的生物正面交战，将其制服。唯有如此，才能证明自己拥有支配这种守卫的意志。"}},faq={{q="血石颈环是什么？",a="血石颈环是一条经过附魔的血石项链，术士将它用作仪式的媒介。它的魔力能够撕裂现实，从虚空召来一个桀骜不驯的虚空行者。",al={"血石颈环","颈环是什么","颈环有什么作用"}},{q="颈环最初属于谁？",a="颈环最初属于黑暗缚灵者加科因。他在暴风城法师区的已宰的羔羊地下的一间隐秘地下室中训练术士。",al={"颈环属于谁","黑暗缚灵者加科因的颈环","颈环的来历"}},{q="颈环为何被盗？",a="苏伦娜·凯尔东从导师黑暗缚灵者加科因手中偷走颈环，随后逃去加入了迪菲亚潜行者。她在藏身艾尔文森林的强盗之中寻求力量。",al={"谁偷走了颈环","苏伦娜为何偷走颈环","苏伦娜·凯尔东的颈环"}},{q="颈环如何用于术士训练？",a="术士在已宰的羔羊地下墓穴的召唤法阵上方激活夺回的颈环。它会引出一个虚空行者，术士学徒必须击败并制服它，才能支配这个恶魔。",al={"如何使用颈环","虚空行者仪式颈环","誓缚颈环"}}},fx={["9d3659ea"]={q="为什么需要血石颈环？",a="黑暗缚灵者加科因将血石颈环视为召唤并奴役虚空行者所需的强大魔法催化剂。在他以前的学徒苏雷娜·卡雷登为了帮助迪菲亚兄弟会偷走它之后，加科因寻求将其夺回，以恢复他的奥术权威，并以此在已宰的羔羊地下室中考验新的术士。",al={"为什么需要血石颈环","谁在找血石颈环","加科因想要颈环的原因"}}},fp="17,164,16.382.1,15.394.0,30.174.0,32.144.0,26.157.0,43.209.0"}
P.entries["item:blueleaf-tuber"] = {n="蓝叶薯",s="蓝叶薯生长在剃刀沼泽地下，隐于地表之下。它们十分稀有，吸引着世界各地的富有美食家和商人。",h="蓝叶薯生长在剃刀沼泽地下，隐于地表之下。它们十分稀有，吸引着世界各地的富有美食家和商人。",kw={"贫瘠之地","蓝叶薯","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","地鼠","块茎"},ang={["profession:Cooking"]="蓝叶薯虽然生长在野猪人巢穴的贫瘠泥土中，却是最富有的美食家竞相追求的珍稀美味。"},sec={{t="珍稀的地下美味",b="蓝叶薯生长在贫瘠之地的剃刀沼泽地下。茂密的根系和野猪人的荆棘丛让寻常采集者难觅其踪。尽管生长环境恶劣，世界各地的富有美食家和商人仍愿为它们独特的风味支付高昂的价钱。"},{t="地鼠协助采收",b="在棘齿城，地精麦伯克·米希瑞克斯想出了寻找这些隐秘块茎的办法。他训练当地的 地鼠，让它们能在五十步之外嗅出块茎的气味。冒险者使用专门的指挥棒引导它们，就能在野猪人巡逻队察觉入侵之前挖出块茎。"}},faq={{q="蓝叶薯有什么用途？",a="蓝叶薯独特的味道和稀缺性吸引着富有的顾客和经营奇珍异货的商人，他们愿意为此支付高价。",al={"块茎用途","为什么采集 蓝叶薯","块茎有什么用"}},{q="哪里能找到蓝叶薯？",a="蓝叶薯生长在南贫瘠之地的剃刀沼泽地下深处，藏于荆棘丛和地下巢穴之间。",al={"蓝叶薯 生长在哪里","块茎位置","块茎在哪里"}},{q="为什么需要地鼠来挖掘它们？",a="蓝叶薯藏在表土之下，人类和地精都看不见它们。受过训练的 地鼠 能在五十步之外嗅出它们的气味，并听从命令将它们挖出来。",al={"为什么需要 地鼠","地鼠用途","为什么需要地鼠"}},{q="谁会购买这些块茎？",a="地精商人麦伯克·米希瑞克斯常驻棘齿城，收购蓝叶薯，再转卖给富有的买家和海外客户，从中赚取丰厚利润。",al={"谁想要 蓝叶薯","谁收购块茎","麦伯克 块茎"}}},fx={["9eab4987"]={q="什么是蓝叶薯？",a="蓝叶薯是一种极其罕见的可食用根茎，埋藏在剃刀沼泽的地下深处。它因其烹饪价值而备受推崇，在世界各地都被视为美味佳肴，尽管由于剃刀沼泽原生地中充斥着野猪人，采集它变得十分危险。",al={"蓝叶薯是什么","蓝叶薯背景知识","关于蓝叶薯的信息"}},["094c1930"]={q="蓝叶薯是从哪里来的？",a="蓝叶薯是南贫瘠之地特有的天然地下根茎，生长在剃刀沼泽错综复杂的根系深处。它们并非由人培育，而是使用训练有素的地穴地鼠嗅探出来，并直接从地下土壤中采集。",al={"蓝叶薯的起源","蓝叶薯的生长地","谁制作了蓝叶薯"}}},fp="14,102,27.246.0,26.291.0,34.113.0,35.121.0,40.170.0,22.151.0"}
P.entries["item:book-from-sven-s-farm"] = {n="斯温农场中的书",s="在暮色森林，斯温的农场废墟中藏着一本沾满泥土、没有书名的日记。残存的篇章记下了一名身份不明的旁观者目睹斯温·约根一家遇袭的片段。",h="在暮色森林，斯温的农场废墟中藏着一本沾满泥土、没有书名的日记。残存的篇章记下了一名身份不明的旁观者目睹斯温·约根一家遇袭的片段。",kw={"斯温农场中的书","夜色镇","迪菲亚潜行者","暮色森林","基特斯","暗中的身影","斯温·约根","狼人"},ang={["faction:Alliance"]="身为联盟调查者，你可以借助这本饱经风雨的书，追查盘踞暮色森林南部的恐怖，并查明凶野的狼人群如何在此站稳脚跟。"},sec={{t="泥土中的线索",b="暮色森林南部，斯温农场烧焦的残骸间，一堆松土下藏着一本饱经风雨的日记。不具名的作者留下了仓促而残缺的笔记，记录农庄里发生的惨剧。这些书页印证了斯温·约根的怀疑：他的家人被杀时，有人在暗处旁观。记述戛然而止，没有交代作者是谁，也没有说明后来发生了什么。斯温提供的线索让调查者带着书前往夜色镇，希望那里有人能认出笔迹。"},{t="追查暗中的身影",b="夜色镇的秘法师和镇民帮助查明，日记的主人是个曾惊恐地逃过树林的陌生人。书页上模糊的印痕将线索引向基特斯，一个藏身林中的流浪汉。基特斯遗失的篇章讲述了迪菲亚潜行者如何染指禁忌神器，意外将饥肠辘辘的狼人释放到暮色森林。找到他后，这些残篇便汇成了他的完整日记。"}},faq={{q="在哪里能找到斯温农场中的书？",a="这本书埋在暮色森林南部斯温·约根的农场废墟里的一堆松土下。",al={"哪里能找到斯温的书","斯温农场土堆","斯温的书位置"}},{q="斯温农场里找到的书是谁写的？",a="这本书没有书名，也没有作者姓名。作者是个惊恐的男人，他逃离了暮色森林别处的恐怖遭遇，躲进斯温的谷仓，目睹斯温一家惨遭杀戮，并遗失了日记。",al={"斯温的书作者","沾满泥土的书是谁写的","日记是谁写的"}},{q="斯温·约根为什么想要这本书？",a="家人遇袭后，斯温在谷仓附近看到了一个身份不明的身影。这本书证实了那名旁观者确实存在，也给了斯温一条确凿的线索，去查明那一夜发生的事。",al={"斯温为什么在意","斯温·约根对书的反应"}},{q="调查这本书之后会发生什么？",a="将这本残缺的日记给夜色镇的居民看过，并找到它的主人基特斯后，《基特斯的完整日记》便会取而代之，讲述完整的故事。",al={"什么会替代斯温的书","斯温的书是否保留"}},{q="书中的内容牵涉着什么更大的秘密？",a="完整的日记讲述了作者为何躲藏起来，以及斯温一家为何遭到袭击。书中的故事超出了一座农场的范围，牵涉到笼罩暮色森林的黑暗。",al={"斯温的书里有什么故事","狼人关联","迪菲亚潜行者关联"}}},fx={fd4c7f5f={q="什么是斯温农场中的书？",a="这是一本未标标题、沾满泥土的日记，从暮色森林斯温·约根破败的家园遗址中挖掘出来。尽管破旧且残缺不全，但其手写页面包含了一份关于斯温农场和家庭所遭遇恐怖事件的目击记录。更重要的是，它作为确凿的证据，表明在屠杀期间有一个身份不明的旁观者在场，这掌握着关于谁袭击了农场以及原因的关键答案。",al={"斯温农场中的书是什么","暮色森林沾满泥土的书","什么是沾满泥土的书"}}},fp="21,125,18.498.0,29.422.1,41.83.0,40.190.1,36.175.0,50.149.1,55.161.1"}
P.entries["item:book-stresses-of-iron"] = {n="《金属的延展性》",s="暴风要塞中，马戈尔夫·布拉贡所著的冶金学书籍已借往北郡修道院，供人抄写。",h="暴风要塞中，马戈尔夫·布拉贡所著的冶金学书籍已借往北郡修道院，供人抄写。",kw={"克里斯托弗修士","帕克斯顿修士","马戈尔夫·布拉贡","冶金学","米尔顿·西弗","北郡修道院","皇家图书馆","铁的压力"},ang={["profession:Blacksmithing"]="马戈尔夫·布拉贡的书探讨了铁的强度，以及加工铁时的实际限制。"},sec={{t="借出的书卷",b="马戈尔夫·布拉贡撰写了关于冶金实践与理论的著作。米尔顿·西弗在暴风要塞的皇家图书馆保管这本书。图书馆将它借给了北郡修道院，帕克斯顿修士在那里亲手抄写，供自己收藏。抄写耗时远超预期。因此，克里斯托弗修士在教堂广场焦急地等待这本书归还城中。"}},faq={{q="这本书讲的是什么？",a="马戈尔夫·布拉贡的书涵盖了冶金与金属加工的理论和实践。",al={"什么是金属的延展性","金属的延展性主题","书籍内容"}},{q="这本书为什么会在北郡修道院？",a="帕克斯顿修士从暴风城的皇家图书馆借走这本书，打算亲手抄写一份，供自己收藏。他应在抄完后归还原书。",al={"帕克斯顿为什么拿着这本书","为什么在北郡"}},{q="谁希望归还这本书？",a="克里斯托弗修士希望这本书能归还。他在教堂广场等候，急切地催促归还。一位冒险者往返于皇家图书馆和北郡之间，追查这本书的下落。",al={"谁需要这本书","谁在等这本书"}}},fx={["7d684098"]={q="铁的应力来自哪里，是谁写的？",a="这本书是由马戈尔夫·布拉贡撰写的关于冶金学的学术论著。它的存放地是皇家图书馆内部，不过帕克斯顿修士借走了这卷书并带到了北郡修道院，以便为自己的书架细心誊抄一份副本。",al={"谁写了金属的延展性","金属的延展性的作者","金属的延展性的起源"}}},fp="22,98,17.376.0,23.83.0,37.146.0,29.178.0"}
P.entries["item:bottle-of-disease"] = {n="一瓶病菌",s="被遗忘者炼金师在灰谷的朵丹尼尔兽穴附近配制病菌。他们营地中发现的瓶子里装着剧毒混合物。",h="被遗忘者炼金师在灰谷的朵丹尼尔兽穴附近配制病菌。他们营地中发现的瓶子里装着剧毒混合物。",kw={"灰谷","瘟疫","一瓶病菌","朵丹尼尔兽穴","林歌神殿","被遗忘者","被遗忘者 病菌","凯尼斯·静风"},ang={["class:Druid"]="身为德鲁伊，你知道带有瘟疫的混合物和人造瘟疫违背了自然平衡。你必须迅速行动，保护这片林地。",["race:NightElf"]="身为暗夜精灵，你知道亡灵病菌侵染灰谷的土地是不可饶恕的冒犯，尤其是在朵丹尼尔兽穴附近。"},sec={{t="圣林中的瘟疫",b="在朵丹尼尔兽穴附近，被遗忘者炼金师在战歌氏族前线后方的一处哨站中配制传染病菌。这些瓶子为林歌神殿的暗夜精灵提供了证据，表明敌人意图侵染林地的土壤和野生生物，而非与他们的哨兵正面交锋。"},{t="凯尼斯·静风的调查",b="凯尼斯·静风是林歌神殿的一名暗夜精灵哨兵，他正在寻找被遗忘者野心的证据。他需要一瓶病菌，以便研究其中的成分。暗夜精灵担心这些混合物会腐化神圣的兽穴，摧残森林守护者的身心。"}},faq={{q="一瓶病菌里装着什么？",a="被遗忘者药剂师在瓶中配制合成毒药和魔法病菌。皇家药剂师学会则在更大范围内开展剧毒瘟疫实验。",al={"瓶子里有什么","一瓶病菌的内容物","被遗忘者 药水"}},{q="这些瓶子在哪里能找到？",a="这些瓶子位于林歌神殿以南一处偏僻的被遗忘者营地中，靠近灰谷东部的朵丹尼尔兽穴入口。",al={"哪里能找到一瓶病菌","一瓶病菌的位置","灰谷 被遗忘者 营地"}},{q="谁需要一瓶病菌？",a="凯尼斯·静风是林歌神殿的一名暗夜精灵守卫，他希望你取回一个瓶子，以便检验其中的成分，查明部落的意图。",al={"谁收取一瓶病菌","交付一瓶病菌","凯尼斯·静风 任务"}},{q="被遗忘者为何在灰谷配制病菌？",a="暗夜精灵怀疑被遗忘者意图侵染神圣的森林，亵渎附近的兽穴，毒害生态环境，从内部削弱暗夜精灵的抵抗力量。",al={"被遗忘者 为何在灰谷","亡灵在灰谷的目的","被遗忘者 兽穴"}}},fx={["4091970d"]={q="什么是一瓶病菌？",a="这是一瓶密封的药剂，里面装有被遗忘者调制的剧毒和瘟疫。幽暗城的特工在灰谷各处的秘密营地中酿造这些邪恶的混合物，将其装瓶以便运输并蓄意传播到古老的精灵林地中。",al={"一瓶病菌是什么","一瓶病菌背景故事","一瓶病菌信息"}},["62494cf6"]={q="一瓶病菌来自哪里，是谁制作的？",a="这瓶药剂是由驻扎在林歌神殿以南，靠近朵丹尼尔兽穴的隐秘营地中的被遗忘者药剂师酿造的。这些不死炼金术士潜伏在神圣的暗夜精灵古墓附近，在卡利姆多大地上积极采集并提炼危险的毒药和瘟疫。",al={"谁制造了一瓶病菌","一瓶病菌的来源","一瓶病菌从何而来"}},["9d281de4"]={q="为什么凯内斯·静风想要一瓶病菌？",a="林歌神殿的凯内斯·静风需要一份完整的样本来分析被遗忘者在策划什么。通过测试这种药剂的炼金属性，暗夜精灵希望确认这些亡灵是否企图污染灰谷本身，并准备有效的应对措施。",al={"为什么要一瓶病菌","为什么要获取一瓶病菌","凯内斯想要病菌的原因"}}},fp="17,129,26.290.0,33.266.1,37.163.0,30.145.0,32.152.0,51.191.0"}
P.entries["item:bottle-of-moonshine"] = {n="一瓶月光酒",s="湖畔镇的酒馆正寻求夜色镇出产的月光酒。酒吧老板丹尼尔需要一瓶，因为黑石兽人的入侵让常规补给无法运抵镇上。",h="湖畔镇的酒馆正寻求夜色镇出产的月光酒。酒吧老板丹尼尔需要一瓶，因为黑石兽人的入侵让常规补给无法运抵镇上。",kw={"酒吧老板丹尼尔","一瓶月光酒","夜色镇","旱季","暮色森林","湖畔镇","月光酒","血鸦旅店"},ang={["faction:Alliance"]="从夜色镇到湖畔镇的这段路途，显出了危机之中暴风城各处分散聚落之间的补给线有多么脆弱。"},sec={{t="烈酒解忧",b="黑石兽人截断了湖畔镇的常规补给商队。酒吧老板丹尼尔四处寻找各地的酒，为酒馆补充存货，供卫兵和镇民饮用。其中一种酒由夜色镇的血鸦旅店酿造并出售，当地人偏爱烈酒。"}},faq={{q="在哪里能找到一瓶月光酒？",a="在暮色森林夜色镇的血鸦旅店可以找到一瓶月光酒。",al={"哪里买月光酒","夜色镇月光酒位置","一瓶月光酒商人"}},{q="谁想要这瓶酒？",a="酒吧老板丹尼尔是赤脊山湖畔镇的旅店老板，他想在兽人围城期间用这瓶酒和其他地方出产的酒补充酒窖的存货。",al={"谁需要月光酒","月光酒任务交付","酒吧老板丹尼尔月光酒"}},{q="湖畔镇为什么快没酒了？",a="黑石兽人大举涌入赤脊山，袭击道路，切断商路。常规货运未能抵达，湖畔镇酒馆的酒架几乎空了。",al={"为什么 旱季","湖畔镇补给短缺","赤脊山酒类短缺"}}},fx={["1eb07341"]={q="什么是瓶装月光酒？",a="这是一种在暮色森林的夜色镇的血鸦旅店出售的烈性酒。虽然在这种宁静的湖畔度假地中，非法或辛辣的烈酒似乎有些格格不入，但困难时期需要烈酒来支撑。",al={"什么是月光酒","月光酒的信息","关于瓶装月光酒"}},["5d3a7e66"]={q="这瓶月光酒来自哪里？",a="这种特定的烈酒来自暮色森林中阴暗的夜色镇，由血鸦旅店提供。随着王国各地的本地供应线紧张，酒馆老板们只能四处寻找货源来填满他们的货架。",al={"谁制造月光酒","月光酒在哪里生产","月光酒起源"}},["08a7d809"]={q="为什么湖畔镇需要一瓶月光酒？",a="酒吧老板丹尼尔需要它来维持湖畔镇酒馆的运转。由于黑石兽人的入侵和贸易路线的中断，该镇的酒类供应几乎已经枯竭。丹尼尔派遣旅行者穿过人类领地去收集烈酒——包括这瓶来自夜色镇的月光酒——以满足他压力重重的客人们。",al={"为什么湖畔镇需要月光酒","为什么购买月光酒","谁需要月光酒"}}},fp="19,158,17.250.0,39.93.0,22.147.0,39.187.0"}
P.entries["item:bottle-of-zombie-juice"] = {n="一瓶僵尸酒",s="夜色镇的一瓶僵尸酒即将送往亚伯克隆比手中，他是一位隐居在暮色森林的隐士。这种烈酒用腐败之花酿成，亚伯克隆比说他需要靠它取暖。",h="夜色镇的一瓶僵尸酒即将送往亚伯克隆比手中，他是一位隐居在暮色森林的隐士。这种烈酒用腐败之花酿成，亚伯克隆比说他需要靠它取暖。",kw={"亚伯克隆比","一瓶僵尸酒","夜色镇","暮色森林","递送酒液","腐败之花","僵尸酒"},ang={["faction:Alliance"]="往返于夜色镇和幽暗荒野之间的差事，将暮色森林饱受困扰的居民联系起来，即使这些活计看上去疑点重重。",["profession:Herbalism"]="熟悉暮色森林的草药师都知道，腐败之花不适合用来配制普通的滋补药剂，因此用它酿酒令人不安。"},sec={{t="刺鼻的酒液",b="这种烈酒用采自暮色森林的腐败之花酿成。夜色镇的酒保警告说，这酒烈得足以让死人复生。大多数人都不愿碰这种令人作呕的酒，但性情古怪的隐士亚伯克隆比说，在那间孤零零的小屋旁度过潮湿寒冷的夜晚时，只有它能让自己暖和起来。"},{t="可疑的酒瘾",b="亚伯克隆比称这种烈酒是睡前暖身的佳酿。收到酒瓶时，他差点称赞送酒人的愚蠢，而非好心。他要这么烈的酒，究竟有什么用？"}},faq={{q="僵尸酒是用什么酿成的？",a="僵尸酒用腐败之花蒸馏而成，这种植物生长在暮色森林被腐化的土壤中，气味恶臭。",al={"僵尸酒 原料","僵尸酒 里有什么"}},{q="谁想让人送去这瓶酒？",a="亚伯克隆比想让人把这瓶酒送到他那间位于暮色森林西部边界的偏僻小屋。",al={"谁需要 僵尸酒","僵尸酒 是给谁的","递送 僵尸酒"}},{q="亚伯克隆比为什么想要僵尸酒？",a="亚伯克隆比声称，这种烈酒能让他这把老骨头熬过暮色森林寒冷漆黑的夜晚，不过他古怪的举止暗示，这么烈的酒或许另有用途。",al={"亚伯克隆比为什么喝它","亚伯克隆比需要 僵尸酒 的原因"}},{q="玩家能喝一瓶僵尸酒吗？",a="不能。这瓶酒是要送给亚伯克隆比的，你必须把它安全地带到他的小屋。",al={"僵尸酒 能喝吗","僵尸酒 是消耗品吗"}}},fx={f1488eba={q="什么是僵尸酒？",a="僵尸酒是一种在暮色森林中混合了腐败之花的烈性酒。它被描述为味道恶臭且极其强烈——据说强烈到足以让死者复活——这是一种酒馆老板处理时必须格外谨慎的令人不悦的混合物。",al={"僵尸酒是什么","僵尸酒的背景知识","关于那种酒"}},b862f5ea={q="僵尸酒来自哪里，是谁制作的？",a="这种酒是在夜色镇由当地的酒馆老板，旅店老板斯密茨酿造的，他用腐败之花蒸馏而成。它是专门根据订单准备的，用于运送到暮色森林阴森荒野中的亚伯克隆比的小屋。",al={"谁制作了僵尸酒","僵尸酒从何而来","谁酿造僵尸酒"}}},fp="22,162,20.292.0,19.194.1,31.104.0,32.96.0,39.175.0,45.75.0"}
P.entries["item:bottom-of-gelkak-s-key"] = {n="基尔卡克钥匙的尾部",s="在黑海岸，基尔卡克钥匙的尾部是一把破碎的发条钥匙的三块碎片之一。它属于遭遇海难的侏儒海盗基尔卡克·旋杆，被礁石蟹从岸边捡走。",h="在黑海岸，基尔卡克钥匙的尾部是一把破碎的发条钥匙的三块碎片之一。它属于遭遇海难的侏儒海盗基尔卡克·旋杆，被礁石蟹从岸边捡走。",kw={"螃蟹","黑海岸","大副","基尔卡克","旋杆","钥匙","找回","海难"},ang={["profession:Engineering"]="工程师会认出，这是专门为复杂的发条自动机提供动力的上弦工具的一部分。",["race:Gnome"]="身为侏儒，你或许会欣赏旋杆的做法：即便受困于危机四伏的海岸，他依然依靠精巧的发条机械，而非血肉之躯的船员。"},sec={{t="落入蟹螯",b="蛇颈龙在黑海岸近海击沉了基尔卡克·旋杆的船，将这个侏儒和他的财物冲上了岸。其中就有用来启动他的机械大副的发条钥匙。钥匙撞上海边的岩石，断成三截，当地的食腐动物随即聚拢到残骸周围。礁石蟹和潮汐蟹在潮线附近觅食时，夺走了钥匙的尾部。"},{t="重新组装",b="基尔卡克需要集齐钥匙的尾部、中部和顶部，才能启动他的机械船员。海边的鱼人拖走了中部，内陆的森林陆行鸟则拖走了顶部。这个侏儒海盗必须从岸边螃蟹的甲壳中撬出这块沉重的碎片，才能修复他的构造体，并为毁于一旦的远征复仇。"}},faq={{q="基尔卡克钥匙的尾部有什么用途？",a="基尔卡克钥匙的尾部是修复发条钥匙所需的三块碎片之一，这把钥匙属于受困的海盗基尔卡克·旋杆。修复后的钥匙可以重新启动他的机械大副。",al={"基尔卡克的钥匙有什么用","基尔卡克钥匙的尾部的用途","为什么需要基尔卡克钥匙的尾部"}},{q="这块钥匙碎片来自哪里？",a="礁石蟹从黑海岸的海边捡走了这块钥匙碎片。硬壳潮行蟹和狂暴暗礁蟹在水边四处觅食。",al={"哪里能找到基尔卡克钥匙的尾部","谁掉落基尔卡克钥匙的尾部","基尔卡克钥匙的尾部的位置"}},{q="钥匙为什么会断成三截？",a="蛇颈龙摧毁了基尔卡克的船，钥匙在他被冲上岸时撞上了岸边的岩石。它碎成几块，散落在当地的野生动物之间。",al={"基尔卡克的钥匙为什么断了","钥匙是怎么断的"}},{q="基尔卡克·旋杆是谁？",a="基尔卡克·旋杆是一个受困于黑海岸岸边的侏儒海盗。蛇颈龙摧毁了他的船，冲散了他的装备。",al={"基尔卡克是谁","基尔卡克·旋杆的故事"}}},fx={bb7c59d0={q="什么是基尔卡克钥匙的尾部？",a="这是属于失事的地精海盗基尔卡克·旋杆的一把机械钥匙的最末端碎片。当他的船在黑海岸附近沉没时，钥匙在撞击锯齿状岩石时破碎，而这块碎片是由当地的海岸爬行者从残骸中搜寻到的。",al={"什么是基尔卡克钥匙的尾部","基尔卡克钥匙的尾部信息","这个钥匙碎片是什么"}}},fp="22,195,19.345.0,10.337.1,44.191.0,36.141.0,40.159.0,23.122.0"}
P.entries["item:branch-of-cenarius"] = {n="塞纳留斯的树枝",s="在灰谷东部，加萨里斯手中握着树妖的圣物——塞纳留斯的树枝。安妮莉亚为守护这件圣物而死，临终前仍希望它能被夺回。",h="在灰谷东部，加萨里斯手中握着树妖的圣物——塞纳留斯的树枝。安妮莉亚为守护这件圣物而死，临终前仍希望它能被夺回。",kw={"安妮莉亚","灰谷","塞纳留斯的树枝","树妖","林歌神殿","加萨里斯","伊莉亚娜","萨特"},ang={["class:Druid"]="身为德鲁伊，你同样肩负着从玷污圣物的萨特手中夺回塞纳留斯的树枝的职责。",["race:NightElf"]="身为灰谷的暗夜精灵，你有神圣的职责去援助树妖，夺回她们祖传的珍宝。"},sec={{t="落入暗影的神圣枝条",b="塞纳留斯的树枝是追随森林之王的树妖们的圣物。安妮莉亚和她的姐妹伊莉亚娜一直珍视着它，直到堕落的萨特伏击了她们。他们的首领加萨里斯夺走了树枝，并在灰谷东部遭到污染的废墟附近重创了安妮莉亚，使她命不久矣。弥留之际，安妮莉亚指向北方，加萨里斯就潜伏在那边的拱门附近。她恳求有勇士能夺回树枝，将它归还给林歌神殿的树妖们。"}},faq={{q="塞纳留斯的树枝是什么？",a="塞纳留斯的树枝是灰谷树妖珍视的圣物。它承载着森林之王的名号与祝福，象征着树妖与古老森林之间的纽带。",al={"塞纳留斯的树枝背景故事","这根树枝是什么","树妖的树枝"}},{q="谁偷走了塞纳留斯的树枝？",a="加萨里斯在灰谷东部附近率众伏击树妖后，偷走了塞纳留斯的树枝。他给了安妮莉亚致命一击，随后带着树枝向北逃到了石拱门的另一侧。",al={"谁拿走了树枝","谁偷走了它","谁掉落塞纳留斯的树枝"}},{q="这根树枝属于谁？",a="这根树枝属于林歌神殿的树妖们。安妮莉亚为守护它而死，她的姐妹伊莉亚娜会遵照她的遗愿接收这件圣物。",al={"树枝交给谁","谁想要树枝","交给谁"}},{q="在哪里夺回这根树枝？",a="加萨里斯带着树枝，就在灰谷东部安妮莉亚倒下的那片废墟以北，靠近艾萨拉边界的地方。",al={"树枝位置","加萨里斯 在哪里","在哪里找到树枝"}}},fx={["4e4ec82f"]={q="为什么取回塞纳留斯的树枝如此重要？",a="灰谷的树妖们认为这根树枝是与她们的父亲塞纳留斯联系在一起的无价圣物。当树妖安妮莉亚在萨维亚附近被腐化的萨特重伤后，她临终的遗愿就是确保这根被偷走的树枝从加萨里斯手中夺回，并安全地送回林歌神殿的树妖手中。",al={"为什么取回塞纳留斯的树枝","为什么树妖想要树枝","塞纳留斯的树枝的作用"}}},fp="18,154,31.441.0,31.174.0,33.181.0,30.149.1,30.123.0"}
P.entries["item:brass-collar"] = {n="黄铜项圈",s="在布莱克威尔南瓜田，公主 戴着斯通菲尔德妈妈想要的项圈，那是这头母猪已被除掉的证据。",h="在布莱克威尔南瓜田，公主 戴着斯通菲尔德妈妈想要的项圈，那是这头母猪已被除掉的证据。",kw={"布莱克威尔南瓜田","黄铜项圈","艾尔文森林","斯通菲尔德妈妈","公主","公主 必须死","斯通菲尔德农场"},ang={["faction:Alliance"]="作为帮助艾尔文乡民的联盟冒险者，拿到 Princess 的项圈有助于平息相邻农场之间的争端。"},sec={{t="农家争端的战利品",b="公主 是布莱克威尔家体型硕大、获过奖的母猪。她在马科伦家宅以东游荡，常因贪吃而闯入斯通菲尔德农场的庄稼地。公主 吃掉了不少珍贵的蔬菜，斯通菲尔德妈妈因此寻找愿意杀死她的人。项圈能证明这头母猪已被杀死，再也不能糟蹋斯通菲尔德家的田地。"}},faq={{q="黄铜项圈从何而来？",a="公主 戴着这条项圈，出没于艾尔文森林东部、马科伦农场另一边的布莱克威尔南瓜田。",al={"黄铜项圈来源","谁掉落黄铜项圈","哪里获得黄铜项圈"}},{q="斯通菲尔德妈妈为什么想要这条项圈？",a="公主 会吃掉斯通菲尔德妈妈引以为傲的蔬菜。这条项圈能证明她已被杀死，无法再毁掉斯通菲尔德妈妈更多的收成。",al={"斯通菲尔德 为什么要项圈","斯通菲尔德妈妈的项圈用途"}},{q="公主 的主人是谁？",a="公主 属于布莱克威尔家，和体型较小的野猪伙伴一起在他们的南瓜田里游荡。",al={"公主 的主人","这头猪的主人是谁"}},{q="除了 公主，还有谁会掉落这件物品？",a="只有 公主 会掉落这条项圈。它是为布莱克威尔家那头体型硕大、备受珍视的母猪量身打造的。",al={"项圈的其他掉落来源","还有哪里能找到黄铜项圈"}}},fx={["92e34b72"]={q="什么是黄铜项圈？",a="黄铜项圈是布莱克威尔家族拥有的获奖母猪公主所佩戴的独特颈圈。由于公主体型庞大且有偷吃邻近庄稼的习惯，这个项圈成为了这头破坏性野兽终于被解决的确凿证据。",al={"黄铜项圈是什么","黄铜项圈的背景故事","谁戴着黄铜项圈"}}},fp="12,103,28.356.0,38.105.0,39.144.0,18.104.0,46.97.0"}
P.entries["item:bristleback-attack-plans"] = {n="刺背野猪人的进攻计划",s="刺背野猪人的进攻计划揭示了一场针对纳拉其营地的围攻。刺刃峡谷的野猪人绘制了粗糙的地图，写下了战术要点，企图攻陷这处牛头人聚居地。",h="刺背野猪人的进攻计划揭示了一场针对纳拉其营地的围攻。刺刃峡谷的野猪人绘制了粗糙的地图，写下了战术要点，企图攻陷这处牛头人聚居地。",kw={"进攻计划","刺刃峡谷","刺背","纳拉其营地","鹰风酋长","莫高雷","野猪人"},ang={["faction:Horde"]="作为部落的一员，挫败刺背的攻势，有助于在莫高雷的神圣平原上守住稳固的立足之地。",["race:Tauren"]="作为牛头人，揭露这场阴谋有助于保卫年轻牛头人接受最初试炼的训练场，并保护长者和新手免遭野猪人围攻。"},sec={{t="针对台地的阴谋",b="刺背野猪人计划对纳拉其营地发动持续进攻。他们的首领打算将红云台地边界的小规模冲突扩大，消灭在那里受训的年轻牛头人。这份计划藏在刺刃峡谷深处的一个土洞里。鹰风酋长可以向血蹄村传信，请求增援，让纳拉其营地有机会在入侵开始前挫败敌人的攻势。"}},faq={{q="刺背野猪人的进攻计划包含什么？",a="这份计划包含一张战术地图和围攻纳拉其营地的简陋指令，表明野猪人正在组织一场持久进攻，而非零星的袭击。",al={"进攻计划是什么","地图上有什么","刺背作战计划"}},{q="在哪里能找到这份计划？",a="这份计划放在刺刃峡谷一处高地洞穴的泥土地面上，从刺背酋长的小屋沿一条岔路往上走不远就能找到。",al={"计划在哪里","哪里能找到地图","刺背野猪人的进攻计划位置"}},{q="鹰风酋长收到计划后会怎么做？",a="鹰风酋长利用这份计划向血蹄村求援，召集战士，增援纳拉其营地的防御。",al={"鹰风会做什么","纳拉其营地的应对","鹰风酋长的反应"}},{q="刺背为什么要进攻纳拉其营地？",a="刺背宣称布满荆棘的峡谷是他们的领地，并将台地上的牛头人视为入侵者。他们打算赶走这里的居民。",al={"野猪人为什么进攻","刺背的动机"}}},fx={["166f21b1"]={q="刺背野猪人的进攻计划来自哪里？",a="这些计划源于刺刃峡谷深处，由刺背野猪人的战酋起草。它被放置在一张隐藏在洞穴网络中的粗糙地图上，详细记录了该部落对纳拉其营地的牛头人定居点发起长期围攻的协调计划。",al={"谁制作了刺背野猪人的进攻计划","刺背野猪人进攻计划的来源","谁写了刺背野猪人的进攻计划"}},aea2975f={q="为什么鹰风酋长需要刺背野猪人的进攻计划？",a="鹰风酋长需要这些计划，因为它们揭露了野猪人围攻纳拉其营地的阴谋。手握这一即将到来的威胁证据，酋长可以立即呼叫附近血蹄村的增援，以准备防御并在定居点被攻陷之前挫败这次攻击。",al={"为什么要刺背野猪人的进攻计划","鹰风酋长想要进攻计划的原因","刺背野猪人进攻计划的意图"}}},fp="24,173,23.385.0,45.170.0,28.145.0,55.125.1,47.142.0"}
P.entries["item:bristleback-belt"] = {n="刺背腰带",s="在纳拉其营地，年轻的牛头人收集刺背腰带，以证明自己的勇气。这些腰带来自刺刃峡谷的野猪人，是完成力量仪祭的一步。",h="在纳拉其营地，年轻的牛头人收集刺背腰带，以证明自己的勇气。这些腰带来自刺刃峡谷的野猪人，是完成力量仪祭的一步。",kw={"腰带","刺刃峡谷","刺背","纳拉其营地","鹰风酋长","野猪人","红云台地","力量仪祭"},ang={["faction:Horde"]="作为部落的一员，遏制莫高雷那些好斗的野猪人，有助于巩固部落在卡利姆多中部腹地的南部边界。",["race:Tauren"]="作为红云台地上的牛头人青年，取下倒下的刺背身上的腰带，是你迈向雷霆崖长者认可的第一步。"},sec={{t="仪式的凭证",b="红云氏族以古老的大地之母仪祭考验那些希望在雷霆崖赢得尊重的年轻人。第一项试炼力量仪祭要求每位受试者保护氏族，抵御威胁。刺背野猪人劫掠食物储备，还在纳拉其营地外伏击狩猎队。鹰风酋长要求夺取他们的腰带作为回击。向他交上十二条腰带，就能证明受试者有能力直面危险，协助保卫氏族。"},{t="野猪人的手艺",b="刺刃峡谷的刺背战士和萨满祭司佩戴着用粗糙兽皮、麻绳和零碎材料制成的腰带。牛头人战士几乎不会拿这种腰带当衣饰，但其野猪人制品的特征使它足以证明一名敌人已被杀死。将腰带带回营地中央，便满足了仪式对凭证的要求。"}},faq={{q="刺背腰带有什么用途？",a="纳拉其营地的鹰风酋长要求受试者交上十二条刺背腰带，以证明他们完成了力量仪祭，这是传统的大地之母仪祭中的第一项试炼。",al={"为什么需要刺背腰带","刺背腰带用途","这条腰带有什么用"}},{q="刺背腰带从何而来？",a="这些腰带由刺刃峡谷的刺背野猪人和萨满祭司佩戴，峡谷位于红云台地，就在纳拉其营地东面。",al={"哪里获取刺背腰带","谁掉落刺背腰带","刺背腰带位置"}},{q="鹰风酋长为什么要腰带，而不是头颅或武器？",a="腰带便于携带，能够证明受试者杀死了氏族的敌人。仪式要求收集腰带，但并未解释为何选择腰带而非其他战利品。",al={"为什么要腰带","鹰风酋长的凭证"}},{q="为什么要对付刺背野猪人？",a="刺背野猪人从刺刃峡谷向外侵占氏族的土地。他们在夜间袭击纳拉其营地，还在台地各处伏击牛头人的狩猎队。",al={"为什么杀死刺背野猪人","莫高雷野猪人威胁"}}},fx={["69faf7fa"]={q="什么是刺背腰带？",a="刺背腰带是栖息在刺刃峡谷中的刺背野猪人所穿戴的简单服饰。这些粗糙的皮革或绳索腰带是从被击败的袭击者身上剥下来的，它们是无可辩驳的战斗战利品，向部落长老证明了入侵的威胁已经得到对抗并被消灭。",al={"刺背腰带","什么是刺背腰带","刺背腰带物品"}},d50579da={q="刺背腰带从何而来，由谁制作？",a="这些腰带是由在刺刃峡谷（纳拉其营地以东）建立了一处荆棘丛生定居点的刺背野猪人制作的。他们的前线战士和萨满在与红云台地的牛头人发生冲突时都会佩戴它们。",al={"刺背腰带从何而来","谁制作刺背腰带","刺背腰带的起源"}}},fp="16,169,17.407.0,14.287.0,36.181.0,37.136.0,63.169.0,40.152.0"}
P.entries["item:bristleback-quilboar-tusk"] = {n="刺背野猪人的獠牙",s="在贫瘠之地北部和中部，刺背野猪人的獠牙取自被杀死的野猪人。曼科里克收集它们，作为杀戮的证明和复仇的信物。",h="在贫瘠之地北部和中部，刺背野猪人的獠牙取自被杀死的野猪人。曼科里克收集它们，作为杀戮的证明和复仇的信物。",kw={"贫瘠之地","刺背","被仇恨吞噬","十字路口","曼科里克","野猪人","獠牙"},ang={["faction:Horde"]="野猪人威胁着十字路口和遍布贫瘠之地的补给路线。收集獠牙既能帮助曼科里克复仇，也能助力部落平定这片地区。",["race:Orc"]="身为兽人，你深知血债的分量，也懂得战士的悲痛。曼科里克力求收集六十件野猪人战利品，这触动了你们共有的荣誉感。"},sec={{t="复仇的战利品",b="刺背野猪人在贫瘠之地各处守卫自己的领土，抵抗部落的扩张。它们参差不齐的象牙色獠牙是近身搏斗的武器。曼科里克是一名驻守十字路口的兽人老兵，他的妻子死于野猪人的一次凶残伏击。他收集数十根獠牙作为报复，用这血腥的计数，衡量他要让刺背野猪人偿还的苦痛。"}},faq={{q="谁想要这些獠牙？",a="曼科里克想要这些獠牙，他是贫瘠之地十字路口的一名兽人战士。一次伏击让他与妻子失散，此后他便向刺背野猪人寻求复仇。",al={"谁需要 刺背 獠牙","谁收刺背野猪人的獠牙","獠牙交付"}},{q="曼科里克为什么想要这么多獠牙？",a="野猪人掠夺者击败了曼科里克，以为他已经死去，便将他弃之不顾，此后悲痛与愤怒吞噬了他。六十根獠牙能向他证明，刺背部族正在遭到屠戮，为此付出代价。",al={"为什么要六十根獠牙","曼科里克为什么要獠牙","曼科里克复仇"}},{q="哪些野猪人长着这些獠牙？",a="刺背部族的成员长着这些獠牙，它们出没于贫瘠之地北部和中部的灌木荒地与荆棘营地。",al={"刺背 獠牙哪里掉落","谁掉落刺背野猪人的獠牙"}},{q="除了供曼科里克复仇，这些獠牙还有别的用途吗？",a="曼科里克收集这些战利品，只为复仇。野猪人的獠牙有时会被制成部族饰物，或充当贸易货物，但这些獠牙不会被用于这些用途。",al={"刺背 獠牙用途","野猪人獠牙能用于制作吗"}}},fx={a893c973={q="什么是刺背野猪人的獠牙？",a="这些是从在贫瘠之地游荡的被杀死的刺背野猪人身上割下的獠牙。对于野猪人来说，这是天生的特征和凶猛的标志，但对于平原上的猎人来说，它们是证明又有一头野兽被杀死的惨烈实证。",al={"刺背野猪人的獠牙","什么是刺背野猪人的獠牙","刺背獠牙"}},fe8719fb={q="刺背野猪人的獠牙从何而来？",a="它们是直接从贫瘠之地各地刺背野猪人的下颚上收割的。野猪人天生就会长出这些尖锐的獠牙，要获取它们，就必须在战斗后从被击败的敌人身上割下来。",al={"刺背獠牙从何而来","谁掉落刺背野猪人的獠牙","刺背野猪人的獠牙来源"}}},fp="25,165,21.348.0,22.171.0,36.170.0,33.123.0,63.154.0"}
P.entries["item:brock-s-list"] = {n="布洛克的名单",s="在塞尔萨玛，布洛克·寻石者送出了一份采矿学徒名单，名单上的学徒将获赠来自铁炉堡公会大厅的矿锄，以示嘉奖。",h="在塞尔萨玛，布洛克·寻石者送出了一份采矿学徒名单，名单上的学徒将获赠来自铁炉堡公会大厅的矿锄，以示嘉奖。",kw={"布洛克的名单","高尼尔·石趾","大锻炉","铁炉堡","洛克莫丹","采矿","塞尔萨玛","索格拉姆·伯雷森"},ang={["profession:Mining"]="身为勘探者，你能看出，布洛克的名单表彰的是那些凭本领在深山矿工协会的传统中赢得一席之地的学徒。",["race:Dwarf"]="身为矮人，你知道这份名单表彰的是那些在卡兹莫丹地下潜心挥动矿锄与铁铲的年轻矿工。"},sec={{t="矿工的殊荣",b="在卡兹莫丹，学徒必须证明自己的技艺，才能在矿井中承担重任。布洛克将课业出众的学徒记录在册。他把名单托付给前往铁炉堡的旅人，好将获此殊荣者的名字刻在矿锄上。"},{t="通往Great Forge之路",b="一头狮鹫从塞尔萨玛的栖所出发，将布洛克的名单送到铁炉堡Great Forge的深山矿工协会，交给高尼尔·石趾。在那里，学徒们的名字会被刻在各自的荣誉锄上。"}},faq={{q="布洛克的名单是什么？",a="塞尔萨玛的采矿训练师布洛克·寻石者会编写一份名册，记录那些采矿课业出众、赢得荣誉锄的学徒。",al={"布洛克的名单","这是什么物品","布洛克的名单用途"}},{q="我该把布洛克的名单交给谁？",a="将布洛克的名单出示给塞尔萨玛的狮鹫管理员索格拉姆·伯雷森，安排飞行行程。然后将名单带到铁炉堡大锻炉的深山矿工协会，交给高尼尔·石趾。",al={"名单送往何处","布洛克的名单交给谁","布洛克的名单交付"}},{q="高尼尔·石趾为什么需要这份文件？",a="高尼尔·石趾负责管理铁炉堡深山矿工协会的工具。他已经备好荣誉锄，需要布洛克的名册，好将每位学徒的名字刻在一把矿锄上。",al={"为什么是高尼尔","铁炉堡为何需要名单"}},{q="为什么要用狮鹫递送名单，而不徒步送去？",a="穿过洛克莫丹的山路与丹莫罗相连。从索格拉姆·伯雷森的栖所出发的狮鹫，能将名单迅速而安全地送到大锻炉。",al={"为何飞往铁炉堡","为何乘坐狮鹫"}}},fx={bca439a3={q="布洛克的名单从何而来，由谁制作？",a="这份名单是由布洛克·寻石者书写的，他是一位在洛克莫丹的塞尔萨玛镇工作的资深矿工。当年轻的矮人来到他的门下学习手艺时，布洛克会评估他们的进步，并起草这份名册，记录下那些因辛勤工作而获得特别认可的杰出学生。",al={"谁制作了布洛克的名单","布洛克的名单从何而来","布洛克的名单创造者"}}},fp="12,110,21.250.0,27.201.0,21.139.0,33.190.0,46.171.0,49.159.0"}
P.entries["item:broken-and-battered-samophlange"] = {n="破碎的主动式负载平衡器",s="在贫瘠之地北部，荆棘谷地精的一台机械在一次失败的检修后变得破烂不堪。受损的主动式负载平衡器必须送到奥格瑞玛的地精专家手中，那里或许有人懂得它的运作原理。",h="在贫瘠之地北部，荆棘谷地精的一台机械在一次失败的检修后变得破烂不堪。受损的主动式负载平衡器必须送到奥格瑞玛的地精专家手中，那里或许有人懂得它的运作原理。",kw={"贫瘠之地","机械店","诺格","奥格瑞玛","雷里·格里斯高布","主动式负载平衡器","荆棘谷地精","维妮·布特巴克"},ang={["faction:Horde"]="作为部落的一员，你将从贫瘠之地回收的荆棘谷地精机械带到奥格瑞玛的地精机械店，或许能在那里揭开宝贵的技术秘密。",["profession:Engineering"]="作为工程师，你看得出，在没有结构图的情况下，给本就不稳定的荆棘谷地精机械加装刻度盘和操纵杆有多危险。"},sec={{t="改得面目全非",b="荆棘谷地精制造主动式负载平衡器，用于贫瘠之地北部的资源开采。维妮·布特巴克试着检修并改装其中一台，添加了仪表、操纵杆和刻度盘，以测量它的稳定性。她的改装反而削弱了机械结构，让它破损不堪，濒临报废。她知道再加东西可能会让它彻底失灵，于是将这台脆弱的装置送到一位有工厂工作经验的人手中。"},{t="通往奥格瑞玛的路",b="修理这台装置，需要找一位曾在荆棘谷地精生产线上工作过的人。雷里·格里斯高布曾是荆棘谷地精的雇员，如今在奥格瑞玛荣誉谷的诺格机械店工作。这台破烂的仪器引起了这位工程师的注意。敢从地精的作业场所搜罗废旧物件的人，或许胆识过人，也可能只是鲁莽。"}},faq={{q="主动式负载平衡器是什么？",a="主动式负载平衡器是荆棘谷地精为其在贫瘠之地的工业作业制造的机械。很少有外人了解其中地精工程学的奥秘。",al={"这是什么物品","操作器有什么作用","操作器的用途"}},{q="主动式负载平衡器为什么会破损不堪？",a="维妮·布特巴克试着改装主动式负载平衡器，加装了额外的仪表来测量它的稳定性。这些加装的部件削弱了它的结构，还损坏了内部精密的零件。",al={"谁弄坏了操作器","为什么受损","维妮弄坏了它"}},{q="谁能修好这台受损的仪器？",a="雷里·格里斯高布可以检查这台受损的装置。这位荆棘谷地精的前雇员在奥格瑞玛荣誉谷的诺格机械店工作。",al={"该交给谁","操作器送到哪里","谁来修理"}},{q="这台机械最初来自哪里？",a="这台机械来自荆棘谷地精在贫瘠之地北部的钻探和开采作业。地精工程师用它为重型开采机械提供动力。",al={"操作器的来源","在哪里找到的","荆棘谷地精的来源"}}},fx={["35e2c2bf"]={q="为什么雷里·格里斯高布想要破碎的主动式负载平衡器？",a="维妮·布特巴克试图通过增加额外的测量仪来修补这个精密设备，结果导致其结构完整性降到了历史最低点。由于承认进一步的修补可能会完全毁掉它，维妮派你去把这台损坏的装置送到奥格瑞玛的诺格机械店交给雷里·格里斯高布。作为荆棘谷地精的前员工，雷里拥有修理其专业机器的技术专长。",al={"为什么要带负载平衡器给雷里","谁想要破碎的主动式负载平衡器","为什么雷里想要负载平衡器"}}},fp="31,182,27.375.0,21.316.0,22.151.0,43.158.0,35.144.0,46.162.0"}
P.entries["item:broken-samophlange"] = {n="损坏的主动式负载平衡器",s="在贫瘠之地北部，损坏的主动式负载平衡器引起了好奇的工程师们的注意。它的齿轮和活动部件似乎暗示着某种用途，却无人知晓究竟是什么。",h="在贫瘠之地北部，损坏的主动式负载平衡器引起了好奇的工程师们的注意。它的齿轮和活动部件似乎暗示着某种用途，却无人知晓究竟是什么。",kw={"贫瘠之地","损坏的主动式负载平衡器","齿轮","莫尔杉壁垒","主动式负载平衡器","安德麦","维妮·布特巴克"},ang={["faction:Horde"]="这台装置出现在贫瘠之地的部落领地，促使当地哨站、工匠和中立贸易联络人展开合作。",["profession:Engineering"]="对工程师而言，samophlange是一个无法抗拒的谜题：这台机器内部装有精密的齿轮，或许只有将它拆开，再让它运转起来，才能弄清它的用途。"},sec={{t="令人费解的机械",b="损坏的主动式负载平衡器是来自贫瘠之地北部的一件古怪装置，令人费解。即使已经损坏，它的活动组件和精密齿轮仍能显出制作工艺的精湛。棘齿城的地精斯布特瓦夫不小心弄坏了这台精密装置，当时还没人来得及记录它的运作方式。发现它的人原本希望将运作结果送给安德麦那些好奇的同行，于是开始寻找能修好它的人。他们找上了维妮·布特巴克，一位住在边境哨站莫尔杉壁垒附近的聪明工匠。"},{t="寻求工匠援手",b="维妮·布特巴克检查了主动式负载平衡器损坏的零件，却依然说不清它究竟有什么用途。不过，它的发条声和部件运转的动静引起了她的兴趣。她没有把它当作废品丢掉，而是着手修理，想看看它的机械结构全力运转时会是什么样子。"}},faq={{q="主动式负载平衡器是什么？",a="就连试图修复主动式负载平衡器的工匠，也说不清它有什么用途。它的名字没有给出答案，但精密的齿轮和活动部件表明，它有某种尚不为人所知的工业用途。",al={"操作器用途","操作器有什么用","操作器是什么"}},{q="主动式负载平衡器为什么坏了？",a="棘齿城的地精斯布特瓦夫摆弄别人送来的装置时，弄坏了其中精密的机械结构。还没来得及与安德麦的同行分享它的秘密，主动式负载平衡器就卡住了，于是他们开始寻找专家，让它重新运转起来。",al={"怎么坏的","损坏的主动式负载平衡器背景故事"}},{q="维妮·布特巴克是谁？",a="维妮·布特巴克是一位充满好奇心的工匠，住在贫瘠之地北部，灰谷边界上的莫尔杉壁垒以南不远处。对工程学的好奇心驱使她检查并重建各种古怪装置。",al={"维妮在哪","布特巴克位置"}},{q="安德麦的地精为什么对它感兴趣？",a="地精工程师和企业家都热衷于研究不同寻常的机械技术。有关这台装置的消息传到了安德麦的联络人耳中，他们很想知道它能带来什么优势。",al={"安德麦的兴趣","地精为什么在意"}}},fp="18,154,20.445.0,24.274.0,22.179.0,30.251.0,26.213.0,46.194.0"}
P.entries["item:broken-tools"] = {n="损坏的工具",s="在血蹄村西北方的挖掘场，矮人的镐头已被砸断，散落在熔炉上。贝恩·血蹄需要证据，证明威胁莫高雷土地与野生动物的挖掘已经停止。",h="在血蹄村西北方的挖掘场，矮人的镐头已被砸断，散落在熔炉上。贝恩·血蹄需要证据，证明威胁莫高雷土地与野生动物的挖掘已经停止。",kw={"贝恩·血蹄","损坏的工具","挖掘场","矮人挖掘","熔炉","莫高雷","勘察员的锄头"},ang={["profession:Blacksmithing"]="身为铁匠，你可以用熔炉和铁砧摧毁矮人的铁制工具，保卫这片土地。",["race:Tauren"]="身为牛头人，将损坏的工具带给贝恩，有助于保护Earth Mother，阻止那些让本地野兽备受折磨的挖掘行为。"},sec={{t="破坏挖掘行动",b="在血蹄村西北方，矮人挖掘者正在莫高雷的丘陵中挖掘，探寻远古的历史。牛头人认为他们的行为亵渎了大地母亲。挖掘造成的噪声与破坏让当地的野生动物躁动不安，尤其是四处游荡的科多兽群。年轻的贝恩·血蹄命令守卫夺取勘探者的铁镐，并在熔炉上将其砸断。镐头一旦被毁，这支探险队就无法继续挖掘大地。"}},faq={{q="这些损坏的工具是什么？",a="损坏的工具是从莫高雷的矮人挖掘者手中夺来、在熔炉上砸毁的勘察员的锄头，留下了破损的镐头和碎裂的镐柄。",al={"损坏的工具","损坏的工具是什么","破碎的镐头"}},{q="贝恩·血蹄为什么要毁掉这些工具？",a="贝恩认为，挖掘土壤亵渎了这片土地，也激怒了莫高雷的野生动物，尤其是科多兽。砸断镐头既能阻止挖掘，也是在警告他们，肆意挖掘无法让大地交出它的智慧。",al={"为什么要毁掉镐头","贝恩为什么要损坏的工具","贝恩 矮人挖掘"}},{q="在哪里可以砸断这些镐头？",a="你可以在任何能够使用的熔炉上砸断镐头。矮人的挖掘场里就有一座，血蹄村和雷霆崖也有。",al={"如何砸断镐头","熔炉在哪里","砸断勘察员的锄头"}},{q="矮人为什么要在莫高雷挖掘？",a="矮人相信，莫高雷的土壤深处藏着秘密和远古遗物。为了寻找自身的起源，他们挖空异乡的土地，丝毫不顾及当地的居民。",al={"矮人为什么在莫高雷","矮人挖掘场 莫高雷"}}},fx={["76aab525"]={q="这些损坏的工具从何而来？",a="这些破损的工具原本是矮人勘探者锻造和携带的坚固矿工锄。为了寻找莫高雷地下的泰坦遗物和古老秘密，探险队带来了他们的铁制工具来开凿大地。通过将这些完好的锄头运到熔炉并砸成碎片，你将他们的采矿装备变成了无法使用的废料，然后将其交还给牛头人，作为挖掘活动已停止的证据。",al={"损坏的工具起源","谁制作了损坏的工具","损坏的工具从何而来"}}},fp="12,182,18.438.0,28.163.0,45.225.0,32.144.0,35.179.0"}
P.entries["item:bundle-of-crocolisk-skins"] = {n="一捆鳄鱼皮",s="在湿地，猎人们为米奈希尔港准备鳄鱼皮。这些皮是当地制皮匠眼中贵重的贸易货物。",h="在湿地，猎人们为米奈希尔港准备鳄鱼皮。这些皮是当地制皮匠眼中贵重的贸易货物。",kw={"鳄鱼","埃纳尔","詹姆斯·哈洛兰","皮革","米奈希尔港","塞达","兽皮","湿地"},ang={["faction:Alliance"]="作为一名联盟旅行者，你可以看到米奈希尔港外的猎人如何供应材料，帮助驻军和居民置办装备，应对恶劣的沼泽环境。"},sec={{t="湿地贸易与家中争执",b="鳄鱼皮是海滨城镇米奈希尔港不可或缺的贸易货物。猎人们在湿地收集并鞣制这些坚韧耐水的皮，再将它们向西运送给詹姆斯·哈洛兰这样的工匠。埃纳尔收集了这一捆皮，却请一位旅行者帮忙送进镇里。他不想回家面对妻子塞达的怒气，她正为此烦心。"}},faq={{q="一捆鳄鱼皮有什么用途？",a="这捆沼泽兽皮中既有生皮，也有鞣制过的皮，是送给米奈希尔港的制革匠詹姆斯·哈洛兰的。他将这些皮制成结实的靴子、腰带和皮甲，适合在湿地潮湿积水的地面上使用。",al={"鳄鱼皮用途","这些皮有什么用","一捆皮的用途"}},{q="这些鳄鱼皮是谁收集的？",a="猎人埃纳尔在沼泽中收集了这些皮，并将它们捆好。他通常会亲自把货物送进镇里，但为了避免与妻子塞达争吵，他请路过的旅行者帮忙运送这一捆皮。",al={"谁捆的皮","谁收集的皮","埃纳尔 鳄鱼"}},{q="詹姆斯·哈洛兰是谁？",a="詹姆斯·哈洛兰是港口城镇米奈希尔港的一名制皮匠兼制革匠。他从沼泽猎人手中收购生皮和鞣制过的皮，为水手、士兵和镇民制作靴子、熟化皮革和实用装备。",al={"詹姆斯·哈洛兰的职责","哈洛兰是谁","制革匠 米奈希尔"}}},fx={["639d94c2"]={q="什么是“一捆鳄鱼皮”？",a="它是一包从潜伏在湿地的危险鳄鱼身上收割的生皮。埃纳尔·石钳将它们收集并捆在一起，打算卖给米奈希尔港的当地工匠，但个人的麻烦使他无法亲自交付这些货物。",al={"什么是“一捆鳄鱼皮”","一捆鳄鱼皮"}},["8cc4b9e1"]={q="为什么詹姆斯·哈洛兰想要“一捆鳄鱼皮”？",a="詹姆斯·哈洛兰在米奈希尔港担任制皮匠，依靠稳定的新鲜兽皮供应来为居民和旅行者制作优质的皮靴和硬化护甲。生鳄鱼皮提供了他进行交易和补充库存所需的坚韧、耐用的材料。",al={"为什么詹姆斯·哈洛兰需要兽皮","为什么想要“一捆鳄鱼皮”","詹姆斯·哈洛兰鳄鱼皮"}}},fp="25,113,37.308.0,47.187.0,35.211.0,22.208.0"}
P.entries["item:bundle-of-hides"] = {n="一捆兽皮",s="一捆兽皮随部落的风骑士穿越贫瘠之地，运往雷霆崖。这些鞣制好的兽皮是交给制皮匠的普通货物，而运送它们的过程也让旅人认识了风骑士航线网。",h="一捆兽皮随部落的风骑士穿越贫瘠之地，运往雷霆崖。这些鞣制好的兽皮是交给制皮匠的普通货物，而运送它们的过程也让旅人认识了风骑士航线网。",kw={"安哈努","贫瘠之地","一捆兽皮","十字路口","迪弗拉克","海瓦的武器店","加翰","制皮","雷霆崖","风骑士"},ang={["faction:Horde"]="毛皮之类的普通货物沿着双足飞龙航线穿越天空，将孤立的部落前哨直接与享有主权的都城联系起来。",["race:Tauren"]="身为牛头人，你依靠天然材料，心怀敬意地狩猎，将邻近草原的兽皮制成护甲和工艺品，在莫高雷的摊位上出售。"},sec={{t="边地贸易",b="猎人剥取贫瘠之地野兽的皮，再将其鞣制成皮革。平原上有庞大的科多兽群、四处潜行的狮子，还有游荡的迅猛龙。这些兽皮供应给雷霆崖的制皮匠，由他们制成部落所需的装备、皮包、护甲和绑带。"},{t="空中货运",b="信使骑着迪弗拉克训练的双足飞龙，将这捆兽皮从十字路口运往雷霆崖。从陆路穿过贫瘠之地进入莫高雷，既缓慢又危险，沿途有游荡的野猪人和半人马劫掠者。将兽皮交给风骑士信使，便能体会到空中旅行穿越卡利姆多破碎地形的速度。"}},faq={{q="一捆兽皮有什么用途？",a="一捆兽皮中装着从贫瘠之地各处动物身上收集的皮，将送到雷霆崖的制皮匠安哈努手中。他为牛头人及其部落盟友制作皮革制品和武备。",al={"一捆兽皮用途","为什么运送兽皮","兽皮有什么用"}},{q="谁在雷霆崖接收这批货物？",a="安哈努在海瓦的军械库接收包裹，那里就在雷霆崖风骑士栖所的正下方。",al={"谁接收兽皮","一捆兽皮接收者","安哈努在哪里"}},{q="为什么要用风骑士运送这捆兽皮？",a="从十字路口步行前往雷霆崖需要数日，还可能遭到半人马或野猪人的伏击。十字路口的飞行管理员迪弗拉克用风骑士运送货物，让它们迅速、安全地抵达。",al={"为什么空运兽皮","十字路口飞行兽皮","迪弗拉克风骑士"}},{q="是谁在贫瘠之地备好了这捆兽皮？",a="加翰·鹰翼用贫瘠之地动物的皮备好了这捆货物。他是十字路口的皮甲和锁甲商人，也是安哈努的同行。",al={"谁给的兽皮","加翰兽皮","谁收集的毛皮"}}},fx={["2b9c2280"]={q="什么是“一捆兽皮”？",a="“一捆兽皮”是从在贫瘠之地游荡的野生野兽身上收集的生皮包裹。它在十字路口附近收集并准备，是旨在出口到雷霆崖的关键制作材料，那里的熟练制皮师将坚韧的边疆兽皮转化为护甲、服装和基本的贸易商品。",al={"什么是“一捆兽皮”","“一捆兽皮”物品","“一捆兽皮”背景传说"}}},fp="15,223,14.223.0,15.280.0,37.194.0,43.96.0,38.215.0,39.135.0"}
P.entries["item:bundle-of-wood"] = {n="一捆木柴",s="东谷伐木场需要将木材运往西方，用于暴风城的重建。",h="东谷伐木场需要将木材运往西方，用于暴风城的重建。",kw={"一捆木柴","东谷","艾尔文","伐木场","木料","莱琳","木材"},ang={["faction:Alliance"]="作为一名联盟旅人，收集这些木柴有助于暴风城重建，也能确保木材按时运抵艾尔文和西部荒野各地的定居点。"},sec={{t="遗弃的木材",b="东谷伐木场将新砍的木材运往西方，用于暴风城王国的房屋及其他工程建设。然而，熊和狼闯入了营地西北方的树林。伐木工人惊恐地逃走，将一捆木柴留在了林间。交货期限将近，监工莱琳需要旅人找回这些木材，以免违反木材供货契约。"}},faq={{q="这些木柴为什么被遗弃在树林里？",a="狼和熊赶走了在东谷伐木场西北方采伐木材的工人。工人们将刚砍好的一捆木柴留在了林地上。",al={"木材为什么在地上","为什么遗弃木材","艾尔文遗弃的木材"}},{q="谁需要收集这些木材？",a="东谷伐木场的监工莱琳需要尽快收齐木材，赶上即将到来的木材交货期限。",al={"谁需要木材","莱琳木材","木材交付"}},{q="在哪里能找到这些木柴？",a="这些木柴散落在东谷伐木场西北方的树林间，艾尔文的熊和狼在那里游荡。",al={"一捆木柴位置","木材在哪里","东谷木材位置"}},{q="镇上的卫兵为什么没有清除这些野兽？",a="莱琳向瑞尼尔副队长求助过，但艾尔文各地的治安官和卫兵都已人手不足。伐木工人需要外来者帮忙，尽快找回原木。",al={"为什么没有卫兵","瑞尼尔副队长木材","东谷的卫兵"}}},fx={e892b12c={q="什么是“一捆木柴”？",a="这些是东谷伐木场的工人们砍伐并收集的新鲜木材堆。它们为运输和加工做好了准备，代表了伐木场在艾尔文森林东部的持续伐木作业。",al={"什么是“一捆木柴”","艾尔文森林的“一捆木柴”","这些木柴捆是什么"}}},fp="14,70,16.390.0,54.168.0,30.123.0,30.115.0,48.173.0"}
P.entries["item:burning-blade-medallion"] = {n="火刃奖章",s="试炼谷的邪教徒携带着火刃奖章。亚罗格·刺影在火刃集会所深处持有这枚奖章，其中的黑暗魔法威胁着杜隆塔尔年轻的战士们。",h="试炼谷的邪教徒携带着火刃奖章。亚罗格·刺影在火刃集会所深处持有这枚奖章，其中的黑暗魔法威胁着杜隆塔尔年轻的战士们。",kw={"火刃集会所","火刃奖章","杜隆塔尔","邪能猎犬","护符","试炼谷","亚罗格·刺影","祖雷萨"},ang={["class:Warlock"]="身为部落术士，你在严格的约束下修习黑暗魔法。这枚奖章代表着火刃氏族肆意妄为、毫无约束的邪能法术，威胁着杜隆塔尔的安定。",["race:Orc"]="对兽人而言，这枚奖章让你想起曾经奴役你们种族的恶魔腐化。如今，这片阴影在年轻的新兵离开试炼谷之前，就已威胁着他们。"},sec={{t="腐化的印记",b="祖雷萨的占卜指向了火刃集会所中的奖章。亚罗格·刺影是火刃氏族教派的一名爪牙，他在蜿蜒的洞穴深处携带着它。这件饰物在教派的小鬼魔仆和邪能猎犬之间传导着黑暗力量。击败Yarrog并夺走奖章，就能终结教派从杜隆塔尔内部破坏部落训练场的企图。"}},faq={{q="火刃奖章是什么？",a="亚罗格·刺影是潜藏在杜隆塔尔的火刃氏族教派成员，他携带着这件魔法护符。它能汇聚黑暗魔法，也表明持有者效忠于这个教派。",al={"火刃氏族护符","集会所奖章","亚罗格的奖章"}},{q="谁想要取回奖章？",a="祖雷萨是试炼谷大兽穴外的一位兽人先知，她希望有人取回奖章。她想根除恶魔的影响，并研究教派在当地的计划。",al={"谁收取奖章","奖章在哪里交","祖雷萨任务"}},{q="奖章在哪里？",a="亚罗格·刺影在火刃集会所深处持有这枚奖章，那是试炼谷大兽穴西北方的一处隐秘洞穴。他潜伏在洞穴上层的岩台上。",al={"亚罗格·刺影在哪里","火刃奖章位置","如何找到奖章"}},{q="奖章的出现对杜隆塔尔意味着什么？",a="奖章的出现证实，火刃氏族教派已将爪牙安插进部落的试炼之地。它的存在表明，邪教徒在兽人的故土上怀有更广泛、更危险的野心。",al={"邪教徒为何在试炼谷","火刃氏族是否在杜隆塔尔"}}},fp="23,184,20.384.0,36.175.0,34.175.0,29.174.0,52.201.0"}
P.entries["item:burning-blood-quest-item"] = {n="燃烧之血",s="暮色森林的夜行狼人的血液引起了格瑞曼德·艾尔默的兴趣。他需要二十瓶这种血液来进行锻造实验。",h="暮色森林的夜行狼人的血液引起了格瑞曼德·艾尔默的兴趣。他需要二十瓶这种血液来进行锻造实验。",kw={"燃烧之血","暮色森林","弗伦·长须","格瑞曼德·艾尔默","加特斯比尔","夜行","罗兰之墓","狼人"},ang={["class:Warrior"]="格瑞曼德·艾尔默用燃烧之血试验锻造方法。他承诺为带来这种血液的战士打造耐用的板甲。",["profession:Blacksmithing"]="铁匠可以使用燃烧的狼人血液等特殊材料，在极高的温度下为厚重的金属淬火和回火。"},sec={{t="不稳定的试剂",b="夜行狼人在暮色森林游荡，陷入一种怪异的狂怒。它们的血液灼热滚烫。这种血液可以从出没于林地和罗兰之墓的狼人身上采集。铸甲师想利用血液的热量淬炼坚韧的板甲。"},{t="艾尔默的实验",b="格瑞曼德·艾尔默是暴风城矮人区的一名铸甲师。他想试验昔日的学生弗伦·长须构思的锻造方法。\n\n为了进行实验，艾尔默需要燃烧之血，以及狼人酋长加特斯比尔持有的一块致密的燃烧之石。把冒泡的血液带给他，他就答应为战士锻造坚固的护甲。"}},faq={{q="什么是燃烧之血？",a="暮色森林的夜行狼人拥有滚烫的血液。格瑞曼德·艾尔默需要用它来进行锻造实验。",al={"燃烧之血背景故事","什么是燃烧之血","狼人血液"}},{q="燃烧之血来自哪里？",a="燃烧之血来自暮色森林的夜行狼人，尤其是罗兰之墓周围的狼人。",al={"哪里获取燃烧之血","谁掉落燃烧之血","燃烧之血位置"}},{q="格瑞曼德·艾尔默为什么需要这种血液？",a="格瑞曼德·艾尔默需要燃烧之血来试验弗伦·长须开发的锻造方法。他打算将这种血液与燃烧之石配合使用，为一名战士锻造提供防护的锁甲。",al={"格瑞曼德为什么需要燃烧之血","格瑞曼德·艾尔默血液任务"}},{q="夜行的血液为什么会燃烧？",a="夜行是黑暗而混乱的魔法召唤出的邪恶怪物，违背自然。它们血液中的诅咒赋予了血液异常猛烈的热量。",al={"狼人的血液为什么会燃烧","狼人的血液是火吗"}}},fp="26,119,18.206.0,19.337.0,22.94.0,35.93.0,32.159.0,42.123.0"}
P.entries["item:burning-rock"] = {n="燃烧之石",s="在暮色森林，燃烧之石在罗兰之墓中闷燃。夜行狼人的首领加特斯比尔带着这块石头，而暴风城的格瑞曼德·艾尔默需要将它与炽热的狼人之血一同使用，为前途可期的战士锻造附魔护甲。",h="在暮色森林，燃烧之石在罗兰之墓中闷燃。夜行狼人的首领加特斯比尔带着这块石头，而暴风城的格瑞曼德·艾尔默需要将它与炽热的狼人之血一同使用，为前途可期的战士锻造附魔护甲。",kw={"燃烧之石","暮色森林","弗伦·长须","格瑞曼德·艾尔默","加特斯比尔","夜行狼人","罗兰之墓"},ang={["class:Warrior"]="身为战士，你为了燃烧之石勇闯罗兰之墓。格瑞曼德·艾尔默会利用它的热量锻造专属护甲，奖赏你的英勇。",["profession:Blacksmithing"]="身为铁匠，你可以研究燃烧之石这种不同寻常的热源。暴风城和铁炉堡的铸甲师正在探索非常规的方法，用于熔炼金属和淬炼护甲。"},sec={{t="闷燃的珍宝",b="加特斯比尔带着燃烧之石穿行于罗兰之墓的矿道中。暴风城的格瑞曼德·艾尔默想利用它的热量，配合炽热的狼人之血打造护甲。他正在试验同行弗伦·长须开发的锻造技艺，希望为身经百战的勇士打造坚固的板甲。"}},faq={{q="燃烧之石在哪里？",a="加特斯比尔带着燃烧之石，藏身于暮色森林东部的罗兰之墓。",al={"燃烧之石位置","谁掉落燃烧之石","哪里获取燃烧之石"}},{q="谁想要燃烧之石？",a="格瑞曼德·艾尔默是暴风城矮人区的一名矮人铁匠，他想用燃烧之石试验新的锻造技艺。",al={"谁需要燃烧之石","谁上交燃烧之石","格瑞曼德·艾尔默燃烧之石"}},{q="格瑞曼德·艾尔默为什么需要它？",a="格瑞曼德计划试验弗伦·长须开发的制作技艺。这块闷燃的石头与夜行狼人之血配合使用，能为锻造一套独特的护甲提供热量。",al={"燃烧之石用途","为什么需要燃烧之石","燃烧之石有什么用"}},{q="这块石头与狼人有什么联系？",a="罗兰之墓中的夜行狼人具有奇异的火焰特性，血液也在燃烧。他们的首领加特斯比尔将燃烧之石保存在矿洞深处。没人知道它是如何来到那里的。",al={"狼人为什么有燃烧之石","加特斯比尔燃烧之石背景故事"}}},fx={a40de154={q="什么是燃烧之石？",a="燃烧之石是一种罕见、灼热的矿物，发现于暮色森林那闹鬼的树林深处。这块火热的石头由占据罗兰之墓的野性夜行狼人首领加特斯比尔持有，它保持着极高的温度，是专门锻造和冶金所追求的材料。",al={"什么是燃烧之石","燃烧之石物品","关于燃烧之石"}}},fp="12,224,18.267.0,32.71.0,27.130.0,32.170.0,50.186.0"}
P.entries["item:cache-of-zanzil-s-altered-mixture"] = {n="赞吉尔的改良药剂",s="淤泥沼泽附近的荆棘谷地精高塔里，锁藏着一批强效毒药。这种混合物以丛林巨魔巫医赞吉尔的名字命名，引起了碎手氏族的注意。",h="淤泥沼泽附近的荆棘谷地精高塔里，锁藏着一批强效毒药。这种混合物以丛林巨魔巫医赞吉尔的名字命名，引起了碎手氏族的注意。",kw={"改良混合物","加里维克斯","保险箱","毒药","碎手氏族","申苏尔","淤泥沼泽","荆棘谷地精","赞吉尔"},ang={["class:Rogue"]="对部落盗贼而言，取回这种混合物是一项必经的试炼，借此证明自己精通开锁、偷窃和毒药处理，能够为碎手氏族效力。",["faction:Horde"]="淤泥沼泽北面那座充斥毒药的荆棘谷地精高塔，威胁着杜隆塔尔和贫瘠之地周边地区的安宁与安全。"},sec={{t="剧毒营生",b="在贫瘠之地淤泥沼泽的北面，荆棘谷地精占据着一座高塔哨站。大工头普兹克·加里维克斯在塔顶的私人保险箱里，藏着一批以巨魔巫医赞吉尔的名字命名的改良混合物。一种毒药削弱了塔内所有人的力量，让住在其中的地精无力抵挡胆大的闯入者。"},{t="为碎手氏族取回混合物",b="碎手氏族是藏身于奥格瑞玛地下的秘密盗贼公会，已经注意到这些离杜隆塔尔如此之近的危险炼金材料。大师级训练师申苏尔派出密探，命他们突袭高塔，杀死加里维克斯，并撬开他的保险箱。公会既想消除威胁，也想研究这种混合物，用于自身的情报工作。取回这批不稳定的混合物，需要高超的潜入技巧。受污染容器上的毒素会使接触者失去防备，虚弱不堪。"}},faq={{q="赞吉尔的改良药剂是什么？",a="赞吉尔的改良药剂是一种以巨魔巫医赞吉尔的名字命名的强效毒药。淤泥沼泽附近的荆棘谷地精高塔里锁藏着一批这种毒药，塔内所有人都已被一种毒药削弱。",al={"赞吉尔 混合物是什么","这批藏物是什么","赞吉尔 药水"}},{q="这批混合物藏在哪里？",a="这批混合物藏在贫瘠之地淤泥沼泽北面荆棘谷地精高塔顶层的 加里维克斯的保险箱 中。",al={"混合物在哪里","赞吉尔 藏物在哪里","混合物位置"}},{q="碎手氏族为什么想要这种混合物？",a="申苏尔和碎手氏族希望铲除部落家门口的荆棘谷地精势力，并取回这种化合物，用于自身的情报研究。",al={"谁想要混合物","申苏尔为什么想要它","碎手氏族 任务"}},{q="如何打开装有这批混合物的箱子？",a="箱子装有精密的弹子锁，需要高超的开锁技能才能打开，而受污染的容器可能使接触者染上令人虚弱的毒素。",al={"如何打开 加里维克斯的保险箱","打开 赞吉尔 箱子","开锁获取 赞吉尔 藏物"}}},fx={["83dd2f73"]={q="赞吉尔的混合药剂从何而来，由谁制作？",a="这种混合药剂源自巫医赞吉尔，但它落入了在贫瘠之地活动的荆棘谷地精手中。大工头普兹克·加里维克斯将剩余的变异供应品锁在了淤泥沼泽附近的钻井塔顶部的个人保险箱里。",al={"谁制作了赞吉尔的混合药剂","混合药剂的起源","赞吉尔混合药剂从何而来"}}},fp="33,176,18.341.0,31.410.1,33.197.0,25.115.0,45.165.0,47.152.0"}
P.entries["item:cactus-apple"] = {n="仙人掌果",s="在试炼谷，仙人掌果为兽人提供了杜隆塔尔干热气候中难得的水分。",h="在试炼谷，仙人掌果为兽人提供了杜隆塔尔干热气候中难得的水分。",kw={"仙人掌果","清凉果","沙漠水果","杜隆塔尔","戈加尔","试炼谷"},ang={["profession:Cooking"]="作为杜隆塔尔的野外厨师，你可以将沙漠中的仙人掌做成补充水分的餐食。",["race:Orc"]="作为杜隆塔尔的年轻兽人，你学着利用这片赤红峡谷中每一分稀缺的水分。"},sec={{t="沙漠采收",b="试炼谷遍布粗壮的仙人掌，仙人掌果就成簇地生长在这些植株周围。采集时得在尖刺间忙碌，但在杜隆塔尔的酷热中，这些果实能补充宝贵的水分。谷中的兽人戈加尔采集这些果实，用来制作清凉果，为正在接受初期训练的新兵消暑。"}},faq={{q="仙人掌果生长在哪里？",a="仙人掌果野生于杜隆塔尔南部的试炼谷，长在散布于谷地的粗壮仙人掌根部附近。",al={"仙人掌果位置","哪里能找到仙人掌果","仙人掌果地点"}},{q="清凉果是什么？",a="清凉果是戈加尔用新鲜采集的仙人掌果制作的冰凉菜肴，能缓解杜隆塔尔沙漠的酷热。",al={"戈加尔的惊喜是什么","仙人掌果食谱","戈加尔的点心"}},{q="谁在收集这些果实？",a="试炼谷的兽人戈加尔请年轻的新兵带回六个新鲜的仙人掌果，用来换取他制作的清凉甜点。",al={"仙人掌果任务给予者","谁需要仙人掌果","戈加尔的仙人掌果"}}},fx={["93b3f975"]={q="什么是仙人掌果？",a="仙人掌果是一种清脆、提神的野生水果，在杜隆塔尔试炼谷的带刺仙人掌下茁壮成长。尽管兽人家园条件恶劣、干旱，但这些韧性十足的植物结出的多汁果实在炙热的沙漠阳光下提供了急需的水分和营养。",al={"什么是仙人掌果","仙人掌果背景传说"}},e52e1b37={q="仙人掌果从何而来？",a="仙人掌果是原生的沙漠水果，自然生长在杜隆塔尔试炼谷各处的仙人掌根部。它们不是由任何人制作或培育的，而是直接从适应了该地区红色峡谷和干燥气候的韧性植物上长出来的。",al={"仙人掌果从何而来","仙人掌果起源","谁制作了仙人掌果"}},["0fea9150"]={q="为什么戈加尔想要仙人掌果？",a="戈加尔收集它们是为了制作他著名的清凉果。试炼谷的酷热对新兵和经验丰富的战士都造成了沉重的负担，而用这些苹果制成的甜美、清凉的甜点在残酷的正午阳光下提供了至关重要的提神作用。",al={"为什么要采集仙人掌果","为什么戈加尔想要仙人掌果","仙人掌果的用途"}}},fp="12,99,14.332.0,28.147.0,30.146.0,26.149.0"}
P.entries["item:calor-s-note"] = {n="卡洛尔的便笺",s="在暮色森林，卡洛尔的便笺承载着一位林中猎人写给乔纳森·卡尔文大师的推荐。卡洛尔为一名经受过考验的冒险者，在一小片褪色的羊皮纸上写下这封信，为其打开了通往一个隐秘团体的门。这个团体与夜色镇的民兵并肩作战，却又独立于民兵之外。",h="在暮色森林，卡洛尔的便笺承载着一位林中猎人写给乔纳森·卡尔文大师的推荐。卡洛尔为一名经受过考验的冒险者，在一小片褪色的羊皮纸上写下这封信，为其打开了通往一个隐秘团体的门。这个团体与夜色镇的民兵并肩作战，却又独立于民兵之外...",kw={"卡洛尔","卡洛尔的便笺","夜色镇","暮色森林","乔纳森·卡尔文","守夜人","推荐","狼人"},ang={["class:Paladin"]="乔纳森·卡尔文以“荣耀归于圣光之下”迎接持信人，表明他与那些致力于清除暮色森林中恶魔和亡灵的神圣勇士有着共同的理想。",["faction:Alliance"]="暴风城的军队不在暮色森林，Carevin的团体与守夜人便作为非官方派系，守卫南部边境，抵御黑暗。"},sec={{t="难得的推荐",b="卡洛尔出了名地难以取悦，暮色森林也很少善待外来者。当一名冒险者从潜伏林间的嗜血狼人手中生还，便赢得了卡洛尔的尊重，他也为此写下一封短信。这张褪色的便笺被带往夜色镇，将这位外来者直接引荐给乔纳森·卡尔文。"},{t="私下的征战",b="夜色镇依靠守夜人维持日常防务，而卡洛尔与卡尔文则在暗中进行着一场更为严酷的战斗。卡洛尔感叹镇上卫兵的人数比他们多，希望能找到足够多能征善战的人，推进他们私下的战争。交出便笺后，持信人便能加入卡尔文的行动，对抗恶魔、亡灵，以及那些暗中帮助它们、令暮色森林日渐衰败的同谋。"}},faq={{q="卡洛尔的便笺是什么？",a="卡洛尔的便笺是卡洛尔亲笔写在一小片褪色羊皮纸上的短信。信中推荐了一名冒险者，称其有能力对抗暮色森林的恐怖威胁，值得信赖。",al={"卡洛尔的便笺","这张便笺是什么","便笺写了什么"}},{q="便笺要交给谁？",a="便笺的收信人是乔纳森·卡尔文。他是一位驻守夜色镇的严厉人物，负责协调对抗威胁这片地区的黑暗势力。",al={"便笺交给谁","卡洛尔的便笺给谁","乔纳森·卡尔文的便笺"}},{q="卡洛尔如何看待守夜人？",a="卡洛尔认为守夜人无法应对暮色森林真正的威胁。交出便笺时，他说自己希望招募足够多有能力的盟友，让人数超过民兵，完成他那小小派系独自承担的紧迫任务。",al={"卡洛尔与守夜人","卡洛尔为何想在人手上超过守夜人"}},{q="乔纳森·卡尔文进行着怎样的战斗？",a="卡尔文大师在暮色森林对抗恶魔、亡灵，以及协助它们的凡人同谋。他重视警惕之心与对圣光的虔诚，只信任经受过考验的人。",al={"卡尔文的事业","卡尔文做什么","卡尔文与谁作战"}}},fx={d10add4c={q="谁写了卡洛尔的便笺，它从何而来？",a="这张便笺是由卡洛尔书写的，他是一名驻扎在暮色森林闹鬼地带的冷酷战士。在你证明了自己对抗恐吓树林的凶猛狼人的勇气后，他将这条信息写在一张褪色的羊皮纸上，让你前往他的上级那里。",al={"卡洛尔的便笺起源","谁制作了卡洛尔的便笺","卡洛尔的便笺从何而来"}},fe7f9dd8={q="为什么乔纳森·卡尔文想要卡洛尔的便笺？",a="大师乔纳森·卡尔文在信任一个被阴影笼罩的土地上的人之前，需要证据。卡洛尔的便笺是一封正式的推荐信，让卡尔文知道你赢得了卡洛尔难得的尊重，并且有能力协助他们秘密对抗恶魔、亡灵和更黑暗的力量。",al={"为什么要带卡洛尔的便笺给卡尔文","为什么卡尔文想要卡洛尔的便笺","卡洛尔便笺给卡尔文的目的"}}},fp="12,258,21.285.0,17.387.0,21.148.0,22.153.0,38.232.0,48.196.0"}
P.entries["item:candle-of-beckoning"] = {n="诱灵蜡烛",s="在澈水湖上，冈瑟尔·阿坎努斯保管着一支用于召唤的魔法蜡烛。在附近的小岛上点燃它，不得安息的灵魂莉莉丝·奈法拉便会回应召唤。",h="在澈水湖上，冈瑟尔·阿坎努斯保管着一支用于召唤的魔法蜡烛。在附近的小岛上点燃它，不得安息的灵魂莉莉丝·奈法拉便会回应召唤。",kw={"澈水湖","诱灵蜡烛","冈瑟尔·阿坎努斯","莉莉丝·奈法拉","证明忠诚","沉睡的幽魂","提瑞斯法林地"},ang={["class:Mage"]="身为法师，你能从冈瑟尔将灵魂束缚在这类仪式蜡烛等用具上的手法中，看出他对死灵法术与召唤术的精通，这些都不在肯瑞托认可的教义之内。",["race:Undead"]="对于幽暗城派出的被遗忘者使者而言，使用冈瑟尔的仪式蜡烛是必要的一步，才能让这位极为独立的死灵法师相信，你们并非巫妖王的奴仆。"},sec={{t="忠诚的试炼",b="冈瑟尔·阿坎努斯住在澈水湖的一座岛上，将诱灵蜡烛存放在身旁的箱子里。这种蜡烛是召唤仪式的用具。冈瑟尔是一位极为独立的亡灵巫师，他凭一己之力摆脱了巫妖王的控制，对天灾军团和被遗忘者都保持着戒心。为了向冈瑟尔证明你并不效忠于巫妖王，带上一支蜡烛，前往西南方一座较小的岛屿。将蜡烛放在一张染血的旧桌上，然后点燃它。烛火会穿透世界之间的帷幕，唤来强大的天灾军团爪牙莉莉丝·奈法拉那沉睡而不得安息的幽魂，让你将她消灭。"}},faq={{q="诱灵蜡烛有什么用途？",a="在冈瑟尔·阿坎努斯营地西南方的小岛上，找到那张染血的古旧仪式桌，点燃诱灵蜡烛，便能召唤幽魂莉莉丝·奈法拉。蜡烛会将她沉睡的灵魂引入物质世界。",al={"诱灵蜡烛有什么作用","诱灵蜡烛的用途","如何使用诱灵蜡烛"}},{q="在哪里可以获得诱灵蜡烛？",a="接受冈瑟尔·阿坎努斯的忠诚试炼期间，你可以从他身旁的箱子里取走一支诱灵蜡烛，他就在提瑞斯法林地东部澈水湖的一座岛上。",al={"哪里能找到诱灵蜡烛","如何获得诱灵蜡烛","蜡烛箱位置"}},{q="蜡烛会召唤谁？",a="点燃蜡烛会召唤莉莉丝·奈法拉，她是一名强大的天灾军团爪牙，盘踞在岛屿南岸外的血腥祭坛。击败她便能证明你并未为天灾军团效力。",al={"会召唤谁","蜡烛召唤目标","莉莉丝·奈法拉是谁"}},{q="冈瑟尔·阿坎努斯为什么会有这些蜡烛？",a="冈瑟尔用这些蜡烛考验所有寻求与他结盟的人。他极力维护自己脱离天灾军团后的自由，又对外人心存疑虑，因此要求你面对并消灭他召唤的、不得安息的亡灵。",al={"冈瑟尔为什么有蜡烛","冈瑟尔的仪式蜡烛"}}},fx={["63af5e56"]={q="什么是诱灵蜡烛？",a="诱灵蜡烛是一种附魔的仪式蜡烛，发现于死灵法师冈瑟尔·阿坎努斯在澈水湖的隐居岛屿上。这支蜡烛存放在这位隐居法师身边的一个板条箱里，带有专门用于穿透死亡帷幕的强大召唤魔法。当放在附近小岛上一个血迹斑斑的仪式桌上并点燃时，它的火焰就成了超自然的诱饵，召唤出莉莉丝·奈法拉沉睡的阴影。",al={"什么是诱灵蜡烛","诱灵蜡烛背景传说"}},cb4d5793={q="为什么会有人想要诱灵蜡烛？",a="任何寻求与冈瑟尔·阿坎努斯会面或结盟的人，首先必须证明他们的忠诚不在于巫妖王。冈瑟尔在与被遗忘者分享他强大的天赋之前，要求忠诚的证明。通过取回诱灵蜡烛，你可以引出并消灭莉莉丝·奈法拉，证明你反对天灾军团的决心，并赢得这位隐居死灵法师来之不易的尊重。",al={"我为什么需要诱灵蜡烛","为什么想要诱灵蜡烛","诱灵蜡烛的用途"}}},fp="19,151,20.545.0,41.198.0,41.187.0,30.185.0,44.217.0"}
P.entries["item:cantation-of-manifestation"] = {n="显形卷轴",s="在幽暗城，安娜斯塔西娅·哈特威尔将一份卷轴交给学徒，用来让奥格诺恩店里看不见的魔法生物显形。",h="在幽暗城，安娜斯塔西娅·哈特威尔将一份卷轴交给学徒，用来让奥格诺恩店里看不见的魔法生物显形。",kw={"奥格诺恩","安娜斯塔西娅·哈特威尔","炼金房","显形卷轴","收容箱","魔法区","裂隙生物","幽暗城"},ang={["class:Mage"]="身为法师，你在早期训练中使用显形卷轴，侦测隐藏的奥术能量流，并收容不稳定的裂隙实体。",["race:Undead"]="身为Undead，你知道魔法区的被遗忘者施法者密切监视着奥术波动，以免魔法裂隙威胁幽暗城的稳定。"},sec={{t="揭开隐形之幕",b="显形卷轴能让被魔法隐藏的生物显形。安娜斯塔西娅·哈特威尔在魔法区保管着这份卷轴，并将它托付给受命收容失控魔法异常体的干练法师。在奥术波动扰乱周围空气的地方，例如炼金房内奥格诺恩的炼金工坊，大声诵读卷轴上的文字，就能迫使游荡的裂隙生物显形。施法者随后便可制服它们，将其困在收容箱中，以供进一步研究。"}},faq={{q="显形卷轴有什么作用？",a="显形卷轴能让隐形的奥术异常体显形。在受到魔法裂隙或扰动影响的区域诵读卷轴，就能迫使裂隙生物等看不见的生物显形，让你能够与它们战斗并将其捕获。",al={"显形卷轴是什么","显形卷轴用途","显形卷轴如何起效"}},{q="在幽暗城哪里能找到显形卷轴？",a="你可以在幽暗城魔法区的法师训练师安娜斯塔西娅·哈特威尔正后方的地板上找到显形卷轴。",al={"显形卷轴幽暗城位置","显形卷轴在哪里","幽暗城寻找显形卷轴"}},{q="安娜斯塔西娅·哈特威尔为什么需要有人使用这份卷轴？",a="炼金房内奥格诺恩的炼金商店出现了一股奇怪的魔法扰动。完全由魔法构成的隐形生物开始在那里游荡，因此安娜斯塔西娅·哈特威尔需要你到现场诵读卷轴，让它们显形，并在裂隙恶化之前将其捕获。",al={"为何使用显形卷轴","哈特威尔任务动机","安娜斯塔西娅魔法扰动"}},{q="使用后可以保留卷轴吗？",a="不可以。让裂隙生物显形并将它们捕获到收容箱中后，要把显形卷轴和收容箱交还给安娜斯塔西娅·哈特威尔。",al={"保留显形卷轴","显形卷轴会失去吗","归还显形卷轴"}}},fx={["1a839123"]={q="显形卷轴是什么？",a="显形卷轴是法师使用的一种特殊奥术卷轴。在被施放时，其咒语能穿透魔法伪装，迫使纯粹由奥术能量构成的隐形实体在肉眼下显形。",al={"什么是显形卷轴","显形卷轴道具","显形卷轴有什么用"}},f236f2b5={q="为什么安娜斯塔西娅·哈特威尔想要显形卷轴？",a="幽暗城的炼金房中，奥格诺恩的商店周围出现了隐形的魔法生物，这标志着魔法流出现了裂隙。法师训练师需要阅读这份卷轴，以便让学徒显现并捕获这些实体进行研究，从而让幽暗城的法师们确定这次扰动是意外，还是主动的魔法攻击。",al={"为什么要显形卷轴","为什么需要显形卷轴","为什么安娜斯塔西娅想要显形卷轴"}}},fp="26,98,23.426.0,44.216.0,44.118.0,50.258.0,43.155.0"}
P.entries["item:canvas-scraps"] = {n="帆布脚料",s="在剃刀岭，弗恩·凝眉收集帆布脚料，为部落新兵制作行囊。这些布料来自杜隆塔尔的人类入侵者和半人马部族。",h="在剃刀岭，弗恩·凝眉收集帆布脚料，为部落新兵制作行囊。这些布料来自杜隆塔尔的人类入侵者和半人马部族。",kw={"帆布脚料","新的背包","杜隆塔尔","弗恩·凝眉","科卡尔","库尔提拉斯","剃刀岭"},ang={["faction:Horde"]="从库尔提拉斯入侵者或科卡尔劫掠者手中夺来的每一块脚料，都能帮助装备杜隆塔尔各地响应萨尔号召的新守卫。",["profession:Tailoring"]="战士们收集编织帆布作为可回收的原料，这些结实的布料可以制成适合严酷沙漠环境的实用背包。"},sec={{t="杜隆塔尔敌人的战利品",b="库尔提拉斯的海军陆战队员和水手沿杜隆塔尔东海岸携带着帆布。他们的装备和船帆会留下碎布。在内陆，科卡尔半人马会重新利用从补给商队和以往战斗中夺来的粗布。他们的营地和装备中都有可以回收的碎布。"},{t="老兵的手艺",b="弗恩·凝眉在剃刀岭的哨塔上监视入侵者。这位年迈的老兵已不再征战，却仍能利用回收的敌方布料。他将这些布料缝成结实的背包，交给年轻的士兵，帮助新一代守卫部落的边疆。"}},faq={{q="帆布脚料从哪里来？",a="帆布脚料来自杜隆塔尔各地的人类和半人马敌人。提拉加德城堡及东海岸沿线的库尔提拉斯部队携带着这些布料，内陆营地附近的科卡尔半人马苦工和斥候也一样。",al={"谁掉落帆布脚料","哪里获取帆布脚料","刷帆布脚料"}},{q="弗恩·凝眉为什么需要这些脚料？",a="弗恩·凝眉是剃刀岭哨塔里一位年迈的兽人老兵，已无法在前线作战。他将回收的布料缝成行囊，供年轻的冒险者使用。",al={"谁需要帆布脚料","帆布脚料有什么用","弗恩·凝眉 帆布"}},{q="库尔提拉斯部队和半人马为什么携带帆布？",a="库尔提拉斯部队乘战舰来到杜隆塔尔，并在海边驻营，帆布和编织布料都是他们的日常必需品。科卡尔半人马则通过劫掠商队、搜寻海岸，以及在干旱的平原上抢劫旅人来获取粗布。",al={"半人马为什么有帆布","人类 帆布脚料 背景故事"}}},fx={["6d5b894e"]={q="什么是帆布脚料？",a="帆布脚料是从杜隆塔尔各地敌人的营地和装备中回收的厚实织物碎片。帆布比普通的亚麻布更结实，广泛用于重型军事装备、风帆和坚固的帐篷。虽然这些碎片在战场上看起来像是垃圾，但它们耐用的纤维可以很容易地被熟练的裁缝或工匠改造成实用的补给品，例如为行军的战士制作坚固的背包。",al={"什么是帆布脚料","帆布脚料道具","帆布脚料是做什么的"}}},fp="13,157,29.252.0,17.288.0,33.206.0,42.178.0,53.257.0"}
P.entries["item:cask-of-merlot"] = {n="一桶葡萄酒",s="暴风城的一桶葡萄酒为湖畔镇提供补给，而黑石兽人切断了当地的贸易路线。",h="暴风城的一桶葡萄酒为湖畔镇提供补给，而黑石兽人切断了当地的贸易路线。",kw={"酒吧老板丹尼尔","一桶葡萄酒","旱季","加林酒坊","湖畔镇","葡萄酒","罗伯特·奥布斯","暴风城"},ang={["faction:Alliance"]="对联盟而言，运送这桶酒让人看到了暴风城安稳的运河区与赤脊山遭到围攻、战火不断的城镇之间的反差。"},sec={{t="王都的滋味",b="这种葡萄酒的葡萄采自王国腹地，也在那里发酵，酒则出自加林纳酒庄的酒窖。酒庄坐落在暴风城贸易区边缘的运河沿岸，酿酒师罗伯特·奥布斯在此照料佳酿，以满足王都挑剔的口味。与暮色森林的月光酒或艾尔文的烈酒不同，这种葡萄酒体现了城墙内人类酿酒师的手艺。"},{t="为湖畔镇补充酒水",b="黑石氏族入侵赤脊山后，补给路线中断，湖畔镇也失去了商人定期运来的货物。当地居民口渴难耐，又惊恐不安，酒吧老板丹尼尔便派遣自愿跑腿的人穿越王国，为酒馆的酒窖补充存货。这桶酒让止水湖畔的守军和难民能用温和的酒水佐餐。"}},faq={{q="在哪里能找到一桶葡萄酒？",a="罗伯特·奥布斯在加林酒庄内出售一桶葡萄酒，酒庄位于暴风城贸易区边缘的运河沿岸。",al={"一桶葡萄酒位置","哪里买葡萄酒","谁出售一桶葡萄酒","暴风城葡萄酒商人"}},{q="酒吧老板丹尼尔为什么需要这种葡萄酒？",a="黑石兽人入侵赤脊山，切断了湖畔镇的常规货运，酒吧老板丹尼尔的酒水也快耗尽了。他派冒险者奔走于艾泽拉斯南部，收集各地的特色酒水，让酒客们喝得满意。",al={"旱季任务葡萄酒","丹尼尔为什么要葡萄酒","湖畔镇葡萄酒用途"}},{q="除了葡萄酒，还要收集哪些酒水？",a="丹尼尔还需要来自闪金镇的一袋蜂蜜酒、来自夜色镇的一瓶月光酒，以及西部荒野丘陵中葛瑞姆·雷酒提供的一桶雷霆啤酒。",al={"旱季酒水","丹尼尔酒水清单","旱季其他酒水"}},{q="加林酒庄有危险吗？",a="加林酒庄位于暴风城的石砌城墙之后，安然无恙。匪徒和兽人的袭击侵扰着西部荒野和赤脊山等外围地区，而王都运河区的贸易和酿酒仍在继续。",al={"加林纳酒庄背景故事","暴风城的酒庄"}}},fx={e882dee4={q="一桶葡萄酒是什么？",a="这是一种在暴风城生产和销售的优质红酒，装在一个大容器里。虽然普通市民将其作为日常美酒享用，但那些陷入动荡的边远定居点却将这种散装烈酒视为珍宝，以维持当地酒馆的库存并提振当地民心。",al={"什么是一桶葡萄酒","一桶葡萄酒道具","一桶葡萄酒是什么东西"}},["33c97a45"]={q="一桶葡萄酒来自哪里，是谁制作的？",a="这桶酒来自位于暴风城贸易区边缘运河旁的加利纳酒庄。它由罗伯特·普佩里弗伯斯准备并出售，他负责向城市顾客和旅行商人供应酒庄备受欢迎的陈酿。",al={"一桶葡萄酒的起源","谁制作了葡萄酒","一桶葡萄酒来自哪里"}}},fp="14,93,22.330.0,20.362.0,34.153.0,40.233.0,53.179.0,31.210.0"}
P.entries["item:cask-of-scalder"] = {n="一桶热酒",s="在暴风城，一桶热麦酒即将送到一位老相识手中。这烈性麦酒承载着矮人之间的一份人情。",h="在暴风城，一桶热麦酒即将送到一位老相识手中。这烈性麦酒承载着矮人之间的一份人情。",kw={"麦酒","一桶热酒","矮人区","弗伦·长须","铸盾师","暴风城"},ang={["class:Warrior"]="身为战士，你可以带上一桶好麦酒，求弗伦·长须施展他闻名遐迩的锻造技艺。这是获得可靠防护的必经考验。",["race:Dwarf"]="身为矮人，你知道一桶新酿的麦酒佳酿足以促成一笔交易，或是了结一份旧日的人情。"},sec={{t="矮人的交易",b="在瑞斯班挑战中证明了自己的旅人，会将热麦酒带给暴风城矮人区的弗伦·长须。弗伦是一位技艺精湛的铸盾师，最受不了无酒可喝的日子。这桶酒让犹鲁斯·麦酒得以讨回一份旧人情，为送酒人求得矮人精工打造的装备。"}},faq={{q="一桶热酒里装的是什么？",a="桶里装着热麦酒，是麦酒家族酿造的烈酒。矮人喜爱它浓烈的风味和暖身的劲道。",al={"里面装的什么酒","热麦酒麦酒","热麦酒"}},{q="这桶酒是送给谁的？",a="这桶酒是送给弗伦·长须的，他是暴风城矮人区的一位矮人铸盾大师。",al={"酒桶送给谁","送到哪里","热麦酒收件人"}},{q="为什么要把这桶酒送给弗伦·长须？",a="弗伦欠犹鲁斯·麦酒一份人情。这桶酒能在弗伦所谓的无酒之日为他解渴，也能说动他为送酒人锻造一面坚固而出众的盾牌。",al={"弗伦为什么想要热麦酒","铸盾师的人情","酒桶的用途"}}},fx={df3534f2={q="一桶热酒是什么？",a="一桶热酒是一个木桶，里面装满了麦酒家族酿造的烈性酒——麦酒热酒。尤鲁斯·麦酒将其作为礼物委托给你，介绍给他在暴风城的矮人朋友：盾甲匠弗伦·长须。",al={"什么是一桶热酒","一桶热酒","热酒是什么"}},["1fd358f8"]={q="一桶热酒来自哪里，是谁制作的？",a="这桶酒由赤脊山的尤鲁斯·麦酒在你通过瑞斯班的挑战后提供。这种独特的酒由著名的麦酒家族酿造，作为一份能换取矮人大师打造的盾牌的厚礼，这份心意再合适不过了。",al={"谁制作了一桶热酒","一桶热酒的起源","一桶热酒来自哪里"}}},fp="15,123,17.311.0,35.132.0,30.99.0,52.170.0"}
P.entries["item:cask-of-shimmer-stout"] = {n="一桶微光酒",s="在丹莫罗寒冷的高地上，一桶微光酒即将被送往东部群山。雷杰德·麦酒酿出了这种劲头十足的新啤酒，他的兄弟要将一桶酒送往东方，作为礼物赠给那里的矮人巡山同袍。",h="在丹莫罗寒冷的高地上，一桶微光酒即将被送往东部群山。雷杰德·麦酒酿出了这种劲头十足的新啤酒，他的兄弟要将一桶酒送往东方，作为礼物赠给那里的矮人巡山同袍。",kw={"一桶微光酒","丹莫罗","卡德雷尔","洛克莫丹","雷杰德·麦酒","微光酒","塞尔萨玛"},ang={["race:Dwarf"]="身为矮人，你知道在巡逻间隙分享美酒是一项备受尊重的传统。它将分散在卡兹莫丹险峻群峰间的Mountaineers紧紧联系在一起。"},sec={{t="送去一桶好酒",b="雷杰德·麦酒在烈酒村酿造微光酒。当地的酒客和冒着丹莫罗刺骨严寒的巡山人很快就喜欢上了它。他的兄弟巡山人维拉特·麦酒对这种酒赞不绝口，特意订了一桶，要穿过东部山口送往洛克莫丹。在群山的寒气中，矮人珍视烈酒，既用它助兴，也用它暖身。与在远方巡逻的同袍分享新酿的啤酒，是军中的传统。"},{t="矮人的提神佳酿",b="巡山人卡德雷尔在塞尔萨玛值守时，打开酒桶，尝了尝这新酿的啤酒。微光酒果然名不虚传：据说喝上一口，就能让人四肢轻盈，觉得自己仿佛能飞起来。对于在高山道路上独自长途巡逻的矮人斥候来说，这样一杯振奋精神的酒想必很受欢迎。"}},faq={{q="微光酒是什么？",a="雷杰德·麦酒在丹莫罗寒冷的高地上酿造微光酒。这种酒劲头十足，以振奋精神、驱散寒意而闻名。",al={"微光酒是什么","微光酒的故事","谁酿造了微光酒"}},{q="这桶酒要送给谁？",a="这桶酒要送给巡山人卡德雷尔，他是一名守卫，驻守在洛克莫丹途经塞尔萨玛的道路沿线。",al={"酒桶送给谁","酒桶送往哪里","酒桶收件人"}},{q="为什么要翻山送酒？",a="矮人巡山人经常与在远方巡逻的同袍分享佳酿。尝过雷杰德·麦酒新酿的酒后，他的兄弟想让卡德雷尔也尝一尝。",al={"为何送酒","为什么送啤酒","为什么送给卡德雷尔"}},{q="喝下微光酒会有什么效果？",a="微光酒的酒劲出奇地大。巡山人卡德雷尔尝过之后说，这酒让他头晕目眩，四肢轻盈，觉得自己仿佛能飞起来。",al={"微光酒酒劲多大","微光酒的效果"}}},fx={aa5543f0={q="一桶微光酒来自哪里，是谁制作的？",a="这种烈酒由丹莫罗烈酒村的雷杰德·麦酒酿造。他的兄弟，巡山人维拉特·麦酒对这个配方印象深刻，于是打包了这桶酒想要在家乡之外分享，并让一位冒险者将它一路带到了洛克莫丹。",al={"谁制作了微光酒","微光酒来自哪里","一桶微光酒的酿造者"}},["3b29018e"]={q="为什么会有人想要一桶微光酒？",a="巡山人维拉特·麦酒很喜欢他兄弟的新配方，并希望另一位巡山人，巡山人卡德雷尔也能尝尝。卡德雷尔负责在塞尔萨玛周围寒冷的道路上巡逻，而一种能暖身、松骨、让人晕乎乎的烈性矮人麦酒，在漫长的值守期间是极好的慰藉。",al={"为什么要送微光酒","谁想要一桶微光酒","为什么卡德雷尔想要微光酒"}}},fp="21,209,19.430.0,20.316.0,22.150.0,30.108.0,34.162.0,51.167.0"}
P.entries["item:cats-eye-emerald"] = {n="猫眼翡翠",s="在贫瘠之地北部，猫眼翡翠引起了棘齿城的码头管理员迪兹维格的注意。荆棘谷地精的头目们将这颗拳头大小的宝石存放在石矿洞，派人看守。",h="在贫瘠之地北部，猫眼翡翠引起了棘齿城的码头管理员迪兹维格的注意。荆棘谷地精的头目们将这颗拳头大小的宝石存放在石矿洞，派人看守。",kw={"考博普拉格","石矿洞","猫眼翡翠","翡翠","棘齿城","淤泥沼泽","荆棘谷地精","码头管理员迪兹维格"},ang={["class:Rogue"]="身为潜行者，从腐败的荆棘谷地精工头眼皮底下偷走一颗巨大的宝石，是一次趁机获利的机会。",["profession:Mining"]="身为矿工，在石矿洞这样的工业采掘场发现一颗完美无瑕、拳头大小的宝石，是每个矿工都梦寐以求的好运。"},sec={{t="拳头大小的财富",b="荆棘谷地精的劳工在淤泥沼泽东北方的石矿洞挖出了一颗巨大的翡翠。发现宝石的消息很快传遍了大草原。在地精的地盘上，稀有宝石的消息很少能藏得住。商人间的传闻将消息从棘齿城的码头带到了藏宝海湾，码头管理员迪兹维格也听说了这件宝物。他开始盘算着将它送往安德麦的公开市场。"},{t="公司财产",b="荆棘谷地精的管理层将翡翠存放在矿洞内，派重兵看守。监工、执行者，以及考博普拉格这样的主管负责守卫宝石，防备敌对财阀和寻宝者。迪兹维格承诺，谁能帮他弄到宝石，就能分得一半收益。"}},faq={{q="猫眼翡翠是什么？",a="猫眼翡翠是一颗异常巨大的翡翠，约有拳头大小，由矿工在贫瘠之地北部发现。它的净度和大小使其在全球市场上价值连城。",al={"猫眼翡翠是什么","猫眼宝石","这是什么宝石"}},{q="这颗宝石是在哪里发现的？",a="荆棘谷地精的矿工在石矿洞内挖出了这颗宝石，那里位于贫瘠之地北部、淤泥沼泽的东北方。",al={"在哪里发现的","宝石位置","石矿洞翡翠"}},{q="棘齿城里谁想要这颗翡翠？",a="码头管理员迪兹维格负责管理棘齿城码头的航运和货物，他想通过安德麦的贸易关系，将这颗宝石卖给富有的买家。",al={"谁收购翡翠","迪兹维格翡翠","谁提供翡翠任务"}},{q="矿洞里是谁保管着这颗宝石？",a="荆棘谷地精的高级主管将翡翠保管在石矿洞内。一名荆棘谷地精的监工或执行者随身带着它。",al={"谁掉落翡翠","谁持有猫眼翡翠","哪里能找到猫眼翡翠"}}},fx={["24f13ef4"]={q="猫眼翡翠来自哪里？",a="猫眼翡翠是一颗天然的、拳头大小的宝石，是在贫瘠之地淤泥沼泽东北部的石矿洞（荆棘谷地精的一个挖掘场）深处出土的。它并非由工匠锻造或切割，而是最近由该地精公司里一位运气较好的矿工从地里挖掘出来的。",al={"猫眼翡翠的起源","在哪里发现了猫眼翡翠","谁制作了猫眼翡翠"}}},fp="16,158,20.372.0,18.275.0,29.184.0,29.115.0,33.145.0,41.135.0"}
P.entries["item:cenarion-lunardust"] = {n="赛纳里奥银尘",s="图拉克·符文图腾在雷霆崖将赛纳里奥银尘交给年轻的牛头人德鲁伊。他们用它唤醒月爪枭兽，地点就在莫高雷与贫瘠之地之间一块古老的月夜枭兽之石旁。",h="图拉克·符文图腾在雷霆崖将赛纳里奥银尘交给年轻的牛头人德鲁伊。他们用它唤醒月爪枭兽，地点就在莫高雷与贫瘠之地之间一块古老的月夜枭兽之石旁。",kw={"身躯与心灵","赛纳里奥银尘","利爪德鲁伊","月爪枭兽","银尘","月夜枭兽之石","图拉克·符文图腾"},ang={["class:Druid"]="作为牛头人德鲁伊，你会在成长仪式中使用这种银尘，开启变身为熊的道路。",["race:Tauren"]="作为牛头人，你以年轻 Shu'halo 的身份领到银尘，加深自己与塞纳里奥议会教诲、自然以及卡利姆多野性之灵的联系。"},sec={{t="身躯与心灵的仪式",b="赛纳里奥银尘承载着塞纳里奥议会的祝福，赐予那些准备加入 利爪德鲁伊 的德鲁伊。在陶拉祖营地以西的月夜枭兽之石旁，银尘会召来月爪枭兽，这头神圣的野兽肩负着考验每一位新人的使命。击败这位守护者，考验的是力量与决心。这场试炼让年轻的德鲁伊领悟化身为熊所需的身躯与心灵的力量。"}},faq={{q="赛纳里奥银尘有什么用途？",a="将赛纳里奥银尘撒在月夜枭兽之石上，它位于莫高雷与贫瘠之地之间的山丘中，陶拉祖营地以西。银尘会召唤月爪枭兽，新人必须击败它，证明自己的力量。",al={"银尘有什么用","如何使用赛纳里奥银尘","银尘用途"}},{q="谁会提供赛纳里奥银尘？",a="图拉克·符文图腾是雷霆崖长者高地上的德鲁伊训练师，他会将银尘交给接受熊形态试炼的牛头人德鲁伊。",al={"谁给银尘","哪里领取赛纳里奥银尘","图拉克·符文图腾的银尘"}},{q="如果丢失了赛纳里奥银尘，该怎么办？",a="如果你丢失了银尘，或未能击败月爪枭兽，就回到雷霆崖长者高地，向图拉克·符文图腾再领取一袋。",al={"银尘丢失","需要更多银尘","哪里再领一份银尘"}},{q="德鲁伊为何必须面对月爪枭兽？",a="德鲁伊面对石头的守护者月爪枭兽，是为了考验身体的力量与内心的决心。击败这头野兽后，立志成为利爪德鲁伊的德鲁伊便能领悟身躯与心灵的真谛，从而驾驭巨熊之灵的力量。",al={"为何与 月爪枭兽 战斗","月爪枭兽 是谁","月爪枭兽 的作用"}}},fx={ca885fb9={q="什么是赛纳里奥银尘？",a="赛纳里奥银尘是由塞纳里奥德鲁伊制作的一种圣粉，只授予那些展现出奉献精神的入门者。当把它撒在贫瘠之地和莫高雷边界附近的枭兽石上时，银尘的魔法会召唤出卢娜爪，以考验年轻的德鲁伊是否具备行走利爪之路所需的体魄与心灵力量。",al={"什么是银尘","赛纳里奥银尘传说","塞纳里奥之尘"}},d52557a0={q="为什么会有人想要赛纳里奥银尘？",a="只有有志于成为德鲁伊的人才会寻求这种粉末，因为它是召唤枭兽石处的卢娜爪的关键。没有它，守护者就不会出现，导致入门者无法面对考验，也无法获得成为真正的利爪德鲁伊所需的精神力量。",al={"为什么要银尘","谁想要赛纳里奥银尘","为什么要使用银尘"}}},fp="18,171,24.360.0,36.197.0,36.138.0,49.126.0,31.232.0"}
P.entries["item:cenarion-moondust"] = {n="塞纳里奥月尘",s="在奥伯丁以东的月夜枭兽之石，塞纳里奥月尘能召唤出月爪枭兽。暗夜精灵德鲁伊在成为利爪德鲁伊的试炼中使用这种神圣的粉末。",h="在奥伯丁以东的月夜枭兽之石，塞纳里奥月尘能召唤出月爪枭兽。暗夜精灵德鲁伊在成为利爪德鲁伊的试炼中使用这种神圣的粉末。",kw={"奥伯丁","身心","塞纳里奥月尘","利爪德鲁伊","月爪枭兽","玛斯雷·驭熊者","月尘","月夜枭兽之石"},ang={["class:Druid"]="身为暗夜精灵德鲁伊，使用塞纳里奥月尘，就迈出了成为利爪德鲁伊并掌握熊形态的最后一步。",["race:NightElf"]="身为暗夜精灵，你能从这月尘中接触到塞纳里奥议会的古老传统，它将自然崇拜与月亮仪式结合起来，向黑海岸的野兽致敬。"},sec={{t="利爪仪式",b="玛斯雷·驭熊者在达纳苏斯将塞纳里奥月尘交给年轻的德鲁伊，让他们接受最后的身心试炼。为了面对守护者月爪枭兽，学徒要前往黑海岸奥伯丁以东的枭兽巢穴。将粉末撒在古老的月夜枭兽之石上，就能召唤月爪枭兽，在战斗中考验德鲁伊。通过这场试炼，学徒将汲取驾驭熊形态所需的持久力量。"}},faq={{q="塞纳里奥月尘有什么用途？",a="暗夜精灵德鲁伊学徒将塞纳里奥月尘撒在黑海岸的月夜枭兽之石上，召唤月爪枭兽，在获取熊形态的试炼中证明自己的力量与决心。",al={"月尘用途","塞纳里奥月尘有什么作用","塞纳里奥月尘用途"}},{q="在哪里使用塞纳里奥月尘？",a="在黑海岸奥伯丁正东方的山丘中，找到枭兽洞穴，将塞纳里奥月尘撒在洞内的月夜枭兽之石上。",al={"月尘使用地点","月夜枭兽之石位置","月爪枭兽石头在哪里"}},{q="谁会提供塞纳里奥月尘？",a="玛斯雷·驭熊者是达纳苏斯塞纳里奥区的德鲁伊训练师，他会将塞纳里奥月尘交给准备好接受身心试炼的学徒。",al={"谁提供月尘","塞纳里奥月尘获取地点","玛斯雷月尘"}},{q="如果弄丢了月尘怎么办？",a="如果月尘丢失，或在挑战月爪枭兽失败时耗尽，就返回达纳苏斯，请玛斯雷·驭熊者重新开启试炼。",al={"塞纳里奥月尘丢失","月尘丢失","重新获取月尘"}}},fx={d9963f3d={q="什么是塞纳里奥月尘？",a="塞纳里奥月尘是塞纳里奥议会赐予暗夜精灵德鲁伊的一种圣粉，他们寻求的是利爪德鲁伊的职责。它带有大自然的祝福，被用作一种仪式试剂来纪念并召唤古代的守护之灵。",al={"什么是塞纳里奥月尘","塞纳里奥月尘传说","月尘的用途"}},["34087882"]={q="塞纳里奥月尘来自哪里，是谁制作的？",a="这种粉末由达纳苏斯的塞纳里奥议会准备和保管。它专门由玛斯雷·驭熊者这样的德鲁伊训练师授予那些表现出敬意并赢得了进行神圣试炼权利的入门者。",al={"谁制作了塞纳里奥月尘","塞纳里奥月尘的起源","月尘来自哪里"}},["1f04d9d3"]={q="为什么需要塞纳里奥月尘？",a="月尘是唤醒卢娜爪所必需的，它是守护黑海岸枭兽石的古代野兽。卢娜爪只会回应那些将这种圣粉洒在石头上的入门者的挑战，让德鲁伊证明他们的体魄与心灵力量。",al={"为什么我需要塞纳里奥月尘","为什么要使用月尘","塞纳里奥月尘的目的是什么"}}},fp="17,150,18.391.0,35.167.0,37.120.0,31.152.0,36.144.0"}
P.entries["item:centaur-bracers"] = {n="半人马护腕",s="在贫瘠之地各处，半人马护腕被从遭击杀的科卡尔战士身上剥下。雷戈萨·死门在十字路口以西收集这些护腕，作为半人马劫掠者已被消灭的证明。",h="在贫瘠之地各处，半人马护腕被从遭击杀的科卡尔战士身上剥下。雷戈萨·死门在十字路口以西收集这些护腕，作为半人马劫掠者已被消灭的证明。",kw={"贫瘠之地","悬赏","护腕","半人马","十字路口","死门","科卡尔","雷戈萨"},ang={["faction:Horde"]="作为部落的一员，你击杀科卡尔劫掠者，就是在帮助保护杜隆塔尔、莫高雷和十字路口之间的商队补给线。",["race:Tauren"]="作为牛头人，你知道自己的族人数代以来饱受半人马氏族的残酷侵扰。清除贫瘠之地的科卡尔，既能报仇，也能带来安宁。"},sec={{t="残酷的悬赏",b="科卡尔劫掠者威胁着部落在贫瘠之地各处的据点。他们阵亡的战士留下皮革和铁制的护腕，证明商路上少了一名劫掠者。雷戈萨·死门是一名驻守在十字路口以西高地上的兽人斥候，他长期悬赏收集这些战利品，以遏制这个部族的侵袭。"}},faq={{q="谁需要这些护腕？",a="雷戈萨·死门是一名部落斥候，在贫瘠之地十字路口以西的一处高地扎营，他收取这些护腕，作为你对抗当地科卡尔半人马的证明。",al={"谁收半人马护腕","雷戈萨·死门交付","谁买半人马护腕"}},{q="哪些半人马携带这些护腕？",a="科卡尔战士佩戴着这些护腕，在贫瘠之地北部的绿洲和营地间游荡，其中包括遗忘之池和甜水绿洲。",al={"哪里刷护腕","科卡尔护腕掉落","半人马护腕来源"}},{q="雷戈萨为什么要收集这些护腕？",a="雷戈萨想要削减科卡尔的数量，以保护部落领土。这些护腕证明勇士们确实击杀了劫掠者，而非只是将他们赶走。",al={"为什么收集护腕","雷戈萨·死门的动机","半人马护腕用途"}}},fx={["2b8929fb"]={q="什么是半人马护腕？",a="这些护腕是贫瘠之地各处的半人马战士所穿戴的粗糙护甲。它们是从被杀死的科卡尔掠夺者手臂上剥下来的，对于部落来说，它们是猎人成功猎杀其好战部族的严酷实物证明。",al={"什么是半人马护腕","半人马护腕传说","半人马护腕是什么"}},e954048b={q="半人马护腕来自哪里？",a="它们由游荡在卡利姆多干旱平原上的半人马氏族，特别是敌对的科卡尔部族锻造或制作。战士们装备它们用于战斗，作为抵御许多敌人刀剑、箭矢和利爪的原始防护。",al={"谁制作了半人马护腕","半人马护腕的起源","半人马护腕来自哪里"}}},fp="15,175,15.349.0,24.184.0,34.145.0,37.153.0"}
P.entries["item:charred-horn"] = {n="烧焦的奇美拉角",s="在暴风城，弗伦·长须需要采自石爪山年轻奇美拉的烧焦的奇美拉角。这些角能抵御火焰、钝击和猛烈的元素力量，适合用来打造坚固的护甲。",h="在暴风城，弗伦·长须需要采自石爪山年轻奇美拉的烧焦的奇美拉角。这些角能抵御火焰、钝击和猛烈的元素力量，适合用来打造坚固的护甲。",kw={"烧焦的奇美拉角","奇美拉","火焰淬炼锁甲","弗伦·长须","石爪山","石爪山脉"},ang={["class:Warrior"]="身为战士，你可以在卡利姆多各地为弗伦·长须收集烧焦的奇美拉角。他会以量身打造的火焰淬炼锁甲，酬谢你这趟危险的旅程。",["profession:Blacksmithing"]="身为铁匠，你可以看出，这些角如何利用卡利姆多掠食者身上经天然火焰淬炼的材料来强化锁甲链环。"},sec={{t="稀有的锻造材料",b="石爪山脉的雏生奇美拉和年轻奇美拉会掉落烧焦的奇美拉角。这些角能抵御火焰和钝击，对在暴风城铁砧旁工作的矮人护甲匠弗伦·长须很有用。他需要十二个角来打造火焰淬炼锁甲。\n\n弗伦将这些角与湿地的毒蜘蛛牙、剃刀沼泽的燃素，以及奇美拉族母的光滑的奇美拉角结合起来。烧焦的奇美拉角提供经过热处理的材料，用来加固锁甲的链环和甲片。"}},faq={{q="哪些生物会掉落烧焦的奇美拉角？",a="卡利姆多石爪山脉的雏生奇美拉和年轻奇美拉会掉落烧焦的奇美拉角。",al={"烧焦的奇美拉角获取地点","烧焦的奇美拉角掉落生物","烧焦的奇美拉角来源"}},{q="暴风城里谁需要这些角？",a="暴风城的护甲匠弗伦·长须需要这些角。他用这些角为有潜力的战士锻造坚固的锁甲胸甲。",al={"烧焦的奇美拉角使用者","上交烧焦的奇美拉角","弗伦·长须的角"}},{q="为什么弗伦需要这么多角？",a="弗伦需要十二个烧焦的奇美拉角，才能获得足够的热处理材料，加固他打造的火焰淬炼锁甲的链环和甲片。",al={"为何需要十二个烧焦的奇美拉角","烧焦的奇美拉角用途"}},{q="这些角和光滑的奇美拉角有区别吗？",a="有。烧焦的奇美拉角来自石爪山较年轻的奇美拉。光滑的奇美拉角则是从雌奇美拉身上取得的单个战利品，要稀有得多。",al={"光滑的奇美拉角与烧焦的奇美拉角对比","角的区别"}}},fx={["785d7f85"]={q="什么是烧焦的奇美拉角？",a="烧焦的奇美拉角是从游荡在石爪山脉山峰上的幼年奇美拉身上收获的一种坚硬、发黑的角。在严酷的山地气候和野兽元素本性的作用下，这些角拥有独特的耐用性，使其成为一种用于专业锻造的珍贵原材料。",al={"什么是烧焦的奇美拉角","烧焦的奇美拉角传说","关于烧焦的奇美拉角"}}},fp="12,187,25.490.0,34.92.0,35.132.0,39.133.0,45.154.0"}
P.entries["item:chest-of-containment-coffers"] = {n="一盒封灵箱",s="幽暗城的法师将一盒封灵箱放在手边。其中的附魔容器能够收容不稳定的魔法异象。",h="幽暗城的法师将一盒封灵箱放在手边。其中的附魔容器能够收容不稳定的魔法异象。",kw={"安娜斯塔西娅·哈特威尔","炼金房","奥术异常","封灵箱","魔法区","裂隙衍生物"},ang={["class:Mage"]="身为法师，你可以使用这些野外工具控制不稳定的奥术显现，并保留活体样本供研究。",["race:Undead"]="身为被遗忘者，你可以用这些封灵箱收容炼金房附近的魔法异常，防止未经检验的奥术力量侵蚀你的研究工作。"},sec={{t="无形之物的容器",b="隐形的奥术生物可能从实验中出现，也可能从位面之间突然裂开的缝隙中涌出。普通牢笼无法囚禁由魔法构成的生物。一盒封灵箱中装着附魔容器，能将被制服的生物活着封入其中。资深导师会将这盒容器放在身边，包括幽暗城的安娜斯塔西娅·哈特威尔和暴风城的詹妮亚·坎农。他们将封灵箱交给学徒，用于调查异常现象，以免这些力量扰乱周遭环境。"},{t="奥术收容规程",b="炼金房内奥格诺恩的店铺中出现了无形的扰动，被遗忘者导师便派法师携带封灵箱前去收容。法师先用特殊卷轴使裂隙实体显形，再施法削弱它，最后将其困入盒中的封灵箱。被遗忘者研究者可以安全地解剖并研究捕获的生物，判断这些扰动究竟源于Ley中的偶发裂隙，还是蓄意发动的奥术袭击。"}},faq={{q="一盒封灵箱里面装着什么？",a="盒中装着空的附魔封灵箱。在危险的实地调查中，法师用它们收容并困住被制服的魔法生物，例如裂隙衍生物。",al={"盒子提供什么","封灵箱内的东西","盒中物品"}},{q="在哪里可以找到这盒容器？",a="在幽暗城，这盒容器放在魔法区的法师训练师安娜斯塔西娅·哈特威尔身后。暴风城的巫师圣殿中，詹妮亚·坎农身后也放着同样的一盒容器。",al={"一盒封灵箱位置","一盒封灵箱在哪里","封灵箱盒子位置"}},{q="为什么法师需要这些封灵箱，而不用普通牢笼？",a="裂隙衍生物由无形的奥术能量构成，普通材料无法将其囚禁。附魔封灵箱能够困住这些异常存在，并使其稳定下来。",al={"为什么使用封灵箱","封灵箱有什么用","封灵箱如何运作"}},{q="封灵箱装满后会如何处理？",a="资深导师会接收装满的封灵箱，用于研究。研究者分析捕获的生物，以确定扰动是源于意外产生的自然裂隙，还是外部势力蓄意发动的攻击。",al={"被捕获的裂隙衍生物如何处理","装满的封灵箱用途","为什么捕获生物"}}},fx={fa57c13a={q="一盒封灵箱是什么？",a="这是一个沉重的补给箱，由法师导师保管，用于装备调查魔法异常的从业者。里面放着一套特制的附魔封灵箱，专门用于束缚和容纳那些纯粹由奥术能量构成的、不稳定的非物质实体。",al={"什么是一盒封灵箱","一盒封灵箱","封灵箱盒子"}},c9b5ba3b={q="为什么安娜斯塔西娅·哈特威尔想要你带走一盒封灵箱？",a="安娜斯塔西娅·哈特威尔探测到幽暗城炼金房里奥格诺恩的炼金商店周围游荡着隐形的魔法实体。普通的束缚手段无法触及这些完全由原始魔法编织而成的生物，所以她为你提供了这盒特制的封灵箱，以便将这些异常实体活捉并进行研究。",al={"为什么要拿一盒封灵箱","为什么我需要封灵箱","为什么安娜斯塔西娅要封灵箱"}}},fp="28,132,22.427.0,28.429.1,48.153.0,30.177.0,56.145.0,49.207.0"}
P.entries["item:chief-sharptusk-thornmantle-s-head"] = {n="刺鬃酋长的头颅",s="刺鬃酋长的头颅标志着红云台地的一场威胁宣告终结。刺背的首领曾威胁年轻的牛头人勇士，而他的头颅被从刺刃峡谷深处带回，作为胜利的证明。",h="刺鬃酋长的头颅标志着红云台地的一场威胁宣告终结。刺背的首领曾威胁年轻的牛头人勇士，而他的头颅被从刺刃峡谷深处带回，作为胜利的证明。",kw={"刺刃","刺背","头颅","莫高雷","刺鬃酋长","刺鬃","风羽"},ang={["class:Hunter"]="对猎人而言，刺鬃酋长是一个也会反过来猎杀你的猎物。追踪并攻击这样聪明的敌人，考验着你的本领。",["race:Tauren"]="身为牛头人，取下强敌的头颅，标志着年轻的守卫迈出了重要的一步。这证明你有决心，也有本领保护族人的新家园。"},sec={{t="狩猎的战利品",b="刺刃峡谷的刺背野猪人袭击了纳拉其营地的各个部族。他们的酋长刺鬃酋长不断煽动他们进攻。牛头人力求以警惕和力量守护他们在莫高雷的家园。刺鬃酋长的头颅证明了他的死讯，也警告幸存的野猪人氏族不得侵犯台地边界。"},{t="狩猎的试炼",b="卫兵维萨罗·风羽要求年轻的猎人和部族守卫带回刺鬃酋长的头颅，以此作为他们的成年试炼。面对一个懂得还击、又能率领战团的聪明敌人，考验着年轻战士的武艺。献上这颗头颅就完成了试炼，也让这位年轻战士在红云台地的勇士中赢得声望。"}},faq={{q="卫兵维萨罗·风羽为什么想要刺鬃酋长的头颅？",a="卫兵维萨罗·风羽想要刺背酋长已被击杀的证明。刺鬃酋长再也无法指挥对纳拉其营地的袭击，而他的头颅也警告其余野猪人，他们的侵略将遭到坚决的武力反击。",al={"为何取下他的头颅","取下刺鬃酋长头颅的原因","风羽索要头颅"}},{q="刺鬃酋长酋长是谁？",a="刺鬃酋长酋长率领着红云台地东缘刺刃峡谷中的刺背野猪人。在他的指挥下，刺背不断骚扰并袭击年轻的牛头人勇士。",al={"刺鬃酋长是谁","刺鬃酋长的故事","莫高雷野猪人酋长"}},{q="这件战利品从何处获得？",a="你需要前往纳拉其营地以东的刺刃峡谷深处，在刺鬃酋长酋长临时搭建的部族村落中杀死他，取得他的头颅。",al={"头颅何处寻","刺鬃酋长头颅位置"}}},fx={["27fbe344"]={q="刺鬃酋长的头颅是从哪里来的？",a="这一可怕的战利品直接取自盘踞在刺刃峡谷的棘背野猪人酋长，该地就在纳拉其营地以东。刺鬃酋长集结了他那简陋的营地来对抗红云台地的牛头人，这使得勇士们要求得到他被砍下的头颅，以此作为棘背野猪人的战争努力已被粉碎的无可辩驳的证据。",al={"刺鬃酋长的头颅来源","刺鬃酋长的头颅从哪来","谁有刺鬃酋长的头颅"}}},fp="34,219,18.315.0,20.306.0,66.221.0,36.198.0,30.144.0"}
P.entries["item:chok-sul-s-head"] = {n="卓克苏尔的头颅",s="在塞尔萨玛，镇长埃罗恩·钝鼻要求用卓克苏尔的头颅证明他的死讯。当地矮人当局设下了悬赏，而镇长必须看到这份证据才会支付赏金。",h="在塞尔萨玛，镇长埃罗恩·钝鼻要求用卓克苏尔的头颅证明他的死讯。当地矮人当局设下了悬赏，而镇长必须看到这份证据才会支付赏金。",kw={"卓克苏尔","卓克苏尔的头颅","洛克莫丹","镇长埃罗恩·钝鼻","莫格罗什","食人魔","巨石水坝","塞尔萨玛"},ang={["race:Dwarf"]="身为矮人，击败卓克苏尔能减轻铁炉堡乡间定居点面临的威胁，并保护巨石水坝免遭摧毁。"},sec={{t="酋长伏诛的证据",b="莫格罗什要塞的食人魔威胁着洛克莫丹的定居点。他们袭击塞尔萨玛、挖掘场和巨石水坝。镇长埃罗恩·钝鼻悬赏捉拿卓克苏尔，这个蛮横的家伙被认为是这些袭击的指使者。\n\n东北部的丘陵动荡不安，因此镇长要求先提供证据，才肯拨付镇上的资金。卓克苏尔被斩下的头颅让矮人议会得以确认悬赏任务已经完成。"}},faq={{q="卓克苏尔是谁？",a="卓克苏尔是洛克莫丹东北部莫格罗什要塞的一名食人魔酋长。矮人官员认为，他指使手下袭击了塞尔萨玛、巨石水坝和附近的挖掘场。",al={"卓克苏尔是谁","卓克苏尔的故事","卓克苏尔的身份"}},{q="镇长埃罗恩·钝鼻为什么要这颗头颅？",a="镇长埃罗恩·钝鼻公开悬赏，无论使用何种手段，只求杀死卓克苏尔。食人魔的袭击让这一带不堪重负，因此他要求先拿出酋长确已死亡的证据，才肯从塞尔萨玛的金库中支付赏金。",al={"镇长埃罗恩·钝鼻为何要头颅","卓克苏尔头颅的用途","谁要卓克苏尔的头颅"}},{q="卓克苏尔在哪里活动？",a="卓克苏尔以莫格罗什要塞为据点，率领他的战团活动，那里位于洛克莫丹东北部崎岖的丘陵之中。",al={"卓克苏尔在哪里","莫格罗什要塞的位置","卓克苏尔的位置"}},{q="卓克苏尔对这一带构成了什么威胁？",a="卓克苏尔被认为指使手下袭击塞尔萨玛和附近的矮人工程设施，包括巨石水坝和当地的挖掘场。",al={"为何悬赏捉拿卓克苏尔","卓克苏尔做了什么"}}},fx={["8aed7d95"]={q="卓克苏尔的头颅是从哪里来的？",a="这一可怕的战利品直接取自洛克莫丹东北部荒野中莫格罗什要塞的食人魔卓克苏尔。这不是什么神器或工艺品，而是食人魔督军本人的断头，由为了完成塞尔萨玛镇发布的官方悬赏而来的冒险者所取。",al={"卓克苏尔的头颅来源","卓克苏尔的头颅从哪来","谁制造了卓克苏尔的头颅"}}},fp="15,171,29.434.0,17.190.0,44.204.0,27.97.0,45.137.0"}
P.entries["item:clarice-s-pendant"] = {n="克拉莉斯的坠饰",s="在雷霆崖的预见之池，克拉莉斯·弗斯特留着一件遗物，苦涩地追忆失去的家人。她的坠饰来自前夫尤瑞夫，他对圣光的虔诚让他抛下了克拉莉斯和孩子们。",h="在雷霆崖的预见之池，克拉莉斯·弗斯特留着一件遗物，苦涩地追忆失去的家人。她的坠饰来自前夫尤瑞夫，他对圣光的虔诚让他抛下了克拉莉斯和孩子们。",kw={"克拉莉斯·弗斯特","克拉莉斯的坠饰","被遗忘者","瑟伯切尔","银松森林","坟墓","至死方休","尤瑞夫"},ang={["class:Paladin"]="身为圣骑士，你或许难以听下去，听克拉莉斯蔑视尤瑞夫的征战。他的神圣狂热留下了一个破碎的家。",["race:Undead"]="身为被遗忘者，你或许也懂得这种苦涩：亲人出征，却没能保护任何人。许多被遗忘者都经历过这样的失去。"},sec={{t="苦涩的信物",b="克拉莉斯的坠饰让人想起克拉莉斯·弗斯特成为被遗忘者之前失去的生活。在第三次大战吞噬洛丹伦之前，她的丈夫尤瑞夫抛下她和孩子们，前去对抗亡灵。他相信，对圣光的虔诚高于一切。尤瑞夫死了，他的家人无人庇护，最终落入了他本想抗击的天灾军团手中。克拉莉斯并不珍视他送的坠饰。对她而言，这是一种侮辱，提醒着她：在他的狂热与职责面前，她和孩子们只能屈居其次。"},{t="安放于尤瑞夫之墓",b="克拉莉斯想斩断与往昔生活的最后联系，也斩断与冷落她的丈夫尤瑞夫的最后牵绊。她派一名冒险者将坠饰放到他位于瑟伯切尔的墓上。那座无人照料的坟墓杂草丛生，垃圾遍地，还遭到了破坏。当坠饰被放在棺木上雕刻的双手中时，宝石失去了光泽。克拉莉斯往昔生活中最后的一丝温暖也随之熄灭。"}},faq={{q="克拉莉斯的坠饰属于谁？",a="坠饰的主人是克拉莉斯·弗斯特，一位身处雷霆崖预见之池的被遗忘者女子。这是她生前丈夫尤瑞夫送给她的礼物，那时他尚未奔赴战场。",al={"坠饰属于谁","这是谁的坠饰","克拉莉斯·弗斯特"}},{q="尤瑞夫是谁？",a="尤瑞夫是克拉莉斯生前的丈夫。他以圣光之名，抛下克拉莉斯和孩子们，前去对抗日益壮大的亡灵。他死后葬在瑟伯切尔一座无人照料的坟墓中。",al={"克拉莉斯的丈夫","尤瑞夫是谁","尤瑞夫的墓"}},{q="克拉莉斯为什么想丢掉坠饰？",a="克拉莉斯想摆脱这枚坠饰，因为她怨恨尤瑞夫将他的征战和对圣光的虔诚置于她和孩子们之上。他死了，留下克拉莉斯独自面对厄运，最终被复生成亡灵，而这正是他力图阻止的命运。",al={"为什么丢掉坠饰","克拉莉斯为什么恨尤瑞夫","克拉莉斯的坠饰任务"}},{q="将坠饰放在尤瑞夫的墓上会发生什么？",a="将坠饰放在尤瑞夫的墓上，能让克拉莉斯放下这件信物，以及它承载的痛苦牵绊。",al={"尤瑞夫墓前发生什么","墓上的坠饰"}}},fp="17,170,14.375.0,25.354.1,27.154.0,14.197.0,48.198.0,57.112.1"}
P.entries["item:claw-key"] = {n="利爪钥匙",s="在石爪峰顶的猛禽洞穴中，三把德鲁伊钥匙可以开启受魔法封印的宝藏。",h="在石爪峰顶的猛禽洞穴中，三把德鲁伊钥匙可以开启受魔法封印的宝藏。",kw={"古墓兽穴","利爪钥匙","德鲁伊的藏匣","守门人的钥匙","石爪峰","猛禽洞穴","猛禽洞穴储藏室","大兽穴"},ang={["class:Druid"]="身为德鲁伊，你携带的这把钥匙以标志性的Druids of the Claw命名。它体现了居住在古墓兽穴中的暗夜精灵的神圣传统，以及他们布下的防护结界。",["faction:Horde"]="通过审问被俘的暗夜精灵，部落可以绕过德鲁伊的古老防御，掠夺存放在石爪峰顶的神圣神器。"},sec={{t="猛禽洞穴的结界",b="暗夜精灵德鲁伊在高耸的石爪峰上建造了猛禽洞穴，作为庇护所和存放强大圣物的宝库。他们将宝物藏在重重防护之后。三道魔法锁封住了宝藏，分别需要古墓钥匙、沉睡者的钥匙和利爪钥匙才能打开。每把钥匙都存放在各自的德鲁伊藏匣中，这些藏匣形似火炬，隐藏在古墓兽穴蜿蜒的隧道里。"},{t="开启藏匣",b="德鲁伊派人守护这些钥匙，使其难以落入他人之手。守门人的钥匙就在古墓入口附近，必须用它才能打开存放利爪钥匙的藏匣。要破解德鲁伊的封印，取得深藏于山中的财宝，利爪钥匙至关重要。"}},faq={{q="利爪钥匙有什么用途？",a="利爪钥匙是开启猛禽洞穴储藏室所需的三把钥匙之一，那是一个受结界保护的石箱，位于石爪峰猛禽洞穴的深处。",al={"利爪钥匙用途","利爪钥匙能打开什么","猛禽洞穴储藏室钥匙"}},{q="在哪里可以找到利爪钥匙？",a="利爪钥匙藏在石爪峰猛禽洞穴隧道中的一个德鲁伊藏匣里，藏匣伪装成了火炬。要打开藏匣，需要取得洞穴入口处的守门人的钥匙。",al={"利爪钥匙位置","利爪钥匙在哪里","寻找利爪钥匙"}},{q="除了利爪钥匙，还需要哪些钥匙？",a="开启猛禽洞穴储藏室需要利爪钥匙、古墓钥匙和沉睡者的钥匙，它们分别存放在洞穴各处的不同藏匣中。",al={"其他钥匙","猛禽洞穴钥匙","大兽穴的钥匙"}},{q="德鲁伊为什么要藏起这些钥匙？",a="暗夜精灵德鲁伊建造猛禽洞穴，是为了让强大的圣物远离窥探的目光。他们用钥匙和隐蔽的藏匣阻挡入侵者。",al={"为什么藏起钥匙","猛禽洞穴背景故事"}}},fx={["31018164"]={q="利爪钥匙是什么？",a="利爪钥匙是石爪峰的暗夜精灵德鲁伊所制作的三把附魔钥匙之一。它被锁在地下猛禽洞穴里的一个隐秘藏匿处，是专门用来保护他们最珍贵的财宝免受入侵的安全屏障的重要组成部分。",al={"利爪钥匙是什么","利爪钥匙信息","利爪钥匙是什么类型的钥匙"}},e0ebbe01={q="利爪钥匙是从哪里来的，是谁制作的？",a="这把钥匙是由在石爪峰高处建立猛禽洞穴的德鲁伊们锻造的。为了守护他们的遗物，他们制作了这把钥匙，以及兽穴钥匙和沉睡者钥匙，并将它锁在一个需要使用守门人的钥匙才能打开的密盒中。",al={"谁制作了利爪钥匙","利爪钥匙来源","利爪钥匙从哪来"}},["9663afaa"]={q="为什么有人想要利爪钥匙？",a="人们寻找利爪钥匙是因为需要它来打开猛禽洞穴宝库。德鲁伊们将许多强大的神器锁在洞穴深处，并加上了三把特殊的锁，确保只有集齐了所有三把钥匙的人才能取回宝库中隐藏的遗物。",al={"为什么要找利爪钥匙","为什么要拿利爪钥匙","利爪钥匙的作用背景"}}},fp="8,85,22.361.0,20.235.0,30.142.0,32.164.0,50.142.0,35.133.0"}
P.entries["item:cliffspring-river-sample"] = {n="壁泉河水样",s="在黑海岸，污水汇聚在壁泉河瀑布下。为奥伯丁的桑迪斯·织风采集的这瓶水样表明，腐化正向海岸蔓延。",h="在黑海岸，污水汇聚在壁泉河瀑布下。为奥伯丁的桑迪斯·织风采集的这瓶水样表明，腐化正向海岸蔓延。",kw={"奥伯丁","黑木","壁泉","费伍德森林","水样","桑迪斯","试管","瀑布","织风"},ang={["class:Druid"]="身为德鲁伊，你深知自然水系的平衡至关重要。壁泉水样中非自然的毒素亟须研究和净化。",["race:NightElf"]="对奥伯丁的暗夜精灵而言，卡利姆多北部水域的腐化是一个严峻的征兆，表明费伍德森林的腐化正在蔓延。"},sec={{t="污浊的水流",b="壁泉河发源于黑海岸东部的高地，流经古老的石桥，在薄雾海汇入大海。昔日清澈的河水已变得污浊，显露出腐化的迹象。奥伯丁的暗夜精灵桑迪斯·织风担心，污浊的水流会流抵定居点的海岸，污染水源。他派旅人前往河流下游的瀑布，从瀑布下的水潭中取水。水样证实，一股非自然的腐败正顺流而下，向海岸蔓延。"},{t="费伍德森林的回响",b="黑木熊怪生活在河流上游沿岸，深受日益加剧的黑暗力量侵害。桑迪斯判断，河水中的腐化来自东边悬崖上方的高处，也就是费伍德森林。肆虐山巅的恶魔疫病正渗入黑海岸的各处流域，奥伯丁的守卫必须做好应对准备。"}},faq={{q="在哪里采集壁泉河水样？",a="水样取自奥伯丁以北、壁泉河第一道瀑布下的水潭。沿河向内陆走，就能找到一座桥下方的瀑布。",al={"哪里获取水样","壁泉河位置","瀑布水潭水样"}},{q="桑迪斯·织风为什么需要这些水？",a="桑迪斯担心污浊的河水会污染奥伯丁的近海水域。水样能让他研究这种污染，并制定应对之策。",al={"为什么采集河水","桑迪斯 河流任务","河水样本用途"}},{q="是什么让壁泉河变得污浊？",a="真正的源头在东边的费伍德森林，那里残留的恶魔腐化正渗入山间水源。遭到腐化的黑木熊怪也生活在河流沿岸。",al={"什么毒害了河流","河水为何被腐化","河流腐化源头"}},{q="河水中的毒素是黑木熊怪造成的吗？",a="黑木熊怪加剧了河岸一带的祸患，但并非祸患的根源。他们也受到了从东部遭腐化的土地蔓延而来的大范围腐化的侵害。",al={"是熊怪干的吗","黑木 熊怪腐化","熊怪在给水下毒吗"}}},fx={["2e135e3b"]={q="壁泉河水样是什么？",a="这是一瓶取自壁泉河瀑布底部、用空的水样试管收集的恶臭的受污染河水。它有力地证明了一种邪恶的腐蚀正顺流而下，穿过黑海岸。",al={"壁泉河水样","壁泉河水样是什么"}},["57059c85"]={q="壁泉河水样是从哪里来的？",a="该水样采集自奥伯丁以北，壁泉河第一道瀑布下方的水潭中。虽然是你自己用空的水样试管采集的天然河水，但其不自然的恶臭源于上游从费伍德森林流下的腐化力量。",al={"壁泉河水样从哪来","壁泉河水样来源","谁制作了壁泉河水样"}}},fp="24,173,17.459.0,17.319.1,48.166.0,45.142.0,51.165.0,54.187.0"}
P.entries["item:cloth-request"] = {n="布料订单",s="在运河裁缝店，雷玛·施涅德收到了哈兰·巴格雷补充新布料和针织品的订单。他货架上的存货正迅速减少。",h="在运河裁缝店，雷玛·施涅德收到了哈兰·巴格雷补充新布料和针织品的订单。他货架上的存货正迅速减少。",kw={"运河裁缝店","布料订单","哈兰·巴格雷","雷玛·施涅德","补货","暴风城"},ang={["faction:Alliance"]="暴风城的市民心怀不安，开始为冲突做准备，尽管摄政当局尚未发布任何正式公告。",["profession:Tailoring"]="这份订单涉及暴风城的纺织品贸易。像施涅德这样的街坊制衣商，为杂货店和装备商供应纺织品。"},sec={{t="结实衣物遭抢购",b="哈兰·巴格雷向雷玛·施涅德订购新布料和针织衣物。生意毫无征兆地突然兴隆起来。市民和旅人大量购买护甲与结实的衣物，仿佛严酷的时节即将来临。这股抢购潮让雷玛既困惑又警惕。贵族并未宣布开战，因此她不禁怀疑，城里人为何悄悄武装自己，王室的掌权者是否隐瞒了动乱的消息。"}},faq={{q="布料订单是什么？",a="哈兰·巴格雷的书面订单要求雷玛·施涅德为他的商店供应新布料和针织衣物。",al={"布料订单是什么","布料订单物品","哈兰订货单"}},{q="哈兰·巴格雷为什么需要更多布料？",a="巴格雷的生意近来异常繁忙。市民和旅人大量购买护甲与结实的衣物，几乎买空了他的货架。",al={"哈兰为何需要布料","巴格雷为何缺货","巴格雷补货原因"}},{q="这份订单需要送到哪里？",a="订单要送给雷玛·施涅德，她在暴风城运河沿岸的运河裁缝店。",al={"布料订单送到哪里","布料订单交给谁","布料订单递送"}},{q="暴风城的人们为什么购买这么多护甲和衣物？",a="商人和平民都不清楚确切原因。这股突如其来的抢购潮让雷玛·施涅德感到不安，她怀疑贵族宫廷是否向民众隐瞒了正在酝酿的战事或危险。",al={"人们为何购买护甲","暴风城正在交战吗","雷玛·施涅德的疑虑"}}},fx={b4374b3c={q="布料订单是从哪里来的，是谁写的？",a="这份请求由暴风城的店主哈兰·巴格雷所写。随着市民们购买结实的衣服和护甲，生意突然激增，巴格雷写下这张征购单是为了确保能再获得一批针织服装，并保持货架充盈。",al={"谁写了布料订单","布料订单来源","布料订单从哪来"}}},fp="13,150,21.391.0,26.103.0,39.159.0,35.94.0,62.187.0"}
P.entries["item:cloven-hoof"] = {n="裂开的蹄子",s="在千针石林深处，加拉克半人马守护着裂蹄堡圣火中的裂开的蹄子。牛头人学者试图弄清这件圣物散发的奇异能量。",h="在千针石林深处，加拉克半人马守护着裂蹄堡圣火中的裂开的蹄子。牛头人学者试图弄清这件圣物散发的奇异能量。",kw={"古老的火盆","裂开的蹄子","加拉克","劳恩·峭壁行者","圣火","裂蹄峭壁","裂蹄堡"},ang={["class:Shaman"]="仪式材料可以暂时熄灭魔法火焰，让人得以取出裂开的蹄子。在卡利姆多，从事这类工作需要对灵性力量进行细致的研究。",["race:Tauren"]="世世代代，游牧的牛头人一直忍受着半人马无休止的侵袭。了解裂开的蹄子这类圣物的起源和魔法，或许能让他们更了解这些宿敌。"},sec={{t="半人马的神圣遗物",b="在裂蹄堡腹地，加拉克半人马将裂开的蹄子供奉在一座古老的火盆中。魔法火焰环绕着这件圣物，只有用祝福之水暂时熄灭火焰，才能触碰它。半人马各氏族四分五裂，生性凶暴，但他们对火盆的悉心看护，暗示着一种与自身起源有关的仪式。在乱风岗，劳恩·峭壁行者和其他牛头人观察者希望借助蹄子散发的奇异气息，了解那些长期侵扰卡利姆多平原的半人马。"}},faq={{q="裂开的蹄子存放在哪里？",a="裂开的蹄子存放在裂蹄堡深处的一座古老火盆中，裂蹄堡是乱风岗以北裂蹄峭壁中的一处洞穴。加拉克精英战士守护着它。",al={"裂开的蹄子位置","哪里能找到裂开的蹄子","裂蹄堡圣物"}},{q="劳恩·峭壁行者为什么想要裂开的蹄子？",a="劳恩·峭壁行者想研究裂开的蹄子，以了解半人马的起源和魔法。他感受到了这件圣物散发的奇异能量，希望它能揭示这些敌对氏族隐藏的真相。",al={"为什么要获取裂开的蹄子","劳恩·峭壁行者任务","谁想要裂开的蹄子"}},{q="如何从火盆中取出裂开的蹄子？",a="魔法火焰环绕着裂开的蹄子，因此无法直接拿取。将一瓶特殊的水倒入古老的火盆，暂时熄灭圣火，然后在火焰再次燃起之前取走蹄子。",al={"如何获取裂开的蹄子","熄灭圣火","装满水的蚀刻瓶用途"}},{q="守护它的加拉克半人马是谁？",a="加拉克是一个占据千针石林北部的半人马部族。他们的据点位于裂蹄峭壁，在那里，他们严密守护着圣火，不容外人靠近。",al={"加拉克半人马","裂蹄峭壁半人马","谁守护圣火"}}},fx={b52742f5={q="裂开的蹄子是什么？",a="裂开的蹄子是一件古老而神秘的遗物，受到千针石林加拉克半人马的崇拜。它被封存在裂蹄堡深处的永恒圣火中，散发出一种奇怪的、未被研究过的能量，引起了牛头人研究人员的极大好奇。",al={"裂开的蹄子是什么","裂开的蹄子遗物","蹄子是什么"}}},fp="11,164,22.475.0,30.156.0,46.192.0,50.207.0,38.178.0"}
P.entries["item:comar-s-heart"] = {n="Comar's Heart",s="幽暗城的术士寻找科马的心脏，用它引诱魅魔为自己效力。这颗心脏属于科马·韦拉德，一个在湿地寻找失踪妻子的人类。",h="幽暗城的术士寻找科马的心脏，用它引诱魅魔为自己效力。这颗心脏属于科马·韦拉德，一个在湿地寻找失踪妻子的人类。",kw={"凯伦丁·哈加尔","科马·韦拉德","科马的心脏","纯洁者之心","魅魔","诅咒神殿","幽暗城","湿地"},ang={["class:Warlock"]="身为术士，夺取科马的心脏让你看到，恶魔学如何将凡人的美德化为诱饵，引来你意欲束缚的魅魔。",["race:Undead"]="身为被遗忘者的一员，挖取一个忠于爱情的人类的心脏，展现了洛丹伦的生者与亡灵之间情感的割裂。"},sec={{t="纯洁的明灯",b="科马·韦拉德一直在湿地寻找失踪的妻子。尽管动荡席卷了东部王国，他仍不肯放弃寻找。凯伦丁·哈加尔在幽暗城的弟子认为，他的忠贞极为罕见，也极为纯粹。魅魔反复无常，又生性凶残，术士需要用他这样的挚情作饵，才能将其束缚。科马坚定不移的爱让他成了屠戮的目标，他的心脏则成了引来恶魔仆从的诱饵。"},{t="诱惑的代价",b="被遗忘者学徒必须向南穿过争夺中的土地，跨越萨多尔大桥，进入联盟控制的沼泽，取得科马的心脏。他们将它与达林的心脏一同带回诅咒神殿。这颗心脏看似平凡，但它曾经的主人却始终心怀善意。对虚空而言，科马血肉中残留的美德是令人沉醉的诱饵。它能引来魅魔，使其穿过维度之间的帷幕，受术士奴役。"}},faq={{q="科马·韦拉德是谁？",a="科马·韦拉德是一个痴情的人类，在危机四伏的湿地寻找失踪的妻子。他不肯放弃希望，这份爱也表明他是个心地纯洁的人。",al={"科马是谁","科马·韦拉德背景故事","为何杀死科马"}},{q="术士为什么需要科马的心脏？",a="幽暗城的术士需要科马的心脏来引诱并束缚魅魔。他的挚情使这颗心脏成为恶魔无法抗拒的诱饵。",al={"为何需要科马的心脏","科马的心脏有何用途","魅魔心脏背景故事"}},{q="在哪里能找到科马·韦拉德？",a="科马·韦拉德在湿地北部的大路上徘徊，就在连接阿拉希高地与卡兹莫丹的萨多尔大桥南面。",al={"科马·韦拉德位置","科马在哪里","如何找到科马"}},{q="谁派术士去收集这颗心脏？",a="幽暗城的术士训练师指派学徒去收集这颗心脏。凯伦丁·哈加尔在诅咒神殿指导他们，学徒们在那里学习召唤魅魔。",al={"谁想要科马的心脏","谁发布纯洁者之心","凯伦丁·哈加尔心脏"}}},fx={["7acb4df8"]={q="科马的心脏是什么？",a="科马的心脏是直接从湿地中一位忠诚的人类流浪者科马·韦拉德的遗体中取出的心脏。术士们将其视为一种罕见的纯洁美德标本，浸透着忠诚和永恒的爱。",al={"科马的心脏是什么","科马的心脏物品","科马的心脏背景"}},a49b76cf={q="科马的心脏是从哪里来的？",a="它直接取自科马·韦拉德的胸膛，此人正在湿地险恶的沼泽中寻找他失踪妻子的踪迹。它并非由魔法锻造的神器，而是一个凡人的器官，其纯粹的奉献使它成为一种强效的仪式试剂。",al={"科马的心脏从哪来","谁制作了科马的心脏","科马的心脏来源"}}},fp="13,164,18.409.0,22.439.1,22.156.0,35.155.0,29.133.0,40.183.0"}
P.entries["item:consecrated-rune"] = {n="神圣符文",s="在寒脊山谷的安威玛尔，神圣符文召唤初出茅庐的矮人圣骑士，正式履行白银之手骑士团成员的职责。",h="在寒脊山谷的安威玛尔，神圣符文召唤初出茅庐的矮人圣骑士，正式履行白银之手骑士团成员的职责。",kw={"安威玛尔","布罗莫斯·格鲁诺尔","寒脊山谷","神圣符文","圣光","圣骑士","白银之手"},ang={["class:Paladin"]="身为矮人圣骑士，收到符文意味着你将在布罗莫斯·格鲁诺尔的指引下，正式加入白银之手骑士团。",["race:Dwarf"]="身为矮人，这枚符文向你展现了人类的神圣传统如何通过铁炉堡与人类之间的同盟和相互尊重，融入矮人的尚武文化。"},sec={{t="白银之手的召唤",b="在白银之手骑士团中，神圣符文标志着一名矮人新人的身份。矮人圣骑士在寒脊山谷证明自己掌握了基本武艺后，便会收到一枚符文。符文上刻着神圣的文字，并受到圣光的祝福。\n\n安威玛尔内的圣骑士训练师布罗莫斯·格鲁诺尔将它作为正式的召令送出。矮人十分尊重人类盟友传授给他们的圣光传统。阅读符文，便确认了新人在骑士团中的身份，也标志着服役的开始。"}},faq={{q="神圣符文有什么用途？",a="神圣符文召唤矮人圣骑士新人前往安威玛尔，寻找布罗莫斯·格鲁诺尔，继续接受圣骑士训练。",al={"神圣符文用途","符文有什么用","神圣符文任务物品"}},{q="是谁送来神圣符文的？",a="布罗莫斯·格鲁诺尔从寒脊山谷的安威玛尔送出神圣符文，他在那里训练矮人圣骑士。",al={"谁给了我神圣符文","符文来源","布罗莫斯·格鲁诺尔符文"}},{q="矮人圣骑士为何遵循白银之手的传统？",a="矮人从人类导师那里学到了许多关于圣光的知识和白银之手的行事之道。他们敬重骑士团的历史与传统，也认同其信念：一次牺牲便能改变艾泽拉斯的命运。",al={"矮人圣骑士 白银之手","矮人为何成为圣骑士","矮人与 圣光"}}},fx={dda1df9e={q="神圣符文是什么？",a="这是一块在圣光中加持过的矮人铭文石，作为一份正式的征召令，发送给正在寒脊山谷训练的圣骑士新兵。矮人将符文工艺与圣教结合，使用像这样的石头来传达庄严的信息，并召唤圣光的初学者们前往导师处。",al={"神圣符文是什么","神圣符文物品","神圣符文含义"}},["924bde77"]={q="为什么布罗莫斯·格鲁诺尔想要你拥有神圣符文？",a="布罗莫斯·格鲁诺尔寄出这枚符文是为了测试你的准备情况，并指引你前往安威玛尔进行正式训练。整个丹莫罗正面临麻烦，白银之手骑士团需要有能力、受过纪律训练的勇士，随时准备履行神圣职责，保护艾泽拉斯免受伤害。",al={"为什么要有神圣符文","为什么布罗莫斯想要神圣符文","我为什么要拿神圣符文"}}},fp="16,140,28.522.0,38.129.0,31.111.0,65.197.0"}
P.entries["item:console-key"] = {n="控制台钥匙",s="在贫瘠之地的荆棘谷地精挖掘场，工匠斯尼格斯持有控制台钥匙。这把钥匙能打开主控制终端，并在装置关闭后让人取出主动式负载平衡器。",h="在贫瘠之地的荆棘谷地精挖掘场，工匠斯尼格斯持有控制台钥匙。这把钥匙能打开主控制终端，并在装置关闭后让人取出主动式负载平衡器。",kw={"贫瘠之地","控制台钥匙","控制台","主动式负载平衡器","工匠斯尼格斯","荆棘谷地精"},ang={["faction:Horde"]="从工匠斯尼格斯手中夺取控制台钥匙，有助于破坏荆棘谷地精在贫瘠之地腹地开展的剥削性工业活动。",["profession:Engineering"]="荆棘谷地精使用配有专用钥匙的定制锁具，防止竞争对手窃取samophlange这类精密的工程原型。"},sec={{t="确保装置安全",b="荆棘谷地精在贫瘠之地北部经营着一处工业哨站。那里的蒸汽机械依靠一种名为操作器的装置运转。控制台上了锁，防止未经许可的人操作，只有现场的首席技师工匠斯尼格斯随身携带控制台钥匙。这把钥匙能打开终端外壳，以便切断整套设备的动力。"},{t="关闭设备",b="转动辅助阀门，待装置冷却并停止运转后，控制台钥匙便能切断最后的电路。转动钥匙会耗尽终端剩余的电力，并解锁外壳，让人能从机械中撬出操作器。"}},faq={{q="控制台钥匙能打开什么？",a="控制台钥匙能打开贫瘠之地北部荆棘谷地精设备的主控制台。机械停止运转后，它会耗尽终端的电力，使主动式负载平衡器显露出来。",al={"控制台钥匙有什么用","控制台钥匙能打开什么","控制台钥匙用途"}},{q="谁带着控制台钥匙？",a="工匠斯尼格斯随身携带控制台钥匙。这位荆棘谷地精工程师待在主控制台装置东北面不远处的一间小屋里。",al={"谁掉落控制台钥匙","哪里获得控制台钥匙","工匠斯尼格斯的钥匙"}},{q="控制台为什么要上锁？",a="荆棘谷地精给终端上锁，是为了防止竞争对手和不守规矩的工人干扰机械运转，或拿走主动式负载平衡器这样的贵重零件。",al={"为什么需要钥匙","主动式负载平衡器为什么被锁住"}},{q="关闭阀门之前能使用钥匙吗？",a="关闭阀门，等仪表读数归零后，再使用控制台钥匙。尝试操作仍在运行的控制台，可能引发机械反冲。",al={"先用钥匙","能否直接解锁控制台"}}},fx={["4424a0fd"]={q="控制台钥匙是什么？",a="控制台钥匙是负责管理贫瘠之地控制台的荆棘谷地精技师所持有的一把机械安全钥匙。它能插入包裹着调节器的锁定外壳中，确保只有获得授权的人员才能接触到精密的机械和终端内部结构。",al={"控制台钥匙","控制台钥匙是什么"}},["81c16021"]={q="为什么有人想要控制台钥匙？",a="一旦设备关闭，控制台断电，外壳仍处于锁定状态。你需要控制台钥匙来解锁控制面板本身，这是安全拆卸并从终端取回调节器的最后一步。",al={"为什么要拿控制台钥匙","我为什么需要控制台钥匙","控制台钥匙的作用"}}},fp="11,180,22.320.0,21.240.1,33.189.0,28.132.0,45.158.0,52.128.0"}
P.entries["item:control-console-operating-manual"] = {n="控制台操作手册",s="在淤泥沼泽西南方的荆棘谷地精工地，控制台操作手册指引工人操作机械。手册说明了如何关闭阀门并断开操作器。",h="在淤泥沼泽西南方的荆棘谷地精工地，控制台操作手册指引工人操作机械。手册说明了如何关闭阀门并断开操作器。",kw={"贫瘠之地","控制台","地精工程学","操作手册","主动式负载平衡器","淤泥沼泽","荆棘谷地精"},ang={["faction:Horde"]="这本手册让部落调查人员得以窥见荆棘谷地精遍布贫瘠之地北部的侵扰性工业活动。",["profession:Engineering"]="这本手册展现了地精的工程思路：系统承受着极高的压力，安全性勉强过关，靠一堆杂乱的操纵杆和阀门运转，而非均衡的故障保护机制。"},sec={{t="解读地精机械",b="在淤泥沼泽西南方，荆棘谷地精经营着一处位于贫瘠之地北部的钻探与研究基地。这里的机械将仪表、加压阀门和各种机构连接到一台名为操作器的装置上。没有正确的操作说明，摆弄这些不稳定的控制装置可能引发危险的故障，或使系统锁死。手册给出了断开核心装置所需的阀门操作顺序，以免故障引发爆炸。"}},faq={{q="控制台操作手册有什么用途？",a="控制台操作手册说明了如何操作淤泥沼泽西南方的荆棘谷地精控制台。它指引你关闭阀门，以便断开主动式负载平衡器。",al={"手册有什么作用","手册用途","为什么有操作手册"}},{q="主动式负载平衡器是什么？",a="即使是荆棘谷地精以外的研究人员，也不完全清楚什么什么平衡器的作用。它似乎是一种由地精设计的核心机构，与贫瘠之地的钻探和工业作业有关。",al={"主动式负载平衡器有什么作用","主动式负载平衡器背景故事","这是什么机器"}},{q="这本手册是谁编写的？",a="负责管理研究哨站的荆棘谷地精技术人员编写了这本手册。它旨在帮助工人操作控制台，并让各个控制阀门的压力保持在预定水平。",al={"谁编写了手册","手册作者"}},{q="如果我丢失了手册，会怎么样？",a="控制台上有显示阀门压力的仪表和读数。即使手边没有手册，熟练的冒险者也能看懂面板并操作开关。",al={"手册丢失","操作手册已删除"}}},fx={["4b9f7b43"]={q="控制台操作手册是什么？",a="这是从荆棘谷地精那里回收的一本操作指南，详细介绍了淤泥沼泽西南方研究设施中控制台的操作方法。它概述了他们的机械运作方式，以便技术人员可以安全地操纵其阀门并拆卸设备。",al={"控制台操作手册是什么","控制台操作手册","荆棘谷地精手册"}},["5e9de40e"]={q="为什么要寻找控制台操作手册？",a="手册提供了关闭并拆卸荆棘谷地精神秘调节器所需的具体操作步骤。如果不解读其说明，盲目摆弄控制台上那些不稳定的操纵杆、按钮和加压控制阀几乎是不可能的。",al={"为什么要找控制台操作手册","为什么需要手册","手册有什么用"}}},fp="32,191,28.383.0,54.172.0,22.193.0,22.180.0,34.143.0"}
P.entries["item:corroded-shrapnel"] = {n="被腐蚀的弹片",s="在石爪山脉，锯齿状的金属碎片深深嵌在腐化树人的体内。荆棘谷地精撤退时使用的弹药在森林守护者体内留下了碎片，如今有人正收集这些碎片进行研究。",h="在石爪山脉，锯齿状的金属碎片深深嵌在腐化树人的体内。荆棘谷地精撤退时使用的弹药在森林守护者体内留下了碎片，如今有人正收集这些碎片进行研究。",kw={"烧焦的古树","被腐蚀的弹片","加克希姆","凯拉·影矛","石爪山脉","树人","荆棘谷地精"},ang={["class:Druid"]="身为德鲁伊，看到卡利姆多的古树被地精弹药和令伤口溃烂的金属碎片扭曲，你便能明白，无节制的掠夺会让荒野付出怎样的代价。",["race:Gnome"]="身为侏儒，你可以将加克希姆对受污染弹片的研究视为一种务实的科学方法，用来探究林地哨兵无法解释的生态谜团。"},sec={{t="工业破坏的残片",b="荆棘谷地精被逐出石爪山脉的林地时，那些地精肆无忌惮地使用弹药掩护逃亡。爆炸产生的弹片撕裂了保卫山谷的树人的身躯，深深嵌入树皮与树心。这些古老的守护者逐渐被腐化吞噬。它们的躯干变得焦黑，怒火转而指向所有进入山谷的人。凯拉·影矛正在寻找这些锈蚀的碎片，好让侏儒加克希姆·尘链研究这些武器是如何使树人腐化的。"}},faq={{q="这些弹片从哪里来？",a="这些弹片来自石爪山脉的腐化树人，包括烧焦的古树、熏黑的古树和复仇的古树。",al={"哪里能找到弹片","被腐蚀的弹片掉落","谁掉落弹片"}},{q="为什么弹片会嵌在树人体内？",a="森林守护者将地精伐木工逐出山谷时，荆棘谷地精的爆炸弹药击中了树人。碎片在战斗中嵌入它们的树皮，一直残留至今。",al={"弹片怎么进入树人体内","树人体内为什么全是金属"}},{q="是这些弹片导致森林古树腐化的吗？",a="凯拉·影矛说，侏儒加克希姆认为，树人的腐化与撤退的地精所用武器中有害的化学成分或金属成分有关。",al={"弹片使树人腐化了吗","树人为什么发狂"}},{q="谁想检查这些弹片？",a="暗夜精灵凯拉·影矛想取得一份样本，交给侏儒发明家加克希姆，他打算研究弹片的性质，查明树人遭受了什么侵害。",al={"谁需要弹片","弹片交给谁"}}},fx={["1f081bfa"]={q="被腐蚀的弹片是什么？",a="被腐蚀的弹片是由地精武器留下的锯齿状金属碎片。这些退化、生锈的爆炸性弹药碎片深深嵌入石爪山脉树人的树皮中，被认为带有挥之不去的毒素或邪恶的腐蚀，折磨着森林的守护者。",al={"被腐蚀的弹片是什么","被腐蚀的弹片背景","被腐蚀的弹片物品"}}},fp="17,153,27.478.0,35.141.0,44.188.0,63.166.0,34.145.0"}
P.entries["item:corrupt-manifestation-s-bracers"] = {n="堕落水之魂的护腕",s="受污染的护腕散落在银松森林的海岸上，是一个腐化水元素的遗留之物。萨满祭司学徒在水之召唤中取回护腕，将其与纯净之水一同投入圣泉火盆，净化祭坛并召唤纯净的水之灵。",h="受污染的护腕散落在银松森林的海岸上，是一个腐化水元素的遗留之物。萨满祭司学徒在水之召唤中取回护腕，将其与纯净之水一同投入圣泉火盆，净化祭坛并召唤纯净的水之灵。",kw={"圣泉火盆","水之召唤","堕落水之魂的护腕","萨满祭司任务","银松森林","水元素"},ang={["class:Shaman"]="身为萨满祭司，取回并净化这些护腕是你在水之召唤中的最终试炼。这证明你有能力安抚并复原遭到扭曲的元素。"},sec={{t="净化的祭品",b="天灾军团 的瘟疫侵染了洛丹伦的灵体。在瑟伯切尔以西、银松森林雾气笼罩的海岸上，一座神圣的水之祭坛遭到了腐化。祭坛的水元素化身变成了凶暴的幽影。萨满祭司学徒必须击败它，取回它的护腕。在圣泉火盆，他们将护腕与纯净之水一同投入火焰，驱除腐化，唤出一个纯洁无瑕的水之灵。"}},faq={{q="这些护腕有什么用途？",a="在净化仪式中，护腕会与纯净之水一同投入圣泉火盆。仪式会清除银松森林祭坛的腐化，并唤出一个纯净的水之灵。",al={"护腕的作用","水之召唤 护腕","腐化护腕用途"}},{q="这些护腕从何而来？",a="护腕来自 堕落的水之魂，它位于瑟伯切尔以西、银松森林海岸上一座受污染的元素祭坛附近。",al={"护腕获取地点","腐化化身位置"}},{q="水元素为何会被腐化？",a="肆虐洛丹伦的瘟疫与黑暗力量扭曲了这个元素，并切断了当地灵体与萨满祭司的沟通。",al={"水受污染的原因","银松森林水体腐化"}}},fx={["0d8aeb2f"]={q="堕落水之魂的护腕是什么？",a="这些护腕是与在银松森林受污染海岸线上发现的一种被腐化的水之魂绑定的物理残留物。像许多与凡世位面相连的元素生物一样，水之魂佩戴着护腕来锚定和塑造其液态形态。即使在生物被消灭后，护腕仍保留着元素生物受腐化存在的精神残留，使其成为仪式净化的重要催化剂。",al={"堕落水之魂的护腕是什么","堕落水之魂的护腕","这些护腕是什么"}}},fp="31,260,20.436.0,32.179.0,31.147.0,43.130.0"}
P.entries["item:corrupted-brain-stem"] = {n="堕落者的脑干",s="在黑暗深渊和灰谷沿岸，堕落者的脑干标本取自扭曲的纳迦和萨特。奥伯丁的戈沙拉·夜语研究滥用魔法造成的畸变。暗夜精灵学者希望研究结果能帮助血精灵避免遭受同样的命运。",h="在黑暗深渊和灰谷沿岸，堕落者的脑干标本取自扭曲的纳迦和萨特。奥伯丁的戈沙拉·夜语研究滥用魔法造成的畸变。暗夜精灵学者希望研究结果能帮助血精灵避免遭受同样的命运。",kw={"灰谷","奥伯丁","黑暗深渊","堕落者的脑干","戈沙拉·夜语","纳迦","研究堕落","萨特"},ang={["faction:Alliance"]="作为灰谷的一名联盟斥候，你勇闯黑暗深渊深处，帮助奥伯丁的学者了解艾泽拉斯各地日益加剧的威胁。",["race:NightElf"]="对暗夜精灵而言，这些遗骸让他们想起族人的悲惨历史，以及肆意染指奥术和邪能所造成的可怕后果。"},sec={{t="蜕变的解剖研究",b="纳迦和萨特身上留有禁忌魔法和恶魔契约的印记。很久以前，肆意妄为的卡多雷上层精灵变成了蛇形水生怪物和长角的恶魔。他们的脑干发生了严重的生理变异，证明腐化能量深深改变了这些昔日精灵的神经系统。"},{t="戈沙拉的警告",b="戈沙拉·夜语在奥伯丁关注着有关东部王国血精灵的令人不安的传闻。他担心他们使用恶魔巫术会在艾泽拉斯催生新一代怪物，因此派冒险者深入黑暗深渊。他希望通过检查纳迦和萨特的组织，追查魔法引发的退化过程，以免又一个精灵文明消亡。"}},faq={{q="哪些生物会掉落堕落者的脑干？",a="黑暗深渊和灰谷沿岸的纳迦与萨特都会掉落，包括黑暗深渊先知、海巫和腐根萨特。",al={"谁掉落脑干","堕落者的脑干掉落","哪里获取脑干"}},{q="谁需要这些脑干，为什么？",a="奥伯丁的戈沙拉·夜语需要这些脑干，用于研究魔法腐化的解剖学影响。",al={"谁需要堕落者的脑干","戈沙拉任务","交还脑干"}},{q="暗夜精灵希望从这些标本中了解什么？",a="暗夜精灵希望了解恶魔能量如何改变精灵的生理结构。戈沙拉担心血精灵会变成怪物，就像古代的上层精灵变成纳迦和萨特一样。",al={"为何研究纳迦和萨特","研究堕落背景故事","与血精灵的关联"}},{q="在黑暗深渊洞穴之外也能找到这些脑干吗？",a="能。灰谷沿岸洞穴入口外的一些腐根萨特和黑暗深渊潮汐女祭司也携带这些脑干。",al={"黑暗深渊外","灰谷脑干","地表怪物是否掉落脑干"}}},fx={["3ff1da04"]={q="堕落者的脑干是什么？",a="堕落者的脑干是一种解剖学标本，从居住在黑暗深渊内及周边的萨特和娜迦身上采集而来。这两个种族曾经都是暗夜精灵，但其身体和思想被恶魔契约或古老而阴暗的深渊暴力地扭曲了。这些脑干带有这种魔法变形的生理特征，使它们成为研究黑暗魔法如何扭曲凡人血肉的学者的宝贵解剖研究对象。",al={"堕落者的脑干是什么","堕落者的脑干物品","堕落者的脑干背景"}},["53f0c38a"]={q="堕落者的脑干是从哪里来的？",a="这些脑干取自栖息在灰谷海岸黑暗深渊附近地下洞穴和遗迹中的邪枝萨特和黑暗深渊娜迦。它们并不是制造出来的物品，而是被腐蚀、邪能和黑暗转化扭曲了数千年的生物残骸。",al={"堕落者的脑干来源","谁掉落堕落者的脑干","堕落者的脑干出处"}}},fp="20,272,25.297.0,18.354.0,44.165.0,36.99.0,58.168.0,60.126.0"}
P.entries["item:corrupted-kor-gem"] = {n="被污染的科尔宝石",s="在黑暗深渊周围，娜迦的仪式污染了科尔宝石。施法者珍视这些能储存奥术能量的宝石，但若要将宝石用于神圣的锻造，就必须先净化其中的污秽。",h="在黑暗深渊周围，娜迦的仪式污染了科尔宝石。施法者珍视这些能储存奥术能量的宝石，但若要将宝石用于神圣的锻造，就必须先净化其中的污秽。",kw={"黑暗深渊","被污染的科尔宝石","科尔宝石","娜迦","净化","桑迪斯·织风","潮汐女祭司"},ang={["class:Paladin"]="身为圣骑士，你必须找回并净化一颗科尔宝石，用它锻造神圣的武器，证明自己能够直面邪恶，净化黑暗，将其化为正义的力量。",["race:NightElf"]="身为暗夜精灵，你深知娜迦遗物给黑海岸带来的危险。桑迪斯·织风这样的学者保存着净化这些古老宝石所需的知识。"},sec={{t="污秽力量的容器",b="科尔宝石能吸收并储存大量魔力，因此备受巫师和附魔铁匠珍视。在黑暗深渊的废墟附近，娜迦先知和潮汐女祭司夺取这些宝石，用于她们的黑暗仪式。她们邪恶的法术让每颗宝石都遭到来自海洋的腐化。这种污染并未耗尽宝石潜藏的力量，因此，需要强大法器的人仍会到娜迦之中寻找宝石。"},{t="净化与锻造",b="桑迪斯·织风要求先净化被污染的科尔宝石，才能将其交给乔丹·斯迪威尔。这位身在奥伯丁的暗夜精灵会清除娜迦的邪恶魔法，并向圣骑士保证，宝石的力量依然完好，足以用于铁匠的仪式。"}},faq={{q="科尔宝石有什么用途？",a="科尔宝石能为施法者储存奥术能量，技艺精湛的铁匠也能将其镶嵌在附魔武器中，用来引导魔法。",al={"科尔宝石是什么","科尔宝石用途","科尔宝石背景故事"}},{q="在哪里能找到被污染的科尔宝石？",a="在灰谷与黑海岸交界处，黑暗深渊的古老废墟内外都有娜迦施法者携带被污染的科尔宝石。黑暗深渊潮汐女祭司和黑暗深渊先知身上都带着这些宝石。",al={"哪里能找到被污染的科尔宝石","科尔宝石位置","谁掉落科尔宝石"}},{q="为什么必须净化宝石？",a="娜迦的仪式让宝石充满了邪恶魔法。在将宝石用于锻造武器之前，必须由桑迪斯·织风这样的自然或圣光大师清除其中的邪恶。",al={"净化科尔宝石","为什么净化科尔宝石","宝石是否邪恶"}},{q="净化宝石后，它的力量还会保留吗？",a="会。桑迪斯·织风向圣骑士保证，净化会完整保留宝石的力量，足以用于乔丹·斯迪威尔的仪式。",al={"净化会损坏宝石吗","净化后是否变弱"}}},fx={["114a4618"]={q="什么是被污染的科尔宝石？",a="被污染的科尔宝石是一种原本用于储存原始奥术或施法能量的魔法容器，但被黑暗魔法扭曲了。娜迦施法者将她们自己邪恶的力量注入了这块石头，将原本中立的导管变成了充满恶意的被玷污的圣物。",al={"什么是被污染的科尔宝石","被污染的科尔宝石信息","介绍被污染的科尔宝石"}},["1218ae71"]={q="被污染的科尔宝石是从哪里来的，它是谁制造的？",a="虽然科尔宝石最初是为施法者储存魔法能量而制作的导管，但这些被污染的版本是由居住在灰谷西北部黑暗深渊周围的娜迦持有并改造的。娜迦女祭司和神谕者用她们自己污秽的魔法使这些宝石饱和，将其变成了黑暗仪式的工具。",al={"谁制造了被污染的科尔宝石","被污染的科尔宝石出处","科尔宝石来源"}},["1d7ce70e"]={q="为什么会有人想要被污染的科尔宝石？",a="圣骑士们在铁匠乔丹·斯迪威尔的要求下寻找这种宝石，以帮助锻造一把正义的武器，尽管它必须首先由桑德里斯·风织者净化掉其中的邪恶魔法。它储存魔法能量的能力使其在适当净化后对于仪式制作非常有价值。",al={"为什么要获取被污染的科尔宝石","谁需要被污染的科尔宝石","为什么需要科尔宝石"}}},fp="17,173,24.365.0,25.250.1,27.119.0,35.213.0,29.158.0,42.119.0"}
P.entries["item:cougar-claws"] = {n="平原狮的爪子",s="在莫高雷中部的平原上，牛头人猎手收集平原狮的爪子，用于净化仪式。这些爪子取自平原狮，它们是草原上的顶级猎食者之一。",h="在莫高雷中部的平原上，牛头人猎手收集平原狮的爪子，用于净化仪式。这些爪子取自平原狮，它们是草原上的顶级猎食者之一。",kw={"净化图腾","平原狮的爪子","平原狮","莫高雷","穆尔·雷角","雷角图腾"},ang={["class:Shaman"]="身为萨满祭司，你知道本土猎食者的精华仍与平原之灵相连。它可以作为媒介，用于净化结界与净化图腾。",["race:Tauren"]="收集平原狮的爪子让年轻牛头人懂得，狩猎是为了维持平衡，满足灵性需求。这与地精产业造成的污染形成了对照。"},sec={{t="自然平衡的载体",b="平原狮是莫高雷草原上的顶级猎食者之一，凭本能潜行猎食。对牛头人而言，取下它们的爪子既非随意杀戮，也非为了炫耀战利品，而是为了收集野兽的自然之灵。当地精的作业污染了平原上祖辈相传的水源时，穆尔·雷角请年轻猎手收集平原狮的爪子和草原捕食者的爪子。牛头人相信，可以将本土野兽纯粹的捕猎本能融入仪式图腾。他们打算用它清除遭到污染的雷角水井中非自然的毒素与邪恶法术。"}},faq={{q="平原狮的爪子有什么用途？",a="穆尔·雷角用平原狮的爪子和草原捕食者的爪子制作雷角之井净化图腾。牛头人将本土猎食者的灵魂融入仪式器物，以净化被地精工业污染的水井。",al={"平原狮的爪子用途","为什么收集平原狮的爪子","平原狮的爪子作用"}},{q="平原狮的爪子从何而来？",a="平原狮在莫高雷的草海平原上游荡，尤其常见于血蹄村的东西两侧，平原狮的爪子便取自它们。",al={"哪里获取平原狮的爪子","平原狮的爪子来源","谁掉落平原狮的爪子"}},{q="穆尔·雷角为什么需要猎食者的爪子来净化水井？",a="牛头人的萨满与德鲁伊传统尊崇野兽捕猎时的纯粹本性。本土猎食者与大地保持着平衡，而地精却掠夺并污染大地，因此这些野兽的精华能够对抗人为的污染。",al={"为什么用猎食者的爪子","穆尔·雷角需要爪子的原因","图腾与猎食者的爪子"}},{q="平原狮的爪子还有其他用途吗？",a="除了制作净化雷角水井所需的仪式图腾，平原狮的爪子没有其他特殊用途。它们通常会被卖给当地商人。",al={"平原狮的爪子其他用途","出售平原狮的爪子"}}},fx={ad1b83a1={q="什么是平原狮的爪子？",a="这些是从潜伏在莫高雷平原的平原狮爪子上取下的天然利爪。牛头人萨满并不将其视为仅仅是战利品，而是将其看作自然狩猎的象征，体现了潜行于荒野中的野兽那纯净且未受玷污的平衡。",al={"什么是平原狮的爪子","平原狮的爪子物品背景","这些爪子是什么"}}},fp="12,169,27.517.0,31.208.0,32.131.0,64.221.0,42.144.0"}
P.entries["item:courser-eye"] = {n="巨角鹿的眼球",s="巨角鹿漫游在石爪山脉的高地，人们采集巨角鹿的眼球，供一位巨魔巫医配制药剂。玛拉卡金的巫医金吉尔需要大量眼球，用来调制一种他称为森林魔法的药剂。",h="巨角鹿漫游在石爪山脉的高地，人们采集巨角鹿的眼球，供一位巨魔巫医配制药剂。玛拉卡金的巫医金吉尔需要大量眼球，用来调制一种他称为森林魔法的药剂。",kw={"长角鹿","巨角鹿的眼球","森林魔法","巨角鹿","金吉尔","玛拉卡金","石爪山脉"},ang={["race:NightElf"]="身为暗夜精灵，你或许会认为，杀死巨角鹿，让巫医用它们对被俘的暗夜精灵进行残酷实验，是对你所怀有的自然敬畏之心的冒犯。",["race:Troll"]="身为巨魔，你知道金吉尔粗陋地利用动物身体部位对付部落敌人的做法，体现了巨魔炼金术和魔精技艺中更阴暗、务实的一面。"},sec={{t="巨魔的药剂",b="巫医金吉尔在玛拉卡金调制部族药剂，对付争夺这片地区的暗夜精灵。鹿眼在巫毒和民间炼金术中很常见，但金吉尔一次就要三十颗巨角鹿的眼球，远远超过普通施法所需的数量。他将眼球与精龙的鳞片、树液和猫科动物的胡须混合。这种药剂是为关在他巢穴后方笼子里的暗夜精灵俘虏准备的。"}},faq={{q="哪里能找到巨角鹿的眼球？",a="巨角鹿的眼球来自石爪山脉高处的巨角鹿和大型巨角鹿，尤其是暗色湖和石爪峰附近。",al={"巨角鹿的眼球位置","哪里获取巨角鹿的眼球","如何获取巨角鹿的眼球"}},{q="巫医金吉尔为什么需要这么多眼球？",a="金吉尔说，要调出像样的药剂，眼球再多也不嫌多。他将眼球与当地动物的身体部位混合，调制他称为森林魔法的药剂。",al={"为什么要三十颗眼球","金吉尔为什么需要眼球","金吉尔用巨角鹿的眼球做什么"}},{q="金吉尔完成森林魔法药剂后会发生什么？",a="金吉尔打算把森林魔法药剂用在关在他洞穴笼子里的暗夜精灵俘虏身上。等他进行实验时，这些俘虏的下场就会揭晓。",al={"金吉尔森林魔法结果","玛拉卡金的俘虏会怎样"}}},fx={["5cdf5ac9"]={q="什么是巨角鹿的眼球？",a="巨角鹿的眼球是一种从漫步在石爪山脉的本地鹿类生物——巨角鹿身上采集的炼金试剂。对于大多数林地居民来说，它们仅仅是当地野生动物的一部分，但在狡猾的从业者手中，这些众多的眼球可以作为强力药剂的原材料。",al={"什么是巨角鹿的眼球","巨角鹿的眼球物品","什么是巨角鹿的眼球（复数）"}},a4aa468a={q="巨角鹿的眼球是从哪里来的？",a="这些眼球直接从漫步在石爪山脉（特别是在暗色湖周围和石爪峰附近）的长角巨角鹿和大型巨角鹿身上采集。它们是取自山中野生动物的天然部分，而不是制作或附魔的工艺品。",al={"巨角鹿的眼球来源","谁制作了巨角鹿的眼球","巨角鹿的眼球出处"}}},fp="11,152,20.401.1,29.153.0,48.149.1,60.157.1"}
P.entries["item:covert-ops-pack"] = {n="隐秘行动工具包",s="在石爪山，隐秘行动工具包为联盟特工提供装备，用于破坏荆棘谷地精的设施并窃取其计划。包内的炸药和示意图针对的是荆棘谷地精在狂风峭壁的作业。",h="在石爪山，隐秘行动工具包为联盟特工提供装备，用于破坏荆棘谷地精的设施并窃取其计划。包内的炸药和示意图针对的是荆棘谷地精在狂风峭壁的作业。",kw={"隐秘行动工具包","峭壁湖","ng-5炸药","第一方案","二号计划","荆棘谷地精","狂风峭壁"},ang={["faction:Alliance"]="身为联盟的一员，你支持Sentinels在石爪山脉抵抗商业掠夺的斗争。",["profession:Engineering"]="对工程师而言，这个工具包将侏儒的巧思化作对抗地精工业的手段。包内特制的NG-5炸药有助于揭开荆棘谷地精机械的运作原理。"},sec={{t="精心策划的破坏",b="隐秘行动工具包装有炸药和行动计划，用于突袭荆棘谷地精的领地。红色和蓝色的NG-5炸药配有遥控起爆器，一号计划和二号计划则为特工提供行动指示。这些炸药用于破坏峭壁湖的伐木场和东部的矿洞。当地精们忙着灭火、检查损坏的机械时，潜入者便能趁乱窃取文件和示意图。"},{t="共同的利益",b="这个工具包同时为石爪山的暗夜精灵哨兵和联盟工程师服务。爆破和盗取行动阻碍了对神圣山坡的滥伐与挖掘。窃取的荆棘谷地精工程图纸也有助于了解地精的重型机械。这些图纸揭示了机械容易出故障的部位，也为联盟工程师改进自身设计提供了思路。"}},faq={{q="隐秘行动工具包里有什么？",a="隐秘行动工具包内有红色和蓝色的NG-5炸药及配套的遥控起爆器，还有一号计划和二号计划的书面指示。",al={"隐秘行动工具包内容","工具包里有什么","隐秘行动工具包内的物品"}},{q="这些炸药有什么战术用途？",a="这些炸药在荆棘谷地精的作业场地制造巨响，分散注意力。守卫被引开后，特工便能悄然潜入伐木场和矿洞。",al={"为什么使用炸弹","ng-5炸药的用途","阿尔法 贝塔爆破"}},{q="这次行动要获取什么情报？",a="这次行动要先从峭壁湖南面的伐木场窃取荆棘谷地精的工程图纸，再从峭壁东端的狂风矿洞获取管理层的信件。",al={"要窃取什么","工具包任务目标","隐秘行动目标"}},{q="利用这个工具包取得的资料对谁有益？",a="暗夜精灵哨兵和联盟工程师都能从中受益。破坏行动阻碍了森林砍伐，工程师则研究示意图，寻找荆棘谷地精伐木机的弱点，并借鉴其中的思路来改进自己的技术。",al={"谁想要荆棘谷地精的图纸","工具包供谁使用","哨兵隐秘行动"}}},fx={["8d787d42"]={q="什么是隐秘行动工具包？",a="隐秘行动工具包是为在狂风峭壁的渗透行动而准备的专业破坏工具包。它包含彩色编码的NG-5爆炸物、配套的远程引爆器和详细的任务计划，旨在制造定时的干扰，以便在荆棘谷地精眼皮底下窃取重要的文件。",al={"什么是隐秘行动工具包","隐秘行动工具包信息","隐秘行动套件"}},["23fc442d"]={q="隐秘行动工具包是从哪里来的，它是谁制造的？",a="该工具包由一名协助石爪山脉暗夜精灵哨兵的联盟技师组装。结合了精密工程与战术爆破，他们特意制作了不稳定的NG-5炸药和远程触发器，以协助针对荆棘谷地精设施的行动打击。",al={"谁制作了隐秘行动工具包","隐秘行动工具包来源","隐秘行动工具包创造者"}},ca775219={q="为什么需要隐秘行动工具包？",a="直接突袭荆棘谷地精的防御工事（如他们的伐木场和矿井）无异于自杀，或者会在获取重要情报之前惊动守卫。该工具包提供了在别处安放远程爆炸物并引发可控混乱的工具，从而将防守者引开，让你能溜进去找回他们的工程计划和通信文件。",al={"为什么要隐秘行动工具包","为什么需要隐秘行动工具包","隐秘行动工具包用途"}}},fp="15,189,18.402.0,25.372.0,35.149.0,47.156.0,45.173.0,58.214.0"}
P.entries["item:crate-of-crash-helmets"] = {n="一箱防撞头盔",s="一批沉重的矮人蒸汽坦克头盔补给，即将运往千针石林的闪光平原。铜栓兄弟急需这些坚固的头盔，保护试车手免受实验型火箭车造成的脑震荡。",h="一批沉重的矮人蒸汽坦克头盔补给，即将运往千针石林的闪光平原。铜栓兄弟急需这些坚固的头盔，保护试车手免受实验型火箭车造成的脑震荡。",kw={"一箱防撞头盔","沙漠赛道","火箭车","闪光平原","蒸汽坦克","千针石林","维兹尔·铜栓"},ang={["profession:Engineering"]="任何工程师都明白，最大推进力与灾难性故障之间只有微妙的平衡，而当安全措施被抛在脑后时，厚重的护甲就绝不可少。",["race:Gnome"]="对沙漠赛道的侏儒来说，要在盐碱平原上以创新胜过地精对手，试车手遭受脑震荡不过是必付的代价。"},sec={{t="高速行驶的安全保障",b="在闪光平原白得刺眼的辽阔荒野上，侏儒工程师不断试探机械推进的极限。可惜，对试车手来说，铜栓兄弟设计的实验型火箭车速度太快，转向系统根本无法可靠应对。车手们经常遭遇猛烈撞车，头部受伤，普通皮帽已不足以保护他们。为了不让这些自愿冒险的勇士一个个消失，重型矮人蒸汽坦克头盔被装箱运过大海，好让车手保持清醒，也保住性命。"}},faq={{q="一箱防撞头盔里装着什么？",a="箱子里装着从矮人军用储备中调来的重型蒸汽坦克头盔。这些头盔能够抵御爆炸冲击和猛烈的车辆碰撞，为高速试车提供所能找到的最厚实的头部防护。",al={"箱内物品","这些是什么头盔","防撞头盔类型"}},{q="谁需要这些头盔？",a="这些头盔将送到闪光平原的沙漠赛道，交给维兹尔·铜栓和他的兄弟。他们设计的车辆过于冒险，一再把试车手撞得昏迷，因此急需坚固的头部防护装备。",al={"谁接收头盔","箱子是给谁的","头盔目的地"}},{q="铜栓兄弟为什么总是撞车？",a="侏儒设计车辆时，更看重极致的速度和突破技术极限，而非稳定的操控。这对兄弟造出了一辆速度惊人的火箭车，但速度实在太快，在盐碱平原上几乎难免发生碰撞。",al={"为什么撞车","火箭车问题","侏儒赛车撞车"}},{q="这些头盔要送往哪里？",a="这批货物必须送往闪光平原，那片辽阔的盐碱平原位于卡利姆多的千针石林东南部。",al={"交货地点","维兹尔在哪里","这些送到哪里"}}},fx={["94078cd5"]={q="一箱防撞头盔是从哪里来的，它是谁制造的？",a="该箱子由丹莫罗的矮人工程师飞行员比罗·长须装箱并提供。长须收集了一批坚固的矮人攻城坦克头盔，以帮助他的老朋友——黄铜螺栓兄弟，他们急需为在闪光平原测试的飞行员提供头部保护。",al={"谁制作了一箱防撞头盔","一箱防撞头盔来源","防撞头盔出处"}}},fp="22,209,21.345.0,42.177.0,24.189.0,49.212.0,38.109.0"}
P.entries["item:crate-of-horseshoes"] = {n="一箱马掌",s="在艾尔文森林，一箱马掌装着五十只铁马掌，正运往湖畔镇。",h="在艾尔文森林，一箱马掌装着五十只铁马掌，正运往湖畔镇。",kw={"一箱马掌","艾尔文森林","闪金镇","湖畔镇","赤脊山","铁匠阿古斯","弗纳·奥斯古"},ang={["faction:Alliance"]="尽管暴风城迟迟不派兵增援，往返于艾尔文森林和赤脊山之间的信使仍在运送货物，维系着王国脆弱的商路，为边远驻军供应装备。",["profession:Blacksmithing"]="这批货物表明，边疆城镇之间的道路沿线，对基本锻造制品一直有着需求。湖畔镇依靠闪金镇的铁砧，让当地的役畜继续劳作。"},sec={{t="送往湖畔镇的货物",b="铁匠阿古斯在闪金镇新打了五十只马掌，装进木箱，再用钉子封好。弗纳·奥斯古为湖畔镇订购了这些马掌，那里受到豺狼人和兽人的威胁，当地工匠只能依靠艾尔文森林供应必需的金属制品。这批货物满足了弗纳·奥斯古对装备的迫切需求，而铁匠阿古斯还附上了一张措辞严厉的账单，让这位赤脊山的工匠明白，要在边疆生存，就得付出高昂的代价。"}},faq={{q="一箱马掌里装着什么？",a="铁匠阿古斯在闪金镇打造了五十只铁马掌，并将它们装进箱子。随箱附上的账单要求买家付款。",al={"箱中物品","箱子里有什么","马掌箱里的物品"}},{q="这箱货物是谁订购的？",a="弗纳·奥斯古订制了这些马掌。他是赤脊山湖畔镇的一名商人兼工匠，需要这些马掌来维持自己的工作，让当地的役畜继续劳作。",al={"谁需要马掌","弗纳·奥斯古的马掌","箱子的收货人"}},{q="这些马掌是谁打造的？",a="铁匠阿古斯是艾尔文森林闪金镇的铁匠，他打造了这些马掌，将它们装箱，做好了送货的准备。",al={"谁打造了马掌","闪金镇的铁匠","铁匠阿古斯"}},{q="弗纳·奥斯古为什么需要艾尔文森林的马掌？",a="敌对的黑石兽人和豺狼人围困着湖畔镇，让这座边疆城镇陷入孤立，原材料和贸易物资都十分短缺。当地工匠必须从闪金镇等较为安全的城镇运来基本物资。",al={"赤脊山为何需要马掌","为何从外地运来马掌","湖畔镇的补给问题"}}},fx={["50a21bee"]={q="什么是一箱马掌？",a="一箱马掌是一个沉重的木制运输箱，里面装着五十个新锻造的马掌，并附有一张发货单。铁匠阿古斯在闪金镇准备了这批货物，以完成弗纳·奥斯古下的订单，他急需新鲜的铁器来给附近的湖畔镇的驮兽和坐骑钉马掌。",al={"什么是一箱马掌","一箱马掌背景","马掌的用途"}}},fp="19,73,23.425.0,39.132.0,23.179.0,29.124.0,44.219.0"}
P.entries["item:crate-of-inn-supplies"] = {n="一箱旅店补给品",s="寒脊山谷需要旅者将一箱旅店补给品送往卡拉诺斯。穴居人封锁了山口，雷酒酿制厂只能依靠旅者的帮助。",h="寒脊山谷需要旅者将一箱旅店补给品送往卡拉诺斯。穴居人封锁了山口，雷酒酿制厂只能依靠旅者的帮助。",kw={"安威玛尔","寒脊","箱子","霜锤","汉兹","卡拉诺斯","跳链","补给品","塔诺克","穴居人"},ang={["race:Dwarf"]="作为一名年轻的矮人，运送这些补给品是你第一次为寒脊山谷之外的人效力。你勇闯穴居人盘踞的山口，帮助卡拉诺斯的同胞。",["race:Gnome"]="作为一名初来乍到的侏儒，运送汉兹·跳链的包裹，能切实赢得当地矮人的好感，他们经营着丹莫罗的旅店。"},sec={{t="穿越穴居人盘踞的山口",b="在安威玛尔附近，一箱旅店补给品正等待安全穿过寒脊山小径的机会。穴居人切断了这条路线，在巡山人清理道路之前，平民信使无法运送货物。汉兹·跳链为卡拉诺斯的塔诺克·霜锤装好了酒馆补给品，那里的补给正告短缺。"}},faq={{q="箱子里装着什么？",a="箱子里装着卡拉诺斯旅店所需的日常酒馆补给品，旅者和当地居民都在那里取暖。",al={"箱内物品","旅店补给品内容","箱子里有什么"}},{q="谁将箱子寄往卡拉诺斯？",a="汉兹·跳链在安威玛尔附近装好箱子，请离开寒脊山谷的旅者将它带过山口。",al={"谁交出箱子","汉兹·跳链","寄件人"}},{q="为什么平常的信使无法送达？",a="穴居人占据了寒脊山小径，没有巡山人护送，普通信使走这条路太过危险。眼下，旅店只能指望能杀出一条路的旅者送来补给。",al={"汉兹为什么无法送达","山口被封锁","为什么请冒险者帮忙"}},{q="谁接收这些补给品？",a="接收包裹的是塔诺克·霜锤，他是卡拉诺斯雷酒酿制厂旅店老板的助手。",al={"谁接收箱子","塔诺克·霜锤","卡拉诺斯旅店老板"}}},fx={bc2f2ebd={q="什么是一箱旅店补给品？",a="这是一个由汉兹·跳链在寒脊山小径打包的货物包裹，旨在送往卡拉诺斯的雷酒酿制厂和旅店。由于离开寒脊山谷的通道被穴居人堵塞，这批货物一直被耽搁，直到有能力强壮的旅行者能将其运送过去。",al={"什么是一箱旅店补给品","一箱旅店补给品任务物品","这个箱子是什么"}},e676223e={q="为什么卡拉诺斯需要一箱旅店补给品？",a="卡拉诺斯旅店的助理塔诺克·霜锤一直在等待来自寒脊山谷的新鲜库存，但由于穴居人起义，消息一直很少。由于常规的信使线路被切断，旅店需要将这些补给品通过通道运进来，以保持旅行者和当地人在火炉旁的供应。",al={"塔诺克为什么要这个箱子","为什么需要旅店补给品","一箱旅店补给品用途"}}},fp="21,187,22.318.0,25.104.0,32.133.0,43.198.0,26.109.0"}
P.entries["item:crate-of-lightforge-ingots"] = {n="一箱光铸铁锭",s="在暴风城，一箱光铸铁锭承载着暮色森林对抗摩本特·费尔的希望。",h="在暴风城，一箱光铸铁锭承载着暮色森林对抗摩本特·费尔的希望。",kw={"箱子","矮人区","格瑞曼德·艾尔默","铁锭","铁","光铸","摩本特·费尔","暴风城"},ang={["class:Paladin"]="这些铁锭会回应圣光的力量。用它们铸成的武器，是死灵法师及其亡灵爪牙的天然克星。",["profession:Blacksmithing"]="锻造光铸铁是一门罕见的技艺。即便是格瑞曼德·艾尔默，也可能一连数年都不曾经手这种神圣的金属。"},sec={{t="神圣的货物",b="光铸铁十分稀有，这种经过祝圣的金属能引导神圣之力，对抗黑暗生物。摩本特·费尔的防护能挡住寻常钢铁，因此暮色森林寄望于用这些铁锭对抗这名死灵法师。只有熟知这种金属的特性，并敬重其神圣本质的工匠，才能将它锻造成器。"},{t="暴风城的武器匠",b="这箱铁锭将送交格瑞曼德·艾尔默，他是暴风城矮人区的一位技艺精湛的矮人武器匠。他已有多年未曾锻造光铸铁，却仍答应将它铸成一件经过祝圣的武器。这件武器将用来击破摩本特·费尔的防护，将他击杀。"}},faq={{q="这只箱子里装着什么？",a="箱子里装着经过祝圣的光铸铁，将用于打造一件能穿透摩本特·费尔魔法防护的武器。",al={"箱中物品","光铸铁是什么","箱子里有什么"}},{q="这只箱子应该交给谁？",a="这只箱子要交给格瑞曼德·艾尔默，他是暴风城矮人区的一位技艺精湛的矮人武器匠。",al={"箱子交给谁","箱子接收人","箱子送到哪里"}},{q="为什么需要光铸铁？",a="摩本特·费尔的防护能挡住寻常钢铁。光铸铁能引导神圣之力，对抗黑暗生物。",al={"为什么用光铸铁","为什么不用普通铁","摩本特·费尔的弱点"}},{q="这只箱子是谁制作的？",a="戈罗林·钢眉将你找回的光铸铁装进箱子，以便送交暴风城的格瑞曼德·艾尔默。",al={"谁装的铁锭","谁给的箱子"}}},fp="26,89,17.292.0,28.272.1,26.104.0,38.101.0,30.111.0,22.117.0"}
P.entries["item:crate-with-holes"] = {n="开孔的箱子",s="在棘齿城，麦伯克·米希瑞克斯正在为一只地鼠准备箱子。",h="在棘齿城，麦伯克·米希瑞克斯正在为一只地鼠准备箱子。",kw={"蓝叶薯","开孔的箱子","麦伯克·米希瑞克斯","棘齿城","剃刀沼泽","地鼠"},sec={{t="箱中的嗅探者",b="麦伯克·米希瑞克斯派出训练有素的地鼠，在剃刀沼泽寻找蓝叶薯。这些地鼠无法徒步跟随冒险者穿越贫瘠之地，因此麦伯克将它们分别装进带有透气孔的木箱。进入野猪人的要塞后，箱子被打开，地鼠便凭着灵敏的嗅觉寻找埋藏的块茎。"}},faq={{q="开孔的箱子里装着什么？",a="里面装着一只活生生的地鼠，由麦伯克·米希瑞克斯训练。箱子上的孔洞让它在穿越贫瘠之地的途中能够呼吸。",al={"箱子里有什么","箱内物品","里面有什么"}},{q="在哪里可以取得开孔的箱子？",a="你可以从棘齿城的麦伯克·米希瑞克斯身旁那堆箱子中取走一个，棘齿城是贫瘠之地东海岸的港口城镇。",al={"箱子位置","哪里能找到开孔的箱子","麦伯克的箱子"}},{q="在剃刀沼泽里如何使用箱子？",a="在剃刀沼泽内打开箱子，放出地鼠。用地鼠指挥棒指挥它，它便会凭着嗅觉寻找埋在地下的蓝叶薯。",al={"如何使用开孔的箱子","使用箱子","召唤地鼠"}},{q="为什么没有地鼠就很难找到蓝叶薯？",a="蓝叶薯生长在剃刀沼泽的根系之间，深埋地下，寻常目力无法看见。地鼠能在五十步外闻到它们的气味。",al={"为什么需要地鼠","寻找块茎","块茎位置"}}},fx={["39b6cc8f"]={q="开孔的箱子是从哪里来的，它是谁制造的？",a="该箱子由在贫瘠之地棘齿城港口城镇经营的进取心强的地精商人麦伯克·米希瑞克斯提供。为了收获隐藏在剃刀沼泽野猪人据点内的珍贵根茎，麦伯克想出了一种将受过训练的嗅鼻地鼠安全运送到现场的方法，在标准的运输箱上打孔，以便他珍贵的小动物在运输过程中呼吸。",al={"开孔的箱子出处","谁制作了开孔的箱子","开孔的箱子来源"}},["08415caf"]={q="为什么麦伯克·米希瑞克斯想要取回开孔的箱子？",a="麦伯克希望取回箱子，同时还有他的指挥棒和收获的蓝叶块茎，因为受过训练的嗅鼻地鼠是他负担不起损失的投资。块茎是世界上极为罕见的美味，没有他受过训练的地鼠和专门的运输箱，在剃刀沼泽深处找到它们几乎是不可能的。",al={"麦伯克为什么要这个箱子","为什么要这个开孔的箱子","开孔的箱子用途"}}},fp="16,68,18.332.0,36.136.0,36.105.0,46.184.0,59.148.0"}
P.entries["item:crawler-leg"] = {n="蟹腿",s="在黑海岸雾气弥漫的海边，螃蟹脱落的蟹腿对大多数旅人来说毫无用处。这些坚韧的肢体却能帮助一位侏儒维持通讯装置的运转。",h="在黑海岸雾气弥漫的海边，螃蟹脱落的蟹腿对大多数旅人来说毫无用处。这些坚韧的肢体却能帮助一位侏儒维持通讯装置的运转。",kw={"奥伯丁","传声盒827","蟹腿","黑海岸","暗礁蟹","潮行蟹","维兹班恩·曲针"},ang={["profession:Engineering"]="维兹班恩·曲针用蟹腿充当临时杠杆，以附近的材料替代标准金属连杆，展现了侏儒在野外就地应变的本领。",["race:Gnome"]="身为侏儒，你或许会在沙滩上看到具有攻击性的甲壳动物，并意识到它们的腿可以用作精密远距离通讯网络的零件。"},sec={{t="海岸上的侏儒巧思",b="黑海岸的螃蟹会在岸边留下坚实的肢体，从小潮行蟹到暗礁蟹都是如此。暗夜精灵哨兵很少留意这些蟹腿，侏儒工程师维兹班恩·曲针却找到了它们的用途。维兹班恩·曲针在奥伯丁设计了名为传声盒的远距离通讯装置原型，利用就地取材的临时零件运转。蟹腿分节的关节与坚韧的几丁质能提供所需的摩擦力和杠杆作用，用来修理镇子南边不远处海岸上的传声盒827。"}},faq={{q="蟹腿有什么用途？",a="收集蟹腿是为了修理传声盒827，这座实验性通讯站位于奥伯丁南边不远处的黑海岸沿岸。侏儒发明家维兹班恩·曲针将它安置在那里。",al={"蟹腿用途","为什么保留蟹腿","传声盒 蟹腿"}},{q="蟹腿从哪里来？",a="蟹腿来自黑海岸沙滩上的螃蟹，包括 小潮行蟹、小暗礁蟹、硬壳潮行蟹 和 暗礁蟹。",al={"蟹腿来源","哪些螃蟹掉落蟹腿","哪里能找到蟹腿"}},{q="机械装置 传声盒 为什么需要蟹腿？",a="维兹班恩·曲针设计的机器可以利用附近野生动物身上的部件进行野外维修。蟹腿坚硬的关节与几丁质体节能嵌合 传声盒 转动的齿轮，让内部机械恢复运转。",al={"机器为什么用螃蟹","传声盒 蟹腿背景故事","蟹腿如何修复 传声盒"}}},fx={bab31e79={q="什么是蟹腿？",a="蟹腿是从沿着黑海岸雾气笼罩的海岸爬行的各种爬行类生物身上采集的断肢。凭借其坚硬的甲壳和耐用的关节，这些腿非常坚韧，适合进行粗糙的临时机械修理。",al={"什么是蟹腿","蟹腿物品","关于蟹腿"}}},fp="11,145,30.488.0,31.178.0,32.155.0,45.214.0"}
P.entries["item:creeper-ichor"] = {n="食苔蛛的毒液",s="在希尔斯布莱德各处的森林中，可以从食苔蛛身上采集到稀有而剧毒的食苔蛛的毒液。塔伦米尔的皇家药剂师学会正在寻找这种毒液，将其用作研制新型瘟疫、对付生者的生物制剂。",h="在希尔斯布莱德各处的森林中，可以从食苔蛛身上采集到稀有而剧毒的食苔蛛的毒液。塔伦米尔的皇家药剂师学会正在寻找这种毒液，将其用作研制新型瘟疫、对付生者的生物制剂。",kw={"药剂师林度恩","食苔蛛的毒液","克雷普塞斯","受难药剂","希尔斯布莱德丘陵","食苔蛛","塔伦米尔"},ang={["race:Undead"]="作为被遗忘者的忠诚追随者，取得食苔蛛的毒液这类致命材料，就能直接推动皇家药剂师学会清除洛丹伦生者的行动。"},sec={{t="希尔斯布莱德的药剂研究",b="在塔伦米尔，药剂师林度恩正在寻找天然毒素和生物催化剂，以研制致命的新毒素，灭绝周围的人类。丘陵间清新的空气与蓬勃的生机令他厌恶。在森林中的巨型蛛类里，成熟的食苔蛛体内藏着一种难得的毒液，是配制受难药剂的理想基液。这种液体与包括灰熊舌头在内的其他材料混合，帮助被遗忘者完善其致命的炼金术。"}},faq={{q="哪些生物能提供食苔蛛的毒液？",a="遍布希尔斯布莱德丘陵的食苔蛛身上可以采集到这种液体。它们包括巨型食苔蛛、森林食苔蛛、老食苔蛛，以及名为克雷普塞斯的知名蛛类。",al={"食苔蛛的毒液获取地点","食苔蛛的毒液掉落来源","掉落食苔蛛的毒液的怪物"}},{q="药剂师林度恩为何需要这种液体？",a="药剂师林度恩在持续进行的炼金研究中，将食苔蛛的毒液用作关键的致死成分。它能帮助他配制受难药剂，用瘟疫感染并灭绝希尔斯布莱德活着的人类。",al={"林度恩需要毒液的原因","受难药剂的用途","食苔蛛的毒液的用途"}},{q="食苔蛛的毒液为何如此难寻？",a="塔伦米尔周围的森林里，食苔蛛十分常见，但体内存有可用剧毒毒液的个体却不多。猎人可能需要杀死许多蛛类，才能取得一份可用的样本。",al={"稀有的原因","食苔蛛的毒液掉落率"}}},fx={f45507cb={q="什么是食苔蛛的毒液？",a="食苔蛛的毒液是一种极其罕见的体液，是从出没于希尔斯布莱德丘陵的苔藓爬行者身上采集的。这些巨大的蜘蛛在塔伦米尔周围的森林和田野中潜行，但只有极少数能产生足够强效和纯净的毒液，可作为可用的炼金试剂。对于皇家药剂师协会来说，这种有害的精华是一种极佳的致命药剂，因其天然的毒性和不稳定的酿造潜力而备受珍视。",al={"什么是食苔蛛的毒液","食苔蛛的毒液背景","苔藓爬行者毒液"}},["3620ba85"]={q="食苔蛛的毒液是从哪里来的？",a="食苔蛛的毒液不是人工制造的，而是直接从希尔斯布莱德丘陵的原生各种苔藓爬行者身上采集的，包括巨型、森林和长者爬行者，以及像克里普瑟斯这样的臭名昭著的野兽。这是一种在这些巨大的掠食性蜘蛛体内形成的天然生物液体，虽然找到一个含有可用、浓缩量的样本需要追踪并在荒野中杀死数十只这种生物。",al={"食苔蛛的毒液来源","食苔蛛的毒液出处","谁制作了食苔蛛的毒液"}}},fp="13,197,32.446.0,35.183.0,42.189.0,42.189.0"}
P.entries["item:crocolisk-skin-classic"] = {n="鳄鱼皮",s="在洛克莫丹的旅行者营地，猎人们冒险猎杀洛克湖中的鳄鱼，获取商人和制皮匠所需的皮。",h="在洛克莫丹的旅行者营地，猎人们冒险猎杀洛克湖中的鳄鱼，获取商人和制皮匠所需的皮。",kw={"猎杀鳄鱼","鳄鱼皮","旅行者营地","洛克湖鳄鱼","洛克莫丹","马雷克·铁心","洛克湖"},ang={["class:Hunter"]="身为猎人，你涉水登上岛屿，制服一条奋力挣扎的鳄鱼并取得它的皮，以此赢得旅行者营地的尊重。",["race:Dwarf"]="身为矮人，你知道洛克莫丹的鳄鱼考验着巡山人和营地林地猎手的胆识与毅力。"},sec={{t="危险的营生",b="鳄鱼在洛克湖冰冷水域的岛屿和岸边筑巢。锋利的牙齿和厚实的鳞片让它们成为危险的猎物。即便如此，驻扎在旅行者营地的猎人仍为获取坚韧的鳄鱼皮而追猎它们。裁缝和远方的商人需要这些皮来制作结实的衣物和护甲，因此一张完好的皮在附近就能卖个好价钱。"}},faq={{q="鳄鱼皮从哪里来？",a="洛克鳄和大型洛克鳄出产这些皮。它们生活在洛克莫丹的水域和岛屿上。",al={"哪里获取鳄鱼皮","洛克湖鳄鱼皮来源","谁掉落鳄鱼皮"}},{q="洛克莫丹有谁收购或交易这些皮？",a="马雷克·铁心是旅行者营地的一名矮人猎人，他收集鳄鱼皮和鳄鱼肉，卖给来访的商人和工匠。",al={"谁需要鳄鱼皮","旅行者营地鳄鱼皮","马雷克·铁心鳄鱼皮"}},{q="为什么这些皮有销路？",a="商人需要这些坚韧、覆有鳞片的皮来制作结实的衣物和护甲。鳄鱼凶猛难杀，因此上好的鳄鱼皮能带来稳定的收入。",al={"鳄鱼皮有什么用途","鳄鱼皮用途","为什么猎杀鳄鱼"}},{q="在洛克湖猎杀鳄鱼危险吗？",a="是的。洛克湖的鳄鱼生性凶猛，强劲的双颚和锯齿状的牙齿足以咬断四肢。马雷克·铁心等当地猎人时常交流那些在设法制住猎物时险些丧命的经历。",al={"洛克湖鳄鱼危险吗","猎杀鳄鱼的危险"}}},fx={c6e655b9={q="什么是鳄鱼皮？",a="鳄鱼皮是从栖息在洛克莫丹水域和岛屿上的鳄鱼身上采集的坚韧带鳞的兽皮。因其耐用性和独特的纹理而备受珍视，它是制皮师和裁缝想要制作坚固的服装、防护装备或特种护甲时的宝贵原材料。",al={"什么是鳄鱼皮","鳄鱼皮（材质）","什么是鳄鱼皮（复数）"}}},fp="24,122,17.342.0,35.115.0,45.132.0,30.140.0,55.210.0"}
P.entries["item:crocolisk-tear-classic"] = {n="鳄鱼的眼泪",s="在巨石水坝，总工程师辛德维尔七世需要鳄鱼的眼泪来对付黑铁的炸药。",h="在巨石水坝，总工程师辛德维尔七世需要鳄鱼的眼泪来对付黑铁的炸药。",kw={"鳄鱼的眼泪","黑铁","辛德维尔七世","洛克莫丹","试剂","巨石水坝","洛克湖"},ang={["profession:Engineering"]="当普通工具不足以应付时，总工程师辛德维尔七世这样的矮人工程师会使用不同寻常的炼金化合物来中和先进的炸药。"},sec={{t="奇特的材料",b="鳄鱼的眼泪来自洛克莫丹水域中的爬行动物。总工程师辛德维尔七世发现了这些分泌物的另一种用途。与强效蜘蛛毒液和能产生共鸣的食人魔矿物混合后，鳄鱼的眼泪便具备了所需的化学性质，能够中和威胁巨石水坝的易爆黑铁爆破炸药。"}},faq={{q="鳄鱼的眼泪有什么用途？",a="在巨石水坝，总工程师辛德维尔七世需要一份鳄鱼的眼泪来配制混合剂，用于解除黑铁破坏者埋下的炸药。",al={"鳄鱼的眼泪用途","为什么需要鳄鱼的眼泪","谁需要鳄鱼的眼泪"}},{q="在哪里可以收集鳄鱼的眼泪？",a="洛克鳄和大型洛克鳄栖息在洛克莫丹的水域和浅滩中。可以在那里收集它们的眼泪。",al={"鳄鱼的眼泪掉落地点","鳄鱼的眼泪位置","如何获得鳄鱼的眼泪"}},{q="鳄鱼的眼泪还要与哪些材料混合？",a="辛德维尔七世将鳄鱼的眼泪与当地森林蜘蛛身上的潜伏者的毒液，以及东北部丘陵中食人魔身上的莫格罗什水晶混合。这些材料混合后便能制成拆弹药剂。",al={"辛德维尔七世所需材料","拆弹材料","除了鳄鱼的眼泪还需要什么"}}},fx={["27a8e6d1"]={q="什么是鳄鱼的眼泪？",a="鳄鱼的眼泪是一种稀有的炼金试剂，直接从栖息在洛克莫丹水域的鳄鱼身上采集而来。尽管有一句关于虚情假意的古老谚语，但这种生理分泌物却具有非同寻常的特性，使其在特殊药剂中非常有用，特别是当它与当地其他强效试剂混合使用以中和挥发性爆炸物时。",al={"鳄鱼的眼泪","什么是鳄鱼的眼泪","鳄鱼的眼泪物品"}}},fp="24,104,19.314.0,34.146.0,38.118.0,48.173.0"}
P.entries["item:crossroads-supply-crate"] = {n="Crossroads Supply Crate",s="十字路口被盗的补给散落在贫瘠之地的钢鬃营地中。一支商队遭到劫掠，导致这座聚落缺少食物、工具和生活必需品。",h="十字路口被盗的补给散落在贫瘠之地的钢鬃营地中。一支商队遭到劫掠，导致这座聚落缺少食物、工具和生活必需品。",kw={"十字路口","十字路口补给箱","野猪人","钢鬃","运往十字路口的补给","贫瘠之地","索克"},ang={["faction:Horde"]="十字路口连接着杜隆塔尔、莫高雷和北方的荒野。这里的补给有助于保障部落在卡利姆多的通行和后勤运输。"},sec={{t="被劫掠的补给",b="钢鬃野猪人袭击了一支向十字路口运送补给的商队。补给箱被拖进了附近灌木丛和泥土洞穴间的营地。聚落的指挥官索克希望找回这些补给，以免哨站的食物、工具和生活必需品陷入严重短缺。"}},faq={{q="这些补给箱是什么？",a="箱中装着运往部落聚落十字路口的食物、工具和其他补给。钢鬃野猪人在贫瘠之地的道路上劫掠了一支补给商队，袭击过后，这些箱子便散落各处。",al={"十字路口补给","箱子里有什么","补给箱信息"}},{q="谁偷走了补给箱？",a="钢鬃野猪人袭击了商队，将补给箱拖回附近荆棘丛生的营地，大吃大喝，并囤积赃物。",al={"谁拿走了箱子","谁劫掠了商队","野猪人窃贼"}},{q="谁在寻找这些箱子？",a="索克是一名驻守十字路口的兽人军官，他正在寻找被盗的补给箱，以确保驻军和当地居民的补给充足。",al={"谁要这些箱子","交还补给箱","索克补给"}},{q="箱子在哪里？",a="这些箱子散落在周围贫瘠之地的钢鬃野猪人营地中。",al={"箱子位置","哪里能找到补给箱","十字路口补给箱位置"}}},fp="23,172,20.278.0,29.186.0,28.122.0,32.127.0,29.83.0"}
P.entries["item:crude-flint"] = {n="粗制打火石",s="在湿地各处，藓皮豺狼人随身携带粗制打火石，用刚砍下的沼泽树木生火。他们燃起的火焰激怒了沼泽的守护者——绿色守卫者雷希耶尔。",h="在湿地各处，藓皮豺狼人随身携带粗制打火石，用刚砍下的沼泽树木生火。他们燃起的火焰激怒了沼泽的守护者——绿色守卫者雷希耶尔。",kw={"粗制打火石","火焰禁忌","豺狼人","绿色守卫者","藓皮","雷希耶尔","打火石","湿地"},ang={["class:Druid"]="身为德鲁伊，你知道，为了让豺狼人过得舒适而砍伐活生生的植物，有违自然之道。夺走并砸碎这些打火石，是荒野守护者应尽的职责。"},sec={{t="泥沼中的引火石",b="在湿地，藓皮豺狼人用粗制打火石打出火花，在潮湿的沼泽中生火取暖、烤肉。他们砍伐活生生的树木，为炉火和篝火添柴。绿色守卫者雷希耶尔认为，每一点火星都在破坏沼泽的自然平衡。"},{t="绿色守卫者的惩戒",b="绿色守卫者雷希耶尔想要阻止藓皮豺狼人砍伐沼泽中的树木。他请路过的冒险者从这群豺狼人手中夺走打火石。雷希耶尔打算将每一块打火石砸成粉末，再把碎屑撒入大海，让豺狼人再也无法焚烧湿地中活生生的树木。"}},faq={{q="粗制打火石有什么用途？",a="藓皮豺狼人用粗制打火石打出火花，生火取暖和烹饪。绿色守卫者雷希耶尔请旅人收集这些打火石，阻止豺狼人点燃活生生的树木。",al={"粗制打火石用途","粗制打火石有什么用","粗制打火石作用"}},{q="哪些生物携带粗制打火石？",a="大多数成年及担任特殊职能的藓皮豺狼人都携带粗制打火石，包括藓皮蛮兵、捕兽者、沼泽行者、织雾者、秘法师、统领和纳博恩。体型较小的藓皮豺狼人和混种豺狼人不携带这种石头。",al={"谁掉落粗制打火石","哪里获取粗制打火石","哪些豺狼人有打火石"}},{q="雷希耶尔为什么要毁掉这些打火石？",a="豺狼人砍下湿地中活生生的树木，烧柴取暖，这让绿色守卫者雷希耶尔惊骇不已。他打算毁掉他们的打火石，把碎片撒入大海，让他们再也无法打火。",al={"为什么毁掉粗制打火石","雷希耶尔打火石原因","火焰禁忌原因"}},{q="这些打火石有制造价值吗？",a="没有。粗制打火石是一种粗糙的石头，只适合勉强打火；它的纯度和形状都达不到铁匠和工程师的要求。",al={"粗制打火石能用于锻造吗","粗制打火石是制造材料吗"}}},fx={b9abde94={q="什么是粗制打火石？",a="粗制打火石是一种粗糙、原始的生火石，由湿地的苔藓爪豺狼人携带。豺狼人利用这些简单的工具敲击出火花来点燃营火，焚烧沼泽地的活树枝来取暖。",al={"什么是粗制打火石","粗制打火石背景故事","这些打火石是什么"}},e1f52dc4={q="粗制打火石来自哪里，是谁制造的？",a="这些石块是由栖息在湿地沼泽中的苔藓爪豺狼人打制并携带的。几乎每一位成年的苔藓爪掠夺者、捕兽者和秘法师都会随身携带一块，作为在潮湿沼泽中引火的必备生存工具。",al={"谁制造了粗制打火石","豺狼人从哪获取粗制打火石","粗制打火石起源"}}},fp="11,156,20.231.1,29.299.1,29.181.1,34.211.0,43.222.1,39.128.0"}
P.entries["item:crystal-kelp-frond"] = {n="水晶藻叶",s="鱼人将水晶藻叶从海洋带到了艾尔文森林的水晶湖。闪金镇的威廉·匹斯特正在寻找它们，用来配制隐形水。",h="鱼人将水晶藻叶从海洋带到了艾尔文森林的水晶湖。闪金镇的威廉·匹斯特正在寻找它们，用来配制隐形水。",kw={"水晶海藻","水晶藻叶","水晶湖","闪金镇","隐形水","鱼人","威廉·匹斯特"},ang={["profession:Herbalism"]="水晶藻叶生长在水中，与扎根土壤的草药不同，也不会出现在艾尔文各处的常规草药采集点。草药师和采集者必须从当地保存这些叶片的鱼人手中夺取它们。"},sec={{t="稀有的水生材料",b="水晶藻叶来自咸水海洋，因此在艾尔文森林的淡水中十分少见。水晶湖沿岸的鱼人部族出于自身的缘由，收集并保存这些叶片。炼金师看重这些叶片扭曲视觉的奇异力量。闪金镇的威廉·匹斯特用它们作为主要材料配制隐形水，好让恋人们避开家人警惕的目光。"}},faq={{q="水晶海藻天然生长在哪里？",a="水晶海藻生长在咸水海洋中。它不会在淡水湖中自然生长，不过鱼人会收集它的枝叶，带到水晶湖这样的地方。",al={"水晶海藻生长在哪里","水晶海藻来源","海藻生长环境"}},{q="为什么水晶湖的鱼人会有海里的海藻？",a="这篇条目没有说明水晶湖的鱼人为何会有海里的海藻。条目只说，它们出于自身的缘由收集并保存这些叶片。",al={"鱼人为什么有海藻","鱼人持有海藻的原因"}},{q="闪金镇的谁需要水晶藻叶？",a="威廉·匹斯特是闪金镇狮王之傲旅店的一名药剂师，他需要水晶藻叶。他用它们为梅贝尔·马科伦配制隐形水，好让她溜出家里的葡萄园，去见托米·乔·斯通菲尔德。",al={"谁需要水晶海藻","威廉·匹斯特海藻"}},{q="水晶海藻具有什么特性？",a="炼金师看重水晶藻叶扭曲视觉的能力。威廉·匹斯特用它们配制隐形水，帮助恋人们避开他人的视线。",al={"海藻效果","水晶海藻有什么作用"}}},fx={e295764f={q="什么是水晶藻叶？",a="水晶藻叶是水晶海带的切片，这是一种海洋原生的稀有水生植物。虽然主要是海洋植被，但这些藻叶有时会被水晶湖等淡水水域周围的鱼人采集并保存。炼金术士看重这些藻叶是因为它们具有强效、半透明的特性，可以用来酿造诸如隐形水之类的特殊药剂。",al={"什么是水晶藻叶","水晶藻叶信息","什么是水晶海带"}},["8bde59b0"]={q="为什么会有人需要水晶藻叶？",a="闪金镇的炼金术士威廉·匹斯特需要水晶藻叶来酿造一种强效隐形水。他打算用这种药剂来帮助年轻的梅贝尔·马科伦，让她能神不知鬼不觉地从她家人严加看管的葡萄园里溜走，去私会她的禁忌恋人托米·乔·斯通菲尔德。",al={"谁需要水晶藻叶","为什么要采集水晶藻叶","水晶藻叶的用途"}}},fp="18,149,22.420.0,39.169.0,51.136.0,43.232.1,42.162.0"}
P.entries["item:crystal-phial"] = {n="水晶瓶",s="这是一个精致的水晶瓶，由德鲁伊特纳隆·雷拳交给幽影谷的年轻暗夜精灵冒险者。它被用来从附近的月井中汲取圣水，开启一系列旨在荣耀并滋养正在生长的世界之树泰达希尔的仪式。",h="这是一个精致的水晶瓶，由德鲁伊特纳隆·雷拳交给幽影谷的年轻暗夜精灵冒险者。它被用来从附近的月井中汲取圣水，开启一系列旨在荣耀并滋养正在生长的世界之树泰达希尔的仪式。",kw={"奥达希尔","crown of the earth","水晶瓶","月井","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="德鲁伊对月井怀有深深的敬意，利用其宁静的特性来引导自然能量并培育新的生长，而不屈服于奥术魔法的诱惑。",["race:NightElf"]="对于刚走出奥达希尔的年轻卡多雷来说，装满这个瓶子是一个基础的成年礼，将他们直接与艾露恩的圣水以及他们的人民在第三次战争后的复兴联系起来。"},sec={{t="圣水容器",b="这个精致的玻璃瓶被交给奥达希尔顶部的暗夜精灵新兵，用于重要的仪式。特纳隆·雷拳指派年轻的守护者携带它前往大树枝北侧的月井，收集那里散发着微光的湖水。虽然构造简单，但瓶中盛放的水蕴含着永恒之井的神圣遗产。带回装满水的水晶瓶是“Crown of the Earth”朝圣之旅的第一步，教导年轻的卡多雷关于他们在岛屿新家园中魔法、历史与自然之间微妙的平衡。"}},faq={{q="水晶瓶的用途是什么？",a="这个瓶子用于从幽影谷奥达希尔北侧的月井收集圣水。一旦装满，它将被送回给特纳隆·雷拳，作为任务“Crown of the Earth”的一部分。",al={"水晶瓶用途","水晶瓶的使用","我该如何处理这个瓶子"}},{q="谁会给你水晶瓶？",a="德鲁伊特纳隆·雷拳在奥达希尔大树枝顶部给年轻冒险者布置最初任务时会提供空的水晶瓶。",al={"谁提供水晶瓶","在哪里获取水晶瓶"}},{q="收集月井之水为何意义重大？",a="月井中包含与永恒之井的精华及艾露恩的恩赐相连的圣水。瓶中汲取的水被用于理解第三次战争的余波，并参与致力于滋养泰达希尔的仪式。",al={"为什么要收集月井之水","月井之水的意义","月井的用途"}},{q="瓶子装满后会发生什么？",a="它会变成装满水的水晶瓶。将其交还给特纳隆·雷拳即可完成你的初步试炼，并开启关于在泰达希尔全境创造和照料世界之树的后续课程。",al={"装满瓶子之后","装满水的水晶瓶用途"}}},fx={d56aa813={q="什么是水晶瓶？",a="水晶瓶是由幽影谷中奥达希尔顶端的特纳隆·雷拳所提供的一种精致、特制的容器。它的设计旨在安全地运输圣水，其纯净的水晶构造确保了你在从森林圣地取回月亮井水时，水中的神圣能量不会受到污染。",al={"什么是水晶瓶","水晶瓶物品"}},["819f868c"]={q="特纳隆·雷拳为什么要装满水晶瓶？",a="特纳隆·雷拳让你装满水晶瓶，作为你加入暗夜精灵社会和迈向更广阔世界的第一步。月亮井中包含着被永恒之井遗产所祝福的水，哨兵将其视为艾露恩的神龛，由德鲁伊照看。采集井水能让你了解在海加尔山所做出的牺牲，并测试你对泰达希尔脆弱现状的理解程度。",al={"为什么要装满水晶瓶","特纳隆为什么要月亮井水","特纳隆的水晶瓶意图"}}},fp="13,178,26.432.0,35.184.0,32.73.0,44.182.0,39.211.0"}
P.entries["item:crystalized-scales"] = {n="水晶鳞片",s="卡利姆多恶劣地区的石化蜥蜴能提供用于奥术研究的水晶鳞片。这些矿化的鳞皮来自焦炭谷和千针石林，而暴风城的科林·马伦正在寻求它们。",h="卡利姆多恶劣地区的石化蜥蜴能提供用于奥术研究的水晶鳞片。这些矿化的鳞皮来自焦炭谷和千针石林，而暴风城的科林·马伦正在寻求它们。",kw={"石化蜥蜴","焦炭谷","科林·马伦","水晶鳞片","施法材料","石爪山脉","暴风城","千针石林"},ang={["class:Mage"]="身为法师，你能看出恶劣的环境如何改变野兽的魔法本质，并产生可用于非同寻常的法术的施法材料。",["faction:Alliance"]="身为联盟的旅行者，你带着这些鳞片往返于暴风城和卡利姆多的荒野之间。"},sec={{t="卡利姆多的稀有施法材料",b="石化蜥蜴在石爪山的焦炭谷和千针石林的盐滩上忍受着高温与灰烬。它们的鳞皮在结晶外壳下逐渐硬化，鳞片中蕴藏着潜在的奥术共鸣。无尽之海彼岸的巫师们珍视这些鳞片，用它们进行罕见法术的实验。"},{t="马伦的奥术研究",b="在暴风城，法师科林·马伦寻找即将前往卡利姆多的旅行者，请他们为自己带回这些鳞片。马伦将鳞片上的结晶矿物层研磨成粉，再将粉末用作施法材料，用于构思中的新法术和他自己的奥术研究。"}},faq={{q="哪些生物能提供水晶鳞片？",a="适应了恶劣环境的石化蜥蜴能提供水晶鳞片，包括石爪山焦炭谷中被灼烧、烧焦和熏黑的石化蜥蜴，以及千针石林的盐石蜥蜴。",al={"鳞片掉落地点","水晶鳞片掉落生物","石化蜥蜴鳞片来源"}},{q="暴风城里是谁在寻找这些鳞片？",a="暴风城的巫师科林·马伦请前往石爪山的旅行者寻找这些鳞片，用于他的魔法实验。",al={"谁需要水晶鳞片","科林·马伦鳞片","谁使用这些鳞片"}},{q="这些鳞片如何用于施法？",a="玛伦将结晶鳞片研磨成细粉，用作他自行创造的特殊法术所需的强效施法材料。",al={"水晶鳞片为何具有魔力","鳞片施法材料"}},{q="只有石爪山能找到水晶鳞片吗？",a="玛伦请前往石爪山焦炭谷的旅行者寻找这些鳞片，而千针石林的盐石蜥蜴也有类似的结晶鳞皮。",al={"千针石林鳞片","获取鳞片的其他地点"}}},fx={cec6ea6a={q="什么是水晶鳞片？",a="水晶鳞片是从某些种类的蛇怪身上采集到的坚硬的结晶外板。值得注意的是，这些坚韧的鳞片常见于栖息在石爪山脉焦炭谷等恶劣地区的蛇怪身上，它们具有独特的矿物类特性，因此受到学者和施法者的青睐。",al={"什么是水晶鳞片","水晶鳞片背景故事","关于水晶鳞片"}},["5be8a367"]={q="水晶鳞片来自哪里？",a="这些鳞片自然生长在特定品种的蛇怪身上。它们通常从徘徊在石爪山脉焦炭谷的焦黑、黝黑且被烧焦的蛇怪身上采集，也常见于千针石林盐碱平原上的盐石蛇怪身上。",al={"水晶鳞片起源","在哪里获得水晶鳞片","水晶鳞片的来源"}}},fp="18,180,23.279.0,20.246.0,40.205.0,41.127.0,40.137.0,51.154.0"}
P.entries["item:curative-animal-salve"] = {n="动物医疗药膏",s="在黑海岸和贫瘠之地，德鲁伊使用动物医疗药膏治疗患病的野生动物。两地的草药师都在配制这种药膏，而塞纳里奥议会认为，动物的病症预示着一场范围更广的疫病。",h="在黑海岸和贫瘠之地，德鲁伊使用动物医疗药膏治疗患病的野生动物。两地的草药师都在配制这种药膏，而塞纳里奥议会认为，动物的病症预示着一场范围更广的疫病。",kw={"奥兰达利亚·夜歌","动物医疗药膏","治疗病患","对抗毒素","病鹿","病瞪羚","图加·符文图腾"},ang={["class:Druid"]="身为德鲁伊，用这种药膏治疗野生动物，既考验你投身塞纳里奥议会在卡利姆多各地事务的决心，也考验你清除毒素的本领。",["race:Tauren"]="身为牛头人，在贫瘠之地使用这种药膏，体现了牛头人德鲁伊如何遵循塞纳留斯的教诲，并配合先祖的结社仪式来疗愈大地。"},sec={{t="疗愈荒野",b="德鲁伊使用动物医疗药膏，为黑海岸和贫瘠之地患病的野生动物减轻病痛。奥兰达利亚·夜歌指引年轻的德鲁伊，治疗壁泉河与灰谷边界之间的病鹿。在贫瘠之地，图加·符文图腾配制同样的药膏，用来治疗在十字路口以北吃草的病瞪羚。两位草药师都用当地采集的草药配制药膏，每批十剂。在野外施治的德鲁伊将药膏直接涂在动物身上，两位草药师则与当地有关方面合作，扩大药膏的供应。"},{t="深层病患的征兆",b="药膏能减轻动物的痛苦，但塞纳里奥议会认为，这些病症预示着一场范围更广的异变。在月光林地，德迪利特·星焰指出，海岸上患病的鹿和草原上受苦的瞪羚，并非偶然遭殃。它们在不知不觉中成了一场疫病的受害者，这场疫病正从多个方向蔓延至卡利姆多各地。对初学者来说，治疗这些动物既考验他们守护自然的决心，也考验他们清除毒素的本领。"}},faq={{q="动物医疗药膏有什么用途？",a="德鲁伊将动物医疗药膏直接涂在患病的野生动物身上，以减轻它们的病痛。他们用这种药膏治疗黑海岸的病鹿，以及在贫瘠之地十字路口以北吃草的病瞪羚。",al={"动物医疗药膏用途","动物医疗药膏使用方法","药膏的作用"}},{q="谁在配制这种药膏？",a="在黑海岸，奥兰达利亚·夜歌用采集来的草药配制药膏。在贫瘠之地，图加·符文图腾在十字路口为部落德鲁伊配制这种药膏。",al={"药膏制作者","药膏来源"}},{q="鹿和瞪羚最初为什么会生病？",a="塞纳里奥议会的德迪利特·星焰说，一股日益加剧的污染正在卡利姆多蔓延，野生动物深受其害。鹿和瞪羚是这场生态疫病最早的受害者。",al={"动物患病原因","黑海岸的鹿中毒原因","贫瘠之地瞪羚的疾病"}},{q="一批药膏有多少剂？",a="一批标准药膏有十剂，足够使用十次。",al={"使用次数","药膏可用次数"}}},fx={a20a877c={q="什么是动物医疗药膏？",a="动物医疗药膏是一种草药疗法，专门用于治疗受蔓延的不自然疾病困扰的野生动物。它由德鲁伊盟友使用当地试剂配制而成，能够净化毒害黑海岸的鹿和贫瘠之地的瞪羚等无辜生物的顽疾。",al={"治疗药膏","什么是动物医疗药膏","动物医疗药膏背景故事"}}},fp="21,211,17.495.0,28.447.0,39.203.0,23.151.0,54.185.0,36.65.0"}
P.entries["item:daffodil-bouquet"] = {n="水仙花",s="在湖畔镇，卫兵帕克送出一束花，感谢达希为他准备午餐。玛蒂·詹罗斯采来了这些花，而她选的花却让两个女人之间多了些闲话。",h="在湖畔镇，卫兵帕克送出一束花，感谢达希为他准备午餐。玛蒂·詹罗斯采来了这些花，而她选的花却让两个女人之间多了些闲话。",kw={"水仙花","达希","卫兵帕克","湖畔镇","玛蒂·詹罗斯","赤脊山"},ang={["profession:Herbalism"]="身为湖畔镇的草药师，你或许能认出这束花出自玛蒂·詹罗斯之手。她会为自己的营生采集野花。"},sec={{t="纠葛的谢礼",b="卫兵帕克想感谢湖畔镇旅店的达希每天为他准备午餐。他请镇上的草药师玛蒂·詹罗斯准备一束水仙花。玛蒂说，这是她最喜欢的花。达希认出这是玛蒂惯常选用的花，怀疑她心存嫉妒。她半开玩笑地猜测，玛蒂会不会因怨恨而在花茎上下了毒。"}},faq={{q="水仙花有什么用途？",a="卫兵帕克将这束花送给湖畔镇旅店的达希，感谢她在他执勤时为他准备并送来午餐。",al={"水仙花用途","水仙花怎么用","水仙花送给谁"}},{q="这束花是谁准备的？",a="湖畔镇的草药师玛蒂·詹罗斯应请求采来鲜花，扎成花束。她选择水仙花，因为这是她最喜欢的花。",al={"谁扎的花束","水仙花来源","这些花从哪里来"}},{q="达希为什么对这些花起了疑心？",a="达希认出水仙花是玛蒂最喜欢的花，并非特意为她挑选的。她称玛蒂是个嫉妒她的情敌，还开玩笑说，玛蒂可能因怨恨而在花上下了毒，但她还是接受了这份心意。",al={"达希为什么生气","达希有毒的花","达希与玛蒂争风吃醋"}},{q="这些水仙花真的有毒吗？",a="没有。达希的疑心只是湖畔镇这两个女人之间夸张的争风吃醋。这些花并无毒害。",al={"花束有毒吗","玛蒂给水仙花下毒了吗"}}},fx={d233835e={q="什么是水仙花？",a="水仙花是在赤脊山采集的一束新鲜黄色花朵。这被特别选定为玛蒂·詹罗斯最喜欢的花，作为给湖畔镇旅店的达希的谢礼，以回报她提供的一顿餐食。",al={"什么是水仙花","水仙花背景故事","水仙花物品"}},c8a417a4={q="为什么达希需要水仙花？",a="达希并没有特别要求花，但卫兵帕克在收到她送到三角路口哨所的热午餐后，想回馈她的好意。他让你去取一束花来让她开心一下，尽管她在意识到是谁准备的这些草药之前，还是迫不及待地收下并将它们插进水里。",al={"为什么要送水仙花","为什么达希想要花","谁想要水仙花"}}},fp="16,182,15.349.0,38.135.0,26.161.0,49.212.1,36.108.1"}
P.entries["item:daggerspine-scale"] = {n="刺脊纳迦的鳞片",s="在希尔斯布莱德丘陵南部沿海，刺脊纳迦的鳞片采自四处游荡的刺脊纳迦，是坚韧的爬行动物鳞片。皇家药剂师学会正在搜集这些鳞片，用来激活剧毒药剂，推进被遗忘者持续进行的瘟疫实验。",h="在希尔斯布莱德丘陵南部沿海，刺脊纳迦的鳞片采自四处游荡的刺脊纳迦，是坚韧的爬行动物鳞片。皇家药剂师学会正在搜集这些鳞片，用来激活剧毒药剂，推进被遗忘者持续进行的瘟疫实验。",kw={"刺脊","刺脊纳迦的鳞片","苦楚药剂","希尔斯布莱德","林度恩","纳迦","皇家药剂师学会","幽暗城"},ang={["faction:Horde"]="身为部落的一员，你必须小心穿行于南部海岸，因为刺脊的营地与联盟港口南海镇相距极近，十分危险。",["race:Undead"]="身为Undead，采集这些鳞片能推进皇家药剂师学会的研究，研制出对付被遗忘者敌人的毁灭性新瘟疫。"},sec={{t="药剂研究",b="皇家药剂师学会正在为其毒素、瘟疫和各类药剂搜集试剂。在改良实验性的苦楚药剂时，药剂师们发现，当地刺脊纳迦的鳞片能产生有用的反应。将这些鳞片与巨魔再生药剂和鱼人器官混合，便能通过化学反应激活悬浮在原始混合液中、处于休眠状态的污染因子。要采集这些鳞片，就得前往南海镇以东的岩石海岸狩猎，那里既有凶残的纳迦部族，也有联盟部队。药剂师们的研究需要这些鳞片。"}},faq={{q="刺脊纳迦的鳞片有什么用途？",a="塔伦米尔的药剂师林度恩正在搜集刺脊纳迦的鳞片，用于研究苦楚药剂。与其他试剂混合后，这些鳞片能激活炼金药剂泥头花水的污染特性。",al={"刺脊纳迦的鳞片用途","为什么收集刺脊纳迦的鳞片","刺脊纳迦的鳞片有什么用"}},{q="这些鳞片来自哪里？",a="刺脊纳迦的鳞片来自希尔斯布莱德丘陵沿海的刺脊纳迦，就在南海镇正东方。这些鳞片可从海岸潜伏者、海岸猎手、尖啸者、海妖以及他们的首领塞菲莉斯身上获取。",al={"哪里能找到刺脊纳迦的鳞片","谁掉落刺脊纳迦的鳞片","刺脊纳迦的鳞片位置"}},{q="皇家药剂师学会为什么需要纳迦鳞片？",a="皇家药剂师学会需要刺脊纳迦的鳞片，因为这些坚韧的鳞片具有所需的化学特性，能够激活实验性枯萎药剂和疾病药剂中的特定传染因子。",al={"为什么需要纳迦鳞片","药剂师纳迦鳞片"}}},fx={["8e2c4377"]={q="什么是刺脊纳迦的鳞片？",a="刺脊纳迦的鳞片是一种坚韧的水生鳞片，是从徘徊在希尔斯布莱德丘陵海岸的刺脊纳迦身上采集的。这些蛇形生物拥有独特的生物特性，使得它们脱落和采集到的鳞片成为皇家药剂师学会制造邪恶药剂的珍贵试剂。",al={"什么是刺脊纳迦的鳞片","刺脊纳迦的鳞片物品","关于刺脊纳迦的鳞片"}}},fp="17,227,19.552.0,37.205.0,32.212.0,55.206.0"}
P.entries["item:dal-bloodclaw-s-skull"] = {n="达尔·血爪的颅骨",s="在灰谷北部，达尔·血爪的颅骨标志着阿斯特兰纳的一场威胁已被消除。莱恩·狼行者收下这颗颅骨，作为暗夜精灵聚居地免遭袭击的证明。",h="在灰谷北部，达尔·血爪的颅骨标志着阿斯特兰纳的一场威胁已被消除。莱恩·狼行者收下这颗颅骨，作为暗夜精灵聚居地免遭袭击的证明。",kw={"灰谷","阿斯特兰纳","达尔·血爪","熊怪","莱恩·狼行者","颅骨","蓟皮"},ang={["faction:Alliance"]="作为联盟的一员，你协助巩固阿斯特兰纳北翼的防线。这处聚居地是联盟在灰谷中部的主要庇护所。",["race:NightElf"]="身为暗夜精灵，击败堕落的熊怪首领或许会让你感到悲哀。腐化扭曲了昔日的盟友，如今他们已威胁到阿斯特兰纳这样的聚居地。"},sec={{t="酋长的覆灭",b="阿斯特兰纳以北的蓟皮熊怪数量日益增多，也变得愈发好斗。与灰谷古老森林中的许多生灵一样，他们已遭到腐化。暗夜精灵哨兵莱恩·狼行者担心，他们很快就会向阿斯特兰纳进军。她下令削减他们的数量，并杀死他们的首领达尔·血爪。他的颅骨是部族首领已被铲除的残酷证明，为阿斯特兰纳的守军争取了宝贵的时间。"}},faq={{q="达尔·血爪是谁？",a="达尔·血爪统领着蓟皮要塞的蓟皮熊怪，那里就在阿斯特兰纳北面不远处。在他的领导下，这个充满敌意的部族迅速壮大，威胁着附近的暗夜精灵前哨站。",al={"达尔·血爪","血爪是谁","蓟皮酋长"}},{q="莱恩·狼行者为什么想要这颗颅骨？",a="莱恩·狼行者需要蓟皮酋长已死的证明。暗夜精灵希望幸存的熊怪会陷入混乱，无法再有组织地策划对阿斯特兰纳的袭击。",al={"为什么要颅骨","莱恩·狼行者的颅骨任务","死亡证明"}},{q="蓟皮熊怪为什么如此充满敌意？",a="与灰谷的许多熊怪部族一样，蓟皮熊怪也屈服于森林中蔓延的腐化。他们变得狂暴，极力排斥闯入领地的外来者，威胁着曾经与他们比邻而居的人们。",al={"熊怪为什么好斗","熊怪腐化","蓟皮发狂"}}},fx={b1ad26a7={q="什么是达尔·血爪的颅骨？",a="这是达尔·血爪被砍下的颅骨，他是阿斯特兰纳以北蓟皮要塞中受腐化的蓟皮熊怪的首领。它是他死亡的血腥物证。",al={"什么是达尔·血爪的颅骨","达尔的颅骨","这个颅骨是什么"}},fa2f0114={q="达尔·血爪的颅骨来自哪里？",a="这个颅骨是在达尔·血爪本人被杀，以打破他日益壮大的部落的领导层之后，直接从位于北部灰谷深处的蓟皮要塞中的遗骸上取下的。",al={"达尔·血爪的颅骨来自哪里","谁制造了达尔·血爪的颅骨","达尔·血爪的颅骨起源"}}},fp="21,130,22.388.0,22.184.0,41.185.0,43.200.0"}
P.entries["item:dalaran-mana-gem"] = {n="达拉然法力宝石",s="在安伯米尔附近，肯瑞托法师随身携带达拉然法力宝石，用来补充力量。被遗忘者裁缝用这些宝石织造附魔长袍。",h="在安伯米尔附近，肯瑞托法师随身携带达拉然法力宝石，用来补充力量。被遗忘者裁缝用这些宝石织造附魔长袍。",kw={"安伯米尔","达拉然法力宝石","乔瑟夫·格里高利","肯瑞托","亚麻布","法力宝石","银松森林","魔焰长袍"},ang={["class:Mage"]="身为被遗忘者法师，你受命夺取这些宝石，作为入门试炼，证明自己的战斗技巧，以及对夺来的奥术力量的掌控。",["race:Undead"]="身为亡灵旅者，你知道被遗忘者为了维系阵营的生存，放下了对达拉然昔日人类同僚的情谊。"},sec={{t="窃取的奥术之力",b="安伯米尔周围的肯瑞托法师、咒术师和卫兵随身携带法力宝石，用来凝聚和补充奥术力量。在幽暗城的魔法区，被遗忘者施法者珍视这些宝石，因为它们能随时提供浓缩的魔力。一些亡灵法师与达拉然有着共同的学术传承，但生存才是首要之事。在被遗忘者眼中，肯瑞托是对手，他们储备的魔法资源可以夺取。"},{t="织入魔焰",b="被遗忘者将从阵亡的肯瑞托人员身上取来的法力宝石，连同普通的亚麻布，一起交给幽暗城的乔瑟夫·格里高利等裁缝。裁缝无法直接引导奥术力量，却能将宝石缚入布料。随后，魔力便会加强穿戴者与奥术的联系。"}},faq={{q="达拉然法力宝石从何而来？",a="银松森林的肯瑞托部队随身携带达拉然法力宝石，尤其是在瑟伯切尔东南方、安伯米尔附近的营地和哨站周围。",al={"哪里刷法力宝石","达拉然宝石掉落","谁掉落法力宝石"}},{q="这些宝石有什么用途？",a="被遗忘者法师将宝石和亚麻布带给幽暗城的乔瑟夫·格里高利。他用这些材料织造魔焰长袍。",al={"法力宝石用途","为何需要达拉然法力宝石"}},{q="银松森林的肯瑞托为何携带这些宝石？",a="肯瑞托成员随身携带法力宝石，作为个人的奥术力量储备。在危机四伏的银松森林，这些宝石为他们的施法、防护结界和召唤法术提供力量。",al={"达拉然巫师为何有宝石","肯瑞托法力宝石背景"}},{q="被遗忘者为何为了这些宝石而袭击达拉然法师？",a="被遗忘者与达拉然有着共同的学术传承，但被遗忘者将那些仍然活着的同行视为对手。幽暗城的导师认为，连自己的奥术财富都守不住的法师太过弱小，无法生存，因此他们会夺走这些法师的施法材料。",al={"被遗忘者与达拉然法师","为何为了长袍杀死达拉然成员"}}},fx={["02094a76"]={q="什么是达拉然法力宝石？",a="达拉然法力宝石是由驻扎在银松森林的肯瑞托特工所携带的带有魔法充能的石头。这些晶体注入了奥术能量，是制作附魔服装的重要组件，例如幽暗城的被遗忘者裁缝所缝制的法术火长袍。",al={"什么是达拉然法力宝石","达拉然法力宝石","银松森林的法力宝石"}}},fp="16,140,13.342.0,21.290.0,37.155.0,29.116.0,56.168.0,56.239.0"}
P.entries["item:dalaran-pendant"] = {n="达拉然坠饰",s="在安伯米尔，达拉然坠饰用来汇聚肯瑞托的魔法。被遗忘者寻求这些坠饰，以阻挠巫师们的行动，并追查他们的力量之源。",h="在安伯米尔，达拉然坠饰用来汇聚肯瑞托的魔法。被遗忘者寻求这些坠饰，以阻挠巫师们的行动，并追查他们的力量之源。",kw={"奥利斯特","安伯米尔","达拉然坠饰","肯瑞托","瑟伯切尔","银松森林"},ang={["class:Mage"]="身为法师，你能看出肯瑞托如何利用这些坠饰汇聚魔法，并协调复杂的法术。",["race:Undead"]="身为亡灵，从肯瑞托手中夺取这些坠饰，有助于抵御试图重新站稳脚跟的人类巫师，确保银松森林的安全。"},sec={{t="安伯米尔的护符",b="肯瑞托的巫师、咒术师和护卫在安伯米尔编织强大的法术，威胁着被遗忘者对银松森林南部的控制。他们每人都携带着一枚经过调谐的达拉然坠饰。在瑟伯切尔，暗影牧师奥利斯特派遣被遗忘者特工夺取这些坠饰，以拖慢法师们的行动，并查明是谁在引导他们编织魔法。"}},faq={{q="达拉然坠饰是什么？",a="达拉然坠饰是安伯米尔的肯瑞托咒术师、法师和护卫随身携带的奥术护符。被遗忘者寻求这些坠饰，以打断巫师们的施法，并研究其中的魔法。",al={"达拉然坠饰是什么","肯瑞托项链 银松森林"}},{q="谁携带着这些坠饰？",a="在银松森林的安伯米尔，达拉然的人类法师、咒术师和护卫携带着这些坠饰。",al={"谁掉落达拉然坠饰","哪里获取达拉然坠饰"}},{q="暗影牧师奥利斯特为什么想要这些坠饰？",a="暗影牧师奥利斯特和他的盟友达拉尔需要这些坠饰，以拖慢巫师们的施法，并找出指挥安伯米尔魔法编织的强大法师。",al={"奥利斯特为什么要坠饰","安伯米尔调查 坠饰"}},{q="安伯米尔位于何处？",a="安伯米尔位于银松森林南部。从瑟伯切尔出发，沿主路向南，再走东侧的岔路便可抵达村庄。",al={"安伯米尔位置","如何前往安伯米尔"}}},fp="15,139,20.355.0,28.155.0,27.104.0,42.155.0,27.141.0"}
P.entries["item:dalaran-status-report"] = {n="达拉然形势报告",s="在安伯米尔，肯瑞托密切关注着正在露天重建的达拉然。他们的报告中有亡灵哨兵想要获取的情报。",h="在安伯米尔，肯瑞托密切关注着正在露天重建的达拉然。他们的报告中有亡灵哨兵想要获取的情报。",kw={"安伯米尔","安伯米尔保险箱","达拉然形势报告","亡灵哨兵","肯瑞托","米奈特·卡加德","交易工具","瓦里玛萨斯"},ang={["class:Rogue"]="身为潜行者，你要在米奈特·卡加德的指导下，从戒备森严的法师手中取回报告，证明自己的开锁和潜入本领。",["race:Undead"]="身为亡灵，你知道安伯米尔的肯瑞托残余势力让银松森林的被遗忘者深感不安。有关他们行动的情报关系着幽暗城的安全。"},sec={{t="关注重建中的城市",b="第三次战争期间，天灾军团洗劫了达拉然，阿克蒙德摧毁了城中高耸的尖塔。重建初期，幸存的法师撤去了城市的防护屏障，开始在露天开展重建工作。肯瑞托还保有多处据点，包括位于银松森林东南部的安伯米尔。那里的巫师编写了达拉然形势报告，其中记载了城市现状的情报，引起了亡灵哨兵的注意。"},{t="亡灵哨兵的考验",b="瓦里玛萨斯大人时刻留意联盟和肯瑞托的残余势力，以持续的警戒维护被遗忘者对洛丹伦的控制。被遗忘者的审讯者迫使一名被俘的肯瑞托法师招供后，这位恐惧魔王命令亡灵哨兵夺取报告。文件藏在安伯米尔深处一只上锁的保险箱里。对于刚入门的潜行者而言，取回报告也是一场入门试炼：他们可以借此机会，在潜行者区的米奈特·卡加德指导下掌握开锁技巧。"}},faq={{q="达拉然形势报告是什么？",a="达拉然形势报告是一组肯瑞托机密文件，记录了达拉然的状况、重建工作及当前形势。它由安伯米尔哨站的法师编写。",al={"这份报告是什么","达拉然报告","安伯米尔文件"}},{q="报告存放在哪里？",a="报告锁在银松森林东南部安伯米尔定居点内的一只保险箱里。",al={"报告在哪里","安伯米尔保险箱位置","如何找到形势报告"}},{q="幽暗城为什么想要这份报告？",a="瓦里玛萨斯大人和被遗忘者认为，幸存的肯瑞托就在他们的家门口，仍构成切实的威胁。这份报告能帮助亡灵哨兵评估达拉然的军事实力和秘密重建工作。",al={"被遗忘者为何想要这份报告","瓦里玛萨斯达拉然报告","亡灵哨兵的目标"}},{q="亡灵哨兵是如何得知这份文件的？",a="一名被俘的肯瑞托囚犯在幽暗城接受审讯，亡灵哨兵从他口中得知了这份文件及其所在之处。",al={"幽暗城如何得知","囚犯供词"}}},fx={f1fae308={q="达拉然形势报告来自哪里，是谁制作的？",a="这份报告由驻扎在银松森林南部安伯米尔的肯瑞托巫师起草。在第三次战争期间达拉然遭到破坏后，幸存的法师们在周边地区维持哨站，以监视他们沦陷的城市、记录正在发生的事务并协调他们剩余的部队。",al={"谁撰写了达拉然形势报告","达拉然形势报告起源","谁制作了达拉然形势报告"}}},fp="21,99,27.420.0,21.456.1,34.173.0,25.84.0,40.202.0,51.122.0"}
P.entries["item:dalin-s-heart"] = {n="达林的心脏",s="在银松森林的格雷迈恩之墙附近，达林·弗治维特怀着一颗正直的心巡逻。",h="在银松森林的格雷迈恩之墙附近，达林·弗治维特怀着一颗正直的心巡逻。",kw={"凯伦丁·哈加尔","达林·弗治维特","达林的心脏","格雷迈恩之墙","纯洁者之心","银松森林","魅魔","幽暗城"},ang={["class:Warlock"]="作为一名被遗忘者术士，你通过这场试炼学习如何束缚魅魔，收割纯洁无瑕的美德，以掌控恶魔。",["race:Undead"]="作为一名亡灵，你看到了洛丹伦遭受Scourge肆虐后的残酷现实，格雷迈恩之墙外那些无私的活人沦为了被遗忘者的猎物。"},sec={{t="黑暗法术所需的纯洁之心",b="幽暗城的术士寻找真正品德高尚的凡人的心脏，用来召唤魅魔，并将其束缚，为自己效力。达林·弗治维特日复一日地保护着绝望的洛丹伦难民，紧闭的格雷迈恩之墙将他们挡在安全之地外。他无私的奉献使他成为难得的纯洁祭品，他的心脏被剖出，用于在诅咒神殿举行的仪式。"}},faq={{q="达林·弗治维特是谁？",a="达林·弗治维特是一名正直的人类，保护着滞留在银松森林南部格雷迈恩之墙紧闭大门外的洛丹伦难民。",al={"达林·弗治维特","达林是谁","达林的故事"}},{q="术士为什么需要达林的心脏？",a="幽暗城的术士在仪式中用达林的心脏引来魅魔，再将她束缚，为自己效力。",al={"为何需要达林的心脏","达林的心脏用途","术士为何需要达林的心脏"}},{q="谁收取达林的心脏？",a="凯伦丁·哈加尔是幽暗城内诅咒神殿的一名术士训练师，他收取达林的心脏。",al={"谁收取心脏","达林的心脏交付","达林的心脏交到哪里"}},{q="除了这颗心脏，还需要什么材料？",a="凯伦丁·哈加尔需要达林的心脏和科马的心脏。科马·韦拉德是一位忠贞的丈夫，在湿地四处寻找失踪的妻子。",al={"纯洁者之心另一颗心脏","所需的另一颗心脏","第二颗心脏"}}},fx={["5b5f5201"]={q="什么是达林的心脏？",a="这是从达林·锻铸者身上切下来的实体心脏，他是一位在银松森林格雷迈恩之墙附近照顾洛丹伦难民的正直之人。虽然在物理上与其他人类心脏没有区别，但它拥有无私且高尚灵魂所独有的纯洁精神。",al={"什么是达林的心脏","达林的心脏描述","达林的心脏物品"}},d7d2edf8={q="达林的心脏来自哪里？",a="这颗心脏来自达林·锻铸者，一位在银松森林南部封闭的格雷迈恩之墙照顾洛丹伦难民的正直之人。术士必须追踪并杀死他，才能直接从他的尸体中获取这个器官。",al={"在哪里获取达林的心脏","达林的心脏起源","谁掉落达林的心脏"}}},fp="13,103,26.378.0,26.159.0,35.105.0,26.107.0,52.144.0"}
P.entries["item:darkhound-blood"] = {n="黑暗犬的血液",s="在提瑞斯法的田野和森林中，受污染的黑暗犬体内流淌着一种体液——黑暗犬的血液。皇家药剂师学会收集这种血液，将其用作早期实验的试剂，以研制一种致命的新型瘟疫。",h="在提瑞斯法的田野和森林中，受污染的黑暗犬体内流淌着一种体液——黑暗犬的血液。皇家药剂师学会收集这种血液，将其用作早期实验的试剂，以研制一种致命的新型瘟疫。",kw={"新型瘟疫","药剂师乔汉","布瑞尔","黑暗犬","黑暗犬的血液","皇家药剂师学会","提瑞斯法林地"},ang={["faction:Horde"]="在布瑞尔，皇家药剂师学会进行着黑暗的实验，除了被遗忘者的核心圈子，鲜有人能完全理解这些实验可能产生怎样的剧毒。",["race:Undead"]="采集黑暗犬的血液这类试剂，是被遗忘者不可或缺的工作。这有助于Sylvanas女士和皇家药剂师学会打造对抗Scourge的终极武器。"},sec={{t="新的瘟疫的原料",b="在希尔瓦娜斯·风行者女士的领导下，皇家药剂师学会致力于研制一种能够消灭阿尔萨斯及其天灾军团的烈性传染病。药剂师乔汉驻扎在布瑞尔。他推测，当地野兽受到黑暗能量的腐化，却能抵御周遭的腐朽，因此具有不同寻常的生物特性。\n\n通过提炼野生黑暗犬的血液，乔汉希望发现能够抵御或传播烈性坏死病株的化合物。"}},faq={{q="黑暗犬的血液有什么用途？",a="布瑞尔的药剂师乔汉将黑暗犬的血液用作皇家药剂师学会研究中的早期试剂，以调制一种比艾泽拉斯以往任何瘟疫都更致命的新型瘟疫。",al={"黑暗犬的血液用途","为何收集黑暗犬的血液","黑暗犬的血液作用"}},{q="哪些生物能提供这种血液？",a="黑暗犬的血液来自游荡在提瑞斯法林地的受诅咒、饥饿和衰老的黑暗犬。",al={"哪里获取黑暗犬的血液","谁掉落黑暗犬的血液","黑暗犬的血液来源"}},{q="为什么选中黑暗犬进行瘟疫研究？",a="药剂师乔汉推测，适应了提瑞斯法腐化土地的野兽，其血液中或许藏着合成一种无法阻挡的传染病所需的生物奥秘。",al={"为何选择黑暗犬","药剂师乔汉的推测","黑暗犬的特性"}}},fx={db825c3d={q="什么是黑暗犬的血液？",a="黑暗犬的血液是从徘徊在提瑞斯法林地的野性黑暗犬身上采集的受污染的生命液体。这些被黑暗魔法和遍布林地的残留亡灵扭曲的可怜犬类，其血液携带独特的、坚韧的特性。尽管对于普通的活体生物来说，它既令人作呕又具有危险性，但炼金术士和研究人员发现它是进行生物实验的理想媒介，特别是在研究剧毒化合物或抵抗亡灵腐烂时。",al={"什么是黑暗犬的血液","黑暗犬的血液背景故事","解释黑暗犬的血液"}},["93cde5f9"]={q="黑暗犬的血液来自哪里？是谁制造的？",a="这种血液是从提瑞斯法林地被诅咒、饥饿而衰弱的黑暗犬身上自然采集的。这些野兽在闹鬼的林地和废弃农庄间徘徊。它并非人工调制品，而是野兽的体液；自第三次战争以来，它们逐渐适应并吸收了毒害这片区域的腐化之力。",al={"黑暗犬血液的来源","黑暗犬的血液来自哪里","谁制造了黑暗犬的血液"}}},fp="15,200,23.432.0,33.180.0,33.99.0,48.172.0"}
P.entries["item:darkshore-grouper"] = {n="黑海岸石斑鱼",s="在黑海岸沿岸，石斑鱼是常见的渔获，但鱼人的袭击已迫使渔民放弃出海。无论作为食材还是垂钓的目标，这种鱼都备受青睐，如今想满载而归却更难了。",h="在黑海岸沿岸，石斑鱼是常见的渔获，但鱼人的袭击已迫使渔民放弃出海。无论作为食材还是垂钓的目标，这种鱼都备受青睐，如今想满载而归却更难了。",kw={"奥伯丁","布拉普家族鱼竿","黑海岸","黑海岸石斑鱼","钓鱼","石斑鱼","古博·布拉普","鱼人"},ang={["profession:Cooking"]="黑海岸石斑鱼是制作简单沿海菜肴的便利食材，让四处游历的厨师能在海边磨炼厨艺。",["race:Dwarf"]="身为矮人，你或许认得古博·布拉普，他在卡利姆多海岸垂钓，延续着家族引以为傲的传统。他会奖励那些捕鱼技艺足以媲美他族人的人。"},sec={{t="雾笼海岸的家常鱼",b="在黑海岸近海的冰冷水域，黑海岸石斑鱼是颇受欢迎的渔获。奥伯丁一带的垂钓者看重它们，因为它们能做成简单的菜肴，旅人和居民都爱吃。只需一根钓线和基本的渔具，就能钓上一条。对许多渔民而言，钓到一条石斑鱼的乐趣不亚于品尝它的滋味。"},{t="鱼人的威胁",b="古博·布拉普这样的渔民曾驾着小船前往更深的水域，带回数十条石斑鱼。沿海的鱼人变得愈发凶暴，迫使奥伯丁周围的大多数渔船停航。如今，垂钓者只能在岸边和码头钓鱼，当地人怀疑鱼人正在吞食石斑鱼。想要满载而归，就得有耐心。"}},faq={{q="在哪里能找到黑海岸石斑鱼？",a="在黑海岸的海水中下钩，包括奥伯丁周围的水域，就能钓到黑海岸石斑鱼。",al={"哪里钓石斑鱼","黑海岸石斑鱼位置","怎么钓黑海岸石斑鱼"}},{q="奥伯丁有谁需要黑海岸石斑鱼？",a="暂居奥伯丁的矮人渔夫古博·布拉普会请旅人为他钓些黑海岸石斑鱼。作为回报，他会送上一根珍贵的布拉普家族鱼竿。",al={"谁需要石斑鱼","古博·布拉普钓鱼","石斑鱼任务发布者"}},{q="渔民为什么不用船捕捞石斑鱼？",a="黑海岸沿岸的鱼人十分凶暴，当地渔民乘船出海太过危险。",al={"渔船为什么停航","奥伯丁渔船","鱼人石斑鱼"}},{q="必须接到任务才能钓到黑海岸石斑鱼吗？",a="不必。黑海岸石斑鱼是普通的海鱼，任何垂钓者都能在黑海岸的水域钓到它们。古博·布拉普这样的当地人可能会请你钓些回来。",al={"石斑鱼是任务物品吗","随时都能钓石斑鱼吗"}}},fp="17,190,30.313.0,17.326.0,37.111.0,41.162.0,50.95.0,58.160.0"}
P.entries["item:darksoul-shackle"] = {n="魔魂镣铐",s="在银松森林，月怒魔魂狼人戴着在大法师阿鲁高指导下打造的附魔镣铐。瑟伯切尔的被遗忘者法师正在寻找这些镣铐，以弄清如何解除笼罩这片地区的魔法。",h="在银松森林，月怒魔魂狼人戴着在大法师阿鲁高指导下打造的附魔镣铐。瑟伯切尔的被遗忘者法师正在寻找这些镣铐，以弄清如何解除笼罩这片地区的魔法。",kw={"阿鲁高","达拉尔·道恩维沃尔","魔魂镣铐","月怒魔魂狼人","瑟伯切尔","银松森林","狼人"},ang={["class:Mage"]="身为法师，你能看出，一个走投无路的巫师如何用粗制的附魔器物，来支撑那些不稳定、又无法妥善控制的召唤法术。",["race:Undead"]="对被遗忘者而言，打破阿鲁高对银松森林的控制至关重要，既能保护他们的南部边境，也能证明幽暗城的奥术学识胜过达拉然那些失败的成果。"},sec={{t="维系不稳魔法的拐杖",b="大法师阿鲁高的魔法无法完全控制或维系他释放到银松森林的狼人。他将魔魂镣铐这样的附魔器具缚在这些野兽身上，以弥补这一缺陷。这些镣铐将外来的魔力导入月怒魔魂狼人体内，增强它们的力量，并巩固使它们受影牙城堡奴役的诅咒。"},{t="肯瑞托的审视",b="在瑟伯切尔，被遗忘者法师达拉尔·道恩维沃尔认为阿鲁高既危险又无能。他相信，阿鲁高的胡乱干预毁掉了肯瑞托抵御 天灾军团 的防线。被遗忘者研究者收集魔魂镣铐以及从月怒暴食者身上扯下的镣铐，再提取金属中残留的附魔。研究这些附魔揭示了阿鲁高施法技艺中的缺陷，也让被遗忘者获得了奥术方面的知识，以制定对策，抵御他造成的狼人灾祸。"}},faq={{q="什么是魔魂镣铐？",a="银松森林的月怒魔魂狼人狼人戴着被称为魔魂镣铐的附魔金属镣铐。大法师阿鲁高打造了这些镣铐，用来强化自己的法术，并将这些野兽束缚在他的控制之下。",al={"魔魂镣铐是什么","魔魂镣铐物品背景","这副镣铐是什么"}},{q="谁想要魔魂镣铐？",a="达拉尔·道恩维沃尔是银松森林瑟伯切尔的一名被遗忘者法师，他想要魔魂镣铐。他研究镣铐上的附魔，寻找解决阿鲁高引发的狼人之乱的办法。",al={"谁需要魔魂镣铐","谁收镣铐","达拉尔·道恩维沃尔任务"}},{q="这些镣铐从何而来？",a="月怒魔魂狼人戴着这些镣铐，它们是出没于银松森林北部和东部的凶暴狼人。",al={"谁掉落魔魂镣铐","魔魂镣铐怪物","哪里获得魔魂镣铐"}},{q="阿鲁高为什么给狼人戴上镣铐？",a="达拉尔·道恩维沃尔说，阿鲁高缺乏仅凭自身力量驾驭这些野兽的才能。阿鲁高依赖这些镣铐之类的附魔物品，来引导并维系将狼群聚在一起的不稳定魔法。",al={"狼人为什么戴镣铐","阿鲁高镣铐用途"}}},fp="16,207,28.323.0,18.453.1,27.193.0,28.177.0,34.107.0,42.219.0"}
P.entries["item:darnassus-marzipan"] = {n="达纳苏斯水果糖",s="万圣节期间，达纳苏斯的旅店老板会在访客跳舞后送上水果糖。这种糖果在暗夜精灵的主城制作，专为秋日庆典准备，是耶斯帕尔需要的四种糖果之一。",h="万圣节期间，达纳苏斯的旅店老板会在访客跳舞后送上水果糖。这种糖果在暗夜精灵的主城制作，专为秋日庆典准备，是耶斯帕尔需要的四种糖果之一。",kw={"糖果","达纳苏斯","达纳苏斯水果糖","万圣节","耶斯帕尔","水果糖","甜食"},ang={["faction:Alliance"]="身为联盟的旅人，你可以收集达纳苏斯、铁炉堡和暴风城的糖果。万圣节让散居各地的联盟各族一同欢庆。",["race:NightElf"]="身为一名kaldorei，你也可以参与秋日里轻松愉快的习俗。旅人若以一支欢快的舞蹈回应热情款待，达纳苏斯的旅店老板便会送上甜甜的水果糖。"},sec={{t="世界之树的滋味",b="万圣节期间，联盟各大主城都有欢乐的“不给糖就捣蛋”习俗。矮人提供清凉的薄荷糖，暴风城制作耐嚼的牛轧糖，达纳苏斯的旅店老板则准备精致的水果糖。应旅店老板的要求跳支舞，就能得到一块。\n\n耶斯帕尔需要收集四种地方糖果，这种甜食便是其中之一。他是暴风城教堂广场里一名生病的孤儿，无法亲自外出收集糖果。"}},faq={{q="达纳苏斯水果糖有什么用途？",a="万圣节期间，耶斯帕尔需要四种不同的糖果，达纳苏斯水果糖便是其中之一。他是暴风城教堂广场孤儿院里一名生病的孤儿。将它与铁炉堡、诺莫瑞根和暴风城的糖果一起带给他，就能获得一包节庆南瓜糖。",al={"达纳苏斯水果糖用途","水果糖有什么用"}},{q="如何获得达纳苏斯水果糖？",a="万圣节期间，达纳苏斯的旅店老板会请你跳一小段舞，随后送你水果糖。",al={"如何获得达纳苏斯水果糖","哪里能获得水果糖"}},{q="耶斯帕尔为什么不能亲自去拿水果糖？",a="耶斯帕尔生病了，无法外出参加“不给糖就捣蛋”的活动。他住在教堂广场的暴风城孤儿院，得靠冒险者帮他收集远方的糖果。",al={"耶斯帕尔为什么需要糖果","耶斯帕尔为什么不能外出"}}},fx={["06b4a124"]={q="达纳苏斯水果糖是什么？",a="达纳苏斯水果糖是在暗夜精灵的首都达纳苏斯制作的一种节庆糖果。这种杏仁膏糖会在秋季的万圣节期间分发给欢庆节日的人们，也是四种传统节日糖果之一，愿意表演节庆小把戏来讨糖的旅行者就能得到它。",al={"达纳苏斯水果糖是什么","达纳苏斯水果糖背景故事","达纳苏斯水果糖是哪种糖果"}},cf1db7fa={q="达纳苏斯水果糖来自哪里，由谁制作？",a="这种糖果源于泰达希尔枝干上的暗夜精灵首都达纳苏斯。在万圣节期间，城中的旅店老板会把这种甜食送给在酒馆里跳舞助兴的访客，共同庆祝联盟在卡利姆多和东部王国各地的情谊与欢乐。",al={"达纳苏斯水果糖来自哪里","谁制作达纳苏斯水果糖","达纳苏斯水果糖来源"}},["1983589f"]={q="为什么有人想要达纳苏斯水果糖？",a="它不仅是精灵的节日美食，也是那些无法亲自庆祝万圣节的人所渴望的东西。耶斯帕尔是暴风城教堂广场里一名患病的孤儿，他请求旅行者代他四处讨糖，好让他也能品尝来自联盟各地的甜食。",al={"为什么需要达纳苏斯水果糖","谁想要达纳苏斯水果糖","为什么收集达纳苏斯水果糖"}}},fp="18,175,25.396.0,36.271.0,37.102.0,42.169.0"}
P.entries["item:darthalia-s-sealed-commendation"] = {n="达萨利亚的奖状",s="在塔伦米尔，达萨利亚向幽暗城最高指挥部传报了对抗希尔斯布莱德人类的胜利。",h="在塔伦米尔，达萨利亚向幽暗城最高指挥部传报了对抗希尔斯布莱德人类的胜利。",kw={"奖状","达萨利亚","希尔斯布莱德","南海镇","塔伦米尔","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="对部落而言，这份奖状记录了在洛丹伦取得的一场战略胜利，也向幽暗城的领袖表明，南部丘陵的联盟要塞可以被摧毁。",["race:Undead"]="身为Undead，赢得达萨利亚的赞许，并将奖状送到王座厅，会提升你在黑暗女王日益壮大的军事体系中的地位。"},sec={{t="向最高指挥部报告",b="希尔斯布莱德丘陵各地的战斗结束后，高级执行官达萨利亚封好了一份战报，记载了击败希尔斯布莱德人类守军、摧毁其阵地的战果。她将战报寄给瓦里玛萨斯，这位恐惧魔王是希尔瓦娜斯·风行者女士的顾问。在皇家区，这份战报向被遗忘者领袖证明，洛丹伦以南的联盟据点可以被攻破，让北方驻军得以腾出手来对抗天灾军团。"}},faq={{q="达萨利亚的奖状是什么？",a="塔伦米尔的高级执行官达萨利亚写下了一份密封的奖状，表彰一名战士在希尔斯布莱德之战中对抗联盟的表现。这份奖状将送往幽暗城最高指挥部。",al={"密封的奖状","达萨利亚的信","希尔斯布莱德战报"}},{q="这份奖状由谁接收？",a="这份奖状的收件人是瓦里玛萨斯，他是希尔瓦娜斯·风行者女士的恐惧魔王顾问，身处幽暗城的皇家区。",al={"交给谁","交付奖状","谁接收达萨利亚的奖状"}},{q="瓦里玛萨斯为何关心希尔斯布莱德的战事？",a="被遗忘者在北方面对巫妖王及其麾下的天灾军团，而希尔斯布莱德的人类则扰乱他们的补给线，威胁南部边境的安全。瓦里玛萨斯看重那些能扫除这一障碍的胜利，让幽暗城的军队得以集中力量应对更大规模的战争。",al={"瓦里玛萨斯为何关心","希尔斯布莱德恐惧魔王","被遗忘者希尔斯布莱德战略"}}},fp="31,114,22.419.0,40.187.0,31.124.0,58.260.0"}
P.entries["item:deadmire-s-tooth"] = {n="死沼巨鳄的牙齿",s="在尘泥沼泽，死沼巨鳄潜伏在浑浊的水中，它的牙齿是一场光荣狩猎的见证。雷霆崖猎人高地的梅洛·石蹄收下这颗牙齿，以此证明这头古老鳄鱼的痛苦已经终结。",h="在尘泥沼泽，死沼巨鳄潜伏在浑浊的水中，它的牙齿是一场光荣狩猎的见证。雷霆崖猎人高地的梅洛·石蹄收下这颗牙齿，以此证明这头古老鳄鱼的痛苦已经终结。",kw={"鳄鱼","死沼巨鳄","尘泥","猎人高地","梅洛·石蹄","雷霆崖","牙齿"},ang={["class:Hunter"]="作为一名向猎人高地的导师学习的猎人，你会明白，狩猎除了追求战利品，也需要尊重与仁慈。",["race:Tauren"]="作为一名牛头人，你将对死沼巨鳄的狩猎视为Earth Mother平衡循环的一部分。年老的掠食者会被引向安宁，而非被留下受苦。"},sec={{t="仁慈的战利品",b="猎人高地的牛头人猎人将狩猎视为维系平衡、敬畏与仁慈的纽带。死沼巨鳄曾是尘泥沼泽最威武的鳄鱼之一。高龄让它的晚年饱受折磨，但它依然保有壮年时的凶猛斗志。庞大的骨架与日渐衰弱的身躯已成为囚禁它的痛苦牢笼。死沼巨鳄的牙齿向梅洛·石蹄证明，一场光荣的狩猎已经终结了这头野兽的痛苦。"}},faq={{q="死沼巨鳄的牙齿有什么用？",a="将这颗牙齿交给雷霆崖猎人高地的梅洛·石蹄。这能完成他交付的狩猎任务，并证明死沼巨鳄已经得到仁慈的解脱。",al={"死沼巨鳄的牙齿交给谁","谁要死沼巨鳄的牙齿","死沼巨鳄的牙齿怎么用"}},{q="死沼巨鳄的牙齿从哪里获得？",a="死沼巨鳄的牙齿来自死沼巨鳄，一头栖息在尘泥沼泽南部的巨大古老鳄鱼。它在塔贝萨的农场以东的水域游荡。",al={"哪里获得死沼巨鳄的牙齿","谁掉落死沼巨鳄的牙齿","死沼巨鳄位置"}},{q="梅洛·石蹄为什么要杀死死沼巨鳄？",a="在梅洛·石蹄眼中，死沼巨鳄是一头高贵的生灵，年老的它正忍受着可怕的痛苦。这场狩猎是一种仁慈，让这头鳄鱼的生命之火安然熄灭，而非任由它在折磨中日渐衰亡。",al={"为什么杀死死沼巨鳄","梅洛·石蹄的理由","死沼巨鳄邪恶吗"}}},fp="16,199,17.401.0,34.162.0,38.141.0,46.198.0"}
P.entries["item:death-cap"] = {n="毒帽蘑菇",s="在黑海岸，毒帽蘑菇生长在峭壁之泉后方的洞穴中。暗夜精灵草药师寻觅着这种稀有的真菌，但古树之林警告人们不要靠近瀑布。",h="在黑海岸，毒帽蘑菇生长在峭壁之泉后方的洞穴中。暗夜精灵草药师寻觅着这种稀有的真菌，但古树之林警告人们不要靠近瀑布。",kw={"奥伯丁","巴瑞萨斯·月影","洞穴蘑菇","峭壁之泉","黑海岸","毒帽蘑菇","古树之林","粗柄蘑菇"},ang={["profession:Herbalism"]="为巴瑞萨斯采集毒帽蘑菇不需要特殊的镰刀，但草药师都知道，在潮湿且遭到腐化的洞穴中寻找稀有真菌有多危险。",["race:NightElf"]="身为暗夜精灵，你可以把毒帽蘑菇带给奥伯丁的巴瑞萨斯，同时谨记古树之林的警告。"},sec={{t="暗处的毒菌",b="毒帽蘑菇生长在峭壁之泉后方潮湿的洞穴中，那里紧邻黑海岸东北部的山脊。粗柄蘑菇铺满洞穴地面，毒帽蘑菇却十分稀少。巴瑞萨斯·月影等暗夜精灵草药师珍视这种蘑菇，用它试制药剂。哪怕只想找到一株，也得进入古树之林警告人们远离的洞穴，腐化正在那里生根。"},{t="壁泉的凶兆",b="古树之林的守护者警告当地的卡多雷远离峭壁之泉。他们察觉到一股邪恶的力量正在黑暗中生根。任何进入洞穴采集毒帽蘑菇的人，都必须面对盘踞在这处潮湿洞穴中的势力。"}},faq={{q="在哪里能找到毒帽蘑菇？",a="毒帽蘑菇生长在峭壁之泉后方隐蔽的洞穴中，那里紧靠黑海岸东北部的山壁。",al={"毒帽蘑菇位置","毒帽蘑菇在哪里","壁泉洞穴蘑菇"}},{q="谁需要这种蘑菇？",a="巴瑞萨斯·月影是海滨村落奥伯丁的一位炼金师，他正在寻找毒帽蘑菇，用来调制一种特殊药剂。",al={"谁需要毒帽蘑菇","巴瑞萨斯蘑菇任务"}},{q="巴瑞萨斯·月影为什么不亲自采集？",a="古树之林的守护者察觉到邪恶正在侵入峭壁之泉后方的洞穴，因此警告巴瑞萨斯不要靠近那里。",al={"为什么不亲自采集","巴瑞萨斯的警告"}},{q="毒帽蘑菇和粗柄蘑菇有什么区别？",a="粗柄蘑菇遍布壁泉洞穴的地面，毒帽蘑菇却十分稀少，更难找到。",al={"毒帽蘑菇与粗柄蘑菇","蘑菇之间的区别"}}},fp="9,179,25.367.0,19.265.1,29.111.0,24.113.0,50.140.0,50.115.0"}
P.entries["item:deathstalker-report"] = {n="亡灵哨兵的报告",s="亡灵哨兵兰妮·尤瑞克向高级执行官哈德瑞克报告了 天灾军团 在银松森林的抵抗情况。",h="亡灵哨兵兰妮·尤瑞克向高级执行官哈德瑞克报告了 天灾军团 在银松森林的抵抗情况。",kw={"亡灵哨兵的报告","哈德瑞克","奎因","兰妮·尤瑞克","天灾军团","瑟伯切尔","银松森林"},ang={["class:Rogue"]="身为潜行者，你能看出亡灵哨兵的秘密侦察如何帮助被遗忘者军队维持运作。",["race:Undead"]="身为亡灵，你深知亡灵哨兵沿洛丹伦边境为 Sylvanas 收集情报时面临的危险。"},sec={{t="前线情报",b="亡灵哨兵兰妮·尤瑞克和奎恩·尤瑞克在银松森林北部遭遇了一场致命的伏击。他们被 天灾军团 困在松林中，匆忙将收集到的情报写成了一封急报。报告指出，被遗忘者在试图占领这片地区时，遭遇了比预期更强的抵抗。奎因身受重伤，因此兰妮将报告托付给了路过的盟友，他们必须立即将报告送到瑟伯切尔的高级执行官哈德瑞克手中。"}},faq={{q="亡灵哨兵的报告是什么？",a="这份报告记录了 天灾军团 的活动，以及被遗忘者斥候在银松森林遭遇的危险与阻碍。",al={"这是什么报告","亡灵哨兵的报告背景故事","亡灵哨兵的报告是什么"}},{q="报告是谁写的？",a="与 天灾军团 交战后，亡灵哨兵兰妮·尤瑞克照料了受伤的兄弟亡灵哨兵奎恩，随后写下了这份报告。",al={"亡灵哨兵的报告是谁写的","报告作者","谁写的"}},{q="报告要交给谁？",a="这份报告是写给瑟伯切尔的高级执行官哈德瑞克的，他在那里指挥银松森林的被遗忘者部队。",al={"报告送往哪里","报告交给谁","哈德瑞克 报告"}},{q="为什么急需这份报告？",a="哈德瑞克低估了银松森林中 天灾军团 的势力。这份报告描述了这些敌对部队的情况，为他提供情报，以保障被遗忘者占领这片地区的行动。",al={"为什么重要","哈德瑞克 为什么需要报告","里面有什么情报"}}},fp="19,104,22.444.0,32.107.0,21.143.0,31.121.0,37.186.0"}
P.entries["item:deepfury-s-orders"] = {n="深怒的命令",s="在萨多尔大桥下，深怒的命令与死去的老伊本瑟躺在一起。皱巴巴的羊皮纸上写着阴狠的指令，出自伏击这名侦察守卫的黑铁矮人之手。",h="在萨多尔大桥下，深怒的命令与死去的老伊本瑟躺在一起。皱巴巴的羊皮纸上写着阴狠的指令，出自伏击这名侦察守卫的黑铁矮人之手。",kw={"黑铁","深怒","命令","拉格·加玛森","伊本瑟","萨多尔大桥","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你看到截获的命令揭露了一场破坏图谋，目标是连接丹莫罗、湿地与联盟北方前哨的主要陆路命脉。",["race:Dwarf"]="身为矮人，你知道，在萨多尔大桥下发现黑铁的阴谋，深深刺痛了铁炉堡。这座大桥是你们王国最伟大的工程成就之一，也是通往北方的重要贸易通道。"},sec={{t="桥下的紧握之手",b="矮人桥梁守卫老伊本瑟在侦察萨多尔大桥的桥基时，被黑铁矮人围困并杀害。他紧握的拳头旁，躺着他们的首领深怒拟定的命令，纸张已被揉皱。这张羊皮纸直接证明，有人正密谋协同行动，对付这座连接湿地与阿拉希高地的大桥。"},{t="揭露威胁",b="命令送到拉格·加玛森手中后，证实了大桥守军最担忧的猜测。黑铁矮人已经计划在萨多尔大桥的石砌结构正下方展开行动。拉格请求铁炉堡和暴风城火速派出援军。"}},faq={{q="深怒的命令是什么？",a="深怒的命令是属于黑铁指挥官深怒的书面军令。这些命令是在萨多尔大桥下老伊本瑟的尸体旁发现的。",al={"深怒的命令","这些命令是什么","深怒羊皮纸"}},{q="命令在哪里发现？",a="这张皱巴巴的羊皮纸是在湿地北部萨多尔大桥下洞穴般的支撑结构中，老伊本瑟紧握的拳头旁发现的。",al={"命令在哪里","伊本瑟位置","寻找深怒的命令"}},{q="老伊本瑟是谁？",a="老伊本瑟是驻守萨多尔大桥的矮人斥候。他前去调查桥梁支撑结构周围的异常活动，遭到了黑铁矮人的伏击。",al={"伊本瑟是谁","老伊本瑟背景故事"}},{q="深怒的命令交给谁？",a="深怒的命令被送到拉格·加玛森手中，这位矮人指挥官正坚守在萨多尔大桥附近的丹莫德。他阅读这些命令，以评估黑铁的威胁。",al={"命令交给谁","拉格·加玛森"}}},fx={["21094d89"]={q="深怒的命令来自哪里？",a="这些书面命令源自黑铁氏族，以负责在萨多尔大桥周边策划敌对行动的行动人员或首领深怒命名。伏击并杀害山地猎人老锈锁的黑铁矮人曾携带这些命令；它们被遗落在他倒下的尸体旁的泥土中。",al={"谁写了深怒的命令","深怒的命令来源","谁制作了深怒的命令"}},ac08f373={q="拉格·加玛森为什么想要深怒的命令？",a="拉格·加玛森需要确凿证据，弄清失踪斥候老锈锁的遭遇。这份羊皮纸残酷地证实了这位山地猎人的死讯，也揭露了黑铁矮人在桥附近正在策划的敌对阴谋。",al={"为什么要把深怒的命令交给拉格","为什么有人想要深怒的命令","拉格·加玛森的命令"}}},fp="17,165,24.310.0,21.239.1,27.158.0,27.140.0,22.170.0,31.161.0"}
P.entries["item:deepmoss-egg"] = {n="深苔蜘蛛的卵",s="在石爪山脉，深苔蜘蛛的卵吸引着来自棘齿城的地精商人。深苔蜘蛛在峭壁和峡谷间成窝产卵，藏宝海湾的海盗则将这些卵视为制作煎蛋卷的上好食材。",h="在石爪山脉，深苔蜘蛛的卵吸引着来自棘齿城的地精商人。深苔蜘蛛在峭壁和峡谷间成窝产卵，藏宝海湾的海盗则将这些卵视为制作煎蛋卷的上好食材。",kw={"藏宝海湾","深苔蜘蛛的卵","深苔蜘蛛","麦伯克·米希瑞克斯","棘齿城","希塞尔山谷","石爪山","狂风峭壁"},ang={["profession:Cooking"]="身为厨师，你或许会犹豫是否要用蜘蛛卵做菜，但藏宝海湾的食客却将打散的蜘蛛卵视为值得尝试的珍馐，甘愿为此付出地精开出的价钱。"},sec={{t="峭壁间的珍馐",b="深苔蜘蛛在石爪山脉各处筑巢，尤其集中在希塞尔山谷和狂风峭壁残存的树木下。它们将一窝窝能够孵化的卵留在厚实的蛛丝囊中，由潮湿的山苔遮护。大多数旅人用不上这些卵，地精商人却从中看到了获利的机会。"},{t="藏宝海湾的美食风潮",b="藏宝海湾如今流行吃蜘蛛卵煎蛋卷，这股古怪的美食风潮在富裕的海盗和勇于尝鲜的食客间颇为盛行。当地的供应无法满足他们的胃口，于是棘齿城的麦伯克·米希瑞克斯便通过码头管理员迪兹维格安排运输。采集者冒险深入石爪山的剧毒蛛群，收集新鲜的卵，这些卵随后便成了值钱的货物。"}},faq={{q="哪里能找到深苔蜘蛛的卵？",a="深苔蜘蛛的卵分布在贫瘠之地西北方的石爪山脉。狂风峭壁残存的树木下，以及希塞尔山谷深处的剧毒蜘蛛巢穴中，都有成窝的卵。",al={"卵的位置","哪里能找到深苔蜘蛛的卵","深苔蜘蛛的卵位置"}},{q="谁想收集这些卵？",a="棘齿城的地精商人麦伯克·米希瑞克斯雇人收集深苔蜘蛛的卵。他安排码头管理员迪兹维格将这些卵运过大海。",al={"谁需要深苔蜘蛛的卵","谁收购深苔蜘蛛的卵","麦伯克·米希瑞克斯任务"}},{q="这些卵究竟有什么用途？",a="这些卵会被送往藏宝海湾，那里正流行吃蜘蛛卵煎蛋卷，海盗和其他食客都很追捧这道古怪的美食。",al={"蜘蛛卵用途","为什么收集蜘蛛卵","蜘蛛卵煎蛋卷"}},{q="为什么采集这些卵时会收到有关希塞尔山谷的警告？",a="希塞尔山谷是蜘蛛的繁殖地，里面到处都是成年蜘蛛、蛛网和被啃食的猎物。麦伯克建议容易反胃的人改去狂风峭壁稀疏的树木下采卵。",al={"希塞尔山谷警告","容易反胃 希塞尔"}}},fp="12,192,23.325.0,24.333.0,30.190.0,32.161.0,36.123.0,54.177.0"}
P.entries["item:defias-docket"] = {n="迪菲亚记事本",s="迪菲亚特工将命令藏在暮色森林西部的腐草农场。这份记事本为暴风城寻找失踪使者提供了线索，指向迪菲亚潜行者的计划。",h="迪菲亚特工将命令藏在暮色森林西部的腐草农场。这份记事本为暴风城寻找失踪使者提供了线索，指向迪菲亚潜行者的计划。",kw={"腐草农场","迪菲亚记事本","迪菲亚保险箱","暮色森林","埃林·提亚斯","失踪的使节","守夜人巴库斯"},ang={["class:Rogue"]="身为潜行者，你能看出迪菲亚潜行者如何在普通匪徒的表象之下，运用密码和隐秘的后勤调度。",["faction:Alliance"]="身为联盟的一员，你能看出这些文件揭露了一场有组织的迪菲亚阴谋，远非寻常匪患可比。"},sec={{t="通往黑暗的线索",b="埃林·提亚斯大师指引调查者前往暮色森林，追查王国失踪外交官的下落。守夜人巴库斯追踪到迪菲亚成员的异常动向，发现他们正向腐草农场集结，那座荒废的农场位于西部荒野通来的道路南侧。那里的一个保险箱中存放着迪菲亚记事本。其中的记录勾勒出迪菲亚潜行者的动向，表明他们的活动远不止拦路抢劫和在当地为匪作乱。"},{t="阴谋之网",b="这些文件内容错综复杂，牵涉危险的政治阴谋，因此守夜人巴库斯拒绝保管。他担心上级发现他经手这份记事本后，会严惩他。文件被送回暴风城的提亚斯奶酪坊后，揭露了一场精心策划的绑架阴谋，背后有迪菲亚的大量资源支持。文件还列出了地下势力成员的名字，其中一人的代号是“拳头”。"}},faq={{q="迪菲亚记事本是什么？",a="迪菲亚记事本是一捆属于迪菲亚潜行者的正式命令和文件。其中详细记载了他们在暮色森林和西部荒野一带的计划与秘密行动。",al={"记事本是什么","迪菲亚文件","失踪外交官记事本"}},{q="在哪里可以找到迪菲亚记事本？",a="记事本锁在腐草农场破败农舍内的一个迪菲亚保险箱中，位于从西部荒野通往暮色森林西部的道路南侧。",al={"记事本位置","哪里能找到迪菲亚记事本","腐草农场记事本"}},{q="为什么记事本存放在暮色森林？",a="迪菲亚特工将腐草农场用作西部荒野与暮色森林之间的一处偏僻集结点。他们在此协调一项高度优先的行动，避开暴风城的主要巡逻队。",al={"为什么在暮色森林","腐草农场的迪菲亚"}},{q="谁负责分析记事本？",a="守夜人巴库斯简短查看了记事本，随后将它送给暴风城的埃林·提亚斯。提亚斯的私人情报网专门破译地下势力的秘密通信。",al={"记事本交给谁","谁查看记事本"}}},fx={b7a864a3={q="迪菲亚记事本来自哪里，由谁编写？",a="这份记事本是由迪菲亚潜行者亲自起草的一套正式文件。它用于概述他们的秘密计划，并协调各地的密探。行动人员将文件妥善藏在腐草农场的一只保险箱里，那是一处越过暮色森林边界不远的僻静农场，在你发现文件之前，组织成员曾在那里聚集。",al={"迪菲亚记事本是谁写的","迪菲亚记事本来源","记事本来自哪里"}},["4693de43"]={q="为什么有人想要迪菲亚记事本？",a="调查那位失踪外交官的人需要这场阴谋的确凿证据。守夜人巴库斯看出，记事本的内容太过周密，绝非简单的诱饵，而暴风城的埃林·提亚斯则利用其中的内容揭开该组织秘密计划的面纱，包括找出提及“拳头”等关键人物的线索。",al={"记事本为什么重要","为什么需要迪菲亚记事本","谁想要迪菲亚记事本"}}},fp="13,170,21.409.0,21.377.1,26.174.0,33.150.0,36.181.0,24.189.0"}
P.entries["item:defias-tower-key"] = {n="迪菲亚塔楼钥匙",s="在西部荒野，迪菲亚塔楼钥匙是悄然绕过克拉文之塔哨兵的凭证。暴风城的密探需要它，证明潜入者未被察觉。",h="在西部荒野，迪菲亚塔楼钥匙是悄然绕过克拉文之塔哨兵的凭证。暴风城的密探需要它，证明潜入者未被察觉。",kw={"密探吉尔妮","迪菲亚塔楼钥匙","暮色森林的箱子","克拉文·摩特维克","克拉文之塔","畸形的迪菲亚爪牙","马迪亚斯·肖尔","si:7"},ang={["class:Rogue"]="作为与SI:7合作的盗贼，你要通过潜行和偷窃取得迪菲亚塔楼钥匙。别忘了致命毒药。",["faction:Alliance"]="作为联盟的一员，你要协助暴风城调查迪菲亚潜行者从暮色森林运来的奇怪货物。从克拉文之塔取得情报。"},sec={{t="畸形守卫身上的战利品",b="克拉文之塔是迪菲亚潜行者在西部荒野海岸的一处据点。最近从暮色森林运来的货物中，有一批畸形的迪菲亚爪牙，被派来守卫这里。这些爪牙是亡灵，浑身布满尖刺。\n\nSI:7的监视者指示外勤密探偷窃哨兵身上的物品，而非与之交战。这样，突破塔楼防线时就不会触发警报。"},{t="追查暮色森林的关联",b="钥匙指向克拉文之塔内的一只箱子，它与暮色森林运来的货物有关。箱中放着克拉文·摩特维克的日记。暴风城的马迪亚斯·肖尔收到日记后，从中发现了一场远超寻常拦路抢劫的阴谋。\n\n迪菲亚与荆棘谷地精联手，贩运流亡者赞吉尔发现的特殊巨魔毒药。这些药剂能让死者复生，解释了塔楼周围那些形貌骇人、不断咳嗽的怪物从何而来。"}},faq={{q="如何获得迪菲亚塔楼钥匙？",a="对西部荒野克拉文之塔周围的一名畸形迪菲亚爪牙使用偷窃。击败敌人后无法取得钥匙。",al={"哪里获得钥匙","如何获得迪菲亚塔楼钥匙","谁掉落迪菲亚塔楼钥匙"}},{q="迪菲亚塔楼钥匙能打开什么？",a="这把钥匙既不能打开塔楼的大门，也不能打开里面的暮色森林的箱子。马迪亚斯·肖尔需要它，作为密探未被察觉便穿过警戒线的证明。",al={"能打开暮色森林的箱子吗","这把钥匙开什么门","迪菲亚钥匙能打开什么"}},{q="守卫塔楼的畸形迪菲亚爪牙是什么？",a="畸形的迪菲亚爪牙是克拉文之塔周围形貌骇人、浑身带刺的亡灵守卫。密探吉尔妮不知道它们是如何形成的，因此要求密探调查它们守护的货物。",al={"钥匙在谁身上","塔楼守卫是什么","带刺的僵尸是什么"}},{q="谁派遣密探去取得这把钥匙？",a="密探吉尔妮是一名监视克拉文之塔外围的SI:7斥候，她指示外勤盗贼取得钥匙，并取回暮色森林的箱子里的东西，交给暴风城的马迪亚斯·肖尔。",al={"谁提供任务","谁需要钥匙"}}},fx={a3164c95={q="迪菲亚塔楼钥匙是什么？",a="这是一把铁钥匙，由西部荒野克拉文之塔周围那些形貌怪异的守卫携带。SI:7特工密探吉尔妮发现，守卫那里的尖刺亡灵怪物持有这把钥匙，并认定它是迪菲亚潜行者在这处防御工事中从事秘密活动的重要证据。",al={"迪菲亚塔楼钥匙","迪菲亚塔楼钥匙是什么","迪菲亚钥匙"}},["2bb6b303"]={q="SI:7为什么想要迪菲亚塔楼钥匙？",a="马迪亚斯·肖尔和密探吉尔妮要求盗贼特工在潜入塔楼、调查从暮色森林运来的神秘货物时取得钥匙。带回它，就证明你成功突破了外围防线，并取回了锁在克拉文·摩特维克据点中的险恶秘密。",al={"为什么获取迪菲亚塔楼钥匙","谁想要迪菲亚塔楼钥匙","为什么取回迪菲亚钥匙"}}},fp="16,164,30.348.0,34.455.1,39.129.0,36.156.0,56.189.1,42.182.0"}
P.entries["item:deliah-s-ring"] = {n="黛丽娅的戒指",s="一条阴森的线索始于黛丽娅的戒指，它是在银松森林的腐皮豺狼人尸堆中发现的。戒指上刻着“献给黛丽娅”，指向一名从提瑞斯法乱葬坑中被盗走的瘟疫死者。",h="一条阴森的线索始于黛丽娅的戒指，它是在银松森林的腐皮豺狼人尸堆中发现的。戒指上刻着“献给黛丽娅”，指向一名从提瑞斯法乱葬坑中被盗走的瘟疫死者。",kw={"布瑞尔","黛丽娅","黛丽娅的戒指","刻字的戒指","芬里斯岛","哈德瑞克","执政官塞弗伦","腐皮豺狼人"},ang={["race:Undead"]="身为亡灵，你知道凡人的情感羁绊也会随着血肉一同消逝。只有极少数仍然铭记着生前所爱之人。"},sec={{t="泥沼中的信物",b="在银松森林的豺狼人尸堆中，一枚戒指戴在一具尚未完全腐烂的尸体手上，那只手布满了痘疮。指环上刻着一句简单的话：“献给黛丽娅。”腐皮豺狼人所做的远不止搜刮战场。它们洗劫提瑞斯法林地的乱葬坑，将人类和被遗忘者的尸体运往南方的芬里斯岛，另有图谋。"},{t="与布瑞尔的牵连",b="高级执行官哈德瑞克将戒指送往布瑞尔，那里的执政官塞弗伦保管着近期死者的记录。塞弗伦证实，黛丽娅生前住在布瑞尔，死于瘟疫。她下葬后，盗尸者又挖出了她的遗体。这枚戒指牵出了她身后亲友的悲痛，也引出了一个疑问：凡人的挚爱能否在亡灵之身中延续。"}},faq={{q="黛丽娅的戒指在哪里找到？",a="这枚戒指位于银松森林北部的腐皮豺狼人尸堆中，戴在一名没有裹尸布的瘟疫死者手上，周围都是搜罗来的尸体。",al={"黛丽娅的戒指在哪里","黛丽娅的戒指位置","如何获得黛丽娅的戒指"}},{q="黛丽娅是谁？",a="黛丽娅生前住在布瑞尔，死于瘟疫。她被埋在当地的乱葬坑中，后来腐皮豺狼人盗走了她的尸体，将其拖进银松森林。",al={"黛丽娅是谁","黛丽娅的故事","布瑞尔的黛丽娅"}},{q="腐皮豺狼人为什么会有她的尸体？",a="效忠天灾军团的腐皮豺狼人洗劫了提瑞斯法林地的公共墓地。它们囤积尸体，并将尸体运往芬里斯岛上的据点。",al={"豺狼人为什么盗尸","腐皮盗尸","豺狼人用尸体做什么"}},{q="戒指上刻着什么？",a="戒指内侧刻着“献给黛丽娅”。这是她生前由恋人或丈夫赠送的私人礼物。",al={"戒指铭文","戒指上写着什么","献给黛丽娅的戒指"}}},fp="13,167,22.333.0,13.355.1,29.167.0,15.162.0,42.178.0,36.109.0"}
P.entries["item:delivery-to-mathias"] = {n="给马迪亚斯的密信",s="科瑞恩·塞尔留斯从闪金镇寄出一个密封包裹，交给暴风城的马迪亚斯·肖尔。这次递送让一名颇有潜力的潜行者首次接触到SI:7的内部运作。",h="科瑞恩·塞尔留斯从闪金镇寄出一个密封包裹，交给暴风城的马迪亚斯·肖尔。这次递送让一名颇有潜力的潜行者首次接触到SI:7的内部运作。",kw={"给马迪亚斯的密信","闪金镇","科瑞恩·塞尔留斯","马迪亚斯·肖尔","旧城区","包裹","si:7","暴风城"},ang={["class:Rogue"]="身为潜行者，你携带的这个包裹，标志着你从后巷里的小打小闹，迈入马迪亚斯·肖尔麾下的王室情报工作。",["faction:Alliance"]="身为联盟特工，你在各地斥候与都城之间递送秘密公文。你的工作帮助暴风城隐秘的谍报机构对抗内部颠覆活动。"},sec={{t="信使的考验",b="一个包裹必须从狮王之傲旅店送到暴风城兵营。对年轻的潜行者来说，这趟旅程是暴风城的情报机构的一次考验。科瑞恩·塞尔留斯将包裹托付给初出茅庐的扒手，让他们首次面见马迪亚斯·肖尔。他们必须悄然穿过都城，保持低调，并遵照秘密指令行事，不得多问。"},{t="通往SI:7之门",b="这次交接将一名特工带到旧城区的SI:7总部。马迪亚斯·肖尔利用这些递送任务，分辨谁是滥竽充数之辈，谁才是真正的人才。那些顺利呈交包裹的人会接到外勤任务。最初的任务是针对艾尔文森林的迪菲亚走私网络展开秘密侦察和渗透。"}},faq={{q="给马迪亚斯的密信里装着什么？",a="信使无权拆开包裹。里面可能装着情报报告、学员评估，或是关于艾尔文的迪菲亚潜行者等当地威胁的机密材料。",al={"包裹里有什么","递送物品内容","包裹内容"}},{q="这件包裹是谁寄出的？",a="科瑞恩·塞尔留斯交出了这件包裹。她是一名潜行者特工兼训练师，就在闪金镇的狮王之傲旅店楼上。",al={"谁给的包裹","包裹寄件人","科瑞恩·塞尔留斯的包裹"}},{q="马迪亚斯·肖尔的总部在哪里？",a="马迪亚斯·肖尔将总部设在SI:7大楼的二楼。这座大楼位于暴风城兵营院区内，坐落在旧城区的东南角。",al={"马迪亚斯·肖尔在哪里","包裹送到哪里","肖尔的位置"}},{q="将包裹呈交给肖尔之后会发生什么？",a="肖尔确认你的能力后，会让你开始执行外勤谍报任务，并派你潜入杰罗德码头。在那里，你要从一名迪菲亚码头管理员手中偷取一份船运时刻表。",al={"递送后的下一个任务","肖尔做什么","给马迪亚斯的密信之后"}}},fx={["1dd6c783"]={q="给马迪亚斯的密信是什么？",a="这是驻守闪金镇的盗贼训练师科瑞恩·塞尔留斯托付给你的一个密封包裹。表面上，这只是一趟跑腿的差事，实际上主要是为了引荐你去见暴风城SI:7总部的马迪亚斯·肖尔，并考验你的能力。",al={"给马迪亚斯的密信是什么","给马迪亚斯的密信包裹","科瑞恩·塞尔留斯的包裹"}},["2bd7511f"]={q="马迪亚斯·肖尔为什么需要这份货物？",a="马迪亚斯·肖尔领导着暴风城的情报组织SI:7，科瑞恩·塞尔留斯负责为他转交任务，并物色有潜力的新成员。将包裹安全送到旧城区，便能证明你有能力遵照秘密指令，为王室的间谍首领执行机密任务。",al={"肖尔为何需要货物","为何给马迪亚斯送包裹","马迪亚斯为何需要这个"}}},fp="19,164,16.356.0,15.314.0,39.184.0,24.122.0,46.164.0,49.182.1"}
P.entries["item:deviate-hide"] = {n="变异皮革",s="变异皮革是从栖息在哀嚎洞穴中的野兽身上剥下的变异兽皮。这些异乎寻常的毛皮受到德鲁伊纳拉雷克斯的梦境腐化而扭曲，一些德鲁伊正在收集它们，希望将噩梦污染之物制成耐用的皮具。",h="变异皮革是从栖息在哀嚎洞穴中的野兽身上剥下的变异兽皮。这些异乎寻常的毛皮受到德鲁伊纳拉雷克斯的梦境腐化而扭曲，一些德鲁伊正在收集它们，希望将噩梦污染之物制成耐用的皮具。",kw={"贫瘠之地","变异皮革","皮革","纳尔帕克","纳拉雷克斯","噩梦","毛皮","哀嚎洞穴"},ang={["class:Druid"]="对德鲁伊而言，收集变异皮革意味着直面 Emerald Nightmare 腐化自然的可怕力量，不过纳尔帕克这样的弟子仍试图净化受腐化的材料，将其用于维持生存。"},sec={{t="噩梦污染的毛皮",b="暗夜精灵德鲁伊纳拉雷克斯在贫瘠之地下方陷入沉睡后，他的梦境化作了 翡翠梦魇，扭曲了当地洞穴的生态。潜伏在深处的野兽变成了违背自然的变异掠食者，长出了坚韧的变异兽皮。这些毛皮虽然沾染了邪恶，却有着非同寻常的柔韧性，格外适合用于制皮。纳尔帕克栖身于洞口上方高处的骷髅状岩石中，收集这些兽皮，研究它们的特性，并将其制成结实实用的背包。"}},faq={{q="变异皮革与普通皮革有何不同？",a="变异皮革取自受到 翡翠梦魇 扭曲的生物，这场噩梦从纳拉雷克斯的沉睡中渗出。这种腐化改变了它们的血肉，赋予它们异乎寻常的耐久性和弹性，是普通兽皮所不具备的。",al={"变异皮革背景故事","变异皮革为何奇异","变异毛皮特性"}},{q="谁在收集这些兽皮？",a="纳尔帕克是纳拉雷克斯的弟子，他在哀嚎洞穴入口上方的眼窝洞穴中扎营，正在寻找这些毛皮。他相信，尽管变异野兽本性邪恶，它们身上的材料仍能得到净化，制成实用的皮具。",al={"谁想要变异皮革","纳尔帕克兽皮","谁需要变异皮革"}},{q="哪里可以找到变异皮革？",a="它们取自游荡在贫瘠之地下方哀嚎洞穴中的各种变异野兽，包括迅猛龙、毒蛇、鳄鱼和恐牙兽。",al={"变异皮革掉落地点","变异皮革获取方法"}}},fx={["8b5833f5"]={q="变异皮革来自哪里？是谁制造的？",a="变异皮革取自哀嚎洞穴深处游荡的奇异畸变野兽。这些生物并非出自凡人之手，而是在贫瘠之地地下诞生；德鲁伊纳拉雷克斯陷入沉睡时，被吞噬他的邪恶梦魇所改变。异常的腐化扭曲了当地野生生物，使它们的皮毛也带上奇异而超凡的特质。",al={"变异皮革来自哪里","变异皮革的来源","谁制造了变异皮革"}}},fp="12,126,30.446.0,56.173.0,30.208.0,30.142.0"}
P.entries["item:devlin-s-remains"] = {n="代弗林的遗骸",s="在阿加曼德磨坊附近，代弗林·阿加曼德的骸骨承载着一段苦涩的往事。他是拥有磨坊的富裕家族的幼子，沦为天灾军团麾下毫无心智的奴仆，在故居废墟旁的道路上游荡。一名旅人将他击倒，把他的遗骸带给了布瑞尔一名渴望复仇的幸存者。",h="在阿加曼德磨坊附近，代弗林·阿加曼德的骸骨承载着一段苦涩的往事。他是拥有磨坊的富裕家族的幼子，沦为天灾军团麾下毫无心智的奴仆，在故居废墟旁的道路上游荡。一名旅人将他击倒，把他的遗骸带给了布瑞尔一名渴望复仇的幸存者。",kw={"阿加曼德磨坊","布瑞尔","库勒曼·法席恩","代弗林·阿加曼德","代弗林的遗骸","闹鬼的磨坊","提瑞斯法林地"},ang={["race:Undead"]="在被遗忘者眼中，阿加曼德一族代表着洛丹伦昔日享有特权的贵族。这个家族的失职让平民丧命，又化为怪物复生，因此亵渎代弗林的遗骸是一场阶级复仇。"},sec={{t="苦涩的遗产",b="代弗林·阿加曼德生前一直活在兄长萨尔曼的阴影下。萨尔曼性情温和，身材高大，代弗林却体弱而尖酸刻薄。当亡灵瘟疫席卷提瑞斯法林地北部时，阿加曼德家族未能保护自己的土地和劳工。代弗林是最早倒下的人之一。天灾军团将他复生为饥肠辘辘的食尸鬼，他疯狂的喋喋声回荡在通往阿加曼德磨坊的路旁。"},{t="壁炉架上的复仇",b="库勒曼·法席恩住在布瑞尔，对阿加曼德一族怀有深深的怨恨。他责怪这个家族在瘟疫降临时未能保护自己的家人。法席恩派旅人去让代弗林安息，并收集他的遗骸。他想把代弗林的骸骨摆在壁炉架上，细细品味昔日的主人如何沦为他脚下的尘土与碎骨。"}},faq={{q="代弗林·阿加曼德生前是什么人？",a="代弗林是富裕的阿加曼德家族的幼子，这个家族拥有提瑞斯法林地北部的阿加曼德磨坊。他的兄长萨尔曼性情温和，肩膀宽阔，与体弱多病、脾气暴躁又尖酸刻薄的代弗林形成了鲜明对比。",al={"代弗林是谁","代弗林·阿加曼德的身世","关于代弗林"}},{q="代弗林的遗骸是从哪里收集的？",a="代弗林的遗骸取自他受天灾军团控制的尸体，地点在阿加曼德磨坊以南，穿过提瑞斯法林地的道路旁。",al={"代弗林在哪里","哪里能找到代弗林","代弗林·阿加曼德的位置"}},{q="库勒曼·法席恩为什么想要这些骸骨？",a="库勒曼·法席恩憎恨阿加曼德家族，认为他们在瘟疫期间抛弃了他和他的亲人。他想把代弗林的骸骨摆在布瑞尔家中的壁炉架上，作为复仇的战利品，从中获得满足。",al={"法席恩为何想要遗骸","库勒曼·法席恩的动机","为何收集阿加曼德的骸骨"}},{q="代弗林是被遗忘者的一员吗？",a="不是。瘟疫夺走了代弗林的心智，天灾军团将他变成了毫无心智的食尸鬼。他在磨坊附近游荡，疯言疯语，直到被消灭。",al={"代弗林是被遗忘者吗","代弗林曾属于天灾军团吗"}}},fp="16,280,15.406.0,23.358.0,31.253.0,42.121.0,43.209.0,31.146.0"}
P.entries["item:dirt-caked-pendant"] = {n="沾满泥土的坠饰",s="在贫瘠之地，一名被俘的兽人交出了随身携带的沾满泥土的坠饰。这件信物被送到奥格瑞玛的甘鲁尔·血眼手中，用来召唤魅魔。",h="在贫瘠之地，一名被俘的兽人交出了随身携带的沾满泥土的坠饰。这件信物被送到奥格瑞玛的甘鲁尔·血眼手中，用来召唤魅魔。",kw={"噬魂者","沾满泥土的坠饰","多格兰","甘鲁尔·血眼","爱的礼物","魅魔","赞卡沙"},ang={["class:Warlock"]="身为一名正在学习的术士，你会看到凡人的悲伤与痴情如何帮助驾驭来自扭曲虚空的恶魔。",["race:Orc"]="身为兽人，你会看到多格兰苦乐交织的抉择：他不愿以伤残之身拖累氏族与伴侣，便舍弃信物，去完成一名战士最后的战斗。"},sec={{t="悲情信物",b="多格兰在贫瘠之地被囚禁期间，交出了沾满泥土的坠饰。他身中剧毒，伤残已无法治愈，不愿回到伴侣赞卡沙身边，成为她的负担。他选择与俘虏他的人战斗，直至死去。坠饰承载着他对她未曾言明的爱。一名术士将这件信物带到奥格瑞玛，暗影裂口的术士们利用了其中的心碎与深情。"},{t="恶魔的诱饵",b="在暗影裂口，甘鲁尔·血眼看出了这枚坠饰引诱魅魔的潜力。这些恶魔会被凡人的渴望、爱情与悲剧吸引。术士将多格兰的坠饰洗净擦亮，让这件忠贞爱情的信物变成了诱饵。随后，术士召出一只魅魔，在仪式中与她交战，将她降服。"}},faq={{q="沾满泥土的坠饰从何而来？",a="多格兰是一名被囚禁在贫瘠之地的兽人战士，你给他服下肯兹格拉的伤药，让他恢复神志后，他便将坠饰交给了你。",al={"坠饰来历","坠饰在哪获得","谁给坠饰"}},{q="这枚坠饰与赞卡沙有什么关系？",a="赞卡沙是多格兰在奥格瑞玛的伴侣。他交出坠饰，隐瞒了自己尚在人世的消息，免得她不得不照料一个伤残的战士。",al={"赞卡沙是谁","多格兰与赞卡沙","坠饰含义"}},{q="甘鲁尔·血眼为什么偏偏需要这枚坠饰？",a="魅魔会被凡人强烈的情感吸引，尤其是爱情、心碎与痴情。洗净后的多格兰的坠饰可以凝聚召唤之力，将一只魅魔引入召唤法阵。",al={"为何需要坠饰","魅魔诱饵坠饰","甘鲁尔·血眼坠饰"}},{q="坠饰送到奥格瑞玛后，会发生什么？",a="你将坠饰送到奥格瑞玛后，甘鲁尔·血眼会将它洗净，利用它的吸引力开始誓缚。一只魅魔会被引入暗影裂口下方的法阵，等你将她击败并降服。",al={"交付坠饰之后","坠饰用途"}}},fp="18,155,14.386.1,16.333.1,44.129.0,44.150.1,53.185.0,57.209.1"}
P.entries["item:disarming-colloid"] = {n="拆弹胶质",s="在巨石水坝，拆弹胶质能防止爆盐遇水爆炸。阿什兰·暗石在湿地提供这种胶质，用来配制能够中和这种粉末的混合物。",h="在巨石水坝，拆弹胶质能防止爆盐遇水爆炸。阿什兰·暗石在湿地提供这种胶质，用来配制能够中和这种粉末的混合物。",kw={"阿什兰·暗石","黑铁","拆弹胶质","爆炸物","辛德维尔七世","爆盐","巨石水坝","湿地"},ang={["profession:Engineering"]="身为工程师，你知道Seaforium能造成巨大的破坏。只有像这种胶质一样配比精确的化学中和剂，才能阻止它。",["race:Dwarf"]="身为矮人，你知道针对巨石水坝的Seaforium威胁着矮人的工程造物，以及上方洛克莫丹的安全。"},sec={{t="化学中和剂",b="阿什兰·暗石认出，黑铁工兵留在洛克莫丹巨石水坝的粉末是爆盐。它的气味和细小的银色晶体暴露了它的身份。这种粉末干燥时无害，但遇水就会产生巨大的破坏力，对到处是水的水坝构成严重威胁。暗石提供了拆弹胶质，以便在爆炸前阻止反应。将胶质与潜伏者的毒液、碾碎的莫格罗什水晶和鳄鱼的眼泪混合，就能中和爆盐的爆炸特性。"}},faq={{q="拆弹胶质有什么用途？",a="拆弹胶质是消除爆盐爆炸能力的基础化学制剂。将它与潜伏者的毒液、碾碎的莫格罗什水晶和鳄鱼的眼泪混合，就能中和这种粉末遇水时的剧烈反应。",al={"胶质用途","拆弹胶质有什么用","爆盐拆弹剂"}},{q="是谁制造或提供了这种胶质？",a="阿什兰·暗石提供了这种胶质。他是一名爆破专家，被派往驻守湿地丹莫德的军团，并识破了黑铁矮人摧毁巨石水坝的计划。",al={"谁提供胶质","阿什兰胶质"}},{q="为什么爆盐在湿地如此危险？",a="爆盐干燥时无害，但遇水就会猛烈爆炸。湿地到处是水，而这种粉末又被用来对付巨石水坝，因此受潮的爆盐可能造成大规模破坏。",al={"爆盐为什么危险","受潮的爆盐"}},{q="必须把这种胶质交给谁？",a="阿什兰·暗石说，必须把胶质和爆盐阴谋的消息直接送到巨石水坝的主工程师辛德维尔七世那里。",al={"胶质交给谁","交付胶质"}}},fx={["6b4ad5ab"]={q="什么是拆弹胶质？",a="拆弹胶质是阿什兰·暗石调制的一种特殊中和剂。将它与另外三种强效试剂——潜伏者的毒液、碾碎的莫格罗什水晶和鳄鱼的眼泪混合后，就能安全地解除海蓝色炸药粉的剧烈化学反应，避免爆炸物受潮引爆。",al={"什么是拆弹胶质","拆弹胶质是什么","拆弹胶质背景"}},["1c3f9fc5"]={q="为什么需要拆弹胶质？",a="首席工程师亨德尔维尔急需这种胶质，以免洛克莫丹的巨石水坝发生灾难。黑铁破坏者已在水坝安放了不稳定的海蓝色炸药；若没有这种化学药剂来消解反应，炸药接触水后就可能炸毁水坝。",al={"为什么需要拆弹胶质","为什么需要这种胶质","谁需要拆弹胶质"}}},fp="17,158,22.482.0,35.170.0,37.201.0,46.204.0,38.136.0"}
P.entries["item:disarming-mixture"] = {n="拆弹剂",s="在巨石水坝，总工程师辛德维尔七世正在调配拆弹剂，以化解黑铁破坏者埋设的爆盐炸药。",h="在巨石水坝，总工程师辛德维尔七世正在调配拆弹剂，以化解黑铁破坏者埋设的爆盐炸药。",kw={"黑铁","拆弹剂","炸药","辛德维尔七世","洛克莫丹","火药桶","爆盐","巨石水坝"},ang={["profession:Engineering"]="对工程师而言，拆弹剂展示了如何通过化学中和，让不稳定的Seaforium炸药失去危险，又不引发爆炸。",["race:Dwarf"]="身为矮人，你协助保护巨石水坝周围的山谷与低地。迅速使用中和剂有助于守护这些地方。"},sec={{t="化学中和剂",b="威力巨大的爆盐炸药埋在水坝地基下，附近没有能赶来帮忙的巡山人。辛德维尔七世采用了爆破专家阿什兰·暗石指定的原料。他将这些原料搅拌成化学中和剂，再到水下将其混入火药桶中。活性化合物被中和，炸药也就不再具有危险。"}},faq={{q="拆弹剂有什么用途？",a="拆弹剂用来中和黑铁叛乱分子埋在巨石水坝地基水下的一大桶爆盐炸药。",al={"拆弹剂有什么作用","拆弹剂的用途","拆弹剂的目的"}},{q="谁调配了拆弹剂？",a="总工程师辛德维尔七世负责巨石水坝的维护与防御，同时调配拆弹剂的原料。",al={"谁调配拆弹剂","谁提供拆弹剂","辛德维尔七世的药剂"}},{q="为什么必须使用拆弹剂，而不能直接拆除炸弹？",a="干燥的爆盐火药没有危险，但受潮后却能引发威力巨大的爆炸。拆弹剂能中和活性火药，而火药桶仍浸没在水坝下方的水中。",al={"为什么不能常规拆弹","为什么用化学药剂处理炸弹","为什么使用拆弹剂"}}},fx={["8d78f743"]={q="拆弹剂是什么？",a="拆弹剂是一种专门配制的化学药剂，用于中和不稳定的爆炸性化合物。将其混入爆盐或高品质爆破火药后，它会与爆炸物发生化学反应，使其失效，让炸药仅仅发出一阵无害的嘶嘶声，而不会引发灾难性的爆炸。",al={"拆弹剂是什么","拆弹剂物品","关于拆弹剂"}}},fp="17,132,22.349.0,39.134.0,34.110.0,67.176.0"}
P.entries["item:divined-scroll"] = {n="使用过的占卜卷轴",s="在银风避难所，使用过的占卜卷轴能揭露搅乱灰谷水域的幕后法师。暗夜精灵借助完整的水元素护腕中蕴藏的魔法，查明召唤者的身份。",h="在银风避难所，使用过的占卜卷轴能揭露搅乱灰谷水域的幕后法师。暗夜精灵借助完整的水元素护腕中蕴藏的魔法，查明召唤者的身份。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","密斯特拉湖","银风避难所","维尔莉妮·星坠"},ang={["class:Mage"]="身为法师，你能看出其中的原理：元素束缚中带有施加束缚的巫师留下的奥术印记。",["race:NightElf"]="身为暗夜精灵，你知道占卜工具能帮助Sentinels找出那些凡人污染者，他们对奥术的滥用威胁着灰谷的神圣水域。"},sec={{t="追查召唤者",b="密斯特拉湖遭污染的湖水令守卫灰谷的哨兵忧心不已。哨兵维尔莉妮·星坠交给旅行者一张尚未注入能量的占卜卷轴，用来追查操纵湖中肆虐的水元素之人。从被消灭的元素身上收集完整的护腕，将其用作奥术施法材料；其中潜藏的束缚之力会转入羊皮纸。随后，使用过的占卜卷轴便会显露出引发这场祸患的叛逆巫师的魔法印记。"},{t="法师现形",b="使用过的占卜卷轴上的文字为哨兵维尔莉妮指明了一个凡人祸首：一名肆意妄为的法师，正在蓄意污染林间的池水。真相揭晓后，哨兵便能筹划复仇，派遣斥候追捕玷污这片神圣荒野的召唤者。"}},faq={{q="使用过的占卜卷轴有什么用途？",a="使用过的占卜卷轴能揭露在灰谷湖泊中召唤并束缚敌对水元素的施法者，让哨兵维尔莉妮·星坠得以锁定祸首。",al={"使用过的占卜卷轴有什么用","使用过的占卜卷轴用途","为什么制作使用过的占卜卷轴"}},{q="如何制成使用过的占卜卷轴？",a="从密斯特拉湖周围被击败的水元素身上收集五个完整的元素护腕，然后对它们使用哨兵维尔莉妮·星坠交给你的空白占卜卷轴。",al={"如何制作使用过的占卜卷轴","制作使用过的占卜卷轴","如何获得使用过的占卜卷轴"}},{q="为什么占卜卷轴需要元素护腕？",a="这些护腕将元素束缚在凡人位面。护腕上残留的附魔能为卷轴提供魔法印记，使其辨认出召唤这些元素的巫师。",al={"为什么需要完整的护腕","元素护腕的用途"}},{q="使用过的占卜卷轴该交给谁？",a="将制成的使用过的占卜卷轴交给哨兵维尔莉妮·星坠，她位于灰谷南部道路旁的银风避难所。",al={"使用过的占卜卷轴在哪里交","谁需要使用过的占卜卷轴"}}},fx={["155064fc"]={q="什么是使用过的占卜卷轴？",a="使用过的占卜卷轴是将占卜卷轴与从污染灰谷水域的水元素身上取得的完整护腕一同使用后得到的物品。卷轴吸收了这些护腕上残留的奥术痕迹，从而揭示与召唤并腐化水元素的特定召唤者有关的神秘信息。",al={"什么是使用过的占卜卷轴","使用过的占卜卷轴的用途","使用过的占卜卷轴有什么作用"}},ebb5ddd6={q="使用过的占卜卷轴来自哪里？是谁制作的？",a="你将哨兵维尔莉妮·星坠的占卜卷轴施法于数个完整的元素护腕上，亲手制作出使用过的占卜卷轴。护腕充当奥术试剂，使卷轴的占卜魔法能够聚焦并记录创造这些元素生物之人的魔法印记。",al={"谁制作了使用过的占卜卷轴","使用过的占卜卷轴的来源","使用过的占卜卷轴是如何制作的"}}},fp="14,177,20.411.0,16.249.1,36.169.0,34.153.0,58.168.0,37.123.0"}
P.entries["item:divining-scroll"] = {n="占卜卷轴",s="在银风避难所，哨兵维尔莉妮·星坠将占卜卷轴交给调查者，用来追查制造腐化元素的元凶。",h="在银风避难所，哨兵维尔莉妮·星坠将占卜卷轴交给调查者，用来追查制造腐化元素的元凶。",kw={"灰谷","使用过的占卜卷轴","占卜卷轴","元素护腕","银风避难所","维尔莉妮·星坠","水元素"},ang={["class:Mage"]="卷轴通过占卜追踪奥术共鸣。它揭示了一名同道正在神圣的kaldorei林地中滥用元素召唤术。",["race:NightElf"]="对守护灰谷的Sentinels而言，卷轴能揭露那些以非自然的腐化玷污森林纯净水源的外来者。"},sec={{t="追查异常的元素",b="腐化的水元素从灰谷的池水中涌出，哨兵知道这场异动并非自然现象。哨兵维尔莉妮·星坠找来一张卷轴，以查明谁该为此负责。借助完整的元素护腕作为媒介，卷轴的魔法能提取出召唤者特有的魔法印记。空白的羊皮纸随之变成使用过的占卜卷轴，写出罪魁祸首的名字。"}},faq={{q="占卜卷轴有什么用途？",a="占卜卷轴能查明是谁制造了灰谷的腐化水元素。完整的元素护腕能汇聚卷轴的魔力，读取施法者的灵气并记下其身份。",al={"卷轴有什么作用","占卜卷轴用途","为什么使用占卜卷轴"}},{q="谁提供占卜卷轴？",a="哨兵维尔莉妮·星坠在调查受污染的水源时，将卷轴交给灰谷南部银风避难所的联盟调查者。",al={"谁提供占卜卷轴","哪里获得卷轴","维尔莉妮·星坠的卷轴"}},{q="为什么需要完整的元素护腕？",a="大多数护腕在战斗中碎得面目全非。少数护腕仍然完好，保留着足够的召唤者束缚魔法，可以用来汇聚占卜法术的力量。",al={"为什么需要护腕","完整的元素护腕","卷轴的施法材料"}},{q="使用卷轴后会发生什么？",a="在五副完整的护腕旁使用卷轴后，卷轴会被消耗，变成使用过的占卜卷轴。它揭示了一名叛离的法师正在蓄意将腐化元素召唤到森林的湖泊中。",al={"使用过的占卜卷轴","使用卷轴之后","会变成什么"}}},fx={["51ca655d"]={q="什么是占卜卷轴？",a="占卜卷轴是一张用于揭示魔法来源的附魔羊皮纸。以完整的元素护腕作为试剂聚焦后，它的魔法可以追踪侵扰灰谷的水元素身上的束缚印记，并找出将它们召入森林纯净水域的叛逃施法者。",al={"什么是占卜卷轴","占卜卷轴背景","占卜卷轴物品"}},af5653e2={q="为什么需要占卜卷轴？",a="哨兵维尔莉妮·星坠需要这张卷轴，查明是谁在灰谷的湖泊与水池中不断召唤受腐化的水元素。没有卷轴的占卜魔法，暗夜精灵就无法锁定罪魁祸首，也无法阻止这片圣洁荒野继续遭到玷污。",al={"为什么需要占卜卷轴","为什么需要这张卷轴","占卜卷轴的用途"}}},fp="15,135,28.348.0,37.192.0,33.152.0,40.153.0,38.198.1"}
P.entries["item:dogran-s-pendant"] = {n="多格兰的坠饰",s="多格兰的坠饰将魅魔引向奥格瑞玛的术士。受伤的兽人多格兰与伴侣赞卡沙分离，随身带着这枚坠饰。在暗影裂口，术士们将寄托于坠饰中的悲伤化作诱饵。",h="多格兰的坠饰将魅魔引向奥格瑞玛的术士。受伤的兽人多格兰与伴侣赞卡沙分离，随身带着这枚坠饰。在暗影裂口，术士们将寄托于坠饰中的悲伤化作诱饵。",kw={"暗影裂口","多格兰","多格兰的坠饰","甘鲁尔·血眼","奥格瑞玛","魅魔","誓缚","赞卡沙"},ang={["class:Warlock"]="身为部落术士，你用多格兰的坠饰证明自己对虚空的掌控，并学会召唤魅魔。",["faction:Horde"]="身为部落的一员，你能看到这枚坠饰与贫瘠之地和杜隆塔尔的个人悲剧，以及奥格瑞玛的术士集会之间的联系。"},sec={{t="心碎的媒介",b="多格兰的坠饰承载着一名兽人与赞卡沙分离的悲伤。囚禁与致残的伤势为他们的爱情蒙上了阴影。暗影裂口的术士知道，魅魔这类恶魔会利用爱、渴望与脆弱。他们借助坠饰中的悲伤，将一只魅魔引过扭曲虚空，带入尼尔鲁·火刃的召唤法阵。"},{t="征服与思念",b="在甘鲁尔·血眼的指引下，一名初出茅庐的术士用坠饰召唤魅魔，并在战斗中将其制服。这场试炼证明术士能够驾驭恶魔的诱惑与操纵。仪式结束后，坠饰交还给甘鲁尔，由他转交给赞卡沙。"}},faq={{q="多格兰的坠饰有什么用途？",a="术士用多格兰的坠饰，在暗影裂口中尼尔鲁·火刃的帐篷内召唤魅魔。恶魔被召唤并击败后，坠饰便交还给甘鲁尔·血眼。",al={"坠饰用途","多格兰的坠饰怎么用","多格兰的坠饰任务"}},{q="魅魔为什么会响应坠饰的召唤？",a="魅魔以欲望、爱与激情为食，也懂得如何操纵这些情感。坠饰寄托着多格兰与赞卡沙的悲恋，将恶魔引过虚空。",al={"魅魔为什么想要坠饰","坠饰为什么能召唤恶魔","坠饰背景故事"}},{q="多格兰是谁？",a="多格兰是一名兽人，部落术士通过盲眼卡祖尔和肯兹格拉等联络人，调查他被囚禁和受伤的情况。他深爱赞卡沙，却不愿让她背负照顾一个残疾者的重担。",al={"多格兰是谁","多格兰的故事"}},{q="召唤仪式结束后，坠饰会如何处置？",a="术士击败召唤出的魅魔后，坠饰便交还给甘鲁尔·血眼，由他转交给赞卡沙。",al={"坠饰交给谁","归还多格兰的坠饰"}}},fp="16,166,23.341.0,27.271.1,34.186.0,43.173.0,15.195.0,55.120.0"}
P.entries["item:dolanaar-delivery"] = {n="多兰纳尔的货物",s="在幽影谷，年轻的旅人将采集的草药向南送往多兰纳尔。伯萨努斯将这包草药托付给他们，交给旅店老板凯达米尔。",h="在幽影谷，年轻的旅人将采集的草药向南送往多兰纳尔。伯萨努斯将这包草药托付给他们，交给旅店老板凯达米尔。",kw={"奥达希尔","送货","多兰纳尔","草药","凯达米尔","伯萨努斯","幽影谷"},ang={["profession:Herbalism"]="泰达希尔的偏远聚落不断补充储备，对奥达希尔周围采集的草药有着稳定的需求。",["race:NightElf"]="作为一名年轻的 kaldorei，运送包裹意味着走出幽影谷庇护的枝叶，踏入更广阔的天地，完成一场成长的仪式。"},sec={{t="来自幽影谷的包裹",b="来自奥达希尔的新鲜草药将被送往多兰纳尔。伯萨努斯正忙于处理幽影谷德鲁伊的事务，于是将包裹托付给沿路南行的年轻旅人。他们将包裹送到旅店老板凯达米尔手中。"},{t="炉火边的欢迎",b="这份包裹将你带到多兰纳尔的旅店，凯达米尔满怀感激地收下了它。在疲惫的旅人深入泰达希尔之前，这家旅店为他们提供休憩之所、内心的安宁和庇护。"}},faq={{q="多兰纳尔的货物里装着什么？",a="包裹里装着在幽影谷采集的新鲜草药，是送给旅店老板凯达米尔和多兰纳尔旅店的客人们的。",al={"里面有什么草药","多兰纳尔的货物内容","包裹里有什么"}},{q="是谁寄出这份货物的？",a="伯萨努斯是一名在幽影谷处理德鲁伊相关事务的精灵，他备好了包裹，却抽不出时间亲自南行。",al={"谁交付货物","谁寄出草药","伯萨努斯的货物"}},{q="谁在多兰纳尔接收包裹？",a="旅店老板凯达米尔在多兰纳尔中心的公共旅店接收包裹。",al={"草药交给谁","多兰纳尔的货物接收者","凯达米尔 草药"}},{q="伯萨努斯为什么不能亲自送去包裹？",a="伯萨努斯与奥达希尔周围的德鲁伊还有紧急事务尚未处理完，因此他在寻找沿林间道路南行的旅人。",al={"伯萨努斯为何留下","伯萨努斯为何派我去"}}},fp="17,125,24.218.0,21.173.0,37.103.0,24.138.0,37.67.0,52.143.0"}
P.entries["item:dragonmaw-war-banner"] = {n="龙喉战旗",s="龙喉战旗在湿地的兽人营地上空飘扬。旗上的氏族标记，让米奈希尔港的矮人守军看到了威胁日益加剧的证据。",h="龙喉战旗在湿地的兽人营地上空飘扬。旗上的氏族标记，让米奈希尔港的矮人守军看到了威胁日益加剧的证据。",kw={"龙喉氏族","格瑞姆巴托","米奈希尔","纳克罗什","斯托菲","战旗","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你削弱了一个宿敌，使龙喉氏族来不及重建他们在Second War期间掌握的可怕力量。",["race:Dwarf"]="身为卡兹莫丹的矮人，你帮助清除沼泽中的龙喉氏族旗帜，保护通往米奈希尔港的商路免遭兽人掠夺者的袭击。"},sec={{t="威胁未息的徽记",b="第二次战争之后，龙喉氏族氏族失去了对所奴役红龙的控制，随之分崩离析。愤怒的幼龙转而攻击囚禁它们的人，将幸存者从格瑞姆巴托赶进了东部丘陵。如今，残存的兽人在酋长纳克罗什的领导下积蓄力量，在米奈希尔港东北方的营地上空竖起战旗。这些粗陋的旗帜彰显着他们的反抗，也威胁着沼泽中的定居点。"},{t="征服的凭证",b="米奈希尔港的斯托菲队长派遣联盟冒险者前往沼泽中的营地，带回龙喉氏族的旗帜。掠夺者、百夫长和护骨者携带着这些战利品，向矮人驻军证明，这些营地正遭到摧毁，氏族还来不及发起协同袭击。"}},faq={{q="斯托菲队长为什么要这些旗帜？",a="斯托菲队长需要这些旗帜，作为冒险者袭击米奈希尔港东北方龙喉氏族营地并削减其兵力的证据。",al={"为什么收集旗帜","战旗用途","斯托菲为什么要旗帜"}},{q="谁携带着龙喉战旗？",a="龙喉氏族的掠夺者、沼泽奔跑者、百夫长、战斗大师、暗影守卫、护骨者以及酋长纳克罗什，都在湿地的营地中携带着这些旗帜。",al={"谁掉落龙喉氏族旗帜","哪里获取战旗","哪些兽人携带旗帜"}},{q="龙喉氏族兽人为什么会在湿地？",a="临近第二次战争结束时，龙喉氏族失去了对被囚禁红龙的控制。重获自由的红龙追杀昔日的主人，迫使幸存的兽人逃离格瑞姆巴托，四散到东部丘陵、湿地和周围的群山中。",al={"龙喉氏族为什么在这里","湿地龙喉氏族历史","龙喉氏族背景故事"}},{q="如今谁在领导龙喉氏族氏族？",a="酋长纳克罗什领导着这个氏族。他是前任酋长耐克鲁斯的儿子，发誓要向那些反噬并杀死他父亲的红龙复仇。",al={"龙喉氏族首领","纳克罗什是谁","纳克罗什酋长"}}},fx={abf078db={q="什么是龙喉战旗？",a="这些战旗是湿地龙喉氏族的集结象征。旗帜上绘有兽人氏族的徽记；这个氏族曾因奴役红龙军团而恶名远扬。战旗彰显着他们的军威与不屈。对于米奈希尔港的联盟守军而言，夺取战旗证明一处营地已被攻破，其中的战士也已溃败。",al={"什么是龙喉战旗","龙喉战旗"}},["2c481a00"]={q="龙喉战旗来自哪里？是谁制作的？",a="它们由龙喉氏族的幸存兽人制作并携带。龙喉氏族失去格瑞姆巴托要塞，并逃离获得解放的红龙的怒火后，在米奈希尔港东北方的山地与沼泽中重新集结。在那里，他们的掠袭者、百夫长与萨满制作这些战旗，标示新占领的领地，并在酋长奈克罗什的率领下集结日渐壮大的战团。",al={"谁制作了龙喉战旗","龙喉战旗的来源","战旗来自哪里"}}},fp="20,150,29.391.0,17.290.0,46.144.0,38.153.0,43.262.0,33.166.0"}
P.entries["item:dried-seeds"] = {n="干枯的种子",s="在十字路口，图加·符文图腾将干枯的种子交给旅行者，用来测试贫瘠之地水下赋予生命的力量。",h="在十字路口，图加·符文图腾将干枯的种子交给旅行者，用来测试贫瘠之地水下赋予生命的力量。",kw={"贫瘠之地","冒泡的裂隙","十字路口","干枯的种子","死水绿洲","图加·符文图腾"},ang={["class:Druid"]="身为德鲁伊，你可以用死去的种子研究从贫瘠之地地下涌出的奇异能量。",["faction:Horde"]="身为部落冒险者，你可以帮助图加·符文图腾调查贫瘠之地干燥土壤中的变化。"},sec={{t="种子与绿洲",b="图加·符文图腾正在研究贫瘠之地水下的奇异喷口。他在遗忘之池的水面下发现了裂隙，如今想弄清东南方的死水绿洲下是否也有这样的裂隙。他将看似毫无生机的干枯的种子交给旅行者，让他们把种子放进冒泡的裂隙中。种子的反应能表明，绿洲下的能量能否唤醒死去的种子中的生机。"}},faq={{q="干枯的种子有什么用途？",a="你用干枯的种子测试死水绿洲水下冒泡的裂隙。将它们放入水中，看看那里的能量能否让它们恢复生机。",al={"干枯的种子用途","干枯的种子怎么用","干枯的种子作用"}},{q="谁提供干枯的种子？",a="图加·符文图腾是十字路口的一位牛头人德鲁伊，他将干枯的种子交给旅行者。他正在研究贫瘠之地植物突然繁茂生长的现象。",al={"谁给干枯的种子","干枯的种子来源"}},{q="使用种子的裂隙在哪里？",a="裂隙位于死水绿洲的水下，就在贫瘠之地十字路口的东南方。",al={"干枯的种子种在哪里","死水绿洲裂隙位置","冒泡的裂隙干枯的种子"}},{q="种子接触裂隙后会发生什么？",a="图加让你将死去的种子放入冒泡的裂隙中，并观察它们。种子的反应会揭示他的实验结果。",al={"种子会生长吗","干枯的种子结果"}}},fp="11,109,23.414.1,34.151.0,29.134.0,36.102.0,55.133.1"}
P.entries["item:durnan-s-scalding-mornbrew"] = {n="德南的热酒",s="安威玛尔内，德南·弗卡特正等着他的那杯晨酿，可山间的严寒随时可能让酒在送到前就凉透。",h="安威玛尔内，德南·弗卡特正等着他的那杯晨酿，可山间的严寒随时可能让酒在送到前就凉透。",kw={"安威玛尔","寒脊山谷","丹莫罗","德南·弗卡特","晨酿","滚烫"},ang={["race:Dwarf"]="身为丹莫罗的矮人，你知道任由好麦酒或晨酿在山间的霜寒中变凉有多令人痛心。"},sec={{t="与严寒赛跑",b="一名信使在前往格瑞林·白须那里的途中耽搁了，刚倒好的晨酿眼看就要被寒脊山谷的霜寒冻凉。沿着积雪的小径，在几分钟内将它送到山间的大厅，否则德南的晨酿就要凉了。"}},faq={{q="这杯晨酿是送给谁的？",a="这杯晨酿是给德南·弗卡特的，他是一名驻守在寒脊山谷安威玛尔内的矮人。",al={"晨酿送给谁","德南晨酿收件人","晨酿送到哪里"}},{q="为什么必须这么快送到？",a="丹莫罗冰冷的空气很快就会让敞口酒杯里的酒变凉。德南要的是滚烫的晨酿，温吞的酒可无法让他满意。",al={"为什么有时限","晨酿变凉","为什么急送晨酿"}},{q="从哪里开始送酒？",a="信使发觉自己无法独自及时赶到锻造大厅后，便在安威玛尔外、格瑞林·白须的营地附近将酒交了出去。",al={"晨酿来自哪里","谁倒的晨酿"}},{q="德南收到酒杯后会怎样？",a="德南会暂时放下在安威玛尔内的职责，趁热细品这杯热气腾腾的酒。",al={"德南的反应","交付晨酿"}}},fx={["93832100"]={q="德南的热酒是什么？",a="这是一杯刚倒好的矮人晨酒，专门为安威玛尔的德南·弗卡特准备。它能暖透筋骨，抵御寒脊山谷刺骨的山间寒气，必须趁滚烫时喝下才够舒坦。",al={"滚烫的晨酒是什么","德南的晨酒物品","晨酒饮品"}},c7c22f23={q="德南为什么想要滚烫的晨酒？",a="德南·弗卡特订了这杯热气腾腾的酒，准备在安威玛尔辛勤劳作后的休息时间享用。矮人很看重清晨的这杯酒，让这样一大杯醇厚的酒凉下来，便会彻底毁掉这份享受。",al={"德南为何想要晨酒","为何需要晨酒","德南的饮品用途"}}},fp="26,124,23.208.0,29.94.0,48.122.0,34.153.0,42.91.0"}
P.entries["item:durotar-tiger-fur"] = {n="杜隆塔尔虎皮",s="在杜隆塔尔东南海岸外的回音群岛上，老虎为难民日益增多的黑暗之矛提供毛皮。巨魔用这些毛皮制作毯子、帐篷和护甲。",h="在杜隆塔尔东南海岸外的回音群岛上，老虎为难民日益增多的黑暗之矛提供毛皮。巨魔用这些毛皮制作毯子、帐篷和护甲。",kw={"杜隆塔尔老虎","杜隆塔尔虎皮","回音群岛","生活所需","森金村","巨魔毛皮","维尔林·长牙"},ang={["class:Hunter"]="身为猎人，在回音群岛追踪老虎，与巨魔传统的狩猎仪式如出一辙，需要耐心和伪装，才能伏击岛上这些行踪隐秘的掠食者。",["race:Troll"]="对黑暗之矛而言，虎皮是在森金村生存的保障，也让他们想起失去回音群岛家园的伤痛。"},sec={{t="黑暗之矛的重要物资",b="在森金村，黑暗之矛必须省着使用紧缺的物资。他们让当地的老虎繁衍生息，直到日益增长的需求迫使他们猎杀一部分老虎。巨魔将厚实的虎皮鞣制成定居点所需的物品，包括防身的护甲和应对季节变化的保暖毯子。"},{t="回音群岛的狩猎",b="回音群岛位于杜隆塔尔南面，与大陆隔海相望。黑暗之矛曾以这片群岛为家，直到巫医扎拉赞恩将他们赶走。猎人既要提防扎拉赞恩的傀儡，也要小心潜伏在茂密枝叶间的老虎。维尔林·长牙这样的老练猎人说过，为了一击毙命，他们会在丛林的灌木中一动不动地守候整天。"}},faq={{q="杜隆塔尔虎皮从哪里获得？",a="猎人在杜隆塔尔东南海岸外的回音群岛上猎杀老虎，获取杜隆塔尔虎皮。",al={"虎皮哪里掉落","杜隆塔尔虎皮位置","如何获取虎皮"}},{q="森金村的巨魔为什么需要这些虎皮？",a="维尔林·长牙为不断扩大的黑暗之矛定居点收集虎皮，巨魔用它们制作毯子、帐篷和防护皮甲，以应对四季的天气变化。",al={"为什么收集虎皮","谁需要虎皮","生活所需用途"}},{q="巨魔为什么不过度猎杀老虎？",a="黑暗之矛让老虎繁衍生息，只有当族群日益增长的需求使住所和衣物的供应吃紧时，才会猎杀一部分老虎。",al={"老虎保护","削减兽群数量"}}},fp="17,179,34.260.0,22.365.0,38.102.0,53.160.0,41.137.0"}
P.entries["item:duskbat-wing"] = {n="夜行蝙蝠翼",s="夜行蝙蝠 在丧钟镇上空盘旋，当地裁缝用它们的翅膀为刚刚复生的士兵制作临时护甲。",h="夜行蝙蝠 在丧钟镇上空盘旋，当地裁缝用它们的翅膀为刚刚复生的士兵制作临时护甲。",kw={"丧钟镇","夜行蝙蝠","夜行蝙蝠翼","新兵艾尔雷斯","食腐狼的爪子","被诅咒者","提瑞斯法林地"},ang={["profession:Tailoring"]="新兵艾尔雷斯展示了提瑞斯法的裁缝如何用坚韧的蝠翼代替皮革和布料。",["race:Undead"]="作为刚刚苏醒的被遗忘者，收集这些蝠翼是你最初的求生任务之一，能帮助你在最初的几场小规模战斗中保全身体。"},sec={{t="丧钟镇的简陋防护",b="新生的被遗忘者从丧钟镇的泥土中挣扎爬出，身上只有几块破布和脆弱的骨头。附近游荡着无脑的 天灾军团 和凶猛的野兽，他们必须尽力搜集能用来防身的东西。暗影牧师萨维斯的助手新兵艾尔雷斯收集夜行蝙蝠翼和狼爪，为刚刚复生的战士拼制并加固衣甲，让他们能进入荒野作战。"}},faq={{q="夜行蝙蝠翼有什么用途？",a="在丧钟镇，新兵艾尔雷斯用夜行蝙蝠翼和食腐动物的爪子，为刚刚苏醒的被遗忘者新兵制作、修补并加固衣甲。",al={"夜行蝙蝠翼用途","为什么收集夜行蝙蝠翼","夜行蝙蝠翼作用"}},{q="夜行蝙蝠翼从哪里来？",a="提瑞斯法林地的丧钟镇周围，树林和山丘中的 夜行蝙蝠 和 癞皮夜行蝙蝠 都能提供这些蝠翼。",al={"哪里找夜行蝙蝠翼","夜行蝙蝠翼来源","谁掉落夜行蝙蝠翼"}},{q="丧钟镇里谁需要这些蝠翼？",a="新兵艾尔雷斯请新兵们收集蝠翼。她在丧钟镇的教堂里，遵照暗影牧师萨维斯的指示照料伤者并制作装备。",al={"谁需要夜行蝙蝠翼","交付夜行蝙蝠翼","夜行蝙蝠翼任务发布者"}},{q="为什么被遗忘者要靠蝙蝠的身体部位制作护甲？",a="丧钟镇几乎没有补给线，也没有传统的制造业，因此当地的照料者从提瑞斯法本土的掠食动物身上搜集兽皮、毛皮和坚韧如皮革的蝠翼。他们用这些材料为即将参战的新兵制作简陋的防护衣物。",al={"为什么用蝠翼制作护甲","蝙蝠皮护甲 被遗忘者"}}},fp="12,79,35.408.0,32.153.0,33.109.0,39.152.0,48.266.0"}
P.entries["item:dusky-crab-cakes"] = {n="黑蟹蛋糕",s="在夜色镇，厨师格鲁奥为饥肠辘辘的基特斯制作黑蟹蛋糕。这道菜是当地的美食，基特斯觉得它美味极了。",h="在夜色镇，厨师格鲁奥为饥肠辘辘的基特斯制作黑蟹蛋糕。这道菜是当地的美食，基特斯觉得它美味极了。",kw={"夜色镇","暮色森林","黑蟹蛋糕","格鲁奥","基特斯","蜘蛛腿"},ang={["profession:Cooking"]="格鲁奥的蛋糕展现了厨师如何用暮色森林中的食材，做出风味浓郁的当地特色菜。"},sec={{t="可疑的美味",b="厨师格鲁奥为基特斯制作黑蟹蛋糕，这个惊恐的流浪汉已经饿坏了。暮色森林的新鲜食材寥寥无几，厨师们只能用林中的肉食将就。格鲁奥做的蛋糕看起来就像普通的海鲜饼，但其中的秘密原料却来自暮色森林那些巨型蛛形生物的腿。基特斯狼吞虎咽地吃着蛋糕，浑然不知自己吃的是什么。"}},faq={{q="黑蟹蛋糕究竟是用什么做的？",a="厨师格鲁奥对自己的配方守口如瓶。在暮色森林为他收集食材时，蛋糕中的秘密原料才显露出来。",al={"蟹肉蛋糕原料","黑蟹蛋糕里有什么","蜘蛛肉"}},{q="谁吃黑蟹蛋糕？",a="厨师格鲁奥为基特斯制作这些蛋糕，这个焦虑不安的男人躲在乌鸦岭，抱怨自己的肚子饿得咕咕叫。",al={"蟹肉蛋糕给谁","这些是给谁的","基特斯的食物"}},{q="基特斯对蛋糕有什么反应？",a="基特斯饿坏了，高高兴兴地狼吞虎咽，丝毫没有过问蛋糕的配方。能有一顿饭填饱肚子，他心怀感激。",al={"基特斯的反应","基特斯喜欢这些蛋糕吗"}},{q="谁制作黑蟹蛋糕？",a="厨师格鲁奥是夜色镇血鸦旅店的厨师，他用别人为他收集的食材制作这些蛋糕。",al={"谁制作蟹肉蛋糕","厨师格鲁奥","夜色镇厨师"}}},fp="16,115,23.346.1,43.125.0,30.116.0,36.130.0,31.109.0"}
P.entries["item:dust-devil-debris"] = {n="尘魔的残骸",s="在西部荒野各地，尘魔会留下蕴含能量的砂砾。法师用这些砂砾为羊皮纸附魔，将传讯法术束缚在卷轴中。",h="在西部荒野各地，尘魔会留下蕴含能量的砂砾。法师用这些砂砾为羊皮纸附魔，将传讯法术束缚在卷轴中。",kw={"科林·马伦","尘魔的残骸","尘魔","传讯法术","卷轴","暴风城","西部荒野"},ang={["class:Mage"]="身为法师，你能看出元素残骸如何帮助铭文书写和通讯魔法，将原始的元素混沌与严谨的奥术技艺结合起来。"},sec={{t="风织入羊皮纸",b="尘魔化作猛烈的旋风，横扫西部荒野的平原。当其中一个倒下时，这团活生生的风暴便会崩散成蕴含能量的尘土与砂砾，称为尘魔的残骸。残骸中仍留有一丝元素漩涡的力量。\n\n在暴风城，科林·马伦等奥术施法者珍视这些砂砾，将其用于特殊的法术。这些砂砾混入附魔墨水和羊皮纸后，能帮助法师将轻灵的传讯法术束缚在卷轴上，让话语传遍王国。"}},faq={{q="尘魔的残骸有什么用途？",a="科林·马伦用尘魔的残骸制作一种特殊的传讯卷轴。残骸中留存的元素能量能帮助他将精妙的通讯魔法束缚在纸上。",al={"尘魔的残骸用途","为何收集尘魔的残骸","残骸用途"}},{q="这些残骸从何而来？",a="尘魔的残骸来自尘魔，这些敌对的空气元素游荡在西部荒野贫瘠的农田和道路上。",al={"哪里能找到残骸","尘魔掉落","西部荒野残骸"}},{q="尘魔为何危险？",a="尘魔是游荡在西部荒野的敌对空气元素。科林·马伦警告说，要收集它们的残骸，就得面对这些危险的生物。",al={"西部荒野为何有元素生物","西部荒野尘魔起源"}},{q="科林·马伦是谁？",a="科林·马伦是暴风城法师区的一位人类法师。他运用奥术知识，为其他施法者和好奇的研究者制作附魔卷轴与魔法材料。",al={"科林·马伦","谁需要残骸"}}},fx={["2f6e3759"]={q="尘魔的残骸是什么？",a="尘魔的残骸是在西部荒野击败尘魔后留下的飞旋沙砾、尘土与残余魔法物质。这些元素旋风肆虐于干旱的平原，其残骸仍保留着足够的游离能量，可供附魔师和铭文师用作强效施法材料。",al={"尘魔的残骸是什么","尘魔的残骸","尘魔的残骸物品"}}},fp="17,129,23.458.0,35.162.0,33.115.0,30.140.0,21.189.0"}
P.entries["item:dwarven-tinder"] = {n="矮人火绒",s="在湿地，矮人火绒让联盟破坏者得以在龙喉氏族的攻城器械抵达米奈希尔港前将其烧毁。",h="在湿地，矮人火绒让联盟破坏者得以在龙喉氏族的攻城器械抵达米奈希尔港前将其烧毁。",kw={"投石车","龙喉氏族","矮人火绒","米奈希尔港","纳克罗什","破坏","湿地"},ang={["faction:Alliance"]="身为联盟的一员，你知道，在敌人的战争机器抵达米奈希尔港之前将其烧毁，有助于在丹奥加兹各处隘口争夺未定之际，保住联盟在沼泽地区的主要港口。",["race:Dwarf"]="身为矮人，你知道可靠的引火物在湿地十分重要，那里的雨水和沼泽让大地终年湿漉漉的。"},sec={{t="破坏龙喉氏族的攻城器械",b="当联盟斥候在龙喉氏族营地内发现纳克罗什酋长的重型投石车时，米奈希尔港面临着一场危机。丹奥加兹的战事切断了港口与南方援军的联系，守军无法承受长时间的围攻。他们决定在这些投石车投入使用前将其破坏。携带矮人火绒深入兽人领地的志愿者，只需打出火星就能将其点燃。火绒燃起的烈焰能在几分钟内烧穿这些加固的木制攻城器械。"}},faq={{q="矮人火绒有什么用途？",a="联盟破坏者用矮人火绒烧毁湿地的龙喉氏族投石车，阻止它们进攻米奈希尔港。",al={"矮人火绒的用途","为什么使用矮人火绒","矮人火绒有什么作用"}},{q="为什么要烧毁投石车，而不是缴获它们？",a="守军无法在龙喉氏族领地深处缴获重型攻城器械。驻军兵力处于劣势，丹奥加兹的封锁又切断了铁炉堡的增援，摧毁投石车成了他们唯一可行的防御手段。",al={"为什么摧毁投石车","为什么不缴获攻城器械"}},{q="这些火绒是谁准备的？",a="米奈希尔港的矮人驻军提供这些火绒，经过专门处理，确保在破坏行动中能够迅速、可靠地点燃。",al={"谁制作了火绒","矮人火绒来自哪里"}}},fx={["5fa2c489"]={q="什么是矮人火绒？",a="矮人火绒是由米奈希尔港的守军提供的一种易燃引火物，经过特殊处理。矮人民兵将它制成只需一星火花就能迅速点燃的引火物，确保笨重的木制战争机器能在潮湿的湿地中迅速、彻底地燃烧起来，不给敌军反应的机会。",al={"什么是矮人火绒","矮人火绒物品","关于矮人火绒"}},f9865b90={q="为什么现在需要矮人火绒？",a="奈克罗什麾下的龙喉兽人建造了巨型攻城投石车，企图摧毁米奈希尔港。丹奥加兹战况激烈，铁炉堡的援军无法抵达，米奈希尔港经受不住长时间的围攻。你必须用这些火绒潜入龙喉兽人的营地，把他们的战争机器烧成灰烬，赶在他们发起进攻之前完成任务。",al={"为什么要矮人火绒","为什么需要矮人火绒","为什么需要火绒"}}},fp="14,123,24.470.0,32.121.0,49.225.0,25.126.0"}
P.entries["item:ear-of-balgaras"] = {n="巴尔加拉斯的耳朵",s="在丹莫德，邪恶的巴尔加拉斯的耳朵标志着这名术士的末路。这只从黑铁指挥官尸体上取下的耳朵，为铁炉堡的巡山人提供了他已死的证据。",h="在丹莫德，邪恶的巴尔加拉斯的耳朵标志着这名术士的末路。这只从黑铁指挥官尸体上取下的耳朵，为铁炉堡的巡山人提供了他已死的证据。",kw={"邪恶的巴尔加拉斯","黑铁","丹莫德","巴尔加拉斯的耳朵","布莱德·长须","萨多尔大桥","湿地"},ang={["class:Warlock"]="巴尔加拉斯躲在暗处施展暗影与邪能法术。他的败亡除掉了一名为北方道路带来毁灭的邪道术士。",["race:Dwarf"]="对铁炉堡的矮人而言，取得这只耳朵，就是为那些在萨多尔大桥遭破坏时惨死的同胞讨还血债。"},sec={{t="残酷的战利品",b="邪恶的巴尔加拉斯指挥了黑铁对丹莫德的进攻。入侵者破坏了萨多尔大桥，消灭了当地的矮人驻军，让这座哨站沦为废墟。巴尔加拉斯是一名诡计多端的术士，他躲在暗处指挥部队，不愿亲自作战。布莱德·长须是山丘之王麾下的军官，驻扎在废墟外，他想要这名祸首已被击杀的证据。巴尔加拉斯被割下的耳朵证实，这名术士在北部边境的统治已经结束。"},{t="为死者讨回公道",b="丹莫德沦陷时，长须的兄弟和数十名坚毅的士兵在西桥的坍塌中丧生。这只耳朵无法修复桥梁，也无法让死者复生。失去了巴尔加拉斯的指挥，散布在湿地北部的黑铁残部更容易受到铁炉堡斥候的遏制，直到另一名指挥官从南方赶来。"}},faq={{q="邪恶的巴尔加拉斯是谁？",a="邪恶的巴尔加拉斯是一名黑铁矮人术士，曾指挥战团袭击丹莫德，摧毁了萨多尔大桥的西桥。他的怯懦臭名昭著，一边派出一波又一波士兵送死，一边躲避联盟的巡逻队。",al={"巴尔加拉斯是谁","巴尔加拉斯的故事","邪恶的巴尔加拉斯"}},{q="布莱德·长须为什么偏偏要他的耳朵？",a="布莱德·长须想要证据，证明那名行踪难觅的术士已经被杀。割下的耳朵是边境地区常见的战利品，既能证明委托已经完成，也省去了把尸体拖回矮人营地的麻烦。",al={"为什么要耳朵","为什么割下耳朵","长须的证据"}},{q="巴尔加拉斯死后，黑铁矮人会怎样？",a="失去那位精于算计的首领后，丹莫德的黑铁残部便成了一盘散沙。尽管他们仍在废墟中出没，长须相信，在铁炉堡的敌人派来新的指挥官之前，联盟能够控制住他们。",al={"巴尔加拉斯死后会怎样","丹莫德的黑铁矮人"}}},fx={a51409b4={q="巴尔加拉斯的耳朵来自哪里？",a="这只被割下的耳朵来自污秽者巴尔加拉斯，一个在湿地北部活动的懦弱黑铁术士。巴尔加拉斯统领着袭击丹莫德、摧毁萨多尔大桥西侧桥段的敌对矮人，但他更愿意躲藏起来，派手下去战斗。",al={"巴尔加拉斯的耳朵来源","哪里能获得巴尔加拉斯的耳朵","谁有巴尔加拉斯的耳朵"}}},fp="15,153,13.440.0,22.358.0,26.229.0,54.202.0,53.231.0"}
P.entries["item:ebonlocke-s-response-to-solomon"] = {n="埃伯洛克的回信",s="艾尔罗·埃伯洛克公爵从夜色镇给所罗门寄去一封拒绝求援的信。他在信中拒绝派遣守夜人援助赤脊山。",h="艾尔罗·埃伯洛克公爵从夜色镇给所罗门寄去一封拒绝求援的信。他在信中拒绝派遣守夜人援助赤脊山。",kw={"夜色镇","暮色森林","埃伯洛克","湖畔镇","信件","信使","守夜人","赤脊山","所罗门"},ang={["faction:Alliance"]="身为联盟的一员，你可以看到暴风城王廷如何将赤脊山、暮色森林和西部荒野弃之不顾。"},sec={{t="愤然拒绝",b="暴风城无视了所罗门镇长的请愿后，他向暮色森林请求增援，以对抗黑石兽人。艾尔罗·埃伯洛克公爵满怀怒火地回信，没有承诺提供援助。他提醒所罗门，当腐化魔法最初笼罩这片森林时，暴风城便抛弃了夜色镇，守夜人正是因此而成立的。如果这里的守卫离开，前去援助赤脊山，暮色森林就会毫无防备，在民兵抵达林缘之前便落入邪恶之手。"},{t="日渐衰败的边疆",b="所罗门收到信后深受震动。暴风城军队已经撤离西部荒野，夜色镇也不见皇家卫兵的踪影。整个南部边疆都被弃之不顾，日渐衰败。所罗门发现，暴风城对各处边远领地的漠视有着可怕的共通之处，并怀疑王国最高层中有人叛国。"}},faq={{q="埃伯洛克的回信是什么？",a="夜色镇的艾尔罗·埃伯洛克公爵给湖畔镇的所罗门镇长寄去一封密封的信。他拒绝派遣守夜人保卫赤脊山，声称暮色森林连抵御自身的梦魇都已十分勉强。",al={"埃伯洛克的信","埃伯洛克的回信","给所罗门的信"}},{q="夜色镇为什么不向湖畔镇派出援兵？",a="夜色镇没有皇家军队驻守。暴风城抛弃这里后，由当地志愿者组成的守夜人便独自承担起保卫这一地区的职责。埃伯洛克公爵警告说，如果他们出征，尚未走出森林，亡灵和邪恶生物就会攻陷夜色镇。",al={"守夜人为何不援助","夜色镇为何拒绝","埃伯洛克拒绝所罗门"}},{q="所罗门镇长对这封信有何反应？",a="所罗门镇长感到震惊与不安。夜色镇没有皇家卫兵驻守，军队又撤离了西部荒野，这让他怀疑暴风城的领导者中有人暗中作梗或叛国。",al={"所罗门的反应","所罗门说了什么"}},{q="这封信是谁写的？",a="这封信出自艾尔罗·埃伯洛克公爵之手，他是困境重重的夜色镇的镇长，也是夜色镇议会的领袖。他负责镇上的防务。",al={"埃伯洛克是谁","埃伯洛克公爵"}}},fx={de19eb29={q="所罗门镇长为什么想要埃伯洛克的回信？",a="所罗门镇长急需援军来抵御黑石兽人，保卫湖畔镇。暴风城多次无视他的军事援助请求后，他向夜色镇求助，希望艾尔罗·埃伯洛克公爵能派出夜色镇卫队。所罗门急切地等待这封信，想知道暮色森林是否会派来援助，却发现夜色镇和赤脊山一样，孤立无援、处境艰难。",al={"所罗门为什么需要信件","为什么要送交埃伯洛克的回信","为什么把回信送给所罗门"}}},fp="31,143,16.441.0,22.336.1,40.201.0,43.276.0,48.204.1,22.140.0"}
P.entries["item:echeyakee-s-hide"] = {n="埃其亚基的皮",s="在十字路口，瑟格拉·黑棘正等待着白雾的浅色毛皮，那是贫瘠之地传说中的白狮。牛头人尊这头猛兽为仁慈与死亡的化身，而猎人则以它的毛皮证明自己的本领。",h="在十字路口，瑟格拉·黑棘正等待着白雾的浅色毛皮，那是贫瘠之地传说中的白狮。牛头人尊这头猛兽为仁慈与死亡的化身，而猎人则以它的毛皮证明自己的本领。",kw={"贫瘠之地","十字路口","埃其亚基","埃其亚基的皮","瑟格拉·黑棘","白狮","白雾"},ang={["class:Hunter"]="身为猎人，你取下草原顶级潜猎者的毛皮，完成早期的一场成长试炼，并以部落追踪者的身份，领悟荒野的微妙之处。",["race:Tauren"]="身为牛头人，你在猎杀埃其亚基时，向白雾迅捷的灵魂致敬，这是一场考验仁慈与潜行技艺的神圣试炼，而非单纯的征服。"},sec={{t="白雾的战利品",b="埃其亚基在牛头人语中的意思是白雾。这头狮子凭借隐蔽的白色皮毛和迅捷的猎杀，在草原的捕食者中赢得了这个名字，猎物还来不及感到恐惧或痛苦，生命便已终结。猎人在十字路口东北方的巨大科多兽骸骨附近，用仪式号角召来这头行踪难觅的大猫，随后取下它的毛皮。将毛皮带给瑟格拉·黑棘，既证明了战斗技艺，也向白雾无声而仁慈的终结致敬。"}},faq={{q="埃其亚基的皮从何而来？",a="埃其亚基的皮来自白狮埃其亚基，它栖息在贫瘠之地十字路口东北方的巨大科多兽骸骨之间。瑟格拉·黑棘会提供埃其亚基的号角，用来召唤它。",al={"哪里获得埃其亚基的皮","如何获得埃其亚基的皮","埃其亚基毛皮位置"}},{q="谁想要埃其亚基的皮？",a="十字路口的兽人女猎手瑟格拉·黑棘想要埃其亚基的皮。她派初露头角的部落猎人追踪这头大猫，并带回它的毛皮，以证明他们与荒野的联系。",al={"埃其亚基的皮交给谁","交付埃其亚基的皮","谁需要埃其亚基的皮"}},{q="埃其亚基这个名字是什么意思？",a="埃其亚基在牛头人语中的意思是白雾。这个名字赞颂它浅色的毛皮，也寄托着这样的信念：它如流动的薄雾般穿行草原，猎杀时不会让恐惧或痛苦久久延续。",al={"埃其亚基译名","埃其亚基的含义","牛头人名字埃其亚基"}}},fp="16,228,19.447.0,38.203.0,27.197.0,34.196.0"}
P.entries["item:egalin-s-grimoire"] = {n="埃加林的魔典",s="在幽暗城，埃加林的魔典记载着召唤和控制虚空行者的仪式。一位术士大师撰写了这本书，作为诅咒神殿的教材。",h="在幽暗城，埃加林的魔典记载着召唤和控制虚空行者的仪式。一位术士大师撰写了这本书，作为诅咒神殿的教材。",kw={"凯伦丁·哈加尔","虚空生物","埃加林","埃加林的魔典","派瑞恩","诅咒神殿","虚空行者"},ang={["class:Warlock"]="身为术士，你可以通过埃加林的魔典学习从虚空召唤虚空行者，并使其服从你的意志。这是修习此道者的必经仪式。",["race:Undead"]="身为亡灵，取回这本书，就能让血色十字军无法继续持有这件从幽暗城施法者手中偷走的强大魔法神器。"},sec={{t="大师之作",b="埃加林的魔典记载了如何从虚空召来混沌生物。埃加林是一位召唤大师，以轻松驾驭虚空行者而闻名。他将这门技艺传授给了学生，其中就包括凯伦丁·哈加尔。没有书中的法术公式和引导方法，准备不足的召唤者可能会被自己召来的生物撕成碎片。"},{t="血色窃案",b="一名叫派瑞恩的血色十字军特工从被遗忘者术士手中偷走了魔典，并将它藏在提瑞斯法林地西部一座塔楼的箱子里。血色十字军憎恶黑暗魔法，然而派瑞恩似乎对这本书的真正意义知之甚少。这本典籍一直被当作查缴的异端物品，直到寻求掌控虚空的被遗忘者学徒将它取回。"}},faq={{q="埃加林是谁？",a="埃加林是一位才华出众的术士，也是凯伦丁·哈加尔的导师。他是他们之中第一个召唤出虚空行者的人，能够轻松驾驭混沌生物。",al={"埃加林是谁","埃加林的传说","魔典是谁写的"}},{q="埃加林的魔典为何如此危险？",a="埃加林的魔典记载着召唤虚空行者所需的咒语和引导方法。术士若未掌握这些要领就尝试举行仪式，便可能被召来的虚空生物撕成碎片。",al={"魔典有什么用","虚空行者魔典的危险","为何危险"}},{q="血色十字军是如何得到这本书的？",a="一名叫派瑞恩的血色十字军密探从被遗忘者术士手中偷走了这本典籍。他将书藏在提瑞斯法林地西部一座血色十字军哨塔的箱子里，似乎并不知道它真正的魔法价值。",al={"谁偷了书","派瑞恩魔典","血色十字军为何持有魔典"}},{q="谁需要取回这本魔典？",a="凯伦丁·哈加尔是幽暗城下方诅咒神殿中的术士训练师，他需要这本魔典来教导新学徒召唤和束缚虚空行者。",al={"谁需要魔典","谁交还埃加林的魔典","凯伦丁·哈加尔的书"}}},fp="17,160,15.337.0,17.369.1,15.152.0,38.221.0,41.216.0,33.161.0"}
P.entries["item:electropeller"] = {n="导电器",s="在黑海岸，维兹班恩·曲针的一次夜间外出以失败告终，他的导电器也散落在了淡水河流中。",h="在黑海岸，维兹班恩·曲针的一次夜间外出以失败告终，他的导电器也散落在了淡水河流中。",kw={"奥伯丁","壁泉河","黑海岸","诱饵鸭","电动推进器","急弯河","维兹班恩·曲针"},ang={["profession:Engineering"]="对工程师而言，electropeller展现了侏儒工程学的雄心与风险。维兹班恩·曲针设计它来驱动爆炸诱饵鸭，可还没来得及正式测试，它就掉进了河里。",["race:Gnome"]="身为侏儒，你或许能理解维兹班恩·曲针在技术上的大胆抱负。他请路过的垂钓者帮忙打捞那些深夜实验的成果。"},sec={{t="河畔的意外",b="维兹班恩·曲针制造了导电器，用来驱动一种试验性的爆炸诱饵鸭。这位侏儒发明家在奥伯丁工作。他喝多了酒，在勘察黑海岸的水道时失去了知觉。几个小时后，他醒了过来，头发被烧焦了，背包也空了。他的导电器掉进了黑海岸的淡水水流中，至今仍散落在河流和湖泊里，等待有耐心的垂钓者将它们打捞上来。"}},faq={{q="电驱动器有什么用途？",a="维兹班恩·曲针设计电驱动器，是为了驱动他在黑海岸研制的一种试验性自推进爆炸诱饵鸭。",al={"导电器用途","导电器有什么用","为什么用诱饵鸭"}},{q="这些零件是怎么掉进黑海岸的河流里的？",a="维兹班恩·曲针喝多了酒，夜间在黑海岸勘察时失去了知觉。几个小时后，他醒了过来，头发被烧焦了，背包也空了；他的电驱动器已经掉进了淡水水流中。",al={"为什么在水里","导电器怎么丢的","曲针的失误"}},{q="在哪里能找回电驱动器？",a="垂钓者可以从黑海岸的淡水水域中打捞到电驱动器，包括壁泉河和急弯河。",al={"哪里能钓到导电器","导电器位置","壁泉河钓鱼"}},{q="谁想要找回这些零件？",a="奥伯丁的侏儒维兹班恩·曲针想要找回十二个电驱动器，以便继续研究他的诱饵鸭。",al={"谁需要导电器","曲针是谁","奥伯丁侏儒任务"}}},fp="13,99,27.427.0,34.139.0,54.213.0,38.126.0,36.118.0"}
P.entries["item:elixir-of-pain"] = {n="痛苦药剂",s="塔伦米尔的被遗忘者药剂师调制痛苦药剂，用于危险的实验。这种混合药剂用于测试生物制剂，以推进希尔瓦娜斯更为阴暗的野心。",h="塔伦米尔的被遗忘者药剂师调制痛苦药剂，用于危险的实验。这种混合药剂用于测试生物制剂，以推进希尔瓦娜斯更为阴暗的野心。",kw={"药剂师","痛苦药剂","农夫雷恩","希尔斯布莱德农场","皇家药剂师学会","斯坦利","希尔瓦娜斯","塔伦米尔"},ang={["faction:Horde"]="在这些阴森的试验中，被遗忘者的盟友可能会目睹塔伦米尔研究者令人不安的手段。",["race:Undead"]="皇家药剂师学会冷酷无情的实地试验表明，被遗忘者愿意不择手段地研制对付活人的化学武器。"},sec={{t="药剂师的实验",b="皇家药剂师学会寻求各种配方，以增强被遗忘者对抗周边凡人和天灾军团的力量。痛苦药剂就是其中一项试验，用希尔斯布莱德丘陵各处新近采集的材料制成。对制作者而言，活体实验对象无足轻重；这瓶药剂用于测试不稳定的物质，以助黑暗女王一臂之力。"},{t="在斯坦利身上实地试验",b="药剂师们希望先悄悄进行一次试验，再考虑动用军事资源，或让希尔斯布莱德的守军察觉他们的研究。他们把痛苦药剂喂给斯坦利，它是希尔斯布莱德农场北部农庄里农夫雷恩养的一条看似无害的家犬。这瓶药剂并没有让它悄然死去。它使斯坦利变异成了一头狂怒的可怕野兽。"}},faq={{q="痛苦药剂有什么用途？",a="痛苦药剂用于为皇家药剂师学会测试生物化合物。制作者希望这些混合物最终能为希尔瓦娜斯带来极具破坏力的药剂，确保被遗忘者的统治地位。",al={"为何制造痛苦药剂","药剂用途","药剂有什么作用"}},{q="斯坦利是谁？",a="斯坦利是农夫雷恩的宠物犬，住在希尔斯布莱德农场北部的农庄。被遗忘者药剂师选中了这条看似无害的家犬，让它在毫不知情的情况下成为新药剂的实验对象。",al={"斯坦利是谁","农夫雷恩的狗","小狗斯坦利"}},{q="为什么要在斯坦利身上测试药剂？",a="药剂师林度恩想实地测试新调制的药剂，于是把药剂送去给农夫雷恩的小狗斯坦利，看看这只动物会有什么反应。",al={"斯坦利会发生什么","斯坦利会死吗","斯坦利变狼"}},{q="药剂在哪里测试？",a="试验地点在希尔斯布莱德农场北部农夫雷恩的农舍外，位于塔伦米尔西南方。斯坦利通常在前廊附近休息。",al={"药剂送到哪里","斯坦利位置","农夫雷恩的农场"}}},fx={["5a45fd3d"]={q="什么是痛苦药剂？",a="痛苦药剂是为被遗忘者在希尔斯布莱德丘陵的战争行动酿制的实验性炼金混合剂。它以新鲜采集的血液和不稳定试剂调制而成，是皇家药剂师协会为希尔瓦娜斯女士研制黑暗瘟疫和毒素的早期原型。",al={"什么是痛苦药剂","痛苦药剂物品","痛苦药水"}},["52862df0"]={q="痛苦药剂来自哪里？是谁制作的？",a="这剂药水是在被遗忘者的塔伦米尔据点酿制的。药剂师会将从周边丘陵收集的新鲜生物血液与其他腐蚀性成分混合，意图制成一种剧毒武器，助黑暗女王征服这一地区。",al={"谁制作了痛苦药剂","痛苦药剂的制作者","痛苦药剂来自哪里"}}},fp="14,162,26.333.0,24.335.1,42.192.0,15.178.0,36.146.1,27.151.0"}
P.entries["item:elixir-of-suffering"] = {n="受难药剂",s="在塔伦米尔，药剂师林度恩为皇家药剂师学会调制一种实验药剂。这项工作旨在研制一种能对付活人和天灾军团的烈性瘟疫。",h="在塔伦米尔，药剂师林度恩为皇家药剂师学会调制一种实验药剂。这项工作旨在研制一种能对付活人和天灾军团的烈性瘟疫。",kw={"药剂师林度恩","受难药剂","被遗忘者瘟疫","希尔斯布莱德丘陵","皇家药剂师学会","塔伦米尔","乌比"},ang={["race:Undead"]="在洛丹伦各地，皇家药剂师学会致力于制造一种武器，确保被遗忘者能够独立于Scourge和活着的人类。林度恩在塔伦米尔的实验，是这项工作中的一步。"},sec={{t="药剂师的实验",b="药剂师林度恩从破败的塔伦米尔周围的荒野中收集原料，将它们配制成有毒的药剂。这项工作遵循皇家药剂师学会的总体方针：研制一种能将生者与死者一并消灭的新瘟疫。为了测试药剂的效力，林度恩将它喂给自己的助手，一只名叫乌比的青蛙。"}},faq={{q="受难药剂有什么用途？",a="药剂师林度恩调制这种药剂，是为皇家药剂师学会进行的一项实验。该组织打算用新瘟疫消灭活人和天灾军团。",al={"为何制作受难药剂","药剂有什么作用","受难药剂的用途"}},{q="乌比是谁？",a="乌比是药剂师林度恩在塔伦米尔饲养的一只青蛙。虽然被戏称为他的助手，乌比却在毫不知情的情况下，成了新配制的炼金毒药的试验对象。",al={"青蛙是谁","蟾蜍是谁","林度恩的助手"}},{q="乌比喝下药剂后会发生什么？",a="乌比喝下受难药剂后，呱呱叫了几声，几乎立刻就被毒死了。这次试验表明，林度恩调制的药剂极其致命。",al={"乌比会死吗","蟾蜍会怎么样"}}},fx={["14f85f3d"]={q="什么是受难药剂？",a="受难药剂是皇家药剂师协会在塔伦米尔酿制的实验性混合剂。它是被遗忘者持续研制新型瘟疫的一部分，这种致命的混合物旨在给生者和亡灵都带来剧痛与死亡。",al={"什么是受难药剂","受难药剂背景","受难药剂有什么作用"}},fa4e475a={q="受难药剂来自哪里？是谁制造的？",a="这种药剂由药剂师林度恩调制，他驻扎在希尔斯布莱德丘陵的塔伦米尔。林度恩代表皇家药剂师协会和希尔瓦娜斯·风行者，在丘陵各地收集当地材料，用以配制并改良这种致命药剂。",al={"谁制造了受难药剂","受难药剂的制造者","受难药剂来自哪里"}},["1d085d8d"]={q="药剂师林度恩为什么想制造受难药剂？",a="药剂师林度恩调制这种药剂，是为了实现黑暗女王的宏图：制造一种威力强大的武器，足以消灭天灾军团和人类。他在当地受试者身上测试药剂的致命性，确保药剂能带来极度折磨和迅速死亡。",al={"为什么制造受难药剂","受难药剂的用途","林度恩为什么要这种药剂"}}},fp="19,159,26.309.0,47.155.0,12.158.0,41.145.1"}
P.entries["item:elune-s-tear"] = {n="月神之泪",s="在灰谷中央的岛屿上，月神之泪为暗夜精灵治疗者提供了净化腐化与疾病的神圣力量。",h="在灰谷中央的岛屿上，月神之泪为暗夜精灵治疗者提供了净化腐化与疾病的神圣力量。",kw={"灰谷","阿斯特兰纳","治愈","月神之泪","伊瑞斯湖","奥雷迪尔","皮尔图拉斯","蕾拉"},ang={["class:Priest"]="身为牧师，你认得这块石头净除暗影与腐朽的力量。它的治疗之力体现了那些被认为出自Priesthood of Elune的治愈奇迹。",["race:NightElf"]="身为暗夜精灵，你知道冠以Elune之名的遗物都是神圣的恩赐。用这块石头拯救无辜孩童，体现了kaldorei与月亮母亲治愈恩典之间的纽带。"},sec={{t="神圣的净化之石",b="月神之泪位于阿斯特兰纳以东、伊瑞斯湖中的一座小岛上。暗夜精灵相信，这块石头蕴含着月亮女神的纯净之力。腐化已将湖水染绿，扭曲的沼泽兽在湖岸徘徊。当地的草药师和治疗者，包括奥雷迪尔·阔叶，都在寻求这块石头，以便在普通林地草药敷剂无法清除深重腐化时，用它应急救治。"},{t="绝境中的良药",b="阿斯特兰纳的年轻暗夜精灵蕾拉·怀特姆恩患上了一种神秘的消耗性疾病。她的父亲皮尔图拉斯用尽了寻常药物。在药剂师奥雷迪尔的建议下，皮尔图拉斯寻找月神之泪，准备用它熬制恢复元气的炖汤。这块石头为对抗怪病带来了眼前的希望，但灰谷顽固的腐化往往需要更强大的净化仪式。"}},faq={{q="什么是月神之泪？",a="月神之泪是一种稀有的魔法矿石，位于灰谷伊瑞斯湖中的一座岛上。暗夜精灵将它视为属于艾露恩的圣物，用它净化非自然的腐化和致命的疾病。",al={"月神之泪","这块石头是什么","月神之泪的作用"}},{q="在哪里能找到月神之泪？",a="月神之泪位于灰谷中部、阿斯特兰纳以东的伊瑞斯湖中央岛屿上。从大路沿溪流旁的小径向北走，即可抵达。",al={"月神之泪在哪里","伊瑞斯湖石头位置","寻找月神之泪"}},{q="皮尔图拉斯·怀特姆恩为什么需要月神之泪？",a="皮尔图拉斯寻找月神之泪，是为了救治患病的女儿蕾拉。寻常草药无法治愈她的怪病，药剂师奥雷迪尔便建议他借助这块石头的恢复之力。",al={"皮尔图拉斯为何需要它","治愈蕾拉","谁需要月神之泪"}},{q="什么守卫着伊瑞斯湖中的石头？",a="扭曲的沼泽兽在伊瑞斯湖岸边徘徊，灰谷蔓延的腐化已将湖水染绿。",al={"伊瑞斯湖敌人","什么守护月神之泪"}}},fp="12,104,24.355.0,18.370.1,21.176.0,32.160.0,42.195.0,35.119.0"}
P.entries["item:embalming-ichor"] = {n="防腐剂",s="在提瑞斯法北部，腐皮豺狼人携带着一种能保存其腐烂躯体的液体。被遗忘者的药剂师希望研究这种液体，用来对抗 天灾军团。",h="在提瑞斯法北部，腐皮豺狼人携带着一种能保存其腐烂躯体的液体。被遗忘者的药剂师希望研究这种液体，用来对抗 天灾军团。",kw={"药剂师","布瑞尔","防腐剂","加伦鬼屋","盗墓者","执政官塞弗伦","乱葬岗","腐皮"},ang={["profession:Herbalism"]="作为一名草药师，你在研究黑暗炼金术和瘟疫试剂时，或许会对腐皮体内的防腐液产生兴趣。",["race:Undead"]="作为被遗忘者，你阻止 Scourge 从乱葬岗获取新鲜尸体，帮助保护提瑞斯法，并为自身的生存取得原料。"},sec={{t="非自然的防腐之法",b="加伦鬼屋及附近乱葬岗的腐皮豺狼人是腐烂的奴仆，受 天灾军团 派遣，挖掘死于瘟疫之人的遗体。防腐剂在它们腐朽的血管中流淌，保存着它们的血肉，维持着它们的亡灵之躯。布瑞尔的执政官塞弗伦想要从这些盗墓者身上收集几瓶防腐剂。皇家药剂师学会将用新鲜样本研究这种液体，寻找用它对付巫妖王爪牙的方法。"}},faq={{q="什么是防腐剂？",a="防腐剂是一种存在于提瑞斯法林地腐皮豺狼人活动躯体内的防腐液。它维持着这些豺狼人腐烂的血肉，让它们能够继续为 天灾军团 效力。",al={"防腐剂","什么是防腐液","豺狼人液体"}},{q="谁要求收集这种液体？",a="布瑞尔的执政官塞弗伦命令被遗忘者的勇士从被杀死的腐皮身上收集这种液体，供皇家药剂师学会研究。",al={"谁需要防腐剂","执政官塞弗伦防腐液","谁想要防腐液"}},{q="腐皮豺狼人为什么要挖掘坟墓？",a="天灾军团 派遣腐皮豺狼人挖掘埋葬在加伦鬼屋附近北部乱葬岗中的瘟疫死者，寻找尸体来扩充兵力。",al={"豺狼人为何盗墓","提瑞斯法 乱葬岗","豺狼人与 天灾军团 的关系"}},{q="被遗忘者打算如何使用这种液体？",a="幽暗城的药剂师研究这种液体，寻找对抗 天灾军团 的方法和新的炼金配方。",al={"塞弗伦 如何使用防腐液","药剂师研究防腐液","防腐剂的用途"}}},fp="15,153,22.452.0,24.165.0,31.133.0,46.154.0,47.114.0"}
P.entries["item:emerald-dreamcatcher"] = {n="翡翠摄梦符",s="在星风村，瘤背熊怪赶走了村民，翡翠摄梦符也被遗忘在那里。班奈希尔兽穴的德鲁伊将它赠予塔隆凯·捷根，希望它能从翡翠梦境中汲取活力。",h="在星风村，瘤背熊怪赶走了村民，翡翠摄梦符也被遗忘在那里。班奈希尔兽穴的德鲁伊将它赠予塔隆凯·捷根，希望它能从翡翠梦境中汲取活力。",kw={"班奈希尔兽穴","多兰纳尔","翡翠摄梦符","熊怪","盖洛拉斯·塔文斯伦","星风村","塔隆凯·捷根","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你能看出这枚护符如何将Ban’ethil Barrow Den中沉睡的德鲁伊与下方的Kaldorei聚居地联系起来，借助他们与翡翠梦境的交融传递援助。",["race:NightElf"]="身为暗夜精灵，寻回这件圣物，是对抗蔓延病患的一场小小胜利，这病患正侵吞星风村和泰达希尔周围的枝桠。"},sec={{t="来自班奈希尔的礼物",b="盖洛拉斯·塔文斯伦是班奈希尔兽穴的德鲁伊守护者，他监督了翡翠摄梦符的制作。德鲁伊只将这种附魔护符赠予少数获选之人。它从翡翠梦境中汲取周围的能量，为携带者带来好运与庇护。发狂的瘤背熊怪攻占星风村时，护符仍留在一个衣柜里，被困在充满敌意、遭到腐化的地域中。"}},faq={{q="翡翠摄梦符有什么作用？",a="塔隆凯·捷根说，这枚护符能从翡翠梦境中汲取原始能量，为拥有者带来好运与活力。塞纳里奥德鲁伊视它为难得的恩宠信物。",al={"翡翠摄梦符的力量","摄梦符有什么用","摄梦符的传说"}},{q="谁制作了翡翠摄梦符？",a="盖洛拉斯·塔文斯伦是德鲁伊守护者，照看着班奈希尔兽穴中沉睡的塞纳里奥议会成员，他将翡翠摄梦符赠予了塔隆凯。",al={"谁制作了摄梦符","谁把摄梦符给了塔隆凯"}},{q="为什么摄梦符会被留在星风村？",a="塔隆凯将护符放在星风村家中的衣柜里。当地的瘤背熊怪被腐化吞噬，变得狂暴，他还没来得及取回护符，村民就不得不放弃这处聚居地。",al={"塔隆凯为什么留下它","摄梦符遗失在哪里"}},{q="星风村的熊怪为什么充满敌意？",a="遍布泰达希尔的瘤背部族已遭到一股不断蔓延的黑暗力量腐化，族人因此陷入狂暴，四处攻击。暗夜精灵被迫逃离星风村等偏远聚居地。",al={"星风为何陷落","星风村熊怪"}}},fp="20,238,21.399.0,38.189.0,34.151.0,59.204.0,51.197.0"}
P.entries["item:empty-blue-waterskin"] = {n="空的蓝色水囊",s="布瑞恩让人带着空的蓝色水囊，从贫瘠之地北上采集圣水。这些水将帮助她调配用于召唤并安抚水之灵的药剂。",h="布瑞恩让人带着空的蓝色水囊，从贫瘠之地北上采集圣水。这些水将帮助她调配用于召唤并安抚水之灵的药剂。",kw={"灰谷","贫瘠之地","布瑞恩","水之召唤","空的蓝色水囊","星尘废墟","水之图腾"},ang={["class:Shaman"]="身为萨满祭司，携带并灌满水囊，是你掌握水之灵力量的关键一步。制作你永久使用的水之图腾，需要用到囊中的纯净之水。",["faction:Horde"]="身为部落的一员，你必须从贫瘠之地出发，进入灰谷西部充满敌意的暗夜精灵领地取水。"},sec={{t="神圣的容器",b="布瑞恩在南贫瘠之地山顶的小屋里，将空的蓝色水囊交给一名萨满祭司学徒。这个容器意味着，初期训练中最后也是最危险的采集任务开始了。为了与水之灵沟通，学徒必须在卡利姆多各地寻找纯净、未受侵扰的水源。这个水囊要装的水，来自灰谷争夺不休的边境地带，星尘废墟深处一座隐蔽的喷泉。"},{t="林中喷泉",b="学徒必须离开安全的部落领地，前往由自然野兽和暗夜精灵守护的古老林地。在星尘废墟深处残破圣所的一座喷泉旁，水囊被灌满，成为装满水的蓝色水囊。配合从贫瘠之地和塔伦米尔采集的水样，囊中的水能让布瑞恩调配出用于召唤并安抚水元素之灵的药剂。"}},faq={{q="空的蓝色水囊有什么用途？",a="空的蓝色水囊用于将灰谷星尘废墟深处的喷泉之水带回布瑞恩那里，供她调配纯水药剂。",al={"空的蓝色水囊有什么作用","空的蓝色水囊用途","为什么有空的蓝色水囊"}},{q="谁会给你这个水囊？",a="布瑞恩会在她位于南贫瘠之地的小屋里将水囊交给你，那里在陶拉祖营地以南，靠近剃刀边界。",al={"谁给空的蓝色水囊","蓝色水囊哪里获得"}},{q="必须在哪里灌满水囊？",a="在灰谷西南部星尘废墟深处的中央喷泉灌满水囊，那里就在密斯特拉湖的另一侧，靠近石爪山山脊。",al={"空的蓝色水囊在哪里灌满","蓝色水囊位置","在哪里灌满"}},{q="布瑞恩为什么需要灰谷的水？",a="布瑞恩想要调配出卡利姆多已知最纯净的一瓶水。暗夜精灵废墟中未受侵扰的神圣泉源，提供了与水元素之灵沟通所需的最后一种纯净材料。",al={"为什么要灰谷的水","为什么要星尘废墟的水"}}},fp="20,175,15.406.0,19.413.0,42.163.0,29.113.0,35.152.0,41.209.0"}
P.entries["item:empty-brown-waterskin"] = {n="空的棕色水囊",s="在贫瘠之地，布瑞恩将一个空水囊交给一名萨满祭司学徒。",h="在贫瘠之地，布瑞恩将一个空水囊交给一名萨满祭司学徒。",kw={"贫瘠之地","布瑞恩","水之召唤","野猪人","灵契","萨满祭司","水囊"},ang={["class:Shaman"]="身为萨满祭司，携带这个水囊是你获得水之图腾途中必须经历的一场试炼。它体现了对元素的敬畏与艰苦求生之间的平衡。"},sec={{t="匮乏中的一课",b="布瑞恩将一个空皮水囊交给一名萨满祭司学徒，用于水之召唤的第一项试炼。学徒必须带着它前往她住处下方的水池，装满水后返回。当地的野猪人十分珍视池中的水，守卫着这处水源。在缺水的贫瘠之地，即使一小片绿洲也能维系生命，引发争斗。"}},faq={{q="空的棕色水囊有什么用途？",a="萨满祭司学徒用这个空水囊，从贫瘠之地布瑞恩小屋下方的天然池塘中取水。装满水后，它便是制备元素 灵契 所需的物品。",al={"水囊用途","棕色水囊有什么用","空的棕色水囊用途"}},{q="这个水囊由谁提供？",a="隐居在南贫瘠之地的布瑞恩，会将水囊交给踏上元素朝圣之旅、寻求与水之灵沟通的萨满祭司。",al={"谁提供水囊","棕色水囊任务给予者","哪里获得空水囊"}},{q="野猪人为什么守卫水源？",a="贫瘠之地各处都鲜有降雨，水源匮乏。对野猪人而言，即使一处小水池也意味着财富和生存，因此他们守卫着它，攻击任何前来取水的人。",al={"野猪人为什么攻击","野猪人与水","水池为什么有守卫"}},{q="水囊装满后会怎样？",a="将水囊浸入布瑞恩所在山丘下方的绿洲水中，它就会变成装满水的棕色水囊。把它带回布瑞恩那里，她便会考验你对自然平衡的理解，之后再派你远赴世界各地，寻找更稀有的水。",al={"装满水后做什么","交还水囊","装满水的棕色水囊交给谁"}}},fp="21,67,20.333.0,43.140.0,28.148.0,48.184.0,37.217.0"}
P.entries["item:empty-cleansing-bowl"] = {n="空的净化碗",s="在奥伯丁，空的净化碗盛装月亮井水，用来对抗黑木熊怪的腐化。井水与食物样本混合后制成的餐食，能短暂解除萨特对熊怪的恶魔控制。",h="在奥伯丁，空的净化碗盛装月亮井水，用来对抗黑木熊怪的腐化。井水与食物样本混合后制成的餐食，能短暂解除萨特对熊怪的恶魔控制。",kw={"奥伯丁","黑木","净化碗","黑海岸","空的净化碗","月亮井","桑迪斯·织风","萨巴克希斯"},ang={["class:Druid"]="身为德鲁伊，运用月亮井水解除违背自然的病痛，正体现了你在黑海岸修复受损的自然平衡的使命。",["race:NightElf"]="对暗夜精灵而言，这场净化仪式表明，Elune的月亮井能够消除恶魔的污染，也让他们看到挽救昔日熊怪盟友的希望。"},sec={{t="净化之器",b="桑迪斯·织风将空的净化碗交给奥伯丁的冒险者，用来盛装当地月亮井中的圣水。暗夜精灵发现，萨特利用施过魔法的护符，让北方的黑木熊怪陷入恶魔般的疯狂。将碗浸入月亮井，再把井水与从熊怪那里收集的坚果、谷物和水果混合。这份受祝福的餐食能让受影响的生物短暂恢复理智，并使幕后操纵它们的萨特监工现身。"}},faq={{q="空的净化碗该怎么用？",a="将碗带到奥伯丁的月亮井，浸入受祝福的井水中，就能得到装满水的净化碗。然后从北方的黑木熊怪营地收集谷物、坚果和水果样本，与碗中的井水混合。",al={"空的净化碗用法","如何使用空的净化碗","在哪里装满净化碗"}},{q="暗夜精灵为什么需要用这只碗来对抗熊怪的腐化？",a="萨特的护符以黑暗魔法束缚着黑木熊怪。桑迪斯·织风用这只碗盛装神圣的混合物，短暂平息它们的狂乱，并引出藏在幕后的操纵者萨巴克希斯。",al={"为什么需要净化碗","净化碗用途"}},{q="谁会提供空的净化碗？",a="桑迪斯·织风是奥伯丁的一位暗夜精灵学者，他请你查明壁泉河沿岸黑木熊怪腐化的源头时，会将碗交给你。",al={"谁提供净化碗","净化碗任务给予者"}},{q="混合物准备好之后会发生什么？",a="将准备好的混合物放在北方营地的篝火旁。它会暂时净化附近的熊怪，足以激起萨巴克希斯的怒火，让你有机会杀死这个萨特，夺取他的堕落护符。",al={"净化碗篝火","放置净化碗"}}},fp="20,209,24.479.0,43.211.0,70.206.1,38.169.0,42.193.1"}
P.entries["item:empty-cliffspring-falls-sampler"] = {n="空的峭壁之泉取样器",s="在黑海岸的峭壁之泉，年轻的德鲁伊采集泉水，调查导致当地野生动物死亡的毒素。塞纳里奥议会发给他们空采样器，用来采集洞口的水。",h="在黑海岸的峭壁之泉，年轻的德鲁伊采集泉水，调查导致当地野生动物死亡的毒素。塞纳里奥议会发给他们空采样器，用来采集洞口的水。",kw={"奥兰达利亚·夜歌","塞纳里奥议会","峭壁之泉","消毒术","黑海岸","德迪利特·星焰","采样器"},ang={["class:Druid"]="身为德鲁伊，你要前往纳迦占据的洞穴采集水样，完成这项入门试炼，然后学习Cure Poison。",["race:NightElf"]="身为暗夜精灵，你知道纳迦正在污染黑海岸森林中的水源，威胁着野生动物和奥伯丁。"},sec={{t="调查受污染的水源",b="峭壁之泉滋养着黑海岸北部，因此源头一旦出事，当地的野生动物就会受到威胁。当一种使身体日渐衰弱的毒素开始导致这一带的鹿死亡时，塞纳里奥议会的德迪利特·星焰将空采样器交给了从月光林地派来的年轻德鲁伊。他们必须抵达泉水旁的峭壁，在被敌对纳迦占据的洞穴入口采集水样。"},{t="解毒的配方",b="奥兰达利亚·夜歌在奥伯丁接收装满水样的采样器。受污染的水证实，有邪恶势力正在向地下水中投毒。通过研究污染，奥兰达利亚和塞纳里奥德鲁伊能够配制解毒剂，并向初学者传授基本的德鲁伊治疗仪式。"}},faq={{q="这个采样器有什么用途？",a="德鲁伊用空采样器采集黑海岸峭壁之泉洞口受污染的水。水样能帮助塞纳里奥草药师查明危害当地野生动物的毒素，并找到解毒的方法。",al={"采样器用途","峭壁之泉采样器有什么用","空采样器用途"}},{q="在哪里采集水样？",a="水样采自峭壁之泉附近的洞口，那里位于黑海岸东北部的高处山地。敌对的纳迦守卫着入口。",al={"在哪里装满采样器","峭壁之泉采样器位置","采样器装水地点"}},{q="装满水样的容器交给谁？",a="装满水样的采样器要交给奥兰达利亚·夜歌，她是驻守奥伯丁的暗夜精灵治疗者，也是塞纳里奥议会的代表。",al={"装满的采样器交给谁","在哪里交采样器","奥兰达利亚采样器"}},{q="为什么在峭壁之泉采样，而不是其他河流？",a="峭壁之泉是黑海岸北部的主要淡水来源。德迪利特·星焰追查导致这一带鹿群死亡的病症，将源头锁定在这片水源，因此需要直接采集水样来研制解药。",al={"为什么是峭壁之泉","什么在毒害黑海岸","峭壁之泉毒素"}}},fp="31,185,32.333.0,19.295.1,36.199.0,32.147.0,34.125.0,63.208.0"}
P.entries["item:empty-dreadmist-peak-sampler"] = {n="空的鬼雾峰取样器",s="在鬼雾峰，德鲁伊们要用一个空的塞纳里奥容器采集受污染的水。这份样本或许能帮助他们查明并治愈正在贫瘠之地北部野生动物间蔓延的疫病。",h="在鬼雾峰，德鲁伊们要用一个空的塞纳里奥容器采集受污染的水。这份样本或许能帮助他们查明并治愈正在贫瘠之地北部野生动物间蔓延的疫病。",kw={"贫瘠之地","火刃氏族","德迪利特·星焰","鬼雾峰","空的鬼雾峰取样器","主要源头","图加·符文图腾"},ang={["class:Druid"]="作为一名德鲁伊，用这个容器采集样本，是你学习解毒、诊断并减轻荒野生灵苦痛的一部分。",["faction:Horde"]="作为部落的一员，你带着这个取样器，协助十字路口的图加·符文图腾，阻止贫瘠之地北部平原的生态继续衰败。"},sec={{t="追查疫病",b="德迪利特·星焰怀疑，鬼雾峰顶的水池正是那场侵害瞪羚、令贫瘠之地北部不得安宁的疫病的根源。这些水池影响着天气，这位德鲁伊担心它们与不断蔓延的疫病有关。他派德鲁伊学徒带着空的取样器，冒险登上高山，从峰顶取水。如今，崇拜恶魔的邪教火刃氏族盘踞在这座山上。"},{t="关键的样本",b="德鲁伊们带着空的取样器登上鬼雾峰，从山上的水池中采集水样。他们将样本交给十字路口的图加·符文图腾，帮助他研制解药，保护当地的野生动物。"}},faq={{q="空的鬼雾峰取样器有什么用途？",a="空的鬼雾峰取样器是一个空容器，也是德鲁伊用来从鬼雾峰顶受污染的水池中取水的专用塞纳里奥容器。他们将样本带给图加·符文图腾，帮助他为患病的野生动物研制解药。",al={"这个物品有什么用","鬼雾峰取样器用途","为什么有这个取样器"}},{q="这个取样器需要带到哪里？",a="将取样器带到贫瘠之地十字路口西北方的鬼雾峰顶，在高处的水池中采集一份水样。",al={"在哪里装满取样器","取样器位置","如何装满空的鬼雾峰取样器"}},{q="谁提供这个取样器？",a="德迪利特·星焰代表塞纳里奥议会提供取样器，随后派这位德鲁伊去与图加·符文图腾协作。",al={"谁提供取样器","谁发起了这个任务"}},{q="为什么采集鬼雾峰的水样如此重要？",a="鬼雾峰顶的水池影响着这一带的天气和雾气。火刃氏族邪教腐化了峰顶，受污染的水流遍平原，毒害当地的生物。",al={"为什么是鬼雾峰水池","水为什么受到污染"}}},fp="28,165,18.362.0,18.213.1,56.217.0,41.124.0,25.133.0,58.188.0"}
P.entries["item:empty-leaden-collection-phial"] = {n="空铅瓶",s="奥齐·电环用铅瓶收集诺莫瑞根的放射性尘埃。他希望这些残留物能帮助治愈患病的同胞，或是酿出烈性十足的酒。",h="奥齐·电环用铅瓶收集诺莫瑞根的放射性尘埃。他希望这些残留物能帮助治愈患病的同胞，或是酿出烈性十足的酒。",kw={"空铅瓶","放射性尘埃","诺恩","诺莫瑞根","卡拉诺斯","铅瓶","奥齐·电环","辐射"},ang={["profession:Engineering"]="这只铅瓶将重金属防护层与抽吸装置结合起来，以安全收集环境中不稳定的微粒。它是一件实用的侏儒工程装置。",["race:Gnome"]="对流亡的侏儒而言，诺莫瑞根的毁灭仍是一道未愈的伤口。无论研究者多么古怪，任何试图消除有毒放射性尘埃影响的尝试，都与他们切身相关。"},sec={{t="有防护的容器",b="奥齐·电环制作了一只铅瓶，用来收集诺莫瑞根残留的辐射。为了清除穴居人的威胁，这座城市的通风系统曾向隧道中排放大量有毒辐射。幸存的守卫变成了麻风侏儒，入侵的野兽也受到了辐射。\n\n游荡在废墟中的辐射入侵者和抢劫者身上，至今仍泛着绿光。铅瓶吸入危险的残留物时，铅层能保护持瓶者。密封后，它就成了装满的铅瓶，供奥齐进行实验。"}},faq={{q="这只瓶子有什么用途？",a="这只瓶子用来收集诺莫瑞根地表隧道附近的辐射入侵者和辐射抢劫者身上的放射性尘埃。将收集的物质密封在瓶内后，它就成了供研究使用的装满的铅瓶。",al={"瓶子有什么用","空铅瓶怎么用","瓶子的用途"}},{q="为什么要用铅制作这只瓶子？",a="铅能保护持瓶者，抵挡诺莫瑞根致命的放射性尘埃。缺少防护的生物可能患上严重的放射病，侏儒则可能变成麻风侏儒。",al={"为什么用铅瓶","为什么用铅"}},{q="这件收集装置是谁制作的？",a="这只瓶子由侏儒工匠奥齐·电环制作。他在丹莫罗的卡拉诺斯工作，将瓶子交给那些愿意冒险前往诺莫瑞根有毒外围地区的人。",al={"谁制作了瓶子","奥齐·电环的瓶子","谁给了我这只瓶子"}},{q="奥齐希望用收集到的放射性尘埃做什么？",a="奥齐和他的伙伴拉兹希望利用收集到的放射性尘埃，研制出治愈灾难中患病的麻风侏儒的解药。奥齐也承认，他们的配方或许会变成烈性朗姆酒，或是治疗秃头的药。",al={"为什么收集放射性尘埃","诺恩的用途","奥齐在制作什么"}}},fx={["8d10cd55"]={q="空铅瓶是什么？",a="这是一种沉重、带有屏蔽防护的容器，专门用来从游荡在诺莫瑞根废墟中的受污染生物身上收集放射性沉降物，并安全地储存它们。瓶身由厚铅制成，保护携带者免受那危险的翠绿色光芒伤害，让侏儒研究者能够采集有毒残留物，而不染上那种令这座陷落之城发生异变的疾病。",al={"空铅瓶是什么","铅制收集瓶","空铅瓶诺莫瑞根"}}},fp="29,173,17.509.0,27.207.0,30.178.0,35.159.0,59.218.0"}
P.entries["item:empty-red-waterskin"] = {n="空的红色水囊",s="在塔伦米尔，空的红色水囊将用来盛取一口未受瘟疫污染的水井中的水。布瑞恩将它交给萨满祭司学徒，用于他们的元素试炼。",h="在塔伦米尔，空的红色水囊将用来盛取一口未受瘟疫污染的水井中的水。布瑞恩将它交给萨满祭司学徒，用于他们的元素试炼。",kw={"布瑞恩","水之召唤","空的红色水囊","希尔斯布莱德丘陵","塔伦米尔","水之灵契"},ang={["class:Shaman"]="作为萨满祭司，你携带并装满这个水囊，迈出掌握水之图腾的第一步，让自己的感官与水中坚韧的元素之灵相通。",["race:Orc"]="作为兽人，你听到布瑞恩将塔伦米尔的纯净水井比作大酋长萨尔，他历经巨大的苦难，依然是力量与希望的灯塔。"},sec={{t="盛装纯净之水的容器",b="布瑞恩将这个朴素的红色水囊交给萨满祭司学徒，用于水之召唤试炼。他们带着它渡过大海，前往希尔斯布莱德丘陵的塔伦米尔。被遗忘者占据着这座城镇，但镇中央的水井依然涌出清冽的泉水。装满的水囊将水样带回布瑞恩手中，她用这些水调配出一瓶最纯净的水，供学徒试炼之用。"}},faq={{q="空的红色水囊有什么用途？",a="萨满祭司在水之召唤试炼中使用这个水囊，从塔伦米尔的水井中采集泉水。装入泉水后，它就变成了装满水的红色水囊。",al={"空的红色水囊用途","红色水囊怎么用"}},{q="谁提供这个水囊？",a="布瑞恩是一位隐居在贫瘠之地南部山丘上的兽人萨满祭司，她将水囊交给接受元素试炼的萨满祭司学徒。",al={"谁提供红色水囊","红色水囊任务给予者"}},{q="为什么偏偏要从塔伦米尔取水？",a="塔伦米尔由被遗忘者控制，但镇中央的水井仍未受到污染。布瑞恩认为，这眼纯净的泉水象征着希望与生命在这片亵渎之地依然延续。",al={"为什么取塔伦米尔的水","塔伦米尔水井的故事"}},{q="装满水囊后会发生什么？",a="在井边装满水囊后，你将它带回贫瘠之地，交给布瑞恩。她将囊中的水与其他珍稀水样混合，制成一瓶最纯净的水，水之先知伊斯伦用它来制作水之灵契。",al={"红色水囊下一步","装满水的红色水囊交给谁"}}},fp="19,143,23.347.0,41.140.0,28.131.0,47.156.0,43.210.0"}
P.entries["item:empty-sampling-tube"] = {n="空的水样试管",s="桑迪斯·织风在奥伯丁交给你一支空的水样试管，用来采集壁泉河的河水。暗夜精灵学者正在研究威胁黑海岸的污染。",h="桑迪斯·织风在奥伯丁交给你一支空的水样试管，用来采集壁泉河的河水。暗夜精灵学者正在研究威胁黑海岸的污染。",kw={"奥伯丁","壁泉河","黑海岸","空的水样试管","薄雾海","桑迪斯·织风","水样"},ang={["class:Druid"]="身为德鲁伊，你可以帮助查明费伍德森林的污染如何流入黑海岸的河流，并使当地野生动物染病。",["race:NightElf"]="身为奥伯丁的暗夜精灵，你可以帮助检验壁泉河的水质，防止受污染的径流毒害你在薄雾海畔的家园。"},sec={{t="检验水质",b="随着瘟疫在荒野中蔓延，黑海岸的水道正逐渐污浊。奥伯丁的调查员桑迪斯·织风交给你一支空玻璃试管，让你采集壁泉河的河水。在镇子北面第一道瀑布下方的水潭中取样。暗夜精灵博物学者会检验水样，了解正流向薄雾海的污染。"},{t="追查源头",b="黑木熊怪住在河岸沿线的营地中，但织风怀疑它们也深受腐化之害，只是在传播污染，而非造成污染。水样证实，污染来自东面费伍德森林遭到腐化的高地。这份样本或许有助于找到治愈方法，并指引直接应对瘟疫的行动。"}},faq={{q="空的水样试管有什么用途？",a="空的水样试管用于采集奥伯丁北面遭到污染的壁泉河水样。将水样带给桑迪斯·织风，让他研究正在黑海岸蔓延的污秽物质。",al={"为何持有这支试管","水样试管的作用","试管用途"}},{q="应该在哪里采集水样？",a="在奥伯丁北面壁泉河的第一道瀑布处装满试管。水潭上方横跨着一座桥，河水流过这里后便汇入薄雾海。",al={"试管装水地点","壁泉河位置","水样试管取样地点"}},{q="这支试管是谁提供的？",a="桑迪斯·织风将这支试管交给你。他是一位暗夜精灵博物学者，正在研究奥伯丁周边土地面临的威胁。",al={"试管提供者","试管任务给予者","桑迪斯·织风"}},{q="是什么污染了壁泉河？",a="黑木熊怪生活在河岸沿线，加重了河水的污浊，但污染源自东面高山上费伍德森林中遭到腐化的林地。",al={"河水变绿的原因","河水污染源","壁泉河污染"}}},fp="19,155,18.379.0,18.293.1,47.203.0,47.166.0,23.115.0,40.156.1"}
P.entries["item:empty-water-tube"] = {n="空水瓶",s="在奥伯丁，空水瓶已准备好盛取神圣的月亮井水，用于研究黑海岸东部峭壁上的红色水晶。",h="在奥伯丁，空水瓶已准备好盛取神圣的月亮井水，用于研究黑海岸东部峭壁上的红色水晶。",kw={"随着水流倾泻","奥伯丁","黑海岸","空水瓶","费伍德森林","月亮井","月亮井水瓶","红色水晶"},ang={["class:Druid"]="身为德鲁伊，你对月亮井怀有深深的敬意。你依靠纯净的井水研究异常现象，净化费伍德森林等腐化之地中的诡异扰动。",["race:NightElf"]="身为暗夜精灵，取用神圣的月亮井水是一项神圣职责。Kaldorei将月亮井视为受Elune祝福的圣水之池，深加敬奉。"},sec={{t="盛装圣水的容器",b="哨兵和学者正在寻找纯净的月之精华，以研究黑海岸东部山脊上的神秘红色水晶。普通玻璃器皿或药瓶可能污染圣水，因此前往奥伯丁月亮井的调查者会领到这个密封的小瓶，用于这项工作。他们将装好的井水带上山坡，观察这种异质矿物对艾露恩的魔法有何反应。"},{t="探查费伍德森林的阴影",b="费伍德森林位于黑海岸东部的群山之外，饱受恶魔腐化的毒害。奥伯丁的守卫怀疑，峭壁附近那块不祥的深红色巨石可能与那片遭到毁坏的森林有关。研究者希望将月亮井水倾洒在水晶的晶格上，揭示其内部结构，同时避免触发其中封存的力量，酿成灾难。"}},faq={{q="空水瓶有什么用途？",a="你在奥伯丁领取这个空容器，用它汲取当地的月亮井水，以分析黑海岸东部高地上的诡异红色水晶。",al={"空水瓶用途","为什么有空水瓶","水瓶有什么用"}},{q="应该在哪里装满水瓶？",a="将水瓶浸入奥伯丁的月亮井中，把它装满。装满月亮井水的瓶子会变成月亮井水瓶。",al={"哪里装满水瓶","哪里装满空水瓶","水瓶装水地点"}},{q="为什么研究水晶需要月亮井水？",a="月亮井水蕴含着艾露恩强大的净化魔法。学者认为，将井水浇在红色水晶上，就能发现有关其起源和成分的线索。",al={"为什么需要月亮井水","月亮井水对水晶有什么作用","红色水晶月亮井水"}},{q="奥伯丁的居民为什么担心水晶？",a="水晶位于俯瞰费伍德森林的高耸山脊附近，那片森林已被燃烧军团严重腐化。当地的守望者担心，水晶若与那片遭到污染的荒野有关，便可能威胁黑海岸。",al={"水晶危险吗","水晶危险黑海岸","为什么调查红色水晶"}}},fp="16,128,27.358.0,24.372.1,44.140.0,32.104.0,45.158.0,56.186.0"}
P.entries["item:enchanted-gaea-seeds"] = {n="附有魔法的盖亚之种",s="烈日石居正在为焦炭谷准备附有魔法的盖亚之种。德鲁伊的魔法赋予它们力量，使它们能在灰烬遍布的土壤中扎根，开始修复卡利姆多饱受摧残的大地。",h="烈日石居正在为焦炭谷准备附有魔法的盖亚之种。德鲁伊的魔法赋予它们力量，使它们能在灰烬遍布的土壤中扎根，开始修复卡利姆多饱受摧残的大地。",kw={"焦炭谷","附有魔法的盖亚之种","盖亚之种","重生","石爪山","烈日石居","塔姆拉·风语"},ang={["class:Druid"]="身为德鲁伊，你帮助维系重生的循环，引导坚韧的生命重返这片被毁灭与野火吞噬的土地。",["race:Tauren"]="身为烈日石居的一名Shu'halo，你种下附有魔法的种子，履行守护大地的精神职责，向Earth Mother致敬，并让受创的土地重获生机。"},sec={{t="灰烬中的火花",b="部落的德鲁伊正试图治愈遍布石爪山脉的深重创伤。在烈日石居，塔姆拉·荒原为未经处理的盖亚之种施加魔法，使它们能够抵御腐化与元素侵蚀。将它们种在焦炭谷烟灰下的肥沃土堆中，它们便能在这片恶劣的土地上扎根。敌对的火元素和入侵的鹰身人仍然盘踞在山谷中。"},{t="复苏的希望",b="播种是争取石爪山未来的一部分。这些种子附有魔法的外壳能抵御残留的腐化，让本土植物得以扎根。重新生长的植被有望安抚躁动的火元素，挤压野蛮鹰身人的生存空间，并弥补荆棘谷地精无休止的伐木造成的森林破坏。"}},faq={{q="附有魔法的盖亚之种有什么用途？",a="将种子种在焦炭谷的肥沃土堆中。它们有望长成坚韧的植物，抵御腐化，并开始治愈被烈火与战乱摧残的土地。",al={"盖亚之种用途","附有魔法的盖亚之种有什么作用","为什么种植盖亚之种"}},{q="是谁创造了这些种子，或为它们施加了魔法？",a="未经处理的盖亚之种从周围的荒野中采集而来，被送到烈日石居的塔姆拉·荒原手中。她为种子施加魔法，帮助它们在焦炭谷灰烬遍布的恶劣土壤中存活。",al={"种子是谁制作的","塔姆拉·荒原种子","盖亚之种如何制作"}},{q="为什么必须将它们种在焦炭谷？",a="焦炭谷是石爪山脉生态破坏最严重的地方，愤怒的火元素与鹰身人在此肆虐。将种子种在谷中残存的土堆里，便能带来新的生命，有望平息这片地区的动荡。",al={"种在哪里","为什么是焦炭谷","焦炭谷播种"}},{q="种下的种子面临哪些威胁？",a="烈焰中诞生的敌对火元素，以及在废墟中筑巢的凶暴血怒鹰身人，都威胁着种下的种子。荆棘谷地精在附近的作业带来了更多工业破坏。",al={"焦炭谷的危险","什么在破坏大地"}}},fx={["2eba8b82"]={q="什么是附有魔法的盖亚之种？",a="附有魔法的盖亚之种是由烈日石居的塔姆拉·荒原准备的坚韧种子，经过魔法处理，能够抵御环境污染。它们是强大的重生催化剂，能在遭到破坏的土地上扎根，开启漫长的焦土复原过程。",al={"什么是附有魔法的盖亚之种","附有魔法的盖亚之种背景"}}},fp="20,170,20.351.0,22.319.0,39.185.0,37.193.0,45.237.0,36.201.0"}
P.entries["item:enchanted-resonite-crystal"] = {n="魔化共鸣水晶",s="在石爪山，摩罗加尔用萨满法术改造了共鸣水晶。魔化共鸣水晶用于打破囚禁高戈罗克的木桶。",h="在石爪山，摩罗加尔用萨满法术改造了共鸣水晶。魔化共鸣水晶用于打破囚禁高戈罗克的木桶。",kw={"土灵的觉醒","魔化共鸣水晶","高戈罗克","摩罗加尔","共鸣水晶木桶","共鸣水晶","石爪山脉"},ang={["class:Shaman"]="身为萨满祭司，你能看出元素之力如何削弱束缚活体岩石的魔法。",["faction:Horde"]="身为部落的一员，你可以帮助摩罗加尔，在远古威胁危及当地哨站之前将其阻止，守护石爪山脆弱的平衡。"},sec={{t="远古岩石的破坏者",b="在石爪山脉的洞穴深处，天然共鸣水晶具有奇特的谐振与大地属性。萨满祭司摩罗加尔察觉到，地下一个密封的木桶中沉睡着危险的存在，于是用元素之力改造了这些矿石。魔化共鸣水晶能够打破加固的共鸣木桶，唤醒巨大的土灵——高戈罗克，此时他仍因漫长的沉睡而神志不清。"},{t="高戈罗克的威胁",b="摩罗加尔认为，若不加以制止，远古土灵可能会给石爪山乃至更广阔的卡利姆多带来灾难。他打算用魔化水晶打破木桶，趁高戈罗克虚弱时将其唤醒。这样就能在他恢复全部元素之力前，获得短暂的机会将其消灭。"}},faq={{q="魔化共鸣水晶有什么用途？",a="这块水晶能打破石爪山脉中狗头人盘踞的洞穴深处的共鸣木桶，释放沉睡的土灵——高戈罗克。",al={"魔化共鸣水晶用途","水晶有什么作用","打破共鸣木桶"}},{q="这块魔化水晶是谁制造的？",a="萨满祭司摩罗加尔将萨满之力注入天然共鸣水晶，制成了这块水晶，用来削弱桶中沉睡的生物，并使其暴露出来。",al={"谁制造了水晶","摩罗加尔的水晶","魔化共鸣水晶制造者"}},{q="为什么必须唤醒并消灭高戈罗克？",a="摩罗加尔担心，远古土灵无可匹敌的力量会危及石爪山和卡利姆多。水晶会在高戈罗克暂时虚弱时将其唤醒，使他变得容易受到攻击。",al={"为什么杀死高戈罗克","高戈罗克危险吗","高戈罗克的威胁"}},{q="击败高戈罗克后，该如何处理这块水晶？",a="将魔化共鸣水晶带回给摩罗加尔，并确认高戈罗克已被杀死。",al={"归还共鸣水晶","交还魔化共鸣水晶"}}},fx={ed58de6b={q="什么是魔化共鸣水晶？",a="这是一种经过改造的矿物护符，由烈日石居的摩罗加尔注入萨满祭司的力量。共鸣水晶是石爪山脉洞穴中天然生成的矿物。经过魔法改造后，这块水晶便成为专门用来击碎共鸣水晶桶的钥匙和锤子；沉睡的土灵巨人高戈罗克正被关在桶中。",al={"什么是魔化共鸣水晶","魔化共鸣水晶背景","共鸣水晶的含义"}},d1731b4b={q="摩罗加尔为什么想要魔化共鸣水晶？",a="摩罗加尔需要这块水晶，在土灵高戈罗克完全苏醒前将其释放并消灭。他担心一旦土灵挣脱束缚，便会带来无可匹敌的灾难，毁灭整个石爪山脉。击碎桶子会让高戈罗克在极度虚弱的状态下苏醒，这样你才有唯一可行的机会将它击倒。",al={"为什么想要魔化共鸣水晶","摩罗加尔为什么需要水晶","为什么需要魔化共鸣水晶"}}},fp="26,153,24.383.0,22.282.1,48.143.1,35.146.0,44.177.0,59.96.0"}
P.entries["item:encrypted-memorandum"] = {n="密文备忘录",s="在寒脊山谷，密文备忘录悄悄指引初出茅庐的潜行者去寻找他们的训练师。索姆·哈格林将邀请伪装成公文，号召流亡的无赖们团结起来。",h="在寒脊山谷，密文备忘录悄悄指引初出茅庐的潜行者去寻找他们的训练师。索姆·哈格林将邀请伪装成公文，号召流亡的无赖们团结起来。",kw={"安威玛尔","寒脊山谷","丹莫罗","密文备忘录","诺莫瑞根","潜行者训练师","索姆·哈格林"},ang={["class:Rogue"]="作为一名潜行者，你可以遵循这封密信的指引，在安威玛尔找到你的训练师，回应他在丹莫罗发出的召唤。",["race:Gnome"]="作为一名侏儒，诺莫瑞根沦陷后，你与矮人盟友生活在一起。这张便条悄悄号召侏儒潜行者团结起来，生存下去。"},sec={{t="隐秘的召唤",b="在安威玛尔，潜行者们行事低调。他们的训练师索姆·哈格林通过密文备忘录联系新人，而不在众目睽睽之下接近他们。这张用密文写成的羊皮纸看起来像是远方上级发来的指令。它告诉初出茅庐的潜行者去哪里寻找导师，同时避开当地卫兵和多疑镇民的注意。"},{t="寒脊同袍",b="索姆·哈格林的密文为寒脊山谷的潜行者提供了实用的忠告。诺莫瑞根已经沦陷，流离失所的侏儒如今涌入丹莫罗白雪覆盖的定居点，与矮人盟友比邻而居。紧张的气氛一触即发。索姆敦促学生们互相照应，因为迁怒与偏见可能让潜行者为每一件失窃的小玩意儿担责。"}},faq={{q="密文备忘录是什么？",a="密文备忘录是一张送到寒脊山谷潜行者新手手中的加密羊皮纸。它看似一份官方公文，实则指引他们前去接受训练。",al={"密文备忘录是什么","备忘录物品","潜行者便条"}},{q="这份备忘录是谁写的？",a="这份备忘录出自索姆·哈格林之手。这位安威玛尔的潜行者训练师将它伪装成官方命令，悄悄召集同道中的无赖。",al={"备忘录是谁写的","密文备忘录是谁送的","备忘录作者"}},{q="这封信为什么要加密？",a="寒脊山谷的潜行者会避开公众的审视。这层伪装让邀请看起来像例行公事，使当地官员和好奇的旁观者不会注意到训练活动。",al={"为什么加密","为什么使用密文","为什么用暗码书写"}},{q="索姆·哈格林想要什么？",a="索姆·哈格林希望提供战斗训练、指引，以及彼此的庇护。他敦促潜行者们在拥挤的丹莫罗团结起来，因为一旦有东西丢失，盗贼很快就会受到指责。",al={"索姆想要什么","为什么找索姆","索姆的目的"}}},fx={["88db5375"]={q="为什么会有人想要密文备忘录？",a="这份备忘录只写给你一人。寒脊山谷的潜行者训练师索姆·哈格林写下它，邀请与你们技艺相通的同行。它伪装成正式信函，意在引导你与他接触，同时避免引起安威玛尔当地人不必要的注意。",al={"为什么需要密文备忘录","谁需要密文备忘录","密文备忘录用途"}}},fp="20,202,18.351.0,20.375.1,33.173.0,26.136.0,29.191.0,28.186.0"}
P.entries["item:encrypted-parchment"] = {n="密文羊皮纸",s="在试炼谷，密文羊皮纸指引年轻的兽人潜行者前往大兽穴。高内克将它交给有潜力的新兵，纸上的密文指引他们去寻找隐于暗处的训练师鲁瓦格。",h="在试炼谷，密文羊皮纸指引年轻的兽人潜行者前往大兽穴。高内克将它交给有潜力的新兵，纸上的密文指引他们去寻找隐于暗处的训练师鲁瓦格。",kw={"杜隆塔尔","密文羊皮纸","高内克","兽人潜行者","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="身为潜行者，你收到召唤，将跟随与碎手氏族有联系的导师，学习部落的隐秘技艺。",["race:Orc"]="身为兽人，你或许更青睐光明正大、充满荣耀的战斗，但这封信欢迎那些擅长更隐秘、更致命的生存技艺的人。"},sec={{t="暗影中的召唤",b="年轻的兽人在试炼谷的烈日下证明自己的力量。那些在潜行、欺诈和刀法上显露天赋的人，会引来另一种关注。在与当地的野兽交锋后，有潜力的兽人潜行者会从高内克手中收到密文羊皮纸。纸上的密文召唤着那些能读懂隐秘讯息的人。"},{t="与碎手氏族的联系",b="密文指引初学者进入大兽穴，经过其他氏族训练师的所在，找到鲁瓦格。新兵在那里得知，这次召唤是碎手氏族安排的。这个组织在部落的秘密情报网中活动，响应召唤便意味着开始接受间谍技艺与暗影之术的潜行者训练。"}},faq={{q="密文羊皮纸有什么用途？",a="密文羊皮纸是一封以密文写成的召唤信，指引兽人潜行者新手前往试炼谷的大兽穴，寻找他们的训练师鲁瓦格。",al={"什么是密文羊皮纸","羊皮纸用途","为什么是密文羊皮纸"}},{q="是谁将羊皮纸交给你的？",a="你在谷中完成最初的试炼后，高内克会将羊皮纸交给你。纸上的讯息来自潜行者训练师鲁瓦格。",al={"谁写了羊皮纸","羊皮纸寄信人","谁给了我羊皮纸"}},{q="为什么这封信要用密文书写？",a="鲁瓦格和他在碎手氏族的联络人行事崇尚隐秘。密文指引那些适合潜行者诡秘之道的新兵，加入他们隐于暗处的行列。",al={"为什么用密文书写","为什么加密","秘密讯息"}},{q="是哪个组织发出了召唤？",a="鲁瓦格透露，碎手氏族请他留意有能力的新兵。这个组织训练潜行者掌握潜行与间谍技艺，在暗影中为部落效力。",al={"谁想训练我","碎手氏族潜行者","哪个阵营寄来的"}},{q="巨魔潜行者能使用这张羊皮纸吗？",a="不能。巨魔潜行者也从试炼谷起步，但他们收到的是密文石板。",al={"巨魔密文羊皮纸","巨魔也能用吗"}}},fp="19,194,26.324.0,26.280.0,47.132.0,31.117.0,37.147.0,40.163.0,36.98.0"}
P.entries["item:encrypted-rune"] = {n="密文符文",s="在寒脊山谷，密文符文召唤有潜质的盗贼新手前往安威玛尔。符文中的信息指引他们破译文字，寻找索姆·哈格林。",h="在寒脊山谷，密文符文召唤有潜质的盗贼新手前往安威玛尔。符文中的信息指引他们破译文字，寻找索姆·哈格林。",kw={"安威玛尔","密文","寒脊山谷","丹莫罗","密文符文","盗贼","索姆·哈格林"},ang={["class:Rogue"]="身为盗贼，你通过这次首次正式接触，结识了丹莫罗的盗贼。你的训练从潜行、迅捷的刀刃与生存之道开始。",["race:Dwarf"]="身为矮人，你也是寒脊山谷中的一名铁炉堡子民。符文召唤你掌握暗影之道，在暗中守护氏族的利益。"},sec={{t="密文中的召唤",b="盗贼新手必须读懂盗贼暗语，才能理解符文的含义。在这个过程中，他们开始接触在丹莫罗严酷的荒野中生存所需的暗影技艺。安威玛尔的盗贼导师索姆·哈格林通过这些密文，私下召唤那些在潜行与机敏方面展现潜质的人。"},{t="暗影中的眼睛",b="破译符文后，盗贼新手便会前往安威玛尔，找到那里的索姆·哈格林。随着当地局势日渐紧张，他希望壮大山谷中的隐秘力量。索姆不仅传授刀刃技艺与潜行之道，也教导他们保持警惕、珍视同伴。和平岌岌可危，盗贼们需要团结一致。"}},faq={{q="密文符文是什么？",a="密文符文为寒脊山谷初出茅庐的盗贼带来了一则加密的信息。它指引他们前往安威玛尔，向索姆·哈格林报到，接受训练。",al={"这是什么符文","密文符文的用途","符文有什么用"}},{q="是谁送来了密文符文？",a="安威玛尔的盗贼训练师索姆·哈格林送出密文符文，悄悄召集新人。",al={"谁写的","谁给的","符文的寄送者"}},{q="我该把符文带到哪里？",a="带着破译后的指示，前往寒脊山谷的安威玛尔，找到那里的索姆·哈格林。",al={"该去哪里","该交给谁","索姆在哪里"}},{q="为什么要将信息加密？",a="只有能够读懂密文的盗贼学徒，才能响应这份召唤。这让盗贼的手段不至于暴露在众目睽睽之下。",al={"为何使用密文","为何加密","符文为何保密"}}},fx={["1ca7ae1e"]={q="为什么会有人把密文符文送给你？",a="安威玛尔的潜行者训练师索姆·哈格林送来了这枚符文，希望引起你这位寒脊山谷潜行者新秀的注意。丹莫罗的麻烦日益增多，他正在矮人和侏儒中物色能干的人手，寻找懂得手持冷刃、隐于暗影的人，并邀请你前去接受进一步训练。",al={"为什么会收到密文符文","索姆为什么送来密文符文","密文符文用途"}}},fp="14,147,15.284.0,19.268.0,27.156.0,28.101.0,29.86.0,29.111.0"}
P.entries["item:encrypted-scroll"] = {n="密文卷轴",s="在丧钟镇，一份密文卷轴召唤一名刚刚复生的潜行者前去受训。卷轴上盖着大卫·提亚斯的印章，指引持有者到旅店与他见面，开始在被遗忘者的秘密特工之中接受训练。",h="在丧钟镇，一份密文卷轴召唤一名刚刚复生的潜行者前去受训。卷轴上盖着大卫·提亚斯的印章，指引持有者到旅店与他见面，开始在被遗忘者的秘密特工之中接受训练。",kw={"大卫·提亚斯","丧钟镇","密文卷轴","被遗忘者潜行者","潜行者训练师","巡影者","提瑞斯法林地"},ang={["class:Rogue"]="作为一名潜行者，你将在被遗忘者潜行者骨干的督导下，开始学习潜行、开锁和卑劣的格斗手段。",["race:Undead"]="作为丧钟镇刚刚复生的一员，你很早就有机会在Sylvanas初具雏形的王国中找到一份有意义的职责。"},sec={{t="秘密召唤",b="在丧钟镇，一名刚刚苏醒、颇具潜行天赋的被遗忘者引起了注意。一名斥候在附近的墓地中对抗无意识的天灾军团，证明了自己的能力，随后便收到了密文卷轴。卷轴上盖着潜行者训练师大卫·提亚斯的印章，要求持有者到当地旅店找他。这份召唤指引初出茅庐的特工掌握效力于黑暗女王所需的本领，而非将重获的生命耗费在扒窃上。"},{t="巡影者的耳目",b="卷轴上的简短信件要求潜行者在深入提瑞斯法林地之前，先在丧钟镇接头。提亚斯代表被遗忘者的秘密组织巡影者，留意有潜力的人才。在洛丹伦，被遗忘者依靠无声的利刃和机敏的斥候，对抗血色十字军、残存的联盟据点以及遗留下来的天灾军团。响应这份加密的召唤，便踏上了加入这一秘密网络的道路。"}},faq={{q="密文卷轴有什么用途？",a="密文卷轴召唤一名刚刚复生的被遗忘者潜行者，到丧钟镇的旅店寻找大卫·提亚斯，开始接受潜行者训练。",al={"卷轴有什么用","为什么是密文卷轴","卷轴用途"}},{q="密文卷轴是谁寄来的？",a="密文卷轴上盖着大卫·提亚斯的私人印章，他是丧钟镇的潜行者训练师，一直在留意有潜力的新兵。",al={"谁写的卷轴","卷轴寄件人","卷轴是谁寄来的"}},{q="大卫·提亚斯提到的巡影者是什么组织？",a="巡影者是被遗忘者的秘密组织，由潜行者、斥候和刺客组成，在洛丹伦各地活动。大卫·提亚斯负责考察有望加入他们的新人。",al={"巡影者是谁","巡影者 被遗忘者","巡影者组织"}},{q="读完密文卷轴后，该把它带到哪里？",a="把密文卷轴带给丧钟镇旅店里的大卫·提亚斯。",al={"在哪里交卷轴","卷轴交给谁","交卷轴"}}},fp="16,182,16.406.0,26.445.0,44.123.0,31.131.0,53.156.0,54.66.0"}
P.entries["item:encrypted-sigil"] = {n="密文符记",s="在幽影谷，密文符记向刚刚苏醒的暗夜精灵潜行者传达召唤。泰达希尔四周危机渐起，弗拉胡恩·影语者召他们前来接受训练。",h="在幽影谷，密文符记向刚刚苏醒的暗夜精灵潜行者传达召唤。泰达希尔四周危机渐起，弗拉胡恩·影语者召他们前来接受训练。",kw={"奥达希尔","密文符记","弗拉胡恩·影语者","卡多雷潜行者","潜行者训练师","幽影谷","泰达希尔"},ang={["class:Rogue"]="身为潜行者，你的道路始于遵循符记中隐藏的指示，与你的导师取得联系。",["race:NightElf"]="身为暗夜精灵，你知道，在Kaldorei面临部落新一轮侵扰之际，秘密行动人员正在搜集至关重要的情报。这是一个局势脆弱的时代。"},sec={{t="隐秘的召唤",b="幽影谷新晋的暗夜精灵斥候与潜入者会通过隐秘的途径收到密文符记。一位行事低调的信使代弗拉胡恩·影语者送来符记。其中藏着指示，要求新学徒前往奥达希尔附近向弗拉胡恩报到。读懂并送达符记，便能向弗拉胡恩证明，学徒能够领会隐晦的指示，处理秘密消息。"},{t="暗影中的眼睛",b="弗拉胡恩借这次召唤说明，在动荡的世界中，潜行者为何至关重要。暗夜精灵与远方的部落之间暗流涌动，但公开的战争并非族人面临的唯一危险。潜行者必须在泰达希尔各处搜集情报，成为卡多雷隐于暗处的眼睛与利刃，并学会在威胁扎根于世界之树的枝桠之前出击。"}},faq={{q="密文符记有何用途？",a="密文符记召唤暗夜精灵潜行者新手前来接受训练。其中隐藏的指示要求你前往奥达希尔附近，向弗拉胡恩·影语者报到。",al={"符记有什么用","密文符记的用途","为什么会有密文符记"}},{q="是谁送来了密文符记？",a="密文符记由弗拉胡恩·影语者送出。他是幽影谷的潜行者训练师，就在奥达希尔的枝桠之下。",al={"谁写了这枚符记","谁送来了密文符记","符记是谁送的"}},{q="弗拉胡恩·影语者找我有什么事？",a="弗拉胡恩想看看你是否准备就绪，向你讲述暗夜精灵面临的危险，包括部落可能挑起的纷争，并传授你基础的战斗技巧。",al={"弗拉胡恩为什么找我","弗拉胡恩任务","为什么要和弗拉胡恩交谈"}},{q="读完符记后，我该把它带到哪里？",a="把符记带给幽影谷奥达希尔附近的弗拉胡恩·影语者。",al={"密文符记交到哪里","弗拉胡恩的位置","弗拉胡恩在哪里"}}},fp="15,158,16.357.0,19.337.0,43.154.0,30.107.0,43.181.0,45.67.0"}
P.entries["item:encrypted-tablet"] = {n="密文石板",s="在试炼谷，密文石板指引初出茅庐的巨魔盗贼前去寻找鲁瓦格。这位盗贼训练师刻下了石板上的密文，并在大兽穴内驻守。",h="在试炼谷，密文石板指引初出茅庐的巨魔盗贼前去寻找鲁瓦格。这位盗贼训练师刻下了石板上的密文，并在大兽穴内驻守。",kw={"杜隆塔尔","密文石板","盗贼训练师","鲁瓦格","碎手氏族","大兽穴","试炼谷"},ang={["class:Rogue"]="作为一名盗贼，收到这块密文石板，是你正式加入部落的第一步。它指引你前往大兽穴，接受鲁瓦格的训练。",["race:Troll"]="作为一名在杜隆塔尔受训的黑暗之矛巨魔，你收到这块石板，证明你的敏捷身手和潜行本领已经引起了谷中训练师的注意。"},sec={{t="隐秘的召唤",b="巨魔盗贼新手抵达试炼谷时，会收到密文石板。上面的密文指引他们去寻找鲁瓦格，一位住在大兽穴幽暗洞窟中的兽人训练师。这块石板既能让当地暗影密探的事务保持隐秘，也能考验新兵是否读得懂其中的信息。"},{t="手的耳目",b="破译石板上的密文，让新兵得以接触部落更广阔的暗影网络。向鲁瓦格报到时，这些斥候会得知，碎手氏族等组织正关注着他们的进展。这些组织依靠谷中的训练师，判断未来的扒手、间谍和刺客是否足够机敏，能够为这个新生的国度效力。"}},faq={{q="密文石板有什么用途？",a="密文石板指引年轻的巨魔盗贼前去向鲁瓦格报到，他是驻守在试炼谷大兽穴内的盗贼训练师。",al={"石板用途","密文石板有什么用","为什么会有密文石板"}},{q="石板上的信息是谁写的？",a="信息由试炼谷的盗贼训练师鲁瓦格写下。他负责为部落训练窃贼、扒手和刺客。",al={"谁送来的密文石板","石板作者","这是谁写的"}},{q="在哪里能找到鲁瓦格？",a="鲁瓦格位于大兽穴内，那是一片沿着杜隆塔尔试炼谷北部山脊分布的洞窟。",al={"鲁瓦格在哪里","鲁瓦格位置","寻找试炼谷盗贼训练师"}},{q="鲁瓦格提到的“手”是什么？",a="手指的是碎手氏族，这是部落盗贼网络中的一个秘密组织。鲁瓦格向他们汇报谷中新密探的准备情况。",al={"手是什么","手是谁","与碎手氏族的联系"}}},fp="16,149,16.301.0,16.328.0,38.124.0,36.154.0,21.101.0,37.156.0"}
P.entries["item:essence-of-nightlash"] = {n="奈塔拉什的灵魂",s="在亡者农场，奈塔拉什败亡后留下了一样被遗忘者可以带走的东西。高级执行官哈德瑞克需要用它证明，支撑腐皮豺狼人的天灾军团部队已被击溃。",h="在亡者农场，奈塔拉什败亡后留下了一样被遗忘者可以带走的东西。高级执行官哈德瑞克需要用它证明，支撑腐皮豺狼人的天灾军团部队已被击溃。",kw={"女妖","亡者农场","尘埃","精华","哈德瑞克","奈塔拉什","腐皮","瑟伯切尔"},ang={["class:Mage"]="身为法师，你可以研究女妖被消灭后留下的残留物，了解幽灵形态的亡灵如何将死灵魔法与物质世界相连。",["race:Undead"]="身为被遗忘者的一员，你知道士兵们为何认为消灭奈塔拉什这样的女妖至关重要。被遗忘者曾是Scourge奴役下的受害者，如今他们与巫妖王的爪牙作战，为自己的同胞夺取洛丹伦。"},sec={{t="亡者农场的女妖",b="在银松森林北部一处名为亡者农场的废弃农庄里，成群的腐皮亡灵豺狼人奉天灾军团之命盘踞于此。被遗忘者的进攻一次次失败，并非因为那些凶蛮的豺狼人，而是因为它们的幽灵指挥官奈塔拉什击退了进攻。她的哀嚎魔法巩固了豺狼人的防线，将瑟伯切尔派来的部队打得溃不成军。奈塔拉什被杀死后，她无形的身躯化作尘埃，留下一份结晶状的魔法精华。"},{t="天灾军团败亡的凭证",b="女妖不会留下尸体，因此奈塔拉什的精华是这个幽灵已被消灭的唯一实物凭证。瑟伯切尔的高级执行官哈德瑞克需要它来确认天灾军团的据点已经陷落。有了这份凭证，被遗忘者就能巩固北部防线，压制腐皮豺狼人的威胁。"}},faq={{q="奈塔拉什的灵魂是什么？",a="奈塔拉什的灵魂是天灾军团女妖奈塔拉什被击败后留下的结晶状尘埃。由于幽灵没有实体，这些残留物便是她已被消灭的证明。",al={"奈塔拉什的灵魂","奈塔拉什尘埃","奈塔拉什精华是什么"}},{q="奈塔拉什是谁？",a="奈塔拉什是一名天灾军团女妖，在银松森林北部的亡者农场指挥腐皮豺狼人，并增强它们的力量。",al={"奈塔拉什是谁","奈塔拉什背景故事","女妖奈塔拉什"}},{q="谁需要这份精华？",a="瑟伯切尔的高级执行官哈德瑞克需要这份精华，以证明曾击溃他前线攻势的奈塔拉什已被击败。",al={"谁需要奈塔拉什精华","精华交给谁","高级执行官哈德瑞克"}},{q="豺狼人为什么会与女妖合作？",a="亡者农场的腐皮豺狼人已被亡灵瘟疫侵蚀，沦为天灾军团的奴仆。奈塔拉什奉命前来监管它们，并提供魔法支援，对抗被遗忘者的巡逻队。",al={"豺狼人与天灾军团","腐皮与天灾军团","豺狼人为何与女妖合作"}}},fp="20,188,30.494.0,23.314.0,33.148.0,17.114.0,23.133.0,42.188.0"}
P.entries["item:essential-artificial"] = {n="基础模组",s="在铁炉堡，基础模组零件帮助流亡的侏儒工匠和工程师重建家园。侏儒逃离诺莫瑞根时，留下了大批库存。",h="在铁炉堡，基础模组零件帮助流亡的侏儒工匠和工程师重建家园。侏儒逃离诺莫瑞根时，留下了大批库存。",kw={"人工外推器","工程学零件","基础模组","诺莫瑞根","科罗莫特·钢尺","侏儒区"},ang={["profession:Engineering"]="身为工程师，你能看出这些用途广泛的零件如何适用于各种机械和实验性设计。",["race:Gnome"]="身为侏儒，从诺莫瑞根遭受辐射的走廊中回收零件，能帮助你的同胞在铁炉堡避难期间重建技术优势。"},sec={{t="制式设计中的巧思",b="诺莫瑞根陷落之前，工匠们就将基础模组用作多种用途的零件。侏儒工程师将它装入遍布地下大厅的各种装置、精巧的发条造物和重型机械。它的标准化设计让铁匠和机械师可以放心地互换零件。"},{t="回收深处的零件",b="穴居人的入侵和辐射灾难迫使侏儒仓皇逃离诺莫瑞根。大量基础模组零件仍存放在名为人工推演器的沉重蒸汽分配装置中，这些装置散布在深处的通道里。\n\n在侏儒区，工匠大师科罗莫特·钢尺正在寻找勇敢的冒险者，重返受到污染的废墟，回收这些零件。他需要这些零件，让研究和发明得以继续。"}},faq={{q="基础模组是什么？",a="基础模组是一种标准化的机械零件。侏儒铁匠和工匠将它用于实验、机械和各种装置。",al={"基础模组是什么","基础模组物品","这是什么零件"}},{q="为什么它们被留在了诺莫瑞根？",a="穴居人的入侵和致命的辐射迫使侏儒仓皇出逃。大批日常使用的零件留在了储存装置中。",al={"为什么在诺莫瑞根","为什么被遗弃"}},{q="谁想回收这些零件？",a="科罗莫特·钢尺是铁炉堡侏儒区中一位雄心勃勃的发明家，他正在寻找这些零件，以便在流亡期间继续开展实验和技术研究。",al={"谁需要基础模组","谁收这些零件","科劳莫特·钢尺任务"}},{q="在废墟的什么地方能找到它们？",a="在受到污染的诺莫瑞根深层各处，名为人工智能模拟器的大型蒸汽容器中存放着基础模组零件。",al={"基础模组在哪里","人工外推器位置"}}},fx={["691fb1fc"]={q="基础模组从何而来，又是谁制造的？",a="基础模组是精密机械部件，由诺莫瑞根的工匠和铁匠在这座伟大城市陷落之前设计制造。它们为侏儒科技而大量生产，储存在称为人工推演器的自动分配器中，这些装置安放在城市深处的工业设施内。",al={"谁制造了基础模组","基础模组起源","基础模组从何而来"}}},fp="20,157,24.294.0,23.448.0,32.141.0,40.139.0,37.150.0,38.152.0"}
P.entries["item:etched-note"] = {n="风化便笺",s="在纳拉其营地，风化便笺召唤一位年轻的牛头人猎人开始接受训练。营地的猎人训练师兰卡·远箭欢迎这位新手踏入狩猎传统。",h="在纳拉其营地，风化便笺召唤一位年轻的牛头人猎人开始接受训练。营地的猎人训练师兰卡·远箭欢迎这位新手踏入狩猎传统。",kw={"纳拉其营地","风化便笺","兰卡·远箭","莫高雷","红云台地","牛头人猎人","训练师的召唤"},ang={["class:Hunter"]="身为猎人，这张便笺标志着你正式踏入猎人的传统。兰卡的教导将让你学会使用远程武器，并与平原上的野兽交流。",["race:Tauren"]="身为牛头人，你肩负着长辈与血脉传承的期望。这张便笺召唤你在远赴异乡之前，先熟悉莫高雷起伏的草原。"},sec={{t="狩猎的召唤",b="在纳拉其营地，一名信使为年轻的舒哈鲁带来了营地猎人训练师兰卡·远箭的口信。便笺称猎人是部族的核心。它也告诫新手，天生的本能需要严格的教导，以及对莫高雷荒野的深深敬意。"},{t="舒哈鲁的传统",b="对牛头人而言，狩猎是一门神圣的技艺，也是一种生存之道，融入了部族生活之中。猎人与战士、萨满祭司和德鲁伊并肩劳作，部族也仰赖他们的指引与保护。学徒将便笺交给兰卡，开始学习武器技艺和理解野兽的方法，为保卫部族、维系部族生计做好准备。"}},faq={{q="风化便笺有何用途？",a="风化便笺召唤牛头人猎人新手前往纳拉其营地，向兰卡·远箭报到。在那里，他们将开始接受射击技巧和野兽知识的正式训练。",al={"便笺有什么用","风化便笺用途","为什么会收到风化便笺"}},{q="这张便笺是谁写的？",a="这张便笺出自纳拉其营地的猎人训练师兰卡·远箭之手。他派出信使，走遍台地，寻找准备好接受教导的年轻猎人。",al={"谁送来了风化便笺","是谁写的","风化便笺作者"}},{q="狩猎为何对牛头人如此重要？",a="狩猎维系着牛头人的生存、精神信仰和部族传统。技艺娴熟的猎人提供食物与材料，同时与大地保持和谐，敬重被他们猎杀的野兽之灵。",al={"牛头人猎人背景故事","牛头人为什么狩猎","牛头人文化中的狩猎"}},{q="这张便笺该送到哪里？",a="将风化便笺交给兰卡·远箭，他就在红云台地的纳拉其营地，靠近帐篷和训练场的地方。",al={"便笺该送到哪里","该交给谁","风化便笺交付"}}},fp="11,154,18.268.0,26.366.0,39.162.0,20.138.0,42.199.0,34.116.0"}
P.entries["item:etched-parchment"] = {n="风蚀羊皮纸",s="高内克将基沙的召集令交给试炼谷的猎人。风蚀羊皮纸指引他们在杜隆塔尔开始最初的训练。",h="高内克将基沙的召集令交给试炼谷的猎人。风蚀羊皮纸指引他们在杜隆塔尔开始最初的训练。",kw={"杜隆塔尔","风蚀羊皮纸","高内克","猎人","基沙","训练师","试炼谷"},ang={["class:Hunter"]="身为猎人，你收到这封信，便踏上了在杜隆塔尔接受首次试炼的道路。它引领你找到基沙，向她学习追踪、远程武器和生存技巧。",["faction:Horde"]="身为部落的一员，你不断磨炼自己的技艺。对猎人而言，这张羊皮纸标志着为氏族获取食物、守卫杜隆塔尔边境的第一步。"},sec={{t="狩猎的召唤",b="年轻的兽人和黑暗之矛巨魔在试炼谷开始接受试炼。新兵们对付当地的害兽，证明自己的实力，而高内克则引导他们找到自己的道路。他将风蚀羊皮纸交给那些将以弓箭、枪械和利齿作战的人。纸上的讯息来自基沙，她是一位技艺精湛的猎人训练师，正在寻找目光敏锐、双手沉稳的新人。"},{t="第一课",b="将羊皮纸带给基沙，便能开始在杜隆塔尔的猎人训练。她教导新人，荒野之路需要全心投入：要驾驭沙漠中的野兽，付出的努力不亚于奥术师研习魔法，或萨满祭司与灵魂沟通。她的召唤将新猎人带到这里，学习射击与野外生存。"}},faq={{q="风蚀羊皮纸有什么用途？",a="风蚀羊皮纸指引试炼谷的新猎人去找他们的训练师基沙。",al={"风蚀羊皮纸用途","风蚀羊皮纸有什么用"}},{q="谁会发放这张羊皮纸？",a="高内克在试炼谷的大兽穴附近，将羊皮纸交给年轻的猎人。",al={"谁发放风蚀羊皮纸","风蚀羊皮纸任务给予者"}},{q="风蚀羊皮纸是谁写的？",a="这封信是基沙写的。她是试炼谷的一位巨魔猎人训练师，随时准备训练新的射手。",al={"谁送来风蚀羊皮纸","羊皮纸作者"}},{q="在哪里可以找到基沙？",a="基沙在杜隆塔尔的试炼谷中，靠近训练场的地方等候，指导初出茅庐的兽人和巨魔猎人。",al={"基沙在哪里","寻找基沙"}}},fp="16,97,21.334.0,16.321.0,33.91.0,29.81.0,31.111.0,28.119.0"}
P.entries["item:etched-rune"] = {n="风蚀符文",s="在寒脊山谷，风蚀符文召唤有潜力的矮人猎人前往安威玛尔。猎人训练师索加斯·格瑞姆森送来符文，引领他们开始学习荒野中的生存之道。",h="在寒脊山谷，风蚀符文召唤有潜力的矮人猎人前往安威玛尔。猎人训练师索加斯·格瑞姆森送来符文，引领他们开始学习荒野中的生存之道。",kw={"安威玛尔","寒脊山谷","丹莫罗","矮人猎人","风蚀符文","猎人训练","索加斯·格瑞姆森"},ang={["class:Hunter"]="身为猎人，符文召唤你学习矮人的狩猎技艺。你将学会追踪、尊重动物伙伴，并凭借自己的智慧在荒野中生存。",["race:Dwarf"]="身为矮人，你知道刻有文字的石头和符文承载着行当知识与紧急指令，在寒脊山谷的风雪中传递。"},sec={{t="荒野的召唤",b="风蚀符文上刻着矮人符文，被送到那些在寒脊山谷的积雪中展露潜力的新手手中。身为巡山人和猎人训练师的索加斯·格瑞姆森召唤初出茅庐的追踪者前往安威玛尔。在那里，他们不再只学习基本的生存技能，而是开始掌握猎人的技艺：尊重丹莫罗的野兽、追踪山中的掠食者、保养远程武器，以及在恶劣的环境中磨炼耐力。"}},faq={{q="风蚀符文有什么用途？",a="风蚀符文召唤有志成为猎人的矮人前往安威玛尔，寻找索加斯·格瑞姆森，接受正式的猎人技艺指导。",al={"风蚀符文有什么作用","风蚀符文用途","为什么会有风蚀符文"}},{q="风蚀符文是谁写下或送来的？",a="安威玛尔的猎人训练师索加斯·格瑞姆森将符文送给寒脊山谷的野外生存新手，他们在冰封荒野中展现出了生存的天赋。",al={"谁送来了风蚀符文","这枚符文是谁给的","风蚀符文作者"}},{q="读完风蚀符文后，该把它带到哪里？",a="将风蚀符文带到寒脊山谷的安威玛尔。索加斯·格瑞姆森在熔炉和训练大厅附近等候，传授你追踪技巧、武器保养方法和矮人的狩猎传统。",al={"风蚀符文带到哪里","交付风蚀符文","索加斯·格瑞姆森位置"}}},fx={["455fa37e"]={q="风蚀符文是什么？",a="风蚀符文是一块刻有文字的石板，交给在寒脊山谷开始训练的矮人猎人新手。它以刻有符文的石板取代普通羊皮纸，作为经久不朽的传讯召令，体现了矮人与荒野生存之道紧密相连、根深蒂固的工艺与传统。",al={"风蚀符文是什么","风蚀符文物品","风蚀符文背景"}},["537b1d7a"]={q="索加斯·格瑞姆森为什么要你带来风蚀符文？",a="这块符文是安威玛尔内的常驻猎人训练师索加斯·格瑞姆森发出的正式训练召令。带着它前来，便确认你已在山谷中证明了基本能力，准备好接受追踪、武器保养和荒野传统方面的严格教导。",al={"索加斯·格瑞姆森为何需要符文","为何需要风蚀符文","风蚀符文召令用途"}}},fp="11,167,16.386.0,39.131.0,34.159.0,52.177.0"}
P.entries["item:etched-sigil"] = {n="风化符记",s="这是一枚交付给幽影谷初醒的暗夜精灵猎人的铭文信物。由林地信使携带，上面带着猎人训练师阿亚娜·远途从奥达希尔巨枝之巅发出的召唤。",h="这是一枚交付给幽影谷初醒的暗夜精灵猎人的铭文信物。由林地信使携带，上面带着猎人训练师阿亚娜·远途从奥达希尔巨枝之巅发出的召唤。",kw={"奥达希尔","阿亚娜·远途","风化符记","猎人","幽影谷","泰达希尔"},ang={["class:Hunter"]="这枚铭文护身符标志着卡多雷猎人在阿亚娜·远途的指导下，开启掌握弓箭和野兽之道旅程的起点。",["race:NightElf"]="这枚符记在幽影谷幽静的树冠下交付，它尊崇了致力于守护泰达希尔的暗夜精灵林务者们的古老传统。"},sec={{t="荒野的召唤",b="风化符记上雕刻着狩猎的印记，当新觉醒的暗夜精灵猎人踏入幽影谷时，他们会收到这枚信物。这枚信物是来自当地猎人训练师阿亚娜·远途的正式通知与欢迎，她居住在奥达希尔中空的枝干高处。符记指示新手前往寻找她，并由此开启关于射箭、荒野追踪以及暗夜精灵潜行者与野兽之间古老羁绊的终身教导。"}},faq={{q="风化符记的用途是什么？",a="该符记是一份直接的召唤，指示暗夜精灵猎人新手前往幽影谷的奥达希尔之巅寻找他们的训练师阿亚娜·远途，以开始关于生存、追踪和射箭的正式训练。",al={"风化符记有什么用","风化符记用途","我为什么会有这个符记"}},{q="是谁寄出了风化符记？",a="它是由阿亚娜·远途制作并派发的，她是负责照看幽影谷中羽翼未丰的林地潜行者的猎人训练师。",al={"谁寄出的风化符记","风化符记从哪里来"}},{q="符记应该被带到哪里？",a="它必须被带到位于幽影谷中心的奥达希尔巨树的高处，阿亚娜·远途正在那里等待。",al={"我该把风化符记带到哪里","我该把风化符记交给谁"}},{q="为什么暗夜精灵猎人收到的是符记而不是纸质信件？",a="卡多雷的传统更倾向于使用天然雕刻和刻有艾露恩及荒野神圣符号的耐用信物，而非普通的羊皮纸，这体现了猎人与森林之间的羁绊本质。",al={"为什么是符记而不是信件","符记是用什么做的"}}},fp="12,81,20.363.0,40.149.0,27.76.0,32.66.0,68.77.0"}
P.entries["item:explosive-stick-of-gann"] = {n="加恩的雷管",s="在南贫瘠之地，加恩·石塔利用偷来的矮人图纸对付巴尔莫丹。他制造了炸药，用来破坏矮人的飞行器。",h="在南贫瘠之地，加恩·石塔利用偷来的矮人图纸对付巴尔莫丹。他制造了炸药，用来破坏矮人的飞行器。",kw={"巴尔莫丹","加恩的雷管","飞行器","加恩·石塔","勘探员 卡兹戈姆","石塔 部族","贫瘠之地"},ang={["profession:Engineering"]="身为工程师，你能看出偷来的蓝图是如何被用来反击矮人机械的。",["race:Tauren"]="身为牛头人，使用这件武器能为流离失所的石塔部族复仇，反击那些挖掘卡利姆多神圣土地的勘探员。"},sec={{t="复仇之器",b="勘探员卡兹戈姆率领铁炉堡的挖掘队进入卡利姆多南部时，矮人将石塔牛头人赶出了祖传的村落，并夷平了他们的圣地，建起巴尔莫丹。加恩·石塔夺回了卡兹戈姆的蓝图，要为流离失所和死去的族人复仇。他研究了图纸，组装出足以摧毁重型机械的炸药。"},{t="瞄准空中机械",b="加恩制造这根雷管，是为了炸毁挖掘场上方瞭望塔上的矮人飞行器。在他眼中，这台机器不仅是交通工具或战争兵器。它象征着联盟对牛头人神圣土地的统治。摧毁它，就能重创矮人的前哨站，也能为失落的石塔部族讨还血债。"}},faq={{q="加恩的雷管是什么？",a="加恩·石塔利用找回的矮人设计图制造了炸药，用来破坏勘探员在他祖传土地上使用的机械。",al={"加恩的雷管","加恩 的雷管","加恩 的炸弹"}},{q="这件爆炸物是谁制造的？",a="巴尔莫丹的铁炉堡矮人摧毁了族人的村落，亵渎了他们在南贫瘠之地的家园后，加恩·石塔组装了这件爆炸物，要为自己的部族复仇。",al={"制造者是谁","加恩 是谁","加恩·石塔"}},{q="这件爆炸物要炸毁什么？",a="这份炸药要摧毁的，是巴尔莫丹挖掘场上方塔楼上的矮人飞行器。摧毁它会重创这处据点的侦察能力，也象征着石塔部族的复仇。",al={"轰炸目标","飞行器目标","使用地点"}},{q="一个牛头人是怎么学会制造矮人炸药的？",a="加恩从巴尔莫丹矮人挖掘队的首领、勘探员卡兹戈姆手中夺回了工程蓝图，并据此制造了雷管。他用入侵者自己的技术反击他们。",al={"加恩 如何制造雷管","炸药设计图","卡兹戈姆 的图纸"}}},fp="23,148,23.363.0,25.321.1,36.143.0,24.180.0,42.215.0,50.180.0"}
P.entries["item:faded-shadowhide-pendant"] = {n="不再发光的暗皮坠饰",s="在赤脊山找到的不再发光的暗皮坠饰，如今传出了声音。暗皮豺狼人佩戴它来接收莫甘斯的命令，而这段迟来的讯息源自塞欧克瑞图斯施放的法术。",h="在赤脊山找到的不再发光的暗皮坠饰，如今传出了声音。暗皮豺狼人佩戴它来接收莫甘斯的命令，而这段迟来的讯息源自塞欧克瑞图斯施放的法术。",kw={"艾尔文","豺狼人","莫甘斯","坠饰","赤脊山","暗皮","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="身为法师，你能看出，即使是粗陋或黑暗的附魔，也能被魔法截获。训练有素的巫师能够破解并夺取它们的控制权。",["faction:Alliance"]="身为联盟的一员，你帮助阿祖拉之塔削弱威胁艾尔文森林和湖畔镇的暗皮豺狼人。"},sec={{t="遭到突破的网络",b="赤脊山的暗皮豺狼人听命于莫甘斯，通过附魔坠饰协调行动。大法师塞欧克瑞图斯在阿祖拉之塔的居所中研究了这些护符，并设计出一道突破其魔法连接的法术。他传送的讯息过了数周才显现。这枚不再发光的坠饰证明，豺狼人的通讯可以被截获，让塞欧克瑞图斯有办法干扰莫甘斯的控制。"},{t="法师的雄心",b="塞欧克瑞图斯想研究这枚坠饰，弄清它的附魔为何在他的侵入下依然有效。他希望改进自己的法术，最终能通过遍布赤脊山的同类护符发动攻击，使佩戴者失去行动能力。必须将坠饰带到艾尔文森林的阿祖拉之塔，他才能着手削弱莫甘斯对当地豺狼人的控制。"}},faq={{q="不再发光的暗皮坠饰是什么？",a="赤脊山的暗皮豺狼人曾佩戴不再发光的暗皮坠饰，接收莫甘斯的命令。大法师塞欧克瑞图斯传送讯息的法术改变了这枚坠饰。",al={"暗皮坠饰","这枚坠饰是什么","塞欧克瑞图斯的坠饰"}},{q="为什么坠饰里会传出声音？",a="这个声音是大法师塞欧克瑞图斯数周前施放的法术留下的回响。经过数月研究，他找到了突破坠饰通讯连接的方法，而这段讯息表明，他的法术已经触及豺狼人的通讯网络。",al={"谁在说话","无形的声音","塞欧克瑞图斯的声音"}},{q="塞欧克瑞图斯是谁？",a="塞欧克瑞图斯是艾尔文森林东部阿祖拉之塔的大法师。他研究边境另一侧赤脊山的黑暗威胁，尤其是叛变的巫师莫甘斯。",al={"塞欧克瑞图斯的故事","大法师塞欧克瑞图斯","阿祖拉之塔的法师"}},{q="莫甘斯是谁？",a="莫甘斯是赤脊山一名邪恶的叛变施法者。他通过附魔坠饰指挥当地的暗皮豺狼人。",al={"莫甘斯的身份","莫甘斯是谁","豺狼人的主人"}},{q="塞欧克瑞图斯打算用这枚坠饰做什么？",a="塞欧克瑞图斯计划在实验室里研究坠饰的附魔。他希望通过这个网络发动攻击，使所有佩戴同类坠饰的豺狼人失去行动能力。",al={"塞欧克瑞图斯为什么想要它","坠饰的用途","将坠饰化为武器"}}},fx={["6c0e263d"]={q="不再发光的暗皮坠饰来自哪里？由谁制造？",a="这枚坠饰源自赤脊山的暗皮豺狼人及其黑暗主宰、盗贼法师摩根斯。摩根斯制造或附魔了这些小饰物，将它们制成神秘媒介，以便把命令直接传达给受他控制的豺狼人群。",al={"谁制造了不再发光的暗皮坠饰","暗皮坠饰来自哪里","不再发光的暗皮坠饰的来源"}}},fp="24,180,16.416.0,19.330.1,37.166.0,40.203.0,18.163.0,16.120.0,49.182.0"}
P.entries["item:fallen-moonstone"] = {n="陨落的月亮石",s="在灰谷的坠星湖，暗夜精灵从宁静的湖水中采集散发光芒、蕴含魔力的陨落的月亮石。神圣的月亮能量赋予这些石头恢复之力，能够补充生命力，治愈严重的虚弱。",h="在灰谷的坠星湖，暗夜精灵从宁静的湖水中采集散发光芒、蕴含魔力的陨落的月亮石。神圣的月亮能量赋予这些石头恢复之力，能够补充生命力，治愈严重的虚弱。",kw={"灰谷","阿斯特兰纳","陨落的月亮石","坠星湖","月亮石","皮尔图拉斯·怀特姆恩","蕾拉","沼泽兽智者"},ang={["class:Priest"]="The Sisterhood of Elune的虔诚信徒将这些石头散发的月光视为治愈恩典的象征。",["race:NightElf"]="对Kaldorei而言，与Elune的光辉相连的遗物是守护生命的神圣器物。当凡人的医术无能为力时，它们便带来神圣的治疗。"},sec={{t="夜空的馈赠",b="阿斯特兰纳东南方的坠星湖，曾在湖岸和浅水处出产大量石头。当寻常疗法无效时，暗夜精灵格外珍视这些石头的恢复魔法与月亮祝福。腐化的沼泽兽沼泽兽占据湖泊后，采集这些石头变得危险重重。它们的首领沼泽兽智者将找到的每一块石头都囤积在湖心的一座小岛上，使当地的卡多雷失去了一种重要的治疗来源。"},{t="一位父亲的救赎",b="在阿斯特兰纳，年幼的蕾拉·怀特姆恩身患重病。寻常疗法让她退了烧，却使她憔悴不堪、濒临死亡，只剩几口气。她的父亲皮尔图拉斯·怀特姆恩知道，只有月亮石中凝聚的恢复之力，才能补回她耗尽的生命力。从沼泽兽智者囤积的石头中取回的一块月亮石，给了这个孩子活下去所需的力量。"}},faq={{q="什么是陨落的月亮石？",a="陨落的月亮石是来自灰谷坠星湖的一种石头，散发着光芒，蕴含着魔力。神圣的月亮能量赋予它恢复之力，暗夜精灵用它为极度虚弱的人补充体力。",al={"什么是陨落的月亮石","陨落的月亮石背景故事","灰谷月亮石"}},{q="哪里能找到陨落的月亮石？",a="陨落的月亮石来自灰谷阿斯特兰纳东南方的坠星湖。它们曾散落在湖底，后来被充满敌意的沼泽兽沼泽兽收集起来，囤积在湖心的一座小岛上。",al={"哪里能找到陨落的月亮石","陨落的月亮石位置"}},{q="谁占有坠星湖的月亮石？",a="沼泽兽智者将陨落的月亮石囤积在坠星湖湖心的一座小岛上。这位先知统领着那里的腐化沼泽兽。",al={"谁有陨落的月亮石","沼泽兽智者月亮石"}},{q="皮尔图拉斯·怀特姆恩为什么需要陨落的月亮石？",a="皮尔图拉斯·怀特姆恩需要一块陨落的月亮石来拯救他年幼的女儿蕾拉。虽然她熬过了一场令人衰弱的高烧，却仍虚弱得性命垂危，而他知道月亮石的魔法能让她恢复活力。",al={"皮尔图拉斯·怀特姆恩的女儿","为什么需要月亮石","蕾拉的治疗"}}},fp="16,166,22.395.0,20.350.1,27.157.0,34.191.0,48.145.0,52.204.0"}
P.entries["item:fandral-s-message"] = {n="范达尔的信",s="在达纳苏斯，范达尔·鹿盔将一封信送过大海，交给黑海岸的安努。这封密封信件带去了泰达希尔神谕林地的消息。",h="在达纳苏斯，范达尔·鹿盔将一封信送过大海，交给黑海岸的安努。这封密封信件带去了泰达希尔神谕林地的消息。",kw={"知识古树","奥伯丁","黑海岸","达纳苏斯","范达尔·鹿盔","范达尔的信","古树之林","安努","神谕林地"},ang={["class:Druid"]="身为德鲁伊，在达纳苏斯的塞纳里奥区与黑海岸的Ancients of Lore之间传递信件，让你看到范达尔·鹿盔的进取心与古老守护者们的耐心之间的分歧。",["race:NightElf"]="身为暗夜精灵，这封信将带你离开泰达希尔的树冠，前往卡利姆多大陆上祖先生活过的森林。"},sec={{t="大德鲁伊的信件",b="大德鲁伊范达尔·鹿盔在达纳苏斯的塞纳里奥区写下信件。这封密封信件的收信人是安努，一位居住在古树之林的知识古树。范达尔收到了有关泰达希尔神谕林地状况的报告，于是派遣信使前往奥伯丁以南，将消息带给安努。这段旅程要渡海前往黑海岸，将消息从新生的世界之树腹地带往卡利姆多更为古老、林荫幽深的大陆。"},{t="迥异的步调",b="安努说，范达尔总是匆匆忙忙。这位知识古树说，万事应当顺应自然的步调，古树们都如此认为。对于黑海岸那些生活节奏缓慢的树人来说，范达尔的急躁与大德鲁伊玛法里奥·怒风昔日展现的耐心和智慧截然不同。"}},faq={{q="范达尔的信是什么？",a="范达尔的信是大德鲁伊范达尔·鹿盔写给安努的一封密封信件，安努是居住在黑海岸古树之林的知识古树。",al={"范达尔的信物品","范达尔的信","大德鲁伊的信"}},{q="这封信是谁寄出的，又为何寄出？",a="大德鲁伊范达尔·鹿盔收到有关泰达希尔神谕林地的报告后，在达纳苏斯写下了这封信。他将消息送给黑海岸的安努。",al={"谁写的","范达尔为何送信"}},{q="这封信需要送到哪里？",a="将信送给黑海岸古树之林的安努，那里就在奥伯丁的正南方。",al={"谁收信","信送到哪里","范达尔的信目的地"}},{q="安努如何看待这封信？",a="安努说，范达尔总是匆匆忙忙。这位古树指出，自然有自己的步调，杉多玛法里奥·怒风更懂得这个道理。",al={"安努的反应","安努说了什么"}}},fp="17,139,29.410.0,18.276.1,26.142.0,31.142.0,35.96.0,34.149.0"}
P.entries["item:fang-of-vagash"] = {n="瓦加什的牙齿",s="在丹莫罗，瓦加什潜伏在冻石农场上方，伺机捕食山羊。他的牙齿证明这头致命的猛兽已被杀死。",h="在丹莫罗，瓦加什潜伏在冻石农场上方，伺机捕食山羊。他的牙齿证明这头致命的猛兽已被杀死。",kw={"冻石农场","丹莫罗","瓦加什的牙齿","铁炉堡","保护羊群","山羊","瓦加什"},ang={["class:Hunter"]="在丹莫罗冰冷的峭壁间追踪瓦加什，考验着猎手追踪、野外求生和猎杀野兽的本领。",["race:Dwarf"]="冻石农场为矮人巡山人和旅者饲养强健的山羊。带回瓦加什的牙齿，有助于保全铁炉堡珍视的坐骑品种。"},sec={{t="狩猎的战利品",b="在冻石农场上方，瓦加什借着夜色捕食山羊。高耸的峭壁间藏着凶猛的掠食者，但没有哪一头像他那样令当地农场深受其害。铁炉堡的兵力捉襟见肘，牧民们得不到城中卫兵的保护。从他口中拔下的牙齿向养殖者证明，瓦加什已经死去，他们的牧场又安全了。"}},faq={{q="瓦加什的牙齿有什么用？",a="丹莫罗冻石农场的养殖者将瓦加什的牙齿视为他已被杀死的证据。他们会奖赏保护了他们生计的猎手。",al={"瓦加什的牙齿用途","瓦加什的牙齿有什么用","上交瓦加什的牙齿"}},{q="瓦加什是谁？",a="瓦加什是一头致命的野兽，巢穴位于丹莫罗山羊牧场上方的雪山中。他在夜间袭击羊群，当地矮人都很惧怕他。",al={"瓦加什是什么","瓦加什在哪里","瓦加什的背景故事"}},{q="铁炉堡的卫兵为什么没有杀死瓦加什？",a="铁炉堡的兵力分散，几乎抽不出士兵到乡间巡逻。牧场主只能依靠路过的冒险者对付危险的猛兽。",al={"卫兵为什么不帮忙","铁炉堡军队在哪里","巡山人 瓦加什"}}},fx={fc16a334={q="瓦加什的牙齿是什么？",a="瓦加什的牙齿是一件巨大的战利品，取自瓦加什的口中，这头凶恶的掠食者在丹莫罗的山脊间徘徊。它是无可辩驳的证据，证明那头威胁众人的野兽终于被追捕并杀死。",al={"瓦加什的牙齿是什么","瓦加什的牙齿背景","瓦加什的牙齿"}},["695a78ed"]={q="瓦加什的牙齿从何而来？",a="这颗獠牙并非人工制作，而是从瓦加什本身的口中撬下的天然牙齿。这头凶猛的怪物将巢穴安在冻石农场正上方的雪丘中。",al={"瓦加什的牙齿获取地点","谁制造了瓦加什的牙齿","瓦加什的牙齿来源"}},f04ec442={q="鲁德拉·冻石为什么需要瓦加什的牙齿？",a="鲁德拉·冻石需要这颗獠牙，作为那头掠食者已死的实证。瓦加什一直在夜间袭击农场，吞食珍贵的公羊，威胁着冻石一家的生计，而铁炉堡的守卫兵力捉襟见肘，无力保护他们。",al={"为何需要瓦加什的牙齿","谁需要瓦加什的牙齿","鲁德拉·冻石獠牙"}}},fp="14,113,18.370.0,36.155.0,14.145.0,45.163.0"}
P.entries["item:fangore-s-paw"] = {n="范高雷的爪子",s="在赤脊山，范高雷中尉率领暗皮豺狼人进攻湖畔镇。他被斩下的爪子向所罗门镇长证明了他的死讯，镇长悬赏是为了消除范高雷对这座受困城镇的威胁。",h="在赤脊山，范高雷中尉率领暗皮豺狼人进攻湖畔镇。他被斩下的爪子向所罗门镇长证明了他的死讯，镇长悬赏是为了消除范高雷对这座受困城镇的威胁。",kw={"范高雷","豺狼人","湖畔镇","莫甘斯","爪子","赤脊山","暗皮","所罗门"},ang={["faction:Alliance"]="身为联盟的英雄，你击败范高雷并带回他的爪子，便能让饱受围困的湖畔镇稍得喘息，这座城镇得到的暴风城军事援助十分有限。"},sec={{t="陨落酋长的战利品",b="范高雷中尉是在赤脊山各处步步进逼的暗皮豺狼人的主要战地指挥官之一。他效命于叛变的法师莫甘斯，指挥部下袭击商道、偏远农场以及止水湖周围的防御工事。豺狼人劫掠者不会留下制服、官方印章或旗帜来确认死者身份，因此镇上的官员只能依靠实物证据。所罗门镇长要求带回范高雷的爪子，以证明他已被处决，让危机四伏的湖畔镇稍得喘息。"}},faq={{q="这只爪子属于谁？",a="这只爪子属于范高雷中尉，他是赤脊山暗皮豺狼人中臭名昭著的首领。他听命于黑暗巫师莫甘斯，组织劫掠并统率部队。",al={"范高雷是谁","这是谁的爪子","范高雷身份"}},{q="所罗门镇长为什么要这只爪子？",a="所罗门镇长发布通缉令，斥责范高雷是暴风城的邪恶敌人。他要求带回被斩下的爪子，作为这名暗皮中尉已被击杀的确凿物证。",al={"为何收集范高雷的爪子","所罗门悬赏凭证","镇长所需的证据"}},{q="范高雷中尉为谁效命？",a="范高雷效命于莫甘斯，这名离经叛道的黑暗魔法修习者盘踞在东部群山中的高塔里，威胁着湖畔镇，并指使豺狼人对抗王国。",al={"范高雷的主人","谁指挥范高雷","与莫甘斯的关系"}},{q="在哪里能找到范高雷中尉？",a="范高雷中尉在赤脊山的荒野中活动，出没于充满敌意的暗皮豺狼人营地之间。",al={"范高雷的位置","范高雷在哪里","寻找范高雷"}}},fx={["62ed4317"]={q="范高雷的爪子来自哪里？",a="这只爪子直接取自中尉范高雷的尸体。范高雷是盘踞在赤脊山的暗皮豺狼人中臭名昭著的首领。它不是人工制作的遗物或武器，而是在战斗中取得的一件断肢战利品，用以确认这名危险的豺狼人指挥官已被消灭。",al={"范高雷的爪子来历","范高雷的爪子来自哪里","谁制作了范高雷的爪子"}}},fp="13,185,28.436.0,28.166.0,41.184.0,38.177.0,34.101.0"}
P.entries["item:farren-s-report"] = {n="法尔林的报告",s="在南海镇，法尔林的报告记录了法尔林·奥里涅尔中尉对当地娜迦的调查结果。他希望这份军报能为他赢得返回暴风城的机会。",h="在南海镇，法尔林的报告记录了法尔林·奥里涅尔中尉对当地娜迦的调查结果。他希望这份军报能为他赢得返回暴风城的机会。",kw={"法尔林·奥里涅尔","法尔林的报告","萨缪尔森少校","娜迦","调任","雷德帕斯","南海镇","暴风要塞"},ang={["faction:Alliance"]="对联盟而言，法尔林的报告揭示了军中的运作手段：远在希尔斯布莱德的军官正设法到暴风城谋求更安全的差事。",["race:Human"]="身为联盟的人类，携带法尔林的报告，便将饱受围困的南海镇与暴风要塞中的王室宫廷联系在了一起。"},sec={{t="离开南海镇的通行证",b="法尔林·奥里涅尔中尉厌倦了南海镇战事不断的海岸、当地的长官，以及这片偏远的边疆。他让冒险者猎杀刺脊娜迦，收集它们构成威胁的证据，随后将调查结果整理成一份正式报告。法尔林打算将报告送交暴风要塞的卫兵队长萨缪尔森少校，而非自己的指挥官治安官雷德帕斯。萨缪尔森曾训练过法尔林，而法尔林希望这份报告能证明自己的能力，让自己立即调回暴风城，重享那里的舒适生活。"}},faq={{q="法尔林的报告是什么？",a="法尔林的报告是法尔林·奥里涅尔中尉撰写的一份军报，总结了他针对侵入南海镇海滩的刺脊娜迦所展开的行动。",al={"法尔林的报告","这份报告是什么","奥里涅尔的报告"}},{q="法尔林为什么想把报告送到暴风城？",a="法尔林希望离开南海镇，返回暴风城。他将报告送交昔日的导师、暴风城卫兵队长萨缪尔森少校，希望能获得一次如愿的调任。",al={"为何向暴风城送报告","法尔林的目标","为何找萨缪尔森"}},{q="法尔林为什么要向雷德帕斯隐瞒这份报告？",a="法尔林想避开治安官雷德帕斯和当地长官的审查。一名军官利用当地的威胁，为自己谋求调回安全的首都，可能会招致他们的不满。",al={"为何瞒着雷德帕斯","老雷德帕斯的秘密"}},{q="萨缪尔森少校收到报告后有何反应？",a="萨缪尔森少校称赞昔日的学生主动出击，对付南海镇的娜迦。他承诺，在下个月审议卫兵职务安排时，会考虑这份报告。",al={"萨缪尔森的反应","交报告调任"}}},fx={["97a8ff6b"]={q="法尔林的报告来自哪里？由谁撰写？",a="这份文件由法尔林·奥里涅尔中尉亲自在南海镇起草。法尔林驻扎在危机四伏的希尔斯布莱德丘陵前线，撰写报告，详细说明自己对付当地鱼人和纳迦的行动，希望引起首都高层的关注。",al={"谁写了法尔林的报告","法尔林的报告来历","谁制作了法尔林的报告"}}},fp="15,148,26.526.0,24.126.0,49.189.0,55.184.0,49.183.1"}
P.entries["item:fathom-core"] = {n="深渊之核",s="在月光神殿废墟下方，深渊之核记录着黑暗深渊中的元素活动。大地之环正在寻找它，以了解暮光之锤如何操纵这些力量。",h="在月光神殿废墟下方，深渊之核记录着黑暗深渊中的元素活动。大地之环正在寻找它，以了解暮光之锤如何操纵这些力量。",kw={"黑暗深渊","大地之环","深渊之核","深渊之石","耶努萨克雷","月光神殿废墟","暮光之锤","佐拉姆加前哨站"},ang={["class:Shaman"]="身为萨满祭司，你能明白大地之环为何重视深渊之核：它的记录能揭示他人如何操纵元素。",["faction:Horde"]="找回深渊之核既能帮助耶努萨克雷，也有助于巩固部落在佐拉姆加前哨站的据点，抵御暮光之锤的腐化图谋。"},sec={{t="元素编年史",b="深渊之核藏在月光神殿废墟下方的一块古老的深渊之石中。它记录着元素随时间推移发生的变化、紊乱与涌动。耶努萨克雷是驻守佐拉姆加前哨站的大地之环萨满祭司，他正在寻找这枚核心，以了解暮光之锤教徒如何驱使这一地区的元素为其所用。"}},faq={{q="深渊之核是什么？",a="深渊之核详细记录着附近元素活动的历史。它藏在月光神殿废墟中的一块古老的深渊之石中。",al={"深渊之核的作用","深渊之核的故事","它是什么"}},{q="深渊之核在哪里？",a="深渊之核位于灰谷海岸下方的黑暗深渊深处。它藏在月光神殿废墟水下的一块深渊之石中。",al={"深渊之核的位置","哪里能找到深渊之核","深渊之石的位置"}},{q="谁在寻找深渊之核，又是为了什么？",a="耶努萨克雷是驻守佐拉姆加前哨站的大地之环萨满祭司，他正在寻找深渊之核。他和同道们希望借助其中的元素变化记录，了解并遏制暮光之锤在废墟中的活动。",al={"谁需要深渊之核","耶努为何需要深渊之核","大地之环 深渊之核"}},{q="暮光之锤为何对黑暗深渊感兴趣？",a="暮光之锤教徒已盘踞在被淹没的废墟中，胁迫并腐化当地的元素。他们企图驱使这些力量实现黑暗的目的，并夺取这座地下神殿的控制权。",al={"暮光之锤 黑暗深渊","黑暗深渊中的教徒"}}},fp="11,193,19.338.0,24.130.0,33.148.0,34.218.0,61.213.0"}
P.entries["item:feather-charm"] = {n="羽毛咒符",s="在安威玛尔，羽毛咒符引起了一位术士训练师的注意。霜鬃新手随身携带着这些粗糙的饰物，其中蕴含着微弱的魔力。",h="在安威玛尔，羽毛咒符引起了一位术士训练师的注意。霜鬃新手随身携带着这些粗糙的饰物，其中蕴含着微弱的魔力。",kw={"阿拉玛尔·格里姆","安威玛尔","寒脊山谷","丹莫罗","羽毛咒符","霜鬃 新手","术士"},ang={["class:Warlock"]="作为丹莫罗的一名术士新手，你要从巨魔施法者手中夺取羽毛咒符，以此接受自律的考验。通过考验后，阿拉玛尔·格里姆便会将召唤小鬼的仪式传授给你。",["race:Gnome"]="作为安威玛尔的一名侏儒术士，你研究这些简陋的巨魔咒物，探究原始的霜鬃施法者所引导的粗粝而未经雕琢的魔力。"},sec={{t="巨魔饰物与黑暗研究",b="在安威玛尔西南方，霜鬃新手带着羽毛咒符穿行于积雪的洞穴中。他们的部族以野蛮排外著称，年轻的巨魔却也研习着原始的法术。咒符中蕴含的力量虽然微弱，却确凿无疑。安威玛尔的术士训练师阿拉玛尔·格里姆对这种粗浅的巨魔巫术颇感兴趣。他用这些咒符考验初出茅庐的术士，此时的他们正寻求束缚自己的第一只小鬼。"}},faq={{q="谁携带着这些羽毛咒符？",a="霜鬃新手携带着这些咒符，出没于寒脊山谷中安威玛尔西南方的一处积雪洞穴。",al={"羽毛咒符来自哪里","谁掉落羽毛咒符","霜鬃 新手咒符"}},{q="阿拉玛尔·格里姆为什么想要这些咒符？",a="阿拉玛尔·格里姆对咒符本身蕴含的魔力很感兴趣，也没想到巨魔的造物竟有这种力量。在传授召唤小鬼的方法之前，他用这些咒符考验术士学徒的体魄与魔法潜能。",al={"阿拉玛尔 为什么需要咒符","阿拉玛尔·格里姆羽毛咒符","格里姆 用咒符做什么"}},{q="霜鬃巨魔擅长使用魔法吗？",a="霜鬃部族以粗野和充满敌意著称，但部族中的新手也会施展简单的法术。他们的羽毛咒符能汇聚这些基础魔力，表明即使是初出茅庐的霜鬃施法者，也能驾驭奥术或萨满之力。",al={"霜鬃 巨魔会使用魔法吗","霜鬃 新手魔法"}},{q="这些咒符是什么模样？",a="霜鬃新手用羽毛和细绳制作简陋的护符。他们在丹莫罗寒冷的洞穴中进行最初的魔法训练时，会随身携带这些护符作为施法媒介。",al={"羽毛咒符描述","羽毛咒符外观"}}},fx={a2188847={q="羽毛咒符是什么？",a="羽毛咒符是一种粗糙的魔法护符，由丹莫罗的霜鬃巨魔新兵制作并随身携带。虽然看起来只是这些原始山地巨魔制作的简单饰物，这些咒符实际上能引导一种独特的魔法能量，引起了研究巨魔神秘法术的学者和施法者的注意。",al={"羽毛咒符是什么","羽毛咒符背景","关于羽毛咒符"}},["6facee45"]={q="羽毛咒符来自哪里，又是谁制作的？",a="这些咒符由霜鬃部族初学法术的施法者制作，他们住在安威玛尔西南方的冰冷洞穴中。这些年轻的巨魔学徒将刚刚萌发的力量注入羽毛，随身携带，作为在寒脊山谷练习基础法术时的施法媒介。",al={"谁制作羽毛咒符","羽毛咒符来自哪里","霜鬃羽毛咒符来源"}}},fp="13,143,31.410.0,33.94.0,32.217.0,43.232.0,29.145.0"}
P.entries["item:fel-cone"] = {n="魔锥果",s="泰达希尔的枝叶下，魔锥果将腐化带入森林。暗夜精灵守卫利用这些果实，对付附近的骗子。",h="泰达希尔的枝叶下，魔锥果将腐化带入森林。暗夜精灵守卫利用这些果实，对付附近的骗子。",kw={"多兰纳尔","魔锥果","萨特","寻求救赎","塞拉尔·刃叶","泰达希尔","赛恩·腐蹄"},ang={["class:Druid"]="身为德鲁伊，你眼看着林间原本健康的种荚变成冒烟的邪能残余。它们受到的腐化表明，泰达希尔的平衡是多么脆弱。",["race:NightElf"]="身为暗夜精灵，你知道魔锥果意味着泰达希尔的根系深处已滋生病害。即便是这棵年轻的世界之树，也无法免受恶魔的腐化。"},sec={{t="树冠中的枯萎",b="泰达希尔的枝叶下，魔锥果表明腐化已侵入这棵年轻的巨树。这些扭曲的松果掉落在地，冒着恶臭的绿色烟雾。它们散落在多兰纳尔东边不远处。污秽的魔法扭曲了周围的植物，贸然触碰或食用这些果实十分危险。"},{t="一剂苦药",b="赛恩·腐蹄是个萨特，靠欺骗路人为他效劳。旅人中了他的诡计后，塞拉尔·刃叶和哨兵便让他们收集魔锥果，装作无害的零食送给腐蹄。魔锥果中的腐化力量会让这个萨特暂时变成一只无害的青蛙。"}},faq={{q="魔锥果是什么？",a="魔锥果是从泰达希尔枝头落下的腐化松果。它受到违背自然的魔法污染，散发出诡异的绿色烟雾，蕴含着不稳定的变形之力。",al={"魔锥果是什么","魔锥果背景故事","什么是魔锥果"}},{q="在哪里能找到魔锥果？",a="魔锥果散落在泰达希尔的林地中，就在多兰纳尔东边不远处的树下。",al={"魔锥果在哪里","魔锥果位置","如何找到魔锥果"}},{q="森林议会为什么要收集魔锥果？",a="如果你在不知情的情况下帮赛恩·腐蹄伤害了自然生灵，森林议会会给你一个弥补过错的机会。他们让你收集魔锥果，骗赛恩吃下去，给他一个教训。",al={"寻求救赎 魔锥果","为什么收集魔锥果","谁要魔锥果"}},{q="吃下魔锥果会发生什么？",a="森林议会打算用魔锥果给赛恩·腐蹄一个教训。他应该会把魔锥果误当成无害的零食。",al={"魔锥果有什么用","吃魔锥果","赛恩·腐蹄 青蛙"}}},fp="8,128,20.285.0,17.270.1,19.172.0,29.89.0,55.211.1,42.126.1"}
P.entries["item:fel-moss"] = {n="魔苔",s="魔苔在泰达希尔的森林中蔓延，充满敌意的grell和grellkin携带着它阴险的腐化能量。这种污染威胁着世界之树的野生生物和土生土长的熊怪部族。",h="魔苔在泰达希尔的森林中蔓延，充满敌意的grell和grellkin携带着它阴险的腐化能量。这种污染威胁着世界之树的野生生物和土生土长的熊怪部族。",kw={"魔苔","瘤背","劣魔","小劣魔","幽影谷","塔琳德拉","泰达希尔","大槌乌萨尔"},ang={["class:Druid"]="身为塞纳里奥议会的德鲁伊，你将魔苔视为在泰达希尔蔓延的毒瘤。它带来的恶魔枯疫表明，这棵新生的世界之树是多么脆弱。",["race:NightElf"]="身为暗夜精灵，你敬奉泰达希尔，将它视为自己的新家园。魔苔是令人不安的凶兆，预示着这片神圣的枝叶间依然难觅安宁。"},sec={{t="世界之树的枯疫",b="尽管种下世界之树是为了恢复暗夜精灵的永生，并治愈自然世界，腐化却已侵入泰达希尔的枝头。魔苔就是这种衰败的明显征兆之一。形似小鬼的grell和grellkin在幽影谷肆虐，魔苔那违背自然的邪恶魔法附着在它们身上，随着苔藓生长而向外散发。树妖塔琳德拉收集样本，以查明腐化对这片神圣林冠的侵蚀究竟有多深。"},{t="疯狂的种子",b="世居泰达希尔高处的熊怪已屈服于魔苔的侵蚀。它们曾经平和安宁，如今却抛弃了传统居所，聚集成充满敌意的瘤背部族。在大槌乌萨尔等首领的带领下，魔苔的邪恶力量使它们陷入疯狂，显露出正在这棵巨树内部扎根的病患。"}},faq={{q="什么是魔苔？",a="魔苔是泰达希尔一种遭到腐化的植物物质。它阴险而污秽的能量附着在劣魔和劣魔怪身上，威胁着周围的野生生物和当地的熊怪。",al={"魔苔背景故事","魔苔是什么","魔苔有什么作用"}},{q="魔苔从何而来？",a="在幽影谷一带，劣魔和劣魔怪携带着一团团魔苔，穿行于泰达希尔的山丘之间。苔藓蕴藏着腐化能量，在世界之树的森林中蔓延。",al={"哪里能获得魔苔","魔苔掉落","魔苔来源"}},{q="魔苔如何影响熊怪？",a="魔苔的邪恶力量已经侵蚀了泰达希尔的本土熊怪。它们抛弃了传统居所，组成了充满敌意、排斥外族的瘤背部族，在大槌乌萨尔等首领的带领下陷入疯狂。",al={"熊怪腐化","瘤背为何疯狂","瘤背魔苔"}},{q="谁在设法阻止魔苔蔓延？",a="在幽影谷，树妖塔琳德拉请年轻的守卫者从劣魔怪身上收集魔苔样本，以查明腐化在林地中蔓延得有多深。她指引心怀忧虑的守护者去找多兰纳尔的阿斯瑞达斯·熊皮等德鲁伊。",al={"谁研究魔苔","谁需要魔苔","塔琳德拉任务"}}},fp="8,162,24.408.0,16.290.1,17.155.0,30.159.0,38.205.0,45.249.0"}
P.entries["item:felix-s-box"] = {n="菲利克斯的盒子",s="菲利克斯的盒子落在安威玛尔西南方的霜鬃营地里，远离了丢失它的侏儒难民。",h="菲利克斯的盒子落在安威玛尔西南方的霜鬃营地里，远离了丢失它的侏儒难民。",kw={"安威玛尔","寒脊山谷","丹莫罗","菲利克斯","菲利克斯的盒子","霜鬃","诺莫瑞根","难民"},ang={["profession:Engineering"]="身为工程师，你知道流离失所的侏儒工匠失去赖以谋生的工具和容器，会有多么艰难。",["race:Gnome"]="作为一名从寒脊山谷起步的侏儒，你可以在诺莫瑞根疏散后找回菲利克斯的财物，帮助这位同样背井离乡的同胞。"},sec={{t="逃离诺莫瑞根时的遗失之物",b="清除穴居人威胁的行动失败后，辐射席卷了诺莫瑞根。菲利克斯随侏儒们逃入寒脊山谷，为了躲避毒气，将财物和制作工具丢在了积雪的路边。他还没来得及返回，霜鬃巨魔就抢走了这些东西。他们把他的盒子、箱子和一桶螺栓带到了安威玛尔西南方的聚居地。"},{t="难民的困境",b="菲利克斯不习惯暴力，也难以适应丹莫罗的荒野。他需要途经安威玛尔的冒险者帮忙找回财物。找回这些东西能让生活恢复几分正常，也能让这位流离失所的工匠有谋生的手段。诺莫瑞根沦陷时，他失去了一切。"}},faq={{q="菲利克斯的盒子是什么？",a="菲利克斯的盒子里装着菲利克斯的私人物品。他是一名侏儒工匠，在辐射蔓延至全城后逃离了诺莫瑞根。",al={"菲利克斯的盒子","这是什么盒子","菲利克斯的盒子的故事"}},{q="盒子是怎么落到霜鬃巨魔手里的？",a="菲利克斯为躲避诺莫瑞根的放射性毒气而逃亡时，丢下了自己的工具。霜鬃巨魔把路边的财物搬到了安威玛尔西南方的营地。",al={"巨魔为什么有菲利克斯的盒子","谁偷走了菲利克斯的盒子","它是怎么丢失的"}},{q="菲利克斯是谁？",a="菲利克斯是安威玛尔的一名侏儒难民。诺莫瑞根的沦陷给他留下了创伤，也让他失去了工具和私人物品。",al={"菲利克斯","菲利克斯是谁"}},{q="菲利克斯还丢了哪些物品？",a="霜鬃巨魔除了拿走盒子，还拿走了菲利克斯的箱子和螺钉桶。他们把这三样东西都带到了安威玛尔西南方的营地。",al={"菲利克斯的其他物品","菲利克斯的财物","菲利克斯丢失的工具"}}},fx={["8f76c19d"]={q="菲利克斯为什么想找回他的盒子？",a="菲利克斯是一名流离失所的侏儒难民，辐射席卷诺莫瑞根后，他惊慌失措地逃离了城市。在仓皇逃命的途中，他的工具和个人物品落入了霜鬃巨魔手中。身为滞留安威玛尔的普通工匠和难民，他没有独自闯入巨魔营地的战斗本领，却迫切需要找回被抢走的盒子和财物，重新开始生活。",al={"菲利克斯为什么要盒子","为什么寻找菲利克斯的盒子","菲利克斯的盒子用途"}}},fp="11,98,34.387.0,20.287.0,20.141.0,49.154.0,25.138.0,32.140.0"}
P.entries["item:felix-s-bucket-of-bolts"] = {n="菲利克斯的螺钉桶",s="在丹莫罗，霜鬃巨魔把菲利克斯的螺钉桶带回了营地。菲利克斯从诺莫瑞根带来的工具不见了。",h="在丹莫罗，霜鬃巨魔把菲利克斯的螺钉桶带回了营地。菲利克斯从诺莫瑞根带来的工具不见了。",kw={"安威玛尔","螺钉","丹莫罗","菲利克斯","霜鬃","诺莫瑞根","难民","巨魔","温德尔波特"},ang={["profession:Engineering"]="身为工程师，你需要基本的五金零件才能干活。在丹莫罗的风雪中重新开始时，一桶螺钉也至关重要。",["race:Gnome"]="身为侏儒，每一桶从诺莫瑞根抢救出来的零件，都能帮助难民在寒脊山谷重新站稳脚跟。"},sec={{t="流亡者散落的工具",b="石腭怪引发灾难后，菲利克斯带着工具逃离了诺莫瑞根。辐射迫使成千上万的侏儒带上能拿走的东西，逃进丹莫罗冰冷的荒野。菲利克斯前往安威玛尔，却遭到了来自镇子西南方峭壁的霜鬃巨魔伏击。他们抢走了他的财物，包括装着螺钉和零件的桶，让这位工匠在流亡途中失去了从事手艺所需的材料。"}},faq={{q="菲利克斯的螺钉桶是什么？",a="菲利克斯的桶里装着螺钉、五金零件和修修补补用的物资。这位流亡的侏儒正在安威玛尔避难。",al={"螺钉桶","菲利克斯的桶","菲利克斯的螺钉桶"}},{q="谁偷走了桶？",a="菲利克斯逃离诺莫瑞根的灾难时，霜鬃巨魔偷走了他的桶和其他财物。",al={"谁拿走了螺钉","巨魔偷走了桶","菲利克斯的螺钉在谁手里"}},{q="巨魔把桶带到了哪里？",a="霜鬃巨魔把桶带回了寒脊山谷中位于安威玛尔西南方峭壁间的营地。",al={"螺钉在哪里","桶的位置","菲利克斯螺钉营地"}},{q="这个桶为什么对菲利克斯很重要？",a="菲利克斯需要螺钉和零件来从事他的手艺。侏儒难民逃离诺莫瑞根时几乎一无所有，因此，在远离家乡的地方求生和重建时，基本物资十分重要。",al={"菲利克斯为什么需要螺钉","菲利克斯螺钉的重要性"}}},fp="23,144,27.424.0,32.120.0,21.109.0,29.107.0,38.160.0"}
P.entries["item:felix-s-chest"] = {n="菲利克斯的箱子",s="在安威玛尔西南方的一处霜鬃营地里，菲利克斯的箱子装着他逃离诺莫瑞根时遗失的物品。",h="在安威玛尔西南方的一处霜鬃营地里，菲利克斯的箱子装着他逃离诺莫瑞根时遗失的物品。",kw={"难民的困境","安威玛尔","寒脊山谷","菲利克斯","菲利克斯的箱子","霜鬃","诺莫瑞根"},ang={["race:Gnome"]="身为侏儒，你可以从菲利克斯的箱子想到诺莫瑞根那场混乱的撤离。逃难的侏儒几乎失去了一切，他们的财物不是遗落在荒野，就是落入了搜掠者之手。"},sec={{t="难民的损失",b="穴居人和有毒的放射性尘埃迫使侏儒逃离诺莫瑞根，难民们带着能带走的东西，穿过白雪覆盖的丹莫罗。霜鬃巨魔沿路搜掠，追上了四散的幸存者。他们把菲利克斯结实的箱子带回了峭壁间的营地，他的工具包和私人物品至今仍混在他们的补给品中。"}},faq={{q="菲利克斯的箱子里有什么？",a="菲利克斯的箱子里装着他逃离诺莫瑞根时抢救出来的私人物品。他为了躲避致命的辐射而仓皇逃命，将这些东西遗落在了身后。这些物品对巨魔而言没什么价值，却是他昔日生活留下的东西。",al={"菲利克斯的箱子里的物品","箱子里有什么","菲利克斯的箱子战利品"}},{q="为什么菲利克斯的物品会在霜鬃巨魔手中？",a="霜鬃巨魔伏击了四散的侏儒难民，抢走了他们的装备。他们骚扰旅人，在寒脊山谷各处搜掠，把丢弃的行李带回营地。",al={"巨魔为什么有菲利克斯的箱子","谁偷了菲利克斯的箱子","巨魔 菲利克斯"}},{q="箱子在哪里？",a="菲利克斯的箱子位于寒脊山谷的安威玛尔西南方，在一处霜鬃巨魔聚落的帐篷附近，与其他掠来的物资放在一起。",al={"菲利克斯的箱子在哪里","菲利克斯的箱子位置","寻找菲利克斯的箱子"}}},fx={cd14610d={q="菲利克斯的箱子是什么？",a="菲利克斯的箱子装着他的个人物品和工具，这名侏儒难民如今正在安威玛尔避难。诺莫瑞根遭到辐射污染时，菲利克斯逃入丹莫罗，却在混乱的逃亡途中让箱子落入了霜鬃巨魔手中。",al={"菲利克斯的箱子是什么","菲利克斯的箱子","菲利克斯的箱子归谁所有"}},bcb95cf5={q="菲利克斯为什么想找回他的箱子？",a="菲利克斯逃离悲惨沦陷的诺莫瑞根时，几乎一无所有。箱子里装着他的私人物品和实用工具，是他流落寒脊山谷的矮人之间时，赖以生存并重新开始生活的必需品。他没有亲自对抗霜鬃巨魔的战斗本领，只能依靠愿意帮忙的冒险者找回箱子。",al={"菲利克斯为什么要箱子","为什么需要菲利克斯的箱子","为什么取回菲利克斯的箱子"}}},fp="13,95,18.350.0,29.235.0,52.192.0,27.135.0"}
P.entries["item:felstalker-hoof"] = {n="地狱捕猎者的蹄子",s="在杜隆塔尔的试炼谷，年轻的萨满祭司要面对恶魔地狱捕猎者，检验自己是否已准备就绪。他们将这些恶魔的蹄子交给坎纳甘·地鸣，随后才会学习如何与大地之灵沟通。",h="在杜隆塔尔的试炼谷，年轻的萨满祭司要面对恶魔地狱捕猎者，检验自己是否已准备就绪。他们将这些恶魔的蹄子交给坎纳甘·地鸣，随后才会学习如何与大地之灵沟通。",kw={"火刃集会所","大地的召唤","坎纳甘·地鸣","杜隆塔尔","大地灵契","地狱捕猎者","地狱捕猎者的蹄子","试炼谷"},ang={["class:Shaman"]="身为萨满祭司，你要先杀死恶魔，收集它们的蹄子，由此踏上与大地之灵沟通的道路。这场试炼考验你的耐心与坚韧，而这些正是运用大地图腾所需的品质。",["faction:Horde"]="杜隆塔尔训练场中的恶魔felstalkers提醒着部落，火刃氏族的腐化仍在这片土地上徘徊。"},sec={{t="萨满祭司的试炼",b="坎纳甘·地鸣派年轻的萨满祭司对抗威胁杜隆塔尔的恶魔污染。火刃集会所位于试炼谷北部，地狱捕猎者与集会所的邪恶仆从在此游荡。取得一只地狱捕猎者的蹄子，考验的是萨满祭司的耐力、决心与心志。制服这些野兽的人，便证明自己已准备好领受大地的奥秘，并配制仪式所需的灵契，以便与元素之灵沟通。"}},faq={{q="地狱捕猎者的蹄子有什么用途？",a="你要将两只地狱捕猎者的蹄子交给试炼谷的坎纳甘·地鸣。它们证明萨满祭司学徒具备足够的力量与心志，可以开始与大地元素沟通。",al={"地狱捕猎者的蹄子有什么用","蹄子任务物品","为什么要收集地狱捕猎者的蹄子"}},{q="这些蹄子来自哪里？",a="这些蹄子来自恶魔邪灵劣魔，它们出没于杜隆塔尔试炼谷北部的火刃集会所内外。",al={"哪里获取地狱捕猎者的蹄子","地狱捕猎者的蹄子位置","谁掉落蹄子"}},{q="谁需要这些蹄子？",a="坎纳甘·地鸣是试炼谷大兽穴附近的萨满祭司训练师，他会在大地的召唤仪式期间要求收集这些蹄子。",al={"谁需要地狱捕猎者的蹄子","蹄子交给谁","坎纳甘·地鸣任务"}},{q="任何冒险者都能收集这些蹄子吗？",a="正在接受元素入门试炼的萨满祭司会寻找地狱捕猎者的蹄子。战士、术士和潜行者在谷中各有自己的试炼，并不需要这些蹄子。",al={"非萨满祭司能获取蹄子吗","蹄子是否仅限萨满祭司"}}},fp="15,176,16.418.0,37.165.0,32.125.0,26.127.0,40.156.0"}
P.entries["item:fenwick-s-head"] = {n="芬维克的头颅",s="被遗忘者盗贼在洛丹米尔湖沿岸搜寻芬威克萨托斯。奉瓦里玛萨斯大人传下的命令，他们要取下他的头颅，作为已将他处决的证据。",h="被遗忘者盗贼在洛丹米尔湖沿岸搜寻芬威克萨托斯。奉瓦里玛萨斯大人传下的命令，他们要取下他的头颅，作为已将他处决的证据。",kw={"亡灵哨兵","芬威克","洛丹米尔","米奈特·卡加德","潜行者区","银松森林","萨托斯","瓦里玛萨斯"},ang={["class:Rogue"]="身为盗贼，取得芬维克的头颅，便能证明一名崭露头角的被遗忘者密探是可靠的亡灵哨兵，并赢得接受高阶训练的机会。",["race:Undead"]="身为亡灵，你见证了被遗忘者如何无情地镇压敌对亡灵势力，这些势力正与他们争夺银松森林和洛丹米尔湖沿岸的控制权。"},sec={{t="暗影中的契约",b="米奈特·卡加德在幽暗城的潜行者区，根据恐惧魔王瓦里玛萨斯传来的紧急情报展开行动。芬威克萨托斯是一名敌对的亡灵首领，已在银松森林洛丹米尔湖畔腐朽的码头附近建立了据点。为了阻止他集结敌对亡灵对抗被遗忘者，卡加德派遣有潜力的亡灵哨兵前去寻找并杀死他，再带回他的头颅作为证据。"},{t="入门的试炼",b="对亡灵哨兵密探而言，将芬维克的头颅带给卡加德，是一场超越领取赏金的试炼。这颗被斩下的头颅证明了盗贼潜入与暗杀的本领。成功之后，便能向被遗忘者大师学习更深入、更专精的暗影技艺。"}},faq={{q="芬威克萨托斯是谁？",a="瓦里玛萨斯大人认定芬威克萨托斯是一名盘踞在银松森林的亡灵首领。他在洛丹米尔湖破败的码头附近，直接威胁着被遗忘者在这一地区的利益。",al={"芬威克是谁","芬威克 萨托斯的故事","萨托斯是谁"}},{q="谁想要芬维克的头颅？",a="米奈特·卡加德是幽暗城潜行者区的一名亡灵哨兵训练师，他遵照瓦里玛萨斯大人传下的紧急命令，要求取得芬维克的头颅。",al={"谁想要头颅","交给谁","米奈特·卡加德"}},{q="芬威克萨托斯在哪里？",a="据亡灵哨兵斥候报告，芬威克萨托斯就在银松森林洛丹米尔湖岸边破败的码头旁。",al={"芬威克 萨托斯的位置","芬威克在哪里","寻找芬威克"}},{q="为什么必须斩下他的头颅？",a="米奈特·卡加德要求先拿出实物证据，证明威胁已经消除，才会让密探接受高阶暗影训练。",al={"为什么取他的头颅","为什么将他斩首"}}},fp="14,163,27.399.0,17.270.0,24.210.0,25.150.0,33.116.0,29.132.0"}
P.entries["item:fey-dragon-scale"] = {n="灵龙的鳞片",s="石爪峰一带的灵龙身上，有着金吉尔渴求的鳞片。这位黑暗之矛巫医用一片鳞片作材料，调制出一种嘲弄暗夜精灵自然魔法的药剂。",h="石爪峰一带的灵龙身上，有着金吉尔渴求的鳞片。这位黑暗之矛巫医用一片鳞片作材料，调制出一种嘲弄暗夜精灵自然魔法的药剂。",kw={"灵龙","灵龙的鳞片","森林魔法","金吉尔","玛拉卡金","纳尔塔萨","石爪峰"},ang={["faction:Horde"]="身为部落的一员，你帮助金吉尔巩固部落在石爪山脉的立足之地，并打击山坡更高处的暗夜精灵势力。",["race:NightElf"]="身为暗夜精灵，你深知灵龙是kaldorei珍爱的伙伴，也是森林的守护者。看到它们的鳞片被取走，用于巨魔巫医那致命的嘲弄，便是目睹对自然的亵渎。"},sec={{t="林间的珍稀收获",b="石爪峰一带，灵龙出没于卡利姆多的荒野林地。它们的鳞片闪耀着自然魔法的光辉。暗夜精灵尊它们为无害的林间精魂与盟友，外来者却将它们的鳞片视为珍贵的魔法材料。"},{t="嘲弄之药",b="在玛拉卡金，巫医金吉尔调制着一种嘲弄卡多雷传统的药剂。他将灵龙的鳞片与树液、猫科动物的胡须，以及数十又数十颗奔鹿的眼睛混合，把这东西称作“森林魔法”。他打算将这残酷的药剂用在关在笼中的三名暗夜精灵身上。"}},faq={{q="这片鳞片从何而来？",a="这片鳞片来自石爪峰周边高地林间的灵龙，包括狡猾的灵龙和纳尔塔萨。",al={"灵龙的鳞片掉落","哪里能找到灵龙的鳞片","谁掉落灵龙的鳞片"}},{q="巫医金吉尔为什么想要灵龙的鳞片？",a="玛拉卡金的巫医金吉尔想将这片鳞片与其他林间材料一起，用来调制一种药剂，他讥讽地称之为“森林魔法”，准备将它用在囚于笼中的暗夜精灵俘虏身上。",al={"金吉尔为什么要这个","鳞片有什么用途","金吉尔森林魔法材料"}},{q="金吉尔调好药剂后会发生什么？",a="金吉尔打算将调好的药剂用在他俘虏的三名暗夜精灵身上。当他付诸行动时，这些俘虏的命运便会揭晓。",al={"金吉尔用药剂做什么","金吉尔魔法结果","金吉尔的俘虏"}}},fx={["9423a9c1"]={q="灵龙的鳞片是什么？",a="灵龙的鳞片是从石爪峰难以寻觅的仙女龙身上采集的鳞片，闪烁着虹彩般的光泽。这些神秘生物与荒野的自然能量息息相关。对炼金师或巫医而言，这种鳞片是强效的魔法试剂，蕴含着古老森林的原始精华。",al={"灵龙的鳞片是什么","灵龙鳞片的背景","关于灵龙的鳞片"}}},fp="16,160,21.219.0,20.288.1,32.120.0,54.178.0,44.142.1"}
P.entries["item:filled-amethyst-phial"] = {n="装满的紫水晶瓶",s="在泰达希尔，神谕之树下月亮井的井水被装入紫水晶瓶。科瑞萨斯·月怒收下井水，供塞纳里奥德鲁伊研究世界之树生长异常的问题。",h="在泰达希尔，神谕之树下月亮井的井水被装入紫水晶瓶。科瑞萨斯·月怒收下井水，供塞纳里奥德鲁伊研究世界之树生长异常的问题。",kw={"紫水晶瓶","科瑞萨斯·月怒","大地之冠","装满的紫水晶瓶","月亮井","神谕林地","神谕之树","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，你知道塞纳里奥德鲁伊将月亮井奉为自然与星界能量的源泉。他们使用像这个瓶子一样经过净化的容器，研究泰达希尔遭受侵蚀的生态。",["race:NightElf"]="身为kaldorei，你装满这个瓶子时，深知守护巨龙拒绝了你们的新家园，而你们失去的永生也尚未恢复。"},sec={{t="神谕之树之水",b="神谕林地位于泰达希尔西北部，最古老、力量最强大的月亮井就坐落在神谕之树下。枝干各处的其他月亮井满足着暗夜精灵的日常所需，而这里的井水蕴含着艾露恩的赐福的原始精华。守护世界之树健康的德鲁伊用紫水晶瓶收集井水，留作检验和净化仪式之用。"},{t="有缺憾的新生",b="德鲁伊密切关注着泰达希尔生长异常的问题，科瑞萨斯·月怒收下了这份水样。大德鲁伊范达尔·鹿盔培育了这棵巨树，意在取代倒下的诺达希尔，但守护巨龙拒绝为它赐福。没有诺兹多姆的祝福来恢复暗夜精灵的永生，也没有阿莱克丝塔萨对其生命力的庇护，泰达希尔始终生长不良，饱受腐化侵扰。就连林地中的圣水，也显露出正在世界之树内扎根的病症。"}},faq={{q="这个瓶子里的水来自哪里？",a="井水来自神谕林地的月亮井，就在泰达希尔西北部的神谕之树下。",al={"在哪里装满","月亮井位置","神谕之树的井"}},{q="神谕林地的月亮井有什么特别之处？",a="神谕林地的月亮井是泰达希尔上最早建成、力量最强大的月亮井。它坐落在古老的神谕之树下，蕴含着艾露恩力量的浓缩精华。",al={"为何选择神谕林地","神谕林地月亮井的重要性"}},{q="是谁请你收集这些井水？",a="驻守多兰纳尔的暗夜精灵德鲁伊科瑞萨斯·月怒请你收集井水，用于大地之冠仪式。",al={"谁需要紫水晶瓶","科瑞萨斯任务"}},{q="德鲁伊为什么要检验泰达希尔的月亮井？",a="德鲁伊检验泰达希尔的月亮井，是因为这棵巨树在培育时没有得到守护巨龙的祝福，至今仍然脆弱。水样有助于他们监测令人忧虑的腐化和生长不良问题。",al={"为何检验井水","泰达希尔的病症"}}},fp="21,165,24.345.0,16.457.1,45.100.0,44.173.0,34.125.0,50.195.0"}
P.entries["item:filled-blue-waterskin"] = {n="装满水的蓝色水囊",s="萨满祭司在灰谷的星尘废墟采集试炼所需的水。装满水的蓝色水囊盛着从古老喷泉中采集的纯净水样。",h="萨满祭司在灰谷的星尘废墟采集试炼所需的水。装满水的蓝色水囊盛着从古老喷泉中采集的纯净水样。",kw={"灰谷","布瑞恩","水之召唤","装满水的蓝色水囊","密斯特拉湖","星尘废墟","萨满祭司任务"},ang={["class:Shaman"]="作为萨满祭司，你采集这些水，完成掌握水之力量的最后一步，跨越敌对阵营的边界，与大自然最纯净的水源沟通。",["faction:Horde"]="作为部落的学徒，你向北深入灰谷战火纷争的森林，踏入暗夜精灵的祖传领地，完成神圣的仪式，一路面对切实的危险。"},sec={{t="灰谷的圣泉",b="参加水之召唤试炼的学徒从贫瘠之地向北，进入灰谷的茂密森林。越过密斯特拉湖，星尘废墟依山而立，山脉将灰谷与石爪山分隔开来。凶猛的森林野兽守卫着这处隐蔽的精灵圣地。湖心有一座未受侵扰的喷泉，其中的泉水既未遭腐化，也未因干旱而枯竭。从泉池中装满的蓝色水囊，盛着萨满导师为仪式中的调和所寻求的水样。"},{t="调和之仪",b="布瑞恩是一位精通水之奥秘的隐士，住在南贫瘠之地的一座山丘上，她需要这最后一份水样。她将它与来自不同水井和泉眼的水混合，再蒸馏出纯净的精华，制成祭品。这份祭品能让水元素之灵显形并安抚它们，使学徒完成试炼。"}},faq={{q="灌满这个水囊的水要在哪里采集？",a="水来自灰谷西南部星尘废墟湖心的一座小喷泉，那里位于密斯特拉湖的另一边。",al={"在哪里装水","星尘废墟喷泉","水源位置"}},{q="谁需要这些水？",a="住在南贫瘠之地的隐士布瑞恩需要这些水，用于她交给萨满新手的水之召唤试炼。",al={"谁需要蓝色水囊","布瑞恩 水","水之召唤任务人物"}},{q="采集这份水样有什么目的？",a="布瑞恩需要这最后一份水样来调制一剂极为纯净的水，让有志成为萨满祭司的学徒能与水元素之灵沟通，并向它们致敬。",al={"为什么需要它","装满水的蓝色水囊用途"}},{q="采水的地方危险吗？",a="是的。星尘废墟栖息着具有敌意的野生生物，包括当地的元素生物和凶猛的野兽，它们守护着这片古老的精灵林地。",al={"星尘废墟危险","灰谷喷泉安全吗"}}},fp="21,134,26.430.0,17.310.0,51.136.0,24.110.0,46.160.0,50.135.0"}
P.entries["item:filled-brown-waterskin"] = {n="装满水的棕色水囊",s="在贫瘠之地，装满水的棕色水囊盛着布瑞恩小屋下方池塘里的淡水。萨满学徒将水囊带给她，用来开始调制灵契，以便与水之灵沟通。",h="在贫瘠之地，装满水的棕色水囊盛着布瑞恩小屋下方池塘里的淡水。萨满学徒将水囊带给她，用来开始调制灵契，以便与水之灵沟通。",kw={"贫瘠之地","布瑞恩","棕色水囊","水之召唤","装满水的棕色水囊","野猪人","灵契","萨满祭司任务"},ang={["class:Shaman"]="身为萨满祭司，你在水之召唤期间前去取水，完成布瑞恩给你的第一项实践考验。这项考验教你尊重围绕水源的平衡与强烈情感。"},sec={{t="赋予生命的干旱",b="布瑞恩小屋下方的池塘是贫瘠之地少有的淡水来源。附近的野猪人为争夺它而激烈交战，萨满学徒由此看到了水源的匮乏如何迫使生灵捍卫赖以生存的资源。"}},faq={{q="装满水的棕色水囊有什么用途？",a="你将水带到南贫瘠之地布瑞恩的小屋，交给她。她用这些水开始调制灵契，这种饮剂能让萨满祭司感知水之灵，并与之沟通。",al={"棕色水囊用途","装满水的棕色水囊是什么","装满水的棕色水囊怎么用"}},{q="这些水来自哪里？",a="这些水来自布瑞恩那间偏僻小屋下方的一处小淡水池，沿山脊往下走便能找到。当地的野猪人为争夺这处水池而激烈交战。",al={"哪里取水","池塘位置","水池在哪里"}},{q="野猪人为何争夺这处水源？",a="干旱的贫瘠之地极少降雨，因此每逢下雨，野猪人都会设宴庆祝。他们守卫天然泉水，抵御外来者，甚至不惜战死。",al={"野猪人为何攻击","野猪人与水","水为何对野猪人如此神圣"}}},fp="22,194,21.186.0,44.170.0,32.130.0,49.153.0"}
P.entries["item:filled-cliffspring-falls-sampler"] = {n="盛满的峭壁之泉取样器",s="在黑海岸的峭壁之泉附近，盛满的峭壁之泉取样器中装着从源头取来的污水。塞纳里奥议会需要用它来研究侵袭当地鹿群的疾病。",h="在黑海岸的峭壁之泉附近，盛满的峭壁之泉取样器中装着从源头取来的污水。塞纳里奥议会需要用它来研究侵袭当地鹿群的疾病。",kw={"奥兰达利亚·夜歌","奥伯丁","塞纳里奥议会","峭壁之泉","黑海岸","德迪利特·星焰","有毒的水","取样器"},ang={["class:Druid"]="身为德鲁伊，取回并研究这份污水是对你的考验，也为掌握Cure Poison打下基础。",["race:NightElf"]="身为黑海岸的暗夜精灵，你协助守护壁泉的源头，保护奥伯丁的生态免遭外来邪恶力量的腐蚀。"},sec={{t="受污染的源头",b="峭壁之泉将东部高地的水送往黑海岸的大部分地区。最近，当地的鹿群染上了一种非自然的疾病。应月光林地的德迪利特·星焰之请，德鲁伊学徒前往敌对纳迦盘踞的洞口取水。瓶中的液体明显污浊，表明淡水水源已遭污染。"},{t="寻求解药",b="奥伯丁的奥兰达利亚·夜歌接收这份污水，作为供塞纳里奥议会研究的证据。奥兰达利亚没有将其丢弃，而是检查其中的毒素。了解这些污泥的特性后，德鲁伊便能制成治疗药膏，这是迈向一项仪式的关键一步，那项仪式能让修行者获得克制毒素的力量。"}},faq={{q="盛满的峭壁之泉取样器里装着什么？",a="取样器里装着从黑海岸峭壁之泉附近一处洞穴入口取来的污水。水的颜色明显异常，其中的毒素正是导致当地鹿群患病的毒素。",al={"取样器内容物","瓶里是什么水","样本里有什么"}},{q="谁要求采集这份水样？",a="塞纳里奥议会的德迪利特·星焰请年轻的德鲁伊采集这份样本。奥伯丁的奥兰达利亚·夜歌接收样本，以研究毒素并配制解药。",al={"谁要水样","取样器交给谁","谁需要盛满的取样器"}},{q="峭壁之泉为何如此重要？",a="峭壁之泉是黑海岸最主要的饮用水源。泉水中的腐化沿着当地水道蔓延，危害荒野。",al={"为何是峭壁之泉","峭壁之泉的重要性"}},{q="是什么让水变得污浊？",a="敌对的纳迦占据了水源附近的一处洞穴，水样正是在那里采集的。它们出现的同时，水质开始恶化，当地动物也染上了疾病。",al={"谁在水里下毒","泉水为何有毒","纳迦 峭壁之泉"}}},fp="32,189,16.340.0,16.310.1,52.176.0,31.171.0,38.152.0,39.156.0"}
P.entries["item:filled-containment-coffer"] = {n="装满的封灵箱",s="在幽暗城，被遗忘者施法者用装满的封灵箱捕获不稳定的魔法实体。显形卷轴能让炼金房中的裂隙生物显形并削弱它们，法师便可将其封入箱中，留待检验。",h="在幽暗城，被遗忘者施法者用装满的封灵箱捕获不稳定的魔法实体。显形卷轴能让炼金房中的裂隙生物显形并削弱它们，法师便可将其封入箱中，留待检验。",kw={"奥格诺恩","安娜斯塔西娅·哈特威尔","炼金房","奥术扰动","显形卷轴","封灵箱","装满的封灵箱","裂隙生物"},ang={["class:Mage"]="身为被遗忘者学徒，你将操作封灵箱作为防护法术的实践课程。你会学习如何让隐藏的魔法实体显形，并将不稳定的奥术能量束缚在实体结界之中。",["race:Undead"]="身为Undead，你知道炼金房的安全对被遗忘者至关重要。调查并控制一处神秘的魔法裂口，是家园中亟待解决的问题。"},sec={{t="捕获无形之物",b="炼金房中奥格诺恩的店铺出现了魔法扰动。被遗忘者法师安娜斯塔西娅·哈特威尔召集奥术研习者，捕获引发扰动的实体。裂隙生物是活的魔法能量，无法被看见，普通牢笼也关不住它们。施法者用显形卷轴让它们现形，在战斗中将其击败，再迅速合上备好的封灵箱，将它们困在其中。密封的箱子既能保护携带者免遭剧烈的魔法反噬，也能让这些生物保持完整，以供魔法解剖。"},{t="奥术勘验",b="幽暗城中活的法力生物构成了严重威胁。这些生物被封入封灵箱后，便会被送到安娜斯塔西娅·哈特威尔和城中的学者手中。被遗忘者法师想要查明，这些入侵究竟源自艾泽拉斯魔法结构中的天然裂隙，还是一场蓄意针对王国的魔法袭击的前期试探。"}},faq={{q="装满的封灵箱里有什么？",a="每只箱子里都关着一只捕获的裂隙生物，那是由原始魔法能量构成的隐形生物，出现在炼金房中奥格诺恩的炼金店内。",al={"箱子里有什么","箱中之物","装满的封灵箱里的怪物"}},{q="如何装满封灵箱？",a="法师诵读显形卷轴，让隐藏的生物现形，在战斗中将其击败，然后趁残余能量消散之前，用空箱子将其捕获。",al={"如何装满封灵箱","如何捕获裂隙生物","装满封灵箱"}},{q="幽暗城里谁需要这些装满的封灵箱？",a="安娜斯塔西娅·哈特威尔是幽暗城魔法区中一位声望卓著的法师训练师，她收集这些密封的箱子，以调查威胁城市的扰动。",al={"谁收封灵箱","封灵箱任务给予者","安娜斯塔西娅·哈特威尔封灵箱"}},{q="被遗忘者为什么研究这些生物？",a="幽暗城的学者需要查明，这种异常究竟源自当地魔法流动中的随机裂口，还是敌对魔法势力蓄意发动的协同攻击。",al={"为何研究裂隙生物","幽暗城裂隙成因"}}},fp="25,201,19.535.0,16.350.0,43.150.0,35.181.0,44.159.0,46.169.0"}
P.entries["item:filled-crystal-phial"] = {n="装满水的水晶瓶",s="在幽影谷，装满水的水晶瓶盛着从奥达希尔北面的月亮井中取来的水。特纳隆·雷拳让年轻的暗夜精灵采集井水，作为了解泰达希尔神圣力量的第一课。",h="在幽影谷，装满水的水晶瓶盛着从奥达希尔北面的月亮井中取来的水。特纳隆·雷拳让年轻的暗夜精灵采集井水，作为了解泰达希尔神圣力量的第一课。",kw={"奥达希尔","大地之冠","水晶瓶","装满水的水晶瓶","月亮井","幽影谷","特纳隆·雷拳","永恒之井"},ang={["class:Druid"]="身为德鲁伊，你对月亮井水怀有深深的敬意，并用它焕发生机的能量照料遭到腐化的植物，滋养参天巨树。",["race:NightElf"]="身为一名在奥达希尔下开始接受训练的年轻kaldorei，你装满这只水晶瓶，思索海加尔山的牺牲，以及自己保护自然的神圣职责。"},sec={{t="月亮井之水",b="特纳隆·雷拳让年轻的暗夜精灵在踏入更广阔的世界之前，先去采集月亮井水。月亮井位于幽影谷，井中并非只有泉水：其中还蕴含着可追溯至古老的永恒之井的能量。哨兵将月亮井尊为艾露恩的圣所，而德鲁伊则用井水的恢复之力照料自然。古老的奥术魔法依然遭到禁止。采集井水，是了解海加尔山的牺牲，以及滋养泰达希尔所需悉心照料的第一课。"}},faq={{q="装满水的水晶瓶里有什么？",a="瓶中盛着从幽影谷奥达希尔北面的月亮井中取来的水。井水蕴含着古老的永恒之井残留的力量，受到艾露恩之光的祝福，也得到德鲁伊的悉心滋养。",al={"瓶里是什么水","瓶中之物","水晶瓶里有什么"}},{q="谁让你装满水晶瓶？",a="驻守在奥达希尔枝头的特纳隆·雷拳让初出茅庐的冒险者前去取水，既作为一场成年仪式，也作为一堂历史课。",al={"谁需要水晶瓶","谁给予水晶瓶任务","特纳隆·雷拳任务"}},{q="特纳隆·雷拳为什么需要这些水？",a="特纳隆以采集井水作为开端，向年轻的冒险者讲述第三次大战之后暗夜精灵的历史。他们将了解诺达希尔的牺牲、月亮井的力量，以及对泰达希尔持续不断的照料。",al={"为什么装满水晶瓶","大地之冠的目的"}},{q="这些井水危险吗？",a="井水蕴含着强大的魔力，其根源可以追溯至古老的永恒之井。德鲁伊和女祭司能够安全地用井水施予祝福和治疗，但肆意操纵奥术曾在远古引发浩劫，至今仍遭到禁止。",al={"月亮井水危险吗","井水有魔力吗"}}},fp="20,161,22.471.0,40.210.0,31.149.0,43.202.0,25.228.0"}
P.entries["item:filled-cursed-ooze-jar"] = {n="被诅咒的软泥怪样本",s="在费伍德森林，被诅咒的软泥怪样本承载着一份要交给铁炉堡的拉里斯·空轮的样本。这位侏儒学者正在探寻遍布艾泽拉斯的软泥怪的远古起源。",h="在费伍德森林，被诅咒的软泥怪样本承载着一份要交给铁炉堡的拉里斯·空轮的样本。这位侏儒学者正在探寻遍布艾泽拉斯的软泥怪的远古起源。",kw={"被诅咒的软泥怪","探险者协会","费伍德森林","被诅咒的软泥怪样本","铁炉堡","拉里斯·空轮","软泥怪"},ang={["faction:Alliance"]="身为联盟的一员，你能看到铁炉堡的自然哲学家正在关注被遗忘者的动向。皇家药剂师学会也对在艾泽拉斯各地采集软泥怪样本表现出了阴暗的兴趣。",["race:Gnome"]="身为侏儒，你能理解拉里斯·空轮为何如此重视软泥怪研究。他希望为流离失所的侏儒赢得荣誉，并向铁炉堡收留他们的矮人证明侏儒的才智与价值。"},sec={{t="奇异的样本",b="侏儒研究员拉里斯·空轮在旁人视而不见的污秽泥潭和腐蚀性软泥怪中看到了谜团。软泥怪在艾泽拉斯各地繁衍，被遗忘者的药剂师则小心地采集它们。这些景象让空轮提出了一个大胆的理论：软泥怪或许是与艾泽拉斯的诞生有关的原始分泌物。要采集样本，就得勇闯费伍德森林枯败的林地，击败一只被诅咒的软泥怪。在它的酸性残骸溶解之前，将其舀入空瓶。"},{t="学术抱负",b="拉里斯·空轮希望这些软泥怪样本能带来知识，也让自己名留后世。一项重大发现或许能让他在矮人领导的探险者协会中确立声望。自诺莫瑞根沦陷以来，铁炉堡的许多侏儒难民都觉得，自己必须向收留他们的矮人证明自身的价值。空轮相信，揭开软泥怪的远古秘密，就能向矮人表明，接纳侏儒并没有错。"}},faq={{q="这个样本瓶从何而来？",a="在费伍德森林遭到腐化的土地上，对被击败的被诅咒的软泥怪的残骸使用被诅咒的软泥怪采样瓶，即可将其装满。",al={"被诅咒的软泥怪采样瓶哪里获取","被诅咒的软泥怪样本如何获取","软泥怪样本瓶位置"}},{q="谁需要这些软泥怪样本？",a="拉里斯·空轮是铁炉堡探险者大厅的一位侏儒研究员，他需要这些样本来研究自然史。",al={"谁需要软泥怪样本瓶","拉里斯·空轮任务","软泥怪样本瓶交给谁"}},{q="拉里斯·空轮为什么研究软泥怪？",a="拉里斯·空轮研究软泥怪，是因为他看到自然界和皇家药剂师学会都对它们表现出了兴趣。他怀疑，软泥怪可能是与艾泽拉斯上生命的诞生和发展有关的古老分泌物，因此需要样本来检验自己的理论。",al={"为什么研究软泥怪","空轮的软泥怪理论","为什么是软泥怪"}},{q="一个侏儒为什么在意探险者协会？",a="诺莫瑞根沦陷后，侏儒难民在铁炉堡的矮人中找到了庇护。拉里斯·空轮希望通过探险者协会取得一项重大发现，证明收留他们是正确的选择。",al={"为什么是探险者协会","铁炉堡的侏儒"}}},fx={b5982a20={q="被诅咒的软泥怪样本是什么？",a="这是一个特别准备的标本容器，里面装着从费伍德森林一只被杀死的受诅咒软泥怪身上取得的新鲜样本。这些污秽、腐化的软泥怪在受污染森林中恶魔造成的腐败环境里滋生，即使少量残留物也极不稳定，没有合适的玻璃器皿，处理起来十分危险。",al={"被诅咒的软泥怪样本是什么","被诅咒的软泥怪样本用途","被诅咒的软泥怪样本罐"}}},fp="22,158,18.436.0,17.395.0,30.110.0,29.122.0,39.249.0,50.203.0"}
P.entries["item:filled-dreadmist-peak-sampler"] = {n="盛满的鬼雾峰取样器",s="在鬼雾峰，一只装满的采样器盛着部落德鲁伊从峰顶水池采集的水。塞纳里奥议会正在研究这份样本，查明是什么毒害了贫瘠之地北部的野生动物。",h="在鬼雾峰，一只装满的采样器盛着部落德鲁伊从峰顶水池采集的水。塞纳里奥议会正在研究这份样本，查明是什么毒害了贫瘠之地北部的野生动物。",kw={"火刃氏族","塞纳里奥议会","鬼雾峰","德鲁伊","盛满的鬼雾峰取样器","贫瘠之地","主要源头","图加·符文图腾"},ang={["class:Druid"]="作为部落德鲁伊，你要采集这份样本，完成一项成长试炼。这项试炼让你了解腐化如何沿天然水道蔓延，并为掌握治疗魔法做好准备。",["faction:Horde"]="作为部落的一员，你可以看到，火刃氏族邪教徒在贫瘠之地的部落领土内造成的威胁正日益加剧。"},sec={{t="被污染的水源",b="鬼雾峰高处的峭壁间分布着水池，池水蒸腾的雾气影响着贫瘠之地北部的天气与降雨。崇拜恶魔的火刃氏族在峰顶设立了集会场所，水质很快便恶化了。塞纳里奥议会的德鲁伊怀疑，恶魔仪式污染了滋养周围草原的水汽。他们派遣初学者，用特制的采样器采集水样。这污浊的液体证实了他们的担忧：其中的腐化力量足以让山下的兽群染病。"},{t="救治草原生灵",b="在十字路口，图加·符文图腾利用这份样本寻找解毒的方法。火刃氏族被怀疑污染了水源，而水样的特性有助于塞纳里奥议会了解这种毒素。德鲁伊通过研究瓶中的污染物，为濒死的瞪羚配制草药，并学会运用自身的自然之力对抗毒素。"}},faq={{q="这份水样是从哪里采集的？",a="水样取自鬼雾峰峰顶的一处水池，位于贫瘠之地十字路口的西北方。",al={"哪里获取水样","鬼雾峰采样器位置","哪里装满采样器"}},{q="鬼雾峰的水为什么受到了污染？",a="火刃氏族的邪教徒占据了鬼雾峰的高处，在那里崇拜恶魔。德迪利特·星焰怀疑，这些邪教徒污染了峰顶的天然水源。",al={"鬼雾峰的水为何有毒","谁污染了鬼雾峰","火刃氏族的水"}},{q="谁需要装满的采样器？",a="图加·符文图腾需要装满的采样器。他是驻守十字路口的塞纳里奥议会德鲁伊，正在调查贫瘠之地野生动物突然染病的原因。",al={"采样器交给谁","图加·符文图腾采样器","交付鬼雾峰水样"}},{q="这些有毒的水对贫瘠之地有什么影响？",a="鬼雾峰高处的气流和水池影响着当地的天气与雾气。水汽一旦染毒，就会笼罩主干道以北的草原，使当地的瞪羚染病。",al={"水有什么作用","贫瘠之地染病的瞪羚","鬼雾峰雾气的影响"}},{q="采集完成后，采样器有什么用途？",a="图加·符文图腾研究这污浊的液体，了解其中恶魔污染的性质，再利用这些知识配制药膏，供德鲁伊治疗染病的瞪羚。",al={"图加如何使用水样","解毒方法","对抗毒素的力量研究"}}},fp="29,164,16.439.0,18.347.1,36.102.0,43.159.0,29.148.0,48.183.0,51.174.0"}
P.entries["item:filled-etched-phial"] = {n="装满水的蚀刻瓶",s="在雷霆崖，牛头人正在寻找装满月亮井水的树妖之瓶。井水蕴含罕见的灵性力量，能够熄灭守护半人马神圣遗物的永恒火焰。",h="在雷霆崖，牛头人正在寻找装满月亮井水的树妖之瓶。井水蕴含罕见的灵性力量，能够熄灭守护半人马神圣遗物的永恒火焰。",kw={"灰谷","树妖","蚀刻瓶","装满水的蚀刻瓶","加拉克","月亮井","劳恩·峭壁行者","千针石林","赞金·石蹄"},ang={["race:NightElf"]="身为暗夜精灵，你知道部落人员盗取树妖之瓶、舀取月亮井水的行为，亵渎了灰谷最神圣的圣地。",["race:Tauren"]="对牛头人而言，取得这些井水便能打击加拉克半人马，将源自塞纳留斯的共同自然魔法转而用于对付部族长久以来的宿敌。"},sec={{t="月亮井水与树妖工艺",b="要装满瓶子，你必须进入灰谷深处的暗夜精灵领地。林中树居周围的树妖携带着空瓶，这些容器专为盛放纯净的恢复药剂而制。弗伦河西岸附近有一口神圣的月亮井，可以用其中蕴含星辰与自然之力的井水装满瓶子。暗夜精灵视擅取井水为亵渎之举。牛头人则认为，这些井水是应对更南方威胁的关键。"},{t="破解半人马巫术",b="赞金·石蹄和劳恩·峭壁行者寻求这种井水，是因为树妖与半人马之间有着深厚的联系。两者的血脉都可追溯至塞纳留斯，魔法也有着原始的共鸣。在千针石林，加拉克氏族用无法攻破的防护火焰守护着一件古老遗物，据说这火焰自半人马一族诞生时便已存在。树妖之瓶中的月亮井水能够穿透并熄灭这道屏障。"}},faq={{q="装满水的蚀刻瓶里装着什么？",a="装满水的蚀刻瓶中盛着神圣的井水，取自灰谷弗伦河附近的一口暗夜精灵月亮井。这个华美的玻璃容器来自林中树居附近的树妖。",al={"瓶里是什么水","蚀刻瓶里装的是什么"}},{q="牛头人为什么需要月亮井水？",a="劳恩·峭壁行者需要用这神圣的井水，穿透并熄灭千针石林中守护加拉克半人马遗物的防护火焰。树妖与半人马同为塞纳留斯的后裔，因此月亮井水拥有对抗这道古老屏障的力量。",al={"为什么用月亮井水","劳恩为什么需要月亮井水"}},{q="空瓶从哪里来？",a="欢笑姐妹是在灰谷中部林中树居周围林地游荡的树妖，她们随身携带着空瓶。",al={"哪里能找到蚀刻瓶","如何获得空瓶"}},{q="装满水的蚀刻瓶要交给谁？",a="收集井水后，先将它带给雷霆崖高地上的赞金·石蹄。他会指引你将它送到千针石林乱风岗的劳恩·峭壁行者手中。",al={"瓶子交给谁","交付瓶子"}}},fp="19,147,31.401.0,24.415.1,39.168.0,38.241.1,37.116.0,46.180.0"}
P.entries["item:filled-jade-phial"] = {n="装满水的翡翠瓶",s="装满水的翡翠瓶盛着星风村的圣水，被带回多兰纳尔。这些水用来补充中央水井，年轻的暗夜精灵也在这一过程中学习族人的历史。",h="装满水的翡翠瓶盛着星风村的圣水，被带回多兰纳尔。这些水用来补充中央水井，年轻的暗夜精灵也在这一过程中学习族人的历史。",kw={"科瑞萨斯·月怒","大地之冠","多兰纳尔","装满水的翡翠瓶","翡翠瓶","月亮井","星风村","泰达希尔"},ang={["class:Druid"]="身为德鲁伊，照料月亮井让你与维系达纳苏斯的恢复魔法相连，也让你参与塞纳里奥议会培育年轻世界之树的工作。",["race:NightElf"]="身为年轻的kaldorei，取水是在履行你对泰达希尔的神圣职责。科瑞萨斯还会教导你，讲述暗夜精灵在海加尔山之战后失去永生的往事。"},sec={{t="星风之水",b="达纳苏斯的德鲁伊从泰达希尔各处汲取月亮井的圣水，补充中央水井。科瑞萨斯·月怒将翡翠瓶交给多兰纳尔的年轻旅者，这种瓶子能够安全地盛放纯净的井水。星风村外的月亮井位于多兰纳尔以东。新学徒在照料世界之树的同时，也会采集井水。"},{t="一堂历史课",b="当你将装满水的翡翠瓶带回多兰纳尔时，科瑞萨斯·月怒会讲述卡多雷历史的又一个篇章。他讲起第三次大战之后的岁月，那时诺达希尔被焚毁，暗夜精灵失去了永生，背叛者重获自由，而尊师玛法里奥·怒风则失踪了。"}},faq={{q="在哪里装满翡翠瓶？",a="在泰达希尔多兰纳尔以东、星风村外的神圣月亮井中装满翡翠瓶。",al={"翡翠瓶在哪里装满","如何获得装满水的翡翠瓶","星风月亮井位置"}},{q="谁需要装满水的翡翠瓶？",a="多兰纳尔的暗夜精灵长者科瑞萨斯·月怒请旅者取回井水，用于大地之冠仪式。",al={"谁需要装满水的翡翠瓶","科瑞萨斯·月怒任务物品"}},{q="为什么要用这样的瓶子采集月亮井水？",a="达纳苏斯的德鲁伊使用翡翠瓶这类特制容器，从泰达希尔偏远的水井运来纯净的井水，补充主要的月亮井。",al={"为什么采集月亮井水","翡翠瓶的用途"}},{q="交还瓶子时，科瑞萨斯会讲述什么历史？",a="科瑞萨斯·月怒收到装满水的瓶子后，会讲述海加尔山之战后的往事：暗夜精灵失去了永生，伊利丹怒风重获自由，而杉多玛法里奥·怒风则不知所踪。",al={"科瑞萨斯讲述什么","大地之冠背景故事"}}},fp="17,170,20.330.0,19.278.0,31.102.0,35.120.0,54.161.0,55.239.0"}
P.entries["item:filled-pure-sample-jar"] = {n="纯净的样本",s="在铁炉堡，拉里斯·空轮研究腐化如何改变生命物质。纯净的样本中盛有来自偏远荒野的原始软泥，为他提供了可供对比的纯净标本。",h="在铁炉堡，拉里斯·空轮研究腐化如何改变生命物质。纯净的样本中盛有来自偏远荒野的原始软泥，为他提供了可供对比的纯净标本。",kw={"纯净的样本","黏稠的软泥怪","铁炉堡","拉里斯·空轮","软泥怪","软泥","安戈洛环形山"},ang={["faction:Alliance"]="身为联盟探险者，你可以将安戈洛环形山等偏远地区的知识带给铁炉堡的学者。",["race:Gnome"]="身为侏儒，你可以帮助学者对比费伍德森林受污染的软泥与纯净的安戈洛标本，研究生命物质。"},sec={{t="寻找未受腐化的软泥",b="拉里斯·空轮研究艾泽拉斯各地的软泥怪，以及腐化如何改变生命物质。他发现，这些没有固定形体的生物会吸收栖息地的魔法与环境特性，并将其体现出来。在将费伍德森林受污染的软泥怪分类记录后，他开始寻找纯净的样本来进行对比。纯净的样本中盛有从安戈洛环形山荒野采集的原始软泥，采集地远离那些受腐化的种群。"},{t="原始生态",b="软泥怪很容易发生变化，因此拉里斯无法在文明聚居地、恶魔污染之地或死灵魔法残留之地附近找到纯净的样本。安戈洛环形山未经开拓的盆地中，黏稠的软泥怪仍然较少受到外界腐化的影响。这使它们成为铁炉堡学者们实用的对照标本。"}},faq={{q="谁需要这些纯净的样本？",a="铁炉堡的侏儒研究员拉里斯·空轮正在寻找纯净的样本，以研究艾泽拉斯的软泥怪种群。",al={"拉里斯·空轮任务","谁需要纯净的样本","谁需要这些罐子"}},{q="拉里斯为什么需要纯净的软泥，而不是受污染的软泥？",a="拉里斯发现，软泥怪会迅速吸收周围环境的特性，包括费伍德森林的恶魔腐化。他需要未受腐化的样本，与受污染的软泥进行对比，了解腐化波及的范围及其作用方式。",al={"为什么需要纯净的软泥","为什么需要纯净的样本","软泥研究目的"}},{q="哪里可以采集到纯净的软泥样本？",a="纯净的样本来自安戈洛环形山原始荒野中的黏稠软泥怪，它们在那里远离外界的污染。",al={"哪里有纯净的软泥","纯净样本罐位置","哪里能装满纯净样本罐"}},{q="样本送到铁炉堡后会怎样？",a="拉里斯用这些样本检验软泥怪如何适应环境并抵御环境的影响。他会奖励那些冒险深入危险荒野、将样本带到铁炉堡的冒险者。",al={"拉里斯任务奖励","拉里斯拿样本做什么"}}},fx={["630b5cc1"]={q="纯净的样本是什么？",a="这是一只密封的玻璃容器，里面装着未受污染的软泥怪样本。与受到恶魔能量或疫病腐化的软泥怪不同，其中的物质代表着软泥怪生命未经污染的原貌，被小心保存下来供学术研究之用。",al={"纯净的样本是什么","纯净样本罐含义","纯净的样本"}},e9b3a5fa={q="纯净的样本来自哪里？",a="空容器由铁炉堡的拉里斯·空轮制作并提供。你要亲自在野外收集未受腐化的野生软泥怪留下的黏稠残骸，将其装满，这些软泥怪繁衍于安戈洛环形山等原始而纯净的自然环境中。",al={"纯净的样本来源","纯净样本来自哪里","纯净样本罐是谁制作的"}}},fp="22,190,30.398.0,18.282.0,29.108.0,54.223.0,41.134.0,57.159.0"}
P.entries["item:filled-red-waterskin"] = {n="装满水的红色水囊",s="塔伦米尔的一口井为萨满祭司的试炼提供清澈的泉水。装满水的红色水囊盛着从村中水井汲取的水，那里是一片由被遗忘者占据的废墟。",h="塔伦米尔的一口井为萨满祭司的试炼提供清澈的泉水。装满水的红色水囊盛着从村中水井汲取的水，那里是一片由被遗忘者占据的废墟。",kw={"布瑞恩","水之召唤","空的红色水囊","装满水的红色水囊","灵契","萨满祭司","塔伦米尔"},ang={["class:Shaman"]="身为萨满祭司，携带这份泉水，考验着你能否在世间最腐朽、最悲苦的角落，寻得并敬重滋养生命的平衡。",["faction:Horde"]="作为来自卡利姆多的部落勇士，你前往塔伦米尔，那里的被遗忘者正与遍布东部王国的联盟军队抗争。"},sec={{t="荒芜之地的明灯",b="布瑞恩是贫瘠之地的一位隐士，她派萨满祭司学徒前往塔伦米尔，接受水之训练。这段旅程通往希尔斯布莱德丘陵，腐朽与亡者环绕着那座城镇。然而，镇中央的水井仍能汲出清澈的泉水。布瑞恩认为，这纯净的泉水象征着污秽之地中不屈的生命力。她将未受污染的泉水比作大酋长萨尔历经磨难却始终不渝的意志。采集泉水考验着学徒能否在充满敌意的环境中，依然敬重水的纯净。"}},faq={{q="装满水的红色水囊里装着什么？",a="装满水的红色水囊里盛着纯净的泉水，取自塔伦米尔中央的公共水井。",al={"里面装的是什么水","塔伦米尔的水","红色水囊里的东西"}},{q="布瑞恩为什么想要塔伦米尔的水？",a="布瑞恩认为，塔伦米尔清新的泉水是被遗忘者的腐朽之中罕见的纯净象征。她需要用这水酿制灵契，供萨满祭司的水之试炼使用。",al={"为什么是塔伦米尔","布瑞恩为什么需要这个","红色水囊的用途"}},{q="亡灵城镇中的水井为何仍能保持洁净？",a="没有人知道，这眼泉水为何始终未受周围瘟疫的侵染。布瑞恩说，塔伦米尔的被遗忘者或许既不了解，也不珍视身边这眼圣泉的纯净。",al={"水井为何未受污染","塔伦米尔的水井有毒吗","塔伦米尔圣井"}},{q="萨尔与这个任务有什么关系？",a="布瑞恩将废墟城镇中的洁净水井比作萨尔。他历经苦难与囚禁，最终仍坚强而纯粹，带领兽人度过黑暗的岁月。",al={"与萨尔的比较","为什么提到萨尔"}}},fp="20,170,26.516.0,40.105.0,43.150.0,47.181.0,37.180.0"}
P.entries["item:filled-tainted-ooze-jar"] = {n="被污染的软泥怪样本",s="在费伍德森林，被污染的软泥怪样本承载着要送往铁炉堡的腐化样本。这些样本或许能帮助解释艾泽拉斯上的生命如何起源。",h="在费伍德森林，被污染的软泥怪样本承载着要送往铁炉堡的腐化样本。这些样本或许能帮助解释艾泽拉斯上的生命如何起源。",kw={"探险者协会","费伍德森林","铁炉堡","拉里斯·空轮","皇家药剂师学会","软泥怪","被污染的软泥怪"},ang={["faction:Alliance"]="身为联盟斥候，你密切监视着被遗忘者的皇家药剂师学会。查明幽暗城为何在各大陆收集软泥怪，是情报工作的重中之重。",["race:Gnome"]="身为流亡铁炉堡的侏儒，你为探险者协会开展的科学研究能够证明你的价值，也能回报矮人在诺莫瑞根惨剧后给予的盛情款待。"},sec={{t="腐化林地的软泥",b="在卡利姆多北部各地，受污染的软泥怪带着费伍德森林挥之不去的腐化。侏儒研究员提供罐子，用来安全地收存它们。大多数旅人都避开这些有毒的生物，但它们的残骸能提供样本，供远离这片枯败林地的学者研究自然哲学和生物学。"},{t="空轮的宏大理论",b="拉里斯·空轮是铁炉堡探险者协会的一名侏儒学者，负责收集这些样本。软泥怪如此常见，令他十分着迷，他还发现被遗忘者的皇家药剂师学会也对它们产生了兴趣。\n\n许多学者对空轮的理论不屑一顾。他认为，软泥怪和淤泥怪可能是与艾泽拉斯的创生有关的原始分泌物。他寻求证据，也希望在诺莫瑞根悲惨陷落后，在矮人学者之中争得一席之地。"}},faq={{q="被污染的软泥怪样本里装着什么？",a="被污染的软泥怪样本中装着从费伍德森林原生的被污染的软泥怪残骸上取得的新鲜样本，密封在侏儒采集罐中。",al={"罐子里有什么","被污染的软泥怪罐内容物","什么是被污染的软泥怪"}},{q="谁需要这些软泥怪样本？",a="拉里斯·空轮是铁炉堡探险者大厅内探险者协会的一名侏儒研究员，他需要这些样本来研究博物学。",al={"谁收软泥怪","拉里斯·空轮任务","谁需要被污染的软泥怪"}},{q="拉里斯·空轮为什么研究软泥怪？",a="空轮看到皇家药剂师学会收集软泥怪样本，便着手探究它们的本质。他认为，软泥怪是与艾泽拉斯的创生有关的原始分泌物，并希望以科学家的身份在铁炉堡扬名。",al={"为什么研究软泥怪","空轮软泥怪理论","侏儒为什么需要软泥怪"}},{q="这些样本在哪里采集？",a="你在费伍德森林击败被污染的软泥怪，再对它们的残骸使用空的容器罐，就能采集样本。",al={"哪里能找到被污染的软泥怪","被污染的软泥怪罐位置","在哪里装满罐子"}}},fx={["297c9c04"]={q="被污染的软泥怪样本来自哪里，又是谁制作的？",a="罐子本身由铁炉堡的侏儒研究员拉里斯·空轮提供，他制作这些特制的空玻璃容器，以便安全收集性质不稳定的样本。只有冒险者在费伍德森林遭到腐化的林地中杀死一只受污染的软泥怪，再用罐子刮取它胶状的残骸，才能将其装满。",al={"被污染的软泥怪样本来源","被污染的软泥怪样本罐是谁制作的","被污染的软泥怪样本罐来自哪里"}}},fp="23,137,27.291.0,25.431.0,41.136.0,29.148.0,39.233.0,34.115.0"}
P.entries["item:filled-tourmaline-phial"] = {n="装满水的红玉瓶",s="在阿里斯瑞恩之池，装满水的红玉瓶盛着为科瑞萨斯·月怒采集的月井水。这些井水帮助他观察日渐成长的世界之树的健康与平衡。",h="在阿里斯瑞恩之池，装满水的红玉瓶盛着为科瑞萨斯·月怒采集的月井水。这些井水帮助他观察日渐成长的世界之树的健康与平衡。",kw={"科瑞萨斯·月怒","大地之冠","装满水的红玉瓶","瘤背","月井","阿里斯瑞恩之池","泰达希尔","红玉瓶"},ang={["class:Druid"]="身为德鲁伊，你携带的这只瓶子与大德鲁伊范达尔·鹿盔留下的争议息息相关。在怒风无故失踪期间，他力主种下泰达希尔。",["race:NightElf"]="身为暗夜精灵，你深知月井水是维系kaldorei精神的命脉。这口月井周围的瘤背林地遭到腐化，对你的新家园而言，这是一个令人不安的预兆。"},sec={{t="阿里斯瑞恩之水",b="装满水的红玉瓶中的水取自通往达纳苏斯的道路东南方、阿里斯瑞恩之池岸边的一口月井。曾经友善的邻居瘤背熊怪变得狂暴而疯狂，前往这处圣地也愈发危险。科瑞萨斯·月怒请旅行者冒险穿过危机四伏的林地，将井水带回来。他希望借此找出那股日益加深、令大地动荡不安的腐化力量。"},{t="泰达希尔之根",b="回到多兰纳尔，科瑞萨斯·月怒讲述了泰达希尔的由来。尊师玛法里奥·怒风失踪后，大德鲁伊范达尔·鹿盔在海对面的黑海岸召集了古树议会，种下这棵树，试图找回他们失去的永生。瓶中的水映照着这项神圣事业的状况。如今，一种原因不明的疾病正在野兽和熊怪之间蔓延。"}},faq={{q="装满水的红玉瓶有什么用途？",a="多兰纳尔的科瑞萨斯·月怒需要装满水的红玉瓶，瓶中盛着蕴含魔力的月井水。他从泰达希尔各处的月井采集井水，研究腐化的蔓延，并向初来乍到的守卫者讲述世界之树的历史。",al={"装满水的红玉瓶用途","红玉瓶用途","为什么要装满瓶子"}},{q="为红玉瓶取水的月井在哪里？",a="这口月井位于达纳苏斯正门的东南方，在泰达希尔西南部的阿里斯瑞恩之池岸边。狂暴的瘤背熊怪在这一带肆虐。",al={"红玉瓶在哪里装水","阿里斯瑞恩之池月井","阿里斯瑞恩月井位置"}},{q="月井附近的熊怪为什么会发起攻击？",a="瘤背熊怪曾与暗夜精灵和平共处，但如今正遭受一股逐渐蔓延的腐化力量侵扰。它们突然变得凶暴，是这棵年轻的世界之树患病的诸多迹象之一。",al={"瘤背为什么发疯","阿里斯瑞恩熊怪敌意","疯狂的瘤背"}},{q="科瑞萨斯·月怒是谁？",a="科瑞萨斯·月怒是多兰纳尔的一位暗夜精灵学者与看护者。他引导年轻的冒险者完成名为大地之冠的仪式，向他们讲述暗夜精灵的历史、泰达希尔的种植经过，以及玛法里奥·怒风的失踪。",al={"科瑞萨斯职责","科瑞萨斯多兰纳尔"}}},fp="23,170,20.383.0,23.411.1,45.258.0,55.170.0,49.195.0,26.256.0"}
P.entries["item:filled-vessel"] = {n="装满月亮井水的瓶子",s="在多兰纳尔，科瑞萨斯·月怒为身在达纳苏斯的范达尔·鹿盔收集圣水。装满月亮井水的瓶子盛着来自泰达希尔各处月亮井的水样，供他研究世界之树的病症。",h="在多兰纳尔，科瑞萨斯·月怒为身在达纳苏斯的范达尔·鹿盔收集圣水。装满月亮井水的瓶子盛着来自泰达希尔各处月亮井的水样，供他研究世界之树的病症。",kw={"塞纳里奥区","科瑞萨斯·月怒","大地之冠","达纳苏斯","范达尔·鹿盔","装满月亮井水的瓶子","月亮井水","泰达希尔"},ang={["class:Druid"]="身为效力于塞纳里奥事业的德鲁伊，递送这个瓶子是你第一次正式为大德鲁伊范达尔·鹿盔办事。这让你明白，泰达希尔的生灵依然如此脆弱。",["race:NightElf"]="身为暗夜精灵，你深知月亮井水是族人新家园的神圣命脉。井水将Elune的魔法与未获祝福的世界之树尚不稳定的生长融为一体。"},sec={{t="圣水汇流",b="暗夜精灵侍僧从泰达希尔各处的月亮井中取水。这棵树种下时未获守护巨龙中的阿莱克丝塔萨和诺兹多姆祝福，因此腐化、怪异的野兽和疯狂的熊怪部族得以侵扰它的枝干。科瑞萨斯·月怒在多兰纳尔收齐这些小瓶，将井水倒入装满月亮井水的瓶子，准备送往首都。这些汇集的井水是反映泰达希尔生命力的重要样本。大德鲁伊范达尔·鹿盔在塞纳里奥区研究这些井水，寻找弥补巨树缺陷的办法。"}},faq={{q="装满月亮井水的瓶子里装着什么？",a="装满月亮井水的瓶子里盛着从泰达希尔多处月亮井采集的井水。科瑞萨斯·月怒在多兰纳尔将这些小瓶里的井水汇在一起。",al={"瓶中之物","这是什么水","瓶子里有什么"}},{q="谁需要装满月亮井水的瓶子？",a="大德鲁伊范达尔·鹿盔需要装满月亮井水的瓶子。他住在达纳苏斯的塞纳里奥区顶端。",al={"装满月亮井水的瓶子交给谁","瓶子送往何处","交付装满月亮井水的瓶子"}},{q="范达尔·鹿盔为什么需要这些水样？",a="泰达希尔的病症源于它未获守护巨龙的祝福。诡异的腐化、凶猛的野生动物和疯狂的熊怪侵扰着它的枝干，鹿盔研究这些混合的井水，以了解这棵树的缺陷并寻找补救之法。",al={"鹿盔为何需要井水","鹿盔要月亮井水的用途","为何收集月亮井水"}},{q="是谁备好了这个瓶子？",a="科瑞萨斯·月怒在多兰纳尔备好这个瓶子，将年轻冒险者收集的小瓶井水倒入其中，然后送往达纳苏斯。",al={"谁制作了装满月亮井水的瓶子","谁给予装满月亮井水的瓶子","科瑞萨斯装满月亮井水的瓶子"}}},fp="13,194,29.537.0,33.132.0,28.103.0,51.239.0,24.136.0"}
P.entries["item:final-clue-to-sanders-treasure"] = {n="Final Clue to Sanders' Treasure",s="在西部荒野沿岸，杉德尔船长留下的最后指引将寻宝者引向大海。一个旧酒壶中的字条指向西方，那里埋藏着他的宝藏。",h="在西部荒野沿岸，杉德尔船长留下的最后指引将寻宝者引向大海。一个旧酒壶中的字条指向西方，那里埋藏着他的宝藏。",kw={"杉德尔船长","宝箱","线索","海盗","宝藏","西部荒野","威士忌酒壶"},ang={["class:Rogue"]="身为潜行者，你可以循着杉德尔船长的指引出海，在西部荒野沿岸寻找迪菲亚口袋之外的宝藏。"},sec={{t="水手的临别之言",b="杉德尔船长将最后的指引留在了西部荒野海岸的一个旧威士忌酒壶中。这个海盗沿着海岸留下了多张隐晦的字条，而这一张补全了整条线索。从酒壶所在的位置出发，指引指向正西方的大海。循着指引穿过海浪，就能抵达近海的一块孤岩，他那包着铁箍的航海箱就在那里。"}},faq={{q="最后的线索说了什么？",a="字条指示从威士忌酒壶所在的位置向西，前往海中。宝箱就在近海的一座小岛上。",al={"线索内容","线索上写了什么","杉德尔的指引"}},{q="这条线索是在哪里发现的？",a="线索藏在西部荒野海岸的一个旧威士忌酒壶里。这是杉德尔船长留下的一连串线索中的第三步。",al={"最后的线索在哪里","旧酒壶位置","线索位置"}},{q="杉德尔船长是谁？",a="杉德尔船长是一名海盗，他的物品和藏宝图被海水冲上了西部荒野的海岸。他生前在乡野各处留下了隐藏的字条和标记，指引人们找到他的宝藏。",al={"杉德尔船长是谁","海盗杉德尔的故事","谁藏了宝藏"}},{q="这条线索最终通向哪里？",a="字条指引人们从西部荒野海岸向西，前往一座孤岛。杉德尔船长的航海箱就在那里。",al={"宝箱在哪里","杉德尔的小岛","小岛位置"}}},fx={ed69490f={q="杉德尔宝藏的最终线索是什么？",a="这是一张饱经风霜的纸条，从西部荒野海岸边杉德尔船长的旧威士忌酒罐中取出。纸条带着淡淡的酒气，墨迹因受潮而晕开，标志着这位已故海盗船长布下的寻宝之旅即将结束，提供了找到他埋藏财宝所需的最后指引。",al={"杉德尔宝藏的最终线索是什么","最后的线索是什么","这条线索是什么"}},["0f7c35ef"]={q="杉德尔宝藏的最终线索来自哪里，又是谁制作的？",a="这条线索由杉德尔船长亲笔写下，密封在西部荒野海边峭壁上一座孤零零的风车旁的旧酒罐里。这位海盗船长沿海岸精心布下了一连串线索，并将它藏在最后一环，确保只有足够坚定、愿意追寻那些散落标记的人，才能找到他隐藏的赃物。",al={"最后的线索是谁制作的","最后的线索来自哪里","最后的线索来源"}},["9095866c"]={q="为什么有人想要杉德尔宝藏的最终线索？",a="追寻杉德尔船长踪迹的人，都在寻找他失落已久的海盗赃物。先前的提示让寻宝者沿着海岸地标辗转前行，而这张最后的纸条明确指引发现者离开西部荒野的海滩，驶向外海，直奔那座孤岛，船长的宝箱就在那里等待着。",al={"为什么需要最后的线索","为什么寻找最后的线索","最后的线索用途"}}},fp="31,150,24.332.0,29.113.0,26.121.0,24.197.0,37.107.0"}
P.entries["item:fine-crab-chunks"] = {n="优质蟹肉",s="优质蟹肉产自黑海岸沿岸的暗礁蟹和硬壳潮行蟹。古博·布拉普正在收集这些蟹肉，用于烹饪。",h="优质蟹肉产自黑海岸沿岸的暗礁蟹和硬壳潮行蟹。古博·布拉普正在收集这些蟹肉，用于烹饪。",kw={"奥伯丁","螃蟹","黑海岸","硬壳潮行蟹","优质蟹肉","海中的水果","古博·布拉普","暗礁蟹"},ang={["faction:Alliance"]="为奥伯丁码头边的居民供应物资，有助于维持这座联盟在黑海岸的前哨站。",["profession:Cooking"]="古博·布拉普知道许多烹制螃蟹的方法，从汤和沙拉，到胡椒擦料和铁炉堡surprise crab。"},sec={{t="海洋的果实",b="暗礁蟹和硬壳潮行蟹在黑海岸的岸边游荡。旅人可能将它们视为水边的害兽或威胁，厨师却十分看重它们的肉。这些蟹肉可以水煮、炙烤、油炸，也可以加入炖菜。"}},faq={{q="哪些生物出产优质蟹肉？",a="黑海岸岩石海滩和潮汐浅滩上的暗礁蟹和硬壳潮行蟹出产优质蟹肉。",al={"优质蟹肉掉落地点","掉落蟹肉的螃蟹","蟹肉来源"}},{q="黑海岸有谁需要优质蟹肉？",a="古博·布拉普是奥伯丁码头上的渔夫，他正在收集优质蟹肉，用来制作蟹肉菜肴。",al={"谁需要优质蟹肉","谁上交蟹肉","古博·布拉普 螃蟹"}},{q="这些蟹肉能做成可食用的菜肴吗？",a="这些生蟹肉是收集来交给古博·布拉普的，并不直接用于某份食谱。蟹肉可以烘烤、烧烤、水煮、炙烤、油炸，也可以拌入沙拉和炖菜。",al={"优质蟹肉能否烹饪","优质蟹肉能做什么","蟹肉食谱"}}},fp="16,131,16.217.0,38.116.0,40.91.0,40.174.0"}
P.entries["item:fine-moonstalker-pelt"] = {n="优质月夜猛虎毛皮",s="在黑海岸南部，成年的月夜猛虎身上有特伦希斯所需的毛皮。它们的优质月夜猛虎毛皮厚实而完好，足以制成附魔披风，帮助搜寻者悄然穿过这一带凶兽出没的区域。",h="在黑海岸南部，成年的月夜猛虎身上有特伦希斯所需的毛皮。它们的优质月夜猛虎毛皮厚实而完好，足以制成附魔披风，帮助搜寻者悄然穿过这一带凶兽出没的区域。",kw={"奥伯丁","黑海岸","优质月夜猛虎毛皮","雌豹","月夜猛虎","雄豹","特伦希斯","沃科尔","急弯河"},ang={["class:Hunter"]="作为猎人，在急弯河附近追踪sires和matriarchs，会让你面对卡利姆多沿海一带最凶猛的掠食者，考验你的本领。",["race:NightElf"]="作为暗夜精灵，你敬重moonstalker神圣的凶猛天性。只有在迫不得已时，才会取用它们的毛皮，帮助像沃科尔这样身陷困境的同胞。"},sec={{t="兽群首领的毛皮",b="月夜雄虎和月夜雌虎的皮毛浓密而完好，能提供优质的毛皮。它们在急弯河沿岸，以及更南边靠近灰谷边界的地带划定领地，耐心地狩猎。普通的月夜猛虎在黑海岸各处的森林中游荡，但它们的毛皮品质不够好。"},{t="幻象披风",b="特伦希斯需要五张完整的毛皮，为寻找失踪暗夜精灵沃科尔的旅人制作一件披风。自然魔法将这些毛皮结合在一起，形成幻象，让黑海岸的野生动物难以察觉穿戴者的存在。只有穿戴者不采取攻击行为，披风才能发挥作用。"}},faq={{q="哪些生物能提供优质月夜猛虎毛皮？",a="月夜雄虎和月夜雌虎能提供优质月夜猛虎毛皮。普通和年幼的月夜猛虎没有品质足够好的毛皮。",al={"什么掉落优质月夜猛虎毛皮","哪里获取月夜猛虎毛皮","哪些猫科野兽有毛皮"}},{q="在哪里能找到成年的月夜猛虎？",a="成年的月夜猛虎生活在黑海岸南部，尤其是急弯河沿岸，以及更南边通往灰谷的地带。",al={"月夜雄虎和月夜雌虎在哪里","月夜雄虎位置","月夜雌虎位置"}},{q="特伦希斯为什么需要这些毛皮？",a="特伦希斯需要五张毛皮，为寻找失踪暗夜精灵沃科尔的旅人制作一件附魔披风。披风的魔法能让救援者避开食肉猛兽的察觉。",al={"毛皮有什么用途","为什么收集月夜猛虎毛皮","特伦希斯毛皮任务"}},{q="制成的披风能让你完全隐形吗？",a="这件披风不能让你完全隐形。它的自然幻象能让野兽避开你，但除了与他人交谈之外的行为都可能破坏附魔，使伪装消散。",al={"披风如何起效","披风幻象的限制","披风潜行失效"}}},fp="21,164,25.300.0,20.277.1,45.128.0,43.119.0,36.164.0,54.174.0"}
P.entries["item:fire-tar"] = {n="火焰焦油",s="在贫瘠之地东部各处，钢鬃施法者都携带着火焰焦油。部落萨满祭司用它调制火焰灵契，借此与火焰之灵沟通。",h="在贫瘠之地东部各处，钢鬃施法者都携带着火焰焦油。部落萨满祭司用它调制火焰灵契，借此与火焰之灵沟通。",kw={"火焰的召唤","火焰灵契","火焰焦油","野猪人","钢鬃","萨满祭司图腾","泰尔夫·祖拉姆","贫瘠之地"},ang={["class:Shaman"]="身为萨满祭司，收集火焰焦油是你成长历程中不可或缺的仪式。你在广阔的世界中寻找元素共鸣，再借此调制火焰灵契，获得自己的火焰图腾。",["faction:Horde"]="身为部落的一员，你从杜隆塔尔渡过怒水河，进入贫瘠之地收集火焰焦油。在那里，你将面对好斗的钢鬃部族。"},sec={{t="钢鬃的调制物",b="钢鬃的地卜师、秘法师和织棘者都携带着火焰焦油。野猪人在凶厉的魔法与仪式中使用这种与火焰共鸣的物质。萨满祭司导师珍视这种尘世试剂，因为它能帮助凡人的感官触及元素原始的狂怒。"},{t="通往火焰图腾之路",b="年轻的兽人和巨魔萨满祭司前往杜隆塔尔峭壁高处，拜访泰尔夫·祖拉姆，制作自己的火焰图腾。泰尔夫要求他们带来从火刃氏族教徒身上取得的试剂袋，以及从钢鬃那里收集的火焰焦油。他将这两种材料调制成火焰灵契。饮下它，萨满祭司便能感知到附近山峰顶端等候着的火焰之灵。"}},faq={{q="火焰焦油有什么用途？",a="萨满祭司将火焰焦油带给杜隆塔尔的泰尔夫·祖拉姆，由他将其与来自火刃氏族的试剂一同调制成火焰灵契。这种药剂能让萨满祭司看见火焰之灵并与之沟通，从而获得火焰图腾。",al={"火焰焦油用途","火焰焦油有什么用","为什么需要火焰焦油"}},{q="谁携带着火焰焦油？",a="贫瘠之地东部会施法的钢鬃野猪人携带着火焰焦油。其中包括钢鬃地卜师、秘法师、织棘者和寻水者。",al={"谁掉落火焰焦油","火焰焦油怪物","哪里获取火焰焦油"}},{q="萨满祭司为什么需要与敌对施法者有关的材料？",a="灵契需要浸透相应元素之力的实体材料。钢鬃施法者和火刃氏族术士引导热力与毁灭性的烈焰，因此他们日常使用的材料蕴含着火焰精华，能唤醒萨满祭司的元素视野。",al={"为什么用野猪人的焦油","为什么是术士和野猪人"}},{q="泰尔夫·祖拉姆在哪里调制火焰灵契？",a="泰尔夫·祖拉姆在一处俯瞰杜隆塔尔群崖的高崖上调制火焰灵契，那里靠近剃刀岭与贫瘠之地之间的道路。他教导初学者平衡火焰的毁灭与创造本性。",al={"泰尔夫·祖拉姆在哪里","交付火焰焦油"}}},fp="8,178,29.274.0,26.361.0,26.196.0,21.147.0,61.243.0,43.215.0"}
P.entries["item:fizzle-s-claw"] = {n="费索的爪子",s="在雷霆山，费索·暗雷的爪子被带往剃刀岭，作为他已死亡的证据。这名地精术士是火刃氏族中一名危险的阴谋策划者。",h="在雷霆山，费索·暗雷的爪子被带往剃刀岭，作为他已死亡的证据。这名地精术士是火刃氏族中一名危险的阴谋策划者。",kw={"火刃氏族","黑暗风暴","杜隆塔尔","费索·暗雷","费索的爪子","奥戈尼尔·魂痕","剃刀岭","雷霆山"},ang={["class:Warlock"]="身为术士，你知道费索·暗雷曾运用邪能法术为火刃氏族效力，用自己的才能对抗部落。",["faction:Horde"]="身为部落的一员，在剃刀岭呈上费索的爪子，有助于清除杜隆塔尔境内威胁这个年轻国度安全的暗影教派。"},sec={{t="阴森的战利品",b="奥戈尼尔·魂痕派出部队，铲除威胁兽人家园的暗影教派。他查明，费索·暗雷是在雷霆山散播腐化的煽动者。这只爪子向部落指挥官证明，那名在火刃氏族旗号下活动的术士已被击杀。"},{t="雷霆山的威胁",b="雷霆山就在剃刀岭的西北方，距离近得足以威胁周边地区。部落斥候将费索的爪子带回剃刀岭，证实他的仪式及建立火刃氏族据点的企图已被阻止。"}},faq={{q="这只爪子属于谁？",a="这只爪子属于费索·暗雷，一名隶属火刃氏族的地精术士。",al={"菲兹尔是谁","费索·暗雷","爪子的主人"}},{q="奥戈尼尔·魂痕为什么想要费索的爪子？",a="奥戈尼尔·魂痕想要菲兹尔已死亡的证据。火刃氏族暗中行事，而这只爪子证实，这个威胁杜隆塔尔的隐患已被清除。",al={"为什么需要爪子","奥戈尼尔·魂痕 爪子","死亡证明"}},{q="这只爪子是在哪里找到的？",a="这只爪子取自费索·暗雷，他的营地位于杜隆塔尔境内、剃刀岭西北方的雷霆山。",al={"菲兹尔的位置","菲兹尔在哪里","雷霆山 爪子"}},{q="火刃氏族在杜隆塔尔做什么？",a="火刃氏族企图通过恶魔腐化、黑暗法术和内部动乱，破坏兽人的新家园。像菲兹尔这样的术士建立隐秘营地，在整个地区散播混乱。",al={"火刃氏族 杜隆塔尔","雷霆山为什么有教徒"}}},fp="13,177,13.277.0,27.251.0,29.90.0,44.151.0,25.101.0,43.199.0"}
P.entries["item:flagongut-s-fossil"] = {n="弗拉冈特的化石",s="在湿地的挖掘场，弗拉冈特正从一块古老的化石中寻求答案。探险者协会保管着这件标本，而弗拉冈特相信雷鲁之石能帮助他解读其中的秘密。",h="在湿地的挖掘场，弗拉冈特正从一块古老的化石中寻求答案。探险者协会保管着这件标本，而弗拉冈特相信雷鲁之石能帮助他解读其中的秘密。",kw={"挖掘","探险者协会","弗拉冈特","化石","雷鲁","雷鲁之石","湿地","维尔加"},ang={["faction:Alliance"]="身为联盟的一员，你可以协助保护维尔加那片已成废墟的挖掘场中的文物，以免它们被野兽毁坏，或被沼泽中的敌对势力搜走。",["race:Dwarf"]="身为矮人，你能将弗拉冈特的化石等化石视为连接远古历史的纽带。探险者协会致力于将它们发掘出土。"},sec={{t="挖掘与研究",b="勘察员维尔加将这块化石保存在湿地南部丘陵的挖掘场中。遍布卡兹莫丹的矮人探险队将它发掘出土，考古学家弗拉冈特相信，这块古老的石头蕴藏着被遗忘的力量。他认为它与大洋彼岸黑海岸出土的文物有着某种联系。"},{t="解开遗物之谜",b="弗拉冈特找到了雷鲁之石，并认定它是解读化石的关键。杂色迅猛龙在路上伏击了他，石头也随之遗失。如今，弗拉冈特需要取得维尔加挖掘场中的化石，并从湿地的野兽身上找回石头，才能解开这件标本的秘密。"}},faq={{q="弗拉冈特的化石是什么？",a="弗拉冈特的化石是一件从湿地出土的古老标本。矮人的探险者协会保管着它，用于研究这个世界的远古历史。",al={"化石是什么","弗拉冈特的化石背景故事"}},{q="化石在哪里？",a="化石位于湿地南部山区的维尔加挖掘场顶端的一处洞穴中。占据挖掘场的杂色迅猛龙守着它。",al={"化石位置","弗拉冈特的化石在哪里","维尔加化石洞穴"}},{q="弗拉冈特为什么需要取回化石？",a="弗拉冈特相信，雷鲁之石能帮助他解读化石中隐藏的魔法奥秘，并将其与卡利姆多的类似发现进行比较。",al={"弗拉冈特为什么想要化石","弗拉冈特会用化石做什么"}},{q="它与黑海岸有什么联系？",a="弗拉冈特认为，湿地的这件标本与勘察员雷姆塔维尔在黑海岸发现的化石有相似之处。他相信，雷鲁之石或许能释放这两件遗物中的力量。",al={"黑海岸联系","雷姆塔维尔化石"}}},fp="18,180,20.293.0,19.257.1,27.144.0,28.155.0,36.158.0,33.180.0"}
P.entries["item:flatland-cougar-femur"] = {n="平原狮的腿骨",s="狮子在莫高雷各处的平原上游荡，茂尔·祈雨需要它们的一根骨头。平原狮的腿骨是他为治疗毒咬伤而寻求的一味药材。",h="狮子在莫高雷各处的平原上游荡，茂尔·祈雨需要它们的一根骨头。平原狮的腿骨是他为治疗毒咬伤而寻求的一味药材。",kw={"血蹄村","腿骨","平原狮","茂尔·祈雨","马兹拉纳其","莫高雷"},ang={["class:Hunter"]="身为猎人，你需要敏锐的目光，才能在莫高雷摇曳的灌木丛中追踪flatland cougars，而这场狩猎也考验着你能否干净利落地击倒另一位掠食者。",["race:Tauren"]="对莫高雷的牛头人而言，猎杀flatland cougars既考验警觉性，也能为传统的平原药方提供不可或缺的材料。"},sec={{t="治疗毒咬伤的药方",b="平原狮是莫高雷最危险的本土潜猎者之一。它们隐没在干枯的灌木丛中，随后扑向毫无防备的猎物。猎人取它们的皮毛和利爪用于制皮或充当战利品，而它们粗重、富含骨髓的骨头则可用于当地的医药。血蹄村的茂尔·祈雨被一只名叫马兹拉纳其的巨大粉色陆行鸟所伤，身中剧毒。他急切地请求人们带来一根狮子的腿骨，以及其他当地野兽的身体部位。将骨头碾碎或熬煮，便可提取其中的药性，制成解毒膏，缓解发热，拔除溃烂咬伤中侵蚀血肉的毒素。"}},faq={{q="平原狮的腿骨有什么用途？",a="血蹄村的茂尔·祈雨需要这根腿骨来制作救急的药物。恶名昭彰的平原陆行鸟马兹拉纳其咬伤了他，他需要用骨髓和骨头配制解毒剂，赶在猛烈的毒素夺走他的性命之前救治自己。",al={"狮子腿骨用途","这根骨头有什么用","腿骨任务"}},{q="在哪里可以获得平原狮的腿骨？",a="你可以从游荡在莫高雷中部和南部平原的平原狮身上取得平原狮的腿骨。它们在血蹄村周围的山坡附近和高草丛中徘徊。",al={"哪里能找到腿骨","狮子腿骨位置","哪些怪物掉落"}},{q="茂尔·祈雨为什么偏偏需要狮子的骨头？",a="牛头人草药师和萨满祭司会用食肉动物坚实的骨头和骨髓制作传统药膏与酊剂。他们相信，莫高雷顶级掠食者的力量和韧性能为药物提供恢复生机的根基，以中和强效毒素。",al={"为什么要狮子骨头","为什么要腿骨"}},{q="茂尔·祈雨是谁？",a="茂尔·祈雨住在血蹄村。他在平原上漫游后，遭遇了祖父曾经交战过的传奇陆行鸟马兹拉纳其，肩膀被咬伤，伤口感染并带有剧毒，勉强才逃过一劫。",al={"茂尔·祈雨","谁需要骨头"}}},fp="21,172,28.545.0,43.216.0,44.178.0,58.226.0,23.224.0"}
P.entries["item:flatland-prowler-claw"] = {n="平原徘徊者的爪子",s="在莫高雷的平原上，平原徘徊者的爪子是年轻猎人接受试炼的凭证。猎人收集这些爪子，向雷霆崖的长者证明自己的决心与野外技艺。",h="在莫高雷的平原上，平原徘徊者的爪子是年轻猎人接受试炼的凭证。猎人收集这些爪子，向雷霆崖的长者证明自己的决心与野外技艺。",kw={"平原徘徊者","平原徘徊者的爪子","猎人高地","梅洛·石蹄","莫高雷","斯考恩·白云","猎人之道","雷霆崖"},ang={["class:Hunter"]="身为猎人，你与善于潜行的徘徊者较量，考验自己在野外的感知能力。它们的爪子表明，你已赢得雷霆崖猎人高地射手们的尊重。",["race:Tauren"]="身为牛头人，你将狩猎奉为一项精神传统。献上狡猾的平原捕食者的爪子，标志着你迈出了成为追踪者、为氏族效力的第一步。"},sec={{t="猎人的凭证",b="平原徘徊者潜行于莫高雷的平原，迅速从高草中伏击猎物。它们狡猾且领地意识强烈，对旅人十分危险，对年轻猎人也是严峻的考验。收集它们的爪子是一项公认的传统。斯考恩·白云会派有潜力的漫游者，将爪子带给雷霆崖猎人高地的梅洛·石蹄，以此证明他们具备踏上猎人之路所需的决心与野外技艺。"}},faq={{q="平原徘徊者的爪子有什么用途？",a="年轻猎人将四只平原徘徊者的爪子带给雷霆崖猎人高地的梅洛·石蹄。这些爪子证明了他们的技艺与勇气，也表明他们已准备好踏上猎人之路。",al={"徘徊者的爪子用途","为何收集徘徊者的爪子","猎人之路爪子"}},{q="是谁让你收集这些爪子的？",a="斯考恩·白云让有潜力的追踪者先收集莫高雷徘徊者的爪子，再去拜见梅洛·石蹄。",al={"谁需要徘徊者的爪子","徘徊者的爪子任务给予者"}},{q="为什么平原徘徊者被视为合适的猎物？",a="平原徘徊者是莫高雷平原上土生土长的食肉野兽，强悍且善于潜行。追踪并击败这些警觉的捕食者，能够考验牛头人传统要求猎人具备的耐心与战斗本能。",al={"为何猎杀平原徘徊者","徘徊者危险吗"}}},fp="21,138,16.457.0,41.189.0,29.129.0,52.196.0"}
P.entries["item:foreman-s-blackjack"] = {n="工头的木棒",s="工头的木棒让杜隆塔尔试炼谷的苦工不敢停工。在部落最初的建设中，工头们用这根包着皮革的短棒，叫醒干活时睡着的劳工。",h="工头的木棒让杜隆塔尔试炼谷的苦工不敢停工。在部落最初的建设中，工头们用这根包着皮革的短棒，叫醒干活时睡着的劳工。",kw={"木棒","杜隆塔尔","工头的木棒","懒惰的苦工","苦工","工头塔兹利尔","试炼谷"},ang={["faction:Horde"]="这根木棒体现了征服杜隆塔尔所需的切实劳作，要在这片严酷的土地上安家，每个劳工都必须不停地干活。",["race:Orc"]="对进入试炼谷的年轻兽人来说，挥动木棒让他们早早领教了部落的等级秩序：缺乏战士力量或斗志的人会被派去做苦工，并受到武力管束。"},sec={{t="兽人的劳作工具",b="杜隆塔尔荒凉的沙漠需要储备大量木材，用来建设部落的新家园。在试炼谷，这份差事落在苦工身上，工头塔兹利尔则用工头的木棒督促他们干活。这根加重的棍棒会猛然惊醒那些在谷中树荫下打盹的劳工，而不会一击致命。在新部落，苦工的生活就是在铁腕管束下，做着繁重而不起眼的工作。"}},faq={{q="工头的木棒有什么用途？",a="监工把木棒交给年轻的冒险者，用来惩戒试炼谷里睡觉的苦工。一棒下去，打盹的苦工就会猛然惊醒，立刻回去砍伐和搬运木材。",al={"木棒用途","为什么用木棒","苦工木棒"}},{q="这根木棒属于谁？",a="这根木棒属于工头塔兹利尔。这位劳工监工驻守在试炼谷，监督原木的采集，为新建的兽人定居点提供木材。",al={"谁给木棒","工头的木棒主人"}},{q="苦工为什么总在干活时睡着？",a="兽人苦工顶着杜隆塔尔的烈日采集木材，轮班劳作，疲惫不堪。当疲劳难以抵挡时，他们常常未经允许就在谷中稀疏的树下打盹。",al={"苦工为什么懒惰","懒惰的苦工睡觉"}},{q="完成任务后，我能留下这根木棒吗？",a="不能。惩戒过那些偷懒的苦工后，监工就会要求立刻归还工具。它会留在监工手边，用来督促劳工完成定额。",al={"保留木棒","能否保留工头的木棒"}}},fp="19,184,22.379.0,41.186.0,24.173.0,48.178.0,50.137.0"}
P.entries["item:forged-steel-bars"] = {n="锻造好的钢锭",s="在贫瘠之地北部，索恩格瑞姆·火眼的钢锭失窃了。找回这些钢锭，将证明一名战士夺回失窃财物的决心。",h="在贫瘠之地北部，索恩格瑞姆·火眼的钢锭失窃了。找回这些钢锭，将证明一名战士夺回失窃财物的决心。",kw={"贫瘠之地","锻钢","锻造好的钢锭","铁箱","钢鬃","失窃的铁箱","索恩格瑞姆·火眼"},ang={["class:Warrior"]="找回索恩格瑞姆失窃的钢材，能证明一名战士有能力追踪窃贼，并迎战成群的危险野猪人。作为回报，索恩格瑞姆会提供量身打造的武器。",["profession:Blacksmithing"]="这些精炼钢锭展现了粗陋的部族废铁与训练有素的部落铁匠打造的优质钢材之间的差别。"},sec={{t="失窃的金属",b="索恩格瑞姆·火眼是一位视力不佳的兽人铁匠，在贫瘠之地北部扎营。钢鬃野猪人在一次夜袭中偷走了他的铁箱，他们用哼叫声分散他的注意力，让窃贼趁机溜走。野猪人不会加工精钢，于是把尚未打开的箱子留在了西北方营地里的一辆破旧货车旁。钢锭仍完好无损，等待愿意出手的战士将它们找回。"}},faq={{q="这些锻造好的钢锭是谁的？",a="这些钢锭属于索恩格瑞姆·火眼，他是一位锻造护甲和武器的兽人铁匠，住在贫瘠之地北部的一处营地。",al={"钢锭的主人","索恩格瑞姆的钢材","这是谁的钢材"}},{q="野猪人为什么要偷走它们？",a="钢鬃野猪人偷走这些钢锭，是为了掠夺索恩格瑞姆的财物。他们知道他的视力不好，便出言嘲弄，分散他的注意力，让其他人搬走了他的铁箱。",al={"为什么偷钢材","野猪人的动机","钢鬃盗窃"}},{q="野猪人用过这些钢材吗？",a="没有。钢鬃缺乏加工这种精炼钢材的技艺。他们没有打开箱子，就把它丢在了营地里的一辆破损货车旁。",al={"野猪人锻造过什么","野猪人拿钢材做了什么"}},{q="找回钢锭后，索恩格瑞姆会给什么报酬？",a="索恩格瑞姆会为有志向的战士打造一件武器，作为勇闯野猪人营地并归还全部钢锭的报酬。",al={"锻造好的钢锭奖励","归还钢材有什么奖励"}}},fp="17,144,12.419.0,33.114.0,32.173.0,31.136.0,45.110.0"}
P.entries["item:fragments-of-rok-alim"] = {n="罗卡里姆的碎片",s="罗卡里姆的碎片是一位游荡在千针石林峡谷中的原始土元素留下的碎石残骸。将它们带给老屋的多恩·平原行者，便能以无可辩驳的实物证明，一名勇士曾在单打独斗中击败远古的恐怖存在。",h="罗卡里姆的碎片是一位游荡在千针石林峡谷中的原始土元素留下的碎石残骸。将它们带给老屋的多恩·平原行者，便能以无可辩驳的实物证明，一名勇士曾在单打独斗中击败远古的恐怖存在。",kw={"多恩·平原行者","元素生物","碎片","重锤","罗卡里姆","力量试炼","千针石林","老屋"},ang={["class:Shaman"]="罗卡里姆是一个古老的大地之灵，早在如今的萨满契约出现之前便已与这个世界相连，他不屈的本性为研究元素最原始的顽强提供了一个引人入胜的对象。",["race:Tauren"]="战胜艾泽拉斯原始时代留存至今的遗存，与牛头人的传统十分契合：面对大地上最可怕的险境，考验自身的和谐、坚韧与力量。"},sec={{t="远古力量的残骸",b="上古之神遭到放逐后，大多数元素生物都从艾泽拉斯消退了，只有少数凭借足够强大的原始力量，无须凡人施法召唤便能留在地表。罗卡里姆就是这样的幸存者之一，游荡在主干道以南的峡谷平地上。他的石拳会将胆敢闯入其行进路线的东西砸得粉碎，当地半人马凭那雷鸣般的巨响认出了他。击倒这个原始世界的活化遗存，便能获得棱角锋利、致密而富有活力的岩石碎块——足以证明无匹体魄的战利品。"},{t="力量的试炼",b="对于牛头人隐士多恩·平原行者而言，取回这些碎片是力量试炼的决定性环节。这场试炼是高处老屋中举行的一系列精神与武艺仪式的一部分，要求受试者直面一个拥有不可撼动蛮力的存在。交回罗卡里姆饱经重击的碎石，便能证明冒险者具备在卡利姆多最严酷的险境中生存所需的勇气与力量。"}},faq={{q="罗卡里姆的碎片是什么？",a="它们是罗卡里姆留下的碎石残骸，这个古老的土元素徘徊在千针石林西北部的峡谷中。它们是击败这个元素生物的凭证。",al={"罗卡里姆的碎片","罗卡里姆 碎片是什么","罗卡里姆 的石头"}},{q="谁需要这些石头碎片？",a="多恩·平原行者是一名发布任务的牛头人，住在千针石林峡谷峭壁高处的老屋，他要求带回这些碎片来完成力量试炼。",al={"谁收取 罗卡里姆 碎片","交付罗卡里姆的碎片","多恩·平原行者任务"}},{q="罗卡里姆为何如此重要？",a="如今的大多数元素生物都必须由凡人法师召唤，而罗卡里姆自上古之神的时代起便一直留在世间。峡谷中的半人马部族听到他用双拳碾碎猎物时发出的轰鸣，便给他起名为“重锤”。",al={"罗卡里姆 为何特别","罗卡里姆 的故事","重锤罗卡里姆是谁"}},{q="在哪里能找到罗卡里姆？",a="罗卡里姆在千针石林西北部的盆地中游荡，徘徊于该地区主干道以南的砂岩尖柱之间。",al={"罗卡里姆 位置","寻找重锤罗卡里姆","罗卡里姆 在哪里刷新"}}},fx={ab6946f8={q="罗卡里姆的碎片从何而来？",a="这些碎片是重拳罗卡里姆身上崩落的石块。这个巨大的岩石元素生物游荡在千针石林西北部的峡谷底部。罗卡里姆并非由凡人施法者召唤而来，而是从上古之神时代存活至今的古老存在；即使它的主人已经陨落，它天生的力量仍足以使它留存于世。这些碎片并非由凡人亲手打造，而是直接从它活着的岩石躯体上敲下来的。",al={"罗卡里姆碎片的来历","罗卡里姆碎片从哪里来","谁制造了罗卡里姆碎片"}}},fp="21,180,28.394.0,18.321.0,35.174.0,32.159.0,28.236.0,24.112.0"}
P.entries["item:frostwolf-banner"] = {n="霜狼军旗",s="在奥特兰克山谷，部落新兵前往蛮爪洞穴寻找霜狼军旗。寻回军旗是祖辈传下的入门仪式，能唤醒他们的战斗精神，让他们获得第一枚氏族徽记。",h="在奥特兰克山谷，部落新兵前往蛮爪洞穴寻找霜狼军旗。寻回军旗是祖辈传下的入门仪式，能唤醒他们的战斗精神，让他们获得第一枚氏族徽记。",kw={"奥特兰克山谷","霜狼军旗","豺狼人","徽记","实验场","拉格隆德","蛮爪洞穴"},ang={["faction:Horde"]="寻回军旗，便意味着战士正式通过考验，加入拉格隆德麾下的霜狼氏族。",["race:Orc"]="身为兽人，从凶残的豺狼人手中夺回氏族军旗，是对霜狼氏族传承的致敬，也是对萨尔在奥特兰克山脉的先祖遗产的敬重。"},sec={{t="入门试炼",b="想要加入霜狼氏族的部落战士，必须在奥特兰克山谷接受意志的考验。拉格隆德派新兵南下，进入蛮爪洞穴，潮湿险恶的通道里满是守卫领地的豺狼人。找到藏在洞中的军旗，并将其完好无损地带回，便能证明他们的勇气，也表明他们的战斗怒火已经觉醒。通过试炼的战士都会获得一枚霜狼新兵徽记。"}},faq={{q="霜狼军旗为什么会在豺狼人的洞穴里？",a="拉格隆德和氏族将军旗放在蛮爪洞穴，以此考验新兵。新战士必须进入豺狼人的领地，直面危险，摆脱懈怠，唤醒自己的战斗精神。",al={"军旗为何在蛮爪洞穴","豺狼人持有军旗","霜狼军旗位置"}},{q="霜狼军旗该交还给谁？",a="将军旗交还给奥特兰克山谷的拉格隆德。向他呈交军旗后，新兵便能加入霜狼的队伍，并获得一枚象征身份的徽记。",al={"谁需要霜狼军旗","军旗任务交付","拉格隆德军旗"}},{q="为什么这面军旗上的徽记看起来不像寻常的霜狼纹章？",a="拉格隆德认定这面军旗是氏族用于试炼的旗帜，但旗上的图案却与更古老的部族徽记相似。其中包括旧部落早期兽人氏族使用的符号。",al={"暮光之锤符号军旗","军旗样式不对","霜狼军旗图案"}}},fx={cf6c63b1={q="什么是霜狼军旗？",a="霜狼军旗是代表奥特兰克山谷中霜狼氏族的部族旗帜。旗帜上的纹章奇怪地更像古老的氏族图案，而不是他们惯用的徽记，但它仍是霜狼氏族在这片冰封山谷中存在与权威的荣誉象征。",al={"什么是霜狼军旗","霜狼军旗的背景","关于霜狼军旗"}},["518ec450"]={q="拉格隆德为什么想要找回霜狼军旗？",a="拉格隆德要求所有希望在奥特兰克山谷与霜狼氏族并肩作战的新人接受一场战斗仪式。从食人妖横行的蛮爪洞穴深处找回军旗，能够证明你的勇气，唤醒你的战士之魂，并让你获得氏族新兵的徽记。",al={"为什么找回霜狼军旗","拉格隆德为什么想要军旗","霜狼军旗的用途"}}},fp="16,187,17.384.0,48.208.0,40.160.0,57.196.0"}
P.entries["item:full-leaden-collection-phial"] = {n="装满的铅瓶",s="在卡拉诺斯，奥齐·电环正寻求诺莫瑞根穴居人的样本。他希望用它治好受辐射的麻风侏儒，或许还能酿出烈得危险的朗姆酒。",h="在卡拉诺斯，奥齐·电环正寻求诺莫瑞根穴居人的样本。他希望用它治好受辐射的麻风侏儒，或许还能酿出烈得危险的朗姆酒。",kw={"装满的铅瓶","诺恩","诺莫瑞根","受辐射穴居人","卡拉诺斯","铅质收集瓶","麻风侏儒","奥齐·电环"},ang={["profession:Engineering"]="铅制外壳体现了侏儒在实验室测试中处理不稳定的有毒辐射尘时所遵循的安全规程。",["race:Gnome"]="对流亡丹莫罗的侏儒而言，携带这份剧毒样本，会让他们想起那场毒害祖居的灾难。它也让他们在绝望中看到了治愈受污染同胞的希望。"},sec={{t="剧毒佳酿",b="铅制内衬保护携带者免受遍布诺莫瑞根的绿色不稳定辐射尘侵害。大工匠梅卡托克的顾问们曾用剧毒辐射淹没下层通道，试图阻止穴居人入侵。结果，这场灾难却将穴居人和幸存的侏儒变成了疯狂的辐射怪物。\n\n辐射入侵者和抢劫者留下的残液，成了卡拉诺斯流亡工匠的材料。奥齐·电环和拉兹·滑链用它作为原料，进行治疗药剂的实验。"},{t="解药还是怪饮",b="奥齐·电环为应对辐射灾害而疯狂实验，诺恩则仍一心想要夺回城市。奥齐·电环希望这种液体能治疗一名被困的麻风侏儒，或许还能治好自己的秃头。在侏儒实验室里，神奇解药和极不稳定的饮料之间，始终只有危险的一线之隔。"}},faq={{q="为什么这只小瓶要用铅制成？",a="小瓶的铅制内衬保护携带者免受强烈辐射尘的侵害，这些辐射尘采自诺莫瑞根受污染的穴居人。因此，他们能将小瓶带回卡拉诺斯，免于患病或死亡。",al={"为何用铅制小瓶","为何用铅制瓶","铅质收集瓶用途"}},{q="谁想要这种受辐射的液体？",a="卡拉诺斯的侏儒研究员奥齐·电环想用这些辐射尘进行实验，寻找治疗麻风侏儒的方法。拉兹·滑链协助他开展研究。",al={"谁需要小瓶","奥齐·电环任务","诺恩交给谁"}},{q="小瓶里的辐射来自哪里？",a="发出绿光的残液来自辐射入侵者和辐射抢劫者，这些穴居人在通往诺莫瑞根的受污染通道中游荡。",al={"如何装满小瓶","受辐射穴居人位置","绿光来源"}},{q="奥齐·电环真的用它治好了麻风侏儒吗？",a="奥齐·电环的实验混乱不堪，结果难料。他调制的药剂旨在治好一名被抓获的麻风侏儒，并让自己的头发重新长出来，但侏儒科学往往需要反复测试、提纯样本，才能得到安全而稳定的结果。",al={"解药是否有效","诺恩结果","麻风侏儒是否治愈"}}},fx={["32cc4509"]={q="装满的铅瓶是什么？",a="这是一个沉重的铅制防护瓶，里面装满了泛着绿光的放射性尘埃，直接采自盘踞在诺莫瑞根的受污染穴居人。厚实的铅壳能防止危险的放射性残留物毒害携带者。",al={"铅瓶是什么","装满的铅瓶","这个瓶子是什么"}}},fp="28,161,12.485.0,18.331.1,30.195.0,32.163.0,48.145.0,50.226.0"}
P.entries["item:fungal-spores"] = {n="菌类孢子",s="在贫瘠之地的绿洲周围，菌类孢子聚集在膨大的蘑菇中。绿洲的水让周围的生命蓬勃生长，皇家药剂师学会则收集这些孢子用于炼金术。",h="在贫瘠之地的绿洲周围，菌类孢子聚集在膨大的蘑菇中。绿洲的水让周围的生命蓬勃生长，皇家药剂师学会则收集这些孢子用于炼金术。",kw={"药剂师赫布瑞姆","药剂师协会","贫瘠之地","十字路口","遗忘之池","菌类孢子","饱满的蘑菇","甜水绿洲","死水绿洲"},ang={["profession:Herbalism"]="作为一名草药师，你能看出贫瘠之地绿洲中赋予生机的池水如何改变附近生长的蘑菇。",["race:Undead"]="作为一名亡灵，你知道皇家药剂师学会重视各地的稀有原料，将其用于研究。与洛丹伦遭受枯萎侵蚀的植物相比，卡利姆多的变异菌类提供了另一种选择。"},sec={{t="绿洲的生机",b="贫瘠之地的绿洲为干燥的平原带来了不同寻常的生机。在遗忘之池、甜水绿洲和死水绿洲，池水不仅能解渴。它还会促进附近的植物和野生动物生长，并使它们发生变化。潮湿岸边的蘑菇因富含孢子而膨大，这些孢子凝聚着池水促进生长的力量。博物学者研究这种变化，皇家药剂师学会则采集这些蘑菇用于炼金术。"},{t="被遗忘者的炼金术",b="在外活动的药剂师会为实验室和同僚收集当地的奇异原料。在十字路口，药剂师赫布瑞姆将这类材料转送各地，其中也包括雷霆崖的药剂师扎玛。这些孢子是调制强效化学药剂的珍贵材料。卡利姆多土壤之下的神秘力量已经改变了它们的天然特性，使它们能为被遗忘者所用。"}},faq={{q="这些孢子在哪里能找到？",a="你可以在贫瘠之地几处主要绿洲的岸边，从膨大的蘑菇中找到菌类孢子：遗忘之池、甜水绿洲和死水绿洲。",al={"孢子位置","哪里能找到菌类孢子","大蘑菇位置"}},{q="被遗忘者为什么对它们感兴趣？",a="绿洲的水蕴含着旺盛的生命能量，使这些孢子发生了变化。药剂师赫布瑞姆用它们为皇家药剂师学会和他在雷霆崖的同僚药剂师扎玛调制强效药剂。",al={"药剂师赫布瑞姆为什么需要孢子","药剂师的孢子用途","孢子有什么用途"}},{q="绿洲周围的蘑菇为什么长得这么大？",a="贫瘠之地的绿洲池水蕴含着不同寻常的生命能量，会改变附近的动植物。岸边的菌类因富含变异孢子而膨大。",al={"蘑菇为什么变异","绿洲池水的作用","绿洲之谜"}},{q="谁在征集孢子？",a="药剂师赫布瑞姆是贫瘠之地十字路口的一位被遗忘者炼金师，他请冒险者收集孢子供他研究。",al={"谁需要菌类孢子","孢子任务发布者","药剂师赫布瑞姆"}}},fp="13,178,21.429.0,16.379.0,29.151.0,40.200.0,52.133.0,24.104.0"}
P.entries["item:furen-s-instructions"] = {n="弗伦的材料清单",s="在暴风城，弗伦·长须会将一份打造火焰淬炼锁甲所需的材料清单交给经受过考验的联盟战士。",h="在暴风城，弗伦·长须会将一份打造火焰淬炼锁甲所需的材料清单交给经受过考验的联盟战士。",kw={"烧焦的奇美拉角","火焰淬炼锁甲","弗伦·长须","弗伦的材料清单","光滑的奇美拉角","剃刀沼泽","烧焦的蜘蛛牙","石爪山","燃素","湿地"},ang={["class:Warrior"]="身为联盟战士，你要迎战凶猛的野兽和野猪人，经受考验，才能赢得厚重的锁甲。",["profession:Blacksmithing"]="身为铁匠，你能看出弗伦的配方如何将野兽身上的材料与稀有的炼金蒸馏物结合，用超越普通锻造的手法淬炼护甲。"},sec={{t="锻造大师的要求",b="弗伦·长须愿意为在较简单的锻造任务中证明了自己的战士打造一套坚韧的锁甲。这位矮人护甲匠要求战士亲自找来那些稀有材料。他的羊皮纸上记载着所需之物，指引战士跨越大陆收集材料。"},{t="奇异的材料",b="羊皮纸上的要求意味着一段穿越东部王国和卡利姆多的危险旅程。数十颗烧焦的蜘蛛牙必须从湿地潮湿的洞穴中取得。坚硬的锁环还需要石爪山脉峭壁间那些喷火奇美拉的角。清单还要求从奇美拉族母身上取得一根光滑的奇美拉角，以及藏在野猪人堡垒剃刀沼泽深处的一瓶不稳定的燃素。"}},faq={{q="弗伦的材料清单是什么？",a="弗伦的材料清单是弗伦·长须在暴风城交给联盟战士的书面清单。上面列出了打造火焰淬炼锁甲所需的奇异材料。",al={"弗伦的材料清单","弗伦的材料清单是什么","弗伦清单"}},{q="弗伦·长须是谁？",a="弗伦·长须是暴风城矮人区的一位矮人护甲大师。他考验经验丰富的战士，并为他们打造耐用的护具。",al={"弗伦是谁","弗伦·长须","弗伦暴风城"}},{q="清单上的材料来自哪里？",a="清单要求从湿地取得烧焦的蜘蛛牙，从石爪山脉的奇美拉身上取得烧焦的角和光滑的奇美拉角，再从剃刀沼泽的鲁古格那里取得一瓶燃素。",al={"物品获取地点","弗伦材料位置","弗伦清单上的材料"}},{q="弗伦用这些材料锻造什么？",a="弗伦运用这些材料和自己的锻造秘法，为战士打造一件特制的火焰淬炼锁甲。",al={"弗伦打造什么护甲","火焰淬炼锁甲奖励","弗伦锻造奖励"}}},fx={["82702a01"]={q="弗伦的材料清单从何而来，是谁编写的？",a="弗伦·长须是一位在暴风城工作的矮人锻造大师，这份文书正是他亲手写的。他掌握着打造精良锁甲的秘法，于是写下这份详尽的清单，列出散落世界各地的稀有材料，让胸怀壮志的战士清楚自己该寻找什么。",al={"谁写了弗伦的材料清单","弗伦的材料清单从何而来","弗伦的材料清单来源"}},["42eefba8"]={q="弗伦的材料清单为什么重要？",a="这份清单指引你踏上横跨卡利姆多与东部王国的艰辛寻物之旅。弗伦要求你在收集烧焦的蜘蛛牙、奇美拉之角和燃素时随身携带它，确保你带回的材料正是他锻造淬火护甲所需的。",al={"为什么需要弗伦的材料清单","为什么有人需要弗伦的材料清单","弗伦的材料清单用途"}}},fp="20,106,24.279.0,17.410.0,29.161.0,23.147.0,45.191.0,43.117.0"}
P.entries["item:furen-s-notes"] = {n="弗伦的笔记",s="在暴风城，弗伦的笔记将他在冶金和铸甲方面的发现传给联盟的工匠。弗伦·长须为身经百战的战士锻造护具，又送出笔记副本，帮助其他铁匠改进技艺。",h="在暴风城，弗伦的笔记将他在冶金和铸甲方面的发现传给联盟的工匠。弗伦·长须为身经百战的战士锻造护具，又送出笔记副本，帮助其他铁匠改进技艺。",kw={"锻造","矮人区","弗伦","弗伦·长须","弗伦的笔记","格瑞曼德·艾尔默","科罗莫特·钢尺","玛希尔"},ang={["class:Warrior"]="身为战士，你在暴风城经历的护甲试炼会直接引出这些笔记。笔记记录了源于前线作战需求的实用构想。",["profession:Blacksmithing"]="身为铁匠，你能看到专门的铸甲知识在联盟各地的矮人、精灵和侏儒工匠之间流传。"},sec={{t="大师的发现",b="在暴风城的矮人区，弗伦·长须为战士锻造专用装备。他一边工作，一边记录自己的方法和发现。矮人的金属加工技艺不断变化，因此他抄写了数份笔记，供其他铁匠使用并进一步改进。他的笔记记述了为护甲淬火、加固和塑形的方法，使其能够抵挡致命的打击。"},{t="送往联盟各地",b="弗伦将副本送给联盟工匠中值得信赖的熟人。格瑞曼德·艾尔默声称自己教过这位铁匠，或许会对他嗤之以鼻，但笔记中仍有实用的见解。有些副本越过无尽之海，送到暗夜精灵工匠手中，其中就包括达纳苏斯战士区的玛希尔。战场上的共同需求将他们不同的传统联系在一起。"}},faq={{q="弗伦的笔记中记载了什么？",a="弗伦的笔记记述了弗伦·长须为身经百战的战士定制护甲时钻研出的铸甲技艺，以及他在冶金方面的发现。",al={"弗伦的笔记是什么","弗伦的笔记里有什么","弗伦的笔记内容"}},{q="弗伦·长须是谁？",a="弗伦·长须是暴风城矮人区的一位矮人铸甲大师。他指引初露头角的战士，并打造专用的防御装备。",al={"谁写的","弗伦是谁","弗伦·长须"}},{q="格瑞曼德·艾尔默为什么会因这些笔记而生气？",a="格瑞曼德·艾尔默声称，弗伦这个矮人的一身本领都是他教的。有人认为他从前的学生能教给他新东西，这让他很不痛快，不过他也承认笔记中记述的技艺值得一试。",al={"格瑞曼德为什么生气","格瑞曼德 艾尔默的反应","格瑞曼德的自傲"}},{q="谁会收到弗伦的笔记副本？",a="弗伦将副本送给联盟各地值得信赖的同行，包括暴风城的武器匠格瑞曼德·艾尔默、达纳苏斯的暗夜精灵铁匠玛希尔，以及铁炉堡的侏儒铁匠科罗莫特·钢尺。",al={"谁收到弗伦的笔记","笔记送往哪里","递送弗伦的笔记"}},{q="玛希尔对这些笔记有何反应？",a="玛希尔是达纳苏斯战士区的一位暗夜精灵铁匠，他热情地欢迎弗伦的发现。他认为这些是重大的发现，能将它们用于自己的锻造工作是一种荣幸。",al={"玛希尔的反应","玛希尔 达纳苏斯","玛希尔怎么看"}}},fx={["224f803f"]={q="为什么有人需要弗伦的笔记？",a="这些笔记记录了弗伦·长须在锻造战士专用护甲时开创的突破性锻造技法。联盟各地的铁匠，比如达纳苏斯的玛希尔和暴风城的格瑞曼德·艾尔默，都能从中获得宝贵的冶金知识。即便是艾尔默这样对弗伦的技艺心存怀疑的工匠，也承认其中有创新的想法，迫不及待地想在自己的铁砧上试一试。",al={"铁匠为什么需要弗伦的笔记","弗伦的笔记价值","为什么分享弗伦的笔记"}}},fp="13,223,22.332.0,30.350.0,39.157.0,23.146.0,50.205.0,37.212.0,36.183.0"}
P.entries["item:furlbrow-s-deed"] = {n="法布隆的地契",s="在西部荒野边境附近，西奥多和弗娜·法布隆守着损坏的货车，他们的农场已落入迪菲亚潜行者之手。他们的地契被强盗夺走，家园和生计也随之失去。",h="在西部荒野边境附近，西奥多和弗娜·法布隆守着损坏的货车，他们的农场已落入迪菲亚潜行者之手。他们的地契被强盗夺走，家园和生计也随之失去。",kw={"地契","迪菲亚","农场","法布隆","西奥多","弗娜","货车","西部荒野"},ang={["faction:Alliance"]="身为联盟的一员，在王国兵力不足之时，你可以给那些被迫离开家园的人带去些许慰藉。",["race:Human"]="身为人类，你能看到迪菲亚如何破坏暴风城周边土地上的秩序，甚至连普通的地契也不放过。"},sec={{t="被夺的土地与伪造的产权",b="西奥多·法布隆和弗娜签署了地契，以确保他们在西部荒野的家族农场归自己所有。迪菲亚潜行者席卷这片地区后，强盗将他们赶出家园，把地契带进了艾尔文森林。地契背面的笔记表明，窃贼打算仿制地契，伪造其他地产的产权凭证。法布隆一家失去了生计，只得流落在外，无家可归。"}},faq={{q="迪菲亚为什么要偷走地契？",a="地契上的笔记表明，迪菲亚打算研究上面的印章和签名，再伪造产权凭证，将西部荒野各处被侵占的农庄据为己有。",al={"为什么偷地契","强盗为什么要地契","迪菲亚地契用途"}},{q="这张地契属于谁？",a="这张地契属于农夫西奥多·法布隆和他的妻子弗娜。歹徒将这对西部荒野的农户夫妇赶出了他们的农场。",al={"法布隆的地契属于谁","法布隆是谁","这是谁的地契"}},{q="在哪里能找到法布隆一家？",a="沿着艾尔文森林通往西部荒野的大路，刚进入西部荒野，就能在损坏的货车旁找到西奥多和弗娜。",al={"法布隆一家在哪里","农夫法布隆位置","去哪里归还地契"}},{q="法布隆一家既然已经逃走，为什么还在意地契？",a="法布隆一家知道，如今的西部荒野对老实人来说太危险了。尽管如此，这份产权证明仍让他们心怀希望，盼着和平归来时能收回自己的土地。",al={"为什么想拿回地契","法布隆一家会回来吗"}}},fx={["4593623b"]={q="法布隆的地契从何而来，是谁签立的？",a="这份地契是西部荒野一片农田的正式土地所有权凭证，由西奥多·法布隆签署，他的妻子弗娜共同签署。它确立了他们对家族农庄的合法所有权，后来迪菲亚匪徒勒索了他们，还直接从他们手中抢走了地契。",al={"法布隆的地契来源","谁签立了法布隆的地契","地契从何而来"}}},fp="15,205,29.380.0,34.129.0,29.121.0,33.116.0,60.150.0"}
P.entries["item:furlbrow-s-pocket-watch"] = {n="法布隆的怀表",s="在西部荒野，农夫法布隆正在寻找被迪菲亚匪徒赶出家园时遗落的怀表。那是弗娜的父亲在他们成婚那天送给他的。",h="在西部荒野，农夫法布隆正在寻找被迪菲亚匪徒赶出家园时遗落的怀表。那是弗娜的父亲在他们成婚那天送给他的。",kw={"本尼·布兰科","迪菲亚","农夫法布隆","法布隆的怀表","被遗忘的传家宝","弗娜·法布隆","衣柜","西部荒野"},ang={["faction:Alliance"]="帮助法布隆夫妇找回传家之物，足以看出暴风城王室在保护西部荒野辛勤劳作的农民免受有组织的匪帮侵害一事上，失职到了何种地步。"},sec={{t="废墟中的纪念物",b="迪菲亚匪徒趁夜将农夫法布隆和弗娜赶出了他们在法布隆南瓜农场的家。逃亡时，他把怀表落在了那座沦陷农舍的衣柜里。本尼·布兰科和他手下的亡命徒就在附近看守。\n\n这对夫妇如今在路边扎营。匪徒几乎毁掉了他们从前生活的一切，怀表是少数幸存的物件之一。"}},faq={{q="这块怀表为何对农夫法布隆如此重要？",a="弗娜的父亲在他们成婚那天，将这块怀表送给了农夫法布隆。迪菲亚潜行者夺走了他们的土地、家园和生计后，这块怀表成了夫妇俩最后一件寄托着深厚感情的财物。",al={"法布隆为何想找回怀表","法布隆怀表的重要性","谁送给法布隆怀表"}},{q="怀表放在哪里？",a="怀表放在法布隆农舍的衣柜里，那座农舍位于大路西侧的南瓜田中，法布隆夫妇就流落在这条路边。",al={"怀表在哪里","法布隆衣柜位置","如何找到怀表"}},{q="谁在看守怀表？",a="迪菲亚潜行者已经占据了农舍。本尼·布兰科和他的同伙在衣柜附近游荡。",al={"法布隆的怀表在谁手里","西部荒野怀表守卫","本尼·布兰科怀表"}},{q="怀表是迪菲亚直接偷走的吗？",a="迪菲亚并没有直接偷走怀表。匪徒袭击南瓜田时，法布隆夫妇仓皇出逃，农夫法布隆忘了带上它。农场沦陷时，怀表仍留在他们卧室的衣柜里。",al={"迪菲亚是否掠走了怀表","怀表是否被偷"}}},fx={["42b91745"]={q="法布隆的怀表是什么？",a="这是农夫法布隆珍爱的传家宝。这只怀表是他妻子弗娜的父亲在两人婚礼当天送给他的礼物。迪菲亚潜行者占领他们的南瓜农场时，夫妇俩不得不在深夜逃命，慌乱中将这件珍贵的计时器遗落在衣柜里。",al={"法布隆的怀表是什么","法布隆的怀表","农夫法布隆的怀表"}},ba43cdcd={q="法布隆的怀表从何而来，是谁制作的？",a="这只怀表原本属于弗娜·法布隆的父亲，他在女儿的婚礼当天将它赠给了农夫法布隆。具体是哪位工匠制作、产自哪座城市，已无从得知，但对这对流离失所的农夫夫妇而言，它是为数不多留存至今的信物，承载着他们的家庭，以及被迪菲亚赶离土地之前的生活。",al={"谁制作了法布隆的怀表","法布隆从哪里得到怀表","法布隆的怀表来源"}}},fp="23,161,23.356.0,56.202.0,31.136.0,26.107.0,40.219.0"}
P.entries["item:gaea-seed"] = {n="盖亚之种",s="在暗色湖畔，盖亚之种为治愈石爪山受创的土地带来了希望。牛头人萨满珍视这些顽强的种子，用它们修复遭受战火与工业摧残的地方。",h="在暗色湖畔，盖亚之种为治愈石爪山受创的土地带来了希望。牛头人萨满珍视这些顽强的种子，用它们修复遭受战火与工业摧残的地方。",kw={"焦炭谷","重生的循环","大地母亲","盖亚之种","暗色湖","石爪山","烈日石居","塔姆拉·荒原"},ang={["class:Shaman"]="身为萨满，你能看到元素仪式与Earthmother的祝福如何加快生长，帮助治愈受创的土地。",["race:Tauren"]="身为牛头人，你与烈日石居的族人肩负着同样的神圣职责，治愈遭到外来战火与伐木破坏的土地。"},sec={{t="复苏的载体",b="盖亚之种会被湖水冲上岸，也会生长在石爪山脉的暗色湖畔。它们小巧，外壳富含纤维，看起来像椰子，却能耐受恶劣的环境。冲突与工业令大地伤痕累累，萨满们视这些种子为治愈大地的途径。"},{t="大地母亲的祝福",b="在烈日石居，牛头人萨满塔姆拉·荒原收集盖亚之种，以应对群山各处遭受的破坏。萨满们通过传统吟唱和元素仪式，将大地母亲的力量赐予沉眠的种壳。这份祝福能加快它们的生长，使其成为顽强的树苗，在焦炭谷那样焦灼贫瘠的土地上扎根。"}},faq={{q="哪里能找到盖亚之种？",a="在石爪山境内、烈日石居以北的群山中，盖亚之种会被湖水冲上暗色湖沿岸。",al={"盖亚之种位置","哪里能找到盖亚之种","如何获得盖亚之种"}},{q="盖亚之种有什么用途？",a="在烈日石居，塔姆拉·荒原收集盖亚之种，为它们施加元素祝福。受到祝福的种子能帮助焦炭谷等饱受摧残的地方恢复植被。",al={"盖亚之种用途","为什么收集盖亚之种","塔姆拉用盖亚之种做什么"}},{q="萨满为什么需要为种子注入力量？",a="大火、战乱与伐木已使石爪山的部分地区遭到严重破坏。大地母亲的力量能加快种子的生长，让它们更加顽强，得以在受损的土壤中扎根。",al={"为什么祝福种子","萨满盖亚之种魔法"}},{q="盖亚之种是什么样的？",a="在暗色湖水边，盖亚之种看起来像小巧、棕色、浑圆的种壳或椰子。",al={"盖亚之种外观","如何辨认盖亚之种"}}},fx={["0f706426"]={q="盖亚之种是什么？",a="盖亚之种是一种坚韧的椰子状种核，原产于石爪山脉。它们天生坚韧，蕴含强大的植物生长潜能。牛头人萨满借助大地母亲的祝福引导这股力量，让遭受工业贪欲和战火蹂躏的土地重新焕发生机。",al={"盖亚之种是什么","盖亚之种介绍","什么是盖亚之种"}},e9a7441d={q="盖亚之种来自哪里？",a="盖亚之种是天然的植物奇珍，只生长在石爪山脉高处、烈日石居以北的暗色湖沿岸。它们并非由凡人制作，而是大地母亲赐予的自然馈赠，在湖岸边自然繁茂。",al={"谁制作了盖亚之种","盖亚之种来源","盖亚之种来自哪里"}},["3509f4c5"]={q="塔姆拉·荒原为什么想要盖亚之种？",a="烈日石居的萨满塔姆拉·荒原想用盖亚之种治愈伤痕累累的石爪山荒野。持续的伐木和战斗重创了这片区域，尤其是焦炭谷那片焦土。收集这些种子后，她便能将大地母亲的祝福和萨满之力注入其中，加速它们生长，重建这片荒芜之地。",al={"为什么收集盖亚之种","谁想要盖亚之种","为什么有人想要盖亚之种"}}},fp="9,162,18.243.0,28.359.1,27.103.0,29.172.0,39.167.0,29.103.0"}
P.entries["item:gaffer-jack"] = {n="小齿轮",s="奥伯丁近海的小齿轮零件沉在黑海岸的波涛之下。维兹班恩·曲针在渡海途中丢失了整整一箱。",h="奥伯丁近海的小齿轮零件沉在黑海岸的波涛之下。维兹班恩·曲针在渡海途中丢失了整整一箱。",kw={"奥伯丁","黑海岸","钓鱼","小齿轮","铁炉堡","斯廷勒·钉扣","维兹班恩·曲针"},ang={["profession:Engineering"]="身为工程师，你知道丢失小齿轮这样的专用零件有多令人懊恼。没有它们，stintle pegs这样的精密机构就无法校准。",["race:Gnome"]="身为侏儒，你也许觉得离开铁炉堡，去奥伯丁过清静日子有些不合常理。但喝得太多，把整箱必需的零件从船舷上掉进海里，就是另一回事了。"},sec={{t="海上遗失",b="侏儒工匠维兹班恩·曲针搭船前往奥伯丁，想远离铁炉堡的锻造车间和酒馆，寻求清静。航行途中，他喝得太多，失手将整箱小齿轮从栏杆上掉进了海里。这些小小的紧固件沉入黑海岸的近海水域，让维兹班恩·曲针没了调校螺栓所需的零件。"},{t="打捞沉物",b="小齿轮沉在黑海岸沿岸的浪涛之中，耐心的渔夫有时能用鱼钩钩到它们。找回这些零件，维兹班恩·曲针就能组装他那些古怪的装置。在茫茫大海中寻找细小的金属零件，需要耐心和运气。"}},faq={{q="小齿轮有什么用途？",a="维兹班恩·曲针需要用小齿轮来调校他那些实验性发明中的调节栓。",al={"小齿轮用途","小齿轮有什么作用","小齿轮用处"}},{q="这些东西怎么会掉进奥伯丁周围的海里？",a="维兹班恩·曲针从东部王国乘船出发，想远离铁炉堡，寻求清静。他在航行途中喝得太多，不慎将整箱小齿轮掉进了黑海岸的海里。",al={"小齿轮为什么在水里","谁弄掉了小齿轮","小齿轮遗失"}},{q="谁想找回小齿轮？",a="维兹班恩·曲针是一位暂住奥伯丁的古怪侏儒发明家，他想找回八个小齿轮，好继续制造他那些奇怪的发明。",al={"谁需要小齿轮","小齿轮交付","谁收小齿轮"}},{q="哪里能找到小齿轮？",a="小齿轮沉在黑海岸沿岸的水下。垂钓者在岸边的浪涛中钓鱼时，有时会钩到它们。",al={"哪里获取小齿轮","如何找到小齿轮","小齿轮位置"}}},fp="11,130,11.333.0,14.253.0,31.95.0,51.206.0,33.152.0,32.112.0"}
P.entries["item:gallywix-s-head"] = {n="加里维克斯的头颅",s="在奥格瑞玛，加里维克斯的头颅证明一名荆棘谷地精监工已被处决。碎手氏族要求用这件战利品作为击杀的凭证。",h="在奥格瑞玛，加里维克斯的头颅证明一名荆棘谷地精监工已被处决。碎手氏族要求用这件战利品作为击杀的凭证。",kw={"贫瘠之地","加里维克斯","奥格瑞玛","普兹克","碎手氏族","申苏尔","淤泥沼泽","风险投资公司"},ang={["class:Rogue"]="作为潜行者，取回加里维克斯的头颅，便向碎手氏族证明了你在秘密渗透、潜行和定点刺杀方面的致命本领。",["faction:Horde"]="作为部落的一员，你协助遏制荆棘谷地精为牟利而进行的工业扩张，这些行动正威胁着贫瘠之地和杜隆塔尔的边境。"},sec={{t="铲除目标的血腥凭证",b="大工头普兹克·加里维克斯在淤泥沼泽以北的高塔中指挥荆棘谷地精的工作。消息传来，风险投资公司. 正在策划一项庞大的计划，碎手氏族便派出密探摧毁这处设施。将加里维克斯的头颅带给奥格瑞玛的申苏尔，就能证明这名监工已被处决，并巩固这名潜行者在公会中的地位。"},{t="突袭淤泥沼泽",b="夺取加里维克斯头颅的命令还要求带回被盗的赞吉尔的改良药剂，并杀光塔中中毒的人员。密探在加里维克斯盘踞的塔顶将他刺杀，再把他的头颅带回暗影裂口。这一行动证实，荆棘谷地精在贫瘠之地的宏大计划已被挫败。"}},faq={{q="这是谁的头颅？",a="这颗头颅属于大工头普兹克·加里维克斯。他是一名地精主管，负责监督荆棘谷地精在贫瘠之地北部淤泥沼泽的行动。",al={"加里维克斯 是谁","普兹克·加里维克斯","加里维克斯 头颅来历"}},{q="谁想要加里维克斯的头颅？",a="申苏尔想要加里维克斯的头颅。他是奥格瑞玛暗影裂口的潜行者训练师，也是碎手氏族的密探。",al={"头颅交给谁","交付加里维克斯的头颅","申苏尔 头颅"}},{q="碎手氏族为什么要他死？",a="普兹克·加里维克斯掌管着淤泥沼泽以北的荆棘谷地精高塔，风险投资公司. 正在那里策划一项庞大的计划。他还将最后一批赞吉尔的改良药剂藏在自己的锁箱中。碎手氏族将他列为刺杀目标，以瓦解这项行动并夺取药剂。",al={"为什么杀 加里维克斯","刺杀 加里维克斯 的原因"}},{q="普兹克·加里维克斯在哪里？",a="普兹克·加里维克斯就在荆棘谷地精高塔的最顶层，高塔位于贫瘠之地北部，紧邻淤泥沼泽以北。",al={"加里维克斯 在哪里","加里维克斯 位置","淤泥沼泽高塔首领"}}},fp="15,144,27.371.0,24.322.1,19.152.0,26.119.0,42.285.0,32.117.0"}
P.entries["item:galvanized-horn"] = {n="光滑的奇美拉角",s="在焦炭谷，铸甲师寻找奇美拉族母身上的光滑的奇美拉角。这些坚硬的角被用来制作战士专用的护甲。",h="在焦炭谷，铸甲师寻找奇美拉族母身上的光滑的奇美拉角。这些坚硬的角被用来制作战士专用的护甲。",kw={"焦炭谷","奇美拉族母","烈火淬炼的锁甲","弗伦·长须","光滑的奇美拉角","奥姆·石蹄","石爪山脉"},ang={["class:Warrior"]="身为战士，杀死一头族母并取得它的光滑的奇美拉角，是对你耐力与力量的考验。这能向暴风城或雷霆崖的铸甲大师证明你的实力。",["profession:Blacksmithing"]="身为铁匠，你能从这种角看出，在极端环境中硬化的有机材料，用于加固定制护甲时，可以媲美甚至超越经过加工的金属。"},sec={{t="焦炭谷的战利品",b="奇美拉族母在石爪山脉的焦炭谷游荡。灰烬、烈焰与求生的磨砺让它们的角变得坚硬。年幼的奇美拉只能提供脆弱、焦黑的角，而族母的角却像经过处理的金属一样坚固。暴风城的弗伦·长须和雷霆崖的奥姆·石蹄各自需要一只这样的角，既用它考验战士的勇武，也用它打造精良的锁甲。"}},faq={{q="光滑的奇美拉角从何而来？",a="光滑的奇美拉角来自石爪山脉西部焦炭谷中的奇美拉族母。",al={"光滑的奇美拉角哪里获得","光滑的奇美拉角如何获得","光滑的奇美拉角掉落"}},{q="铁匠为什么需要这种角？",a="铸甲大师看重这种角的致密质地与耐热性。他们用它来加固特制的锁甲和板甲。",al={"光滑的奇美拉角有什么用","光滑的奇美拉角用途"}},{q="谁收取光滑的奇美拉角？",a="暴风城的弗伦·长须需要这种角，为联盟战士制作经烈火淬炼的护甲。雷霆崖的奥姆·石蹄需要它作为力量的证明，并用它为部落战士打造头盔。",al={"谁需要光滑的奇美拉角","光滑的奇美拉角交给谁"}},{q="它与普通的烧焦的奇美拉角有什么区别？",a="普通的烧焦的奇美拉角来自较弱的年幼奇美拉。光滑的奇美拉角则来自成熟的族母，质地更致密，经过淬炼，适合用来打造精工装备。",al={"烧焦的奇美拉角与光滑的奇美拉角对比","与烧焦的奇美拉角有区别吗"}}},fx={["39b0e048"]={q="光滑的奇美拉角是什么？",a="光滑的奇美拉角是一种罕见而坚硬的角，取自栖息在卡利姆多石爪山脉中的雌奇美拉。与普通的奇美拉角不同，它经受了焦炭谷遭烈火摧残的恶劣环境的锤炼，因而格外坚韧，备受联盟和部落双方护甲大师的珍视。",al={"光滑的奇美拉角是什么","什么是光滑的奇美拉角","光滑的奇美拉角背景"}}},fp="15,140,26.367.0,39.107.0,38.131.0,32.205.0,47.173.0"}
P.entries["item:gargantuan-tumor"] = {n="巨大的瘤",s="在泰达希尔，奥拉密斯湖畔受到腐化的林精奥肯斯古尔身上，一块巨大的瘤被撕了下来。这块瘤见证了疾病在当地生物之间的蔓延。",h="在泰达希尔，奥拉密斯湖畔受到腐化的林精奥肯斯古尔身上，一块巨大的瘤被撕了下来。这块瘤见证了疾病在当地生物之间的蔓延。",kw={"腐化","巨大的瘤","奥拉密斯湖","奥肯斯古尔","泰达希尔","林精"},ang={["class:Druid"]="作为照料泰达希尔幼嫩枝干的德鲁伊，你能从这块瘤看出，这里的自然在腐化面前是多么脆弱。",["race:NightElf"]="作为暗夜精灵，你看到一位受人敬重的林精长者沦为疯狂、染病的怪物，这预示着你的新家园正面临种种困境。"},sec={{t="湖畔的疫病",b="奥肯斯古尔潜伏在奥拉密斯湖南岸附近的一处洞穴中。它曾是一位高贵的林精长者，如今却染上了恶疾。一块巨大的瘤毒害了奥肯斯古尔，扭曲了它的行为，还将污秽传播给周围的野生生物。为了终止这头野兽的肆虐，也让当地的研究者有机会检验这种疫病，人们切下了这块瘤。他们希望查明，这种疾病是如何在新生的世界之树枝干间扎根的。"}},faq={{q="巨大的瘤来自哪里？",a="巨大的瘤来自奥肯斯古尔，它是一只受到腐化的大型林精，栖身于泰达希尔奥拉密斯湖南岸的一处洞穴中。",al={"瘤的来源","如何获得巨大的瘤","奥肯斯古尔掉落"}},{q="是什么导致奥肯斯古尔身上长出了瘤？",a="这块瘤是那股奇异腐化的外在征兆，这股腐化正在毒害奥拉密斯湖周围的林精和野生生物。奥肯斯古尔曾是族群中威严的领袖，却最终被这块瘤击垮。",al={"奥肯斯古尔为什么长瘤","林精的疾病","奥拉密斯湖的腐化"}},{q="谁想研究这块瘤？",a="当地的调查者想用这块瘤研究侵害当地林精的奇异腐烂病症，并找出治疗或遏制这种疫病的方法。",al={"谁收这块瘤","交付巨大的瘤","奥肯斯古尔任务交付"}}},fp="16,140,20.455.0,42.131.0,48.171.0,30.121.0"}
P.entries["item:garrick-s-head"] = {n="加瑞克的头颅",s="在北郡农场，加瑞克·帕德弗特被砍下的头颅证明这个恶徒已经毙命。北郡修道院的当局要求先交上这颗头颅，才肯支付赏金。",h="在北郡农场，加瑞克·帕德弗特被砍下的头颅证明这个恶徒已经毙命。北郡修道院的当局要求先交上这颗头颅，才肯支付赏金。",kw={"赏金","维里副队长","艾尔文森林","加瑞克·帕德弗特","加瑞克的头颅","北郡修道院","北郡山谷"},ang={["class:Rogue"]="身为潜行者，除掉帕德弗特能让当地的恶棍明白，拦路抢劫会招来训练有素的致命刀锋。",["race:Human"]="身为人类，取下帕德弗特的头颅，是对艾尔文森林中日渐猖獗的不法之徒打出的早期一击。"},sec={{t="匪徒的末路",b="几个星期以来，加瑞克·帕德弗特和他的团伙不断骚扰北郡山谷的农民与商人。暴风城的防御兵力捉襟见肘，当地卫兵又忙于应付狗头人和迪菲亚匪徒。于是，加瑞克藏身于农场附近的一间棚屋，劫掠过往商旅。维里副队长悬赏缉拿这个亡命之徒，寻找能杀死他并带回凭证的人。"}},faq={{q="加瑞克·帕德弗特是谁？",a="加瑞克·帕德弗特是个凶徒，曾让北郡山谷的农民、农场工人和往来商人惶惶不安。他和团伙在北郡修道院以东的河对岸设立了一处据点。",al={"加瑞克 是谁","加瑞克·帕德弗特 的故事","帕德弗特 是谁"}},{q="为什么领取赏金需要一颗砍下的头颅？",a="维里副队长和北郡当局要求先拿到 加瑞克 已死的凭证，才会支付赏金。",al={"为什么要他的头颅","死亡凭证","为什么要取下加瑞克的头颅"}},{q="加瑞克·帕德弗特藏在哪里？",a="帕德弗特藏在北郡修道院以东的一间小木屋里，过了河桥就能找到，离北郡农场不远。",al={"加瑞克 在哪里","加瑞克 的棚屋位置","在哪里找到 加瑞克·帕德弗特"}},{q="谁支付加瑞克的头颅的赏金？",a="维里副队长发布了悬赏，收到加瑞克的头颅后便会支付赏金。他就驻守在北郡修道院入口外。",al={"谁要加瑞克的头颅","交付加瑞克的头颅","谁交了加瑞克的头颅"}}},fx={cb1a40d1={q="加瑞克的头颅是什么？",a="这颗被割下的头颅，是加瑞克·帕德弗特已经毙命的骇人铁证，这个臭名昭著的恶徒曾在北郡山谷各处恐吓当地农民和商人。将这件战利品带回修道院，就能证实他的强盗团伙已经失去了头目。",al={"什么是加瑞克的头颅","加瑞克的头颅物品","这颗头颅属于谁"}},["79b2de99"]={q="加瑞克的头颅从何而来？",a="它直接取自加瑞克·帕德弗特本人。这个盗贼在河流东岸、北郡农场附近的一间小屋里扎营，身边围着一群忠心耿耿的打手，守护着他掠夺来的财物。",al={"哪里获得加瑞克的头颅","谁掉落加瑞克的头颅","加瑞克的头颅来源"}}},fp="14,162,14.369.0,24.197.0,51.103.0,33.116.0,39.134.0"}
P.entries["item:gazlowe-s-ledger"] = {n="加兹鲁维的账本",s="一批来自藏宝海湾的货物失踪后，加兹鲁维在棘齿城将自己的贸易记录与港口货单逐一核对。",h="一批来自藏宝海湾的货物失踪后，加兹鲁维在棘齿城将自己的贸易记录与港口货单逐一核对。",kw={"藏宝海湾","迪兹维格","海盗","加兹鲁维","账本","棘齿城","货物","热砂"},ang={["class:Rogue"]="身为潜行者，你可以从一位地精老板的私人贸易账本中，窥见贫瘠之地沿岸违禁品与贵重进口货物的流向，以及海盗的活动。",["faction:Horde"]="身为部落的一员，你可以在中立港口棘齿城进行贸易。帮助加兹鲁维追查被盗的货物，能让你与当地的热砂当局保持良好关系。"},sec={{t="棘齿城的商业记录",b="加兹鲁维用一本私人账本记录棘齿城的贸易货物。账本记载了运入的货箱、运出的货物和仓库库存。一批来自藏宝海湾的货物失踪后，加兹鲁维将预期库存与码头管理员迪兹维格保管的码头记录进行核对。"},{t="查明失窃真相",b="加兹鲁维和其他地精将账本与迪兹维格的港口日志进行比对，发现那批货物从未抵达港口仓库。记录之间的出入证实了加兹鲁维的怀疑：货箱在上岸之前就被劫走了。罪魁祸首是附近商旅海岸一带的南海海盗。"}},faq={{q="加兹鲁维的账本是什么？",a="加兹鲁维的账本记载了棘齿城预计收取的货物和现有库存。货物失踪时，加兹鲁维会将账本送到码头，以便将其中的条目与码头记录进行核对。",al={"加兹鲁维的账本","棘齿城账本","加兹鲁维库存账本"}},{q="谁需要检查账本？",a="码头管理员迪兹维格会将加兹鲁维的账本与自己的航运日志进行核对。他负责管理棘齿城的码头，能够查明失踪的货物是放错了地方，还是根本没有卸下船。",al={"账本交给谁","账本接收者","迪兹维格账本"}},{q="账本中缺失的是哪批货物？",a="加兹鲁维正在等待从藏宝海湾运来的最新一批货物。迪兹维格发现自己的日志并无异常，不过他说，有些来自安德麦的货物正等着加兹鲁维领取。",al={"加兹鲁维丢了什么","失踪的货物"}},{q="账本核对完后会怎样？",a="迪兹维格会检查那批货物是否经过码头。他发现货物并未经过码头后，账本便被送回加兹鲁维手中，证实很可能是南海海盗在海上截走了货物。",al={"账本后续去向","迪兹维格检查之后"}}},fp="16,103,28.271.0,20.278.1,25.169.0,32.170.0,37.165.0,41.193.1"}
P.entries["item:gem-of-anacondra"] = {n="安娜科德拉宝石",s="安娜科德拉宝石是哀嚎洞穴内堕落的蛇形首领持有的四颗梦境宝石之一。它由安娜科德拉随身携带，是她已被击败、梦魇在贫瘠之地的蔓延受到遏制的实证。",h="安娜科德拉宝石是哀嚎洞穴内堕落的蛇形首领持有的四颗梦境宝石之一。它由安娜科德拉随身携带，是她已被击败、梦魇在贫瘠之地的蔓延受到遏制的实证。",kw={"梦境宝石","尖牙德鲁伊","安娜科德拉宝石","安娜科德拉","纳拉·蛮鬃","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊而言，取得这颗宝石是一项庄严的职责，意味着必须击败一位将心智与形态都交给腐化的Emerald Nightmare的姐妹。",["race:Tauren"]="取回宝石能直接帮助雷霆崖的纳拉·蛮鬃，消除那些侵扰长者高地Shu'halo睡梦的黑暗幻象。"},sec={{t="腐化的焦点",b="纳拉雷克斯为了让水源与生机重回干旱的贫瘠之地而陷入沉睡时，翡翠梦魇侵入了他的思想，扭曲了他最亲近的弟子。安娜科德拉和她的同谋抛弃了传统，成为尖牙德鲁伊，将恢复生机的崇高使命扭曲为恶毒的妄念。安娜科德拉宝石是这些蛇形首领随身携带的四颗梦境宝石之一，凝聚着他们与翡翠梦境之间受到腐化的联系，并将梦魇锚定在洞穴深处。"},{t="净化幻象",b="纳拉·蛮鬃和雷霆崖的塞纳里奥德鲁伊们发现，自己的睡梦也受到幻象和尖牙首领邪恶面容的侵扰。必须取得安娜科德拉宝石，以及考布莱恩、皮萨斯和瑟芬迪斯的宝石，才能证实安娜科德拉已被击败，让卡利姆多的平衡守护者们摆脱压迫心灵的梦魇。"}},faq={{q="安娜科德拉宝石是什么？",a="这是一颗由安娜科德拉随身携带的梦境宝石，她是盘踞在哀嚎洞穴内、已遭扭曲的尖牙德鲁伊的四名首领之一。",al={"安娜科德拉宝石是什么","安娜科德拉宝石","安娜科德拉宝石有什么用"}},{q="谁在寻找这颗宝石？",a="纳拉·蛮鬃是一位身处雷霆崖长者高地的牛头人德鲁伊，她正在寻找这颗宝石和另外三颗梦境宝石，以摆脱心中的梦魇，保护贫瘠之地。",al={"安娜科德拉宝石交给谁","安娜科德拉宝石在哪里交","安娜科德拉宝石交付"}},{q="在哪里能找到安娜科德拉宝石？",a="这颗宝石由安娜科德拉随身携带，她潜伏在贫瘠之地中部哀嚎洞穴蜿蜒的地下通道中。",al={"哪里掉落","谁掉落安娜科德拉宝石","安娜科德拉位置"}},{q="梦境宝石为何重要？",a="这四颗宝石由尖牙德鲁伊的堕落首领持有。集齐它们便能证实这些头目已被铲除，打破他们对这一地区翡翠梦境腐化的掌控。",al={"为什么需要四颗宝石","梦境宝石的用途","尖牙德鲁伊的宝石"}}},fx={["2e0de493"]={q="安娜科德拉宝石来自哪里？是谁制作的？",a="安娜科德拉在哀嚎洞穴深处携带着这颗宝石。虽然不知道具体是哪位大师切割或附魔了它，但它是尖牙德鲁伊四位首领持有的梦境宝石之一。这些堕落的暗夜精灵曾属于一个致力于治愈贫瘠之地的高贵团体，如今却将他们对翡翠梦境的扭曲幻象注入这些石头。",al={"安娜科德拉宝石的来历","谁制作了安娜科德拉宝石","安娜科德拉从哪里得到宝石"}}},fp="16,175,17.541.0,20.369.1,29.153.0,19.180.0,40.112.0,33.201.0"}
P.entries["item:gem-of-cobrahn"] = {n="考布莱恩宝石",s="考布莱恩宝石是考布莱恩携带的一颗梦境宝石，他是哀嚎洞穴中尖牙德鲁伊的堕落首领之一。它既是他腐化梦境的焦点，也是纳拉·蛮鬃确认他已被击败所需的实物凭证。",h="考布莱恩宝石是考布莱恩携带的一颗梦境宝石，他是哀嚎洞穴中尖牙德鲁伊的堕落首领之一。它既是他腐化梦境的焦点，也是纳拉·蛮鬃确认他已被击败所需的实物凭证。",kw={"梦境宝石","尖牙德鲁伊","考布莱恩宝石","考布莱恩","纳拉·蛮鬃","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊而言，取回考布莱恩宝石意味着一位堕落同胞迎来了悲惨却必要的终结，他为了Emerald Nightmare而背弃了自然的和谐。",["race:Tauren"]="雷霆崖的德鲁伊密切关注着贫瘠之地；夺取考布莱恩的宝石，能直接保护平原和猎场免遭非自然的腐化。"},sec={{t="腐化梦境的焦点",b="暗夜精灵德鲁伊纳拉雷克斯进入翡翠梦境，试图让卡利姆多荒芜的平原重获生机，但他的噩梦却扭曲了哀嚎洞穴和他的弟子。其中就有考布莱恩，他抛弃了塞纳里奥议会的和平之道，化身为蛇。考布莱恩携带着四颗梦境宝石中的一颗，这些宝石维系着首领们对地下水道的控制，而他借此引导扭曲的梦境，威胁着要将贫瘠之地变成一片毒沼。"},{t="恢复平衡",b="在雷霆崖，牛头人德鲁伊纳拉·蛮鬃饱受叛离正道的尖牙德鲁伊送来的噩梦折磨。为了净化地下泉水，保护卡利姆多免遭他们的愿景侵害，冒险者必须深入洞穴，杀死考布莱恩和他的三名同谋，并取回他们的梦境宝石。将考布莱恩的宝石交还给塞纳里奥德鲁伊，便能终结他对沉睡中的纳拉雷克斯施加的腐化影响。"}},faq={{q="考布莱恩宝石是什么？",a="它是考布莱恩持有的一颗梦境宝石，这名堕落的德鲁伊在哀嚎洞穴中领导着尖牙德鲁伊。它是他那被噩梦扭曲的力量的导体。",al={"考布莱恩宝石","考布莱恩宝石是什么"}},{q="谁想要考布莱恩宝石？",a="纳拉·蛮鬃是一名位于雷霆崖长者高地的牛头人德鲁伊，她要求收集这颗宝石和另外三颗宝石，以终结尖牙德鲁伊。",al={"谁需要考布莱恩宝石","考布莱恩宝石交付","谁收取考布莱恩宝石"}},{q="完成任务需要多少颗宝石？",a="需要四颗宝石：考布莱恩宝石、安娜科德拉宝石、皮萨斯宝石和瑟芬迪斯宝石，分别由洞穴中的四名毒蛇首领持有。",al={"梦境宝石数量","尖牙德鲁伊宝石","全部尖牙宝石"}},{q="考布莱恩是谁？",a="考布莱恩曾是纳拉雷克斯的弟子。当纳拉雷克斯的愿景变成噩梦时，考布莱恩和其他几名德鲁伊选择化身为蛇，组建了尖牙德鲁伊。",al={"考布莱恩是谁","考布莱恩的故事","考布莱恩"}}},fp="14,123,27.439.0,17.357.1,27.116.0,29.138.0,47.172.0,20.172.0"}
P.entries["item:gem-of-pythas"] = {n="皮萨斯宝石",s="皮萨斯宝石是四颗被腐化的梦境宝石之一，由哀嚎洞穴内的尖牙德鲁伊首领们持有。它由皮萨斯保管，为扭曲地下绿洲、威胁贫瘠之地的梦魇提供力量。",h="皮萨斯宝石是四颗被腐化的梦境宝石之一，由哀嚎洞穴内的尖牙德鲁伊首领们持有。它由皮萨斯保管，为扭曲地下绿洲、威胁贫瘠之地的梦魇提供力量。",kw={"贫瘠之地","梦境宝石","尖牙德鲁伊","皮萨斯宝石","皮萨斯","纳拉·蛮鬃","哀嚎洞穴"},ang={["class:Druid"]="对塞纳里奥德鲁伊而言，取回这颗宝石是一项沉重的职责，因为它象征着纳拉雷克斯的核心追随者已彻底堕落，化作蛇形的恐怖怪物。",["race:Tauren"]="洞穴中扭曲的仪式威胁着贫瘠之地脆弱的平衡，因此，取回这些宝石对保护萨满祭司和德鲁伊的家园至关重要。"},sec={{t="梦魇的容器",b="纳拉雷克斯进入翡翠梦境，意图让干旱的贫瘠之地重获生机，他的崇高愿景却被扭曲成了活生生的梦魇。他最重要的追随者也随他一同堕落，自称尖牙德鲁伊，企图将地表世界改造成剧毒的丛林。皮萨斯携带着这颗共鸣之石，它是将腐化之力锚定在洞穴中的四颗梦境宝石之一。这颗宝石是他们黑暗图谋的媒介，也向雷霆崖的德鲁伊证明，皮萨斯扭曲的梦境终于被打破了。"}},faq={{q="皮萨斯宝石有什么用途？",a="这颗宝石要与考布莱恩、安娜科德拉和瑟芬迪斯的宝石一同交给雷霆崖的纳拉·蛮鬃。集齐这些宝石，就能完成铲除尖牙德鲁伊叛变首领的任务。",al={"皮萨斯宝石用途","皮萨斯宝石怎么用","皮萨斯宝石任务"}},{q="谁携带着这颗宝石？",a="它由皮萨斯持有，这位堕落的暗夜精灵德鲁伊栖身于贫瘠之地的哀嚎洞穴深处。",al={"谁掉落皮萨斯宝石","皮萨斯位置","哪里获取皮萨斯宝石"}},{q="雷霆崖的德鲁伊为何想要这颗宝石？",a="哀嚎洞穴散发的腐化之力令纳拉·蛮鬃和雷霆崖的塞纳里奥德鲁伊深感不安。取得这些宝石，就能证明四名畸变的首领已被击杀，阻止梦魇进一步渗入贫瘠之地。",al={"纳拉 为什么要宝石","纳拉·蛮鬃 皮萨斯"}},{q="还有其他类似的宝石吗？",a="有。皮萨斯是四名首领之一。其余三位——安娜科德拉、考布莱恩和瑟芬迪斯——也各自携带着一颗梦境宝石，藏身于洞穴深处。",al={"其他梦境宝石","尖牙 宝石","哀嚎洞穴宝石"}}},fx={["3d8d64d3"]={q="皮萨斯宝石是什么？",a="皮萨斯宝石是哀嚎洞穴中尖牙德鲁伊首领携带的四颗梦境宝石之一。这件遗物由皮萨斯领主持有，承载着腐化这些昔日高贵暗夜精灵的黑暗蛇形疯狂，将他们对翡翠梦境的扭曲幻象凝为实体。",al={"皮萨斯宝石","皮萨斯宝石是什么","这是什么宝石"}}},fp="13,170,25.468.0,35.195.0,21.114.0,48.234.0,35.134.0"}
P.entries["item:gem-of-serpentis"] = {n="瑟芬迪斯宝石",s="瑟芬迪斯宝石是由哀嚎洞穴中尖牙德鲁伊的四位首领之一，瑟芬迪斯所携带的一颗梦境宝石。它是重塑洞穴网络并威胁着贫瘠之地的扭曲梦魇的焦点媒介。",h="瑟芬迪斯宝石是由哀嚎洞穴中尖牙德鲁伊的四位首领之一，瑟芬迪斯所携带的一颗梦境宝石。它是重塑洞穴网络并威胁着贫瘠之地的扭曲梦魇的焦点媒介。",kw={"尖牙德鲁伊","瑟芬迪斯宝石","尖牙德鲁伊首领","瑟芬迪斯","纳拉·蛮鬃","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="瑟芬迪斯和他的团伙所携带的梦境宝石，代表了在没有警惕的精神约束下与梦境进行深度恍惚交流所带来的可怕风险。",["race:Tauren"]="切断瑟芬迪斯对这颗宝石的控制，有助于将雷霆崖的萨满祭司和德鲁伊从扰乱他们莫高雷睡眠的黑暗幻象中解救出来。"},sec={{t="蛇形梦境之心",b="当纳拉雷克斯在哀嚎洞穴中的沉睡被翡翠梦魇吞噬时，他最忠诚的追随者们被扭曲成了狂热的尖牙德鲁伊。瑟芬迪斯是这伙人的四位首领之一。和其他三人一样，瑟芬迪斯携带一颗附魔的梦境宝石，将他们的集体意志锚定在这扭曲的幻象上。回收这颗宝石可以打破瑟芬迪斯对洞穴生态系统的控制，直接打击那些指挥着在贫瘠之地蔓延的腐化的首领。"},{t="雷霆崖的证明",b="雷霆崖长者高地上的牛头人德鲁伊，特别是纳拉·蛮鬃，饱受潜伏在草原之下的腐化所引起的梦魇的折磨。回收瑟芬迪斯宝石，以及考布拉恩、安娜科德拉和皮萨斯的宝石，提供了确凿的证据，证明这个堕落教派的首领们已经倒下，从而减轻了梦魇对莫高雷的塞纳里奥议会的控制。"}},faq={{q="瑟芬迪斯宝石从哪里来？",a="这颗宝石由瑟芬迪斯携带，他是尖牙德鲁伊的四位首领之一，居住在哀嚎洞穴蜿蜒的水道深处。",al={"瑟芬迪斯宝石掉落者","如何获得瑟芬迪斯宝石","瑟芬迪斯宝石位置"}},{q="这颗宝石有什么用途？",a="它是尖牙德鲁伊的首领们用来引导扭曲地下绿洲的梦魇的四颗焦点宝石之一。雷霆崖的纳拉·蛮鬃寻找它作为瑟芬迪斯已被击败的证明。",al={"为什么要收集瑟芬迪斯宝石","瑟芬迪斯宝石用途"}},{q="谁需要全部四颗梦境宝石？",a="驻扎在雷霆崖长者高地的德鲁伊纳拉·蛮鬃，请求冒险者为她带回考布拉恩、安娜科德拉、皮萨斯和瑟芬迪斯的宝石，以切断梦魇对该地区的控制。",al={"谁需要这些宝石","瑟芬迪斯宝石任务提交","尖牙德鲁伊首领任务提交"}},{q="携带这颗宝石之前的瑟芬迪斯是谁？",a="他最初是纳拉雷克斯的学徒，进入洞穴的目的是为了让贫瘠之地恢复生机，但翡翠梦魇将他崇高的抱负扭曲成了以蛇的形态重塑世界的狂热渴望。",al={"瑟芬迪斯背景故事","瑟芬迪斯是谁"}}},fx={["58ca37b7"]={q="瑟芬迪斯宝石是什么？",a="瑟芬迪斯宝石是哀嚎洞穴中尖牙德鲁伊首领持有的四颗梦境宝石之一。它由瑟芬迪斯领主亲自携带，是堕落德鲁伊的象征与工具；他们妄图将贫瘠之地扭曲成符合其黑暗幻象的模样。",al={"瑟芬迪斯宝石背景","瑟芬迪斯的宝石是什么","瑟芬迪斯领主的宝石"}}},fp="16,191,29.465.0,23.330.1,42.139.0,31.209.0,30.208.0,48.207.0"}
P.entries["item:gerenzo-s-mechanical-arm"] = {n="格雷苏的机械臂",s="在石爪山脉，地精干员在铲除竞争对手的同时，也在寻找格雷苏的机械臂作为凭证。这条从叛逆工程师格雷苏身上取下的移植肢体，是他死亡的证明。",h="在石爪山脉，地精干员在铲除竞争对手的同时，也在寻找格雷苏的机械臂作为凭证。这条从叛逆工程师格雷苏身上取下的移植肢体，是他死亡的证明。",kw={"手臂","峭壁湖","格雷苏","机械臂","斯布特瓦夫","石爪山","扳哨","菲兹克斯"},ang={["profession:Engineering"]="这条手臂展现了两种不同的工程传统。侏儒愿意牺牲自身的血肉之躯来换取机械的精密，而地精则偏爱外部加装和强大火力。",["race:Gnome"]="格雷苏代表了侏儒创造力一个可怕的极端，将机械替换远远推向常规医用义肢之外，变成了病态的自我改造。"},sec={{t="离奇的发明",b="在峭壁湖上方，叛逆工程师格雷苏将嗡嗡作响的齿轮和金属移植到自己日渐衰败的身体上。这个离经叛道的侏儒用精密机械替换了自己的血肉肢体。地精工匠菲兹克斯想除掉格雷苏，好给上司留下深刻印象，而这条独特的机械臂正是他需要的战利品，足以确凿证明这名工程师已经死亡。"},{t="侏儒的理念，地精的批评",b="菲兹克斯觉得，砍掉一条完好的手臂，再装上机械替代品，实在没什么道理。他说，合格的地精工程师会保留两条血肉手臂，再装上第三条机械臂。尽管双方的工程理念存在分歧，交付这条断臂仍能让斯布特瓦夫满意，也有助于菲兹克斯申请调往加基森或安德麦。"}},faq={{q="格雷苏的机械臂从何而来？",a="这条手臂来自格雷苏，他在石爪山脉峭壁湖上方高处的水车附近，监管伐木和工程作业。",al={"谁掉落格雷苏的手臂","格雷苏的手臂位置","哪里获得格雷苏的机械臂"}},{q="菲兹克斯为什么想要这条手臂？",a="菲兹克斯需要向上司斯布特瓦夫证明格雷苏已经死了。格雷苏独特的义肢无法伪造，也不可能被误认成别人的手臂。",al={"菲兹克斯为什么要手臂","手臂任务交付","格雷苏死亡的证据"}},{q="格雷苏为什么要替换自己的手臂？",a="菲兹克斯说，格雷苏的血肉似乎正在腐烂。出于绝望，或是对侏儒实验的痴迷，格雷苏将机械移植到自己身上，用机械肢体替换了日渐衰败的血肉肢体。",al={"格雷苏为什么是半机械人","格雷苏腐烂的血肉","为什么用机械臂"}}},fx={["379afa91"]={q="格雷苏的机械臂是什么？",a="这是一条粗糙的赛博义肢，直接移植在格雷苏·扳哨的身上。他是一个患病的侏儒监工，潜伏在峭壁湖上方的水车附近。格雷苏没有保留自然血肉，而是用发条齿轮和金属护板改造了腐烂的躯体，这条精巧的机械肢体也因此成为他最显眼的特征。",al={"格雷苏的手臂是什么","格雷苏的手臂物品","格雷苏的机械臂"}}},fp="24,189,19.329.0,35.317.1,46.165.0,35.157.0,36.221.0"}
P.entries["item:ghost-hair-comb"] = {n="幽灵的梳子",s="伊瓦夫人将幽灵的梳子送给盲眼玛丽，她独自住在暮色森林边缘。梳子勾起了悲伤，也留下了幽灵的头发，供艾瓦纺成线。",h="伊瓦夫人将幽灵的梳子送给盲眼玛丽，她独自住在暮色森林边缘。梳子勾起了悲伤，也留下了幽灵的头发，供艾瓦纺成线。",kw={"盲眼玛丽","夜色镇","暮色森林","幽灵的梳子","幽灵的发丝","伊瓦夫人"},ang={["class:Priest"]="身为牧师，你能从玛丽痛苦地拒绝梳子的举动中，听出凡人的虚荣与灵魂深处的折磨，这在暮色森林不得安息的亡者中并不陌生。",["profession:Tailoring"]="身为裁缝，你能看出缠在梳齿间的发丝是一种诡异的纺织材料。它们由幽灵的悲伤纺成，原料并非羊毛或蚕丝。"},sec={{t="可悲的虚荣",b="夜色镇的伊瓦夫人将幽灵的梳子送给盲眼玛丽，她独自住在暮色森林边缘一间破败的屋子里。一见到梳子，这个幽灵便惊恐地退缩。她必须面对一个事实：自己已不再是记忆中那个美丽鲜活的女子。玛丽悲痛万分，将梳子猛地推开，几缕幽灵般的头发缠在了梳齿间。"},{t="悲伤纺成的线",b="伊瓦夫人在夜色镇收回幽灵的梳子时，梳齿间仍缠着盲眼玛丽的幽灵发丝。艾瓦收集这些纤细的发丝，将它们纺成幽灵的发丝。这种线是一种神秘的材料，用于缝合和捆扎暮色森林阴影之境中的秘术造物。"}},faq={{q="幽灵的梳子是什么？",a="夜色镇的伊瓦夫人将幽灵的梳子送给幽灵盲眼玛丽。梳子挂住了玛丽的几缕幽灵头发，艾瓦将它们纺成幽灵的发丝。",al={"幽灵的梳子","这把梳子是什么","艾瓦的梳子"}},{q="盲眼玛丽为什么尖叫并拒绝梳子？",a="盲眼玛丽拒绝梳子，是因为它让她想起了自己失去的凡人美貌。它迫使她面对如今的自己：一个可怕的幽灵怪物，而非记忆中生前那个美丽的女子。",al={"盲眼玛丽为什么尖叫","盲眼玛丽对梳子的反应","玛丽为什么扔掉梳子"}},{q="谁需要收回梳子？",a="住在夜色镇的占卜师兼民间法师伊瓦夫人要求归还幽灵的梳子，以便收集缠在上面的幽灵头发。",al={"谁要梳子","梳子送到哪里","梳子还给谁"}},{q="幽灵的头发有什么用途？",a="伊瓦夫人将幽灵的头发纺成幽灵的发丝，这种特殊材料用于暮色森林的秘术仪式和物品制作。",al={"幽灵头发的用途","幽灵的发丝是什么","幽灵的发丝的用途"}}},fp="15,113,15.349.0,16.279.1,28.162.0,47.204.0,28.134.0,32.135.0"}
P.entries["item:ghost-hair-thread"] = {n="幽灵的发丝",s="在夜色镇，伊瓦夫人从灵魂世界纺出幽灵的发丝。它蕴含的神秘力量能够束缚灵魂，或将生命缝入无生命之物。亚伯克隆比请求用它保护自己的小屋，抵御躁动不安的幽灵。",h="在夜色镇，伊瓦夫人从灵魂世界纺出幽灵的发丝。它蕴含的神秘力量能够束缚灵魂，或将生命缝入无生命之物。亚伯克隆比请求用它保护自己的小屋，抵御躁动不安的幽灵。",kw={"亚伯克隆比","夜色镇","暮色森林","幽灵的发丝","伊瓦夫人","乌鸦岭","灵魂"},ang={["class:Warlock"]="身为术士，你或许能从操纵灵魂与束缚构造体的黑暗法术中，认出这种丝线束缚灵魂、赋予无生命物质以生命的力量。",["profession:Tailoring"]="裁缝通常使用毛料、丝绸和魔纹布。伊瓦夫人的幽灵丝线表明，布料也能由超自然精华纺成，并承载魔法。"},sec={{t="纺自灵魂世界",b="伊瓦夫人在夜色镇纺制幽灵的发丝，当地人都知道它具有奇异的力量。艾瓦说，这缕幽魂丝线能够束缚邪恶的灵魂，或将活力缝入无生命的物体。在暮色森林，它可用于仪式和防护结界。"},{t="亚伯克隆比的防护",b="亚伯克隆比住在乌鸦岭墓地北边不远处的一间破旧小屋里。这位隐士请求旅人为他从夜色镇带来幽灵的发丝。他说，他需要将丝线拉在窗户和门框上，阻止游荡的亡灵进入家中。这丝线还能做些什么呢？"}},faq={{q="幽灵的发丝是什么？",a="伊瓦夫人在夜色镇纺制幽灵的发丝。它蕴含的神秘力量能够束缚灵魂，或将生命缝入无生命之物。",al={"幽灵发丝","幽灵的发丝是什么","幽灵丝线"}},{q="亚伯克隆比为什么想要幽灵的发丝？",a="亚伯克隆比说，他需要将幽灵的发丝拉在窗户和门口，抵御乌鸦岭墓地附近躁动不安的灵魂。",al={"亚伯克隆比丝线","亚伯克隆比为什么想要丝线","亚伯克隆比防护"}},{q="谁制作这种丝线？",a="夜色镇的占卜师伊瓦夫人纺制这种丝线，并应请求提供。",al={"谁纺制幽灵的发丝","伊瓦夫人丝线"}},{q="玩家能用这种丝线进行裁缝制作吗？",a="不能。幽灵的发丝不能用于常规裁缝配方；它是为亚伯克隆比准备的。",al={"裁缝幽灵的发丝","幽灵的发丝能用于制作吗"}}},fp="17,214,24.220.0,18.290.1,26.120.0,44.129.0,21.86.0,41.96.0"}
P.entries["item:ghoul-fang"] = {n="食尸鬼的牙齿",s="在暮色森林，人们从亡灵身上收集食尸鬼的牙齿，供伊瓦夫人制作护身符。在夜色镇，旅人们面对着森林中不断逼近的黑暗，这些牙齿是她施展法术不可或缺的材料。",h="在暮色森林，人们从亡灵身上收集食尸鬼的牙齿，供伊瓦夫人制作护身符。在夜色镇，旅人们面对着森林中不断逼近的黑暗，这些牙齿是她施展法术不可或缺的材料。",kw={"夜色镇","暮色森林","食尸鬼的牙齿","食尸鬼","伊瓦夫人","惩罚图腾","亡灵"},ang={["faction:Alliance"]="对于援助饱受围困的夜色镇的联盟冒险者而言，收集这些牙齿，就是将暮色森林中的恐怖之物化为求生的工具，抵御不断蔓延、如同Scourge侵染一般的污秽。"},sec={{t="The Restless Dead的战利品",b="饥肠辘辘的亡灵出没于暮色森林阴暗的林地与墓穴。食腐者潜伏在墓地附近，腐烂者则在林间游荡。从这些生物身上取下牙齿是一项可怖的差事，也证明了采集者从威胁夜色镇边界的亡灵手中活了下来。"},{t="秘术材料",b="伊瓦夫人是夜色镇的占卜师与秘术师，她在穿越暮色森林的旅人周围看到了可怕的凶兆。她将食尸鬼的牙齿、骷髅的手指和蜘蛛毒液结合起来，为惩罚图腾施加魔法。这件护符借助森林中的黑暗力量抵御暴力袭击，保护它的持有者。"}},faq={{q="哪里能找到食尸鬼的牙齿？",a="各种食尸鬼出没于暮色森林的墓地与偏僻小径。它们包括瘟疫食尸鬼、食脑者、噬骨者、腐臭的食尸鬼、腐烂者和食腐者。",al={"食尸鬼的牙齿掉落地点","食尸鬼的牙齿掉落怪物","食尸鬼的牙齿位置"}},{q="谁需要食尸鬼的牙齿？",a="夜色镇的秘术师伊瓦夫人需要食尸鬼的牙齿，用于制作防御性的惩罚图腾的仪式。",al={"谁需要食尸鬼的牙齿","食尸鬼的牙齿交付","伊瓦夫人任务"}},{q="伊瓦夫人为什么需要这些牙齿？",a="伊瓦夫人感到危险正在旅人周围聚集。她用这些牙齿、骷髅的手指和蜘蛛毒液为护身图腾施加魔法，惩罚任何攻击其持有者的人。",al={"为什么需要食尸鬼的牙齿","惩罚图腾材料","伊瓦夫人用牙齿做什么"}}},fx={["7c703fef"]={q="食尸鬼的牙齿是什么？",a="食尸鬼的牙齿是从暮色森林中徘徊的不死食尸鬼口中撬下的尖牙。这些牙齿受到死灵腐化和噬肉欲望的污染，仍残留着一丝驱动不死生物的黑暗魔法，因此是制作护身符和进行神秘仪式的强力材料。",al={"食尸鬼的牙齿是什么","食尸鬼的牙齿背景","关于食尸鬼的牙齿"}},["87f3f6fc"]={q="食尸鬼的牙齿来自哪里？",a="这些牙齿来自暮色森林阴影中游荡的各种不死食尸鬼，例如瘟疫散播者、食脑者、啃骨者和食肉者。它们并非人工制作，而是直接从游荡死者的口中搜集而来。",al={"食尸鬼的牙齿来源","食尸鬼的牙齿来自哪里","谁会掉落食尸鬼的牙齿"}}},fp="10,182,29.255.0,15.302.0,31.170.0,22.98.0,30.189.0"}
P.entries["item:ghoul-rib"] = {n="食尸鬼的肋骨",s="在暮色森林，食尸鬼游荡于林间和墓地，亚伯克隆比正在索要它们的肋骨。这位隐士说，他需要用这些肋骨制作一尊塑像，驱赶棚屋附近那些吞食血肉的恐怖怪物。",h="在暮色森林，食尸鬼游荡于林间和墓地，亚伯克隆比正在索要它们的肋骨。这位隐士说，他需要用这些肋骨制作一尊塑像，驱赶棚屋附近那些吞食血肉的恐怖怪物。",kw={"亚伯克隆比","乞丐鬼屋","噬骨者","夜色镇","暮色森林","食腐者","食尸鬼的肋骨","食尸鬼塑像","亡灵"},ang={["class:Paladin"]="处理那些不得安息的亡者遭到亵渎的遗骨，是一项令人心情沉重的工作。帮助一位孤居的隐士对抗饥肠辘辘的恐怖怪物，符合圣骑士在暮色森林守护生者的职责。",["class:Priest"]="让这些骨头重新活动的扭曲力量，显露出笼罩暮色森林的深重阴影，在这里，死去的村民变成了贪婪的食腐怪物。"},sec={{t="骇人的护卫",b="食尸鬼出没于暮色森林，其中有食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼。亚伯克隆比独自住在乌鸦岭墓地北面的一间棚屋里，向旅人索要这些食尸鬼结实而腐烂的肋骨。他说，自己住在夜色镇的守夜人保护范围之外，需要一尊骇人的塑像，将亡灵吓离他的住处。"},{t="棚屋周围的疑云",b="亚伯克隆比索要食尸鬼残骸的请求引人疑窦。他本可以到夜色镇的木栅后寻求庇护，或使用经过祝圣的护符，却坚持收集未经处理的通灵残骸，保护自己那间偏僻的棚屋。"}},faq={{q="哪些生物身上有食尸鬼的肋骨？",a="食尸鬼的肋骨来自暮色森林中的多种食尸鬼，包括食腐者、噬骨者、食脑者、腐烂者和瘟疫食尸鬼。它们出没于森林各处的古老墓地、路边废墟和废弃农庄。",al={"食尸鬼的肋骨掉落地点","哪些食尸鬼有肋骨","食尸鬼的肋骨来源"}},{q="亚伯克隆比为什么想要这些骨头？",a="亚伯克隆比说，他的住处离夜色镇太远，守夜人无法保护他。他索要肋骨，是为了制作一个简陋的稻草人或塑像，相信它能让游荡的亡灵远离他的屋墙。",al={"亚伯克隆比为何需要肋骨","食尸鬼塑像的用途","亚伯克隆比用肋骨做什么"}},{q="稻草人真的能赶走食尸鬼吗？",a="食尸鬼受饥饿或黑暗通灵力量驱使，通常不会感到恐惧。亚伯克隆比却仍坚持认为，用骨头做成的稻草人能保住他的家。",al={"塑像是否有效","塑像能否吓退亡灵","食尸鬼是否害怕稻草人"}},{q="亚伯克隆比的棚屋在哪里？",a="亚伯克隆比的棚屋位于暮色森林西部，就在乌鸦岭墓地北面。",al={"亚伯克隆比的位置","隐士在哪里","食尸鬼的肋骨交付地点"}}},fx={["3e8ffb18"]={q="食尸鬼的肋骨是什么？",a="食尸鬼的肋骨顾名思义，就是从在暮色森林游荡的腐烂复生不死生物身上取下的骨头。这些残骸取自食肉者、食脑者和啃骨者等恶魔般的怪物，仍带有一丝污秽魔法的气息；正是这种魔法驱动着这片受诅森林中的行尸走肉。",al={"食尸鬼的肋骨信息","食尸鬼的肋骨是什么","食尸鬼的肋骨物品"}},f2829c95={q="食尸鬼的肋骨来自哪里？",a="这些肋骨直接来自出没于暮色森林阴暗道路和古墓中的各种食尸鬼。它们是天然的骸骨，而非制作而成的遗物，取自瘟疫散播者和腐烂者等不死怪物；这些怪物游荡在远离夜色镇相对安全地带的地方。",al={"食尸鬼的肋骨来源","食尸鬼的肋骨背景及获取地点","谁制作了食尸鬼的肋骨"}}},fp="9,161,15.373.0,27.237.1,32.238.0,38.200.0,40.163.0,37.84.0"}
P.entries["item:giant-crocolisk-skin"] = {n="巨型鳄鱼的皮",s="湿地的巨型鳄鱼能提供厚实的皮，米奈希尔港的商人需要用这些皮来制作皮具。猎杀巨型鳄鱼十分危险，已有不止一名猎人因此伤残。",h="湿地的巨型鳄鱼能提供厚实的皮，米奈希尔港的商人需要用这些皮来制作皮具。猎杀巨型鳄鱼十分危险，已有不止一名猎人因此伤残。",kw={"学徒的职责","鳄鱼","巨型鳄鱼的皮","詹姆斯·哈洛兰","米奈希尔港","湿地"},ang={["class:Hunter"]="身为猎人，沿海岸追猎巨型鳄鱼，会考验你追踪水生野兽并避开沼泽水域的本领。"},sec={{t="危险的营生",b="湿地的泥沼和水道中栖息着体形庞大的鳄鱼，它们的皮十分致密，足以抵御沼泽湿气的侵蚀。在米奈希尔港，詹姆斯·哈洛兰这样的工匠依靠源源不断运来的兽皮制作结实耐用的皮具。要接近一头成年的巨型鳄鱼，就得冒险涉入深水，直面凶猛的沼泽掠食者，因此每张皮都来之不易。"},{t="学徒的莽撞",b="哈洛兰年轻的学徒曾负责收集这些厚皮。这个男孩没有击败成年沼泽野兽的本领，在北部海岸遭到了伏击。巨型鳄鱼将他咬成重伤，如今他正由当地的一位接生婆照料。她说他或许能挺过来。袭击发生后，哈洛兰雇用了经验丰富的冒险者，猎杀这些掠食者，收集他所需的皮。"}},faq={{q="巨型鳄鱼的皮有什么用途？",a="米奈希尔港的商人詹姆斯·哈洛兰用巨型鳄鱼的皮制作结实的皮具，让它们能经受住沼泽地的潮湿气候。",al={"鳄鱼皮用途","为何收集巨型鳄鱼的皮","哈洛兰收皮用途"}},{q="提供这些皮的鳄鱼在哪里出没？",a="巨型湿地鳄鱼出没于米奈希尔港以北的海岸和内陆沼泽水域，栖息在当地鱼人聚落外的浅水中。",al={"巨型鳄鱼位置","哪里能找到巨型鳄鱼","湿地海岸鳄鱼"}},{q="哈洛兰的学徒遭遇了什么？",a="哈洛兰派学徒独自到沼泽中收集兽皮。巨型鳄鱼将这个男孩咬成重伤，如今他正由米奈希尔的一位接生婆照料。她说他或许能挺过来。",al={"学徒受伤","哈洛兰的学徒","谁失去了一条腿"}},{q="这些皮与幼年鳄鱼的皮相比如何？",a="幼年鳄鱼的皮更薄，也更柔韧。成年巨型鳄鱼的皮更厚、更坚韧，但要杀死它们，需要娴熟的战斗技巧。",al={"幼年与巨型鳄鱼的皮对比","鳄鱼皮差别"}}},fx={["406c8fec"]={q="巨型鳄鱼的皮是什么？",a="这是从湿地沼泽中游荡的巨型鳄鱼身上剥下的厚实耐用的皮。皮革匠和工匠看重它的韧性与尺寸。要获取这样的皮毛并非易事，因为这些掠食者是水道中最凶猛的野兽之一。",al={"巨型鳄鱼的皮是什么","巨型鳄鱼皮","鳄鱼皮信息"}},bd43ba97={q="巨型鳄鱼的皮来自哪里？是谁制作的？",a="这种皮是从湿地沿海岸向北、鱼人窝棚以外的沼泽中生活的巨型鳄鱼身上剥下的。它并非由工匠制作，而是必须直接从这些巨型沼泽野兽的尸体上剥取。",al={"谁制作了巨型鳄鱼的皮","巨型鳄鱼的皮来自哪里","巨型鳄鱼的皮来源"}},c37602c5={q="詹姆斯·哈洛兰为什么需要巨型鳄鱼的皮？",a="米奈希尔港的工匠詹姆斯·哈洛兰需要这些皮来从事他的行当。他起初派年轻的学徒去收集，但那孩子遭饥饿的野兽撕咬，随后由一位助产士照料。于是哈洛兰转而求助经验丰富的冒险者，帮他取得材料并为学徒报仇。",al={"哈洛兰为什么要鳄鱼皮","谁需要巨型鳄鱼的皮","为什么需要巨型鳄鱼的皮"}}},fp="20,143,17.317.0,22.358.1,40.145.0,56.154.0,39.169.0,52.154.0"}
P.entries["item:gloom-weed"] = {n="阴暗草",s="在提瑞斯法林地，阴暗草生长在丧钟镇与布瑞尔之间的田野里。葛尔多是被遗忘者的一头憎恶，行动笨重，在寻找末日草时误采了阴暗草。",h="在提瑞斯法林地，阴暗草生长在丧钟镇与布瑞尔之间的田野里。葛尔多是被遗忘者的一头憎恶，行动笨重，在寻找末日草时误采了阴暗草。",kw={"憎恶","布瑞尔","末日草","阴暗草","葛尔多","霍兰德","提瑞斯法林地"},ang={["profession:Herbalism"]="作为一名受过训练的草药师，你可以通过Find Herbs感知阴暗草，更容易在提瑞斯法阴暗的灌木丛中发现它。",["race:Undead"]="作为一名刚离开丧钟镇的被遗忘者，你可以在运送阴暗草的过程中，见识憎恶办事有多差劲，以及幽暗城的炼金师说话有多尖刻。"},sec={{t="误采的草药",b="阴暗草生长在布瑞尔以西、索利丹农场以东的田野里。这种植物无害，也不具备皇家药剂师学会所追求的炼金效力。憎恶葛尔多沿着道路游荡，用笨拙的双手拔取杂草。他误解了主人的命令，一直在采集阴暗草。随后，他请旅人将草药送到布瑞尔墓地的霍兰德手中，让这位药剂师十分恼火。"}},faq={{q="阴暗草有什么用途？",a="被遗忘者的炼金师几乎用不上阴暗草。葛尔多采集它，是因为他将它误认成了主人要求的草药末日草。",al={"阴暗草用途","阴暗草有什么用","谁需要阴暗草"}},{q="阴暗草生长在哪里？",a="阴暗草生长在提瑞斯法林地中布瑞尔与丧钟镇之间的田野里。沿路以及索利丹农场以东的草地上都能找到它。",al={"哪里能找到阴暗草","阴暗草位置","阴暗草采集点"}},{q="葛尔多是谁，为什么要采集阴暗草？",a="葛尔多是霍兰德派去收集材料的一头憎恶。他双手笨拙，头脑简单，因此总是拔错植物，还会请路人帮忙。",al={"葛尔多是谁","葛尔多为什么拔草","葛尔多憎恶"}},{q="霍兰德真正想要的是什么？",a="霍兰德需要末日草，以便在布瑞尔墓地进行实验。旅人将阴暗草交给他时，他会嘲笑这个错误，并派他们去采集他需要的草药。",al={"霍兰德草药","霍兰德需要什么","末日草与阴暗草的区别"}}},fp="10,118,18.441.0,28.137.0,27.131.0,38.172.0,38.180.0"}
P.entries["item:glowing-ember"] = {n="余烬",s="在恒焰圣殿，余烬点燃火盆，供萨满祭司接受试炼。它来自杜隆塔尔峭壁上的火焰之魂。",h="在恒焰圣殿，余烬点燃火盆，供萨满祭司接受试炼。它来自杜隆塔尔峭壁上的火焰之魂。",kw={"火焰的召唤","火焰灵契","余烬","火焰之魂","恒焰圣殿","泰尔夫·祖拉姆","眠炎火炬"},ang={["class:Shaman"]="身为萨满祭司，在掌控图腾之前，你要在这场入门仪式中直面活生生的火焰，考验自己的意志。"},sec={{t="火焰之核",b="成长中的萨满祭司喝下火焰灵契，便能看见泰尔夫·祖拉姆附近山脊上的火焰之灵。在那里，学徒要面对火焰之魂。元素倒下后，它的实体形态只留下一块阴燃的余烬。原始的元素热力仍在其中涌动，蕴藏着唤醒恒焰圣殿神圣火盆所需的鲜活火种。"},{t="点燃火炬",b="余烬落入山上火盆冰冷的盆中，炽白的烈火便骤然燃起。学徒借助火盆中的火焰，点燃眠炎火炬。火炬将桀骜的火焰精华束缚在容器之中，学徒可以将它带下山，作为驾驭元素的证明。"}},faq={{q="余烬从何而来？",a="你在杜隆塔尔的恒焰圣殿上方山顶击败火焰之魂，便能从它身上取得余烬。",al={"如何获得余烬","余烬掉落","余烬在哪里"}},{q="余烬有什么用途？",a="你将余烬放入恒焰圣殿的金属火盆中。它燃起炽烈而有节律的火焰，点亮仪式所用的眠炎火炬。",al={"余烬有什么作用","余烬用途","火盆余烬"}},{q="萨满祭司为什么需要火焰灵契才能取得余烬？",a="山顶的元素之灵无法被凡人的寻常双眼看见。喝下火焰灵契能让你的感官与元素位面相通，显现出火焰之魂，让你能够向它发起挑战。",al={"为什么需要灵契","看不见火元素","火焰灵契余烬"}},{q="谁指引萨满祭司寻找这块余烬？",a="泰尔夫·祖拉姆是隐居在杜隆塔尔峭壁间的隐士，他调制火焰灵契，并引导萨满祭司学徒通过击败火焰之灵的试炼。",al={"谁给予任务","泰尔夫·祖拉姆余烬","火焰的召唤任务给予者"}}},fp="13,157,17.352.0,18.308.1,39.125.0,27.150.0,49.206.0,39.144.0"}
P.entries["item:glowing-fruit"] = {n="发光的水果",s="在泰达希尔，一种奇异的水果在不寻常的蕨叶下发着光。奥拉密斯湖畔的德纳兰正在研究它与世界之树的土壤之间产生的奇怪反应。",h="在泰达希尔，一种奇异的水果在不寻常的蕨叶下发着光。奥拉密斯湖畔的德纳兰正在研究它与世界之树的土壤之间产生的奇怪反应。",kw={"植物学","德纳兰","发光的水果","奥拉密斯湖","植物","泰达希尔","林精"},ang={["class:Druid"]="身为感知着泰达希尔平衡的德鲁伊，你或许会认为，那些与当地土壤产生奇怪反应的外来植物，会威胁这棵年轻的世界之树。",["profession:Herbalism"]="身为草药师，你可以从水果奇异的光芒看出，外来的种子与蕴含魔力的土壤之间产生了不寻常的相互作用。"},sec={{t="奇异的样本",b="发光的水果悬挂在泰达希尔不寻常的蕨叶下，浑圆而明亮。奥拉密斯湖畔的植物学家德纳兰认出，它并非世界之树的原生植物。他认为，它的种子来自大洋彼岸的遥远土地。它与泰达希尔肥沃且蕴含魔力的土壤之间产生的反应，表明外来植物能够影响这棵年轻的世界之树。"}},faq={{q="发光的水果是什么？",a="发光的水果是一种圆形果实，生长在泰达希尔不寻常的蕨叶下。它自身会发光，并与当地的土壤产生奇怪的反应。",al={"发光的水果 泰达希尔","这是什么水果","奇怪的水果任务"}},{q="这种水果来自哪里？",a="德纳兰认为，发光的水果并非泰达希尔的原生植物。他怀疑，它的种子来自遥远的大洋彼岸，也许是东部王国。",al={"水果来源","种子来自哪里","是否为原生植物"}},{q="谁想检查发光的水果？",a="德纳兰是奥拉密斯湖畔的一位暗夜精灵研究者，他想研究发光的水果。他研究泰达希尔的枝干和生态系统，对那些会与世界之树的土壤产生反应的外来植物很感兴趣。",al={"谁需要水果","发光的水果交到哪里","德纳兰 水果"}}},fp="13,151,18.318.0,26.136.0,31.143.0,39.201.0"}
P.entries["item:glowing-gem"] = {n="发光的宝石",s="泰洛尼斯为寻找发光的宝石而丧命后，宝石便留在了法拉希姆湖的鱼人手中。这块宝石蕴含着修复达图尔的魔棒所需的魔力。",h="泰洛尼斯为寻找发光的宝石而丧命后，宝石便留在了法拉希姆湖的鱼人手中。这块宝石蕴含着修复达图尔的魔棒所需的魔力。",kw={"阿斯特兰纳","净化魔棒","达图尔","发光的宝石","伊瑞斯湖","鱼人","莱恩·狼行者","莎尔蒂恩","泰洛尼斯"},ang={["class:Druid"]="身为德鲁伊，泰洛尼斯对蔓延的腐化所做的研究，以及他希望修复的圣物，都与你息息相关。",["race:NightElf"]="身为暗夜精灵，寻回宝石并完成泰洛尼斯的使命，既能向这位牺牲的斥候致敬，也能帮助Sentinels保护灰谷，抵御蔓延的腐化。"},sec={{t="达图尔遗失的圣物",b="法拉希姆湖附近的鱼人持有发光的宝石，这块宝石蕴藏着尚未激发的魔力。泰洛尼斯是一名来自阿斯特兰纳的年轻暗夜精灵，他前去寻找宝石，希望找到遏制灰谷森林中蔓延的腐化的方法。泰洛尼斯死在了湖边，但宝石完好无损，仍在岸边的拾荒者手中。"},{t="修复魔棒",b="发光的宝石和泰洛尼斯的日记被寻回后，哨兵首领莱恩·狼行者便让持有者向东北方出发，去找守望着附近一座月亮井的树妖莎尔蒂恩。莎尔蒂恩知道如何将宝石与达图尔的魔棒其余遗失的部件结合起来，继续泰洛尼斯未竟的工作。"}},faq={{q="发光的宝石来自哪里？",a="灰谷西部的法拉希姆湖畔，神殿周围的岸边和浅水中都有携带发光的宝石的鱼人，泰洛尼斯就倒在了那里。",al={"发光的宝石位置","谁掉落发光的宝石","哪里获取发光的宝石"}},{q="泰洛尼斯为什么要寻找这块宝石？",a="泰洛尼斯试图找到净化灰谷日益蔓延的污秽的方法。他的研究指出，发光的宝石是重铸达图尔设计的一根魔棒所需的关键部件。",al={"泰洛尼斯任务","泰洛尼斯为什么需要宝石","宝石用途"}},{q="应该把发光的宝石交给谁？",a="把发光的宝石和泰洛尼斯的日记拿给阿斯特兰纳的莱恩·狼行者看，然后带着宝石向东北方出发，交给伊瑞斯湖东侧月亮井旁的树妖莎尔蒂恩。",al={"谁需要发光的宝石","交付发光的宝石","宝石有什么用"}},{q="达图尔的魔棒是什么？",a="达图尔的魔棒是他创造的一件魔法器具。它的部件散落在森林各处，重铸它需要发光的宝石。",al={"达图尔的魔棒","达图尔制造了什么"}}},fx={["464fc9d6"]={q="发光的宝石是什么？",a="发光的宝石是一块附魔石头，是重制达图尔制作的法杖所需的材料。泰洛尼斯在研究灰谷的腐化时寻找过它，而莱恩·狼行者则负责寻找法杖剩余的部件。",al={"发光的宝石是什么","介绍一下发光的宝石","发光的宝石背景"}}},fp="11,131,22.265.0,17.285.1,37.142.0,37.167.0,37.166.0,26.137.0"}
P.entries["item:glowing-soul-gem"] = {n="发光的灵魂宝石",s="在奥迪拉兰，发光的灵魂宝石被用于暗滩教派在灰谷北部的活动。宝石中充斥着暗影巫术，囚禁着一名不知情受害者的灵魂。",h="在奥迪拉兰，发光的灵魂宝石被用于暗滩教派在灰谷北部的活动。宝石中充斥着暗影巫术，囚禁着一名不知情受害者的灵魂。",kw={"奥萨拉克斯","暗滩教派","净化者德尔格伦","发光的灵魂宝石","迈斯特拉岗哨","奥迪拉兰","灵魂宝石"},ang={["class:Priest"]="身为牧师，你能感受到被囚禁在宝石中的灵魂所承受的痛苦。必须净化这件神器，才能让灵魂安息。",["class:Warlock"]="身为术士，你深谙将灵魂囚禁在灵魂石中的技艺。暗滩教派的宝石则以更粗陋的通灵术操纵灵魂。"},sec={{t="黑暗巫术的容器",b="迈斯特拉岗哨东北方的奥迪拉兰废墟，藏匿着暗滩教派的成员及其隐于暗影中的主人。教派成员随身携带发光的灵魂宝石，这些附魔容器囚禁并折磨着死者的灵魂。这些宝石引导魔法能量，束缚灵魂，供教派驱使。"},{t="奥迪拉兰的秘密",b="在迈斯特拉岗哨，净化者德尔格伦正在调查这些宝石，以削弱暗滩教派在卡利姆多北部的影响。破解发光的灵魂宝石上的魔法，会揭示黑暗的奥术公式，以及其中一个正在哀号的被囚灵魂。这些公式揭露了一些实验，将灰谷的教徒与奥萨拉克斯之塔的同伙联系起来。"}},faq={{q="发光的灵魂宝石是什么？",a="暗滩教派将发光的灵魂宝石用作附魔灵魂石。暗影魔法将灵魂困在其中，让教派得以利用其精华施展巫术。",al={"灵魂宝石是什么","灵魂宝石 黑海岸","发光的灵魂宝石 背景故事"}},{q="这颗灵魂宝石来自哪里？",a="暗滩教派的成员从灰谷北部的奥迪拉兰废墟带来这种宝石。携带者包括教徒、刺客、执行者和精通法术的教派成员。",al={"谁掉落灵魂宝石","发光的灵魂宝石 位置","奥迪拉兰 宝石"}},{q="谁想要这颗灵魂宝石，又是为什么？",a="迈斯特拉岗哨的净化者德尔格伦正在寻找这颗宝石。他相信，宝石上的魔法会揭示教派力量的秘密来源，以及他们正在策划的阴谋。",al={"德尔格伦 灵魂宝石","德尔格伦为什么想要灵魂宝石","迈斯特拉岗哨 灵魂宝石"}},{q="破解灵魂宝石上的魔法后会发生什么？",a="破解宝石上的魔法，会释放困在其中的幽灵。饱受折磨的灵魂得以解脱，暗滩教派的所作所为也随之暴露。",al={"灵魂宝石里有什么","灵魂宝石中的幽灵"}}},fp="16,179,24.294.0,25.318.1,29.167.0,35.167.0,32.161.0,45.143.1"}
P.entries["item:glutton-shackle"] = {n="暴食者镣铐",s="在银松森林，暴食者镣铐为阿鲁高有缺陷的法术提供力量。这位疯狂的大法师为月怒暴食者狼人打造了这些附魔束具。",h="在银松森林，暴食者镣铐为阿鲁高有缺陷的法术提供力量。这位疯狂的大法师为月怒暴食者狼人打造了这些附魔束具。",kw={"阿鲁高","达拉尔·道恩维沃尔","暴食者镣铐","月怒暴食者","瑟伯切尔","银松森林","狼人"},ang={["class:Mage"]="身为法师，你或许能理解达拉尔·道恩维沃尔对阿鲁高拙劣技艺的尖刻批评。依靠附魔实物来稳定简单的变形术和召唤法术，足以显出一名巫师的平庸。",["race:Undead"]="身为被遗忘者的一员，你知道狼人正直接威胁着瑟伯切尔的边界，而收集这些镣铐是消除这一威胁的关键。"},sec={{t="孱弱法术的支撑",b="凶野的狼人遍布银松森林，而被遗忘者中训练有素的法师认为，这正是奥术技艺拙劣的证据。达拉尔·道恩维沃尔是驻守瑟伯切尔的资深奥术师，他鄙视大法师阿鲁高，称其为不配跻身肯瑞托的无能庸才。道恩维沃尔发现，阿鲁高依靠附魔遗物来支撑他脆弱的法术。在银松森林北部游荡的魁梧月怒暴食者戴着暴食者镣铐，这些魔法锚点强化了束缚这些野兽的诅咒。"},{t="被遗忘者反制之力的来源",b="阿鲁高将粗糙的附魔直接束缚在沉重的铁环中，即使佩戴者被杀死，镣铐内仍残留着魔法能量。道恩维沃尔希望被遗忘者的特工将这些铁环带给他，以便研究其构造，并抽取其中储存的能量。通过研究金属中粗劣的附魔，被遗忘者希望解开狼人诅咒的奥秘，并设法扳倒盘踞在影牙城堡的驭兽者。"}},faq={{q="暴食者镣铐是什么？",a="暴食者镣铐是银松森林的月怒暴食者狼人佩戴的附魔铁制束具。大法师阿鲁高打造了这些铁环，以魔法强化佩戴者，并支撑他有缺陷的法术。",al={"暴食者镣铐是什么","暴食者镣铐背景故事","狼人镣铐"}},{q="达拉尔·道恩维沃尔为什么需要暴食者镣铐？",a="达拉尔·道恩维沃尔想要这些镣铐，以研究阿鲁高粗劣的附魔，并抽取其中残留的魔法能量。了解阿鲁高用来稳定其野兽的物品，可以帮助被遗忘者对抗他的魔法。",al={"为什么收集镣铐","达拉尔·道恩维沃尔任务","交给瑟伯切尔的镣铐"}},{q="这些镣铐是谁制作的？",a="大法师阿鲁高为这些镣铐施加了附魔。他曾是达拉然的巫师，召唤狼人对抗天灾军团，最终却丧失了理智，借助魔法饰物迫使自己的造物服从他的意志。",al={"谁制作了镣铐","阿鲁高的镣铐","镣铐的来源"}},{q="在哪里能找到佩戴这些镣铐的生物？",a="月怒暴食者游荡在银松森林中部和北部的林地与废弃农庄中，常与其他受到腐化的月怒狼人结伴成群。",al={"暴食者出现地点","月怒 暴食者位置","银松森林狼人镣铐"}}},fp="15,143,25.512.0,33.458.1,26.198.0,48.218.0,25.190.0,53.170.0"}
P.entries["item:glyph-of-azora"] = {n="阿祖拉的铭文饰品",s="塞欧克瑞图斯在阿祖拉之塔中监视着艾尔文境外的威胁。他的铭文饰品将阿祖拉之眼的力量延伸到更远的地方，让他能够读取敌人的思想和计划。",h="塞欧克瑞图斯在阿祖拉之塔中监视着艾尔文境外的威胁。他的铭文饰品将阿祖拉之眼的力量延伸到更远的地方，让他能够读取敌人的思想和计划。",kw={"阿祖拉的铭文饰品","莫甘斯","赤脊山","窥视","石堡要塞","塞欧克瑞图斯","阿祖拉之塔","伊尔加拉之塔"},ang={["class:Mage"]="身为法师，你可以运用奥术占卜，将水晶窥视扩展为定向心灵感应和远程感官传递。",["faction:Alliance"]="身为联盟的一员，你可以利用铭文饰品收集有关莫甘斯和石堡要塞的黑石兽人的情报。"},sec={{t="边境之外的耳目",b="塞欧克瑞图斯在艾尔文森林的高塔中监视着敌对势力。阿祖拉之眼能让他看见远方，却无法窥探对手的思想或计划。因此，他将名为阿祖拉的铭文饰品的小型聚焦物安置在远处的物体表面。每一件饰品都能锚定他的魔法，让他读取敌人的意图，并将声音传至数英里之外，与外勤人员交谈。"},{t="赤脊山的谍报行动",b="在赤脊山，塞欧克瑞图斯将铭文饰品安置在敌方领地。他把第一件固定在一座俯瞰伊尔加拉之塔的古老雄狮雕像上。他的对手，黑暗巫师莫甘斯，占据着那座据点。借助铭文饰品，塞欧克瑞图斯潜入莫甘斯的思想，发现他与附近石堡要塞的黑石兽人发生了争执。为了查明缘由，他将第二件铭文饰品送入要塞内仍然完好的瞭望塔高处，藏在一个废弃的酒罐里。"}},faq={{q="阿祖拉的铭文饰品有什么用途？",a="塞欧克瑞图斯用阿祖拉的铭文饰品扩展阿祖拉之眼的作用范围。将它安置在远处，就能锚定他的魔法，让他读取对手的思想和计划，并与数英里之外的外勤人员交谈。",al={"阿祖拉的铭文饰品有什么作用","为什么使用阿祖拉的铭文饰品","阿祖拉的铭文饰品用途"}},{q="谁创造了阿祖拉的铭文饰品？",a="塞欧克瑞图斯创造了阿祖拉的铭文饰品。他住在艾尔文森林东部边境的阿祖拉之塔中。",al={"谁制作了铭文饰品","阿祖拉的铭文饰品创造者","塞欧克瑞图斯的铭文饰品"}},{q="阿祖拉的铭文饰品安置在哪里？",a="一件铭文饰品固定在俯瞰伊尔加拉之塔的古老雄狮雕像上。另一件藏在石堡要塞内仍然完好的瞭望塔中的一个废弃酒罐里。",al={"铭文饰品放在哪里","铭文饰品安置地点","铭文饰品放置位置"}},{q="塞欧克瑞图斯为什么要监视伊尔加拉之塔？",a="伊尔加拉之塔是莫甘斯的据点。这名叛离正道的黑暗巫师是塞欧克瑞图斯的对手，而铭文饰品让塞欧克瑞图斯能够读取他的思想和计划。",al={"为什么监视莫甘斯","塞欧克瑞图斯 伊尔加拉","莫甘斯的争端"}},{q="铭文饰品如何让塞欧克瑞图斯与人交谈？",a="铭文饰品固定在远处的物体表面，锚定塞欧克瑞图斯的魔法。它能让他将声音传至数英里之外，与外勤人员交谈。",al={"会说话的铭文饰品","铭文饰品中塞欧克瑞图斯的声音","铭文饰品能说话吗"}}},fx={["16152ed3"]={q="阿祖拉的铭文饰品是什么？",a="阿祖拉的铭文饰品是巫师塞欧克瑞图斯在阿祖拉之塔制作的附魔奥术标记。这些刻有铭文的石头与他的占卜法器阿祖拉之眼配合，充当远程监听哨。只要将铭文饰品固定在所关注区域附近的某个表面上，塞欧克瑞图斯就能在遥远的地方探入目标的心智，窥探其思想，还能将自己的声音传给站在饰品旁的人。",al={"什么是阿祖拉的铭文饰品","阿祖拉的铭文饰品物品","阿祖拉的铭文饰品介绍"}},["7c5a9e02"]={q="塞欧克瑞图斯为什么要你放置阿祖拉的铭文饰品？",a="塞欧克瑞图斯依靠这些铭文饰品，对赤脊山的危险敌人进行深入刺探。阿祖拉之眼虽然能让他看到远方的地方，但附近若没有媒介，他就无法窥探心智。将一枚铭文饰品放在伊尔加拉之塔附近，就能让他探查对手、叛逃法师莫甘斯的思想和未来计划，而将另一枚放在石堡要塞附近，则能帮助他弄清莫甘斯与黑石兽人之间的争斗。",al={"为什么放置阿祖拉的铭文饰品","塞欧克瑞图斯为什么要放置铭文饰品","阿祖拉的铭文饰品用途"}}},fp="14,161,22.362.0,21.468.1,42.206.0,31.107.0,37.168.0,49.150.0,55.136.0"}
P.entries["item:glyphic-letter"] = {n="雕文信件",s="在北郡修道院，雕文信件召唤有潜力的新学徒研习奥术。他们为驻军效力后，便会受召前往楼上，拜见常驻于此的法师训练师凯尔登·布雷门。",h="在北郡修道院，雕文信件召唤有潜力的新学徒研习奥术。他们为驻军效力后，便会受召前往楼上，拜见常驻于此的法师训练师凯尔登·布雷门。",kw={"奥术","艾尔文森林","雕文信件","凯尔登·布雷门","法师训练师","治安官玛克布莱德","北郡修道院"},ang={["class:Mage"]="身为法师，这封带有徽记的信函召你上楼，在凯尔登·布雷门的指导下，开始正式研习联盟的奥术传统。",["race:Human"]="身为人类，你从这份召令开始，为暴风城的魔法事业效力。在王国的历史长河中，北郡修道院一直庇护着研习奥术的学徒。"},sec={{t="奥术的召唤",b="凯尔登·布雷门用自己的徽记封好雕文信件。施法学徒在北郡山谷证明自己严守纪律后，便会收到这封信。这份召令让他们放下基础的野外差事，进入修道院接受专门的魔法教导。\n\n在学生开始研习奥术之前，布雷门会考验每个人的决心。奥术的力量危险，考验严苛，重担沉重。"}},faq={{q="雕文信件是什么？",a="凯尔登·布雷门写下雕文信件并将其封好，召唤学徒前来受教。信中指引有志成为法师的人类前往北郡修道院楼上的房间找他，接受正式的奥术教育。",al={"这封信是什么","雕文信件物品","凯尔登的信"}},{q="雕文信件是谁寄来的？",a="北郡修道院的法师训练师凯尔登·布雷门用自己的徽记封好这封信。学徒在对付附近害兽的战斗中证明自己的本领后，驻军指挥官便会将信交给他们。",al={"谁写的信","谁给了我雕文信件","寄信人"}},{q="我该把雕文信件带到哪里？",a="把信带进北郡修道院。从治安官玛克布莱德身后的入口进去，沿左侧走廊前行，登上楼梯，再往后面的房间找，凯尔登·布雷门就在那里传授奥术。",al={"去哪里","凯尔登·布雷门在哪里","凯尔登的位置"}},{q="凯尔登为什么召唤年轻的法师？",a="凯尔登想考验你的决心。他告诫你，追求奥术会招来恐惧与敬重，也意味着要挑战强大的力量。他需要知道，你是否有意志承受这样的命运。",al={"凯尔登为什么找我","法师训练师召唤的原因","凯尔登想要什么"}}},fx={["4321b6bd"]={q="凯尔登·布雷门为什么要把雕文信件交给你？",a="这封信既是对初出茅庐的法师的正式召唤，也是对他们决心的考验。凯尔登·布雷门的信件以他的私人徽记封缄，阐明了奥术之路的危险与艰难，告诫你追寻禁忌知识会伴随怎样的恐惧与挑战。将信交给你，是为了在开始正式训练之前，确认你愿意面对这样的命运。",al={"为什么需要雕文信件","为什么收到雕文信件","雕文信件用途"}}},fp="14,180,23.390.0,27.190.0,29.183.0,35.185.0,38.193.0"}
P.entries["item:glyphic-memorandum"] = {n="雕文备忘录",s="在寒脊山谷，雕文备忘录召集初学法师前往安威玛尔。玛瑞克·斯托纳尔写下这份备忘录，引导新晋施法者接受正规的奥术教导。",h="在寒脊山谷，雕文备忘录召集初学法师前往安威玛尔。玛瑞克·斯托纳尔写下这份备忘录，引导新晋施法者接受正规的奥术教导。",kw={"安威玛尔","寒脊山谷","丹莫罗","雕文备忘录","法师","玛瑞克·斯托纳尔"},ang={["class:Mage"]="作为丹莫罗的一名法师，你凭这张便笺，在玛瑞克·斯托纳尔的指导下开始正式的奥术学徒生涯。",["race:Gnome"]="作为一名在流亡中踏上旅途的侏儒法师，你的训练师敦促你专心学习，远离你那沦陷的故乡诺莫瑞根。"},sec={{t="安威玛尔的召唤",b="初学施法者完成在寒脊山谷的最初几项任务后，就会收到雕文备忘录。当地的法师训练师玛瑞克·斯托纳尔召他们到安威玛尔里面见。他的忠告很直白：学好咒语，攒钱接受训练、购买旅店里的麦酒，并远离被辐射摧毁的诺莫瑞根。"}},faq={{q="雕文备忘录是什么？",a="雕文备忘录召集初到寒脊山谷的法师。它指引他们去找安威玛尔内的奥术训练师。",al={"雕文备忘录","法师便笺","雕文备忘录是什么"}},{q="这份备忘录是谁写的？",a="玛瑞克·斯托纳尔写下了这份备忘录。他在丹莫罗的安威玛尔训练法师。",al={"谁写的","谁寄来雕文备忘录","便笺作者"}},{q="前去回应备忘录的召唤时，训练师会给出什么忠告？",a="当你出示这张便笺时，玛瑞克会劝你保持克制。攒钱学习法术、购买旅店里的麦酒，并避开诺莫瑞根那些充斥着辐射的大厅。",al={"玛瑞克 的忠告","玛瑞克 说了什么"}}},fx={c67a7a55={q="玛瑞克·斯托纳尔为什么要你把雕文备忘录带给他？",a="这份备忘录是发给在寒脊山谷起步、立志成为法师之人的邀请与召唤。将它交给安威玛尔的玛瑞克·斯托纳尔，就能与你当地的法师训练师取得联系。他借此机会向新手提供建议，提醒你远离沦陷的诺莫瑞根，并在你有余钱时，为你提供正式的奥术训练。",al={"为什么带去雕文备忘录","玛瑞克·斯托纳尔为什么要备忘录","为什么要雕文备忘录"}}},fp="18,158,21.305.0,31.126.0,26.81.0,64.131.0"}
P.entries["item:glyphic-scroll"] = {n="雕文卷轴",s="在丧钟镇，雕文卷轴召唤新近复生的被遗忘者法师前往教堂。这份召令盖有伊莎贝拉的印章，邀请初出茅庐的施法者以亡灵之身开始奥术训练。",h="在丧钟镇，雕文卷轴召唤新近复生的被遗忘者法师前往教堂。这份召令盖有伊莎贝拉的印章，邀请初出茅庐的施法者以亡灵之身开始奥术训练。",kw={"奥术","丧钟镇","雕文卷轴","伊莎贝拉","法师","卷轴","提瑞斯法"},ang={["class:Mage"]="身为被遗忘者法师，你收到的这份召令，是你接受训练的第一份正式召令。即使化为亡灵，你也无法免受奥术魔法的腐化诱惑。",["race:Undead"]="身为被遗忘者，你重新掌握奥术知识，将其化为武器，对抗Scourge和活着的敌人，捍卫自己的主权。"},sec={{t="教堂的召唤",b="新近苏醒的被遗忘者法师在丧钟镇的墓地清剿无意识的天灾军团后，会找到一份密封的卷轴。镇上的法师训练师伊莎贝拉在卷轴上盖下印章，召唤他们前往残破的教区圣堂。在那里，新晋法师开始在被遗忘者的旗帜下学习奥术。死亡让他们摆脱了凡人的弱点，但魔法带来的腐化诱惑依然存在。"}},faq={{q="雕文卷轴是什么？",a="雕文卷轴引领丧钟镇新近复生的被遗忘者法师开始奥术训练。卷轴盖有训练师伊莎贝拉的印章，召唤他们到镇上的教堂里与她见面。",al={"这是什么物品","雕文卷轴用途","卷轴有什么用"}},{q="谁送来了雕文卷轴？",a="伊莎贝拉将雕文卷轴送给具有奥术天赋的新近复生的亡灵。她是丧钟镇残破教堂里的法师训练师。",al={"谁写的","谁给的","卷轴寄件人"}},{q="伊莎贝拉为什么要训练新的被遗忘者法师？",a="伊莎贝拉训练的被遗忘者法师与她有着共同的经历和愿望：承受过死亡的痛苦，渴望夺回故土、重新掌握自己的命运。她教导他们积蓄奥术力量，消灭与被遗忘者为敌的人，同时告诫他们提防魔法成瘾与腐化。",al={"伊莎贝拉的动机","为什么训练法师"}}},fp="14,167,25.355.0,27.176.0,29.139.0,51.253.0"}
P.entries["item:glyphic-tablet"] = {n="雕文石板",s="在试炼谷，高内克将雕文石板交给初入门的黑暗之矛巨魔法师。石板上的召唤指引他们前去向迈安学习奥术魔法。",h="在试炼谷，高内克将雕文石板交给初入门的黑暗之矛巨魔法师。石板上的召唤指引他们前去向迈安学习奥术魔法。",kw={"奥术","杜隆塔尔","雕文石板","高内克","迈安","巨魔法师","试炼谷"},ang={["class:Mage"]="身为法师，你的黑暗之矛奥术学习始于迈安的告诫：魔法那腐蚀人心的诱惑是你最大的危险。",["race:Troll"]="身为黑暗之矛巨魔，你收到这块石板，开始踏上与传统萨满之道和武技之路并行的道路。"},sec={{t="法师的初次召唤",b="对奥术力量有天赋的黑暗之矛新学徒会在试炼谷收到雕文石板。年轻的新兵在赤红的峡谷间完成最初的任务时，高内克便会将石板交给他们。石板上，大兽穴外经验丰富的巨魔法师迈安邀请他们前去相见。黑暗之矛遵循的奥术传统与人类或高等精灵的学术学院不同。迈安传授知识，也郑重告诫他们：未经驾驭的魔法会腐蚀人心、蒙蔽心智，它对法师心智的威胁远胜于任何敌兵。"}},faq={{q="雕文石板有什么用途？",a="雕文石板召唤初入门的巨魔法师前往试炼谷，向迈安接受正规的施法训练。",al={"雕文石板有什么作用","雕文石板用途","为什么会有雕文石板"}},{q="是谁送来雕文石板的？",a="迈安在石板上写下文字，高内克则将它交给试炼谷中年轻的巨魔新兵。",al={"雕文石板是谁写的","雕文石板是谁给的"}},{q="为什么巨魔法师需要听取关于魔法的警告？",a="迈安警告说，奥术魔法会腐蚀人心、滋长傲慢，让施法者觉得自己无可匹敌。它潜藏的危险比有形的敌手更加致命。",al={"迈安说了什么","魔法危险吗"}},{q="其他部落种族也能收到这块石板吗？",a="巨魔法师会在试炼谷收到雕文石板。兽人法师会收到一份雕文羊皮纸，召他们前往迈安处。",al={"兽人能获得雕文石板吗","雕文石板仅限巨魔吗"}}},fp="14,152,22.518.0,42.114.0,29.94.0,46.154.0,42.130.0"}
P.entries["item:glyphs-of-summoning"] = {n="召唤铭文",s="在奥格瑞玛，术士学徒用召唤铭文召唤虚空行者。这些铭文抄录自古老的维尔加石板，能将虚空行者从虚空引入召唤法阵，并束缚它为术士效劳。",h="在奥格瑞玛，术士学徒用召唤铭文召唤虚空行者。这些铭文抄录自古老的维尔加石板，能将虚空行者从虚空引入召唤法阵，并束缚它为术士效劳。",kw={"暗影裂口","甘鲁尔·血眼","召唤铭文","尼尔鲁·火刃","奥格瑞玛","维尔加石板","誓缚","虚空行者"},ang={["class:Warlock"]="身为部落术士，你面临着一场必经的试炼。借助这些铭文，你可以证明自己对虚空的掌控，并获得一个虚空行者仆从。"},sec={{t="暗影中缔结的契约",b="在暗影裂口，术士们研习黑暗法术，远离大酋长卫兵的窥探。对于向甘鲁尔·血眼求教的术士学徒而言，驾驭虚空行者是重要的一步。召唤铭文源自维尔加石板上记载的知识，连接着艾泽拉斯与虚空。在尼尔鲁·火刃的帐篷里，术士将铭文放入召唤法阵。铭文开启一道门扉，将虚空生物引入凡人世界。在甘鲁尔传授最后的束缚方法之前，术士必须在战斗中击败召唤出的生物。"}},faq={{q="召唤铭文有什么用途？",a="这些铭文是仪式文字，用于奥格瑞玛尼尔鲁·火刃帐篷内的召唤法阵。它们会从虚空召来一个敌对的虚空行者，术士必须将其制服，才能掌握召唤它的方法。",al={"召唤铭文的作用","召唤铭文的用途","召唤铭文的用法"}},{q="召唤铭文来自哪里？",a="暗影裂口的术士训练师甘鲁尔·血眼会提供这些铭文。铭文运用了维尔加石板上保存的知识。",al={"召唤铭文的获取地点","召唤铭文的提供者"}},{q="召唤仪式在哪里进行？",a="仪式在奥格瑞玛的暗影裂口举行，穿过洞穴地面，便是尼尔鲁·火刃的帐篷，仪式就在帐篷内进行。",al={"虚空行者召唤地点","奥格瑞玛召唤法阵位置","尼尔鲁·火刃的法阵"}},{q="术士为什么必须击败召唤出的生物？",a="术士必须确立支配地位，才能安全地控制恶魔或虚空生物。击败召唤出的生物能证明术士的决心，之后甘鲁尔·血眼便会传授如何让这类生物受制于术士的意志。",al={"与虚空行者战斗的原因","制服虚空行者"}}},fp="19,242,23.539.0,42.207.0,43.139.0,40.109.0,53.218.0"}
P.entries["item:gnoam-sprecklesprocket"] = {n="小型高能发动机",s="死亡矿井深处的小型高能发动机，为一项通往诺莫瑞根的计划提供动力。沉默的舒尼正在寻找它，用来驱动钻掘机械，凿穿失落的侏儒家园周围的岩层。",h="死亡矿井深处的小型高能发动机，为一项通往诺莫瑞根的计划提供动力。沉默的舒尼正在寻找它，用来驱动钻掘机械，凿穿失落的侏儒家园周围的岩层。",kw={"死亡矿井","小型高能发动机","诺莫瑞根","回旋钻掘机","沉默的舒尼","斯尼德","斯尼德的伐木机","斯普克斯普鲁克"},ang={["profession:Engineering"]="身为工程师，你看得出，这台完好的动力装置足以驱动钻穿诺莫瑞根地下岩层屏障所需的机械。",["race:Gnome"]="身为侏儒，每回收一个部件，你就离钻入失落的家园、赶走穴居人的目标更近一步。"},sec={{t="关键的动力源",b="斯尼德的伐木机在迪菲亚据点深处运转。地精工头斯尼德驾驶着这台机器，小巧的动力核心为繁重的伐木作业和切割刀片提供能量。稳定的能量输出，让小型高能发动机成了西部荒野矿道中值得回收的部件。"},{t="凿通诺莫瑞根",b="在暴风城，侏儒发明家沉默的舒尼选中了死亡矿井的伐木机，要将它用于一项更大的行动。侏儒部队试图从占据诺莫瑞根的穴居人手中夺回家园，但封闭的地下通道挡住了去路。舒尼计划用小型高能发动机驱动重型回旋钻掘机。这些机器能够钻穿失落的科技之城周围的基岩，为地下突袭开辟一条出其不意的通路。"}},faq={{q="小型高能发动机是什么？",a="小型高能发动机是从死亡矿井深处的一台地精伐木机上拆下的高输出动力装置。它能驱动重型地下钻掘机械。",al={"小型高能发动机","这台发动机是什么","这是什么物品"}},{q="小型高能发动机从哪里来？",a="小型高能发动机来自斯尼德的伐木机，那是一台工业伐木机械，由地精工头斯尼德在死亡矿井的伐木场中驾驶。",al={"谁掉落","如何获得小型高能发动机","伐木机掉落"}},{q="沉默的舒尼为什么需要它？",a="沉默的舒尼需要用这台发动机为回旋钻掘机提供动力。这些机器能够钻穿诺莫瑞根周围的岩层，为效忠联盟的侏儒开辟进攻穴居人的通路。",al={"沉默的舒尼为什么需要它","沉默的舒尼任务物品"}},{q="这台发动机属于地精技术还是侏儒技术？",a="这台发动机来自死亡矿井中一台仍在运转的地精伐木机，舒尼计划将它用于侏儒钻掘机械。没有人提到最初是谁设计了这个部件。",al={"是地精技术吗","侏儒还是地精装置"}}},fp="22,198,20.274.0,20.444.0,35.152.0,48.156.0,35.211.0,45.170.0"}
P.entries["item:gnoll-paw"] = {n="豺狼人的爪子",s="在哨兵岭，收集豺狼人的爪子换取赏金，有助于保护西部荒野的农庄免受河爪群落侵袭。人民军付钱收取巡逻队击杀豺狼人的凭证。",h="在哨兵岭，收集豺狼人的爪子换取赏金，有助于保护西部荒野的农庄免受河爪群落侵袭。人民军付钱收取巡逻队击杀豺狼人的凭证。",kw={"丹努文","豺狼人的爪子","巡逻西部荒野","人民军","河爪","哨兵岭","西部荒野"},ang={["class:Hunter"]="身为猎人，你可以在西部荒野开阔的平原上追踪河爪群落，同时帮助守卫乡间的哨站。",["faction:Alliance"]="对联盟的勇士而言，接受人民军的悬赏，有助于保护暴风城西部的粮仓，使其免受游荡野兽和有组织的匪徒侵袭。"},sec={{t="民兵的悬赏",b="人民军以哨兵岭为据点，保卫西部荒野。王国军队不见踪影，王室似乎也对乡间的困境视而不见。因此，普通居民和志愿者挺身而出，对抗不法之徒、失控的机械和河爪豺狼人。\n\n丹努文队长悬赏征集击杀豺狼人的凭证。这些爪子证明巡逻队确实搜查过灌木荒地，而不是在哨塔下歇息。"},{t="相互勾结的威胁",b="河爪豺狼人在西部荒野的平原上四处觅食。民兵的观察哨发现了一些迹象，表明这些群落与盘踞在死亡矿井周边的迪菲亚盗贼配合密切。豺狼人恐吓农庄，袭击补给车，帮助匪徒抵挡当地人的反抗。\n\n交回豺狼人的爪子，有助于维持哨兵岭与艾尔文森林之间陆路的畅通。"}},faq={{q="丹努文队长为什么需要豺狼人的爪子？",a="丹努文队长要求收集豺狼人的爪子，以此证明巡逻队已经穿过西部荒野的平原，并击杀了豺狼人。民兵资源匮乏，又得不到王室援助，因此用赏金换取这些凭证。",al={"为什么收集爪子","丹努文 豺狼人的爪子","豺狼人的爪子有什么用"}},{q="哪些豺狼人会掉落这些爪子？",a="这些爪子来自游荡在西部荒野草地、丘陵和废弃农场上的河爪豺狼人。",al={"哪里获取豺狼人的爪子","哪些豺狼人掉落爪子","豺狼人的爪子位置"}},{q="西部荒野的豺狼人是在独自行动吗？",a="不是。丹努文队长和民兵怀疑，河爪豺狼人与盘踞在死亡矿井周边的匪徒和盗贼相互勾结。他们共同威胁着当地的农庄。",al={"豺狼人是否与迪菲亚勾结","豺狼人与死亡矿井的联系","谁指挥豺狼人"}},{q="暴风城为什么不处理豺狼人的威胁？",a="内乱与政局瘫痪之下，暴风城基本上任由西部荒野自生自灭。保卫乡间的重担几乎全落在当地农民和人民军肩上。",al={"为什么没有暴风城军队","军队在哪里","民兵为什么对抗豺狼人"}}},fx={aa4b645a={q="豺狼人的爪子是什么？",a="豺狼人的爪子是从游荡于西部荒野平原的河爪豺狼人身上砍下的手掌。对于驻守哨兵岭的人民军而言，这些骇人的战利品是无可辩驳的实物证据，证明冒险者确实巡视了这片土地，并剿灭了威胁当地农庄的凶悍豺狼人群。",al={"什么是豺狼人的爪子","豺狼人的爪子物品","豺狼人的爪子是什么"}},["96952327"]={q="豺狼人的爪子从何而来？",a="这些爪子直接取自散布在西部荒野草原和废弃农场中的野生河爪豺狼人。这些凶残的豺狼人在这片地区游荡，袭击农民并与不法之徒勾结，因此，它们被砍下的爪子成了从野外倒下的劫掠者身上取得的血腥赏金凭证。",al={"哪里获得豺狼人的爪子","谁掉落豺狼人的爪子","豺狼人的爪子来源"}}},fp="9,161,21.403.0,20.379.1,41.199.0,29.98.0,40.159.1,50.195.0"}
P.entries["item:gnomeregan-gumdrop"] = {n="诺莫瑞根橡皮糖",s="万圣节期间，流亡的侏儒将诺莫瑞根橡皮糖送到旅人手中。一颗糖果，让暴风城孤儿院里生病的耶斯帕尔也能欢度节日。",h="万圣节期间，流亡的侏儒将诺莫瑞根橡皮糖送到旅人手中。一颗糖果，让暴风城孤儿院里生病的耶斯帕尔也能欢度节日。",kw={"糖果","诺莫瑞根橡皮糖","万圣节","铁炉堡","耶斯帕尔","暴风城","塔瓦斯德·基瑟尔"},ang={["faction:Alliance"]="你穿行于人类、矮人和侏儒的聚居地，收集这种糖果。这场节日庆典展现了联盟成员之间的紧密联系。",["race:Gnome"]="虽然侏儒尚未夺回自己的城市，但在万圣节期间，他们的特色糖果仍与联盟各大主城的糖果一同登场。"},sec={{t="侏儒巧思的滋味",b="在铁炉堡的秘法区，只要旅人配合塔瓦斯德·基瑟尔玩万圣节的把戏，他就会送上诺莫瑞根橡皮糖。联盟的旅店老板会提供各自家乡的糖果，但流亡的侏儒没有自己的主城旅店。放射性灾难迫使他们离开了地下王国。即便如此，他们仍与联盟分享自己独特的糖果。"},{t="给耶斯帕尔的糖果",b="生病的耶斯帕尔住在教堂广场的暴风城孤儿院，无法跨越大陆，四处讨糖。于是，旅人从联盟各大主城收集四种地方糖果，带给他：诺莫瑞根橡皮糖、暴风城杏仁糖、铁炉堡薄荷糖和达纳苏斯水果糖。"}},faq={{q="诺莫瑞根橡皮糖从哪里来？",a="在铁炉堡的秘法区，只要你配合塔瓦斯德·基瑟尔玩一个万圣节的把戏，他就会送你诺莫瑞根橡皮糖。",al={"谁给诺莫瑞根橡皮糖","如何获得橡皮糖","橡皮糖位置"}},{q="为什么这种糖果不在诺莫瑞根发放？",a="穴居人攻占了诺莫瑞根，并使那里遭到辐射污染，幸存的侏儒被迫流亡。如今，许多侏儒与矮人一同住在铁炉堡，塔瓦斯德·基瑟尔也在其中。",al={"为什么在铁炉堡","塔瓦斯德·基瑟尔为什么在铁炉堡"}},{q="这种糖果有什么用？",a="你要把这种糖果带给耶斯帕尔，他是住在教堂广场的暴风城孤儿院里的一名患病孤儿。这是万圣节期间为他收集的四种节日糖果之一。",al={"橡皮糖有什么用","耶斯帕尔糖果"}},{q="还要一同收集哪些糖果？",a="耶斯帕尔还想要暴风城杏仁糖、铁炉堡薄荷糖和达纳苏斯水果糖。你要前往各自对应的联盟主城收集这些糖果。",al={"其他糖果","万圣节 糖果"}}},fx={["243db981"]={q="诺莫瑞根橡皮糖是什么？",a="诺莫瑞根橡皮糖是一种代表侏儒的节日糖果，在万圣节期间分发。虽然它以失落的科技奇迹诺莫瑞根命名，但分发这种糖果的，是在矮人首都铁炉堡避难的侏儒，其中最著名的就是工匠塔瓦斯德·基瑟尔。",al={"什么是诺莫瑞根橡皮糖","诺莫瑞根橡皮糖糖果","侏儒橡皮糖背景"}}},fp="18,142,28.371.0,18.281.0,42.121.0,46.162.0,28.168.0,45.130.0"}
P.entries["item:gnomish-tools"] = {n="侏儒的工具",s="在杜隆塔尔沿岸，侏儒的工具散落在普罗德摩尔舰队的残骸之间。部落正搜寻这些可打捞的装置，以研究联盟的工程技术，并改进运用其中的创新成果来谋求生存。",h="在杜隆塔尔沿岸，侏儒的工具散落在普罗德摩尔舰队的残骸之间。部落正搜寻这些可打捞的装置，以研究联盟的工程技术，并改进运用其中的创新成果来谋求生存。",kw={"杜隆塔尔","工程学","加索克","侏儒的工具","普罗德摩尔","剃刀岭","流亡海岸","提拉加德城堡"},ang={["faction:Horde"]="作为部落的一员，你可以帮助找回遗失的联盟装备，供部落研究。了解敌人的设计和外来的机械装置，可以帮助部落抵御未来来自海上的入侵。",["profession:Engineering"]="作为工程师，你可以研究这些工具套件，了解联盟工匠的精密技艺、发条组件和微型化技术。"},sec={{t="水下的遗物",b="海军上将戴林·普罗德摩尔的舰队将大量先进装备带到了杜隆塔尔。普罗德摩尔率领库尔提拉斯和联盟部队抵达这里的海岸，船上装载着侏儒盟友制造的精密装备。舰队在提拉加德城堡以东的流亡海岸被摧毁后，这些精巧的机械工具套件沉入了海中。防水工具箱至今仍散落在浅水区腐朽的木料和结满藤壶的船体之间。"},{t="奥格瑞玛的目光",b="负责剃刀岭事务的加索克派出部落斥候，从普罗德摩尔海军葬身的海域打捞工具。兽人知道人类和侏儒精通工程技术，尤其擅长攻城器械、造船和发条机械。他们通过商队，将这些工具套件送往奥格瑞玛的工匠和学者手中。在那里，部落打算研究联盟的机械装置，学习如何对抗敌人的战争机器，并改进运用外来的创新成果来谋求自身的生存。"}},faq={{q="为什么侏儒的工具会散落在杜隆塔尔近海？",a="库尔提拉斯进攻杜隆塔尔时，海军上将戴林·普罗德摩尔的舰队携带了这些工具。当这支舰队在提拉加德城堡以东的流亡海岸被击溃并沉没后，船上的货物也沉到了海底。",al={"侏儒的工具为何在这里","侏儒的工具的来历","工具如何来到杜隆塔尔"}},{q="部落为什么想要这些工具？",a="剃刀岭的加索克希望有人能找回这些工具，并将它们送往奥格瑞玛。研究联盟工程师精密的机械技术，可以帮助部落了解敌人的机器，并制造出更精良的装备。",al={"加索克为何想要工具","部落如何使用侏儒的工具","工具的用途"}},{q="在哪里能找到这些工具？",a="这些工具装在工具箱中，散落在杜隆塔尔流亡海岸的沉船残骸内外，就在提拉加德城堡以东不远处。许多工具箱沉在水下，或散落在半浸水中的破损船体上。",al={"侏儒的工具的位置","哪里能找到侏儒的工具","侏儒工具箱的位置"}}},fp="13,208,14.447.0,17.457.0,53.225.0,36.204.0,26.188.0"}
P.entries["item:gold-dust"] = {n="金砂",s="在艾尔文森林，金砂从狗头人手中流向当地买家。矿工们仍在寻找完整的矿脉。",h="在艾尔文森林，金砂从狗头人手中流向当地买家。矿工们仍在寻找完整的矿脉。",kw={"艾尔文森林","法戈第矿洞","金砂","闪金镇","金牙","玉石矿洞","狗头人","雷米"},ang={["class:Rogue"]="身为潜行者，你可以了解地下势力如何通过雷米这样的可疑商人，转运未经提炼、无从追查的金砂，将这些原始财富藏在暴风城司法官的视线之外。",["profession:Mining"]="身为矿工，你用矿镐和淘洗盘寻找坚实的铜矿脉和锡矿脉。狗头人的金砂表明，艾尔文森林的地下通道中蕴藏的矿脉，比常规勘测所揭示的更为富饶。"},sec={{t="满袋碎金",b="狗头人在艾尔文森林地下的法戈第矿洞和玉石矿洞中挖掘。它们不提炼找到的金砂，而是将其装进口袋和小袋。当地的小贩和销赃者想要这些碎金，希望避开官府征收的冶炼税，从中牟利。"},{t="闪金镇的黑市",b="在闪金镇，雷米请旅人将寻回的金砂带给他。他声称自己的收购价全镇最高，代表一些不具名的同伙，用钱币和可疑的代币换取未经提炼的金砂。旅人从狗头人手中夺回黄金，中间商则在暴风城卫兵的眼皮底下积累财富。"}},faq={{q="金砂从何而来？",a="艾尔文森林各处的狗头人都携带着金砂。矿工、掘地工、地卜师和它们的首领金牙在山丘中挖掘时，收集并囤积金砂。",al={"如何获得金砂","金砂掉落","哪里能找到金砂"}},{q="哪些矿洞里携带金砂的狗头人最多？",a="闪金镇南面的法戈第矿洞和东北面的玉石矿洞，到处都是携带金砂的狗头人。",al={"矿洞在哪里","获取金砂的最佳矿洞","矿洞位置"}},{q="谁在艾尔文森林收购金砂？",a="雷米是个行事可疑的商人，就在闪金镇的狮王之傲旅店外，用钱币和同伙提供的代币收购一袋袋金砂。",al={"谁需要金砂","雷米金砂","交付金砂"}},{q="狗头人为什么携带金砂，而不是金锭？",a="狗头人既缺乏严谨的做事习惯，也没有妥善冶炼矿石的条件。它们用粗陋的矿镐挖掘岩石时，散落的金砂便积在随身物品上，也被装进小袋，当作闪亮的小玩意随身携带。",al={"狗头人为什么有金砂","狗头人的黄金"}}},fx={["38570104"]={q="金砂是什么？",a="金砂是珍贵黄金的细小原矿碎屑，由盘踞在艾尔文森林地下的成群狗头人开采而来。它既不是精炼的货币，也不是浇铸的金锭，而是狗头人在法戈第和玉石等矿洞中，从富矿脉上直接凿下的原始碎屑。",al={"金砂是什么","金砂物品","关于金砂"}},["4a74ebdb"]={q="雷米为什么想要金砂？",a="闪金镇的雷米收购未经提炼的金砂，用于自己的买卖，也供给那些来路不明的同伙。狗头人不怎么懂得熔铸金锭，因此身上带着大量无人登记的矿产财富，只等胆子够大的人夺来出售。",al={"雷米为什么要金砂","为什么要金砂"}}},fp="9,107,22.262.0,24.318.1,31.158.0,53.101.0,36.153.0,44.201.0"}
P.entries["item:golm-fragment"] = {n="高尔姆碎片",s="在湿地南部的挖掘场，高尔姆碎片是戈阿兹之石遗失的四块碎片之一。矮人考古学家需要用它来拼合古老的泰坦铭文。",h="在湿地南部的挖掘场，高尔姆碎片是戈阿兹之石遗失的四块碎片之一。矮人考古学家需要用它来拼合古老的泰坦铭文。",kw={"挖掘场","戈阿兹之石","高尔姆碎片","发现历史","湿地","维尔加"},ang={["faction:Alliance"]="作为联盟的一员，你帮助探险者协会在迅猛龙占领挖掘场之前，保住无价的古代知识。",["race:Dwarf"]="作为矮人，你可以帮助拼合戈阿兹之石，揭开自己的Titan血脉以及卡兹莫丹地下隐藏的历史。"},sec={{t="戈阿兹之石的一块碎片",b="高尔姆碎片就在湿地南部维尔加的挖掘场遗迹之中。勘察员维尔加发现了巨大的戈阿兹之石，不久后迅猛龙便迫使探险者协会撤退。石上的铭文有四处断裂。挖掘场被攻陷后，这块碎片留在泥土和翻倒的板条箱之间，藏在一个古老的遗物箱中，等待探险者取回。"},{t="泰坦的秘密",b="高尔姆碎片与阿度斯、莫德和奈尔鲁碎片拼合后，便能补全一篇晦涩的泰坦文字。重新拼好戈阿兹之石后，维尔加便能解读其中关于神圣计划、毁灭预言，以及被锁在地下的远古存在的文字。铭文揭示的秘密比矮人传承本身更古老，也更危险。"}},faq={{q="高尔姆碎片有什么用途？",a="在发现历史任务中，勘察员维尔加需要高尔姆碎片和另外三块碎片，在湿地挖掘场复原戈阿兹之石。",al={"高尔姆碎片用途","为何需要高尔姆碎片","高尔姆碎片任务"}},{q="在哪里能找到高尔姆碎片？",a="湿地南部丘陵的挖掘场中迅猛龙横行，高尔姆碎片就藏在那里的古代遗物和松软的泥土中。",al={"高尔姆碎片位置","寻找高尔姆碎片","高尔姆碎片在哪"}},{q="戈阿兹之石拼好后，上面写着什么？",a="维尔加最初译出的内容提到了一个神圣的计划和一则毁灭预言。他需要集齐四块碎片，才能继续解读残缺的泰坦文字。",al={"戈阿兹之石译文","石板上写着什么","维尔加译文"}},{q="还需要哪些碎片才能拼好石板？",a="你需要将阿度斯、莫德和奈尔鲁碎片与高尔姆碎片拼在一起，才能复原石板。",al={"其他石板碎片","戈阿兹之石碎片","四块碎片"}}},fx={["523a83d7"]={q="什么是高尔姆碎片？",a="高尔姆碎片是从古代遗物戈阿兹之石上脱落的四块遗失碎片之一；这件遗物是在湿地的挖掘现场发现的。碎片上刻有古老铭文，补充了整块石板晦涩叙述的一部分。",al={"什么是高尔姆碎片","高尔姆碎片背景","高尔姆碎片是什么"}},["890266ad"]={q="高尔姆碎片来自哪里？是谁制作的？",a="这块碎片原本属于戈阿兹之石，很久以前以泰坦文字雕刻而成。矮人在湿地的挖掘现场进行考古发掘时将其出土，随后凶猛的迅猛龙袭击了该地区，并使石板碎片散落各处。",al={"谁制作了高尔姆碎片","高尔姆碎片的起源","高尔姆碎片来自哪里"}},["6695e471"]={q="勘察员维尔加为什么要高尔姆碎片？",a="勘察员维尔加需要高尔姆碎片和其他几块碎片一起拼成完整的戈阿兹之石。缺少它，译文就会戛然而止，关于神圣计划和注定应验的预言的重要细节也会因此缺失。",al={"维尔加为什么需要高尔姆碎片","谁想要高尔姆碎片","为什么寻找高尔姆碎片"}}},fp="13,178,25.394.0,21.324.1,35.148.0,37.127.0,44.151.1,52.83.0"}
P.entries["item:gordon-s-crate"] = {n="高顿的箱子",s="幽暗城的高顿的箱子里装着武器，即将运往银松森林的被遗忘者部队。这批货物将送往瑟伯切尔的偏远驻军。",h="幽暗城的高顿的箱子里装着武器，即将运往银松森林的被遗忘者部队。这批货物将送往瑟伯切尔的偏远驻军。",kw={"蝙蝠管理员","亡灵卫兵博迪瑞格","高顿的箱子","卡洛斯·拉佐克","银松森林补给","瑟伯切尔","幽暗城"},ang={["faction:Horde"]="作为部落的一员，你看到被遗忘者的飞行航线让补给和信使迅速穿行于战火纷飞的洛丹伦。",["race:Undead"]="作为一名Undead，你知道从首都运来的每一批刀剑和装备，都有助于守住Sylvanas女士在银松森林岌岌可危的边疆。"},sec={{t="运往银松森林的补给",b="被遗忘者不断从幽暗城运来补给，以守住银松森林。高顿的箱子里装着武器，要交给亡灵卫兵博迪瑞格麾下驻守瑟伯切尔的守军。哨站的卫兵面对着林中的狼人、野兽和人类残部。"},{t="蝙蝠管理员的航线",b="从首都出发的陆路危险而耗时，因此贵重货物都由幽暗城的蝙蝠管理员运送。高顿的箱子被交给迈克尔·加勒特，他是位于城内贸易区上方的蝙蝠管理员。他安排一只训练有素的飞行蝙蝠，将箱子运回瑟伯切尔的卡洛斯·拉佐克的蝙蝠栖所。"}},faq={{q="高顿的箱子里装着什么？",a="高顿的箱子里装着从幽暗城征调的武器和重要作战物资，用来支援银松森林的亡灵卫兵哨兵。",al={"高顿的箱子里的物品","箱子里装着什么"}},{q="高顿的箱子应该交给谁？",a="高顿的箱子应交给瑟伯切尔的亡灵卫兵博迪瑞格。幽暗城的蝙蝠管理员迈克尔·加勒特负责安排空运。",al={"高顿的箱子交给谁","箱子运往哪里"}},{q="为什么箱子要由蝙蝠运送，而不是交给步行的信使？",a="银松森林依然争战不休，危机四伏。由迈克尔·加勒特和卡洛斯·拉佐克照管的受训蝙蝠能从空中迅速运送货物，避开地面道路沿途的威胁。",al={"为何空运箱子","蝙蝠运输箱子"}},{q="为什么迈克尔·加勒特要求你先去一趟瑟伯切尔？",a="被遗忘者的蝙蝠会本能地返回首都。要让它们安全飞往瑟伯切尔这样的偏远基地，你必须先与当地的蝙蝠管理员卡洛斯·拉佐克建立联系。",al={"为何需要飞行路线","蝙蝠飞行条件"}}},fp="14,148,23.233.0,23.282.0,30.142.0,42.134.0,65.191.0,66.192.0"}
P.entries["item:grape-manifest"] = {n="葡萄出货单",s="在北郡修道院，米莉·奥斯沃斯被强盗夺走的收成已被夺回，即将运入库房。",h="在北郡修道院，米莉·奥斯沃斯被强盗夺走的收成已被夺回，即将运入库房。",kw={"尼尔斯修士","艾尔文","葡萄出货单","米莉·奥斯沃斯","北郡修道院","葡萄园","葡萄酒"},ang={["profession:Cooking"]="身为厨师，你能看出田间的收成如何充实修道院的储备，帮助养活这里的修士。",["race:Human"]="身为人类，你见证了暴风城腹地早期的艰难处境。即使是修道院的生活和寻常的收成，也需要武力保护，才能抵御四处游荡的匪徒。"},sec={{t="收成的记录",b="北郡修道院的食物和饮品依靠附近的农场供应。收成丢失，让修道院的储备陷入了危机。如今，货箱已被夺回，军需官们可以调配物资，备好木桶用于发酵。米莉·奥斯沃斯的出货单记下了数量，供他们安排。"},{t="修道院的酒窖管事",b="尼尔斯修士负责管理北郡修道院的食物和饮品。他喜欢在安静的钟楼里品尝修道院的葡萄酒。得知葡萄即将运来，他便能安排好修士和来访新兵的饮品供应。每挽回一蒲式耳葡萄，都能充实修道院的储备，并带来圣光的祝福。"}},faq={{q="葡萄出货单是什么？",a="米莉·奥斯沃斯的葡萄出货单记录了从她那被占据的葡萄园中夺回的收成。单上记载着将运往北郡修道院的新鲜葡萄。",al={"葡萄出货单是什么","葡萄出货单物品"}},{q="谁接收出货单？",a="尼尔斯修士接收米莉·奥斯沃斯的出货单。他负责管理修道院的食物和葡萄酒储备，也常在北郡修道院的钟楼里品酒。",al={"谁接收葡萄出货单","葡萄出货单交给谁","葡萄出货单送往哪里"}},{q="葡萄为何面临危险？",a="迪菲亚强盗把米莉·奥斯沃斯赶出了她在北郡山谷的葡萄园。收成岌岌可危，修道院也断了新鲜水果的供应，直到新兵们出手相助。",al={"葡萄为何需要抢救","葡萄园强盗","米莉 的收成怎么了"}},{q="尼尔斯修士用葡萄做什么？",a="尼尔斯修士用这些葡萄补充修道院的食物储备，并酿造新一批北郡葡萄酒。这些酒供常住的修士和来访的守卫饮用。",al={"葡萄有什么用途","修道院葡萄酒"}}},fx={a2f30a46={q="葡萄出货单来自哪里，是谁写的？",a="这份出货单由米莉·奥斯沃斯拟定，她是一位在北郡山谷经营葡萄园的农夫。你帮助她击退侵占田地的迪菲亚强盗，夺回收获的葡萄后，她便写下这份记录，记载保住的收成。",al={"谁写了葡萄出货单","葡萄出货单来自哪里","葡萄出货单来历"}},cbb35726={q="为什么需要葡萄出货单？",a="尼尔斯修士负责管理北郡修道院的食物和饮料储备。米莉送出这份出货单，是为了通知他，收成已从强盗手中夺回，修道院的酿酒师可以指望用新鲜葡萄榨汁酿酒了。",al={"尼尔斯修士为什么要葡萄出货单","葡萄出货单用途","为什么需要葡萄出货单"}}},fp="14,104,23.282.0,20.303.0,27.142.0,26.154.0,30.162.0,43.168.0"}
P.entries["item:gray-bear-tongue"] = {n="灰熊的舌头",s="在希尔斯布莱德丘陵，灰熊舌头是塔伦米尔的皇家药剂师学会为研制试验性毒素而收集的原料。",h="在希尔斯布莱德丘陵，灰熊舌头是塔伦米尔的皇家药剂师学会为研制试验性毒素而收集的原料。",kw={"药剂师林度恩","萨姆拉斯","受难药剂","灰熊的舌头","希尔斯布莱德丘陵","皇家药剂师学会","塔伦米尔"},ang={["race:Undead"]="身为亡灵，你从当地野生动物身上收集有机材料，帮助皇家药剂师学会研制针对活人的新瘟疫。"},sec={{t="希尔斯布莱德的药剂研究",b="塔伦米尔周围的荒野上游荡着几种体格健壮的灰熊。它们的舌头含有厚实的肌肉组织和体液，药剂师林度恩将这些用作配制致命药液的基础原料，其中就包括受难药剂。"}},faq={{q="谁需要灰熊舌头？",a="药剂师林度恩驻守在希尔斯布莱德丘陵的被遗忘者前哨塔伦米尔，正在收集灰熊舌头，用来调制试验性的致命药剂。",al={"谁需要熊舌头","药剂师林度恩舌头","熊舌头交给谁"}},{q="药剂师用这些舌头做什么？",a="林度恩将灰熊舌头用作受难药剂的主要有机成分之一，这种致命药剂旨在帮助瘟疫侵袭希尔斯布莱德尚在人世的人类居民。食苔蛛的毒液是另一种原料。",al={"林度恩为什么要舌头","熊舌头用途","受难药剂原料"}},{q="哪些生物会掉落这些舌头？",a="灰熊舌头来自游荡在希尔斯布莱德丘陵的当地灰熊，包括普通灰熊、老灰熊、凶恶的灰熊，以及臭名昭著的野兽萨姆拉斯。",al={"哪里掉落熊舌头","哪些熊有舌头","希尔斯布莱德的熊"}}},fx={["57051fe5"]={q="什么是灰熊的舌头？",a="它就是字面上的意思：从希尔斯布莱德丘陵四处游荡的野生灰熊身上刚割下来的舌头。大多数旅行者对此毫无兴趣，但被遗忘者中的炼金师和研究人员在调制新药剂时，会看重动物组织特有的化学性质。",al={"什么是灰熊的舌头","灰熊的舌头物品"}},["4de594f1"]={q="灰熊的舌头来自哪里？",a="这些舌头直接取自希尔斯布莱德丘陵塔伦米尔周围森林和山丘上的灰熊。猎人可以从普通灰熊、年长的灰熊、凶猛的变种，或大萨姆拉斯这类知名野兽身上取得舌头。",al={"灰熊的舌头来源","灰熊的舌头来自哪里","谁会掉落灰熊的舌头"}}},fp="16,112,32.187.0,28.112.0,47.207.0,35.162.0"}
P.entries["item:gregor-s-remains"] = {n="格里高的遗骸",s="库勒曼·法席恩正在寻找格里高的遗骸，以清算一笔旧账。这些骸骨属于格里高·阿加曼德，他曾是提瑞斯法林地最富有家族的一员。",h="库勒曼·法席恩正在寻找格里高的遗骸，以清算一笔旧账。这些骸骨属于格里高·阿加曼德，他曾是提瑞斯法林地最富有家族的一员。",kw={"阿加曼德","布瑞尔","库勒曼","阿加曼德家族","法席恩","格里高","磨坊","遗骸","天灾军团"},ang={["faction:Horde"]="清剿阿加曼德磨坊，可以打击仍在威胁提瑞斯法林地的Scourge势力。",["race:Undead"]="阿加曼德家族的悲剧映照着许多被遗忘者的命运：平民遭到贵族傲慢的背叛，被遗弃在Plague的恐怖之中。"},sec={{t="毁灭的遗产",b="第三次大战之前，阿加曼德家族在提瑞斯法林地北部拥有巨额财富和广袤土地。天灾军团入侵洛丹伦时，家族的掌权者出于傲慢，选择拒绝逃离。他们加固了磨坊，并敦促忠诚的劳工留下来抵抗亡灵。防守失败了。庄园沦陷，坚守的人们惨遭屠戮，又被复活为亡灵。格里高·阿加曼德沦为巫妖王麾下没有心智的仆从，在家族昔日统治的磨坊间游荡。"},{t="复仇的代价",b="一些摆脱巫妖王控制的人加入了被遗忘者，但那场防守的记忆仍在刺痛他们。库勒曼·法席恩曾是磨坊的工人，如今驻留在布瑞尔，他将自己的灵魂困于永恒腐朽的命运归咎于阿加曼德家族的傲慢。法席恩寻求格里高的遗骸，是为了向那个将自家上下引向毁灭的主人报私仇。"}},faq={{q="格里高·阿加曼德是谁？",a="格里高·阿加曼德是阿加曼德家族的重要成员，这个家族是第三次大战之前提瑞斯法林地最富有的地主家族。亡灵瘟疫来袭时，他和家人选择加固庄园，而非逃离。天灾军团屠杀了庄园内的所有人，又将他们复活为亡灵。",al={"格里高的故事","格里高是谁","格里高·阿加曼德"}},{q="库勒曼·法席恩为什么想要格里高的遗骸？",a="库勒曼·法席恩曾在阿加曼德家族的磨坊工作。他怨恨这个家族，因为他们说服工人留下来对抗天灾军团，而这个选择让所有人都沦为了亡灵。他寻找格里高的遗骸，是为了完成这场迟来的复仇。",al={"库勒曼为何想要遗骸","库勒曼·法席恩的怨恨","为何收集格里高的骸骨"}},{q="在哪里能找到格里高的遗骸？",a="提瑞斯法林地北部山丘中的阿加曼德磨坊里，复活后的格里高·阿加曼德身上可以取得这些遗骸。",al={"哪里能找到格里高","格里高的位置","阿加曼德磨坊的格里高"}},{q="阿加曼德家族是被遗忘者的一员吗？",a="不是。格里高·阿加曼德及其亲族仍是受天灾军团束缚、没有心智的仆从，与在希尔瓦娜斯女王领导下挣脱控制的被遗忘者不同。",al={"格里高是被遗忘者吗","阿加曼德家族属于天灾军团吗","谁控制着格里高"}}},fp="16,123,16.482.0,22.346.0,23.279.0,48.232.0,33.109.0,38.134.0"}
P.entries["item:grelin-s-report"] = {n="格瑞林的报告",s="在寒脊山谷，格瑞林的报告将有关霜鬃巨魔的消息送往卡拉诺斯。它将安威玛尔的斥候与森内尔·白须和铁炉堡联系起来。",h="在寒脊山谷，格瑞林的报告将有关霜鬃巨魔的消息送往卡拉诺斯。它将安威玛尔的斥候与森内尔·白须和铁炉堡联系起来。",kw={"寒脊山谷","格瑞林·白须","格瑞林的报告","铁炉堡参议院","卡拉诺斯","巡山人萨鲁斯","森内尔·白须"},ang={["race:Dwarf"]="身为矮人，递送这份报告会让你离开寒脊安全的训练场，进入丹莫罗腹地，为铁炉堡效力。",["race:Gnome"]="身为侏儒难民，递送格瑞林的消息，让你在穿越丹莫罗各族共用的山间小径时，向矮人巡山人证明自己的实力。"},sec={{t="穿越穴居人封锁的急件",b="格瑞林·白须一直在寒脊山谷监视霜鬃巨魔，认为它们构不成多大威胁。已经驻扎在当地的巡山人，加上由参议院出资雇用的佣兵，足以应付它们。因此，格瑞林将报告托付给了一位能干的旅人，而不是他那笨手笨脚的学徒。这趟旅程要穿过穴居人盘踞的寒脊山小径。\n\n这份文件向巡山人萨鲁斯证明，你身负紧急公务。有了它，你就能通过他的封锁，进入丹莫罗白雪皑皑的群山。"},{t="在卡拉诺斯惹起不满",b="在卡拉诺斯的雷酒酿制厂，森内尔·白须收到了格瑞林呈交铁炉堡的实地报告。他的兄弟在整份文件中处处搬出国王麦格尼·铜须的名号，森内尔对此既觉得好笑，又有些无奈。格瑞林声称自己的行动得到了国王的许可。森内尔料想，这种借助王权的做法会引起铁炉堡参议院的不满。"}},faq={{q="格瑞林的报告有什么用途？",a="格瑞林的报告将格瑞林·白须对霜鬃巨魔的评估，从寒脊山谷送交卡拉诺斯的森内尔。报告指出，它们构不成多大威胁，当地的巡山人和由参议院出资雇用的佣兵足以应付。",al={"格瑞林的报告是什么","为什么要送报告","格瑞林报告的用途"}},{q="格瑞林为什么不能亲自送信？",a="格瑞林留在寒脊山谷监视巨魔。他起初考虑过派学徒送信，但隧道中穴居人盘踞，通行危险，因此他将文件托付给了一位久经沙场的旅人。",al={"为什么不亲自送信","为什么托付给冒险者"}},{q="为什么带着报告，巡山人萨鲁斯就会让你通过？",a="巡山人萨鲁斯把守着通往寒脊山谷外的隧道，保护平民免遭凶恶的穴居人袭击。格瑞林的报告证明，你正在执行关乎矮人防务的紧急公务，因此萨鲁斯准许你通过。",al={"萨鲁斯为什么放行","隧道封锁","寒脊山小径的穴居人"}},{q="铁炉堡参议院为什么对报告感到不满？",a="森内尔·白须说，格瑞林在整份报告中处处搬出麦格尼国王的名号。虽然兄弟二人都认为铁炉堡的政客们需要被敲响警钟，但森内尔料想，格瑞林借助王权的做法会引起参议院的不满。",al={"参议院为什么不满","惹起不满","森内尔的反应"}}},fx={cdcce173={q="什么是格瑞林的报告？",a="这是一份由格瑞林·白须在寒脊山谷撰写的书面报告，收件人是住在卡拉诺斯的兄弟森内尔·白须。报告详细记录了山谷里的见闻和亟待处理的事务。不过，格瑞林在报告中频繁搬出国王麦格尼·铜须的名号，足以让铁炉堡的参议员们对此议论纷纷。",al={"什么是格瑞林的报告","格瑞林的报告"}},["9a092709"]={q="格瑞林的报告从何而来？是谁写的？",a="这份文件由驻守寒脊山谷的格瑞林·白须起草。格瑞林没有把它托付给自己的学徒，而是决定交给一位可靠的旅行者，确保报告能安全地向东穿过通往丹莫罗腹地、遍布穴居人的隧道。",al={"谁写了格瑞林的报告","格瑞林的报告从何而来","谁制作了格瑞林的报告"}},["6be6ebf1"]={q="为什么有人需要格瑞林的报告？",a="他的兄弟森内尔·白须正在卡拉诺斯等候这份报告，以便汇总两人的发现，再将合并后的报告送往铁炉堡。这份文件对你本人也至关重要：出示白须家族公务的证明，是巡山人萨鲁斯允许你通过离开寒脊山谷、危机四伏且穴居人横行的隧道的唯一理由。",al={"为什么需要格瑞林的报告","森内尔为什么需要格瑞林的报告"}}},fp="15,155,26.493.0,29.370.0,39.233.0,36.218.0,57.195.0,50.236.0"}
P.entries["item:grelin-whitebeard-s-journal"] = {n="格瑞林·白须的日记",s="格瑞林·白须在寒脊山谷的一本野外日记中记录霜鬃巨魔的活动。冷酷的格瑞克尼尔偷走了日记，并将它带进了巨魔洞穴。",h="格瑞林·白须在寒脊山谷的一本野外日记中记录霜鬃巨魔的活动。冷酷的格瑞克尼尔偷走了日记，并将它带进了巨魔洞穴。",kw={"寒脊山谷","丹莫罗","霜鬃巨魔要塞","格瑞林·白须","冷酷的格瑞克尼尔","森内尔·白须","被盗的日记"},ang={["race:Dwarf"]="身为矮人，找回格瑞林的日记，就能保住有关铁炉堡训练场附近霜鬃威胁的重要情报。"},sec={{t="斥候的记录簿",b="格瑞林·白须监视着寒脊山谷附近的霜鬃巨魔，记下他们的一举一动。他的皮面笔记本记录了他们的实力、组织状况以及构成的威胁。冷酷的格瑞克尼尔在一次冲突或伏击中夺走了日记。这个身上带有印记的巨魔蛮兵将日记带进了巨魔洞穴，使格瑞林失去了完成报告所需的笔记。于是，他请路过的冒险者找回这本日记。"},{t="送往森内尔的急报",b="格瑞林·白须研究了找回的笔记，认为寒脊山谷的霜鬃威胁暂时得到了遏制。他根据这些随手记下的内容，完成了一份关于霜鬃暴动的急报。信使将密封的信件送往他兄弟森内尔·白须手中，森内尔驻守在丹莫罗的另一处。"}},faq={{q="谁偷走了格瑞林·白须的日记？",a="冷酷的格瑞克尼尔偷走了格瑞林·白须的日记。这个身上布满印记的霜鬃巨魔蛮兵将日记带进了寒脊山谷的巨魔洞穴。",al={"谁拿走了日记","格瑞林的日记在谁手里","偷走格瑞林日记的窃贼"}},{q="日记里写了什么？",a="格瑞林·白须的日记中记载着有关当地霜鬃巨魔、他们构成的威胁以及寒脊山谷安全状况的野外笔记。",al={"日记内容","日记里有什么","格瑞林·白须的笔记"}},{q="找回日记后会发生什么？",a="格瑞林利用找回的笔记，完成了一份关于巨魔的报告。他请一位冒险者将报告送给他的兄弟森内尔·白须。",al={"格瑞林用日记做什么","日记被盗之后"}},{q="这本日记为什么对格瑞林如此重要？",a="格瑞林需要这本日记，才能为矮人当局和他的兄弟森内尔准备一份关于霜鬃暴动的准确报告。没有它，寒脊山谷的防御状况就难以确定。",al={"格瑞林为什么想找回日记","日记的重要性"}}},fx={["15978139"]={q="格瑞林·白须的日记是什么？",a="这是驻守寒脊山谷的观察员格瑞林·白须随身记录的私人笔记。格瑞林在其中记下对当地霜鬃巨魔活动的观察结果，并撰写实地报告，详述山谷的防御状况。",al={"格瑞林·白须的日记是什么","格瑞林的日记","格瑞林的笔记本"}},["9ed18e74"]={q="格瑞林·白须的日记来自哪里，是谁写的？",a="这本日记是矮人格瑞林·白须在监视寒脊山谷期间亲手编写的。然而，霜鬃恶徒冷酷的格瑞克尼尔从他手中抢走了日记，将它带进了附近巨魔洞穴的深处。",al={"谁写了格瑞林的日记","格瑞林的日记来自哪里","格瑞林的日记来历"}}},fp="27,163,16.436.0,17.302.1,38.142.0,31.134.0,44.133.1,43.198.0"}
P.entries["item:grell-earring"] = {n="劣魔耳环",s="在巴莎兰，劣魔耳环上留有束缚阿斯特利安的封印痕迹。",h="在巴莎兰，劣魔耳环上留有束缚阿斯特利安的封印痕迹。",kw={"阿斯特利安","巴莎兰","黑海岸","劣魔耳环","封印","恶灵劣魔","野生劣魔"},ang={["class:Mage"]="身为法师，你能看出，金属可能会在漫长岁月中留存周围古老防护封印散发的魔力。",["race:NightElf"]="身为暗夜精灵，你看到神圣的废墟被佩戴着拾荒所得黄铜饰物的小妖精占据，不禁想起古代卡利姆多那些曾经宏伟的庄园如今已衰败到何种地步。"},sec={{t="黄铜中的痕迹",b="巴莎兰的野生劣魔和恶灵劣魔在废墟中搜集碎片，用来制作耳环。大多数凡人只把它们看作毫无价值的小饰物。阿斯特利安是一位古老的暗夜精灵，被束缚在此，化作饱受折磨的幽魂，他研究着耳环上残留的魔法。他希望这些痕迹能指引他找到囚禁自己的古老封印。"}},faq={{q="劣魔耳环从何而来？",a="黑海岸的巴莎兰是一处已成废墟的暗夜精灵聚居地，那里的野生劣魔和恶灵劣魔携带着这些耳环。",al={"劣魔耳环掉落","哪里获取劣魔耳环","谁掉落劣魔耳环"}},{q="阿斯特利安为何想要这些耳环？",a="阿斯特利安是一个被强大魔法囚禁在巴莎兰的古老灵魂。他利用这些耳环，寻找将自己的灵魂束缚了数百年的封印痕迹。",al={"阿斯特利安耳环","为何收集劣魔耳环","劣魔耳环用途"}},{q="耳环如何帮助阿斯特利安寻找封印？",a="阿斯特利安希望对耳环施法，追踪将他的幽魂形态囚禁在巴莎兰的封印。",al={"耳环有魔法吗","劣魔懂魔法吗"}},{q="阿斯特利安从耳环中找到了他需要的东西吗？",a="封印并不在耳环中。耳环上的痕迹表明，这些生物最近曾靠近封印，指引着阿斯特利安向废墟更深处寻找。",al={"耳环起作用了吗","阿斯特利安封印位置"}}},fp="13,75,19.322.0,34.120.0,38.141.0,54.116.0,51.146.0"}
P.entries["item:grenka-s-claw"] = {n="格林卡的爪子",s="格林卡的爪子是从飞羽洞穴深处强悍的鹰身人格林卡·血啸身上取得的实物战利品。将它交给老屋的多恩·平原行者，就能确凿地证明，一名胸怀抱负的冒险者已经在峡谷高处经受住了艰苦的体能试炼。",h="格林卡的爪子是从飞羽洞穴深处强悍的鹰身人格林卡·血啸身上取得的实物战利品。将它交给老屋的多恩·平原行者，就能确凿地证明，一名胸怀抱负的冒险者已经在峡谷高处经受住了艰苦的体能试炼。",kw={"多恩·平原行者","格林卡·血啸","格林卡的爪子","鹰身人","飞羽洞穴","尖啸峡谷","耐力的试炼","千针石林","老屋"},ang={["faction:Horde"]="扫清飞羽洞穴深处的敌人并除掉格林卡·血啸，能削弱鹰身人的威胁，它们一直在袭扰乱风岗周围的旅人。",["race:Tauren"]="多恩·平原行者长者将此视为自己的神圣职责：在年轻的部落勇士踏入更广阔、更严酷的世界之前，以牛头人仪式中的智慧与坚韧磨炼他们。"},sec={{t="耐力的见证",b="乱风岗以西，飞羽洞穴蜿蜒的洞窟中，鹰身人囤积着食物，并凶狠地抵御闯入领地的外来者。为了考验年轻勇士的身体耐力，多恩·平原行者要求他们深入巢穴，摧毁鹰身人储藏的食物。如此大胆的挑衅必然会激起格林卡·血啸的怒火。斩下她的利爪并带回，就能证明一名勇士足以抵挡一波又一波暴怒的鹰身人，并在它们女首领的凶猛攻势下存活。"}},faq={{q="格林卡的爪子有什么用途？",a="这只爪子是交给多恩·平原行者的胜利凭证，这位牛头人长者居住在千针石林的老屋。将它交给他，就能完成耐力的试炼，表明你拥有在持久战中生存所需的强健体魄与韧性。",al={"格林卡的爪子用途","为什么需要格林卡的爪子","格林卡的爪子任务"}},{q="格林卡·血啸是谁？",a="格林卡·血啸是一名强大的鹰身人，栖息在飞羽洞穴中，那里位于千针石林南部峭壁沿线的尖啸峡谷。只有当入侵者摧毁储藏的食物、威胁到族群时，她才会现身。",al={"格林卡是谁","格林卡·血啸背景故事","格林卡是什么"}},{q="拿到爪子后，该交到哪里？",a="将爪子带回给千针石林峭壁间老屋的多恩·平原行者。他会收下这件战利品，确认你已经通过了身体耐力的试炼。",al={"格林卡的爪子交到哪里","谁需要格林卡的爪子"}},{q="多恩·平原行者为什么指定要这件战利品？",a="多恩·平原行者引导年轻旅者接受严苛的试炼，确保他们在心智、精神和体魄上都做好准备，迎接更大的危险。杀死格林卡并取得她的爪子，就能证明一名勇士既能承受成群敌人的伏击，也能抵挡致命首领的正面猛攻。",al={"多恩为什么要爪子","爪子的用途"}}},fx={cd538a11={q="什么是格林卡的爪子？",a="格林卡的爪子是从格林卡·血啸身上取得的实物战利品。她是一只强大的鹰身人，栖身于尖啸峡谷深处的飞羽洞穴。激怒她的族群并从其怒火下幸存后，你从这只凶恶的生物身上割下了这只爪子。它是无可辩驳的证明，表明一名有志成为冒险者的人拥有足够的耐力和战斗本领，能够经受住一场残酷的战斗考验。",al={"格林卡的爪子","什么是格林卡的爪子","关于格林卡的爪子"}}},fp="13,207,21.408.0,31.187.0,27.199.0,42.163.0,55.244.0"}
P.entries["item:grimtotem-satchel"] = {n="恐怖图腾背包",s="在奥格瑞玛地下深处，恐怖图腾背包仍被玛尔·恐怖图腾紧紧攥着。石腭怪在怒焰裂谷杀死了这名牛头人，但他直到临死仍护着这个背包。背包被送回雷霆崖，也让玛加萨·野性图腾对此的关注浮出水面。",h="在奥格瑞玛地下深处，恐怖图腾背包仍被玛尔·恐怖图腾紧紧攥着。石腭怪在怒焰裂谷杀死了这名牛头人，但他直到临死仍护着这个背包。背包被送回雷霆崖，也让玛加萨·野性图腾对此的关注浮出水面。",kw={"长者高地","恐怖图腾","玛加萨·野性图腾","玛尔·恐怖图腾","怒焰裂谷","拉哈罗","背包","雷霆崖","石腭怪"},ang={["faction:Horde"]="一名恐怖图腾信使死在萨尔都城地下的隧道深处。怒焰裂谷中的危险远不止那些野兽。",["race:Tauren"]="一名恐怖图腾成员深入奥格瑞玛地下，随后，他有所发现的消息传到了长者高地的玛加萨耳中。在联合起来的牛头人各部族之中，这个氏族行事隐秘，令人不安。"},sec={{t="至死紧握",b="玛尔·恐怖图腾在奥格瑞玛地下的怒焰裂谷深处死于石腭怪之手。尸体被发现时，这名牛头人仍紧紧抱着那个简陋的皮背包。石腭怪包围了他，他奋力保护着背包。里面究竟装着什么，竟让他以性命守护？"},{t="老妪的关注",b="雷霆崖长者高地的拉哈罗替恐怖图腾氏族的女族长玛加萨·野性图腾收下背包。玛尔效命于玛加萨，她已经得知，他死前在奥格瑞玛地下的洞穴中发现了某种奇特的东西。她为安全送回背包的人准备了酬劳。这位恐怖图腾领袖显然很在意玛尔的发现。"}},faq={{q="恐怖图腾背包在哪里找到？",a="恐怖图腾背包是在玛尔·恐怖图腾的尸体下找到的，地点位于奥格瑞玛地下的火山洞穴——怒焰裂谷深处。在石腭怪杀死他的地方，他的双臂仍抱着背包。",al={"背包位置","背包在哪里","如何找到背包"}},{q="这个背包属于谁？",a="背包属于玛尔·恐怖图腾，他是进入怒焰裂谷的一名恐怖图腾氏族成员。石腭怪袭击时，他紧紧抱着背包。",al={"背包属于谁","玛尔背包主人"}},{q="谁想要取回背包？",a="雷霆崖长者高地的拉哈罗替玛加萨·野性图腾收下背包。玛加萨为送回这位死去族人遗物的人准备了酬劳。",al={"背包交给谁","谁交还背包","谁想要恐怖图腾背包"}},{q="为什么一名恐怖图腾成员会在奥格瑞玛地下带着这个背包？",a="玛尔·恐怖图腾效命于玛加萨·野性图腾，后者对怒焰裂谷颇为关注。他前去与石腭怪交谈，并发现了某种奇特的东西，却没能活着将它带给她看。",al={"玛尔为什么在怒焰裂谷","恐怖图腾在奥格瑞玛做什么"}},{q="背包里装着什么？",a="拉哈罗在雷霆崖收到背包时，袋口仍封着。玛加萨希望里面有线索，能揭示玛尔在裂谷中的奇特发现。",al={"背包内的物品","包里有什么"}}},fp="17,225,12.266.0,26.343.1,37.178.0,31.135.0,31.165.0,50.190.0,27.153.0"}
P.entries["item:grizzled-bear-heart"] = {n="灰熊的心脏",s="在银松森林，健壮的熊提供的心脏被用于皇家药剂师学会对新的瘟疫的研究。",h="在银松森林，健壮的熊提供的心脏被用于皇家药剂师学会对新的瘟疫的研究。",kw={"死亡配方","药剂师伦弗利尔","灰熊的心脏","大药剂师法拉尼尔","新的瘟疫","维斯迦尔","皇家药剂师学会","银松森林","粘稠的血液"},ang={["class:Hunter"]="作为猎人，你追踪银松森林中包括维斯迦尔在内的巨熊，寻找生物样本，这考验着你的耐心与野外剖取技巧。",["race:Undead"]="作为被遗忘者的一员，采集这些器官能直接帮助大药剂师法拉尼尔研制武器，对抗阿尔萨斯麾下的Scourge，以及威胁洛丹伦的活人。"},sec={{t="新的瘟疫的试剂",b="皇家药剂师学会日夜不停地研制一种瘟疫，意图将天灾军团与活着的人类一并灭绝。在银松森林的林地中，药剂师伦弗利尔发现，灰熊心脏中的毒素与蛛类体液混合后，能制成极其致命的药剂。信使与效忠被遗忘者的人猎杀凶猛的灰熊、巨型灰熊，以及四处游荡的野兽维斯迦尔。他们挖出心脏，送往幽暗城深处的炼金房，交给大药剂师法拉尼尔。"}},faq={{q="灰熊的心脏有什么用途？",a="皇家药剂师学会将灰熊的心脏用作实验性的生物试剂。药剂师伦弗利尔发现，这些心脏中的毒素可以提炼成致命的药剂，帮助被遗忘者研制新的瘟疫。",al={"熊心有什么用","熊心任务","死亡的配方试剂"}},{q="谁需要这些熊心？",a="银松森林的药剂师伦弗利尔指引旅者收集这些心脏和粘稠的血液，并将它们送往幽暗城的炼金房，交给大药剂师法拉尼尔。",al={"谁需要熊心","大药剂师法拉尼尔熊心","熊心交给谁"}},{q="灰熊的心脏从哪里来？",a="灰熊的心脏来自银松森林中游荡的熊，包括凶猛的灰熊、巨型灰熊，以及四处游荡的野兽维斯迦尔。",al={"哪里能找到熊心","哪些熊掉落心脏","熊心位置"}},{q="皇家药剂师学会为什么需要天然的动物毒素？",a="皇家药剂师学会寻找能够污染并摧毁活体血肉及亡灵生理机能的生物制剂。银松森林中健壮的熊，其心脏组织具有独特的化学性质，与剧毒的蜘蛛血液混合后，便能提供理想的反应基质。",al={"药剂师为什么使用熊的毒素","为什么用动物心脏研制瘟疫"}}},fp="19,114,28.520.0,39.234.0,28.188.0,40.156.0,65.274.0"}
P.entries["item:grizzled-scalp"] = {n="灰色头皮",s="在黑海岸南部，灰斑蓟熊 出没于奥伯丁以南的森林中。它们厚实的毛皮被送到侏儒工匠维兹班恩·曲针手里，他自有用途。",h="在黑海岸南部，灰斑蓟熊 出没于奥伯丁以南的森林中。它们厚实的毛皮被送到侏儒工匠维兹班恩·曲针手里，他自有用途。",kw={"奥伯丁","传声盒525","黑海岸","灰色头皮","灰斑蓟熊","蓟熊 啤酒","维兹班恩·曲针"},ang={["profession:Engineering"]="身为工程师，你能看出侏儒如何凭借技艺，将自动酿酒蒸馏器伪装成野外维修用的通信阵列。",["race:NightElf"]="身为暗夜精灵，你保护黑海岸的野生动物，对肆意偷猎和藏在荒野中的侏儒蒸馏器颇有微词。"},sec={{t="奇特的发酵",b="灰斑蓟熊出没于奥伯丁以南的道路一带，猎人们十分看重它们粗糙的毛皮。将四块头皮带到传声盒525，用途便一目了然。这些熊的毛皮既不是用来修补，也不是用来研究的。维兹班恩·曲针将散布在黑海岸各处的隐蔽传声盒当作蒸馏器。暗夜精灵不赞成在自己的聚居地私自酿酒，因此维兹班恩·曲针依靠冒险者收集熊的头皮和其他古怪原料，酿造他心爱的蓟熊啤酒。"}},faq={{q="在哪里可以找到灰色头皮？",a="沿着黑海岸的主路，在奥伯丁以南的森林中，可以找到 灰斑蓟熊 和它们的雌性首领雌蓟熊。",al={"灰色头皮位置","谁掉落灰色头皮","蓟熊 头皮"}},{q="灰色头皮有什么用途？",a="将头皮放入传声盒525。这台机械终端藏在奥伯丁南方远处路旁的灌木丛中。",al={"灰色头皮用途","灰色头皮怎么用"}},{q="传声盒525为什么需要熊的头皮？",a="维兹班恩·曲针利用隐蔽的 传声盒 网络蒸馏烈酒，避开暗夜精灵的耳目。这些头皮是他酿造 蓟熊 啤酒的原料。",al={"维兹班恩·曲针为什么要头皮","传声盒525用途"}},{q="维兹班恩·曲针为什么躲在黑海岸的荒野中酿酒？",a="维兹班恩·曲针将蒸馏器藏在荒野的灌木丛中，因为奥伯丁的暗夜精灵反对有人未经许可，在他们神圣的林地里吵吵闹闹地酿酒。这些隐蔽的装置让他的私酿生意得以避人耳目。",al={"为什么藏起 传声盒","维兹班恩·曲针 烈酒 黑海岸"}}},fp="14,129,23.410.1,33.127.0,34.117.0,38.137.1,60.214.1"}
P.entries["item:gryshka-s-letter"] = {n="格雷什卡的信",s="旅店老板格雷什卡收到鲜肉后，写信向十字路口的扎尔夫致谢。这封信也让年轻的部落信使了解了驭风者飞行网络。",h="旅店老板格雷什卡收到鲜肉后，写信向十字路口的扎尔夫致谢。这封信也让年轻的部落信使了解了驭风者飞行网络。",kw={"贫瘠之地","十字路口","多拉斯","格雷什卡","格雷什卡的信","肉","奥格瑞玛","驭风者","扎尔夫"},ang={["faction:Horde"]="递送格雷什卡的信，会让年轻的部落冒险者了解连接杜隆塔尔和贫瘠之地的双足飞龙飞行管理员网络。"},sec={{t="旅店老板的谢意",b="旅店老板格雷什卡感谢扎尔夫从贫瘠之地送来牛排，供应奥格瑞玛的中心酒馆。她提起他准备肉食时失去一根手指的往事，又打趣说，即使干活时沾了一身血，他依然英俊。"},{t="飞行航线上的信使",b="要将格雷什卡的信送回十字路口，你需要先向奥格瑞玛高台上的驭风者管理员多拉斯报到。向他证明你已经在十字路口的迪弗拉克那里报到过，多拉斯便会向年轻的信使介绍连接杜隆塔尔和贫瘠之地各处定居点的双足飞龙航线。"}},faq={{q="格雷什卡的信是谁写的？",a="旅店老板格雷什卡在奥格瑞玛的力量谷经营着一家酒馆，收到鲜肉后写下了这封信。",al={"谁写的","格雷什卡信件作者","寄信人"}},{q="这封信是写给谁的？",a="这封信是写给扎尔夫的，他是贫瘠之地十字路口的一名屠夫，曾为格雷什卡供应肉食。",al={"收信人","格雷什卡的信写给谁","信送到哪里"}},{q="信里写了什么？",a="格雷什卡感谢扎尔夫送来的肉，提起他准备肉食时意外失去一根手指的往事，还打趣说，即使沾了一身血，他依然英俊。",al={"信件原文","格雷什卡说了什么","信件内容"}},{q="为什么要让多拉斯看这封信？",a="多拉斯是奥格瑞玛的驭风者管理员。格雷什卡让你去向他证明，你已经在十字路口的迪弗拉克那里报到过，这样多拉斯就能向你介绍双足飞龙航线。",al={"为什么给多拉斯看","驭风者管理员多拉斯","奥格瑞玛飞行管理员"}}},fp="16,165,20.205.0,30.294.0,27.119.0,31.108.0,34.137.0,38.176.0"}
P.entries["item:gunther-s-spellbook"] = {n="冈瑟尔的法术书",s="如今，比索的附魔已在提瑞斯法林地的冈瑟尔的法术书上留下了印记。这本书或许能让它的主人知道，还有其他法师摆脱了巫妖王的控制。",h="如今，比索的附魔已在提瑞斯法林地的冈瑟尔的法术书上留下了印记。这本书或许能让它的主人知道，还有其他法师摆脱了巫妖王的控制。",kw={"阿坎努斯","比索","达拉然","冈瑟尔","埃斯沙德","肯瑞托","法术书","提瑞斯法"},ang={["class:Mage"]="身为法师，你与被遗忘者的魔法领袖，以及那些独自在荒野中游历的施法者，都有着源自达拉然的奥术传承。",["race:Undead"]="身为亡灵，你知道被遗忘者正在寻找那些摆脱了巫妖王控制的强大亡灵。"},sec={{t="旧日情谊的信物",b="冈瑟尔·阿坎努斯曾在达拉然研习魔法，与比索·埃斯沙德和图勒·鸦爪同为肯瑞托成员。亡灵瘟疫席卷洛丹伦时，冈瑟尔死去，随后又作为亡灵复生。后来，他摆脱了天灾军团对他心智的控制。冈瑟尔以为只有自己重获自由，又认定巫妖王的爪牙正在追捕他，因此对外来者充满敌意。法术书被找回后，比索在书页上施加了奥术附魔。这道魔法带有比索独有的印记，能让冈瑟尔认出老友的气息，知道还有另一位法师保有自己的意志。"}},faq={{q="这是谁的法术书？",a="法术书的主人是冈瑟尔·阿坎努斯，他住在提瑞斯法林地澈水湖中的一座孤岛上。",al={"书的主人是谁","冈瑟尔的书的主人","法术书的主人"}},{q="比索为什么要给法术书附魔？",a="比索在书上施加了带有自身印记的法术，以证明自己仍在洛丹伦存活，并且摆脱了巫妖王的控制。他希望冈瑟尔能相信他，并与被遗忘者结盟。",al={"为什么给书附魔","比索在书上施加的法术","书上的魔法"}},{q="为什么归还法术书时，冈瑟尔会心生疑虑？",a="冈瑟尔认为，任何接近他隐居之地的人，都可能是天灾军团派来再次奴役他的爪牙。起初，他以为你只是偷走他法术书的窃贼。",al={"冈瑟尔为什么发怒","冈瑟尔愤怒","冈瑟尔的敌意"}},{q="冈瑟尔和比索是怎么认识的？",a="在瘟疫夺去他们的生命之前，冈瑟尔、比索·埃斯沙德和图勒·鸦爪曾是朋友，也都是肯瑞托的学徒，一起在达拉然研习魔法。",al={"比索和冈瑟尔的过去","肯瑞托的联系","达拉然的朋友"}}},fp="19,150,22.608.1,24.107.1,37.179.0,52.162.0,43.144.1"}
